function clubDisplayName(name){
  if(typeof name === 'object' && name !== null){
    return name.name || name.club || '';
  }
  return String(name || '');
}

function clubBadge(name, size=32){
  const realName = (typeof name === 'object' && name !== null ? (name.name || name.club || '') : String(name || '')).trim();
  const nKey = typeof norm === 'function' ? norm(realName) : realName.toLowerCase();
  if(typeof state !== 'undefined' && state && state.customClub && (nKey === norm(state.club) || nKey === norm(state.customClub.name))){
    if(state.customClub.badgeImage){
      return `<img src="${state.customClub.badgeImage}" class="crest crest-img custom-badge-img" style="width:${size}px;height:${size}px;object-fit:contain;border-radius:4px;vertical-align:middle;flex-shrink:0" alt="${esc(realName)}">`;
    }
    if(state.customClub.badgeSvg){
      const svg = state.customClub.badgeSvg;
      if(typeof svg === 'string' && (svg.startsWith('data:') || svg.startsWith('http') || (!svg.includes('<svg') && !svg.includes('</svg>')))){
        return `<img src="${svg}" class="crest crest-img custom-badge-img" style="width:${size}px;height:${size}px;object-fit:contain;border-radius:4px;vertical-align:middle;flex-shrink:0" alt="${esc(realName)}">`;
      }
      return `<div class="crest custom-badge-svg" style="width:${size}px;height:${size}px;display:inline-flex;align-items:center;justify-content:center;overflow:hidden">${svg.replace(/width="[^"]*"/, `width="${size}"`).replace(/height="[^"]*"/, `height="${size}"`)}</div>`;
    }
  }
  if(typeof window !== 'undefined' && window.CUSTOM_CLUB_BADGES && window.CUSTOM_CLUB_BADGES[nKey]){
    const badge = window.CUSTOM_CLUB_BADGES[nKey];
    if(typeof badge === 'string' && (badge.startsWith('data:') || badge.startsWith('http') || badge.endsWith('.png') || badge.endsWith('.jpg') || badge.endsWith('.webp') || (!badge.includes('<svg') && !badge.includes('</svg>')))){
      return `<img src="${badge}" class="crest crest-img custom-badge-img" style="width:${size}px;height:${size}px;object-fit:contain;border-radius:4px;vertical-align:middle;flex-shrink:0" alt="${esc(realName)}">`;
    }
    if(typeof badge === 'string'){
      return `<div class="crest custom-badge-svg" style="width:${size}px;height:${size}px;display:inline-flex;align-items:center;justify-content:center;overflow:hidden">${badge.replace(/width="[^"]*"/, `width="${size}"`).replace(/height="[^"]*"/, `height="${size}"`)}</div>`;
    }
  }
  if(typeof window.renderClubBadge === 'function'){
    return window.renderClubBadge(realName, size);
  }
  const inits = initials(realName);
  return `<div class="crest" style="width:${size}px;height:${size}px;font-size:${Math.round(size*.4)}px">${esc(inits)}</div>`;
}



// ==============================================================================
// SISTEMA OFICIAL DE FOTOS DE JOGADORES & CARDS FUT (AFM 2027)
// ==============================================================================

function isGoalkeeperPosition(pos) {
  return ['gk', 'gol', 'goalkeeper', 'goleiro', 'por', 'guarda redes'].includes(typeof norm === 'function' ? norm(pos) : String(pos || '').trim().toLowerCase());
}

function trustedPlayerPhotoUrl(rawPhoto){
  if(typeof rawPhoto !== 'string' || !rawPhoto.trim()) return null;
  const photo = /^(?:https?:|data:|blob:|\/)/i.test(rawPhoto) ? rawPhoto.trim() : (rawPhoto.startsWith('img/') ? rawPhoto : `img/${rawPhoto.replace(/^\.?\//, '')}`);
  const localPath = photo.replace(/^\.\//, '');
  const isUnverifiedMappedPhoto = window.PLAYER_PHOTO_MAPPED_PATHS?.has(localPath) && !window.PLAYER_PHOTO_VERIFIED?.has(localPath);
  return isUnverifiedMappedPhoto || window.PLAYER_PHOTO_DUPLICATES?.has(localPath) ? null : photo;
}

function resolvePlayerPhotoUrl(p) {
  if (!p) return null;
  const name = typeof p === 'string' ? p : (p.name || '');
  if (!name) return null;

  // Regens s?o atletas novos: n?o reutilizar fotos, IDs ou mapas de rostos do veterano.
  if (typeof p === 'object' && (p.isGeneticRegen || p.regenOf || p.geneticOrigin || String(p.id || '').startsWith('regen_'))) {
    return null;
  }

  // 1. Verificar se o atleta já possui foto explícita
  if (typeof p === 'object' && p.photo && typeof p.photo === 'string') {
    const trusted = trustedPlayerPhotoUrl(p.photo);
    if (trusted) return trusted;
  }

  // 2. Verificar se o atleta possui ID do Transfermarkt (tmId) com arquivo local verificado
  if (typeof p === 'object' && p.tmId) {
    const tmPath = `img/players/tm_${p.tmId}.jpg`;
    if (!window.PLAYER_PHOTO_DUPLICATES?.has(tmPath)) {
      const trusted = trustedPlayerPhotoUrl(tmPath);
      if (trusted) return trusted;
    }
  }

  // 3. Resolução contextual de clube para HOMÔNIMOS (jogadores de mesmo nome em clubes diferentes)
  const club = typeof p === 'object' ? (p.club || (typeof state !== 'undefined' ? state?.club : '')) : '';
  const photos = window.PLAYER_PHOTOS || {};
  const normName = typeof norm === 'function' ? norm(name) : name.toLowerCase();
  const slugName = typeof normSlug === 'function' ? normSlug(name) : name.toLowerCase().replace(/[^a-z0-9]/g, '_');

  if (club) {
    const clubNorm = typeof norm === 'function' ? norm(club) : club.toLowerCase();
    const clubMatch = photos[`${club}::${name}`] || photos[`${clubNorm}::${normName}`] || photos[`${club}::${normName}`] || photos[`${club}::${slugName}`];
    if (clubMatch) {
      const trusted = trustedPlayerPhotoUrl(clubMatch);
      if (trusted) return trusted;
    }
  }

  // 4. Módulo AFM_RealPlayerFaces (com verificação de clube se disponível)
  if (typeof window !== 'undefined' && window.AFM_RealPlayerFaces && typeof window.AFM_RealPlayerFaces.resolveRealPlayerPhotoUrl === 'function') {
    const realPhoto = window.AFM_RealPlayerFaces.resolveRealPlayerPhotoUrl(p);
    if (realPhoto) {
      const trusted = trustedPlayerPhotoUrl(realPhoto);
      if (trusted) return trusted;
    }
  }

  // 5. SEGURANÇA MÁXIMA ANTI-HOMÔNIMOS:
  // Se o atleta pertencer à lista de nomes homônimos entre clubes distintos,
  // NUNCA fazer fallback para uma chave global solta de outro clube!
  if (window.AMBIGUOUS_PLAYER_NAMES && (window.AMBIGUOUS_PLAYER_NAMES.has(normName) || window.AMBIGUOUS_PLAYER_NAMES.has(name.toLowerCase()))) {
    return null;
  }

  // 6. Verificar no mapeamento global window.PLAYER_PHOTOS (exato, norm, lowercase, slug) apenas para nomes não ambíguos
  let match = photos[name] || photos[normName] || photos[name.toLowerCase()] || photos[slugName];
  if (!match) {
    const normalizedKey = Object.keys(photos).find(key => !key.includes('::') && (norm(key) === normName || normSlug(key) === slugName));
    if (normalizedKey) match = photos[normalizedKey];
  }
  return match ? trustedPlayerPhotoUrl(match) : null;
}

function resolvePlayerPhotoCandidates(p) {
  const primary = resolvePlayerPhotoUrl(p);
  return primary ? [primary] : [];
}

function playerPhoto(p, size = 36) {
  const name = typeof p === 'string' ? p : (p?.name || 'Jogador');
  const pos = typeof p === 'object' ? (p?.pos || 'CM') : 'CM';
  const photoUrl = typeof resolvePlayerPhotoUrl === 'function' ? resolvePlayerPhotoUrl(p) : null;

  if (photoUrl) {
    const fallbackSvg = renderPlayerAvatarFallback(name, pos, size);
    return `<div class="player-photo-container" style="width:${size}px;height:${size}px;border-radius:50%;overflow:hidden;position:relative;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;vertical-align:middle;box-shadow:0 2px 6px rgba(0,0,0,0.3)">
      <img src="${esc(photoUrl)}" alt="${esc(name)}" style="width:100%;height:100%;object-fit:cover;display:block" onerror="this.style.display='none';if(this.nextElementSibling)this.nextElementSibling.style.display='inline-flex';" />
      <div style="display:none;width:100%;height:100%">${fallbackSvg}</div>
    </div>`;
  }

  return renderPlayerAvatarFallback(name, pos, size);
}

function renderPlayerAvatarFallback(name, pos = 'CM', size = 36) {
  const posUpper = String(pos || 'CM').toUpperCase();
  const posColorMap = {
    GK: '#f59e0b',
    CB: '#3b82f6', LB: '#38bdf8', RB: '#38bdf8',
    DM: '#10b981', CM: '#22c55e', AM: '#a855f7',
    LM: '#06b6d4', RM: '#06b6d4',
    LW: '#ec4899', RW: '#ec4899', CF: '#ef4444', ST: '#f43f5e'
  };
  const color = posColorMap[posUpper] || '#94a3b8';
  const iconSize = Math.round(size * 0.68);
  return `<div class="player-avatar" style="width:${size}px;height:${size}px;border-radius:50%;background:radial-gradient(circle at 35% 30%, #1e293b, #090d16);border:1.5px solid rgba(148,163,184,0.35);box-shadow:0 2px 6px rgba(0,0,0,0.45);display:inline-flex;align-items:center;justify-content:center;position:relative;flex-shrink:0;vertical-align:middle" title="${esc(name || '')}">
    <svg width="${iconSize}" height="${iconSize}" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style="opacity:0.95">
      <path d="M12 12C14.21 12 16 10.21 16 8C16 5.79 14.21 4 12 4C9.79 4 8 5.79 8 8C8 10.21 9.79 12 12 12ZM12 14C9.33 14 4 15.34 4 18V20H20V18C20 15.34 14.67 14 12 14Z" fill="${color}"/>
    </svg>
    ${size >= 30 ? `<span style="position:absolute;bottom:-2px;right:-2px;background:#0f172a;border:1px solid rgba(255,255,255,0.25);color:${color};font-size:${Math.max(7, Math.round(size * 0.22))}px;font-weight:900;padding:1px 3px;border-radius:4px;line-height:1">${esc(posUpper.slice(0, 2))}</span>` : ''}
  </div>`;
}

function renderFifaCardFallbackSvg() {
  return `<img src="img/players/default_avatar.svg" alt="Jogador" class="fifa-mini-card-photo" style="opacity:0.85;" />`;
}

function renderTacticalCard(player, index, isSelected = false) {
  if (!player) return '';
  const photoUrl = resolvePlayerPhotoUrl(player) || "img/players/default_avatar.svg";
  const fallbackUrl = "img/players/default_avatar.svg";
  const ovr = player.overall || player.ovr || (typeof playerOverall === 'function' ? playerOverall(player) : 60);
  const ovrNum = Number(ovr) || 0;
  const isLegendary = ovrNum >= 90;
  const isSpecial = ovrNum >= 84 && ovrNum < 90;
  const isGoldRare = ovrNum >= 78 && ovrNum < 84;
  const isGold = ovrNum >= 70 && ovrNum < 78;
  const isSilver = ovrNum >= 60 && ovrNum < 70;
  const tierClass = isLegendary ? 'tier-legendary' : (isSpecial ? 'tier-special' : (isGoldRare ? 'tier-gold-rare' : (isGold ? 'tier-gold' : (isSilver ? 'tier-silver' : 'tier-bronze'))));
  const pos = player.pos || 'CM';
  const name = (player.name || 'Jogador').toUpperCase();

  return `
    <div class="fifa-mini-card ${tierClass} ${isSelected ? 'selected-glow selected' : ''}"
         data-player-id="${player.id || index}"
         data-index="${index}"
         data-player-key="${esc(playerKey(player))}">
      <div class="card-header fifa-mini-card-top">
        <div class="fifa-mini-card-badge">
          <span class="card-ovr fifa-mini-card-ovr">${ovr}</span>
          <span class="card-pos fifa-mini-card-pos">${esc(pos)}</span>
        </div>
      </div>
      <div class="card-photo-wrapper fifa-mini-card-photo-wrap">
        <img class="card-player-img fifa-mini-card-photo"
             src="${photoUrl}"
             alt="${esc(name)}"
             loading="lazy"
             onerror="this.onerror=null;this.src='${fallbackUrl}';" />
      </div>
      <div class="card-footer fifa-mini-card-bottom">
        <span class="card-player-name fifa-mini-card-name">${esc(name)}</span>
      </div>
    </div>
  `;
}
window.renderTacticalCard = renderTacticalCard;

function splitPlayerCardName(fullName) {
  if (!fullName) return { first: '', last: 'VAZIO', isSingle: true };
  const raw = String(fullName).trim();
  if (!raw) return { first: '', last: 'VAZIO', isSingle: true };
  const parts = raw.split(/\s+/);
  if (parts.length === 1) {
    return { first: '', last: parts[0].toUpperCase(), isSingle: true };
  }
  if (parts.length === 2) {
    return { first: parts[0].toUpperCase(), last: parts[1].toUpperCase(), isSingle: false };
  }
  const connectors = new Set(['DE', 'DA', 'DO', 'DOS', 'DAS', 'E']);
  if (parts.length === 3 && connectors.has(parts[1].toUpperCase())) {
    return { first: parts[0].toUpperCase(), last: (parts[1] + ' ' + parts[2]).toUpperCase(), isSingle: false };
  }
  const first = parts[0].toUpperCase();
  let last = parts[parts.length - 1].toUpperCase();
  if (parts.length > 2 && connectors.has(parts[parts.length - 2].toUpperCase())) {
    last = (parts[parts.length - 2] + ' ' + parts[parts.length - 1]).toUpperCase();
  }
  return { first, last, isSingle: false };
}
window.splitPlayerCardName = splitPlayerCardName;

function renderFifaMiniCard(p, slot = {}, opts = {}) {
  const i = slot.index ?? 0;
  const role = slot.role || (p?.pos || 'ST');
  const x = slot.x ?? 50;
  const y = slot.y ?? 50;
  const pk = p ? (p.key || (typeof playerKey === 'function' ? playerKey(p) : (p.id || p.name))) : '';
  const baseOvr = p ? (typeof playerOverall === 'function' ? playerOverall(p) : (p.overall || 60)) : 60;
  const effectiveOvr = p ? (typeof getPlayerEffectiveOverall === 'function' ? getPlayerEffectiveOverall(p, role) : baseOvr) : '-';
  const ovr = p ? effectiveOvr : '-';
  const pos = p ? (p.pos || role) : role;
  const fit = p ? (typeof getPositionFit === 'function' ? getPositionFit(p.pos, role) : (p.pos === role ? 'IDEAL' : 'ADAPTADA')) : 'IDEAL';
  const isAdapted = p && fit === 'ADAPTADA';
  const isIncompatible = p && fit === 'INCOMPATÍVEL';
  const ovrDiff = p ? (effectiveOvr - baseOvr) : 0;
  const isSelected = !!opts.isSelected;
  const isHalftime = !!opts.isHalftime;
  const stamina = p ? Math.round(p.stamina ?? p.fitness ?? 100) : 100;
  const staminaClass = stamina >= 75 ? 'stamina-good' : stamina >= 50 ? 'stamina-warn' : 'stamina-tired';
  const cardNameData = p ? splitPlayerCardName(p.name) : { first: '', last: 'VAZIO', isSingle: true };
  const firstLen = cardNameData.first.length;
  const lastLen = cardNameData.last.length;
  const firstLenClass = firstLen > 8 ? 'len-huge' : (firstLen > 6 ? 'len-long' : '');
  const lastLenClass = lastLen > 8 ? 'len-huge' : (lastLen > 6 ? 'len-long' : '');
  const photoUrl = p ? resolvePlayerPhotoUrl(p) : null;
  const fallbackUrl = "img/players/default_avatar.svg";
  const clubName = p?.club || state?.club || '';

  const ovrNum = Number(ovr) || 0;
  const isLegendary = ovrNum >= 90;
  const isSpecial = ovrNum >= 84 && ovrNum < 90;
  const isGoldRare = ovrNum >= 78 && ovrNum < 84;
  const isGold = ovrNum >= 70 && ovrNum < 78;
  const isSilver = ovrNum >= 60 && ovrNum < 70;
  const tierClass = isLegendary ? 'tier-legendary' : (isSpecial ? 'tier-special' : (isGoldRare ? 'tier-gold-rare' : (isGold ? 'tier-gold' : (isSilver ? 'tier-silver' : 'tier-bronze'))));
  const customClass = opts.customClass || '';
  const ovrColor = isIncompatible ? 'color:#f87171;' : (isAdapted ? 'color:#fde047;' : (ovrDiff < 0 ? 'color:#fca5a5;' : ''));

  const savedRole = opts.roleDef || (pk && state?.tactics?.playerRoles?.[pk]?.roleId) || (p?.name && state?.tactics?.playerRoles?.[p.name]?.roleId);
  const curRoleDef = getPlayerRoleDef(role, savedRole);

  return `
    <div class="fifa-mini-card ${tierClass} ${isSelected ? 'selected selected-glow' : ''} ${isAdapted ? 'slot-adapted' : ''} ${isIncompatible ? 'slot-incompatible' : ''} ${customClass}"
         style="left:${x}%;top:${y}%;"
         data-slot-index="${i}"
         data-slot-role="${esc(role)}"
         data-player-key="${esc(pk)}"
         data-starterkey="${esc(pk)}"
         title="${p ? `${esc(p.name)} (${esc(pos)}) • OVR ${ovr} • Função: ${esc(curRoleDef?.name || role)} (${esc(curRoleDef?.focus || 'Balanced')})${ovrDiff < 0 ? ` (${ovrDiff} fora de posição: ${fit})` : ''}` : 'Slot Vazio'}">

      <!-- Topo: OVR, POS e Escudo -->
      <div class="fifa-mini-card-top">
        <div class="fifa-mini-card-badge">
          <div style="display:inline-flex;align-items:center;gap:2px;">
            <span class="fifa-mini-card-ovr" style="${ovrColor}">${ovr}</span>
            ${isLegendary ? '<span class="fifa-mini-card-tier-icon legendary" title="Craque Festival (OVR 90+)" style="font-size:9px;line-height:1;">👑</span>' : (isSpecial ? '<span class="fifa-mini-card-tier-icon special" title="Craque TOTW In-Form (OVR 84+)" style="font-size:9px;line-height:1;">⭐</span>' : '')}
          </div>
          <span class="fifa-mini-card-pos">${esc(pos)}</span>
          ${p?.number ? `<span class="fifa-mini-card-num" style="font-size:8px;font-weight:900;color:#38bdf8;background:rgba(15,23,42,0.85);padding:1px 3px;border-radius:3px;margin-top:1px;line-height:1" title="Camisa #${p.number}">#${p.number}</span>` : ''}
          ${isAdapted ? `<span class="fifa-mini-card-role-adapted" style="color:#fde047;background:rgba(113,63,18,0.9);border:1px solid #eab308" title="Posição adaptada: ${esc(role)}${ovrDiff < 0 ? ` (${ovrDiff} OVR)` : ''}">(${esc(role)})</span>` : ''}
          ${isIncompatible ? `<span class="fifa-mini-card-role-incompatible" style="color:#f87171;background:rgba(127,29,29,0.9);border:1px solid #ef4444;font-size:7px;font-weight:900;padding:1px 2px;border-radius:3px;margin-top:1px;line-height:1" title="Posição incompatível: ${esc(role)}${ovrDiff < 0 ? ` (${ovrDiff} OVR)` : ''}">(${esc(role)})</span>` : ''}
        </div>
        <div class="fifa-mini-card-crest">
          ${typeof clubBadge === 'function' ? clubBadge(clubName, 15) : ''}
        </div>
      </div>

      <!-- Centro: Foto Oficial Recortada ou Fallback SVG Seguro -->
      <div class="fifa-mini-card-photo-wrap">
        <img src="${photoUrl || fallbackUrl}"
             alt="${esc(p?.name || 'Jogador')}"
             class="fifa-mini-card-photo"
             loading="lazy"
             onerror="this.onerror=null;this.src='${fallbackUrl}';" />
      </div>

      <!-- Base: Nome do Atleta (2 Camadas: Nome e Sobrenome) e Barra de Stamina -->
      <div class="fifa-mini-card-bottom">
        <div class="fifa-mini-card-name ${cardNameData.isSingle ? 'is-single-name' : 'is-double-name'}">
          ${cardNameData.first ? `<span class="fifa-name-layer-first ${firstLenClass}">${esc(cardNameData.first)}</span>` : ''}
          <span class="fifa-name-layer-last ${lastLenClass}">${esc(cardNameData.last)}</span>
        </div>
        ${isHalftime ? `
          <div class="fifa-mini-card-stamina" title="Energia: ${stamina}%">
            <div class="fifa-mini-card-stamina-fill ${staminaClass}" style="width:${stamina}%"></div>
          </div>
        ` : ''}
      </div>

      <!-- Ícones de Lesão e Suspensão -->
      ${p?.injury ? '<span class="fifa-mini-card-status" title="Lesionado">🚑</span>' : ''}
      ${p?.suspended > 0 ? '<span class="fifa-mini-card-status" title="Suspenso">🟥</span>' : ''}
    </div>
  `;
}

