function getAuditClubsList(filter){
  const tMap = window.COMPETITION_TEAMS || {};
  const comps = (filter === 'all' || !filter)
    ? Object.keys(tMap)
    : [filter];
  const list = [];
  comps.forEach(cId => {
    const teams = tMap[cId] || [];
    const compObj = (window.COMPETITIONS || []).find(c => c.id === cId) || { name: cId };
    teams.forEach(tName => {
      list.push({
        name: tName,
        compId: cId,
        compName: compObj.name
      });
    });
  });
  return list;
}

