function getClubCountry(clubName, stateContext = (typeof state !== 'undefined' ? state : null)){
  const cName = String(clubName || stateContext?.club || '').trim();
  const nClub = typeof norm === 'function' ? norm(cName) : cName.toLowerCase();

  // 1. Se estivermos olhando o clube do state e tiver compId
  const cId = stateContext?.compId || '';
  if(cId.startsWith('bra-') || cId.startsWith('sp-') || cId.startsWith('rj-') || cId.startsWith('mg-') || cId.startsWith('rs-')) return 'Brasil';
  if(cId === 'usa-1') return 'Estados Unidos';
  if(cId === 'arg-1') return 'Argentina';
  if(cId === 'eng-1' || cId === 'eng-2') return 'Inglaterra';
  if(cId === 'esp-1' || cId === 'esp-2') return 'Espanha';
  if(cId === 'ita-1') return 'Itália';
  if(cId === 'ger-1') return 'Alemanha';
  if(cId === 'fra-1') return 'França';
  if(cId === 'por-1') return 'Portugal';
  if(cId === 'ksa-1') return 'Arábia Saudita';

  // 2. Busca nas competições cadastradas em COMPETITION_TEAMS
  if(typeof COMPETITION_TEAMS !== 'undefined' && COMPETITION_TEAMS){
    for(const [compKey, teamArr] of Object.entries(COMPETITION_TEAMS)){
      if(Array.isArray(teamArr) && teamArr.some(t => (typeof norm === 'function' ? norm(t) : String(t).toLowerCase()) === nClub)){
        if(compKey.startsWith('bra-')) return 'Brasil';
        if(compKey === 'usa-1') return 'Estados Unidos';
        if(compKey === 'arg-1') return 'Argentina';
        if(compKey === 'eng-1' || compKey === 'eng-2') return 'Inglaterra';
        if(compKey === 'esp-1' || compKey === 'esp-2') return 'Espanha';
        if(compKey === 'ita-1') return 'Itália';
        if(compKey === 'ger-1') return 'Alemanha';
        if(compKey === 'fra-1') return 'França';
        if(compKey === 'por-1') return 'Portugal';
        if(compKey === 'ksa-1') return 'Arábia Saudita';
      }
    }
  }

  // 3. Heurísticas diretas de nomes de clubes consagrados
  if(/inter miami|la galaxy|los angeles galaxy|los angeles fc|lafc|columbus crew|seattle sounders|atlanta united|new york red bulls|nycfc|philadelphia union|orlando city|portland timbers|nashville/i.test(cName)) return 'Estados Unidos';
  if(/boca juniors|river plate|racing club|san lorenzo|independiente|velez|estudiantes|talleres|rosario central|newell/i.test(cName)) return 'Argentina';
  if(/al-hilal|al-nassr|al-ittihad|al-ahli|al-ettifaq|al-shabab/i.test(cName)) return 'Arábia Saudita';
  if(/real madrid|barcelona|atlético de madrid|sevilla|valencia|villarreal|athletic club|betis/i.test(cName)) return 'Espanha';
  if(/manchester city|liverpool|arsenal|manchester united|chelsea|tottenham|aston villa|newcastle/i.test(cName)) return 'Inglaterra';
  if(/inter de milão|juventus|milan|napoli|roma|lazio|atalanta|fiorentina/i.test(cName)) return 'Itália';
  if(/bayern|dortmund|leverkusen|leipzig|stuttgart|frankfurt/i.test(cName)) return 'Alemanha';
  if(/paris saint-germain|psg|marseille|monaco|lyon|lille/i.test(cName)) return 'França';
  if(/benfica|porto|sporting|braga/i.test(cName)) return 'Portugal';

  // 4. Se o usuário estiver numa liga nacional brasileira ou estadual
  if(typeof state !== 'undefined' && state && typeof curComp === 'function'){
    const c = curComp();
    if(c?.country) return c.country;
  }

  return 'Brasil';
}
if(typeof window !== 'undefined') {
  window.SPONSOR_POOLS_BY_COUNTRY = SPONSOR_POOLS_BY_COUNTRY;
  window.getClubCountry = getClubCountry;
}

function generateSponsorOffers(clubBudget, clubName = (typeof state !== 'undefined' ? state?.club : ''), squadRef = null, stateRef = (typeof state !== 'undefined' ? state : null)){
  const st = stateRef || (typeof state !== 'undefined' ? state : null);
  const targetClub = clubName || st?.club || '';
  const fame = typeof teamFameScore === 'function' ? teamFameScore() : 50;
  const mktMult = typeof marketingBenefits === 'function' ? marketingBenefits().sponsorMultiplier : 1;
  const fameMult = 0.60 + (fame / 100) * 0.90;
  const seasonFactor = Math.max(0.1, Number(st?.sponsorSeasonFactor ?? state?.sponsorSeasonFactor) || 1);
  const legacyBase = Math.round(Math.max(40000, Math.round((clubBudget || 2000000) * 0.024)) * mktMult * fameMult * seasonFactor);

  // Determina o elenco de referência para calcular a folha salarial mensal
  let squad = squadRef;
  if(!squad && st?.squad && Array.isArray(st.squad) && (!targetClub || norm(st.club) === norm(targetClub))){
    squad = st.squad;
  }
  if(!squad && typeof state !== 'undefined' && state?.squad && Array.isArray(state.squad) && (!targetClub || norm(state.club) === norm(targetClub))){
    squad = state.squad;
  }
  if(!squad && targetClub && typeof playersForClub === 'function'){
    try {
      squad = playersForClub(targetClub, st?.worldGenerated || (typeof buildWorldGenerated === 'function' ? buildWorldGenerated() : []));
    } catch(e){}
  }

  // Se o save for v2+ (ou nova carreira), calcula a folha real e assegura que os 3 patrocinadores somados cubram a folha
  let payrollBaseMonthly = 0;
  if(Array.isArray(squad) && squad.length > 0){
    const monthlyPayroll = squad.reduce((sum, p) => sum + (Number(p.wage) || playerSalary(p, st) || 0), 0);
    if(monthlyPayroll > 0){
      // Como Master (~1.55x) + Mangas (~0.70x) + Costas (~0.68x) somam ~2.93x do baseMonthly,
      // com divisor 2.50 qualquer combinação de 3 patrocinadores (mínimo de soma de mults = 2.55)
      // cobre pelo menos 102% a 125% da folha salarial mensal do elenco, garantindo saúde financeira ao clube.
      payrollBaseMonthly = Math.round((monthlyPayroll / 2.50) * (0.96 + (fame / 100) * 0.16) * mktMult * seasonFactor);
    }
  }

  const isV2 = Boolean((st && st.salaryModelVersion >= 2) || (squadRef && (!st || st.salaryModelVersion >= 2)));
  const baseMonthly = isV2 && payrollBaseMonthly > 0 ? Math.max(legacyBase, payrollBaseMonthly, 50000) : legacyBase;

  const country = getClubCountry(targetClub, st);
  const countryPool = SPONSOR_POOLS_BY_COUNTRY[country] || SPONSOR_POOLS_BY_COUNTRY['Brasil'];
  const globalPool = SPONSOR_POOLS_BY_COUNTRY['Global'] || [];

  // Mescla o pool do país local com os globais
  const sponsorPool = [...countryPool, ...globalPool];

  // Filtra marcas elegíveis para a fama atual do time
  const eligible = sponsorPool.filter(s => fame >= (s.minFame - 10));
  const activePool = eligible.length >= 4 ? eligible : sponsorPool;

  const mList = activePool.filter(s => s.category === 'Master').sort(() => Math.random() - 0.5);
  const sList = activePool.filter(s => s.category === 'Mangas').sort(() => Math.random() - 0.5);
  const bList = activePool.filter(s => s.category === 'Costas').sort(() => Math.random() - 0.5);

  const selected = [
    mList[0] || countryPool.find(s => s.category === 'Master'),
    sList[0] || countryPool.find(s => s.category === 'Mangas'),
    bList[0] || countryPool.find(s => s.category === 'Costas'),
    mList[1] || sList[1] || bList[1] || countryPool[1]
  ].filter(Boolean);

  return selected.map(s => ({
    brand: s.brand,
    category: s.category,
    color: s.color,
    monthly: Math.round(baseMonthly * s.mult),
    winBonus: Math.round(baseMonthly * s.winMult),
    years: s.years,
    desc: s.desc,
    country: country
  }));
}

const SPONSOR_CONTRACT_SLOTS = [
  ['master', 'Master'],
  ['sleeves', 'Mangas'],
  ['back', 'Costas']
];

function uniqueAvailableSponsorOffers(offers, sponsors){
  const activeBrands = new Set(SPONSOR_CONTRACT_SLOTS
    .map(([slot]) => norm(sponsors?.[slot]?.brand || sponsors?.[slot]?.name))
    .filter(Boolean));
  const listedBrands = new Set();
  return (Array.isArray(offers) ? offers : []).filter(offer => {
    const brandKey = norm(offer?.brand || offer?.name);
    if(!brandKey || activeBrands.has(brandKey) || listedBrands.has(brandKey)) return false;
    listedBrands.add(brandKey);
    return true;
  });
}

function activateSponsorContract(offer, season = state?.season || 2026){
  const years = Math.max(1, Math.floor(Number(offer?.contractYears) || Number(offer?.years) || 1));
  return {
    ...offer,
    years,
    contractYears: years,
    contractStartSeason: Number(season) || 2026,
    contractEndSeason: (Number(season) || 2026) + years - 1
  };
}

function expireSeasonSponsorContracts(s, season = s?.season){
  if(!s?.sponsors) return [];
  const expired = [];
  const seasonNumber = Number(season) || 2026;
  for(const [slot, category] of SPONSOR_CONTRACT_SLOTS){
    const sponsor = s.sponsors[slot];
    const hasEndSeason = sponsor?.contractEndSeason != null && sponsor.contractEndSeason !== '' && Number.isFinite(Number(sponsor.contractEndSeason));
    if(!sponsor || !hasEndSeason || Number(sponsor.contractEndSeason) >= seasonNumber) continue;
    expired.push({ ...sponsor, category, renewalFor: slot });
    s.sponsors[slot] = null;
  }
  if(!expired.length) return expired;

  s.sponsorOffers = Array.isArray(s.sponsorOffers) ? s.sponsorOffers : [];
  expired.forEach(offer => {
    const alreadyListed = s.sponsorOffers.some(item => item?.renewalFor === offer.renewalFor);
    if(!alreadyListed) s.sponsorOffers.unshift({ ...offer, renewal: true });
  });
  s.news = Array.isArray(s.news) ? s.news : [];
  expired.forEach(offer => s.news.unshift(`📄 FIM DE CONTRATO: o vínculo com ${offer.brand || offer.name || 'o patrocinador'} venceu. Renove ou escolha uma nova proposta no Escritório.`));
  s.news = s.news.slice(0, 50);
  return expired;
}

function ensureClubSponsors(s){
  if(!s) return;
  const hadSponsorState = s.sponsorLifecycleVersion === 1 || Object.values(s.sponsors || {}).some(Boolean);
  s.sponsors = s.sponsors || {};
  const baseBudget = s.balance || 5000000;
  const offers = generateSponsorOffers(baseBudget, s.club, s.squad, s);

  const mOff = offers.find(o => o.category === 'Master') || { brand: 'Patrocinador Master', category: 'Master', color: '#f35b04', monthly: 1850000, winBonus: 240000, years: 2, desc: 'Patrocinador Master Oficial' };
  const sOff = offers.find(o => o.category === 'Mangas') || { brand: 'Patrocínio Mangas', category: 'Mangas', color: '#10b981', monthly: 720000, winBonus: 95000, years: 2, desc: 'Mangas da Camisa' };
  const bOff = offers.find(o => o.category === 'Costas') || { brand: 'Patrocínio Costas', category: 'Costas', color: '#ea580c', monthly: 980000, winBonus: 130000, years: 3, desc: 'Costas / Omoplata' };

  if(!hadSponsorState){
    s.sponsors.master = activateSponsorContract(mOff, s.season);
    s.sponsors.sleeves = activateSponsorContract(sOff, s.season);
    s.sponsors.back = activateSponsorContract(bOff, s.season);
  }
  const legacyStartSeason = Math.max(2026, (Number(s.season) || 2026) - 1);
  for(const [slot] of SPONSOR_CONTRACT_SLOTS){
    const sponsor = s.sponsors[slot];
    if(!sponsor) continue;
    if((sponsor.brand || sponsor.name) === 'Sem Patrocínio' || (!sponsor.brand && !sponsor.name)){
      s.sponsors[slot] = null;
      continue;
    }
    if(!sponsor.brand && sponsor.name) sponsor.brand = sponsor.name;
    if(sponsor.winBonus == null && sponsor.bonus != null) sponsor.winBonus = Number(sponsor.bonus) || 0;
    if(sponsor.contractEndSeason == null || sponsor.contractEndSeason === '' || !Number.isFinite(Number(sponsor.contractEndSeason))){
      const years = Math.max(1, Math.floor(Number(sponsor.contractYears) || Number(sponsor.years) || 1));
      sponsor.contractStartSeason = legacyStartSeason;
      sponsor.contractEndSeason = legacyStartSeason + years - 1;
      sponsor.contractYears = years;
    }
  }
  s.sponsorLifecycleVersion = 1;
  expireSeasonSponsorContracts(s, s.season);
  if(!Array.isArray(s.sponsorOffers) || s.sponsorOffers.length === 0) s.sponsorOffers = offers;
  s.sponsorOffers = uniqueAvailableSponsorOffers(s.sponsorOffers, s.sponsors);
}
if(typeof window !== 'undefined'){
  window.generateSponsorOffers = generateSponsorOffers;
  window.ensureClubSponsors = ensureClubSponsors;
}



