function getStadiumMaintenanceData(){
  state.stadiumMaintenance = state.stadiumMaintenance ?? 90;
  state.stadiumPitchType = state.stadiumPitchType || 'natural'; // 'natural' | 'hybrid' | 'synthetic'

  let statusText = 'Excelente';
  let statusColor = '#22c55e';
  if(state.stadiumMaintenance >= 85){ statusText = 'Excelente (Impecável)'; statusColor = '#22c55e'; }
  else if(state.stadiumMaintenance >= 65){ statusText = 'Bom (Conservado)'; statusColor = '#38bdf8'; }
  else if(state.stadiumMaintenance >= 40){ statusText = 'Regular (Desgaste notável)'; statusColor = '#facc15'; }
  else if(state.stadiumMaintenance >= 20){ statusText = 'Ruim (Gramado esburacado)'; statusColor = '#f97316'; }
  else { statusText = 'Crítico (Risco de interdição!)'; statusColor = '#ef4444'; }

  return {
    val: state.stadiumMaintenance,
    statusText,
    statusColor,
    pitch: state.stadiumPitchType
  };
}

// Reparo e Manutenção
function repairStadium(mode){
  const cost = mode === 'quick' ? 25000 : 75000;
  if(state.balance < cost){
    toast('Saldo insuficiente para realizar a manutenção do estádio!');
    return;
  }
  state.balance -= cost;
  state.expense = (state.expense || 0) + cost;

  if(mode === 'quick'){
    state.stadiumMaintenance = Math.min(100, (state.stadiumMaintenance || 70) + 25);
    toast('🔧 Reparo rápido do gramado realizado com sucesso (+25% conservação)!');
  } else {
    state.stadiumMaintenance = 100;
    toast('🏛️ Reforma e manutenção geral da estrutura concluída (100% conservação)!');
  }
  save();
  openStadiumModal('maintenance');
}

// Troca / Evolução do Gramado
function installPitchType(type){
  const costs = { natural: 0, hybrid: 150000, synthetic: 220000 };
  const cost = costs[type] || 0;
  if(state.balance < cost){
    toast('Saldo insuficiente para instalar este tipo de gramado!');
    return;
  }
  state.balance -= cost;
  state.expense = (state.expense || 0) + cost;
  state.stadiumPitchType = type;
  toast(`🌱 Novo gramado (${type.toUpperCase()}) instalado no estádio!`);
  save();
  openStadiumModal('maintenance');
}

function clubStadiumName(targetClub){
  const st = (typeof state !== 'undefined' && state) ? state : (window && window.state ? window.state : null);
  const cName = targetClub || st?.club;
  const realStad = (typeof window !== 'undefined' && typeof window.getClubStadiumInfo === 'function')
    ? window.getClubStadiumInfo(cName)
    : (typeof getClubStadiumInfo === 'function' ? getClubStadiumInfo(cName) : null);
  const realName = realStad?.name || realStad?.stadium;

  if(targetClub && st?.club && typeof norm === 'function' && norm(targetClub) !== norm(st.club)){
    return realName || (typeof clubByName === 'function' && clubByName(targetClub)?.stadium) || `Estádio do ${targetClub}`;
  }

  if(st && (!targetClub || (typeof norm === 'function' && norm(targetClub) === norm(st.club)))){
    if(st.namingRights && st.namingRights.stadiumName){
      return st.namingRights.stadiumName;
    }
    const isRealBrasilia = typeof norm === 'function' && norm(cName) === norm('Real Brasília');
    const isArucOrSobradinho = typeof norm === 'function' && (norm(cName) === norm('ARUC') || norm(cName) === norm('Sobradinho'));
    const isCorrupted = (str) => {
      if(!str) return false;
      const s = String(str);
      if(s === 'Estádio do clube' || s === 'Arena Oficial' || s === 'Arena Municipal' || s === 'Estádio Municipal') return true;
      if(!isRealBrasilia && s.includes('Defelê')) return true;
      if(!isArucOrSobradinho && (s.includes('Augustinho') || s.includes('Pires de Lima'))) return true;
      return false;
    };

    if(st.stadiumCustomization?.name && !isCorrupted(st.stadiumCustomization.name)){
      return st.stadiumCustomization.name;
    }
    if(st.stadiumName && !isCorrupted(st.stadiumName)){
      return st.stadiumName;
    }
    if(st.stadium?.name && !isCorrupted(st.stadium.name)){
      return st.stadium.name;
    }
    if(st.infrastructure?.stadium?.name && !isCorrupted(st.infrastructure.stadium.name)){
      return st.infrastructure.stadium.name;
    }

    // Auto-cura caso estivesse contaminado por save antigo
    if(realName){
      if(st.stadiumName && isCorrupted(st.stadiumName)) st.stadiumName = realName;
      if(st.stadium && isCorrupted(st.stadium.name)) st.stadium.name = realName;
      if(st.stadiumCustomization && isCorrupted(st.stadiumCustomization.name)) st.stadiumCustomization.name = realName;
      if(st.infrastructure?.stadium && isCorrupted(st.infrastructure.stadium.name)) st.infrastructure.stadium.name = realName;
      return realName;
    }
  }

  const clubObj = typeof clubByName === 'function' ? clubByName(cName) : null;
  if(clubObj && clubObj.stadium && clubObj.stadium !== 'Estádio do clube') {
    return clubObj.stadium;
  }
  return realName || (cName ? `Estádio do ${cName}` : 'Estádio Municipal');
}

function getCaldeiraoData(){
  const f = userFixture();
  const opp = f && f[0] === state.club ? f[1] : (f ? f[0] : 'Adversário');
  const proj = attendanceProjection(opp);
  const cap = state.infrastructure?.stadium?.capacity || 3000;
  const occRate = Math.round(clamp((proj.attendance / cap) * 100, 0, 100));
  const fans = state.trust?.fans ?? 70;

  state.stadiumUpgrades = state.stadiumUpgrades || {
    chairs: false,
    mosaic: false,
    ledRing: false,
    flares: false,
    screen: false,
    ledLights: false
  };

  let structScore = 0;
  if(state.stadiumUpgrades.chairs) structScore += 6;
  if(state.stadiumUpgrades.mosaic) structScore += 13;
  if(state.stadiumUpgrades.ledRing) structScore += 6;
  if(state.stadiumUpgrades.flares) structScore += 25;
  if(state.stadiumUpgrades.screen) structScore += 6;
  if(state.stadiumUpgrades.ledLights) structScore += 6;

  // Percentual total do Caldeirão (de 0% a +25%)
  const caldeiraoPercent = Math.round((occRate * 0.35 + fans * 0.35 + structScore * 0.30) * 0.25);

  return {
    occRate,
    fans,
    structScore,
    caldeiraoPercent,
    upgrades: state.stadiumUpgrades
  };
}

