// =========================================================================
// SISTEMA DE AMPLIAÇÃO DO ESTÁDIO (ANEL POR ANEL ATÉ 100K)
// =========================================================================
let isBuildingStadiumSide = false;
function buildStadiumSide(side, mode = 'cash'){
  if(typeof state === 'undefined' || !state){
    if(typeof window !== 'undefined' && window.state) state = window.state;
  }
  if(isBuildingStadiumSide) return false;
  const stData = getStadiumExpansionData();
  if(stData.activeWork){ toast(`Obra do Anel ${stData.activeWork.ring} em andamento: faltam ${getStadiumWorkDaysRemaining(stData.activeWork)} dias.`); return false; }
  const curRing = Math.max(1, Math.min(stData.maxRings || 6, Number(stData.ring) || 1));
  if(curRing > stData.maxUnlockedRing){ toast('Evolua o estádio para liberar esse anel.'); return false; }
  if(curRing > 1 && !['norte', 'sul', 'leste', 'oeste'].every(s => stData.rings[curRing - 1]?.[s] === true)){
    stData.ring = curRing - 1;
    stData.sides = stData.rings[stData.ring];
    toast(`Conclua os quatro setores do Anel ${curRing - 1} antes de iniciar o Anel ${curRing}.`);
    return false;
  }
  stData.ring = curRing;
  stData.rings = stData.rings || {};
  stData.rings[curRing] = stData.rings[curRing] || { norte: false, sul: false, leste: false, oeste: false };

  const unbuiltSide = ['norte', 'sul', 'leste', 'oeste'].find(s => !stData.rings[curRing][s]);
  if(!unbuiltSide){
    toast(`Todos os 4 setores do Anel ${curRing} já foram concluídos! Avance para o próximo anel.`);
    return false;
  }

  const targetSide = side || stadiumSelectedSide || unbuiltSide;
  if(!['norte', 'sul', 'leste', 'oeste'].includes(targetSide)){
    toast('Selecione um setor válido do estádio.');
    return false;
  }

  // Validação: setor já construído no anel atual?
  if(stData.rings[curRing][targetSide]){
    toast(`O setor ${targetSide.toUpperCase()} já foi concluído no Anel ${curRing}!`);
    return false;
  }

  isBuildingStadiumSide = true;
  try {
    const cost = getStadiumSectorCost(curRing);
    const workDays = getStadiumSectorWorkDays(curRing);
    const monthlyRev = Math.max(100000, (state.lastHome?.revenue || 400000) * 2 + 150000); // Estimativa de receita mensal
    const maxAllowedInstallment = monthlyRev * 0.30;

    if(mode === 'cash'){
      if(state.balance < cost){
        toast('Saldo em caixa insuficiente para pagamento à vista!');
        return false;
      }
      state.balance -= cost;
      state.expense = (state.expense || 0) + cost;
      toast(`Obra iniciada no Setor ${targetSide.toUpperCase()} do Anel ${curRing}. Prazo estimado: ${workDays} dias.`);
    } else {
      const downPayment = cost * 0.20;
      if(state.balance < downPayment){
        toast(`Entrada de 20% (${fmtMoney(downPayment)}) insuficiente no caixa!`);
        return false;
      }
      const numMonths = mode === '6x' ? 6 : 12;
      const interest = mode === '6x' ? 1.06 : 1.12; // 1% ao mês
      const totalFinanced = (cost * 0.80) * interest;
      const monthlyInst = Math.round(totalFinanced / numMonths);

      if(monthlyInst > maxAllowedInstallment){
        toast(`Aviso do Conselho Fiscal: A parcela de ${fmtMoney(monthlyInst)} ultrapassa 30% da receita mensal do clube (${fmtMoney(maxAllowedInstallment)})!`);
        return false;
      }

      state.balance -= downPayment;
      state.expense = (state.expense || 0) + downPayment;
      stData.debt = stData.debt || { remaining: 0, monthly: 0, monthsLeft: 0 };
      stData.debt.remaining += totalFinanced;
      stData.debt.monthly += monthlyInst;
      stData.debt.monthsLeft = Math.max(stData.debt.monthsLeft, numMonths);

      toast(`Obra iniciada no Setor ${targetSide.toUpperCase()} do Anel ${curRing}! Entrada de ${fmtMoney(downPayment)} paga; prazo estimado: ${workDays} dias.`);
    }
    const finishDate = new Date(`${state.date}T12:00:00`);
    finishDate.setDate(finishDate.getDate() + workDays);
    stData.activeWork = { ring: curRing, side: targetSide, startedDate: state.date, durationDays: workDays, finishDate: finishDate.toISOString().slice(0, 10) };

    save();
    render();
    return true;
  } finally {
    isBuildingStadiumSide = false;
  }
}

function getStadiumWorkDaysRemaining(work = state?.stadiumRingData?.activeWork){
  if(!work || !state?.date) return 0;
  if(!work.finishDate){
    const legacyFinishDate = new Date(`${state.date}T12:00:00`);
    legacyFinishDate.setDate(legacyFinishDate.getDate() + Math.max(1, Number(work.roundsRemaining) || 1) * 7);
    work.finishDate = legacyFinishDate.toISOString().slice(0, 10);
  }
  const today = Date.parse(`${state.date}T00:00:00`);
  const finish = Date.parse(`${work.finishDate}T00:00:00`);
  return Number.isFinite(today) && Number.isFinite(finish) ? Math.max(0, Math.ceil((finish - today) / 86400000)) : 0;
}

function getStadiumContractorRushCost(work, days){
  const remaining = getStadiumWorkDaysRemaining(work);
  if(days === 'instant'){
    if(!work || remaining <= 0) return 0;
    return Math.max(250000, Math.round(getStadiumSectorCost(Number(work.ring) || 1) * 0.75));
  }
  const requestedDays = Math.max(0, Math.floor(Number(days) || 0));
  if(!work || requestedDays <= 0 || requestedDays >= remaining) return 0;
  const sectorCost = getStadiumSectorCost(Number(work.ring) || 1);
  // Taxas mais altas: equipe extra, turnos noturnos e entrega prioritária.
  const baseRushPct = requestedDays <= 3 ? 0.08 : requestedDays <= 7 ? 0.15 : 0.25;
  return Math.max(50000, Math.round(sectorCost * baseRushPct));
}

function hireStadiumContractor(days){
  if(typeof state === 'undefined' || !state){
    if(typeof window !== 'undefined' && window.state) state = window.state;
  }
  const work = state?.stadiumRingData?.activeWork;
  if(!work){
    if(typeof toast === 'function') toast('Não há uma obra ativa para acelerar.');
    return false;
  }
  const remaining = getStadiumWorkDaysRemaining(work);
  const instant = days === 'instant';
  const requestedDays = Math.floor(Number(days) || 0);
  if(!instant && (![3, 7, 14].includes(requestedDays) || requestedDays >= remaining || remaining <= 0)){
    if(typeof toast === 'function') toast('Selecione uma opção válida de aceleração para esta obra.');
    return false;
  }
  let cost = getStadiumContractorRushCost(work, instant ? 'instant' : requestedDays);
  if(instant && (!Number.isFinite(cost) || cost <= 0)){
    cost = Math.max(250000, Math.round(getStadiumSectorCost(Number(work.ring) || 1) * 0.75));
  }
  if(!Number.isFinite(cost) || cost <= 0){
    if(typeof toast === 'function') toast('Não foi possível calcular o custo da construtora.');
    return false;
  }
  if((Number(state.balance) || 0) < cost){
    if(typeof toast === 'function') toast(`Saldo insuficiente para contratar a construtora. Custo: ${fmtMoney(cost)}.`);
    return false;
  }
    // Não cobrar se a obra não tiver setor válido para concluir.
    if(!Number(work.ring) || !['norte','sul','leste','oeste'].includes(String(work.side || '').toLowerCase())){
      toast('A obra ativa tem um setor inválido e não pode ser concluída.');
      return false;
    }

  if(instant){
    const ringNum = Number(work.ring) || 1;
    const sideName = String(work.side || '').toLowerCase();
    state.balance = (Number(state.balance) || 0) - cost;
    state.expense = (Number(state.expense) || 0) + cost;
    work.contractorRushDays = (Number(work.contractorRushDays) || 0) + Math.max(1, remaining);
    work.contractorRushCost = (Number(work.contractorRushCost) || 0) + cost;
    work.finishDate = state.date;

    // Processa dia da obra
    processStadiumConstructionDay();

    // Garante que o setor seja registrado como concluído e activeWork seja limpo
    const st = getStadiumExpansionData();
    st.rings = st.rings || {};
    st.rings[ringNum] = st.rings[ringNum] || { norte: false, sul: false, leste: false, oeste: false };
    st.rings[ringNum][sideName] = true;
    st.purchasedSectors = Array.isArray(st.purchasedSectors) ? st.purchasedSectors : [];
    const secKey = `r${ringNum}_${sideName}`;
    if(!st.purchasedSectors.includes(secKey)){
      st.purchasedSectors.push(secKey);
      const curCap = Math.max(0, Number(state.infrastructure?.stadium?.capacity) || 8000);
      state.infrastructure.stadium.capacity = Math.min(100000, curCap + 3500);
      if(state.stadium) state.stadium.capacity = state.infrastructure.stadium.capacity;
      if(typeof syncStadiumCapacityAndLevel === 'function') syncStadiumCapacityAndLevel(state);
    }
    st.activeWork = null;
    if(state.stadiumRingData) state.stadiumRingData.activeWork = null;
    st.sides = st.rings[st.ring];

    // Próximo setor disponível selecionado automaticamente
    const nextUnbuiltSide = ['norte', 'sul', 'leste', 'oeste'].find(s => !st.rings[ringNum][s]);
    if(nextUnbuiltSide) {
      stadiumSelectedSide = nextUnbuiltSide;
      if(typeof window !== 'undefined') window.stadiumSelectedSide = nextUnbuiltSide;
    }

    state.news = Array.isArray(state.news) ? state.news : [];
    state.news.unshift(`🏗️ CONSTRUTORA EXPRESSA: O setor ${sideName.toUpperCase()} do Anel ${ringNum} foi concluído na hora por ${fmtMoney(cost)}.`);
    state.news = state.news.slice(0, 50);

    save();
    render();
    if(typeof toast === 'function') toast(`⚡ Obra concluída na hora! Taxa premium: ${fmtMoney(cost)}.`);
    openStadiumModal('expansion');
    return true;
  }

  const currentFinish = new Date(`${work.finishDate}T12:00:00`);
  if(!Number.isFinite(currentFinish.getTime())){ toast('A data de conclusão da obra está inválida.'); return false; }
  currentFinish.setDate(currentFinish.getDate() - requestedDays);
  const today = Date.parse(`${state.date}T00:00:00`);
  const newFinishDay = Date.parse(`${currentFinish.toISOString().slice(0, 10)}T00:00:00`);
  if(!Number.isFinite(today) || newFinishDay <= today){ toast('A aceleração não pode concluir a obra antes de um dia válido.'); return false; }

  state.balance = (Number(state.balance) || 0) - cost;
  state.expense = (Number(state.expense) || 0) + cost;
  work.finishDate = currentFinish.toISOString().slice(0, 10);
  work.contractorRushDays = (Number(work.contractorRushDays) || 0) + requestedDays;
  work.contractorRushCost = (Number(work.contractorRushCost) || 0) + cost;
  state.news = Array.isArray(state.news) ? state.news : [];
  state.news.unshift(`🏗️ CONSTRUTORA CONTRATADA: obra do setor ${String(work.side).toUpperCase()} do Anel ${work.ring} antecipada em ${requestedDays} dias por ${fmtMoney(cost)}.`);
  state.news = state.news.slice(0, 50);
  save();
  toast(`Construtora contratada! ${requestedDays} dias antecipados por ${fmtMoney(cost)}.`);
  openStadiumModal('expansion');
  return true;
}

function processStadiumConstructionDay(){
  if(typeof state === 'undefined' || !state){
    if(typeof window !== 'undefined' && window.state) state = window.state;
  }
  if(!state) return;
  const st = getStadiumExpansionData();
  if(!st.activeWork) return;
  if(getStadiumWorkDaysRemaining(st.activeWork) > 0) return;
  const completedWork = st.activeWork;
  const { ring, side } = completedWork;
  const wasPremiumBuild = Number(completedWork.contractorRushCost) > 0 && Number(completedWork.contractorRushDays) >= Number(completedWork.durationDays || 0);
  st.rings[ring][side] = true;
  st.purchasedSectors = Array.isArray(st.purchasedSectors) ? st.purchasedSectors : [];
  const key = `r${ring}_${side}`;

  // INVIOLABLE RULE: capacity increases exactly once for each newly completed, unique sector.
  const baseCapacity = Math.max(0, Number(state.infrastructure.stadium.capacity) || 8000);
  const isNewPurchasedSector = !st.purchasedSectors.includes(key);
  if(isNewPurchasedSector){
    st.purchasedSectors.push(key);
    state.infrastructure.stadium.capacity = Math.min(100000, baseCapacity + 3500);
  }
  if(state.stadium) state.stadium.capacity = state.infrastructure.stadium.capacity;
  if(typeof syncStadiumCapacityAndLevel === 'function') syncStadiumCapacityAndLevel(state);
  st.activeWork = null;
  st.sides = st.rings[st.ring];
  const nextSide = ['norte', 'sul', 'leste', 'oeste'].find(s => !st.rings[ring][s]);
  if(nextSide) stadiumSelectedSide = nextSide;
  else if(ring < st.maxUnlockedRing && ring < st.maxRings){
    st.ring = ring + 1;
    st.sides = st.rings[st.ring];
    stadiumSelectedSide = 'norte';
  }
  const completionMessage = `🏟️ OBRA CONCLUÍDA! O setor ${String(side).toUpperCase()} do Anel ${ring} está pronto. Capacidade atual: ${state.infrastructure.stadium.capacity.toLocaleString('pt-BR')} lugares.`;
  addNews(completionMessage);
  if(typeof toast === 'function') toast(completionMessage);
  if(wasPremiumBuild) addNews(`🏗️ CONSTRUTORA PREMIUM: serviço expresso concluído por ${fmtMoney(Number(completedWork.contractorRushCost) || 0)}.`);
  if(typeof save === 'function') save();
}

function getStadiumLevelByCapacity(cap){
  const c = Math.max(0, Number(cap) || 0);
  if(c >= 80000) return 6;
  if(c >= 60000) return 5;
  if(c >= 40000) return 4;
  if(c >= 25000) return 3;
  if(c >= 15000) return 2;
  return 1;
}
if(typeof window !== 'undefined') window.getStadiumLevelByCapacity = getStadiumLevelByCapacity;

/**
 * REGRA CRÍTICA INVIOLÁVEL: Sincronização bidirecional entre o volume da capacidade real
 * e o nível arquitetônico de infraestrutura do estádio no save.
 * Ex: 12.000 pessoas é estritamente Nível 1 (Raiz), nunca Nível 3 (Ferradura).
 */
function syncStadiumCapacityAndLevel(st = (typeof state !== 'undefined' ? state : (typeof window !== 'undefined' ? window.state : null))){
  if(!st) return;
  st.infrastructure = st.infrastructure || {};
  st.infrastructure.stadium = st.infrastructure.stadium || { level: 1, capacity: 5000 };
  
  let cap = Number(st.infrastructure.stadium.capacity || st.stadiumCapacity || 0);
  if(cap <= 0){
    const cName = st.club || '';
    const info = (typeof window !== 'undefined' && typeof window.getClubStadiumInfo === 'function') ? window.getClubStadiumInfo(cName) : null;
    cap = Number(info?.capacity || 5000);
  }
  
  st.infrastructure.stadium.capacity = cap;
  st.stadiumCapacity = cap;
  if(st.stadium) st.stadium.capacity = cap;

  const expectedLevel = (typeof getStadiumLevelByCapacity === 'function')
    ? getStadiumLevelByCapacity(cap)
    : (cap >= 80000 ? 6 : cap >= 60000 ? 5 : cap >= 40000 ? 4 : cap >= 25000 ? 3 : cap >= 15000 ? 2 : 1);

  // Regra crítica: estádios com menos de 15.000 pessoas são estritamente Nível 1 (Raiz)
  if(cap < 15000){
    st.infrastructure.stadium.level = 1;
  } else {
    st.infrastructure.stadium.level = Math.max(1, expectedLevel);
  }
  if(st.stadium) st.stadium.level = st.infrastructure.stadium.level;

  if(!st.stadiumRingData){
    st.stadiumRingData = {
      ring: st.infrastructure.stadium.level,
      maxRings: 6,
      maxUnlockedRing: st.infrastructure.stadium.level,
      sides: { norte: false, sul: false, leste: false, oeste: false },
      rings: {
        1: { norte: false, sul: false, leste: false, oeste: false },
        2: { norte: false, sul: false, leste: false, oeste: false },
        3: { norte: false, sul: false, leste: false, oeste: false },
        4: { norte: false, sul: false, leste: false, oeste: false },
        5: { norte: false, sul: false, leste: false, oeste: false },
        6: { norte: false, sul: false, leste: false, oeste: false }
      },
      purchasedSectors: [],
      activeWork: null
    };
  }

  st.stadiumRingData.maxUnlockedRing = st.infrastructure.stadium.level;
  st.stadiumRingData.ring = Math.min(st.stadiumRingData.maxUnlockedRing, Math.max(1, Number(st.stadiumRingData.ring) || 1));

  // Auto-cura de setores para saves antigos
  if(cap < 15000){
    st.stadiumRingData.rings = st.stadiumRingData.rings || {};
    st.stadiumRingData.rings[1] = st.stadiumRingData.rings[1] || {};
    st.stadiumRingData.rings[1].norte = (cap > 5000);
    st.stadiumRingData.rings[1].sul = (cap > 8500);
    st.stadiumRingData.rings[1].leste = false;
    st.stadiumRingData.rings[1].oeste = false;
    st.stadiumRingData.purchasedSectors = [];
    if(st.stadiumRingData.rings[1].norte) st.stadiumRingData.purchasedSectors.push('r1_norte');
    if(st.stadiumRingData.rings[1].sul) st.stadiumRingData.purchasedSectors.push('r1_sul');
    for(let r = 2; r <= 6; r++){
      st.stadiumRingData.rings[r] = { norte: false, sul: false, leste: false, oeste: false };
    }
  }

  // Auto-cura de upgrades para todos os saves
  st.stadiumUpgrades = st.stadiumUpgrades || {};
  const allUpgradeKeys = ['chairs', 'mosaic', 'ledRing', 'flares', 'screen', 'ledLights', 'vipBoxes', 'surroundSound', 'museumTour', 'solarPitch'];
  allUpgradeKeys.forEach(k => {
    st.stadiumUpgrades[k] = !!st.stadiumUpgrades[k];
  });
}
if(typeof window !== 'undefined') window.syncStadiumCapacityAndLevel = syncStadiumCapacityAndLevel;

// =========================================================================
// SISTEMA DE CONSTRUÇÃO DE NOVA ARENA DO CLUBE (ATÉ 100 MIL)
// =========================================================================
function calcArenaTotalCost(cap){
  if(cap <= 15000) return 75000000;
  if(cap <= 30000) return 165000000;
  if(cap <= 50000) return 325000000;
  if(cap <= 80000) return 600000000;
  return 850000000;
}

function buyDirectArenaLand(mode = 'cash'){
  const capacity = getSelectedArenaCapacity();
  const landCost = arenaLandCost(capacity);
  if(state.arenaLandBought){
    toast('O Lote Urbano já foi adquirido e escriturado para o clube!');
    return false;
  }
  if(mode === 'cash'){
    if(state.balance < landCost){
      toast(`Saldo insuficiente no caixa para comprar o Lote Urbano à vista (${fmtMoney(landCost)})!`);
      return false;
    }
    state.balance -= landCost;
    state.expense = (state.expense || 0) + landCost;
    state.arenaLandBought = true;
    toast('🏙️ Lote Urbano adquirido com sucesso! Escritura registrada em cartório.');
  } else {
    const down = Math.round(landCost * 0.10);
    if(state.balance < down){
      toast(`Saldo insuficiente para entrada da parceria do terreno (${fmtMoney(down)})!`);
      return false;
    }
    state.balance -= down;
    state.expense = (state.expense || 0) + down;
    state.arenaLandBought = true;
    state.arenaLandDebt = { monthly: Math.round(landCost * 0.9 / 24), roundsRemaining: 24, principal: landCost, capacity };
    toast('🏛️ Parceria público-privada aprovada! Entrada de 10% quitada e terreno liberado.');
  }
  save();
  render();
  return true;
}

function buyDirectArenaPermit(mode = 'cash'){
  const capacity = getSelectedArenaCapacity();
  const permitCost = arenaPermitCost(capacity);
  if(state.arenaPermitBought){
    toast('O Alvará da Prefeitura já foi emitido e aprovado!');
    return false;
  }
  if(mode === 'cash'){
    if(state.balance < permitCost){
      toast(`Saldo insuficiente no caixa para emitir o Alvará da Prefeitura (${fmtMoney(permitCost)})!`);
      return false;
    }
    state.balance -= permitCost;
    state.expense = (state.expense || 0) + permitCost;
    state.arenaPermitBought = true;
    toast('🏛️ Alvará de Construção da Prefeitura e licença ambiental emitidos!');
  } else {
    const down = Math.round(permitCost * 0.10);
    if(state.balance < down){
      toast(`Saldo insuficiente para entrada das taxas do alvará (${fmtMoney(down)})!`);
      return false;
    }
    state.balance -= down;
    state.expense = (state.expense || 0) + down;
    state.arenaPermitBought = true;
    state.arenaPermitDebt = { monthly: Math.round(permitCost * 0.9 / 24), roundsRemaining: 24, principal: permitCost, capacity };
    toast('📋 Convênio municipal aprovado! Alvará emitido com taxas parceladas.');
  }
  save();
  render();
  return true;
}

function buyDirectArenaBoth(){
  const capacity = getSelectedArenaCapacity();
  const landCost = arenaLandCost(capacity);
  const permitCost = arenaPermitCost(capacity);
  const total = (state.arenaLandBought ? 0 : landCost) + (state.arenaPermitBought ? 0 : permitCost);
  if(state.arenaLandBought && state.arenaPermitBought){
    toast('Os pré-requisitos legais (Lote e Alvará) já estão 100% quitados!');
    return false;
  }
  if(state.balance < total){
    toast(`Saldo insuficiente para regularizar Lote e Alvará à vista (${fmtMoney(total)})!`);
    return false;
  }
  state.balance -= total;
  state.expense = (state.expense || 0) + total;
  if(!state.arenaLandBought) state.arenaLandBought = true;
  if(!state.arenaPermitBought) state.arenaPermitBought = true;
  toast('🎉 Regularização completa! Lote escriturado e Alvará emitido com sucesso.');
  save();
  render();
  return true;
}

function startNewArenaProject(name, cap, financingMethod = 'cash'){
  const arenaData = getNewArenaData();
  if(arenaData.underConstruction){
    toast('Já existe uma Nova Arena em construção para o clube!');
    return;
  }

  if(!state.arenaLandBought){
    openCustomModal(
      '🏙️ Lote Urbano Pendente',
      `
        <div style="font-size:13px;line-height:1.6;color:rgba(255,255,255,0.85)">
          Para iniciar as obras da nova arena, o clube precisa primeiro adquirir o terreno.<br><br>
          <div style="background:#181428;padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.1)">
            <b>Opções de Regularização:</b><br>
            • <b>À Vista:</b> R$ 12.000.000<br>
            • <b>Financiamento Municipal:</b> Entrada de 10% (R$ 1.200.000) e 24 parcelas.
          </div>
        </div>
      `,
      () => { buyDirectArenaLand(state.balance >= 12000000 ? 'cash' : 'finance'); },
      state.balance >= 12000000 ? 'Comprar Lote à Vista (R$ 12 Mi)' : 'Financiar Lote (10% entrada)',
      true,
      '500px'
    );
    return;
  }
  if(!state.arenaPermitBought){
    openCustomModal(
      '🏛️ Alvará da Prefeitura Pendente',
      `
        <div style="font-size:13px;line-height:1.6;color:rgba(255,255,255,0.85)">
          O projeto civil precisa do alvará de construção e da licença ambiental municipal.<br><br>
          <div style="background:#181428;padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.1)">
            <b>Opções de Emissão:</b><br>
            • <b>À Vista:</b> R$ 4.500.000<br>
            • <b>Parcelamento de Taxas:</b> Entrada de 10% (R$ 450.000) e 24 parcelas.
          </div>
        </div>
      `,
      () => { buyDirectArenaPermit(state.balance >= 4500000 ? 'cash' : 'finance'); },
      state.balance >= 4500000 ? 'Emitir Alvará à Vista (R$ 4,5 Mi)' : 'Parcelar Alvará (10% entrada)',
      true,
      '500px'
    );
    return;
  }

  const finalCap = [15000, 30000, 50000, 80000, 100000].includes(Number(cap)) ? Number(cap) : 15000;
  const totalCost = calcArenaTotalCost(finalCap);
  let downPayment = totalCost;
  let months = finalCap <= 15000 ? 18 : finalCap <= 30000 ? 24 : finalCap <= 50000 ? 30 : finalCap <= 80000 ? 36 : 42;
  let monthly = 0;

  if(financingMethod === 'cash'){
    if(state.balance < totalCost){
      toast(`Caixa insuficiente para pagamento à vista (${fmtMoney(totalCost)})!`);
      return;
    }
    state.balance -= totalCost;
    state.expense = (state.expense || 0) + totalCost;
    monthly = 0;
  } else {
    downPayment = Math.round(totalCost * 0.20);
    if(state.balance < downPayment){
      toast(`Entrada de 20% (${fmtMoney(downPayment)}) insuficiente no caixa do clube!`);
      return;
    }
    state.balance -= downPayment;
    state.expense = (state.expense || 0) + downPayment;

    if(financingMethod === '4years'){
      months = 48;
      monthly = Math.round((totalCost * 0.80 * 1.25) / 48);
    } else if(financingMethod === '6years'){
      months = 72;
      monthly = Math.round((totalCost * 0.80 * 1.35) / 72);
    } else { // 8years
      months = 96;
      monthly = Math.round((totalCost * 0.80 * 1.45) / 96);
    }
  }

  arenaData.underConstruction = true;
  arenaData.name = name;
  arenaData.capacity = finalCap;
  arenaData.financingMethod = financingMethod;
  arenaData.roundsTotal = months;
  arenaData.roundsRemaining = months;
  arenaData.monthly = monthly;

  state.news.unshift(`🏛️ PROJETO MONUMENTAL: O ${state.club} iniciou a construção da ${name} (${finalCap.toLocaleString('pt-BR')} lugares)! Custo total: ${fmtMoney(totalCost)}. ${financingMethod==='cash'?'Pago 100% à vista!':'Entrada de 20% quitada e parcelamento ativo.'}`);
  toast(`🎉 Obra monumental da ${name} (${finalCap.toLocaleString('pt-BR')} lugares) iniciada com sucesso!`);
  save();
  render();
}
window.buyDirectArenaLand = buyDirectArenaLand;
window.buyDirectArenaPermit = buyDirectArenaPermit;
window.buyDirectArenaBoth = buyDirectArenaBoth;
window.startNewArenaProject = startNewArenaProject;

// =========================================================================
// SISTEMA DO MUSEU DO CLUBE (16 NÍVEIS & VITRINE DE TAÇAS)
// =========================================================================
function upgradeMuseum(){
  if(window.__afmFacilityLock && Date.now() - window.__afmFacilityLock < 300) return;
  window.__afmFacilityLock = Date.now();
  const m = getMuseumData();
  state.museumData = state.museumData || { level: 1, skipOfferUsed: false };
  const currentLvl = Math.max(
    1,
    Number(state.infrastructure?.museum?.level || state.facilities?.museum || state.museumData.level || 1)
  );
  state.museumData.level = currentLvl;
  if(currentLvl >= 16){
    toast('O Museu do Clube já atingiu o nível máximo: Panteão do Clube!');
    return;
  }
  const nextLevel = currentLvl + 1;
  const nextLvlMeta = MUSEUM_LEVELS.find(x => x.level === nextLevel) || { level: nextLevel, name: `Nível ${nextLevel}`, cost: 50000 };
  const cfgCost = typeof getMuseumConfig === 'function' ? Number(getMuseumConfig(currentLvl)?.cost || 0) : 0;
  const upgradeCost = cfgCost > 0 ? cfgCost : nextLvlMeta.cost;

  if(state.balance < upgradeCost){
    toast(`Saldo insuficiente! Custo para evoluir ao nível ${nextLevel}: ${fmtMoney(upgradeCost)}`);
    return;
  }

  state.balance -= upgradeCost;
  state.expense = (state.expense || 0) + upgradeCost;
  state.museumData.level = nextLevel;
  if(!state.infrastructure) state.infrastructure = {};
  if(!state.infrastructure.museum) state.infrastructure.museum = { level: nextLevel };
  state.infrastructure.museum.level = nextLevel;
  if(state.facilities && typeof state.facilities === 'object') state.facilities.museum = nextLevel;
  state.trust = state.trust || {};
  state.trust.fans = Math.min(100, (state.trust.fans || 70) + 8);

  toast(`🏆 Museu inaugurado no nível ${nextLevel}/16 (${nextLvlMeta.name})! A torcida está em festa com o novo espaço das taças!`);
  save();
  render();
}

function skipUpgradeMuseum(){
  if(window.__afmFacilityLock && Date.now() - window.__afmFacilityLock < 300) return;
  window.__afmFacilityLock = Date.now();
  const uMus = typeof getUnifiedMuseumData === 'function' ? getUnifiedMuseumData(state) : null;
  const m = getMuseumData();
  state.museumData = state.museumData || { level: 1, skipOfferUsed: false };
  const currentLvl = uMus ? uMus.level : Math.max(1, Number(state.infrastructure?.museum?.level || state.facilities?.museum || state.museumData.level || 1));
  const neededCap = uMus ? uMus.totalCount : m.allTitles.length;
  const targetLevel = uMus ? uMus.neededLevel : (MUSEUM_LEVELS.find(x => x.capacity >= neededCap) || MUSEUM_LEVELS[MUSEUM_LEVELS.length - 1]).level;
  const targetLvlObj = MUSEUM_LEVELS.find(x => x.level === targetLevel) || MUSEUM_LEVELS[MUSEUM_LEVELS.length - 1];

  if(targetLevel <= currentLvl){
    toast('Todas as taças já cabem na vitrine atual!');
    return;
  }

  let totalCost = 0;
  if(uMus && typeof uMus.skipCost === 'number' && uMus.skipCost > 0){
    totalCost = uMus.skipCost;
  } else {
    for(let i = currentLvl + 1; i <= targetLevel; i++){
      const lvl = MUSEUM_LEVELS.find(x => x.level === i);
      if(lvl) totalCost += lvl.cost;
    }
  }

  if(state.balance < totalCost){
    toast(`Saldo insuficiente para oferta única de Ampliar de Uma Vez (${fmtMoney(totalCost)})!`);
    return;
  }

  state.balance -= totalCost;
  state.expense = (state.expense || 0) + totalCost;
  state.museumData.level = targetLevel;
  state.museumData.skipOfferUsed = true;
  if(!state.infrastructure) state.infrastructure = {};
  if(!state.infrastructure.museum) state.infrastructure.museum = { level: targetLevel };
  state.infrastructure.museum.level = targetLevel;
  if(state.facilities && typeof state.facilities === 'object') state.facilities.museum = targetLevel;
  state.trust = state.trust || {};
  state.trust.fans = Math.min(100, (state.trust.fans || 70) + 15);

  const newCap = uMus && typeof getMuseumConfig === 'function' ? getMuseumConfig(targetLevel).capacity : targetLvlObj.capacity;
  toast(`⚡ Oferta acionada! O museu foi direto para Nível ${targetLevel}/16 (${newCap} vagas)! Todas as taças voltaram para a vitrine!`);
  save();
  render();
}

// =========================================================================
// SISTEMA DE SUA CASA & PATRIMÔNIO DO TREINADOR
// =========================================================================
function buyHouseItem(itemId){
  const item = HOUSE_ITEMS.find(x => x.id === itemId);
  if(!item) return;

  state.housePurchases = state.housePurchases || [];
  if(state.housePurchases.includes(itemId)){
    toast('Você já possui este bem/licença!');
    return;
  }

  // Validação dupla (Carreira + Saldo Bancário Pessoal)
  if (typeof evaluatePersonalAssetStatus === 'function') {
    const status = evaluatePersonalAssetStatus(item, state);
    if (!status.unlocked) {
      toast(`🔒 Bloqueado: ${status.reqLabel || item.reqText}`);
      return;
    }
    if (!status.canAfford) {
      toast(`Saldo bancário insuficiente! Você possui ${fmtMoney(status.cash)}, mas o item custa ${fmtMoney(item.cost)}.`);
      return;
    }
  } else {
    const pMoney = state.managerMoney || (state.career && state.career.cash) || 57000;
    if(pMoney < item.cost){
      toast('Seu patrimônio pessoal é insuficiente para adquirir este item!');
      return;
    }

    // Validação de requisitos
    if(!item.unlocked){
      const seasons = Number(state.career?.seasonsCompleted ?? state.historySeasons ?? 0);
      if(item.reqType === 'seasons' && seasons < item.reqVal){
        toast(`Requisito não atingido: ${item.reqText}`);
        return;
      }
      if(item.reqType === 'titles' && (state.titles || []).length < item.reqVal){
        toast(`Requisito não atingido: ${item.reqText}`);
        return;
      }
    }
  }

  // Deduz estritamente do patrimônio pessoal do treinador
  if (state.career && typeof state.career.cash === 'number') state.career.cash -= item.cost;
  if (typeof state.personalCash === 'number') state.personalCash -= item.cost;
  if (typeof state.managerMoney === 'number') state.managerMoney -= item.cost;
  if (state.managerPersonal && typeof state.managerPersonal.personalBalance === 'number') state.managerPersonal.personalBalance -= item.cost;

  state.housePurchases.push(itemId);
  if (window.AFMCareerFix && typeof window.AFMCareerFix.calculateCareerEconomy === 'function') {
    window.AFMCareerFix.calculateCareerEconomy(state);
  }
  toast(`🎉 Parabéns! Você adquiriu ${item.name} por ${fmtMoney(item.cost)}!`);
  save();
  render();
}

// =========================================================================
// SISTEMA DE OLHEIRO NO MERCADO (RELATÓRIOS EM 1 MÊS & BUSCA DE PROMESSAS EM 5 MESES)
// =========================================================================
function activeScoutCount(gameState = state){
  // Missions are queues, not hired staff: old saves with queued missions but no
  // hired scout must not permit free scouting actions.
  return Math.max(0, Math.floor(Number(gameState?.scoutStaffCount ?? gameState?.staff?.scouts ?? gameState?.scouts ?? 0) || 0));
}

function requireActiveScout(actionLabel = 'realizar esta ação', gameState = state){
  if(activeScoutCount(gameState) > 0) return true;
  toast(`Você precisa contratar pelo menos 1 olheiro para ${actionLabel}.`);
  return false;
}

function scoutSlotCapacity(gameState = state){
  return activeScoutCount(gameState) > 0 ? 2 : 0;
}

const SCOUT_MONTHLY_SALARY = 18000;
function getMonthlyScoutPayroll(gameState = state){
  return activeScoutCount(gameState) * SCOUT_MONTHLY_SALARY;
}

function hireScoutStaff(){
  if(!state) return;
  const current = activeScoutCount(state);
  const maxScouts = 3;
  const signingCost = 30000;
  if(current >= maxScouts){ toast(`O clube já atingiu o limite de ${maxScouts} olheiros contratados.`); return; }
  if(Number(state.balance) < signingCost){ toast(`Saldo insuficiente para contratar um olheiro. Custo inicial: ${fmtMoney(signingCost)}.`); return; }
  state.balance -= signingCost;
  state.expense = (Number(state.expense) || 0) + signingCost;
  state.scoutStaffCount = current + 1;
  state.news = Array.isArray(state.news) ? state.news : [];
  state.news.unshift(`🕵️ NOVO OLHEIRO CONTRATADO: o clube agora tem ${state.scoutStaffCount} olheiro(s). Custo inicial ${fmtMoney(signingCost)} e salário de ${fmtMoney(SCOUT_MONTHLY_SALARY)}/mês por profissional.`);
  state.news = state.news.slice(0,50);
  toast(`Olheiro contratado! ${state.scoutStaffCount} no clube; até ${scoutSlotCapacity(state)} trabalhos simultâneos.`);
  save();
  render();
}

function sendScoutToPlayer(key){
  if(!requireActiveScout('analisar um jogador')) return;
  state.scoutMissions = state.scoutMissions || [];
  if(state.scoutMissions.length >= scoutSlotCapacity()){
    toast('Não há vaga de trabalho disponível para este olheiro.');
    return;
  }

  const cost = 25000;
  if(state.balance < cost){
    toast(`Saldo insuficiente! O envio do olheiro custa ${fmtMoney(cost)}.`);
    return;
  }

  const p = marketUniverse().find(x => playerKey(x) === key);
  if(!p){
    toast('Jogador não encontrado no mercado.');
    return;
  }

  state.balance -= cost;
  state.expense = (state.expense || 0) + cost;
  state.scoutMissions.push({
    type: 'player',
    playerKey: key,
    playerName: p.name,
    club: p.club,
    roundsTotal: 4,      // 1 mês = 4 rodadas
    roundsLeft: 4
  });

  toast(`🔍 Olheiro enviado para analisar ${p.name}! Relatório completo em 1 mês (4 rodadas).`);
  save();
  render();
}

