function processPendingTransfersOnWindowOpen(gameState = state){
  if(!gameState) return false;
  const isWinOpen = (typeof isTransferWindowOpen === 'function') ? isTransferWindowOpen(gameState.date) : false;
  if(!isWinOpen) return false;

  let changed = false;
  gameState.news = Array.isArray(gameState.news) ? gameState.news : [];
  gameState.playerMoves = gameState.playerMoves || {};

  // 1. Processa saídas do elenco do usuário (atletas vendidos ou emprestados fora da janela que aguardavam abertura)
  if(Array.isArray(gameState.squad) && gameState.squad.length > 0){
    const remaining = [];
    const departedSales = [];
    const departedLoans = [];

    gameState.squad.forEach(p => {
      if(!p){ return; }
      const pt = p.pendingTransfer || (p.isSold ? { type: 'sale', buyerClub: p.soldTo || 'Outro Clube', fee: p.soldFee || p.price || 0 } : null);
      if(pt && pt.type === 'sale'){
        departedSales.push({ player: p, transfer: pt });
      } else if(pt && pt.type === 'loan_out'){
        departedLoans.push({ player: p, transfer: pt });
      } else {
        remaining.push(p);
      }
    });

    if(departedSales.length > 0 || departedLoans.length > 0){
      gameState.squad = remaining;
      changed = true;

      departedSales.forEach(({ player, transfer }) => {
        const pKey = (typeof playerKey === 'function') ? playerKey(player) : (player.id || player.name);
        const buyerClub = transfer.buyerClub || 'novo clube';
        gameState.playerMoves[pKey] = buyerClub;
        gameState.playerMoves[norm(player.name)] = buyerClub;
        gameState.lineup = (gameState.lineup || []).map(k => (k === pKey || k === player.name || k === player.id || (player.id && k === String(player.id))) ? null : k);

        // Feed mundial do mercado
        gameState.marketWorldFeed = gameState.marketWorldFeed || [];
        gameState.marketWorldFeed.unshift({
          player: player.name,
          pos: player.pos,
          ovr: (typeof playerOverall === 'function') ? playerOverall(player) : 75,
          from: gameState.club,
          to: buyerClub,
          fee: transfer.fee || transfer.price || 0,
          date: gameState.date
        });
        if(gameState.marketWorldFeed.length > 30) gameState.marketWorldFeed = gameState.marketWorldFeed.slice(0, 30);

        // Atualiza histórico de transferências
        if(Array.isArray(gameState.transfers)){
          const trRecord = gameState.transfers.find(t => (t.name === player.name || t.playerName === player.name || t.player === player.name) && t.pending);
          if(trRecord){
            trRecord.pending = false;
            trRecord.finalizedDate = gameState.date;
          }
        }

        player.pendingTransfer = null;
        player.isSold = false;
        delete player.soldTo;
        delete player.soldFee;
        delete player.soldDate;

        gameState.news.unshift(`⭐ TRANSFERÊNCIA OFICIALIZADA: Com a reabertura da janela de transferências, ${player.name} despediu-se do ${gameState.club} e apresentou-se oficialmente ao ${buyerClub}!`);
        if(typeof toast === 'function') toast(`✈️ Janela Aberta: ${player.name} se apresentou ao ${buyerClub}!`);
      });

      departedLoans.forEach(({ player, transfer }) => {
        const pKey = (typeof playerKey === 'function') ? playerKey(player) : (player.id || player.name);
        const buyerClub = transfer.buyerClub || 'novo clube';
        gameState.playerMoves[pKey] = buyerClub;
        gameState.playerMoves[norm(player.name)] = buyerClub;
        gameState.loanedOut = Array.isArray(gameState.loanedOut) ? gameState.loanedOut : [];
        gameState.loanedOut.push({
          ...player,
          loanTo: buyerClub,
          isLoan: true,
          pendingTransfer: null
        });
        gameState.lineup = (gameState.lineup || []).map(k => (k === pKey || k === player.name || k === player.id || (player.id && k === String(player.id))) ? null : k);
        gameState.news.unshift(`🤝 EMPRÉSTIMO OFICIALIZADO: Com a janela aberta, ${player.name} apresentou-se ao ${buyerClub} para iniciar o período de empréstimo.`);
        if(typeof toast === 'function') toast(`🤝 Janela Aberta: ${player.name} apresentou-se ao ${buyerClub} por empréstimo!`);
      });
    }
  }

  // 2. Processa entradas no elenco do usuário (atletas contratados em pré-contrato ou pré-empréstimo)
  if(Array.isArray(gameState.pendingSignings) && gameState.pendingSignings.length > 0){
    gameState.squad = Array.isArray(gameState.squad) ? gameState.squad : [];
    gameState.pendingSignings.forEach(sp => {
      if(!sp) return;
      const pt = sp.pendingTransfer || { type: 'buy', buyerClub: gameState.club };
      const pKey = (typeof playerKey === 'function') ? playerKey(sp) : (sp.id || sp.name);
      const isAlreadyIn = gameState.squad.some(s => s && ((typeof playerKey === 'function' && playerKey(s) === pKey) || norm(s.name) === norm(sp.name)));
      if(!isAlreadyIn){
        const cleanPlayer = {
          ...sp,
          club: gameState.club,
          owned: pt.type === 'buy',
          isLoan: pt.type === 'loan_in',
          pendingTransfer: null
        };
        gameState.squad.push(cleanPlayer);
        gameState.playerMoves[pKey] = gameState.club;
        gameState.playerMoves[norm(sp.name)] = gameState.club;
        changed = true;

        if(pt.type === 'buy'){
          gameState.news.unshift(`🎉 REFORÇO APRESENTADO: Com a reabertura da janela, ${cleanPlayer.name} vestiu a camisa do ${gameState.club} e foi integrado oficialmente ao elenco!`);
          if(typeof toast === 'function') toast(`🎉 Janela Aberta: ${cleanPlayer.name} foi integrado oficialmente ao seu elenco!`);
        } else {
          gameState.news.unshift(`🤝 REFORÇO POR EMPRÉSTIMO: ${cleanPlayer.name} apresentou-se ao ${gameState.club} e já está à disposição da comissão técnica!`);
          if(typeof toast === 'function') toast(`🤝 Janela Aberta: ${cleanPlayer.name} chegou por empréstimo ao seu elenco!`);
        }
      }
    });
    gameState.pendingSignings = [];
  }

  // 3. Processa pendências de clubes da CPU (IA)
  if(Array.isArray(gameState.pendingCPUTransfers) && gameState.pendingCPUTransfers.length > 0){
    gameState.pendingCPUTransfers.forEach(cpuTr => {
      if(!cpuTr) return;
      const key = cpuTr.playerKey || cpuTr.playerName;
      if(key && cpuTr.buyerClub){
        gameState.playerMoves[key] = cpuTr.buyerClub;
        gameState.playerMoves[norm(cpuTr.playerName || '')] = cpuTr.buyerClub;
        changed = true;
      }
    });
    gameState.pendingCPUTransfers = [];
  }

  if(gameState.news.length > 50) gameState.news = gameState.news.slice(0, 50);

  if(changed && typeof optimizeLineup === 'function'){
    optimizeLineup();
  }
  return changed;
}
window.processPendingTransfersOnWindowOpen = processPendingTransfersOnWindowOpen;

function findGlobalPlayerByKey(key){
  if(!key) return null;
  // 1. Elenco do treinador
  let p = findSquadPlayerByKey(key);
  if(p) return p;
  // 2. Universo do mercado
  const mUni = (typeof marketUniverse === 'function') ? marketUniverse() : [];
  p = mUni.find(x => playerKey(x) === key);
  if(p) return p;
  // 3. Atletas do banco de dados ao vivo
  p = (typeof livePlayers !== 'undefined' && Array.isArray(livePlayers)) ? livePlayers.find(x => playerKey(x) === key) : null;
  if(p) return p;
  // 4. Atletas procedurais mundiais
  p = (state?.worldGenerated || []).find(x => playerKey(x) === key);
  if(p) return p;
  // 5. Busca por prefixo de ID
  if(key.startsWith('id:') || key.startsWith('fifa:') || key.startsWith('pes:')) {
    const raw = key.split(':')[1];
    p = (livePlayers || []).find(x => String(x.id) === raw || String(x.fifaId) === raw || String(x.pesId) === raw) ||
        (state?.worldGenerated || []).find(x => String(x.id) === raw || String(x.fifaId) === raw);
    if(p) return p;
  }
  // 6. Busca por nome normalizado
  const namePart = key.startsWith('n:') ? key.slice(2).split('|')[0] : norm(key);
  p = mUni.find(x => norm(x.name) === namePart) ||
      (livePlayers || []).find(x => norm(x.name) === namePart) ||
      (state?.worldGenerated || []).find(x => norm(x.name) === namePart);
  return p || null;
}

function calcValueMi(p){
  if(!p) return 0.05;
  const o = playerOverall(p);
  const age = Number(p.age) || 25;
  const pot = Number(p.potential) || o;

  // Curva realista de valor de mercado (R$) por escala técnica (Overall)
  let base = 0;
  if(o <= 50) {
    base = 20000 + Math.max(0, o - 40) * 2000;
  } else if(o <= 55) {
    base = 40000 + (o - 50) * 12000; // 40k -> 100k
  } else if(o <= 60) {
    base = 100000 + (o - 55) * 35000; // 100k -> 275k (Série D / Estaduais)
  } else if(o <= 65) {
    base = 275000 + (o - 60) * 115000; // 275k -> 850k (Candangão / Série C / Série D topo)
  } else if(o <= 70) {
    base = 850000 + (o - 65) * 650000; // 850k -> 4.1M (Série B)
  } else if(o <= 75) {
    base = 4100000 + (o - 70) * 2500000; // 4.1M -> 16.6M (Série A médios)
  } else if(o <= 80) {
    base = 16600000 + (o - 75) * 9000000; // 16.6M -> 61.6M (Série A estrelas)
  } else if(o <= 85) {
    base = 61600000 + (o - 80) * 25000000; // 61.6M -> 186.6M (Craques continentais)
  } else {
    base = 186600000 + (o - 85) * 65000000; // 186.6M -> 500M+ (Superastros mundiais)
  }

  // Fator de Idade Realista (jovens valorizados, veteranos desvalorizados)
  let ageMult = 1.0;
  if(age <= 18) ageMult = 1.50;
  else if(age <= 21) ageMult = 1.35;
  else if(age <= 24) ageMult = 1.18;
  else if(age <= 28) ageMult = 1.00;
  else if(age <= 30) ageMult = 0.82;
  else if(age <= 32) ageMult = 0.60;
  else if(age <= 34) ageMult = 0.40;
  else if(age <= 36) ageMult = 0.25;
  else ageMult = 0.15;

  // Bônus de Potencial para Jovens Atletas (até 26 anos)
  let potBonus = 1.0;
  if(pot > o && age <= 26) {
    potBonus += Math.min(0.60, (pot - o) * 0.05);
  }

  const finalReais = Math.round(base * ageMult * potBonus);
  const valMi = +(finalReais / 1e6).toFixed(3);
  p.value = valMi;
  return valMi;
}
window.calcValueMi = calcValueMi;

