function playerContractUntil(p){
  if(p?.contractUntil) return Number(p.contractUntil);
  const n = norm(p?.name || '');
  if(n === 'gustavinho') return 2027;
  if(n === 'juan rocha') return 2029;
  if(n === 'joao garcia') return 2029;
  if(n === 'anderson prestes') return 2028;
  if(n === 'kaua oliveira' || n === 'kaua') return 2028;
  if(n === 'romo') return 2029;
  if(n === 'matheus reggiori') return 2027;
  const hash = hashStr(p?.name || '') % 3;
  return 2027 + hash;
}

function addMonthsToIsoDate(date, months){
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(date || ''));
  if(!match) return '';
  const original = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12);
  if(original.getFullYear() !== Number(match[1]) || original.getMonth() !== Number(match[2]) - 1 || original.getDate() !== Number(match[3])) return '';
  const monthIndex = Number(match[1]) * 12 + Number(match[2]) - 1 + Math.max(0, Number(months) || 0);
  const year = Math.floor(monthIndex / 12);
  const month = monthIndex % 12 + 1;
  const lastDay = new Date(year, month, 0).getDate();
  const day = Math.min(Number(match[3]), lastDay);
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function getLoanEndDate(startDate, durationMonths){
  const nextDate = addMonthsToIsoDate(startDate, durationMonths);
  if(!nextDate) return '';
  const end = new Date(`${nextDate}T12:00:00`);
  end.setDate(end.getDate() - 1);
  return end.toISOString().slice(0, 10);
}

function getLoanRemainingDays(player, date = state?.date){
  if(!player?.loanEndDate || !date) return 0;
  if(!addMonthsToIsoDate(player.loanEndDate, 0) || !addMonthsToIsoDate(date, 0)) return 0;
  const end = new Date(`${player.loanEndDate}T12:00:00`);
  const current = new Date(`${date}T12:00:00`);
  if(!Number.isFinite(end.getTime()) || !Number.isFinite(current.getTime())) return 0;
  return Math.max(0, Math.ceil((end - current) / 86400000));
}

function normalizeLoanContractData(gameState){
  if(!Array.isArray(gameState?.squad)) return;
  gameState.squad.forEach(player => {
    if(!player?.isLoan) return;
    if(!addMonthsToIsoDate(player.loanEndDate, 0)){
      const endYear = Number(player.contractUntil) || Number(gameState.season) || 2026;
      player.loanStartDate = player.loanStartDate || `${endYear}-01-01`;
      player.loanEndDate = `${endYear}-12-31`;
      player.loanDurationMonths = Number(player.loanDurationMonths) || 12;
    }
    player.loanDurationMonths = Math.max(1, Number(player.loanDurationMonths) || 12);
  });
}

function detachLoanedPlayer(gameState, player){
  if(!gameState || !player?.isLoan) return false;
  const key = playerKey(player);
  const index = (gameState.squad || []).findIndex(item => playerKey(item) === key);
  if(index < 0) return false;
  gameState.squad.splice(index, 1);
  gameState.lineup = (gameState.lineup || []).map(itemKey => itemKey === key ? null : itemKey);
  gameState.playerMoves = gameState.playerMoves || {};
  gameState.playerMoves[key] = player.loanFrom || player.originalClub || player.club || 'Clube de Origem';
  _marketUniverseCache = null;
  _marketUniverseCacheRound = -1;
  _marketUniverseCacheMoves = -1;
  if(gameState === state && typeof optimizeLineup === 'function') optimizeLineup();
  return true;
}

function processLoanContractReturns(gameState = state, currentDate = gameState?.date){
  if(!gameState || !Array.isArray(gameState.squad) || !currentDate) return 0;
  normalizeLoanContractData(gameState);
  const expired = gameState.squad.filter(player => player?.isLoan && player.loanEndDate < currentDate);
  if(!expired.length) return 0;
  gameState.loans = Array.isArray(gameState.loans) ? gameState.loans : [];
  gameState.news = Array.isArray(gameState.news) ? gameState.news : [];
  expired.forEach(player => {
    if(!detachLoanedPlayer(gameState, player)) return;
    const parentClub = player.loanFrom || player.originalClub || 'clube de origem';
    gameState.loans.unshift({ type: 'loan_return', name: player.name, from: gameState.club, to: parentClub, date: currentDate });
    gameState.news.unshift(`↩️ FIM DO EMPRÉSTIMO: ${player.name} voltou ao ${parentClub} após o término do contrato temporário.`);
  });
  gameState.news = gameState.news.slice(0, 50);
  if(gameState === state){
    save();
    toast(`📅 ${expired.length === 1 ? `${expired[0].name} voltou ao clube de origem` : `${expired.length} jogadores voltaram aos clubes de origem`} pelo fim do empréstimo.`);
  }
  return expired.length;
}

function getPlayerContractRemainingMonths(p, stateRef){
  if(!p) return 12;
  const st = stateRef || window.state || {};
  if(p.isLoan){
    normalizeLoanContractData(st);
    const days = getLoanRemainingDays(p, st.date);
    return Math.ceil(days / 30.4375);
  }
  const until = playerContractUntil(p);
  const curDateStr = st.date || `${st.season || 2026}-01-01`;
  const parts = String(curDateStr).split('-');
  const curYear = parseInt(parts[0], 10) || (st.season || 2026);
  const curMonth = parseInt(parts[1], 10) || 1;

  if(until < curYear) return 0;

  const endMonth = Number(p.contractMonth) || 12;
  const diffYears = until - curYear;
  const remainingMonths = (diffYears * 12) + (endMonth - curMonth);

  return Math.max(0, remainingMonths);
}

function isPlayerContractExpiringSoon(p, stateRef){
  if(!p || p.isLoan) return false;
  return getPlayerContractRemainingMonths(p, stateRef) <= 6;
}

function syncExpiringContractsToTransferList(stateRef){
  const st = stateRef || window.state;
  if(!st || !Array.isArray(st.squad)) return;
  st.transferListed = Array.isArray(st.transferListed) ? st.transferListed : [];
  st.transferOffers = st.transferOffers || {};

  st.squad.forEach(p => {
    if(!p || p.isLoan || p.pendingTransfer) return;
    const key = playerKey(p);
    const monthsLeft = getPlayerContractRemainingMonths(p, st);
    if(monthsLeft <= 6){
      if(!st.transferListed.includes(key)){
        st.transferListed.push(key);
        p.autoListedExpiringContract = true;
      }
      if(!st.transferOffers[key] || st.transferOffers[key].length === 0){
        if(typeof generateBuyerOffers === 'function'){
          st.transferOffers[key] = generateBuyerOffers(p);
        }
      }
    }
  });
}
window.applyMonthlyTrainingAndCommercial = applyMonthlyTrainingAndCommercial;

function calcSalary(p){
  return playerSalary(p);
}

// 1. Teto salarial mensal justo por Overall e Divisão do Clube
function getExpectedPlayerMonthlyWage(player, club) {
  const ovr = Math.max(40, Number(player?.overall || player?.ovr || 60));
  const st = typeof state !== 'undefined' ? state : null;
  const compId = String(club?.division || club?.tier || club?.compId || st?.compId || '').toLowerCase();
  let tierMult = 1.0;
  if (compId.includes('bra-a') || compId.includes('bra_a') || compId === '1') tierMult = 4.5;
  else if (compId.includes('bra-b') || compId.includes('bra_b') || compId === '2') tierMult = 2.2;
  else if (compId.includes('bra-c') || compId.includes('bra_c') || compId === '3') tierMult = 1.35;
  const base = Math.max(3500, Math.round((Math.pow(Math.max(1, ovr - 45), 2.15) * 42) * tierMult));
  return base;
}

// 2. Salário mensal normalizado do atleta
function getPlayerMonthlyWageNormalized(player) {
  if (!player) return 0;
  const monthly = Number(player?.monthlyWage || player?.salarioMensal || 0);
  if (monthly > 0) return Math.round(monthly);
  let raw = Number(player?.wage || player?.salary || player?.salario || 0);
  if (raw <= 0 && typeof playerSalary === 'function') {
    raw = playerSalary(player);
  }
  if (raw <= 0) return 0;
  const isWeekly = player?.wagePeriod === 'weekly';
  return Math.round(isWeekly ? raw * 4 : raw);
}

// 3. Regra única para definir se o atleta está "caro para o nível"
function isPlayerWageExpensive(player, club) {
  const wage = getPlayerMonthlyWageNormalized(player);
  const expected = getExpectedPlayerMonthlyWage(player, club);
  return wage > Math.round(expected * 1.35);
}

// 4. Ano final de contrato normalizado (evita NaN na ordenação)
function getPlayerContractYear(player, currentYear = 2026) {
  const raw = player?.contractUntil ?? player?.contratoAte ?? player?.contractEnd;
  if (typeof raw === 'number' && !Number.isNaN(raw)) return raw;
  if (typeof raw === 'string') {
    const match = raw.match(/(\d{4})/);
    if (match) return Number(match[1]);
  }
  const yearsLeft = Number(player?.contractYears || player?.years || 1);
  return Number(currentYear || 2026) + Math.max(0, yearsLeft);
}

// 5. Snapshot completo e reconciliado do elenco para Contratos & Salários
function getSquadContractsSnapshot(targetState = state, targetClub = null) {
  const s = targetState || (typeof state !== 'undefined' ? state : null) || {};
  const c = targetClub || (typeof clubByName === 'function' && s.club ? clubByName(s.club) : s.club) || {};
  const currentYear = Number(s.year || s.season || 2026);

  let rawPlayers = [];
  if (Array.isArray(s.squad) && s.squad.length > 0) {
    rawPlayers = s.squad.filter(Boolean);
  } else if (Array.isArray(c.players) && c.players.length > 0) {
    rawPlayers = c.players.filter(Boolean);
  } else if (typeof playersForClub === 'function' && s.club) {
    try {
      rawPlayers = playersForClub(s.club, s.worldGenerated || []);
    } catch(e){}
  }

  const enriched = rawPlayers.map((p, idx) => {
    const monthlyWage = getPlayerMonthlyWageNormalized(p);
    const contractYear = getPlayerContractYear(p, currentYear);
    const expensive = isPlayerWageExpensive(p, c);
    const expiringSoon = contractYear <= currentYear;
    return {
      ...p,
      _idx: idx,
      _monthlyWage: monthlyWage,
      _contractYear: contractYear,
      _expensive: expensive,
      _expiringSoon: expiringSoon
    };
  });

  const totalMonthlyPayroll = enriched.reduce((sum, p) => sum + p._monthlyWage, 0);
  const expensiveCount = enriched.filter((p) => p._expensive).length;
  const expiringCount = enriched.filter((p) => p._expiringSoon).length;
  const maxSquadLimit = Number(c.squadLimit || (typeof squadCapacity === 'function' ? squadCapacity() : 25));

  const avgOvr = enriched.length ? Math.round(enriched.reduce((acc, p) => acc + (Number(p.ovr || p.overall) || 60), 0) / enriched.length) : 60;
  const recommendedTierCap = getExpectedPlayerMonthlyWage({ overall: avgOvr }, c);

  return {
    players: enriched,
    totalCount: enriched.length,
    maxSquadLimit,
    expensiveCount,
    expiringCount,
    totalMonthlyPayroll,
    totalAnnualPayroll: totalMonthlyPayroll * 12,
    recommendedTierCap
  };
}

function isExpensiveForTier(p){
  const club = (typeof clubByName === 'function' && state?.club) ? clubByName(state.club) : null;
  return isPlayerWageExpensive(p, club);
}

if(typeof window !== 'undefined'){
  window.getExpectedPlayerMonthlyWage = getExpectedPlayerMonthlyWage;
  window.getPlayerMonthlyWageNormalized = getPlayerMonthlyWageNormalized;
  window.isPlayerWageExpensive = isPlayerWageExpensive;
  window.getPlayerContractYear = getPlayerContractYear;
  window.getSquadContractsSnapshot = getSquadContractsSnapshot;
  window.isExpensiveForTier = isExpensiveForTier;
}

