function clubStateCompId(clubName){
  const nameNorm = norm(clubName);
  if(CLUB_TO_STATE_COMP[nameNorm]) return CLUB_TO_STATE_COMP[nameNorm];
  if(typeof state !== 'undefined' && state && state.customClub && norm(state.customClub.name) === nameNorm){
    return state.customClub.stateCompId || state.customClubStateCompId || 'bra-est-sp';
  }

  // Saved rosters are equally authoritative: hydration can lag behind a promoted save.
  const tMap = Object.assign({}, window.COMPETITION_TEAMS || {}, state?.competitionTeams || {});
  for(const [cId, list] of Object.entries(tMap)){
    if(cId.startsWith('bra-est-') && Array.isArray(list)){
      if(list.some(c => norm(typeof c === 'string' ? c : c?.name) === nameNorm)) return cId;
    }
  }
  const clubObj = clubByName(clubName);
  const comp = clubObj?.competition || '';
  if(comp.includes('Candango')) return 'bra-est-df';
  if(comp.includes('Paulista')) return 'bra-est-sp';
  if(comp.includes('Carioca')) return 'bra-est-rj';
  if(comp.includes('Mineiro')) return 'bra-est-mg';
  if(comp.includes('Gaúcho') || comp.includes('Gaucho')) return 'bra-est-rs';
  if(comp.includes('Paranaense')) return 'bra-est-pr';
  if(comp.includes('Catarinense')) return 'bra-est-sc';
  if(comp.includes('Baiano')) return 'bra-est-ba';
  if(comp.includes('Cearense')) return 'bra-est-ce';
  if(comp.includes('Goiano')) return 'bra-est-go';
  if(comp.includes('Pernambucano')) return 'bra-est-pe';
  // A legacy save can have a national Série A-D membership but no estadual entry.
  if(['bra-a','bra-b','bra-c','bra-d'].some(id => (tMap[id] || []).some(c => norm(typeof c === 'string' ? c : c?.name) === nameNorm))){
    const clubText = norm(`${clubName} ${clubObj?.name || ''} ${clubObj?.state || ''} ${clubObj?.uf || ''} ${clubObj?.competition || ''}`);
    if(/\b(brasilia|aruc|gama|ceilandia|sobradinho|samambaia|paranoa|capital-df|real brasilia|brasiliense)\b/.test(clubText)) return 'bra-est-df';
    if(/\b(sao paulo|paulista|bragantino|corinthians|palmeiras|santos|sao bernardo|mirassol)\b/.test(clubText)) return 'bra-est-sp';
    if(/\b(rio de janeiro|carioca|flamengo|fluminense|vasco|botafogo|volta redonda)\b/.test(clubText)) return 'bra-est-rj';
    if(/\b(mineiro|belo horizonte|cruzeiro|atletico-mg|america-mg)\b/.test(clubText)) return 'bra-est-mg';
    if(/\b(gaucho|rio grande do sul|porto alegre|gremio|internacional|juventude|caxias)\b/.test(clubText)) return 'bra-est-rs';
    if(/\b(paranaense|curitiba|athletico-pr|operario-pr|coritiba|maringa)\b/.test(clubText)) return 'bra-est-pr';
    if(/\b(catarinense|santa catarina|chapecoense|figueirense|avai|criciuma|brusque)\b/.test(clubText)) return 'bra-est-sc';
    if(/\b(baiano|salvador|bahia|vitoria)\b/.test(clubText)) return 'bra-est-ba';
    if(/\b(cearense|fortaleza|ceara|ferroviario)\b/.test(clubText)) return 'bra-est-ce';
    if(/\b(pernambucano|recife|sport|nautico|santa cruz)\b/.test(clubText)) return 'bra-est-pe';
    return 'bra-est-sp';
  }
  // Se for clube explicitamente brasileiro sem estadual mapeado, usa SP como fallback. Clubes internacionais NÃO possuem estadual.
  if(clubObj?.country === 'Brasil' || (state?.club && norm(state.club) === nameNorm && (state?.country === 'Brasil' || String(state?.compId || '').startsWith('bra-')))){
    return 'bra-est-sp';
  }
  return null;
}

// Returns all roster memberships; a Brazilian club may play both national and estadual leagues.
function getClubCompetitionIds(clubName){
  if(!clubName) return [];
  const key = norm(clubName), ids = new Set();
  for(const map of [state?.competitionTeams || BASE_COMPETITION_TEAMS || window.COMPETITION_TEAMS].filter(Boolean)){
    for(const [id, roster] of Object.entries(map)){
      if(Array.isArray(roster) && roster.some(name => norm(typeof name === 'string' ? name : name?.name) === key)) ids.add(id);
    }
  }
  // A national division and an estadual are simultaneous memberships.
  const nationalId = getClubPrimaryCompetitionId(clubName, state?.compId);
  if(['bra-a','bra-b','bra-c','bra-d'].includes(nationalId)) ids.add(nationalId);
  const stateId = clubStateCompId(clubName);
  const stateRoster = state?.competitionTeams?.[stateId] || BASE_COMPETITION_TEAMS?.[stateId] || window.COMPETITION_TEAMS?.[stateId] || [];
  // Membership can be derived from the state association even when an old save lost the roster entry.
  if(stateId && (stateRoster.some(name=>norm(typeof name==='string'?name:name?.name)===key) || ['bra-a','bra-b','bra-c','bra-d'].includes(nationalId))) ids.add(stateId);
  return [...ids];
}
function getClubPrimaryCompetitionId(clubName, preferredCompId = null){
  if(!clubName) return preferredCompId || 'bra-a';
  const nameNorm = norm(clubName);
  const tMap = state?.competitionTeams || BASE_COMPETITION_TEAMS || window.COMPETITION_TEAMS || {};

  // A promoted club's explicit saved division has priority over stale historical
  // club metadata, even while the global roster is being hydrated.
  if(['bra-a','bra-b','bra-c','bra-d'].includes(preferredCompId) && compById(preferredCompId)){
    const savedTeams = Array.isArray(state?.teams) ? state.teams : [];
    const persistedRoster = state?.competitionTeams?.[preferredCompId] || tMap[preferredCompId] || [];
    if(savedTeams.some(team => norm(team?.name) === nameNorm) || persistedRoster.some(team => norm(typeof team === 'string' ? team : team?.name) === nameNorm)) return preferredCompId;
  }

  // Em saves de temporadas anteriores, a divisão nacional salva é dinâmica e deve prevalecer
  // sobre o catálogo histórico fixo do clube, desde que o clube conste na divisão salva.
  if(['bra-a','bra-b','bra-c','bra-d'].includes(preferredCompId) && compById(preferredCompId) && Array.isArray(tMap[preferredCompId])){
    const savedTeams = Array.isArray(state?.teams) ? state.teams : [];
    if(savedTeams.some(team => norm(team.name) === nameNorm) || tMap[preferredCompId].some(team => norm(team) === nameNorm)) return preferredCompId;
  }
  if(preferredCompId){
    const prefComp = compById(preferredCompId);
    if(prefComp && eligibleClubNames(prefComp).some(c => norm(c) === nameNorm)) return preferredCompId;
  }
  // Clubes candangos sem divisão nacional (Brasília, ARUC, etc.)
  if(nameNorm === 'brasilia' || nameNorm.includes('brasilia fc') || nameNorm === 'aruc' || nameNorm === 'paranoa' || nameNorm === 'samambaia' || nameNorm === 'sobradinho'){
    return 'bra-est-df';
  }

  // A atribuição dinâmica da temporada prevalece sobre o campeonato histórico
  // gravado no objeto estático do clube (que não acompanha acessos/rebaixamentos).
  const brDivs = ['bra-a', 'bra-b', 'bra-c', 'bra-d'];
  for(const divId of brDivs){
    if(Array.isArray(tMap[divId]) && tMap[divId].some(c => norm(c) === nameNorm)){
      return divId;
    }
  }

  const clubObj = clubByName(clubName);
  if(clubObj?.competition){
    const matchedComp = (window.COMPETITIONS||[]).find(c => norm(c.name) === norm(clubObj.competition));
    if(matchedComp && (matchedComp.id in tMap || !matchedComp.id.startsWith('bra-est-'))){
      return matchedComp.id;
    }
  }

  // 2. Principais ligas internacionais
  const intlLigas = ['usa-1', 'eng-1', 'eng-2', 'esp-1', 'esp-2', 'ita-1', 'ger-1', 'fra-1', 'por-1', 'ned-1', 'arg-1', 'uru-1', 'chi-1', 'col-1', 'par-1', 'ecu-1', 'per-1', 'bol-1', 'ven-1', 'ksa-1', 'jpn-1', 'kor-1', 'chn-1', 'qat-1', 'uae-1'];
  for(const lId of intlLigas){
    if(Array.isArray(tMap[lId]) && tMap[lId].some(c => norm(c) === nameNorm)){
      return lId;
    }
  }

  // 3. Estaduais
  const estId = clubStateCompId(clubName);
  if(estId && tMap[estId] && tMap[estId].some(c => norm(c) === nameNorm)){
    return estId;
  }

  // 4. Qualquer outra competição em tMap
  for(const [cId, list] of Object.entries(tMap)){
    if(Array.isArray(list) && list.some(c => norm(c) === nameNorm)){
      return cId;
    }
  }

  if(clubObj?.country === 'Brasil') return 'bra-a';
  return 'eng-1';
}

function compBaseStrength(comp){
  if(!comp)return 65;
  if(comp.id==='bra-a')return 78;if(comp.id==='bra-b')return 71;if(comp.id==='bra-c')return 64;if(comp.id==='bra-d')return 59;
  if(comp.continent==='Europa')return /champions|premier|laliga|serie a|bundesliga|ligue 1/i.test(comp.name)?80:73;
  if(comp.continent==='Ásia')return 69;
  if(comp.country==='Brasil'&&comp.id.startsWith('bra-est'))return 61;
  return 68;
}

function playerModeBudgetCap(comp){
  if(comp?.id === 'bra-a') return 25000000;
  if(comp?.id === 'bra-b') return 8000000;
  if(comp?.id === 'bra-c') return 2500000;
  if(comp?.id === 'bra-d') return 1200000;
  if(comp?.country === 'Brasil') return 1500000;
  if(comp?.continent === 'Europa') return compBaseStrength(comp) >= 78 ? 75000000 : 15000000;
  if(comp?.continent === 'América do Sul') return /segunda|divisi[oó]n intermedia|primera nacional|s[eé]rie b/i.test(comp.name) ? 5000000 : 15000000;
  if(comp?.continent === 'Ásia') return 15000000;
  return 10000000;
}

function playerModeStartingBudget(comp, club, squad, isCustom = false){
  if(isCustom) return 300000;
  const payroll = (Array.isArray(squad) ? squad : []).reduce((sum, player) => sum + (Number(player.wage) || 0), 0);
  return Math.min(playerModeBudgetCap(comp), Math.max(250000, (Number(club?.budget) || 5) * 1000000, Math.round(payroll * 2.5)));
}

function inferClubMeta(p){
  const league=String(p?.league||'');
  const rules=[
   [/premier league/i,'Inglaterra','Premier League'],[/championship/i,'Inglaterra','EFL Championship'],[/laliga|la liga/i,'Espanha','LaLiga'],[/serie a/i,'Itália','Serie A'],
   [/bundesliga/i,'Alemanha','Bundesliga'],[/ligue 1/i,'França','Ligue 1'],[/primeira liga|liga portugal/i,'Portugal','Primeira Liga'],[/eredivisie/i,'Países Baixos','Eredivisie'],
   [/argentina|liga profesional/i,'Argentina','Liga Profesional Argentina'],[/major league soccer|mls/i,'Estados Unidos','Major League Soccer'],[/saudi|roshn/i,'Arábia Saudita','Saudi Pro League'],[/j1 league|japan/i,'Japão','J1 League'],[/k league/i,'Coreia do Sul','K League 1'],[/chinese super league|china/i,'China','Chinese Super League']
  ];
  for(const [rx,country,competition] of rules) if(rx.test(league))return {country,competition};
  return {country:p?.clubCountry||p?.teamCountry||'Outro',competition:league||'Outros clubes'};
}

function buildClubs(){
  const map=new Map();
  (window.BASE_CLUBS||[]).forEach(c => {
    const item = clone(c);
    const sInfo = (typeof getClubStadiumInfo === 'function') ? getClubStadiumInfo(item.name) : (window.getClubStadiumInfo ? window.getClubStadiumInfo(item.name) : null);
    if (sInfo?.stadium && (!item.stadium || item.stadium === 'Estádio do clube' || item.stadium.toLowerCase().startsWith('estádio ' + item.name.toLowerCase()))) {
      item.stadium = sInfo.stadium;
    }
    map.set(norm(item.name), item);
  });
  const liveByClub={};
  for(const p of livePlayers){if(!p.club)continue;(liveByClub[p.club]??=[]).push(p)}
  for(const [name,ps] of Object.entries(liveByClub)){
    const vals=ps.map(playerOverall).filter(Boolean);const avg=Math.round(vals.reduce((a,b)=>a+b,0)/(vals.length||1));const key=norm(name);const existing=map.get(key);const meta=inferClubMeta(ps[0]);
    const sInfo = (typeof getClubStadiumInfo === 'function') ? getClubStadiumInfo(name) : (window.getClubStadiumInfo ? window.getClubStadiumInfo(name) : null);
    const stadName = sInfo?.stadium || 'Estádio do clube';
    if(existing){
      existing.atk=Math.round(((existing.atk||avg)+avg)/2);
      existing.mid=Math.round(((existing.mid||avg)+avg)/2);
      existing.def=Math.round(((existing.def||avg)+avg)/2);
      existing.playerCount=ps.length;
      if (!existing.stadium || existing.stadium === 'Estádio do clube') existing.stadium = stadName;
    }
    else map.set(key,{name,country:meta.country,competition:meta.competition,stadium:stadName,atk:avg,mid:avg,def:avg,budget:Math.max(.4,(avg-52)*2.2),playerCount:ps.length});
  }
  for(const [compId,names] of Object.entries(teamMap)){
    const comp=compById(compId);if(!comp)continue;const base=compBaseStrength(comp);
    names.forEach((name,i)=>{
      const key=norm(name);
      const sInfo = (typeof getClubStadiumInfo === 'function') ? getClubStadiumInfo(name) : (window.getClubStadiumInfo ? window.getClubStadiumInfo(name) : null);
      const stadName = sInfo?.stadium || 'Estádio do clube';
      if(!map.has(key)){
        const wiggle=(hashStr(name)%7)-3;const s=clamp(base+wiggle,48,88);
        map.set(key,{name,country:comp.country==='CONMEBOL'||comp.country==='UEFA'||comp.country==='AFC'?'Outro':comp.country,competition:comp.name,stadium:stadName,atk:s+rnd(-1,1),mid:s+rnd(-1,1),def:s+rnd(-1,1),budget:Math.max(.25,Math.pow(Math.max(3,s-48),1.35)/2.6)});
      } else {
        const exist = map.get(key);
        if (exist && (!exist.stadium || exist.stadium === 'Estádio do clube')) {
          exist.stadium = stadName;
        }
      }
    });
  }
  return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
}

function regionCountries(continent){
  if(continent==='América do Sul')return ['Brasil','Argentina','Uruguai','Chile','Colômbia','Equador','Paraguai','Peru','Bolívia','Venezuela'];
  if(continent==='América do Norte')return ['Estados Unidos','México','Canadá'];
  if(continent==='Europa')return ['Inglaterra','Espanha','Itália','Alemanha','França','Portugal','Países Baixos','Bélgica','Turquia','Escócia','Áustria','Suíça','Grécia','Croácia','Sérvia','Tchéquia','Dinamarca','Noruega','Suécia'];
  return ['Arábia Saudita','Japão','Coreia do Sul','China','Catar','Emirados Árabes Unidos','Irã','Índia','Tailândia','Austrália'];
}

function eligibleClubNames(comp, rosterOverride = null){
  if(!comp)return [];
  // The active career owns its seasonal roster. Static teamMap is the immutable
  // starting catalog and must never be changed by promotions/relegations.
  const savedRoster = rosterOverride?.[comp.id] || state?.competitionTeams?.[comp.id];
  if(Array.isArray(savedRoster)&&savedRoster.length)return [...savedRoster];
  if(window.AFM_RealWorldLeagues && typeof window.AFM_RealWorldLeagues.getClubsByCompetition === 'function'){
    const realClubs = window.AFM_RealWorldLeagues.getClubsByCompetition(comp, state);
    if(Array.isArray(realClubs) && realClubs.length) return [...realClubs];
  }
  const baseRoster = (typeof BASE_COMPETITION_TEAMS !== 'undefined' ? BASE_COMPETITION_TEAMS?.[comp.id] : null) || teamMap[comp.id];
  if(Array.isArray(baseRoster)&&baseRoster.length)return [...baseRoster];
  const exact=clubs.filter(c=>norm(c.competition)===norm(comp.name)).map(c=>c.name);
  if(exact.length)return [...new Set(exact)];
  if(['CONMEBOL','UEFA','AFC'].includes(comp.country))return clubs.filter(c=>regionCountries(comp.continent).includes(c.country)).map(c=>c.name);
  if(/cup|copa|taça|pokal|king/i.test(comp.name))return clubs.filter(c=>c.country===comp.country).map(c=>c.name);
  if(comp.id && comp.id.startsWith('bra-est-')) return []; // Jamais vazar todos os clubes do Brasil para estaduais vazios
  return clubs.filter(c=>c.country===comp.country).map(c=>c.name);
}

function competitionClubs(comp,selected,rosterOverride=null){
  let names=eligibleClubNames(comp,rosterOverride);
  const target=comp.teams||Math.max(10,names.length);
  if(selected&&!names.some(x=>norm(x)===norm(selected))){
    names.unshift(selected);
    if(names.length > target) names.pop();
  }
  const base=compBaseStrength(comp);
  const out=names.map(name=>clubByName(name)||{name,country:comp.country,competition:comp.name,stadium:'Estádio do clube',atk:base,mid:base,def:base,budget:5});
  const selectedRoster = rosterOverride?.[comp.id] || state?.competitionTeams?.[comp.id];
  const hasSavedRoster = Array.isArray(selectedRoster) && selectedRoster.length > 0;
  const baseRoster = (typeof BASE_COMPETITION_TEAMS !== 'undefined' ? BASE_COMPETITION_TEAMS?.[comp.id] : null) || teamMap[comp.id];
  const hasBaseRoster = Array.isArray(baseRoster) && baseRoster.length > 0;
  if(!hasBaseRoster && !hasSavedRoster){
    while(out.length<target){const n=out.length+1,s=clamp(base+rnd(-5,5),48,88);out.push({name:`Clube ${n} — ${comp.country}`,country:comp.country,competition:comp.name,stadium:'Estádio Municipal',atk:s,mid:s,def:s,budget:Math.max(.3,(s-50)*1.5)});}
  }
  if(selected && !hasBaseRoster && !hasSavedRoster){
    const sIdx = out.findIndex(x => norm(x.name) === norm(selected));
    if(sIdx >= target){
      const selItem = out.splice(sIdx, 1)[0];
      out.unshift(selItem);
    }
  }
  return out.slice(0,target);
}

// Auditoria central: a temporada só termina quando todas as competições
// efetivamente disputadas pelo clube não têm mais partidas pendentes.
function getPendingClubCompetitions(gameState = state){
  if(!gameState?.club) return [];
  // Older saves may not have initialized Copa data until its panel is opened.
  // Initialize it before checking whether the primary calendar ended the season.
  if(gameState === state && typeof getCopaDoBrasilState === 'function') getCopaDoBrasilState();
  const clubKey = norm(gameState.club);
  const season = Number(gameState.season);
  const pending = [];
  const push = (id, name, date, detail) => pending.push({id, name, date:date || null, detail:detail || ''});
  const history = Array.isArray(gameState.history) ? gameState.history : [];
  const hasResult = (id, fixture, roundIndex = null) => history.some(item =>
    Number(item.season || season) === season &&
    (!item.competitionId || item.competitionId === id) &&
    (roundIndex == null || Number(item.round) === roundIndex + 1) &&
    ((norm(item.h) === clubKey && norm(item.a) === norm(fixture[1])) ||
     (norm(item.a) === clubKey && norm(item.h) === norm(fixture[0])))
  );

  // Campeonato principal que alimenta as tabelas da carreira.
  const clubPrimaryRow = Array.isArray(gameState.teams) ? gameState.teams.find(t => norm(t?.name) === clubKey) : null;
  (Array.isArray(gameState.schedule) ? gameState.schedule : []).forEach((games, roundIndex) => {
    (Array.isArray(games) ? games : []).forEach(fixture => {
      if(!Array.isArray(fixture) || fixture.length < 2 || !fixture.some(team => norm(team) === clubKey)) return;
      const id = gameState.compId || 'primary';
      const playedByRoundCounter = roundIndex < Number(gameState.round || 0) && (!clubPrimaryRow || Number(clubPrimaryRow.j || 0) >= roundIndex + 1);
      const played = playedByRoundCounter || hasResult(id, fixture, roundIndex) || history.some(item => Number(item.season || season) === season && item.competitionId === id && Number(item.round) === roundIndex + 1 && (norm(item.h) === clubKey || norm(item.a) === clubKey));
      if(!played) push(id, compById(id)?.name || gameState.competition || 'Campeonato principal', getDateForRound(roundIndex, season), `Rodada ${roundIndex + 1}`);
    });
  });

  // Estaduais têm calendário independente do campeonato nacional.
  const stateIds = Object.keys(gameState.competitionTeams || window.COMPETITION_TEAMS || {}).filter(id => id.startsWith('bra-est-'));
  const assignedState = stateIds.find(id => (gameState.competitionTeams?.[id] || window.COMPETITION_TEAMS?.[id] || []).some(team => norm(typeof team === 'string' ? team : team?.name) === clubKey));
  if(assignedState){
    const data = getStateCompData(assignedState);
    (data?.fixtures || []).forEach((fixture, index) => {
      if(norm(fixture.home) !== clubKey && norm(fixture.away) !== clubKey) return;
      const played = fixture.played === true || Boolean(fixture.result || fixture.score) || history.some(item => Number(item.season || season) === season && (item.competitionId === assignedState || !item.competitionId) && ((norm(item.h) === norm(fixture.home) && norm(item.a) === norm(fixture.away)) || (norm(item.h) === norm(fixture.away) && norm(item.a) === norm(fixture.home))));
      if(!played) push(assignedState, compById(assignedState)?.name || 'Campeonato estadual', fixture.isoDate || getDateForRound(fixture.roundIndex ?? index, season), `Rodada ${(Number(fixture.roundIndex ?? index) || 0) + 1}`);
    });
  }

  // Copa do Brasil: só conta jogos ainda pendentes do clube, não de outras equipes.
  const copa = gameState === state && typeof getCopaDoBrasilState === 'function'
    ? getCopaDoBrasilState()
    : (gameState.copaData && Number(gameState.copaData.season) === season ? gameState.copaData : null);
  if(copa?.phases && (typeof isClubRegisteredInCopaDoBrasil !== 'function' || isClubRegisteredInCopaDoBrasil(gameState, gameState.club))){
    Object.entries(copa.phases).forEach(([phaseName, phase]) => (phase.fixtures || []).forEach(fixture => {
      if(norm(fixture.home) !== clubKey && norm(fixture.away) !== clubKey) return;
      const playedInHistory = history.some(item => Number(item.season || season) === season && item.competitionId === 'bra-cup' && ((norm(item.h) === norm(fixture.home) && norm(item.a) === norm(fixture.away)) || (norm(item.h) === norm(fixture.away) && norm(item.a) === norm(fixture.home))));
      if(fixture.score || fixture.winner || fixture.played === true || playedInHistory || phase.status === 'CONCLUÍDO') return;
      const rawCupDate = fixture.isoDate || phase.isoDate;
      const cupDate = rawCupDate ? ensureMidweekDate(rawCupDate, season) : rawCupDate;
      push('bra-cup', 'Copa do Brasil', cupDate, phaseName);
    }));
  }

  // Competições continentais/internacionais qualificadas e persistidas no save.
  for(const id of ['lib','sud','ucl','uel','uecl','afc-el','afc2','cwc']){
    const tournament = (gameState === state && typeof getContinentalTournament === 'function')
      ? getContinentalTournament(id)
      : gameState.tournaments?.[id];
    if(!tournament || Number(tournament.season) !== season) continue;
    (tournament.matches || []).forEach(match => {
      if((norm(match.home) !== clubKey && norm(match.away) !== clubKey) || match.status !== 'scheduled') return;
      const cDate = typeof ensureMidweekDate === 'function' ? ensureMidweekDate(match.date, season) : match.date;
      push(id, ({lib:'Copa Libertadores',sud:'Copa Sul-Americana',ucl:'UEFA Champions League',uel:'UEFA Europa League',uecl:'UEFA Conference League','afc-el':'AFC Champions League Elite',afc2:'AFC Champions League Two',cwc:'Mundial de Clubes FIFA'})[id] || id, cDate, `Rodada ${match.round || ''}`);
    });
  }
  return pending.sort((a,b) => String(a.date || '9999-12-31').localeCompare(String(b.date || '9999-12-31')));
}

function seasonCompetitionsComplete(gameState = state){
  return getPendingClubCompetitions(gameState).length === 0;
}

function getNextClubFixtureDate(gameState = state){
  const pending = getPendingClubCompetitions(gameState);
  // Prioriza sempre o compromisso NÃO JOGADO mais antigo em ordem cronológica (nunca pula jogo pendente/atrasado)
  return pending.find(item => item.date)?.date || null;
}

function getNextPendingClubFixture(gameState = state){
  if(!gameState) return null;
  const pending = getPendingClubCompetitions(gameState);
  const next = pending.filter(item => item.date).sort((a,b)=>String(a.date).localeCompare(String(b.date)))[0] || null;
  if(!next) return null;
  const clubKey = norm(gameState.club);

  if(next.id === 'bra-cup'){
    const copa = gameState === state && typeof getCopaDoBrasilState === 'function'
      ? getCopaDoBrasilState()
      : gameState.copaData;
    const phase = copa?.phases?.[next.detail];
    const fixtureIndex = (phase?.fixtures || []).findIndex(fixture =>
      !fixture.score && !fixture.winner && fixture.played !== true &&
      (norm(fixture.home) === clubKey || norm(fixture.away) === clubKey)
    );
    const fixture = fixtureIndex >= 0 ? phase.fixtures[fixtureIndex] : null;
    const isHome = fixture ? norm(fixture.home) === clubKey : true;
    const opp = fixture ? (isHome ? fixture.away : fixture.home) : 'Adversário';
    return {
      ...next,
      fixtureIndex,
      home: fixture?.home || (isHome ? gameState.club : opp),
      away: fixture?.away || (!isHome ? gameState.club : opp),
      opponent: opp,
      isHome
    };
  }

  if(['lib','sud','ucl','uel','uecl','afc-el','afc2','cwc'].includes(next.id)){
    const tournament = typeof getContinentalTournament === 'function' ? getContinentalTournament(next.id) : (gameState.tournaments?.[next.id]);
    const matches = Array.isArray(tournament?.matches) ? tournament.matches : [];
    const match = matches.find(m =>
      (m.status === 'scheduled' || (!m.result && !m.score)) &&
      (norm(m.home) === clubKey || norm(m.away) === clubKey) &&
      (m.date === next.date || `Rodada ${m.round}` === next.detail)
    ) || matches.find(m =>
      (m.status === 'scheduled' || (!m.result && !m.score)) &&
      (norm(m.home) === clubKey || norm(m.away) === clubKey)
    );
    if(match){
      const isHome = norm(match.home) === clubKey;
      const opp = isHome ? match.away : match.home;
      return {
        ...next,
        matchId: match.id,
        round: match.round,
        date: match.date || next.date,
        home: match.home,
        away: match.away,
        opponent: opp,
        isHome,
        detail: `Rodada ${match.round || ''}`
      };
    }
  }

  if(next.id && next.id.startsWith('bra-est-')){
    const data = typeof getStateCompData === 'function' ? getStateCompData(next.id) : null;
    const fixtureIndex = (data?.fixtures || []).findIndex(f =>
      !f.played && !f.result && (norm(f.home) === clubKey || norm(f.away) === clubKey) &&
      (!next.date || f.isoDate === next.date)
    );
    const fixture = fixtureIndex >= 0 ? data.fixtures[fixtureIndex] : (data?.fixtures || []).find(f => !f.played && !f.result && (norm(f.home) === clubKey || norm(f.away) === clubKey));
    if(fixture){
      const isHome = norm(fixture.home) === clubKey;
      const opp = isHome ? fixture.away : fixture.home;
      return {
        ...next,
        fixtureIndex,
        roundIndex: fixture.roundIndex,
        home: fixture.home,
        away: fixture.away,
        opponent: opp,
        isHome,
        date: fixture.isoDate || next.date,
        detail: `Rodada ${(Number(fixture.roundIndex) || 0) + 1}`
      };
    }
  }

  return next;
}

function openNextPendingCompetitionFixture(nextFixture = getNextPendingClubFixture(state)){
  if(!state || !nextFixture){
    toast('Não há mais partidas pendentes nas competições desta temporada.');
    return false;
  }
  const targetDate = nextFixture.date;
  if(targetDate && targetDate !== state.date){
    const current = new Date(`${state.date}T12:00:00`);
    const target = new Date(`${targetDate}T12:00:00`);
    if(Number.isFinite(target.getTime()) && target > current){
      const days = Math.max(1, Math.round((target - current) / 86400000));
      advanceCalendarDays(days, true);
    } else if(Number.isFinite(target.getTime()) && target < current){
      // Never simulate a user fixture retroactively in legacy saves.
      const repaired = ensureMidweekDate(state.date, state.season);
      if(nextFixture.id === 'bra-cup' && nextFixture.detail){
        const phase = state.copaData?.phases?.[nextFixture.detail];
        (phase?.fixtures || []).filter(f => !f.score && !f.winner && (norm(f.home) === norm(state.club) || norm(f.away) === norm(state.club))).forEach(f=>{ f.isoDate=repaired; f.date=formatDatePtBr(repaired); });
        if(phase){ phase.isoDate=repaired; phase.dateStr=formatDatePtBr(repaired); }
      }
      state.date = repaired;
      save();
    }
  }
  // Keep the user on the Central. Its match panel will render the pending
  // competition as the next commitment instead of redirecting to Calendar.
  const isPl = (typeof window !== 'undefined' && window.isPlayerCareerActive?.(state)) || state?.gameMode === 'player';
  view = isPl ? 'player_hub' : 'central';
  state.view = view;
  if(typeof window !== 'undefined') window.view = view;
  save();
  render();
  toast(`Próximo confronto aberto: ${nextFixture.name}${nextFixture.detail ? ` (${nextFixture.detail})` : ''}. Data: ${formatDatePtBr(state.date)}.`);
  return true;
}

function generatedRosterForClub(club){
  const c=clubByName(club)||{name:club,country:'Outro',atk:66,mid:66,def:66};const base=Math.min(76,strength(c));const arr=[];
  for(let i=0;i<25;i++){
    const pos=POSITIONS[i%POSITIONS.length];const age=18+(hashStr('age|'+club+'|'+i)%18);const o=age<=21?clamp(base-8+(hashStr(club+'|'+i)%6),52,72):(age<=28?clamp(base-3+((hashStr(club+'|'+i)%7)-3),55,78):clamp(base-5+((hashStr(club+'|'+i)%5)-2),52,75));const pot=clamp(o+(age<=21?(6+(hashStr('pot|'+club+'|'+i)%8)):(hashStr('pot|'+club+'|'+i)%4)),o,age<=21?84:80);const name=`${NAMES[(hashStr(club+'n'+i)%NAMES.length)]} ${LAST[(hashStr(club+'l'+i)%LAST.length)]}`;
    const p={id:`gen-${norm(club)}-${i}`,marketKey:`gen:${norm(club)}:${i}`,name,club,country:c.country||'Outro',pos,age,fc:o,pes:clamp(o+((i%3)-1),45,78),ovr:o,overall:o,potential:pot,value:0,morale:70,fitness:100,owned:false};p.value=calcValueMi(p);arr.push(p);
  }
  return arr;
}

function sanitizeWorldGeneratedPlayers(st = state){
  if(!st) return;
  const pools = [st.worldGenerated, st.worldRegens];
  pools.forEach(pool => {
    if(!Array.isArray(pool)) return;
    pool.forEach(p => {
      if(!p) return;
      const age = Number(p.age) || 22;
      const curOvr = playerOverall(p);
      const isGen = String(p.id || '').startsWith('gen-') || String(p.marketKey || '').startsWith('gen:') || pool === st.worldGenerated;
      if(isGen && curOvr > 78){
        const maxOvr = age <= 21 ? 72 : 78;
        p.fc = Math.min(p.fc || maxOvr, maxOvr);
        p.pes = Math.min(p.pes || maxOvr, maxOvr);
        p.ovr = maxOvr;
        p.overall = maxOvr;
        if(p.potential && p.potential > 84) p.potential = Math.min(84, maxOvr + (age <= 21 ? 8 : 2));
        p.value = calcValueMi(p);
      }
    });
  });
}
window.sanitizeWorldGeneratedPlayers = sanitizeWorldGeneratedPlayers;

function buildWorldGenerated(){
  const counts=new Map();for(const p of livePlayers){const k=norm(p.club);if(k)counts.set(k,(counts.get(k)||0)+1)}
  const out=[];for(const c of clubs){const liveCount=counts.get(norm(c.name))||0;if(liveCount>=11)continue;const need=Math.max(4,22-liveCount);out.push(...generatedRosterForClub(c.name).slice(0,need));}return out;
}

// =========================================================================
// NORMALIZAÇÃO & HIDRATAÇÃO GARANTIDA DE ELENCO (MODO TREINADOR)
// =========================================================================
function normalizeClubLookupKey(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}
window.normalizeClubLookupKey = normalizeClubLookupKey;

function generateFallbackSquadForClub(clubName, targetOvr = 56, count = 22) {
  const firstNames = [
    'Lucas', 'Gabriel', 'Matheus', 'Rafael', 'Bruno', 'Felipe', 'Gustavo', 'Pedro',
    'Vinícius', 'Caio', 'Diego', 'Thiago', 'Leonardo', 'Rodrigo', 'Eduardo', 'Henrique',
    'Igor', 'Renan', 'André', 'Marcelo', 'Daniel', 'Guilherme', 'João', 'Vitor'
  ];
  const lastNames = [
    'Silva', 'Santos', 'Oliveira', 'Souza', 'Pereira', 'Costa', 'Rodrigues', 'Almeida',
    'Nascimento', 'Lima', 'Araújo', 'Fernandes', 'Carvalho', 'Gomes', 'Martins', 'Rocha',
    'Ribeiro', 'Alves', 'Monteiro', 'Mendes', 'Barros', 'Freitas', 'Barbosa', 'Cardoso'
  ];
  const templatePositions = [
    'GK', 'GK',
    'RB', 'CB', 'CB', 'CB', 'LB', 'RB', 'LB',
    'DM', 'DM', 'CM', 'CM', 'AM', 'AM',
    'RW', 'LW', 'ST', 'ST', 'ST', 'RW', 'LW'
  ];

  const baseOvr = Math.max(48, Math.min(88, Number(targetOvr) || 56));
  const generated = [];
  const cName = String(clubName || 'Clube');
  const normKey = normalizeClubLookupKey(cName);

  for (let i = 0; i < count; i++) {
    const pos = templatePositions[i % templatePositions.length];
    const fn = firstNames[(i * 7 + baseOvr) % firstNames.length];
    const ln = lastNames[(i * 11 + baseOvr) % lastNames.length];
    const variation = (i % 5) - 2; // -2 a +2
    const ovr = Math.max(46, Math.min(92, baseOvr + variation));
    const age = 19 + ((i * 3) % 15);
    const pot = Math.min(94, ovr + (age <= 22 ? 8 : age <= 26 ? 4 : 1));
    const marketValue = Math.round(Math.pow(Math.max(1, ovr - 40), 2.35) * 4500);
    const salary = Math.max(4500, Math.round(marketValue * 0.018));
    const id = `gen_${normKey}_${i + 1}`;
    const name = `${fn} ${ln}`;

    generated.push({
      id,
      name,
      club: cName,
      pos,
      position: pos,
      age,
      ovr,
      overall: ovr,
      pot,
      potential: pot,
      salary,
      wage: salary,
      value: Math.round((marketValue / 1e6) * 100) / 100 || 0.15,
      marketValue,
      contractUntil: 2028,
      contractYears: 1 + (i % 3),
      fitness: 96,
      stamina: 96,
      morale: 80,
      shirtNumber: i + 1,
      number: i + 1,
      nationality: 'Brasil',
      transferListed: false,
      loanListed: false,
      injuredWeeks: 0,
      suspendedMatches: 0,
      marketKey: `${name}_${cName}_${pos}`,
      owned: true
    });
  }
  return generated;
}
window.generateFallbackSquadForClub = generateFallbackSquadForClub;

function syncLineupFromSquad(state) {
  if (!state || !Array.isArray(state.squad) || state.squad.length === 0) return;
  const squad = state.squad;

  const validKeys = new Set(squad.map(p => playerKey(p)));
  const validIds = new Set(squad.map(p => String(p.id || p.name)));

  let lineup = Array.isArray(state.lineup)
    ? state.lineup.filter(k => {
        if (!k) return false;
        if (typeof k === 'object') return validIds.has(String(k.id)) || validKeys.has(playerKey(k));
        return validKeys.has(String(k)) || validIds.has(String(k));
      }).map(k => typeof k === 'object' ? playerKey(k) : String(k))
    : [];

  if (lineup.length < 11) {
    const sorted = [...squad].sort((a, b) => (playerOverall(b) || b.ovr || 50) - (playerOverall(a) || a.ovr || 50));
    const used = new Set();
    const pickByPos = (positions) => {
      const found = sorted.find(p => !used.has(playerKey(p)) && positions.includes(String(p.pos || p.position || '').toUpperCase()));
      if (found) {
        used.add(playerKey(found));
        return playerKey(found);
      }
      const any = sorted.find(p => !used.has(playerKey(p)));
      if (any) {
        used.add(playerKey(any));
        return playerKey(any);
      }
      return null;
    };

    lineup = [
      pickByPos(['GK', 'GOL']),
      pickByPos(['LB', 'LE']),
      pickByPos(['CB', 'ZAG']),
      pickByPos(['CB', 'ZAG']),
      pickByPos(['RB', 'LD']),
      pickByPos(['CM', 'MC', 'AM', 'MEI']),
      pickByPos(['DM', 'VOL', 'CM']),
      pickByPos(['CM', 'MC', 'AM', 'MEI']),
      pickByPos(['LW', 'PE', 'LM', 'ME']),
      pickByPos(['ST', 'CA', 'ATA', 'CF']),
      pickByPos(['RW', 'PD', 'RM', 'MD'])
    ].filter(Boolean);

    // Garante que o slot 0 seja GK se tiver algum GK no squad
    const gkInSquad = squad.find(p => ['GK', 'GOL'].includes(String(p.pos || p.position || '').toUpperCase()));
    if (gkInSquad) {
      const gkKey = playerKey(gkInSquad);
      if (lineup[0] !== gkKey) {
        const existingIdx = lineup.indexOf(gkKey);
        if (existingIdx > 0) {
          [lineup[0], lineup[existingIdx]] = [lineup[existingIdx], lineup[0]];
        } else {
          lineup[0] = gkKey;
        }
      }
    }

    state.lineup = lineup;
  }

  // Preenche cobradores e capitão
  const starters = state.lineup.map(k => squad.find(p => playerKey(p) === k || String(p.id) === k)).filter(Boolean);
  if (starters.length > 0) {
    state.setPieces = state.setPieces || {};
    state.setPieceTakers = state.setPieceTakers || {};
    state.captains = Array.isArray(state.captains) ? state.captains : [];

    if (!state.captainId || !validIds.has(String(state.captainId))) {
      const cap = [...starters].sort((a, b) => (Number(b.age) || 24) - (Number(a.age) || 24))[0];
      state.captainId = cap ? (cap.id || playerKey(cap)) : null;
      if (cap) {
        state.setPieces.captain = playerKey(cap);
        state.captains[0] = cap.name;
      }
    }
    if (!state.penaltyTakerId || !validIds.has(String(state.penaltyTakerId))) {
      const pen = [...starters].sort((a, b) => (playerOverall(b) || b.ovr || 50) - (playerOverall(a) || a.ovr || 50))[0];
      state.penaltyTakerId = pen ? (pen.id || playerKey(pen)) : null;
      if (pen) {
        state.setPieces.penalty = playerKey(pen);
        state.setPieceTakers.penalties = playerKey(pen);
      }
    }
    if (!state.freekickTakerId || !validIds.has(String(state.freekickTakerId))) {
      const fk = starters.find(p => ['AM', 'MEI', 'CM', 'LW', 'RW', 'ST', 'ATA'].includes(String(p.pos || '').toUpperCase())) || starters[0];
      state.freekickTakerId = fk ? (fk.id || playerKey(fk)) : null;
      if (fk) {
        state.setPieces.freekick = playerKey(fk);
        state.setPieceTakers.freekicks = playerKey(fk);
      }
    }
  }
}
window.syncLineupFromSquad = syncLineupFromSquad;

function ensureManagerSquadHydrated(targetState = state) {
  if (!targetState || targetState.gameMode === 'player') return (targetState?.squad || []);

  // Limpeza de resíduos de sessões do Modo Jogador
  if (typeof document !== 'undefined') {
    const oldDayAdv = document.getElementById('afmDayAdvanceNewsModal');
    if (oldDayAdv) oldDayAdv.remove();
    const oldPostHub = document.getElementById('afmPostMatchHubModal');
    if (oldPostHub) oldPostHub.remove();
  }
  if (targetState.playerCareer || targetState.playerCareerState || targetState.controlledPlayerId) {
    targetState.playerCareer = null;
    targetState.playerCareerState = null;
    targetState.controlledPlayerId = null;
  }
  if (Array.isArray(targetState.news)) {
    targetState.news = targetState.news.filter(n => typeof n === 'string' && !n.includes('treinamentos do') && !n.includes('atleta do usuário'));
  }

  const clubObj = typeof targetState.club === 'object' && targetState.club !== null ? targetState.club : (typeof targetState.userClub === 'object' ? targetState.userClub : {});
  const clubName = typeof targetState.club === 'string' ? targetState.club : (clubObj.name || targetState.clubName || targetState.userClub || 'Clube');
  const clubId = clubObj.id || clubObj.clubId || targetState.clubId;
  const normTarget = normalizeClubLookupKey(clubName);

  // 1. Verifica fontes existentes de elenco no state
  let currentSquad = Array.isArray(targetState.squad) && targetState.squad.length > 0
    ? targetState.squad.filter(Boolean)
    : (Array.isArray(clubObj.squad) && clubObj.squad.length > 0 ? clubObj.squad.filter(Boolean) : []);

  // 2. Se estiver com menos de 11 atletas, busca na base de jogadores
  if (currentSquad.length < 11) {
    const globalPools = [
      (typeof livePlayers !== 'undefined' && Array.isArray(livePlayers) ? livePlayers : null),
      (typeof PLAYERS_DB !== 'undefined' && Array.isArray(PLAYERS_DB) ? PLAYERS_DB : null),
      (typeof ALL_PLAYERS !== 'undefined' && Array.isArray(ALL_PLAYERS) ? ALL_PLAYERS : null),
      (typeof AFM_PLAYERS !== 'undefined' && Array.isArray(AFM_PLAYERS) ? AFM_PLAYERS : null),
      (Array.isArray(targetState.playersDb) ? targetState.playersDb : null),
      (Array.isArray(targetState.allPlayers) ? targetState.allPlayers : null),
      (Array.isArray(targetState.worldGenerated) ? targetState.worldGenerated : null)
    ].filter(Boolean);

    for (const pool of globalPools) {
      const matched = pool.filter(p => {
        if (!p) return false;
        if (clubId && (p.clubId === clubId || p.teamId === clubId)) return true;
        const pClubNorm = normalizeClubLookupKey(p.club || p.team || p.clubName);
        return pClubNorm && pClubNorm === normTarget;
      });
      if (matched.length >= 11) {
        currentSquad = matched.map((p, idx) => ({
          ...p,
          id: p.id || `pl_${normTarget}_${idx + 1}`,
          club: clubName,
          pos: (p.pos || p.position || 'CM').toUpperCase(),
          position: (p.pos || p.position || 'CM').toUpperCase(),
          ovr: Number(p.ovr || p.overall || playerOverall(p) || 56),
          overall: Number(p.ovr || p.overall || playerOverall(p) || 56),
          pot: Number(p.pot || p.potential || (Number(p.ovr || 56) + 4)),
          age: Number(p.age || 24),
          salary: Number(p.salary || p.wage || 8000),
          wage: Number(p.wage || p.salary || 8000),
          value: Number(p.value || p.marketValue || calcValueMi(p) || 0.2),
          marketValue: Number(p.marketValue || p.value || 150000),
          fitness: Number(p.fitness ?? p.stamina ?? 95),
          stamina: Number(p.stamina ?? p.fitness ?? 95),
          morale: Number(p.morale ?? 78),
          contractYears: Number(p.contractYears ?? 2),
          contractUntil: p.contractUntil || 2028,
          shirtNumber: Number(p.shirtNumber || p.number || (idx + 1)),
          number: Number(p.number || p.shirtNumber || (idx + 1)),
          marketKey: playerKey(p),
          owned: true
        }));
        break;
      }
    }
  }

  // 3. Se ainda estiver insuficiente (< 14 atletas), gera plantel completo calibrado (ex: Ceilândia Série D)
  if (currentSquad.length < 14) {
    const clubOvr = Number(clubObj.ovr || clubObj.overall || clubObj.atk || targetState.teamOvr || 55);
    const needed = Math.max(22 - currentSquad.length, 14);
    const fallback = generateFallbackSquadForClub(clubName, clubOvr, needed);
    currentSquad = [...currentSquad, ...fallback];
  }

  // 4. Sincroniza em todos os pontos de leitura do estado
  targetState.squad = currentSquad;
  if (typeof clubObj === 'object' && clubObj !== null) {
    clubObj.squad = currentSquad;
  }

  // 5. Garante 11 titulares válidos na tática (slot 0 = GK) e cobradores
  syncLineupFromSquad(targetState);

  return currentSquad;
}
window.ensureManagerSquadHydrated = ensureManagerSquadHydrated;

function autoNumberSquad(targetState = state) {
  if (!targetState || !Array.isArray(targetState.squad)) return;
  const starters = (targetState.lineup || []).map(k => targetState.squad.find(p => playerKey(p) === k || String(p.id) === k)).filter(Boolean);
  const others = targetState.squad.filter(p => !starters.includes(p));

  let starterGk = starters.find(p => ['GK','GOL'].includes(String(p.pos||'').toUpperCase()));
  if (starterGk) starterGk.number = 1;
  let sNum = 2;
  starters.forEach(p => {
    if (p !== starterGk) {
      p.number = sNum++;
    }
  });
  let rNum = 12;
  others.forEach(p => {
    p.number = rNum++;
  });
  targetState.squad.forEach(p => {
    p.shirtNumber = p.number;
  });
  if (typeof save === 'function') save();
  if (typeof toast === 'function') toast('🔢 Elenco numerado com sucesso (1 a 25)!');
  if (typeof render === 'function') render();
}
window.autoNumberSquad = autoNumberSquad;

// =========================================================================
// BLINDAGEM DE SESSÃO, CALENDÁRIO & NOTÍCIAS (MODO TREINADOR)
// =========================================================================
function cleanManagerSessionModals() {
  if (typeof document === 'undefined') return;
  const dayAdv = document.getElementById('afmDayAdvanceNewsModal');
  if (dayAdv) {
    dayAdv.innerHTML = '';
    dayAdv.style.display = 'none';
    if (typeof dayAdv.remove === 'function') dayAdv.remove();
  }
  const postHub = document.getElementById('afmPostMatchHubModal');
  if (postHub) {
    postHub.innerHTML = '';
    postHub.style.display = 'none';
    if (typeof postHub.remove === 'function') postHub.remove();
  }
}
window.cleanManagerSessionModals = cleanManagerSessionModals;

function formatSafeMatchDate(rawDate, fallbackIndex = 0) {
  if (!rawDate) {
    const base = new Date(2026, 0, 18 + fallbackIndex * 4);
    return base.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
  }
  if (typeof rawDate === 'number') {
    const base = new Date(2026, 0, 1 + rawDate);
    return base.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
  }
  const str = String(rawDate);
  const parsed = new Date(str.includes('T') ? str : `${str}T12:00:00`);
  if (!Number.isNaN(parsed.getTime())) {
    return parsed.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
  }
  return str;
}
window.formatSafeMatchDate = formatSafeMatchDate;

function ensureManagerCalendarHydrated(targetState = state) {
  if (!targetState) return [];
  cleanManagerSessionModals();
  const clubObj = typeof targetState.club === 'object' && targetState.club !== null ? targetState.club : (typeof targetState.userClub === 'object' ? targetState.userClub : {});
  const clubName = typeof targetState.club === 'string' ? targetState.club : (clubObj.name || targetState.clubName || 'Meu Clube');
  const compName = clubObj.league || clubObj.competition || targetState.competitionName || 'Campeonato Brasileiro Série D';
  const normTarget = typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(clubName) : String(clubName).toLowerCase();

  const existingSchedule = Array.isArray(targetState.schedule) ? targetState.schedule : [];
  const existingFixtures = Array.isArray(targetState.fixtures) ? targetState.fixtures : [];

  let hasMatches = false;
  if (existingSchedule.length > 0) {
    hasMatches = existingSchedule.some(round => {
      if (!Array.isArray(round)) return false;
      return round.some(match => {
        if (Array.isArray(match)) {
          return match.some(team => (typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(team) : String(team).toLowerCase()) === normTarget);
        }
        if (match && typeof match === 'object') {
          const hNorm = typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(match.home) : String(match.home).toLowerCase();
          const aNorm = typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(match.away) : String(match.away).toLowerCase();
          return hNorm === normTarget || aNorm === normTarget;
        }
        return false;
      });
    });
  }

  if (!hasMatches && existingFixtures.length > 0) {
    hasMatches = existingFixtures.some(f => {
      if (!f || typeof f !== 'object') return false;
      const hNorm = typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(f.home) : String(f.home).toLowerCase();
      const aNorm = typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(f.away) : String(f.away).toLowerCase();
      return hNorm === normTarget || aNorm === normTarget;
    });
  }

  if (hasMatches && existingSchedule.length > 0) {
    return existingSchedule;
  }

  const rivals = [
    'Brasiliense', 'Anápolis', 'Mixto', 'Real Brasília', 'Capital-DF',
    'Gama', 'Aparecidense', 'CRAC', 'Iporá', 'Operário-VG', 'Samambaia', 'Paranoá'
  ].filter(r => (typeof normalizeClubLookupKey === 'function' ? normalizeClubLookupKey(r) : r.toLowerCase()) !== normTarget);

  const generatedSchedule = [];
  const generatedFixtures = [];

  for (let round = 0; round < 14; round++) {
    const opp = rivals[round % rivals.length];
    const isHome = round % 2 === 0;
    const matchDate = new Date(2026, 0, 18 + round * 7);
    const isoDate = matchDate.toISOString().slice(0, 10);
    const homeTeam = isHome ? clubName : opp;
    const awayTeam = isHome ? opp : clubName;

    generatedFixtures.push({
      id: `fix_${round + 1}`,
      round: round + 1,
      date: isoDate,
      competition: round < 4 ? 'Torneio Início / Estadual' : compName,
      home: homeTeam,
      away: awayTeam,
      stadium: isHome ? (clubObj.stadium || 'Estádio Mandante') : `Estádio do ${opp}`,
      played: false,
      homeGoals: null,
      awayGoals: null
    });

    generatedSchedule.push([[homeTeam, awayTeam]]);
  }

  targetState.schedule = generatedSchedule;
  targetState.fixtures = generatedFixtures;
  return generatedSchedule;
}
window.ensureManagerCalendarHydrated = ensureManagerCalendarHydrated;

function ensureManagerNewsHydrated(targetState = state) {
  if (!targetState) return [];
  cleanManagerSessionModals();
  const clubObj = typeof targetState.club === 'object' && targetState.club !== null ? targetState.club : (typeof targetState.userClub === 'object' ? targetState.userClub : {});
  const clubName = typeof targetState.club === 'string' ? targetState.club : (clubObj.name || targetState.clubName || 'Clube');
  const managerName = targetState.manager || targetState.managerName || targetState.coachName || 'Novo Treinador';
  const currentDate = targetState.currentDate || targetState.date || '01/01/2026';

  let list = Array.isArray(targetState.news) ? targetState.news : [];

  if (targetState.gameMode !== 'player') {
    const pName = targetState.playerCareer?.name ? String(targetState.playerCareer.name).toLowerCase() : '';
    list = list.filter(n => {
      const text = String(typeof n === 'string' ? n : (n.title || n.text || n.headline || '')).toLowerCase();
      if (pName && text.includes(pName)) return false;
      if (text.includes('treinamentos do') || text.includes('atleta do usuário') || text.includes('rumo ao estrelato')) return false;
      return true;
    });
  }

  if (list.length === 0) {
    list = [
      {
        id: 'news_init_1',
        date: currentDate,
        category: 'MYCLUB',
        channel: 'G1',
        source: 'G1 Esporte',
        badgeColor: '#c4170c',
        time: 'Hoje',
        club: clubName,
        title: `${clubName} anuncia ${managerName} como novo comandante para a temporada 2026`,
        text: `A diretoria oficializou a contratação e definiu o planejamento esportivo e financeiro para a disputa da temporada.`
      },
      {
        id: 'news_init_2',
        date: currentDate,
        category: 'MARKET',
        channel: 'CAZETV',
        source: 'CazéTV',
        badgeColor: '#eab308',
        time: 'Hoje',
        club: clubName,
        title: `Janela de transferências aberta: ${clubName} mapeia reforços dentro do orçamento`,
        text: `Com comissão técnica definida, o departamento de futebol avalia oportunidades de mercado e jogadores em fim de contrato.`
      },
      {
        id: 'news_init_3',
        date: currentDate,
        category: 'COMPETITION',
        channel: 'TWITTER',
        source: 'Twitter / X',
        badgeColor: '#1d9bf0',
        time: 'Hoje',
        club: clubName,
        title: `Tabela base da temporada 2026 divulgada pela federação`,
        text: `Comissão técnica já pode consultar todos os confrontos, mandos de campo e datas na aba Calendário de Jogos.`
      }
    ];
  }

  targetState.news = list;
  return list;
}
window.ensureManagerNewsHydrated = ensureManagerNewsHydrated;

// -------------------------------------------------------------
// UNIFICAÇÃO DE PRESTÍGIO, DATAS E ECONOMIA DO TREINADOR
// -------------------------------------------------------------
function parseSafeLocalDate(rawDate) {
  if (!rawDate) return new Date(2026, 0, 1, 12, 0, 0);
  if (rawDate instanceof Date) return rawDate;
  const str = String(rawDate).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
    const [y, m, d] = str.split('-').map(Number);
    return new Date(y, m - 1, d, 12, 0, 0);
  }
  const parsed = new Date(str);
  return Number.isNaN(parsed.getTime()) ? new Date(2026, 0, 1, 12, 0, 0) : parsed;
}
window.parseSafeLocalDate = parseSafeLocalDate;

function getUnifiedManagerPrestige(state) {
  const s = state || window.state || {};
  const pts = Math.max(0, Number(s.managerPrestige ?? s.coachPrestige ?? s.prestige ?? 5) || 0);
  const titlesList = Array.isArray(s.managerTitles)
    ? s.managerTitles
    : (Array.isArray(s.trophies) ? s.trophies : (Array.isArray(s.titles) ? s.titles : []));
  const titlesCount = typeof s.titlesCount === 'number' ? s.titlesCount : titlesList.length;
  const level = Math.min(99, Math.max(1, Math.floor(pts / 15) + 1));
  let license = 'LICENÇA CBF D (INICIANTE)';
  if (level >= 60) license = 'LICENÇA UEFA PRO (LENDA)';
  else if (level >= 40) license = 'LICENÇA CBF PRO (ELITE)';
  else if (level >= 25) license = 'LICENÇA CBF A (NACIONAL)';
  else if (level >= 12) license = 'LICENÇA CBF B (REGIONAL)';
  else if (level >= 5) license = 'LICENÇA CBF C (FORMAÇÃO)';
  return { pts, level, titlesCount, license };
}
window.getUnifiedManagerPrestige = getUnifiedManagerPrestige;

function ensureManagerEconomyHydrated(state) {
  const s = state || window.state;
  if (!s) return;
  if (typeof s.personalCash !== 'number' || Number.isNaN(s.personalCash)) {
    s.personalCash = Number(s.managerCash ?? s.managerMoney ?? 104250) || 104250;
  }
  if (!s.managerPersonal) s.managerPersonal = {};
  if (typeof s.managerPersonal.personalBalance !== 'number') {
    s.managerPersonal.personalBalance = s.personalCash;
  }
  if (!Array.isArray(s.ownedProperties)) s.ownedProperties = [];
  if (!Array.isArray(s.ownedBusinesses)) s.ownedBusinesses = [];
  if (!Array.isArray(s.ownedVehicles)) s.ownedVehicles = [];
  if (!Array.isArray(s.safShares)) s.safShares = [];
  if (!Array.isArray(s.salaryHistory)) s.salaryHistory = [];
  if (!s.careerSubTab) s.careerSubTab = 'trainer';

  if (!Array.isArray(s.managerPersonal.properties)) s.managerPersonal.properties = s.ownedProperties;
  if (!Array.isArray(s.managerPersonal.businesses)) s.managerPersonal.businesses = s.ownedBusinesses;
  if (!Array.isArray(s.managerPersonal.vehicles)) s.managerPersonal.vehicles = s.ownedVehicles;
  if (!s.managerPersonal.safPortfolio || typeof s.managerPersonal.safPortfolio !== 'object') {
    s.managerPersonal.safPortfolio = {};
  }
}
window.ensureManagerEconomyHydrated = ensureManagerEconomyHydrated;

function ensureClubStructureHydrated(state) {
  const s = state || (typeof window !== 'undefined' ? window.state : null);
  if (!s) return;

  // 1. Garante arrays válidos (previne .reduce / .some / .map is not a function)
  if (!Array.isArray(s.bankLoans)) {
    s.bankLoans = Array.isArray(s.bankLoans?.activeLoans) ? s.bankLoans.activeLoans : [];
  }
  if (!Array.isArray(s.trophies)) s.trophies = [];
  if (!Array.isArray(s.clubTrophies)) s.clubTrophies = [];
  if (!Array.isArray(s.youthPlayers)) s.youthPlayers = [];
  if (!Array.isArray(s.titles)) s.titles = [];

  // 2. Garante níveis válidos das 11 estruturas
  const defaultFacilities = {
    stadium: 2,
    parking: 0,
    training: 1,
    academy: 1,
    medical: 1,
    admin: 1,
    store: 1,
    museum: 1,
    press: 1,
    marketing: 1,
    bank: 1
  };
  if (!s.facilities || typeof s.facilities !== 'object' || Array.isArray(s.facilities)) {
    s.facilities = { ...defaultFacilities };
  } else {
    for (const [k, defVal] of Object.entries(defaultFacilities)) {
      if (typeof s.facilities[k] !== 'number' || Number.isNaN(s.facilities[k])) {
        s.facilities[k] = defVal;
      }
    }
  }

  if (!s.infrastructure || typeof s.infrastructure !== 'object' || Array.isArray(s.infrastructure)) {
    s.infrastructure = {};
  }
  for (const [k, defVal] of Object.entries(defaultFacilities)) {
    if (!s.infrastructure[k] || typeof s.infrastructure[k] !== 'object') {
      s.infrastructure[k] = { level: s.facilities[k] ?? defVal };
    } else {
      if (typeof s.infrastructure[k].level !== 'number' || Number.isNaN(s.infrastructure[k].level)) {
        s.infrastructure[k].level = s.facilities[k] ?? defVal;
      }
    }
    s.facilities[k] = s.infrastructure[k].level;
  }

  // 3. Garante capacidade mínima do estádio (evita divisão por zero / NaN% na ocupação)
  const cap = Number(s.infrastructure.stadium?.capacity || s.stadiumCapacity || s.club?.stadiumCapacity || 18000);
  s.stadiumCapacity = cap >= 5000 ? cap : 18000;
  if (s.infrastructure.stadium) {
    s.infrastructure.stadium.capacity = s.stadiumCapacity;
  }

  // 4. Garante preços de ingresso e estacionamento persistidos no state
  if (typeof s.ticketPrice !== 'number' || Number.isNaN(s.ticketPrice) || s.ticketPrice < 10) {
    s.ticketPrice = 25;
  }
  if (typeof s.parkingPrice !== 'number' || Number.isNaN(s.parkingPrice) || s.parkingPrice < 10) {
    s.parkingPrice = 25;
  }

  // Sincroniza vagas do estacionamento
  if (typeof parkingSpots === 'function' && s.infrastructure.parking) {
    s.infrastructure.parking.spots = parkingSpots(s.infrastructure.parking.level);
  }

  // 5. Sincroniza economia pessoal caso o usuário abra a sub-aba "Sua Casa & Bens Pessoais"
  if (typeof window !== 'undefined' && typeof window.ensureManagerEconomyHydrated === 'function') {
    window.ensureManagerEconomyHydrated(s);
  } else if (typeof ensureManagerEconomyHydrated === 'function') {
    ensureManagerEconomyHydrated(s);
  }

  if (typeof syncStadiumCapacityAndLevel === 'function') {
    syncStadiumCapacityAndLevel(s);
  }
}
window.ensureClubStructureHydrated = ensureClubStructureHydrated;

function safeUpgradeFacility(facilityKey, upgradeFn) {
  if (window.__afmFacilityLock) return;
  window.__afmFacilityLock = true;
  try {
    if (typeof upgradeFn === 'function') upgradeFn(facilityKey);
    else if (typeof upgradeFacility === 'function') upgradeFacility(facilityKey);
  } finally {
    setTimeout(() => { window.__afmFacilityLock = false; }, 350);
  }
}
window.safeUpgradeFacility = safeUpgradeFacility;

