function playersForClub(club,worldGenerated){
  const live=livePlayers.filter(p=>norm(p.club)===norm(club)).map((p,i)=>({...p,id:p.id||`live-${hashStr(playerKey(p))}`,marketKey:playerKey(p),morale:p.morale??70,fitness:p.fitness??100,owned:true,value:calcValueMi(p)}));
  if(live.length >= 11){
    return live.map(p=>({...p,club,owned:true,marketKey:playerKey(p)}));
  }
  const gen=(worldGenerated||[]).filter(p=>norm(p.club)===norm(club));
  const res = [...live,...gen].slice(0,25).map(p=>({...p,club,owned:true,marketKey:playerKey(p)}));
  if(res.length >= 11) return res;
  return generateFallbackSquadForClub(club, 55, 22);
}

function restorePlayerCareerSquad(gameState){
  if(gameState?.gameMode !== 'player' || !gameState.club || !Array.isArray(gameState.squad) || gameState.squad.length >= 11) return false;
  let roster = playersForClub(gameState.club, gameState.worldGenerated || []);
  if(roster.length < 11) roster = generatedRosterForClub(gameState.club);
  const knownNames = new Set(gameState.squad.map(player => norm(player.name || '')).filter(Boolean));
  const targetSize = Math.min(25, Math.max(11, gameState.squad.length + roster.length));
  const initialSize = gameState.squad.length;
  for(const player of roster){
    const key = norm(player?.name || '');
    if(!key || knownNames.has(key) || gameState.squad.length >= targetSize) continue;
    knownNames.add(key);
    gameState.squad.push(stablePlayer({
      ...player,
      club: gameState.club,
      wage: Number(player.wage) > 0 ? Math.round(player.wage) : playerSalary(player, gameState),
      contractUntil: player.contractUntil || (Number(gameState.season) || 2026) + 2,
      owned: true
    }));
  }
  return gameState.squad.length > initialSize;
}

function stablePlayer(p){
  const o = playerOverall(p);
  let activeState = null;
  try { activeState = state || null; } catch (_) {}
  if (!activeState && typeof window !== 'undefined') activeState = window.state || null;
  const wage = (typeof p?.wage === 'number' && p.wage > 0) ? Math.round(p.wage) : playerSalary(p, activeState);
  const contractUntil = playerContractUntil(p);
  const isControlledAthlete = Boolean(
    p?.isControlled ||
    p?.isControlledAthlete ||
    (activeState?.controlledPlayerId && String(p?.id) === String(activeState.controlledPlayerId))
  );
  if (isControlledAthlete && typeof window !== 'undefined' && window.AFM_PlayerEngine?.calculateAthleteInitialMarketValue) {
    const mvBrl = window.AFM_PlayerEngine.calculateAthleteInitialMarketValue(o, p.age || 15);
    const mvMi = Number((mvBrl / 1000000).toFixed(3));
    return {...p, marketKey:playerKey(p), ovr:o, overall:o, fc:o, pes:o, marketValue:mvBrl, marketValueMi:mvMi, value:mvMi, wage, contractUntil};
  }
  return {...p, marketKey:playerKey(p), ovr:o, overall:o, value:calcValueMi(p), wage, contractUntil};
}
function calcClubMonthlySquadWages(club, targetState = (typeof state !== 'undefined' ? state : null)){
  const st = targetState || (typeof state !== 'undefined' ? state : null);
  const clubName = typeof club === 'string' ? club : (club?.name || st?.club || '');

  // 1. Prioriza elenco do targetState se tiver atletas
  if(st?.squad && Array.isArray(st.squad) && st.squad.length > 0 && (!clubName || norm(st.club) === norm(clubName))){
    const sum = st.squad.reduce((acc, p) => acc + ((typeof p?.wage === 'number' && p.wage > 0) ? p.wage : playerSalary(p, st)), 0);
    if(sum > 0) return Math.round(sum);
  }

  // 2. Se o clube passado possui elenco
  if(club && Array.isArray(club.players) && club.players.length > 0){
    const sum = club.players.reduce((acc, p) => acc + ((typeof p?.wage === 'number' && p.wage > 0) ? p.wage : playerSalary(p, st)), 0);
    if(sum > 0) return Math.round(sum);
  }

  // 3. Tenta buscar via playersForClub
  if(clubName && typeof playersForClub === 'function'){
    try {
      const generated = playersForClub(clubName, st?.worldGenerated || (typeof buildWorldGenerated === 'function' ? buildWorldGenerated() : []));
      if(Array.isArray(generated) && generated.length > 0){
        const sum = generated.reduce((acc, p) => acc + ((typeof p?.wage === 'number' && p.wage > 0) ? p.wage : playerSalary(p, st)), 0);
        if(sum > 0) return Math.round(sum);
      }
    } catch(e){}
  }

  // 4. Fallback calibrado pelo OVR da divisão para 22 atletas
  const ovr = (typeof clubByName === 'function' && typeof strength === 'function' && clubName) ? strength(clubByName(clubName)) : 55;
  const avgWage = ovr >= 80 ? 250000 : ovr >= 70 ? 45000 : ovr >= 60 ? 12000 : 3500;
  return Math.round(avgWage * 22);
}

function totalMonthlyPayroll(targetState = (typeof state !== 'undefined' ? state : null)){
  const st = targetState || (typeof state !== 'undefined' ? state : null);
  const c = (typeof clubByName === 'function' && st?.club) ? clubByName(st.club) : null;
  return calcClubMonthlySquadWages(c, st);
}

if(typeof window !== 'undefined'){
  window.calcClubMonthlySquadWages = calcClubMonthlySquadWages;
  window.totalMonthlyPayroll = totalMonthlyPayroll;
}
function payrollPerRound(){
  return Math.round(totalMonthlyPayroll() / 4);
}

function roundRobin(teamNames){let a=[...teamNames];if(a.length%2)a.push('FOLGA');const n=a.length,rounds=[];for(let r=0;r<n-1;r++){const games=[];for(let i=0;i<n/2;i++){const x=a[i],y=a[n-1-i];if(x!=='FOLGA'&&y!=='FOLGA')games.push(r%2?[y,x]:[x,y])}rounds.push(games);a=[a[0],a[n-1],...a.slice(1,n-1)]}return rounds.concat(rounds.map(rd=>rd.map(([h,a])=>[a,h])))}
function roundRobinSingleLeg(teamNames){const a0=[...teamNames];if(a0.length%2)a0.push('FOLGA');const n=a0.length,rounds=[],a=[...a0];for(let r=0;r<n-1;r++){const games=[];for(let i=0;i<n/2;i++){const x=a[i],y=a[n-1-i];if(x!=='FOLGA'&&y!=='FOLGA')games.push(r%2?[y,x]:[x,y])}rounds.push(games);a.splice(1,0,a.pop())}return rounds}
function leaguePhaseSchedule(teamNames,rounds=8){const out=[],seen=new Set();for(let r=0;r<rounds;r++){const used=new Set(),games=[],order=[...teamNames].sort(()=>Math.random()-.5);for(const t of order){if(used.has(t))continue;let opp=order.find(x=>x!==t&&!used.has(x)&&!seen.has([t,x].sort().join('|')));if(!opp)opp=order.find(x=>x!==t&&!used.has(x));if(!opp)continue;used.add(t);used.add(opp);seen.add([t,opp].sort().join('|'));games.push(r%2?[opp,t]:[t,opp])}out.push(games)}return out}
function groupSchedule(teamNames,size=4,homeAway=true){const groups=[];for(let i=0;i<teamNames.length;i+=size)groups.push(teamNames.slice(i,i+size));const groupRounds=groups.map(g=>homeAway?roundRobin(g):roundRobinSingleLeg(g));const max=Math.max(0,...groupRounds.map(x=>x.length)),out=[];for(let r=0;r<max;r++)out.push(groupRounds.flatMap(g=>g[r]||[]));return out}
function firstKnockoutRound(teamNames){const a=[...teamNames].sort(()=>Math.random()-.5),games=[];for(let i=0;i<a.length;i+=2)if(a[i+1])games.push([a[i],a[i+1]]);return [games]}
function buildSchedule(comp,teamNames){if(comp.type==='knockout')return firstKnockoutRound(teamNames);if(comp.type==='league-phase'||comp.type==='continental-league')return leaguePhaseSchedule(teamNames,comp.rounds||8);if(comp.id==='bra-d')return groupSchedule(teamNames,24,false);if(comp.type.includes('groups')||comp.type==='continental-groups')return groupSchedule(teamNames,comp.groupSize||4).slice(0,comp.rounds||999);const rr=roundRobin(teamNames);return comp.rounds?rr.slice(0,Math.min(comp.rounds,rr.length)):rr}

function defaultInfrastructure(club){
  const s=strength(club);const cap=clamp(Math.round((8000+(s-55)*1400)/1000)*1000,8000,65000);
  // shortcut: capacity remains estimated until verified seat counts are added to each club profile.
  const stadiumLevel = cap <= 14000 ? 1 : cap <= 30640 ? 2 : cap <= 49000 ? 3 : cap <= 72160 ? 4 : cap <= 90000 ? 5 : 6;
  return {
    stadium:{level:stadiumLevel,capacity:cap},
    parking:{level:0,spots:0},
    training:{level:1},academy:{level:1},medical:{level:1},admin:{level:1},store:{level:1},museum:{level:1},press:{level:1},marketing:{level:1},bank:{level:1}
  };
}

// -------------------------------------------------------------
// CATEGORIA DE BASE (JUNIORES - 15 A 18 ANOS)
// -------------------------------------------------------------
function generateYouthPlayer(academyLevel=1, fixedAge=null, fixedPos=null){
  const lvl = clamp(Number(academyLevel) || 1, 1, 8);
  // Idade estritamente entre 15 e 18 anos conforme especificado
  const age = fixedAge ? clamp(Math.round(fixedAge), 15, 18) : rnd(15, 18);
  const pos = fixedPos || POSITIONS[rnd(0, POSITIONS.length - 1)];
  const firstName = NAMES[rnd(0, NAMES.length - 1)];
  const lastName = LAST[rnd(0, LAST.length - 1)];
  const name = `${firstName} ${lastName}`;

  // Quanto maior o nível da Categoria de Base, maior o Overall e Potencial gerado
  const baseOvr = Math.round(clamp(53 + (lvl * 3.0) + (Math.random() * 6 - 2), 52, 84));
  const basePot = Math.round(clamp(baseOvr + 10 + (lvl * 1.5) + (Math.random() * 6), baseOvr + 5, 96));

  const id = `youth-${Date.now()}-${rnd(100, 9999)}`;
  const p = {
    id,
    marketKey: `youth:${id}`,
    name,
    club: state?.club || 'Clube',
    country: 'Brasil',
    pos,
    age,
    fc: baseOvr,
    pes: baseOvr,
    potential: basePot,
    morale: 80,
    fitness: 100,
    isYouth: true,
    value: 0
  };
  p.value = calcValueMi(p);
  return p;
}

const YOUTH_ACADEMY_CAPACITY = 15;

function normalizeYouthAcademyRoster(saveState=state){
  if(!saveState) return [];
  if(!Array.isArray(saveState.youthAcademy)) saveState.youthAcademy = [];
  if(!Array.isArray(saveState.youthAcademyOverflow)) saveState.youthAcademyOverflow = [];
  if(saveState.youthAcademy.length > YOUTH_ACADEMY_CAPACITY){
    saveState.youthAcademyOverflow.push(...saveState.youthAcademy.splice(YOUTH_ACADEMY_CAPACITY));
  }
  normalizeYouthAcademyPositions(saveState);
  return saveState.youthAcademy;
}

function resolveRegenOrYouthPosition(p){
  if(!p || typeof p !== "object") return "CM";
  const posVal = String(p.pos || p.position || p.primaryPosition || "").trim();
  if(posVal && posVal !== "-" && posVal !== "undefined" && posVal !== "null"){
    const n = typeof normTacticalPos === "function" ? normTacticalPos(posVal) : posVal.toUpperCase();
    if(n && n !== "-") return n;
  }

  const searchStr = `${p.name || ""} ${p.regenOf || ""} ${p.geneticOrigin || ""}`.toLowerCase();
  if(searchStr.includes("virgil") || searchStr.includes("dijk") || searchStr.includes("marquinhos") || searchStr.includes("silva") || searchStr.includes("ramos") || searchStr.includes("milit") || searchStr.includes("zagueiro")) return "CB";
  if(searchStr.includes("manuel") || searchStr.includes("neuer") || searchStr.includes("alisson") || searchStr.includes("ederson") || searchStr.includes("courtois") || searchStr.includes("goleiro")) return "GK";
  if(searchStr.includes("cristiano") || searchStr.includes("ronaldo") || searchStr.includes("luis") || searchStr.includes("suarez") || searchStr.includes("haaland") || searchStr.includes("lewandowski") || searchStr.includes("kane") || searchStr.includes("benzema") || searchStr.includes("centroavante")) return "ST";
  if(searchStr.includes("lionel") || searchStr.includes("messi") || searchStr.includes("salah") || searchStr.includes("rodrygo") || searchStr.includes("saka") || searchStr.includes("ponta d")) return "RW";
  if(searchStr.includes("neymar") || searchStr.includes("vinicius") || searchStr.includes("mbappe") || searchStr.includes("diaz") || searchStr.includes("ponta e")) return "LW";
  if(searchStr.includes("modric") || searchStr.includes("kroos") || searchStr.includes("bruyne") || searchStr.includes("bellingham") || searchStr.includes("meia")) return "CM";
  if(searchStr.includes("casemiro") || searchStr.includes("rodri") || searchStr.includes("kante") || searchStr.includes("volante")) return "DM";
  if(searchStr.includes("davies") || searchStr.includes("robertson") || searchStr.includes("arana") || searchStr.includes("lateral esquerdo")) return "LB";
  if(searchStr.includes("walker") || searchStr.includes("carvajal") || searchStr.includes("hakimi") || searchStr.includes("arnold") || searchStr.includes("lateral direito")) return "RB";

  return "CM";
}
if(typeof window !== "undefined") window.resolveRegenOrYouthPosition = resolveRegenOrYouthPosition;

function normalizeYouthAcademyPositions(saveState, startIndex=0){
  const positions = ["GK", "CB", "LB", "RB", "DM", "CM", "AM", "RW", "LW", "ST"];
  const players = [...(saveState?.youthAcademy || []), ...(saveState?.youthAcademyOverflow || [])];
  players.forEach((player, index) => {
    if(!player || typeof player !== "object") return;
    let normalizedPos = "";
    const sourcePos = String(player.pos || "").trim() || String(player.position || "").trim() || player.primaryPosition;
    if (sourcePos && sourcePos !== "-" && sourcePos !== "undefined" && sourcePos !== "null") {
      normalizedPos = typeof normTacticalPos === "function" ? normTacticalPos(sourcePos) : sourcePos.toUpperCase();
    }
    if (!normalizedPos || normalizedPos === "-") {
      normalizedPos = resolveRegenOrYouthPosition(player);
    }
    player.pos = positions.includes(normalizedPos) ? normalizedPos : (normalizedPos || positions[(startIndex + index) % positions.length]);
    player.position = player.pos;
  });
}

function addYouthAcademyPlayer(player, saveState=state){
  const roster = normalizeYouthAcademyRoster(saveState);
  if(!player || roster.length >= YOUTH_ACADEMY_CAPACITY) return false;
  normalizeYouthAcademyPositions({ youthAcademy: [player], youthAcademyOverflow: [] }, roster.length);
  roster.unshift(player);
  return true;
}

function restoreYouthAcademyOverflow(saveState=state){
  const roster = normalizeYouthAcademyRoster(saveState);
  const overflow = saveState?.youthAcademyOverflow || [];
  const available = YOUTH_ACADEMY_CAPACITY - roster.length;
  if(available <= 0 || !overflow.length) return 0;
  const restored = overflow.splice(0, available);
  roster.push(...restored);
  return restored.length;
}

function generateInitialYouthAcademy(academyLevel=1, clubName=null){
  const club = clubName || state?.club || 'Clube';
  const positions = ['GK', 'CB', 'LB', 'RB', 'DM', 'CM', 'RW', 'LW', 'ST'];
  const players = [];
  const count = 7;
  for(let i = 0; i < count; i++){
    const pos = positions[i % positions.length];
    const age = 15 + (i % 4); // 15, 16, 17, 18 anos estritamente
    const p = generateYouthPlayer(academyLevel, age, pos);
    p.club = club;
    players.push(p);
  }
  return players;
}

function boostYouthAcademyOnUpgrade(newLevel){
  normalizeYouthAcademyRoster(state);
  state.youthAcademy.forEach(p => {
    p.potential = clamp((p.potential || playerOverall(p)) + 2, playerOverall(p) + 4, 96);
  });
  const topProspect = generateYouthPlayer(newLevel, rnd(15, 16));
  topProspect.potential = Math.min(96, topProspect.potential + 4);
  const joined = addYouthAcademyPlayer(topProspect, state);
  state.news.unshift(joined
    ? `🌱 A Categoria de Base foi ampliada para o Nível ${newLevel}! O jovem prodígio ${topProspect.name} (${topProspect.pos}, ${topProspect.age} anos, POT ${topProspect.potential}) ingressou na base.`
    : `🌱 A Categoria de Base foi ampliada para o Nível ${newLevel}, mas ${topProspect.name} não ingressou porque as 15 vagas estão ocupadas.`);
}

function processYouthDevelopment(){
  if(!Array.isArray(state.youthAcademy)) return;
  const acadLvl = state.infrastructure?.academy?.level || 1;
  const trainLvl = state.infrastructure?.training?.level || 1;

  for(const p of state.youthAcademy){
    p.age = clamp(Number(p.age) || 16, 15, 18);
    const pot = p.potential || (playerOverall(p) + 8);
    const ovr = playerOverall(p);
    if(ovr < pot){
      const chance = 18 + acadLvl * 6 + trainLvl * 2;
      if((hashStr(playerKey(p) + '|' + state.round) % 100) < chance){
        p.fc = clamp(ovr + 1, 45, pot);
        p.pes = p.fc;
        p.value = calcValueMi(p);
      }
    }
    p.fitness = 100;
    p.morale = clamp((p.morale || 75) + rnd(1, 3), 60, 100);
  }
}


function parkingSpots(lvl){
  const table = [0, 300, 1000, 2500, 5000, 10000];
  return table[lvl] || (lvl * 2000);
}

function recommendedTicketPrice(){const st=state||window.state||{};const c=clubByName(st.club);return Math.round(clamp(18+(strength(c)-58)*1.7,15,130))}
function formationSlots(){const st=state||window.state||{};return FORMATIONS[st.formation]||FORMATIONS['4-3-3']}

// =========================================================================
// MATRIZ DE APTIDÃO TÁTICA (getPositionFit) — AFM MANAGER 2027
// =========================================================================
function getPositionFit(playerRole, slotRole){
  if(!playerRole || !slotRole) return 'INCOMPATÍVEL';
  const rawP = String(playerRole).split(',')[0].trim().toUpperCase();
  const rawS = String(slotRole).trim().toUpperCase();
  const p = typeof normTacticalPos === 'function' ? normTacticalPos(rawP) : rawP;
  const s = typeof normTacticalPos === 'function' ? normTacticalPos(rawS) : rawS;

  // NOTA: Goleiro (GK) NUNCA é adaptado em posição de linha e vice-versa.
  if(p === 'GK' || s === 'GK'){
    return (p === 'GK' && s === 'GK') ? 'IDEAL' : 'INCOMPATÍVEL';
  }

  // 1. 'IDEAL' (Posição de Origem): Exata mesma posição
  if(p === s) return 'IDEAL';

  // 2. 'ADAPTADA' (Posição Secundária / Compatível):
  const adaptedMap = {
    // Zagueiro (CB) em Lateral (LB/RB) ou Volante (DM)
    CB: ['LB', 'RB', 'DM'],
    // Lateral (LB/RB) em Ponta (LW/RW) ou Meia Aberto (LM/RM) ou outro lado
    LB: ['RB', 'LW', 'LM', 'CB'],
    RB: ['LB', 'RW', 'RM', 'CB'],
    // Volante (DM) em Zagueiro (CB) ou Meia Central (CM)
    DM: ['CB', 'CM'],
    // Meia Central (CM) em Volante (DM) ou Meia Armador (AM)
    CM: ['DM', 'AM', 'LM', 'RM'],
    // Meia Armador (AM) em Ponta (LW/RW) ou Meia Central (CM)
    AM: ['LW', 'RW', 'CM', 'CF'],
    // Ponta (LW/RW) em Segundo Atacante / Meia Aberto / Centroavante
    LW: ['RW', 'LM', 'AM', 'ST', 'CF'],
    RW: ['LW', 'RM', 'AM', 'ST', 'CF'],
    // Meias abertos (LM/RM)
    LM: ['LW', 'LB', 'CM', 'AM', 'RM'],
    RM: ['RW', 'RB', 'CM', 'AM', 'LM'],
    // Centroavante (ST/CF) em Segundo Atacante / Ponta
    ST: ['CF', 'LW', 'RW', 'AM'],
    CF: ['ST', 'LW', 'RW', 'AM']
  };

  if(adaptedMap[p]?.includes(s) || adaptedMap[s]?.includes(p)){
    return 'ADAPTADA';
  }

  return 'INCOMPATÍVEL';
}
window.getPositionFit = getPositionFit;

function compatibleScore(p, role){
  const rawP = String(p?.pos || '').trim().toUpperCase();
  const rawS = String(role || '').trim().toUpperCase();
  if(!rawP || !rawS) return 0;
  const pPos = typeof normTacticalPos === 'function' ? normTacticalPos(rawP) : rawP;
  const sRole = typeof normTacticalPos === 'function' ? normTacticalPos(rawS) : rawS;
  if(pPos === sRole) return 0;

  // Goleiro na linha ou jogador de linha no gol: penalidade controlada (-8)
  if(sRole === 'GK' && pPos !== 'GK') return -8;
  if(sRole !== 'GK' && pPos === 'GK') return -8;

  const fit = getPositionFit(pPos, sRole);
  if(fit === 'IDEAL' || fit === 'best') return 0;
  if(fit === 'ADAPTADA' || fit === 'ok') return -3;
  return -6; // Posição fora da origem cai um pouco (-6)
}

function getPlayerEffectiveOverall(p, role){
  const base = typeof playerOverall === 'function' ? playerOverall(p) : (p?.overall || 60);
  if(!p || !role) return base;
  const penalty = compatibleScore(p, role);
  return Math.max(45, Math.min(99, base + penalty));
}
window.getPlayerEffectiveOverall = getPlayerEffectiveOverall;
window.compatibleScore = compatibleScore;

// =========================================================================
// RENDERIZAÇÃO DO CAMPO VERTICAL FIXO (renderVerticalTacticsPitch)
// =========================================================================
function formatPedestalRole(role) {
  if (!role) return 'ST';
  const r = String(role).toUpperCase().trim();
  const map = {
    'GK': 'GL', 'GOL': 'GL', 'GOAL': 'GL',
    'CB': 'ZAG', 'DF': 'ZAG',
    'LB': 'LE', 'LWB': 'LE',
    'RB': 'LD', 'RWB': 'LD',
    'CDM': 'VOL', 'DM': 'VOL',
    'CM': 'MC', 'MF': 'MC',
    'CAM': 'MEI', 'AM': 'MEI',
    'LM': 'ME',
    'RM': 'MD',
    'LW': 'PE',
    'RW': 'PD',
    'ST': 'ATA', 'CF': 'ATA', 'FW': 'ATA'
  };
  return map[r] || r;
}
window.formatPedestalRole = formatPedestalRole;


function formatTacticalPedestalRole(posRole, roleDef) {
  const pos = formatPedestalRole(posRole);
  const rName = roleDef?.name || roleDef?.role || '';
  let clean = rName
    .split('/')[0]
    .replace(/\s*\([^)]*\)/g, '')
    .replace(/^Goleiro\s+/i, '')
    .replace(/^Zagueiro\s+/i, '')
    .replace(/^Lateral\s+/i, '')
    .replace(/^Meia\s+/i, '')
    .replace(/^Atacante\s+/i, '')
    .replace(/^Volante\s+/i, '')
    .replace(/^Ponta\s+/i, '')
    .replace(/^Extremo\s+/i, '')
    .replace(/^Centroavante\s+/i, '')
    .replace(/^Homem\s+de\s+/i, '')
    .replace(/^Camisa\s+10\s+/i, '')
    .trim();

  if (/Primeiro\s+Volante/i.test(rName)) clean = '1º Volante';
  else if (/Ponta\s+Agudo/i.test(rName)) clean = 'Ponta Agudo';
  else if (/Box-to-Box/i.test(rName)) clean = 'Box-to-Box';
  else if (/Falso\s+Nove/i.test(rName)) clean = 'Falso 9';
  else if (/Centroavante\s+Alvo/i.test(rName)) clean = 'Pivô';
  else if (/Homem\s+de\s+Área/i.test(rName) || /Oportunista/i.test(rName)) clean = 'Área';
  else if (/Armador\s+Recuado/i.test(rName)) clean = 'Armador Rec.';
  else if (/Criador/i.test(rName)) clean = 'Armador';
  else if (/Shadow\s+Striker/i.test(rName)) clean = '2º Atacante';

  if (!clean) clean = pos;
  return { pos, shortName: clean, fullName: rName || pos };
}
window.formatTacticalPedestalRole = formatTacticalPedestalRole;

function renderVerticalTacticsPitch(starters = [], formationName = '4-3-3', opts = {}){
  const formSlots = FORMATIONS[formationName] || FORMATIONS['4-3-3'];
  const isHalftime = !!opts.isHalftime;
  const selectedKey = opts.selectedStarterKey || null;
  const clubName = state?.club || 'MEU CLUBE';
  const fallbackUrl = "img/players/default_avatar.svg";

  // Cálculo de Avaliação Média da Equipe e Entrosamento Total (Max 33)
  let totalOvr = 0;
  let totalChem = 0;
  let startersWithPlayer = 0;
  let inspectPlayer = null;
  let inspectSlotRole = 'ST';

  formSlots.forEach((slot, idx) => {
    const p = starters[idx] || null;
    if (p) {
      startersWithPlayer++;
      const slotRole = slot.r || (p.pos || 'ST');
      const pOvr = typeof getPlayerEffectiveOverall === 'function' ? getPlayerEffectiveOverall(p, slotRole) : (typeof playerOverall === 'function' ? playerOverall(p) : (p.overall || 60));
      totalOvr += pOvr;
      const fit = typeof getPositionFit === 'function' ? getPositionFit(p.pos, slotRole) : (p.pos === slotRole ? 'IDEAL' : 'ADAPTADA');
      totalChem += fit === 'IDEAL' ? 3 : (fit === 'ADAPTADA' ? 2 : 1);

      const pk = opts.isHalftime && p.key ? p.key : (typeof playerKey === 'function' ? playerKey(p) : (p.id || p.name));
      if (selectedKey && pk === selectedKey) {
        inspectPlayer = p;
        inspectSlotRole = slotRole;
      }
    }
  });

  const teamAvgOvr = startersWithPlayer > 0 ? Math.round(totalOvr / startersWithPlayer) : 78;
  const squadChem = Math.min(33, totalChem);

  // Jogador em destaque no HUD direito
  if (!inspectPlayer) {
    inspectPlayer = starters.find(Boolean) || null;
    inspectSlotRole = formSlots[0]?.r || 'ST';
  }
  const inspectOvr = inspectPlayer ? (typeof playerOverall === 'function' ? playerOverall(inspectPlayer) : (inspectPlayer.overall || 75)) : '-';
  const inspectShortName = inspectPlayer ? (inspectPlayer.name.split(' ').pop() || inspectPlayer.name).toUpperCase() : 'ESCALAÇÃO';
  const inspectPos = inspectPlayer ? (inspectPlayer.pos || inspectSlotRole) : '-';
  const inspectPhoto = inspectPlayer ? (resolvePlayerPhotoUrl(inspectPlayer) || fallbackUrl) : fallbackUrl;

  return `
    <!-- Ambiência 3D do Topo do Estádio (Refletores & Arquibancadas) -->
    <div class="fut-stadium-top-ambience">
      <div class="stadium-skyline"></div>
      <div class="stadium-floodlights">
        <div class="floodlight fl-left-1"><div class="fl-flare"></div><div class="fl-beam"></div></div>
        <div class="floodlight fl-left-2"><div class="fl-flare"></div><div class="fl-beam"></div></div>
        <div class="floodlight fl-right-1"><div class="fl-flare"></div><div class="fl-beam"></div></div>
        <div class="floodlight fl-right-2"><div class="fl-flare"></div><div class="fl-beam"></div></div>
      </div>
      <div class="stadium-crowd-silhouette"></div>
    </div>

    <!-- Marcações Oficiais do Gramado -->
    <div class="pitch-lines">
      <div class="pitch-half-line"></div>
      <div class="pitch-center-circle"></div>
      <div class="pitch-center-spot"></div>
      <div class="pitch-penalty-top"></div>
      <div class="pitch-goal-area-top"></div>
      <div class="pitch-penalty-bottom"></div>
      <div class="pitch-goal-area-bottom"></div>
    </div>

    <!-- Rede do Gol 3D no Fundo (Atrás do Goleiro) -->
    <div class="pitch-goal-3d-bottom">
      <svg class="goal-net-mesh" viewBox="0 0 240 60" preserveAspectRatio="none">
        <defs>
          <pattern id="futNetPattern" width="10" height="10" patternUnits="userSpaceOnUse">
            <path d="M 0 0 L 10 10 M 10 0 L 0 10" stroke="rgba(255,255,255,0.4)" stroke-width="0.8" fill="none"/>
          </pattern>
        </defs>
        <polygon points="20,0 220,0 240,60 0,60" fill="url(#futNetPattern)" stroke="rgba(255,255,255,0.7)" stroke-width="1.5"/>
        <line x1="20" y1="0" x2="220" y2="0" stroke="#ffffff" stroke-width="2.5"/>
      </svg>
    </div>

    <!-- HUD Superior Esquerdo: Informações do Clube, Rating e Entrosamento 33/33 (Apenas em tela cheia fora de jogo) -->
    ${!isHalftime ? `
    <div class="fut-pitch-hud-left">
      <div class="fut-hud-badge-wrap">
        ${typeof clubBadge === 'function' ? clubBadge(clubName, 26) : ''}
      </div>
      <div class="fut-hud-info">
        <div class="fut-hud-team-name">${esc(clubName)}</div>
        <div class="fut-hud-stars">
          <span class="stars-gold">★★★★★</span>
          <span class="hud-ovr-val">${teamAvgOvr}</span>
          <span class="hud-ovr-lbl">RATING</span>
        </div>
        <div class="fut-hud-chem-row">
          <span class="chem-icon">◆</span>
          <span class="chem-val">${squadChem}</span>
          <span class="chem-max">/ 33</span>
          <span class="chem-lbl">ENTROSAMENTO</span>
        </div>
      </div>
    </div>
    ` : ''}

    <!-- Slots dos Jogadores no Gramado -->
    ${formSlots.map((slot, idx) => {
      const p = starters[idx] || null;
      const pk = p ? (opts.isHalftime && p.key ? p.key : (typeof playerKey === 'function' ? playerKey(p) : (p.id || p.name))) : '';
      const isSelected = selectedKey && pk && (selectedKey === pk);
      const slotRole = slot.r || (p?.pos || 'ST');
      const posX = slot.x;
      const posY = slot.y;

      const fit = p ? (typeof getPositionFit === 'function' ? getPositionFit(p.pos, slotRole) : (p.pos === slotRole ? 'IDEAL' : 'ADAPTADA')) : 'IDEAL';
      const chemScore = !p ? 0 : (fit === 'IDEAL' ? 3 : (fit === 'ADAPTADA' ? 2 : 1));
      const pedestalRole = formatPedestalRole(slotRole);

      const slotSavedRole = (pk && state?.tactics?.playerRoles?.[pk]?.roleId) || (p?.name && state?.tactics?.playerRoles?.[p.name]?.roleId);
      const slotRoleDef = getPlayerRoleDef(slotRole, slotSavedRole);
      const slotFocus = (pk && state?.tactics?.playerRoles?.[pk]?.focus) || slotRoleDef.focus || 'Balanced';

      return `
        <div class="pitch-slot-dropzone ${isSelected ? 'selected' : ''}"
             id="pitchSlot_${idx}"
             style="left:${posX}%;top:${posY}%;"
             data-slot-index="${idx}"
             data-slot-role="${esc(slotRole)}"
             data-player-key="${esc(pk)}"
             title="${p ? `${esc(p.name)} (${esc(p.pos)}) • Função: ${esc(slotRoleDef.name || slotRole)} (${esc(slotFocus)})` : 'Slot Vazio'}">
          ${renderFifaMiniCard(p, { index: idx, role: slotRole, x: 50, y: 50 }, {
            isSelected: isSelected,
            isHalftime: isHalftime,
            customClass: 'slot-card-inner',
            roleDef: slotRoleDef
          })}
          <!-- Brackets de Mira Ciano Estilo EA FC (Ativo ao Selecionar) -->
          <div class="fut-target-brackets">
            <span class="tb tb-tl"></span>
            <span class="tb tb-tr"></span>
            <span class="tb tb-bl"></span>
            <span class="tb tb-br"></span>
          </div>
          ${!isHalftime ? `
            <!-- Pedestal Oval com Posição, Função Tática e Diamantes de Entrosamento -->
            <div class="pitch-slot-pedestal ${isSelected ? 'selected' : ''}">
              ${(() => {
                const roleInfo = formatTacticalPedestalRole(slotRole, slotRoleDef);
                return `
                  <div style="display:flex;flex-direction:column;align-items:center;line-height:1.15;gap:1px;">
                    <div class="pedestal-role-line" title="${esc(roleInfo.pos)} • ${esc(roleInfo.fullName)}">
                      <span style="font-size:8.5px;font-weight:900;color:#ffffff;letter-spacing:0.3px;">${esc(roleInfo.pos)}</span>
                      <span style="color:rgba(255,255,255,0.4);font-size:7px;">•</span>
                      <span style="font-size:8px;font-weight:800;color:#38bdf8;">${esc(roleInfo.shortName)}</span>
                    </div>
                    <div style="display:inline-flex;align-items:center;gap:4px;">
                      <span class="pedestal-focus" style="font-size:7px;color:#c084fc;font-weight:800;letter-spacing:0.3px;text-transform:uppercase;">${esc(slotFocus)}</span>
                      <div class="pedestal-chem" style="display:inline-flex;gap:1.5px;font-size:6.5px;" title="Entrosamento: ${chemScore}/3">
                        <span class="chem-diamond ${chemScore >= 1 ? 'active' : ''}">◆</span>
                        <span class="chem-diamond ${chemScore >= 2 ? 'active' : ''}">◆</span>
                        <span class="chem-diamond ${chemScore >= 3 ? 'active' : ''}">◆</span>
                      </div>
                    </div>
                  </div>
                `;
              })()}
            </div>
          ` : `
            <div class="pitch-slot-pedestal-mini" style="font-size:8px;font-weight:900;color:#38bdf8;background:rgba(15,23,42,0.9);padding:1px 5px;border-radius:4px;margin-top:2px;white-space:nowrap;border:1px solid rgba(56,189,248,0.3);letter-spacing:0.3px">
              ${esc(formatPedestalRole(slotRole))}
            </div>
          `}
        </div>
      `;
    }).join('')}
  `;
}
window.renderVerticalTacticsPitch = renderVerticalTacticsPitch;

// =========================================================================
// MANIPULADORES DE EVENTO DE ARRASTE E CLIQUE (setupTacticsInteractions)
// =========================================================================
function setupTacticsInteractions({ containerEl, starters, bench, onSwap, onStarterSwap, isHalftime }){
  if(!containerEl) return;

  const keyOf = p => isHalftime && p?.key ? p.key : (typeof playerKey === 'function' ? playerKey(p) : p?.key);

  let selectedStarterKey = null;
  let selectedStarterIndex = null;
  let selectedBenchKey = null;

  function clearVisualHighlights(){
    if(window.__afmDragState) window.__afmDragState = { starterKey: null, benchKey: null };
    const slots = containerEl.querySelectorAll('.pitch-slot-dropzone');
    slots.forEach(s => {
      s.classList.remove('selected', 'slot-ideal', 'slot-adapted', 'slot-incompatible', 'slot-dimmed', 'drag-over', 'drag-target');
    });
    const benchRows = containerEl.querySelectorAll('.bench-player-row');
    benchRows.forEach(b => {
      b.classList.remove('selected', 'bench-ideal', 'bench-adapted', 'bench-incompatible', 'drag-over', 'drag-target');
      b.style.borderColor = '';
      b.style.boxShadow = '';
      b.style.background = '';
      b.style.opacity = '1';
    });
  }

  function highlightSlotsForBench(playerPos){
    if(!playerPos) return;
    const slots = containerEl.querySelectorAll('.pitch-slot-dropzone');
    slots.forEach(slot => {
      const slotRole = slot.dataset.slotRole;
      const fit = (typeof getPositionFit === 'function') ? getPositionFit(playerPos, slotRole) : 'IDEAL';
      slot.classList.remove('slot-ideal', 'slot-adapted', 'slot-incompatible', 'slot-dimmed');
      if(fit === 'IDEAL'){
        slot.classList.add('slot-ideal');
      } else if(fit === 'ADAPTADA'){
        slot.classList.add('slot-adapted');
      } else {
        slot.classList.add('slot-incompatible');
      }
    });
  }

  function highlightBenchForStarter(slotRole){
    if(!slotRole) return;
    const benchRows = containerEl.querySelectorAll('.bench-player-row');
    benchRows.forEach(row => {
      const pPos = row.dataset.playerPos;
      const fit = (typeof getPositionFit === 'function') ? getPositionFit(pPos, slotRole) : 'IDEAL';
      row.classList.remove('bench-ideal', 'bench-adapted', 'bench-incompatible');
      if(fit === 'IDEAL'){
        row.classList.add('bench-ideal');
        row.style.borderColor = 'rgba(34, 197, 94, 0.6)';
      } else if(fit === 'ADAPTADA'){
        row.classList.add('bench-adapted');
        row.style.borderColor = 'rgba(234, 179, 8, 0.6)';
      } else {
        row.classList.add('bench-incompatible');
        row.style.borderColor = 'rgba(239, 68, 68, 0.4)';
      }
    });
  }

  // 1. Configurar Slots do Campo (Interação 100% por Clique)
  const slots = containerEl.querySelectorAll('.pitch-slot-dropzone');
  slots.forEach(slot => {
    slot.removeAttribute('draggable');
    slot.ondragenter = null;
    slot.ondragover = null;
    slot.ondragleave = null;
    slot.ondrop = null;
    slot.ondragstart = null;
    slot.ondragend = null;

    slot.onclick = (e) => {
      e.stopPropagation();
      const sKey = slot.dataset.playerKey || '';
      const slotIndex = Number(slot.dataset.slotIndex);

      // CASO A: Reserva já estava selecionado -> Substituição imediata (Reserva ➔ Titular)!
      if(selectedBenchKey){
        const bKey = selectedBenchKey;
        selectedBenchKey = null;
        selectedStarterKey = null;
        selectedStarterIndex = null;
        clearVisualHighlights();
        if(typeof onSwap === 'function'){
          onSwap(sKey, bKey, slotIndex);
        }
        return;
      }

      // CASO B: Outro titular já estava selecionado -> Inverte posições entre titulares!
      if(Number.isInteger(selectedStarterIndex) && selectedStarterIndex !== slotIndex){
        const prevKey = selectedStarterKey;
        const prevIdx = selectedStarterIndex;
        selectedStarterKey = null;
        selectedStarterIndex = null;
        clearVisualHighlights();
        if(typeof onStarterSwap === 'function'){
          onStarterSwap(prevKey, sKey, prevIdx, slotIndex);
        }
        return;
      }

      // CASO C: Mesmo titular clicado novamente -> Desseleciona!
      if(Number.isInteger(selectedStarterIndex) && selectedStarterIndex === slotIndex){
        selectedStarterKey = null;
        selectedStarterIndex = null;
        clearVisualHighlights();
        return;
      }

      // CASO D: Seleciona este titular
      selectedStarterKey = sKey;
      selectedStarterIndex = slotIndex;
      selectedBenchKey = null;
      clearVisualHighlights();
      slot.classList.add('selected');

      const slotRole = slot.dataset.slotRole || 'ST';
      highlightBenchForStarter(slotRole);

      const stPlayer = (starters || []).find((p, idx) => idx === slotIndex || keyOf(p) === sKey);
      toast(`👉 Titular selecionado: ${stPlayer?.name || 'Posição ' + (slotIndex + 1)} (${slotRole}). Clique em um reserva para trocar ou em outro titular para inverter.`);
    };
  });

  // 2. Configurar Linhas do Banco de Reservas (Interação 100% por Clique)
  const benchRows = containerEl.querySelectorAll('.bench-player-row');
  benchRows.forEach(row => {
    row.removeAttribute('draggable');
    row.ondragstart = null;
    row.ondragend = null;
    row.ondragenter = null;
    row.ondragover = null;
    row.ondragleave = null;
    row.ondrop = null;

    row.onclick = (e) => {
      e.stopPropagation();
      const bKey = row.dataset.benchKey;
      const bPos = row.dataset.playerPos;

      // CASO A: Titular já estava selecionado no campo -> Substituição imediata (Titular ➔ Reserva)!
      if(Number.isInteger(selectedStarterIndex) || selectedStarterKey){
        const sKey = selectedStarterKey;
        const targetSlotIndex = selectedStarterIndex;
        selectedStarterKey = null;
        selectedStarterIndex = null;
        selectedBenchKey = null;
        clearVisualHighlights();
        if(typeof onSwap === 'function'){
          onSwap(sKey, bKey, targetSlotIndex);
        }
        return;
      }

      // CASO B: Mesmo reserva clicado novamente -> Desseleciona!
      if(selectedBenchKey === bKey){
        selectedBenchKey = null;
        clearVisualHighlights();
        return;
      }

      // CASO C: Seleciona este reserva
      selectedBenchKey = bKey;
      selectedStarterKey = null;
      selectedStarterIndex = null;
      clearVisualHighlights();

      row.classList.add('selected');
      row.style.borderColor = '#fbbf24';
      row.style.boxShadow = '0 0 16px rgba(250, 204, 21, 0.7)';
      row.style.background = 'rgba(250, 204, 21, 0.15)';

      highlightSlotsForBench(bPos);

      const bPlayer = (bench || []).find(p => keyOf(p) === bKey);
      toast(`👉 Reserva selecionado: ${bPlayer?.name || 'Jogador'} (${bPos}). Clique em qualquer vaga no campo para confirmar a troca.`);
    };
  });

  // Clique no container desmarca seleção se não for em slot/linha
  containerEl.onclick = (e) => {
    if(e.target.closest('.pitch-slot-dropzone') || e.target.closest('.bench-player-row')) return;
    selectedStarterKey = null;
    selectedStarterIndex = null;
    selectedBenchKey = null;
    clearVisualHighlights();
  };
}
window.setupTacticsInteractions = setupTacticsInteractions;

// =========================================================================
// ESCALAÇÃO INTELIGENTE (autoPickBestLineup) — AFM 2027
// =========================================================================
function autoPickBestLineup(squad, formationName = state?.formation || '4-3-3'){
  if (!Array.isArray(squad) || squad.length === 0) return [];
  const form = FORMATIONS[formationName] || FORMATIONS['4-3-3'];
  const available = [...squad];
  const chosenKeys = new Array(form.length).fill(null);

  // Mapeamento rígido de preferências por posição tática
  const rolePreferences = {
    GK: { primary: ['GK'], secondary: [] },
    CB: { primary: ['CB'], secondary: ['RB', 'LB', 'DM'] },
    LB: { primary: ['LB'], secondary: ['LWB', 'RB', 'LM', 'CB'] },
    RB: { primary: ['RB'], secondary: ['RWB', 'LB', 'RM', 'CB'] },
    LWB: { primary: ['LB', 'LWB'], secondary: ['LM', 'RB'] },
    RWB: { primary: ['RB', 'RWB'], secondary: ['RM', 'LB'] },
    DM: { primary: ['DM'], secondary: ['CM', 'CB'] },
    CM: { primary: ['CM'], secondary: ['DM', 'AM'] },
    AM: { primary: ['AM'], secondary: ['CM', 'RW', 'LW', 'CF'] },
    LM: { primary: ['LM', 'LW'], secondary: ['LB', 'AM', 'CM'] },
    RM: { primary: ['RM', 'RW'], secondary: ['RB', 'AM', 'CM'] },
    LW: { primary: ['LW', 'LM'], secondary: ['RW', 'ST', 'AM', 'CF'] },
    RW: { primary: ['RW', 'RM'], secondary: ['LW', 'ST', 'AM', 'CF'] },
    ST: { primary: ['ST', 'CF'], secondary: ['RW', 'LW', 'AM'] },
    CF: { primary: ['CF', 'ST'], secondary: ['AM', 'RW', 'LW'] }
  };

  // 1. PRIMEIRA PASSAGEM: Goleiro (REGRA INVIOLÁVEL: apenas goleiro no gol se houver)
  const gkIndex = form.findIndex(slot => slot.r === 'GK');
  if (gkIndex !== -1) {
    const gks = available.filter(p => (p.pos === 'GK') && (!p.suspended || p.suspended <= 0) && (!p.injury));
    const poolGK = gks.length ? gks : available.filter(p => p.pos === 'GK');
    if (poolGK.length) {
      poolGK.sort((a, b) => playerOverall(b) - playerOverall(a));
      const chosenGK = poolGK[0];
      chosenKeys[gkIndex] = playerKey(chosenGK);
      const rmIdx = available.indexOf(chosenGK);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  // 2. SEGUNDA PASSAGEM: Posições de ofício estritas (Primary Match)
  const priorityOrder = ['LB', 'RB', 'LWB', 'RWB', 'CB', 'ST', 'CF', 'LW', 'RW', 'LM', 'RM', 'DM', 'AM', 'CM'];
  const slotIndices = form.map((slot, idx) => ({ idx, role: slot.r }))
    .filter(item => item.role !== 'GK');

  slotIndices.sort((a, b) => {
    const prioA = priorityOrder.indexOf(a.role);
    const prioB = priorityOrder.indexOf(b.role);
    return (prioA === -1 ? 99 : prioA) - (prioB === -1 ? 99 : prioB);
  });

  for (const { idx, role } of slotIndices) {
    if (chosenKeys[idx]) continue;
    const pref = rolePreferences[role] || { primary: [role], secondary: [] };

    // Candidatos aptos (sem suspensão/lesão grave primeiro)
    const candidates = available.filter(p => {
      if (p.pos === 'GK') return false; // NUNCA colocar goleiro na linha
      return pref.primary.includes(p.pos);
    });

    if (candidates.length) {
      candidates.sort((a, b) => {
        const fitA = (a.fitness ?? 100) / 100;
        const fitB = (b.fitness ?? 100) / 100;
        const scoreA = playerOverall(a) * fitA;
        const scoreB = playerOverall(b) * fitB;
        return scoreB - scoreA;
      });
      const best = candidates[0];
      chosenKeys[idx] = playerKey(best);
      const rmIdx = available.indexOf(best);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  // 3. TERCEIRA PASSAGEM: Posições secundárias adaptadas (Secondary Match)
  for (const { idx, role } of slotIndices) {
    if (chosenKeys[idx]) continue;
    const pref = rolePreferences[role] || { primary: [role], secondary: [] };

    const candidates = available.filter(p => {
      if (p.pos === 'GK') return false;
      return pref.secondary.includes(p.pos);
    });

    if (candidates.length) {
      candidates.sort((a, b) => playerOverall(b) - playerOverall(a));
      const best = candidates[0];
      chosenKeys[idx] = playerKey(best);
      const rmIdx = available.indexOf(best);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  // 4. QUARTA PASSAGEM: Vagas restantes preenchidas pelos melhores atletas restantes (evitando GK na linha)
  for (let i = 0; i < form.length; i++) {
    if (!chosenKeys[i] && available.length) {
      const nonGKs = available.filter(p => p.pos !== 'GK');
      const pool = nonGKs.length ? nonGKs : available;
      pool.sort((a, b) => playerOverall(b) - playerOverall(a));
      const best = pool[0];
      chosenKeys[i] = playerKey(best);
      const rmIdx = available.indexOf(best);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  return chosenKeys;
}
window.autoPickBestLineup = autoPickBestLineup;

function optimizeLineup(){
  if (!state?.squad || state.squad.length === 0) return;
  state.lineup = autoPickBestLineup(state.squad, state.formation || '4-3-3');
}

function lineupPlayer(i){const st=state||window.state;const k=st?.lineup?.[i];return (st?.squad||[]).find(p=>playerKey(p)===k)}
function lineupSector(){
  const vals={atk:[],mid:[],def:[]};
  formationSlots().forEach((s,i)=>{
    const p=lineupPlayer(i);
    if(p)vals[s.g].push(Math.max(40,playerOverall(p)+compatibleScore(p,s.r)));
  });
  const avg=a=>a.length?Math.round(a.reduce((x,y)=>x+y,0)/a.length):55;
  return {atk:avg(vals.atk),mid:avg(vals.mid),def:avg(vals.def)};
}
function overallSquad(){const st=state||window.state;if(!st?.squad)return 68;const x=lineupSector();return Math.round((x.atk+x.mid+x.def)/3)}
function teamStrengthByName(name){const st=state||window.state||{};if(norm(name)===norm(st.club))return overallSquad();return (st.teams||[]).find(t=>norm(t.name)===norm(name))?.strength||strength(clubByName(name)||{atk:66,mid:66,def:66})}

