const TRANSFER_WINDOWS = [
  { startMonth: 1, startDay: 1, endMonth: 3, endDay: 1, name: 'Janela de Início de Temporada' },
  { startMonth: 6, startDay: 1, endMonth: 8, endDay: 1, name: 'Janela de Meio de Temporada' }
];

function closeSeasonTransferWindow(saveState = state){
  if(!saveState) return;
  const dateYear = Number(String(saveState.date || saveState.currentDate || '').slice(0, 4));
  saveState.transferWindowClosedForSeason = dateYear || Number(saveState.season) || null;
  saveState.transferWindowActive = false;
  saveState.isPreSeason = false;
  saveState.preSeasonDays = 0;
}

function startSeasonTransferWindow(saveState){
  if(!saveState) return;
  saveState.isPreSeason = true;
  saveState.preSeasonDays = 4;
  saveState.transferWindowActive = true;
  saveState.transferWindowDay = 1;
  saveState.transferWindowHour = 0;
  saveState.transferWindowClosedForSeason = null;
  if(typeof processPendingTransfersOnWindowOpen === 'function'){
    processPendingTransfersOnWindowOpen(saveState);
  }
}

function recoverJanuaryTransferWindow(saveState){
  if(!saveState) return false;
  const savedDate = String(saveState.date || saveState.currentDate || '').slice(0, 10);
  const parts = /^(\d{4})-01-\d{2}$/.exec(savedDate);
  if(!parts || (Number(saveState.round) || 0) > 1) return false;
  const year = Number(parts[1]);
  if(Number(saveState.transferWindowClosedForSeason) === year || saveState.transferWindowActive) return false;

  // Saves antigos não registravam o fechamento deliberado da janela.
  saveState.transferWindowActive = true;
  saveState.transferWindowDay = 1;
  saveState.transferWindowHour = 0;
  if(savedDate === `${year}-01-01`){
    saveState.isPreSeason = true;
    saveState.preSeasonDays = 4;
  }
  saveState.transferWindowSaveRepairKey = `v3-${year}`;
  return true;
}

function getTransferWindowState(){
  if(!state) return { active: false };
  if(state.freeTransferWindow) return { active: true, free: true, text: 'Janela Aberta (Modo Livre)' };
  if(state.transferWindowActive === undefined || (!state.transferWindowActive && state.isPreSeason && Number(state.preSeasonDays) > 0)){
    if(state.isPreSeason && state.preSeasonDays > 0){
      state.transferWindowActive = true;
      state.transferWindowDay = Math.max(1, 5 - state.preSeasonDays);
      state.transferWindowHour = 0;
    } else {
      state.transferWindowActive = false;
    }
  }
  if(state.transferWindowActive){
    if(Number(state.transferWindowHour) >= 24 || Number(state.transferWindowDay) > 4){
      closeSeasonTransferWindow(state);
      return { active: false, text: 'Janela de Transferências Fechada' };
    }
    const day = Math.min(4, Math.max(1, Number(state.transferWindowDay) || 1));
    const hour = Math.min(24, Math.max(0, Number(state.transferWindowHour) || 0));
    const isDeadlineDay = day === 4;
    return {
      active: true,
      day,
      maxDays: 4,
      hour,
      isDeadlineDay,
      text: isDeadlineDay ? `Deadline Day (${String(hour).padStart(2,'0')}:00)` : `Dia ${day} de 4`
    };
  }
  return { active: false, text: 'Janela de Transferências Fechada' };
}

function isTransferWindowOpen(dateStr){
  if(typeof window !== 'undefined' && window.AFM_CALENDAR_HUB && typeof window.AFM_CALENDAR_HUB.getTransferWindowStatus === 'function'){
    return window.AFM_CALENDAR_HUB.getTransferWindowStatus(dateStr).open;
  }
  const st = (typeof state !== 'undefined' && state) ? state : ((typeof window !== 'undefined' && window.state) ? window.state : null);
  if(st && st.freeTransferWindow) return true;
  if(typeof getTransferWindowState === 'function' && getTransferWindowState().active) return true;

  const dStr = dateStr || st?.date || st?.currentDate;
  if(!dStr) return false;
  const parts = String(dStr).split('-');
  if(parts.length < 3) return false;
  const year = parseInt(parts[0], 10);
  const m = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  if(st && Number(st.transferWindowClosedForSeason) === year && m < 6){
    return false;
  }
  // Janela 1 (Verão): 01/01 a 31/03 (inclusive)
  if(m >= 1 && m <= 3){
    return !st || Number(st.transferWindowClosedForSeason) !== year;
  }
  // Janela 2 (Inverno / Meio de ano): 10/07 a 02/09 (inclusive)
  if((m === 7 && day >= 10) || (m === 8) || (m === 9 && day <= 2)){
    return true;
  }
  return false;
}
function _oldIsTransferWindowOpen(dateStr){
  if(state?.freeTransferWindow) return true;
  if(!dateStr) return true;
  const parts = String(dateStr).split('-');
  if(parts.length < 3) return true;
  const m = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);
  if((m === 1) || (m === 2) || (m === 3 && day <= 1)) return true;
  if((m === 6) || (m === 7) || (m === 8 && day <= 1)) return true;
  return false;
}
window.isTransferWindowOpen = isTransferWindowOpen;

function getTransferWindowInfo(dateStr){
  if(typeof window !== 'undefined' && window.AFM_CALENDAR_HUB && typeof window.AFM_CALENDAR_HUB.getTransferWindowStatus === 'function'){
    return window.AFM_CALENDAR_HUB.getTransferWindowStatus(dateStr);
  }
  const st = (typeof state !== 'undefined' && state) ? state : ((typeof window !== 'undefined' && window.state) ? window.state : null);
  if(st?.freeTransferWindow) {
    return { open: true, text: 'Janela Aberta (Modo Livre)', nextOpenDate: 'Sempre Aberto', currentWindow: 'Livre' };
  }
  const dateOpen = isTransferWindowOpen(dateStr);
  if(dateOpen){
    const dStr = dateStr || st?.date || '2026-01-01';
    const m = parseInt(String(dStr).split('-')[1], 10) || 1;
    return {
      open: true,
      text: m <= 3 ? 'Janela de Verão Aberta (01/Jan a 31/Mar)' : 'Janela de Inverno Aberta (10/Jul a 02/Set)',
      nextOpenDate: m <= 3 ? '10/07' : '01/01',
      currentWindow: m <= 3 ? 'Janela de Verão' : 'Janela de Inverno'
    };
  }
  const dateParts = String(dateStr || st?.date || '').split('-').map(Number);
  const year = dateParts[0] || Number(st?.season) || new Date().getFullYear();
  const month = dateParts[1] || 1;
  const nextOpen = month < 7 ? { year, month: 7, day: 10 } : { year: year + 1, month: 1, day: 1 };
  const nextOpenDate = `${String(nextOpen.day).padStart(2,'0')}/${String(nextOpen.month).padStart(2, '0')}/${nextOpen.year}`;
  return { open: false, text: `Janela Fechada (reabre em ${nextOpenDate})`, nextOpenDate, currentWindow: null };
}
function _oldGetTransferWindowInfo(dateStr){
  if(state?.freeTransferWindow) {
    return { open: true, text: 'Janela Aberta (Modo Livre)', nextOpenDate: 'Sempre Aberto', currentWindow: 'Livre' };
  }
  const parts = String(dateStr || '2026-01-01').split('-');
  const m = parseInt(parts[1], 10) || 1;
  const day = parseInt(parts[2], 10) || 1;
  const open = isTransferWindowOpen(dateStr);

  if(open){
    if(m <= 3){
      return { open: true, text: 'Janela Aberta (fecha em 01/03)', nextOpenDate: '01/06', currentWindow: 'Início de Temporada' };
    }
    return { open: true, text: 'Janela Aberta (fecha em 01/08)', nextOpenDate: '01/01', currentWindow: 'Meio de Temporada' };
  } else {
    // Fora da janela: 02/03 -> 31/05 ou 02/08 -> 31/12
    if(m < 6 || (m === 3 && day > 1)){
      return { open: false, text: 'Janela Fechada (reabre em 01/06)', nextOpenDate: '01/06', currentWindow: null };
    }
    return { open: false, text: 'Janela Fechada (reabre em 01/01)', nextOpenDate: '01/01', currentWindow: null };
  }
}
window.getTransferWindowInfo = getTransferWindowInfo;

function teamFameScore(){
  if(!state) return 50;
  let score = 40;
  // Títulos dão enorme prestígio (+12 pts cada)
  score += (state.titles || []).length * 12;
  // Confiança da torcida
  score += ((state.trust?.fans || 70) - 50) * 0.35;
  // Sócios torcedores
  const members = state.socioTorcedor?.members || 1200;
  score += clamp(Math.round(members / 1500), 0, 25);
  // Nível do Departamento de Marketing
  const mktLvl = state.infrastructure?.marketing?.level || 1;
  score += (mktLvl - 1) * 3;
  // Força do elenco e divisão
  const ovr = overallSquad();
  score += clamp((ovr - 60) * 1.2, 0, 25);
  return clamp(Math.round(score), 25, 100);
}

// Fonte única dos multiplicadores de marketing para modal, escritório,
// projeção de público e ofertas comerciais.
function marketingBenefits(weeklyInvestment = state?.marketingWeekly, marketingLevel = state?.infrastructure?.marketing?.level){
  const level = clamp(Math.round(Number(marketingLevel) || 1), 1, FACILITIES.marketing.max);
  const minWeekly = (typeof MARKETING_MINIMUM_WEEKLY !== 'undefined' ? MARKETING_MINIMUM_WEEKLY : 36000);
  const investment = Math.max(minWeekly, Number(weeklyInvestment) || minWeekly);

  // Parcela estrutural equilibrada (nível da sede de marketing: 1 a 8)
  const baseAttLevel = 0.005 * level; // Nível 1: 0.5% ... Nível 4: 2.0% ... Nível 8: 4.0%
  const baseSponLevel = 0.008 * (level - 1); // Nível 1: 0.0% ... Nível 4: 2.4% ... Nível 8: 5.6%

  // Parcela dinâmica de ativação de marca equilibrada e crível:
  const extraInvest = Math.max(0, investment - minWeekly);
  const investAttBoost = 0.005 + (extraInvest / 36000) * 0.0045; // Piso: +0.5% ... escala moderada
  const investSponBoost = 0.015 + (extraInvest / 36000) * 0.0065; // Piso: +1.5% ... escala moderada

  const attendanceBoost = baseAttLevel + investAttBoost;
  const sponsorBoost = baseSponLevel + investSponBoost;

  return {
    level,
    weeklyInvestment: investment,
    monthlyInvestment: investment * 4,
    attendanceBoost,
    attendancePercent: Math.round(attendanceBoost * 100),
    sponsorBoost,
    sponsorPercent: Math.round(sponsorBoost * 100),
    sponsorMultiplier: 1 + sponsorBoost
  };
}

// Espaço do elenco profissional cresce a cada melhoria do Centro de
// Treinamento. Nível 1 começa com 25 vagas; nível 8 chega a 46.
function squadCapacity(trainingLevel = state?.infrastructure?.training?.level){
  const level = clamp(Math.round(Number(trainingLevel) || 1), 1, FACILITIES.training.max);
  return 25 + ((level - 1) * 3);
}
if(typeof window !== 'undefined') window.squadCapacity = squadCapacity;


// =========================================================================
// SISTEMA OFICIAL DE NÚMEROS DE CAMISA (DORSAL) DOS JOGADORES (1 a 99)
// =========================================================================
function ensureSquadShirtNumbers(targetState = (typeof state !== 'undefined' ? state : null)){
  if(!targetState || !Array.isArray(targetState.squad)) return;
  const squad = targetState.squad.filter(Boolean);
  if(squad.length === 0) return;

  const usedNumbers = new Set();

  // 1. Prioriza jogadores com número já definido válido (ex: Messi #10, CR7 #7, etc.)
  squad.forEach(p => {
    const num = parseInt(p.number, 10);
    if(!isNaN(num) && num >= 1 && num <= 99 && !usedNumbers.has(num)){
      p.number = num;
      usedNumbers.add(num);
    } else {
      p.number = null; // precisa receber número
    }
  });

  // 2. Números preferenciais tradicionais por posição
  const preferredPosNumbers = {
    'GK': [1, 12, 22, 23, 30, 31, 99],
    'RB': [2, 13, 16, 20, 22],
    'LB': [6, 16, 12, 14, 26, 33],
    'CB': [3, 4, 14, 15, 24, 25, 30, 44],
    'DM': [5, 8, 17, 18, 21, 28, 55],
    'CM': [8, 10, 15, 20, 26, 88],
    'AM': [10, 7, 20, 80, 99],
    'RW': [7, 11, 17, 19, 21, 77],
    'LW': [11, 7, 17, 19, 22, 99],
    'ST': [9, 19, 29, 99, 18, 23],
    'CF': [9, 10, 19, 99]
  };

  function findNextAvailableNumber(pos){
    const prefs = preferredPosNumbers[pos] || [];
    for(const n of prefs){
      if(!usedNumbers.has(n)) return n;
    }
    for(let n = 1; n <= 99; n++){
      if(!usedNumbers.has(n)) return n;
    }
    return Math.floor(Math.random() * 99) + 1;
  }

  // 3. Atribui números para os jogadores que ainda não têm
  squad.forEach(p => {
    if(!p.number){
      const assigned = findNextAvailableNumber(p.pos);
      p.number = assigned;
      usedNumbers.add(assigned);
    }
  });
}
window.applyMonthlyTrainingAndCommercial = applyMonthlyTrainingAndCommercial;

function setPlayerShirtNumber(playerOrKey, newNumber, targetState = (typeof state !== 'undefined' ? state : null)){
  if(!targetState || !Array.isArray(targetState.squad)) return false;
  const num = parseInt(newNumber, 10);
  if(isNaN(num) || num < 1 || num > 99){
    if(typeof showNotification === 'function') showNotification('O número da camisa deve ser entre 1 e 99.', 'warn');
    return false;
  }

  const pKey = typeof playerOrKey === 'string' ? playerOrKey : (typeof playerKey === 'function' ? playerKey(playerOrKey) : (playerOrKey?.name || ''));
  const player = targetState.squad.find(p => p && ((typeof playerKey === 'function' ? playerKey(p) : p.name) === pKey || p.name === pKey));
  if(!player){
    if(typeof showNotification === 'function') showNotification('Jogador não encontrado no elenco.', 'error');
    return false;
  }

  const oldNum = player.number || null;
  if(oldNum === num) return true; // mesmo número

  // Verifica se outro jogador já usa esse número -> faz o swap inteligente!
  const occupyingPlayer = targetState.squad.find(p => p && p !== player && p.number === num);
  player.number = num;
  if(occupyingPlayer){
    occupyingPlayer.number = oldNum || 99;
    const occupiedSet = new Set(targetState.squad.filter(p => p && p !== occupyingPlayer).map(p => p.number));
    if(occupiedSet.has(occupyingPlayer.number)){
      for(let n = 1; n <= 99; n++){
        if(!occupiedSet.has(n)){
          occupyingPlayer.number = n;
          break;
        }
      }
    }
  }
  ensureSquadShirtNumbers(targetState);

  if(typeof showNotification === 'function'){
    if(occupyingPlayer){
      showNotification(`👕 Camisa trocada: ${player.name} agora é o #${player.number} (e ${occupyingPlayer.name} ficou com o #${occupyingPlayer.number})!`, 'success');
    } else {
      showNotification(`👕 Camisa atualizada: ${player.name} é o novo camisa #${player.number}!`, 'success');
    }
  }

  if(typeof render === 'function') render();
  return true;
}

function assignTraditionalShirtNumbers(targetState = (typeof state !== 'undefined' ? state : null)){
  if(!targetState || !Array.isArray(targetState.squad)) return;
  const squad = targetState.squad.filter(Boolean);
  if(squad.length === 0) return;

  const used = new Set();
  const lineupKeys = Array.isArray(targetState.lineup) ? targetState.lineup.slice(0, 11) : [];

  // 11 titulares recebem 1 a 11 pela ordem posicional tradicional
  const starters = [];
  lineupKeys.forEach(k => {
    const p = squad.find(pl => (typeof playerKey === 'function' ? playerKey(pl) : pl.name) === k);
    if(p && !starters.includes(p)) starters.push(p);
  });
  squad.forEach(p => {
    if(starters.length < 11 && !starters.includes(p)) starters.push(p);
  });

  // Ordena os 11 titulares do gol ao ataque
  const posOrder = { 'GK': 1, 'RB': 2, 'CB': 3, 'LB': 4, 'DM': 5, 'CM': 6, 'AM': 7, 'RW': 8, 'LW': 9, 'ST': 10, 'CF': 11 };
  starters.sort((a,b) => (posOrder[a.pos] || 99) - (posOrder[b.pos] || 99));

  // Mapa de números ideais 1 a 11
  let nextStarterNum = 1;
  starters.forEach(p => {
    p.number = nextStarterNum++;
    used.add(p.number);
  });

  // Reservas recebem 12 em diante
  let benchNum = 12;
  squad.forEach(p => {
    if(!starters.includes(p)){
      while(used.has(benchNum) && benchNum < 99) benchNum++;
      p.number = benchNum++;
      used.add(p.number);
    }
  });

  if(typeof showNotification === 'function') showNotification('👕 Numeração tradicional (1 a 11 nos titulares) aplicada com sucesso!', 'success');
  if(typeof render === 'function') render();
}

