function computeCompetitionAwards(compId, fallbackName = null){
  const normId = normalizeCompStatsId(compId);
  const meta = getCompetitionAwardsMeta(normId, fallbackName);
  const stats = syncCompetitionStatsComprehensive(normId) || getStateCompStats(normId);
  const summaries = collectCompetitionClubSummaries(normId);
  const maxMatches = summaries.size ? Math.max(...[...summaries.values()].map(s => s.j || 0)) : 0;
  const isKnockoutCup = normId === 'bra-cup' || normId.endsWith('-cup') || normId === 'eng-fa' || normId === 'eng-efl';
  const minMatchesRequired = maxMatches <= 2
    ? 1
    : Math.max(2, Math.ceil(maxMatches * (isKnockoutCup ? 0.34 : 0.40)));

  const createdAthleteName = state?.gameMode === 'player'
    ? (state.playerCareerState?.athleteName || state.squad?.find(p => p.isControlled)?.name)
    : null;
  const isMe = (name, club) => Boolean(
    createdAthleteName &&
    norm(name) === norm(createdAthleteName) &&
    (!state?.club || !club || norm(club) === norm(state.club))
  );

  const emptyAward = (title, icon) => ({
    title,
    icon,
    hasWinner: false,
    winnerName: 'A definir',
    winnerClub: '—',
    metricText: 'Aguardando jogos',
    value: 0,
    isUser: false,
    isMyClub: false
  });

  const hasRealData = maxMatches > 0 || (stats.scorers?.length > 0) || (stats.assists?.length > 0);
  if(!hasRealData){
    return {
      compId: normId,
      compName: meta.compName,
      hasPlayedMatches: false,
      maxMatches: 0,
      minMatchesRequired: 1,
      mvp: emptyAward(meta.mvp, '👑'),
      topScorer: emptyAward(meta.topScorer, '⚽'),
      assistLeader: emptyAward(meta.assistLeader, '🎯'),
      goldenGlove: emptyAward(meta.goldenGlove, '🧤'),
      youngPlayer: emptyAward(meta.youngPlayer, '🌟')
    };
  }

  // 1. Craque / MVP (exige amostragem mínima de partidas na competição + peso por impacto)
  const eligibleMvpPool = (stats.mvp || []).filter(p => (Number(p.matches) || 1) >= minMatchesRequired);
  const mvpSource = eligibleMvpPool.length ? eligibleMvpPool : (stats.mvp || []);
  const mvpWinner = mvpSource.slice().sort((a, b) => {
    const scoreA = (Number(a.rating) || 6.5) + Math.min(0.65, ((Number(a.goals) || 0) * 0.035 + (Number(a.assists) || 0) * 0.025));
    const scoreB = (Number(b.rating) || 6.5) + Math.min(0.65, ((Number(b.goals) || 0) * 0.035 + (Number(b.assists) || 0) * 0.025));
    return scoreB - scoreA || (Number(b.rating) || 0) - (Number(a.rating) || 0);
  })[0] || null;

  // 2. Artilheiro (Gols > Assistências > Menos Partidas)
  const scorerWinner = (stats.scorers || [])[0] || null;

  // 3. Garçom (Assistências > Gols > Menos Partidas)
  const assistWinner = (stats.assists || [])[0] || null;

  // 4. Luva de Ouro (Clean Sheets > Menos Gols Sofridos)
  const gloveWinner = (stats.cleanSheets || [])[0] || null;

  // 5. Revelação Sub-21 (idade <= 21 + amostragem mínima)
  const eligibleU21 = eligibleMvpPool.filter(p => (Number(p.age) || 24) <= 21);
  const fallbackU21 = (stats.mvp || []).filter(p => (Number(p.age) || 24) <= 21);
  const u21Pool = eligibleU21.length ? eligibleU21 : fallbackU21;
  const youngWinner = u21Pool[0] || null;

  const buildAward = (title, icon, row, valKey, fmtMetric) => {
    if(!row) return emptyAward(title, icon);
    const val = Number(row[valKey]) || 0;
    return {
      title,
      icon,
      hasWinner: true,
      winnerName: row.name,
      winnerClub: row.club || '—',
      pos: row.pos || '',
      age: row.age || null,
      matches: row.matches || maxMatches || 1,
      value: val,
      metricText: fmtMetric(row),
      isUser: isMe(row.name, row.club),
      isMyClub: Boolean(state?.club && row.club && norm(row.club) === norm(state.club))
    };
  };

  return {
    compId: normId,
    compName: meta.compName,
    hasPlayedMatches: true,
    maxMatches,
    minMatchesRequired,
    mvp: buildAward(meta.mvp, '👑', mvpWinner, 'rating', r => `Nota ${Number(r.rating || 7.0).toFixed(2)} (${r.matches || 1}J)`),
    topScorer: buildAward(meta.topScorer, '⚽', scorerWinner, 'goals', r => `${Number(r.goals) || 0} gol${Number(r.goals) === 1 ? '' : 's'}${r.matches ? ` (${r.matches}J)` : ''}`),
    assistLeader: buildAward(meta.assistLeader, '🎯', assistWinner, 'assists', r => `${Number(r.assists) || 0} assist.${r.matches ? ` (${r.matches}J)` : ''}`),
    goldenGlove: buildAward(meta.goldenGlove, '🧤', gloveWinner, 'cleanSheets', r => `${Number(r.cleanSheets) || 0} sem sofrer gol${r.matches ? ` (${r.matches}J)` : ''}`),
    youngPlayer: buildAward(meta.youngPlayer, '🌟', youngWinner, 'rating', r => `Nota ${Number(r.rating || 7.0).toFixed(2)}${r.age ? ` · ${r.age} anos` : ''}`)
  };
}
window.computeCompetitionAwards = computeCompetitionAwards;

function renderCompetitionStatsAndAwardsBlock(compId, compName = null){
  const normId = normalizeCompStatsId(compId);
  const resolvedName = compName || (typeof compById === 'function' ? compById(normId)?.name : null) || 'Competição Oficial';
  const awards = computeCompetitionAwards(normId, resolvedName);
  const compStats = getStateCompStats(normId);
  const currentStatsTab = (typeof statsFilterTab !== 'undefined' && statsFilterTab) || 'artilharia';
  const createdAthleteName = state?.gameMode === 'player'
    ? (state.playerCareerState?.athleteName || state.squad?.find(p => p.isControlled)?.name)
    : null;

  let displayStatsList = [];
  let statMetricHeader = 'Gols';
  if (currentStatsTab === 'assistencias') {
    statMetricHeader = 'Assistências';
    displayStatsList = Array.isArray(compStats.assists) ? compStats.assists : [];
  } else if (currentStatsTab === 'luva') {
    statMetricHeader = 'Jogos s/ Sofrer Gols';
    displayStatsList = Array.isArray(compStats.cleanSheets) ? compStats.cleanSheets : [];
  } else if (currentStatsTab === 'mvp') {
    statMetricHeader = 'Nota Média';
    displayStatsList = Array.isArray(compStats.mvp) ? compStats.mvp : [];
    if (!displayStatsList.length && Array.isArray(compStats.scorers) && compStats.scorers.length) {
      displayStatsList = compStats.scorers.map(s => ({ ...s, rating: (7.2 + Math.min(2.0, (Number(s.goals) || 0) * 0.25)).toFixed(2) }));
    }
  } else if (currentStatsTab === 'cartoes') {
    statMetricHeader = 'Amarelos / Vermelhos';
    displayStatsList = Array.isArray(compStats.cards) ? compStats.cards : [];
    if (!displayStatsList.length && Array.isArray(compStats.scorers) && compStats.scorers.length) {
      displayStatsList = compStats.scorers.slice().reverse().map((s, idx) => ({ ...s, yellowCards: ((idx % 3) + 1), redCards: 0 }));
    }
  } else {
    statMetricHeader = 'Gols';
    displayStatsList = Array.isArray(compStats.scorers) ? compStats.scorers : [];
  }

  if (window.statsOnlyMyClub) {
    const myClubNorm = typeof norm === 'function' ? norm(state?.club) : String(state?.club || '').toLowerCase();
    displayStatsList = displayStatsList.filter(item => {
      const cNorm = typeof norm === 'function' ? norm(item.club) : String(item.club || '').toLowerCase();
      return cNorm === myClubNorm;
    });
  }

  const awardCards = [awards.mvp, awards.topScorer, awards.assistLeader, awards.goldenGlove, awards.youngPlayer];

  return `
    <!-- TÍTULOS INDIVIDUAIS OFICIAIS DA COMPETIÇÃO -->
    <div class="card afm-comp-individual-awards-card" data-awards-comp="${esc(normId)}" style="margin-top:16px;background:linear-gradient(135deg, #151029 0%, #0b0917 100%);border:1px solid rgba(250,204,21,0.28);border-radius:14px;padding:18px 20px;box-shadow:0 8px 22px rgba(0,0,0,0.35)">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px;border-bottom:1px solid rgba(255,255,255,0.08);padding-bottom:10px">
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-size:20px">🏅</span>
          <div>
            <div style="font-size:13px;font-weight:900;letter-spacing:0.8px;color:#facc15;text-transform:uppercase">
              Títulos Individuais Oficiais — ${esc(resolvedName)}
            </div>
            <div style="font-size:11px;color:rgba(255,255,255,0.55)">
              ${awards.hasPlayedMatches ? `Corrida oficial em tempo real (${awards.maxMatches}J disputados · mínimo ${awards.minMatchesRequired}J p/ Craque & Sub-21)` : 'Os candidatos aparecerão assim que a bola rolar na competição'}
            </div>
          </div>
        </div>
        <span class="pill" style="font-size:10px;font-weight:900;background:${awards.hasPlayedMatches ? 'rgba(250,204,21,0.16)' : 'rgba(255,255,255,0.06)'};color:${awards.hasPlayedMatches ? '#fde047' : 'rgba(255,255,255,0.6)'};border:1px solid ${awards.hasPlayedMatches ? 'rgba(250,204,21,0.35)' : 'rgba(255,255,255,0.1)'}">
          ${awards.hasPlayedMatches ? '🔥 CORRIDA PELOS TROFÉUS' : '⏳ AGUARDANDO INÍCIO'}
        </span>
      </div>

      <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(195px, 1fr));gap:10px">
        ${awardCards.map(aw => `
          <div style="background:${aw.isUser ? 'linear-gradient(135deg,rgba(16,185,129,0.2),rgba(15,23,42,0.9))' : aw.isMyClub ? 'linear-gradient(135deg,rgba(124,58,237,0.18),rgba(15,23,42,0.9))' : 'rgba(255,255,255,0.025)'};border:1px solid ${aw.isUser ? '#10b981' : aw.isMyClub ? 'rgba(168,85,247,0.45)' : 'rgba(255,255,255,0.07)'};border-radius:12px;padding:12px;position:relative">
            ${aw.isUser ? `<span style="position:absolute;top:8px;right:8px;background:#10b981;color:#000;font-size:9px;font-weight:900;padding:2px 6px;border-radius:4px">⭐ VOCÊ</span>` : aw.isMyClub ? `<span style="position:absolute;top:8px;right:8px;background:#7c3aed;color:#fff;font-size:9px;font-weight:900;padding:2px 6px;border-radius:4px">SEU CLUBE</span>` : ''}
            <div style="font-size:10px;font-weight:800;color:#eab308;text-transform:uppercase;letter-spacing:0.4px;padding-right:${aw.isUser || aw.isMyClub ? '58px' : '0'}">${aw.icon} ${esc(aw.title)}</div>
            <div style="display:flex;align-items:center;gap:8px;margin-top:8px">
              ${aw.hasWinner && typeof clubBadge === 'function' ? clubBadge(aw.winnerClub, 22) : ''}
              <div style="min-width:0">
                <div style="font-size:14px;font-weight:900;color:${aw.hasWinner ? '#fff' : 'rgba(255,255,255,0.45)'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(aw.winnerName)}</div>
                <div style="font-size:11px;color:rgba(255,255,255,0.55);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${aw.hasWinner ? `${esc(aw.winnerClub)} · <b style="color:#c084fc">${esc(aw.metricText)}</b>` : esc(aw.metricText)}</div>
              </div>
            </div>
          </div>
        `).join('')}
      </div>
    </div>

    <!-- BLOCO DE ESTATÍSTICAS EM TEMA DARK NEON (UNIVERSAL PARA TODAS AS LIGAS E COPAS) -->
    <div class="card afm-comp-stats-neon-card" data-stats-comp="${esc(normId)}" style="margin-top:14px;background:linear-gradient(135deg, #100d1e 0%, #0d0a1a 100%);color:#f8fafc;border:1px solid rgba(139,92,246,0.25);border-radius:14px;padding:20px;box-shadow:0 10px 25px rgba(0,0,0,0.4)">
      <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(255,255,255,0.08);padding-bottom:10px;flex-wrap:wrap;gap:10px">
        <div style="display:flex;gap:12px;flex-wrap:wrap">
          <button type="button" class="btn btn-stat-tab ${currentStatsTab==='artilharia'?'active':''}" data-stats-tab="artilharia" style="background:transparent;border:none;font-size:14px;font-weight:900;letter-spacing:0.5px;color:${currentStatsTab==='artilharia'?'#a855f7':'rgba(255,255,255,0.5)'};cursor:pointer;padding:4px 8px;border-bottom:${currentStatsTab==='artilharia'?'3px solid #a855f7':'none'}">
            ⚽ ARTILHARIA
          </button>
          <button type="button" class="btn btn-stat-tab ${currentStatsTab==='assistencias'?'active':''}" data-stats-tab="assistencias" style="background:transparent;border:none;font-size:14px;font-weight:900;letter-spacing:0.5px;color:${currentStatsTab==='assistencias'?'#a855f7':'rgba(255,255,255,0.5)'};cursor:pointer;padding:4px 8px;border-bottom:${currentStatsTab==='assistencias'?'3px solid #a855f7':'none'}">
            🎯 ASSISTÊNCIAS
          </button>
          <button type="button" class="btn btn-stat-tab ${currentStatsTab==='mvp'?'active':''}" data-stats-tab="mvp" style="background:transparent;border:none;font-size:14px;font-weight:900;letter-spacing:0.5px;color:${currentStatsTab==='mvp'?'#a855f7':'rgba(255,255,255,0.5)'};cursor:pointer;padding:4px 8px;border-bottom:${currentStatsTab==='mvp'?'3px solid #a855f7':'none'}">
            ⭐ NOTA MÉDIA (MVP)
          </button>
          <button type="button" class="btn btn-stat-tab ${currentStatsTab==='luva'?'active':''}" data-stats-tab="luva" style="background:transparent;border:none;font-size:14px;font-weight:900;letter-spacing:0.5px;color:${currentStatsTab==='luva'?'#a855f7':'rgba(255,255,255,0.5)'};cursor:pointer;padding:4px 8px;border-bottom:${currentStatsTab==='luva'?'3px solid #a855f7':'none'}">
            🧤 LUVA DE OURO
          </button>
          <button type="button" class="btn btn-stat-tab ${currentStatsTab==='cartoes'?'active':''}" data-stats-tab="cartoes" style="background:transparent;border:none;font-size:14px;font-weight:900;letter-spacing:0.5px;color:${currentStatsTab==='cartoes'?'#a855f7':'rgba(255,255,255,0.5)'};cursor:pointer;padding:4px 8px;border-bottom:${currentStatsTab==='cartoes'?'3px solid #a855f7':'none'}">
            🟨 CARTÕES
          </button>
        </div>
        <div style="display:flex;align-items:center;gap:10px">
          <button type="button" id="btnToggleStatsOnlyClub" class="btn" style="font-size:11px;font-weight:800;padding:4px 10px;border-radius:6px;cursor:pointer;${window.statsOnlyMyClub ? 'background:#7c3aed;color:#fff;border:none' : 'background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.7);border:1px solid rgba(255,255,255,0.1)'}">
            ${window.statsOnlyMyClub ? '🛡️ Meu Clube' : '🏆 Todos'}
          </button>
          <div style="font-size:11px;font-weight:900;letter-spacing:1px;color:rgba(255,255,255,0.5);text-transform:uppercase">
            ${statMetricHeader}
          </div>
        </div>
      </div>

      <div style="display:flex;flex-direction:column;margin-top:12px;gap:6px">
        ${displayStatsList.slice(0, 10).map((item, idx) => {
          const isCreatedAthlete = Boolean(createdAthleteName && (typeof norm === 'function' ? norm(item.name) === norm(createdAthleteName) : item.name === createdAthleteName));
          const isMyPlayer = isCreatedAthlete || (typeof norm === 'function' ? norm(item.club) === norm(state?.club) : item.club === state?.club);
          const val = currentStatsTab === 'assistencias'
            ? (item.assists || 0)
            : currentStatsTab === 'luva'
            ? `${item.cleanSheets || 0} 🧤`
            : currentStatsTab === 'mvp'
            ? Number(item.rating || 7.0).toFixed(2)
            : currentStatsTab === 'cartoes'
            ? `${item.yellowCards || 0}🟨${item.redCards ? ` ${item.redCards}🟥` : ''}`
            : (item.goals || 0);

          return `
            <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border-bottom:1px solid rgba(255,255,255,0.06);border-radius:8px;${isMyPlayer ? 'background:rgba(124,58,237,0.22);border:1px solid rgba(139,92,246,0.3);' : 'background:rgba(255,255,255,0.02);'}">
              <div style="display:flex;align-items:center;gap:14px">
                <span style="font-size:16px;font-weight:900;color:${idx < 3 ? '#fbbf24' : 'rgba(255,255,255,0.5)'};min-width:24px;text-align:center">${idx + 1}</span>
                <div style="position:relative">
                  ${typeof playerPhoto === 'function' ? playerPhoto(item.name, 40) : ''}
                </div>
                ${typeof clubBadge === 'function' ? clubBadge(item.club, 24) : ''}
                <div>
                  <div style="font-size:14px;font-weight:900;color:#fff">
                    ${typeof esc === 'function' ? esc(item.name) : item.name} ${isCreatedAthlete ? '<span class="tag-you" style="display:inline-block;margin-left:5px;background:#7c3aed;color:#fff">VOCÊ</span>' : ''}
                  </div>
                  <div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.5);letter-spacing:0.5px;text-transform:uppercase;margin-top:2px">
                    ${typeof esc === 'function' ? esc(item.pos || 'ATA') : (item.pos || 'ATA')}${item.age ? ` • ${item.age}A` : ''} • ${typeof esc === 'function' ? esc(item.club) : item.club}${item.matches ? ` • ${item.matches}J` : ''}
                  </div>
                </div>
              </div>

              <div style="display:flex;align-items:center;gap:8px">
                <span style="font-size:20px;font-weight:900;color:${isMyPlayer ? 'var(--neon)' : '#fff'}">${val}</span>
              </div>
            </div>
          `;
        }).join('') || `
          <div style="text-align:center;padding:24px;color:rgba(255,255,255,0.4)">
            Nenhum dado registrado até o momento na temporada.
          </div>
        `}
      </div>

      <div style="text-align:center;margin-top:14px;padding-top:12px;border-top:1px solid rgba(255,255,255,0.08)">
        <button type="button" class="btn" id="btnOpenFullStatsModal" data-comp-id="${esc(normId)}" data-comp-name="${esc(resolvedName)}" style="background:linear-gradient(135deg,rgba(124,58,237,0.3) 0%,rgba(139,92,246,0.1) 100%);border:1px solid #7c3aed;color:#c084fc;font-size:12px;font-weight:800;letter-spacing:1px;padding:8px 20px;border-radius:8px;cursor:pointer">
          VER RANKING COMPLETO (TOP 30) ➔
        </button>
      </div>
    </div>
  `;
}
window.renderCompetitionStatsAndAwardsBlock = renderCompetitionStatsAndAwardsBlock;


function openClubInfoModal(clubName){
  const clubObj = clubByName(clubName) || { name: clubName, country: 'Brasil', competition: curComp()?.name || 'Brasileirão', atk: 60, mid: 60, def: 60, budget: 1, stadium: 'Estádio Municipal' };
  const str = strength(clubObj);
  const cComp = clubObj.competition || 'Estadual';
  const cEstId = clubStateCompId(clubName);
  const estData = getStateCompData(cEstId);
  const tableRow = estData?.teams?.find(t=>norm(t.name)===norm(clubName));
  const squadPool = playersForClub(clubName, state.worldGenerated || []).slice(0, 16);

  openCustomModal(
    `Informações do Clube: ${esc(clubName)}`,
    `
      <div style="display:flex;align-items:center;gap:16px;background:rgba(255,255,255,0.03);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.08)">
        ${clubBadge(clubName, 64)}
        <div>
          <h2 style="margin:0;font-size:22px;color:#fff">${esc(clubName)}</h2>
          <div style="font-size:13px;color:rgba(255,255,255,0.6);margin-top:2px">
            🏟️ <b>${esc(clubObj.stadium||'Estádio do Clube')}</b> • 🏆 ${esc(cComp)}
          </div>
          <div style="margin-top:6px;display:flex;gap:8px;flex-wrap:wrap">
            <span class="pill good">Força Geral: ${str}</span>
            <span class="pill">ATK: ${clubObj.atk||60}</span>
            <span class="pill">MEI: ${clubObj.mid||60}</span>
            <span class="pill">DEF: ${clubObj.def||60}</span>
          </div>
        </div>
      </div>

      ${tableRow ? `
        <div style="margin-top:14px;background:#161324;padding:12px 16px;border-radius:10px;border:1px solid rgba(139,92,246,0.2);display:flex;justify-content:space-around;text-align:center">
          <div><div class="small muted">Posição</div><div style="font-weight:900;font-size:18px;color:var(--neon)">#${estData.teams.indexOf(tableRow)+1}</div></div>
          <div><div class="small muted">Pontos</div><div style="font-weight:900;font-size:18px">${tableRow.p}</div></div>
          <div><div class="small muted">Jogos</div><div style="font-weight:900;font-size:18px">${tableRow.j}</div></div>
          <div><div class="small muted">Vitórias</div><div style="font-weight:900;font-size:18px">${tableRow.v}</div></div>
          <div><div class="small muted">Gols Pró</div><div style="font-weight:900;font-size:18px">${tableRow.gp}</div></div>
          <div><div class="small muted">Saldo</div><div style="font-weight:900;font-size:18px">${tableRow.sg>0?'+':''}${tableRow.sg}</div></div>
        </div>
      ` : ''}

      <h3 style="margin:16px 0 8px 0;font-size:15px">Destaques do Elenco (${squadPool.length} atletas)</h3>
      <div class="tablewrap" style="max-height:260px">
        <table>
          <thead><tr><th>Foto</th><th>Jogador</th><th>Pos</th><th>Idade</th><th>Overall</th><th>Salário Estimado</th></tr></thead>
          <tbody>
            ${squadPool.map(p=>`
              <tr>
                <td style="width:40px">${playerPhoto(p, 28)}</td>
                <td><b>${esc(p.name)}</b></td>
                <td><span class="pill" style="font-size:11px">${esc(p.pos||'-')}</span></td>
                <td>${p.age||23} anos</td>
                <td><div style="display:flex;flex-direction:column;align-items:center;gap:2px"><span class="rating-pill ${ratingClass(playerOverall(p))}">${playerOverall(p)}</span>${window.AFM_PlayerXPEvolution ? window.AFM_PlayerXPEvolution.renderMiniXPBar(p) : ''}</div></td>
                <td style="color:#22c55e;font-weight:700">R$ ${playerSalary(p).toLocaleString('pt-BR')}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `,
    null,
    'Fechar',
    false
  );
}

function openBorrowedPlayerManagementModal(p){
  if(!p) return;
  normalizeLoanContractData(state);
  if(p.loanEndDate < state.date){ processLoanContractReturns(state); return; }
  const parentClub = p.loanFrom || p.originalClub || 'Clube Detentor';
  const valMi = calcValueMi(p);
  const marketBuyPrice = Math.round(valMi * 1e6);
  const buyOptionActive = Number(p.loanBuyOptionPrice) > 0 && (!p.loanBuyOptionEndDate || state.date <= p.loanBuyOptionEndDate);
  const buyPrice = buyOptionActive ? Math.round(Number(p.loanBuyOptionPrice)) : Math.round(valMi * 1e6);
  let purchaseContractYears = clamp(Number(p.loanPurchaseContractYears) || 3, 1, 5);
  const loanRemainingDays = getLoanRemainingDays(p, state.date);
  const extFee6m = Math.round(marketBuyPrice * 0.05);
  const extFee12m = Math.round(marketBuyPrice * 0.10);
  const canBuy = state.balance >= buyPrice;
  const canExt6 = state.balance >= extFee6m;
  const canExt12 = state.balance >= extFee12m;

  openCustomModal(
    `🤝 Gestão de Empréstimo: ${esc(p.name)}`,
    `
      <div style="display:flex;align-items:center;gap:16px;background:rgba(255,255,255,0.03);padding:14px;border-radius:12px;margin-bottom:14px">
        ${playerPhoto(p, 52)}
        <div style="flex:1">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <h2 style="margin:0;font-size:18px">${esc(p.name)}</h2>
            <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px">
              <span class="pill warn" style="font-weight:900;font-size:11px">🏷️ ATLETA EMPRESTADO</span>
              <div style="padding:6px 10px;border-radius:8px;background:rgba(245,158,11,.12);border:1px solid rgba(245,158,11,.3);text-align:right">
                <div style="font-size:10px;font-weight:800;letter-spacing:.5px;color:#fbbf24">${loanRemainingDays > 0 ? `FALTAM ${loanRemainingDays} ${loanRemainingDays === 1 ? 'DIA' : 'DIAS'}` : 'ÚLTIMO DIA DO EMPRÉSTIMO'}</div>
                <div style="font-size:10px;color:#cbd5e1;margin-top:2px">Devolução: ${formatDatePtBr(p.loanEndDate)}</div>
              </div>
            </div>
          </div>
          <div style="font-size:12px;color:rgba(255,255,255,0.6);margin-top:2px">
            ${esc(p.pos||'-')} • ${p.age||22} anos • Overall: <b class="good">${playerOverall(p)}</b> • Passe de mercado: <b class="good">${fmtMi(valMi)}</b>
          </div>
          <div style="margin-top:6px;font-size:12px;color:#38bdf8;display:flex;align-items:center;gap:6px">
            <span>🏛️ Clube Detentor dos Direitos:</span>
            <b>${esc(parentClub)}</b>
          </div>
          <div style="margin-top:5px;font-size:12px;color:#fbbf24">📅 Vigência do empréstimo: ${formatDatePtBr(p.loanEndDate)} · ${loanRemainingDays > 0 ? `${loanRemainingDays} ${loanRemainingDays === 1 ? 'dia restante' : 'dias restantes'}` : 'último dia'}</div>
        </div>
      </div>

      <div style="background:rgba(59,130,246,0.08);border:1px solid rgba(59,130,246,0.25);border-radius:10px;padding:10px 14px;margin-bottom:16px;font-size:12px;color:rgba(255,255,255,0.85);line-height:1.5">
        ℹ️ Este atleta não pertence em definitivo ao <b>${esc(state.club)}</b>. Para manter ou liberar o atleta, escolha uma das opções de negociação direta com o <b>${esc(parentClub)}</b> abaixo:
      </div>

      <div style="display:flex;flex-direction:column;gap:12px">
        <!-- 1. COMPRA DEFINITIVA -->
        <div style="background:#131024;border:1px solid rgba(34,197,94,0.3);border-radius:12px;padding:14px">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px">
            <div>
              <div style="font-weight:900;font-size:14px;color:#4ade80">💰 1. Exercer Cláusula / Comprar em Definitivo</div>
              <div style="font-size:11px;color:rgba(255,255,255,0.6);margin-top:3px">
                Transfere 100% dos direitos econômicos e federativos para o ${esc(state.club)} com contrato definido abaixo.
              </div>
              <div style="font-size:13px;font-weight:800;color:#22c55e;margin-top:6px">
                ${buyOptionActive ? 'Preço fixado no empréstimo' : 'Valor de mercado atual'}: ${fmtMoney(buyPrice)} <span class="small muted">(Seu Caixa: ${fmtMoney(state.balance)})</span>
              </div>
              <label style="display:flex;align-items:center;gap:8px;font-size:11px;color:#cbd5e1;margin-top:8px">Duração do novo contrato
                <select id="loanPurchaseContractYears" style="background:#0f172a;color:#fff;border:1px solid #475569;border-radius:7px;padding:5px">${[1,2,3,4,5].map(years=>`<option value="${years}" ${purchaseContractYears===years?'selected':''}>${years} ano(s)</option>`).join('')}</select>
              </label>
            </div>
            <button class="btn success" id="btnBuyoutLoanPlayer" ${!canBuy ? 'disabled title="Saldo insuficiente no caixa"' : ''} style="font-weight:900;padding:8px 16px;font-size:12px">
              ${canBuy ? '🛒 Comprar em Definitivo' : 'Saldo Insuficiente'}
            </button>
          </div>
        </div>

        <!-- 2. SOLICITAR EXTENSÃO -->
        <div style="background:#131024;border:1px solid rgba(56,189,248,0.3);border-radius:12px;padding:14px">
          <div style="font-weight:900;font-size:14px;color:#38bdf8;margin-bottom:4px">🤝 2. Solicitar Extensão do Empréstimo</div>
          <div style="font-size:11px;color:rgba(255,255,255,0.6);margin-bottom:10px">
            Envia uma solicitação oficial ao ${esc(parentClub)} para estender a cessão temporária do atleta.
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
            <button class="btn" id="btnExtendLoan6m" ${!canExt6 ? 'disabled' : ''} style="padding:10px;text-align:left;background:rgba(56,189,248,0.08);border:1px solid #38bdf8">
              <div style="font-weight:800;font-size:12px;color:#fff">📅 Extensão por 6 Meses</div>
              <div style="font-size:11px;color:#38bdf8;margin-top:2px">Taxa: ${fmtMoney(extFee6m)}</div>
            </button>
            <button class="btn" id="btnExtendLoan12m" ${!canExt12 ? 'disabled' : ''} style="padding:10px;text-align:left;background:rgba(56,189,248,0.08);border:1px solid #38bdf8">
              <div style="font-weight:800;font-size:12px;color:#fff">📅 Extensão por 12 Meses</div>
              <div style="font-size:11px;color:#38bdf8;margin-top:2px">Taxa: ${fmtMoney(extFee12m)}</div>
            </button>
          </div>
        </div>

        <!-- 3. DEVOLVER ATLETA -->
        <div style="background:#131024;border:1px solid rgba(239,68,68,0.3);border-radius:12px;padding:14px">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">
            <div>
              <div style="font-weight:900;font-size:14px;color:#f87171">↩️ 3. Devolver Atleta ao Clube de Origem</div>
              <div style="font-size:11px;color:rgba(255,255,255,0.6);margin-top:3px">
                Encerra imediatamente o empréstimo antes do término e libera a vaga na folha salarial.
              </div>
            </div>
            <button class="btn bad" id="btnReturnLoanPlayer" style="font-weight:900;padding:8px 16px;font-size:12px">
              ↩️ Devolver Atleta
            </button>
          </div>
        </div>
      </div>
    `,
    null,
    'Fechar',
    false
  );

  setTimeout(() => {
    const yearsSelect = $('#loanPurchaseContractYears');
    if(yearsSelect) yearsSelect.onchange = () => { purchaseContractYears = clamp(Number(yearsSelect.value) || 3, 1, 5); p.loanPurchaseContractYears = purchaseContractYears; save(); };
    const bBuy = $('#btnBuyoutLoanPlayer');
    if(bBuy){
      bBuy.onclick = () => {
        if(state.balance < buyPrice){
          toast('Saldo insuficiente para comprar o atleta.');
          return;
        }
        state.balance -= buyPrice;
        state.expense = (state.expense || 0) + buyPrice;
        delete p.isLoan;
        delete p.loanFrom;
        p.owned = true;
        p.contractUntil = Number(state.season) + purchaseContractYears;
        p.contractMonth = 12;
        ['isLoan','loanFrom','loanStartDate','loanEndDate','loanDurationMonths','loanBuyOptionPrice','loanBuyOptionEndDate','loanPurchaseContractYears'].forEach(field => delete p[field]);
        state.transfers = Array.isArray(state.transfers) ? state.transfers : [];
        state.transfers.unshift({ type: 'in', name: p.name, from: parentClub, to: state.club, value: buyPrice, date: state.date, loanBuyout: true });
        state.news.unshift(`💰 COMPRA DEFINITIVA: ${state.club} adquiriu ${p.name} do ${parentClub} por ${fmtMoney(buyPrice)} e assinou contrato por ${purchaseContractYears} ano(s).`);
        toast(`🎉 ${p.name} comprado em definitivo por ${fmtMoney(buyPrice)}. Contrato de ${purchaseContractYears} ano(s).`);
        closeCustomModal();
        save();
        render();
      };
    }

    const handleExtend = (months, fee) => {
      if(state.balance < fee){
        toast('Saldo insuficiente para taxa de extensão.');
        return;
      }
      state.balance -= fee;
      state.expense = (state.expense || 0) + fee;
      const previousEndDate = p.loanEndDate;
      p.loanEndDate = addMonthsToIsoDate(p.loanEndDate, months);
      p.loanDurationMonths = (Number(p.loanDurationMonths) || 12) + months;
      p.contractUntil = Number(p.loanEndDate.slice(0, 4)) || Number(state.season);
      if(p.loanBuyOptionEndDate === previousEndDate) p.loanBuyOptionEndDate = p.loanEndDate;
      state.news.unshift(`🤝 EXTENSÃO DE EMPRÉSTIMO: O ${parentClub} aceitou prorrogar o empréstimo de ${p.name} por mais ${months} meses (taxa de ${fmtMoney(fee)}).`);
      toast(`✅ Empréstimo de ${p.name} estendido por mais ${months} meses!`);
      closeCustomModal();
      save();
      render();
    };

    const bExt6 = $('#btnExtendLoan6m');
    if(bExt6) bExt6.onclick = () => handleExtend(6, extFee6m);

    const bExt12 = $('#btnExtendLoan12m');
    if(bExt12) bExt12.onclick = () => handleExtend(12, extFee12m);

    const bRet = $('#btnReturnLoanPlayer');
    if(bRet){
      bRet.onclick = () => {
        if(!confirm(`Deseja realmente devolver ${p.name} ao ${parentClub} e rescindir o empréstimo?`)) return;
        if(!detachLoanedPlayer(state, p)) return;
        state.loans = Array.isArray(state.loans) ? state.loans : [];
        state.loans.unshift({ type: 'loan_return', name: p.name, from: state.club, to: parentClub, date: state.date, earlyReturn: true });
        state.news.unshift(`↩️ RESCISÃO DE EMPRÉSTIMO: ${p.name} foi devolvido ao ${parentClub} antes do término do vínculo.`);
        toast(`Atleta ${p.name} devolvido ao ${parentClub}.`);
        closeCustomModal();
        save();
        render();
      };
    }
  }, 50);
}

function openPlayerContractRenewalModal(pk){
  const p = state.squad.find(q=>q && playerKey(q)===pk);
  if(!p) return;
  if(p.isLoan){
    openBorrowedPlayerManagementModal(p);
    return;
  }
  const curWage = playerSalary(p);
  const curUntil = playerContractUntil(p);
  const morale = p.morale || 70;

  // Chances de aceite baseadas no moral do atleta e no patamar salarial
  const legacySigningBonus = state.gameMode === 'manager'
    ? clamp(Number(state.managerCareerBonuses?.playerSigningChancePct ?? state.bonusNegociacaoJogadores) || 0, 0, 5)
    : 0;
  const chance1 = clamp(Math.round(morale * 0.90 + 15) + legacySigningBonus, 25, 95);
  const chance2 = clamp(Math.round(morale * 0.85 + 20) + legacySigningBonus, 20, 92);
  const chance3 = clamp(Math.round(morale * 0.80 + 25) + legacySigningBonus, 15, 88);

  openCustomModal(
    `Renovação Contratual: ${esc(p.name)}`,
    `
      <div style="display:flex;align-items:center;gap:16px;background:rgba(255,255,255,0.03);padding:14px;border-radius:12px;margin-bottom:14px">
        ${playerPhoto(p, 50)}
        <div>
          <h2 style="margin:0;font-size:18px">${esc(p.name)}</h2>
          <div style="font-size:12px;color:rgba(255,255,255,0.6)">${p.pos||'-'} • ${playerOverall(p)} OVR • ${p.age||22} anos • Moral: <b style="color:${morale>=70?'#22c55e':morale>=50?'#f59e0b':'#ef4444'}">${morale}%</b></div>
          <div style="margin-top:4px;font-size:13px">
            Salário atual: <b style="color:#22c55e">R$ ${curWage.toLocaleString('pt-BR')}</b>/mês • Vínculo até: <b>${curUntil}</b>
          </div>
        </div>
      </div>

      <div style="display:flex;flex-direction:column;gap:10px">
        <label style="font-size:13px;font-weight:700">Escolha a proposta de renovação:</label>
        <button class="btn primary" id="btnRenew1Year" style="padding:12px;text-align:left;display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:800;font-size:13px">📅 +1 ano (Até ${curUntil + 1}) • Aumento de 10%</div>
            <div style="font-size:11px;color:rgba(255,255,255,0.8);margin-top:2px">
              🎲 Chance de Aceite do Atleta: <b style="color:#facc15">${chance1}%</b>${legacySigningBonus > 0 ? ' <span style="color:#10b981;font-weight:800;font-size:10px">(+5% Ex-Atleta)</span>' : ''}
            </div>
          </div>
          <b style="font-size:14px;color:#fff">R$ ${Math.round(curWage * 1.10).toLocaleString('pt-BR')}/mês</b>
        </button>

        <button class="btn" id="btnRenew2Years" style="padding:12px;text-align:left;display:flex;justify-content:space-between;align-items:center;background:#7c3aed22;border:1px solid #7c3aed">
          <div>
            <div style="font-weight:800;font-size:13px">📅 +2 anos (Até ${curUntil + 2}) • Aumento de 15%</div>
            <div style="font-size:11px;color:rgba(255,255,255,0.8);margin-top:2px">
              🎲 Chance de Aceite do Atleta: <b style="color:#facc15">${chance2}%</b>${legacySigningBonus > 0 ? ' <span style="color:#10b981;font-weight:800;font-size:10px">(+5% Ex-Atleta)</span>' : ''}
            </div>
          </div>
          <b style="font-size:14px;color:#fff">R$ ${Math.round(curWage * 1.15).toLocaleString('pt-BR')}/mês</b>
        </button>

        <button class="btn" id="btnRenew3Years" style="padding:12px;text-align:left;display:flex;justify-content:space-between;align-items:center;background:#05966922;border:1px solid #059669">
          <div>
            <div style="font-weight:800;font-size:13px">📅 +3 anos (Até ${curUntil + 3}) • Aumento de 20%</div>
            <div style="font-size:11px;color:rgba(255,255,255,0.8);margin-top:2px">
              🎲 Chance de Aceite do Atleta: <b style="color:#facc15">${chance3}%</b>${legacySigningBonus > 0 ? ' <span style="color:#10b981;font-weight:800;font-size:10px">(+5% Ex-Atleta)</span>' : ''}
            </div>
          </div>
          <b style="font-size:14px;color:#fff">R$ ${Math.round(curWage * 1.20).toLocaleString('pt-BR')}/mês</b>
        </button>
      </div>
    `,
    null,
    'Cancelar',
    false
  );

  const applyRenewal = (yearsPlus, wageFactor, chance) => {
    const roll = Math.random() * 100;
    if(roll <= chance){
      p.contractUntil = curUntil + yearsPlus;
      p.wage = Math.round(curWage * wageFactor);
      p.morale = clamp((p.morale || 70) + 10, 0, 100);
      save();
      render();
      closeCustomModal();
      toast(`🎉 ${p.name} ACEITOU a renovação até ${p.contractUntil} por R$ ${p.wage.toLocaleString('pt-BR')}/mês!`);
    } else {
      p.morale = clamp((p.morale || 70) - 5, 10, 100);
      save();
      render();
      closeCustomModal();
      toast(`❌ ${p.name} RECUSOU a proposta (+${Math.round((wageFactor - 1)*100)}%)! O atleta ou seu agente exigem números maiores.`);
    }
  };

  setTimeout(()=>{
    const b1 = $('#btnRenew1Year'); if(b1) b1.onclick = () => applyRenewal(1, 1.10, chance1);
    const b2 = $('#btnRenew2Years'); if(b2) b2.onclick = () => applyRenewal(2, 1.15, chance2);
    const b3 = $('#btnRenew3Years'); if(b3) b3.onclick = () => applyRenewal(3, 1.20, chance3);
  }, 50);
}

