      rivalClub: data.rivalClub || null,
      pitchType: data.pitchType || 'natural',
      clubModel: data.clubModel || 'associativo',
      projectTier: data.projectTier || 'raiz',
      masterSponsor: data.masterSponsor || activeSponsors.master,
