function bankLoanPaymentBreakdown(loan, payment){
  const remainingDebt = Math.max(0, Number(loan?.remainingDebt) || 0);
  const principal = Math.max(0, Number(loan?.principal) || 0);
  const totalDebt = Math.max(principal, Number(loan?.totalDebt) || principal);
  const totalInstallments = Math.max(1, Number(loan?.totalInstallments) || 1);
  const paidInstallments = Math.max(0, Number(loan?.paidInstallments) || 0);
  const scheduledInstallment = Math.max(0, Number(loan?.installmentValue) || totalDebt / totalInstallments);
  const interestPerInstallment = Math.max(0, totalDebt - principal) / totalInstallments;
  const remainingPrincipal = Number.isFinite(Number(loan?.remainingPrincipal))
    ? Math.max(0, Number(loan.remainingPrincipal))
    : Math.min(remainingDebt, Math.max(0, principal - Math.round(Math.max(0, scheduledInstallment - interestPerInstallment) * paidInstallments)));
  const amount = Math.min(remainingDebt, Math.max(0, Number(payment) || 0));
  const principalPaid = Math.min(remainingPrincipal, Math.max(0, amount - Math.min(amount, interestPerInstallment)));
  const interestPaid = Math.max(0, amount - principalPaid);
  return { amount, principalPaid, interestPaid, remainingPrincipal: Math.max(0, remainingPrincipal - principalPaid) };
}

function currentSeasonSponsorFactor(positionValue, teamCount, compId){
  const pos = Math.max(1, Number(positionValue) || 1);
  const count = Math.max(1, Number(teamCount) || 1);
  const rankFactor = pos <= 3 ? 1.12 : pos <= Math.ceil(count / 2) ? 1 : 0.88;
  const divisionFactor = ({'bra-a':1.2,'bra-b':1.05,'bra-c':0.9,'bra-d':0.78})[compId] || 1;
  return Math.round(rankFactor * divisionFactor * 1000) / 1000;
}

function refreshAnnualSponsorValues(positionValue, teamCount, compId){
  const previousFactor = Math.max(0.1, Number(state.sponsorSeasonFactor) || 1);
  const nextFactor = currentSeasonSponsorFactor(positionValue, teamCount, compId);
  const adjustment = nextFactor / previousFactor;
  ['master','sleeves','back'].forEach(slot => {
    const sponsor = state.sponsors?.[slot];
    if(!sponsor) return;
    sponsor.monthly = Math.round((Number(sponsor.monthly) || 0) * adjustment);
    sponsor.winBonus = Math.round((Number(sponsor.winBonus) || 0) * adjustment);
  });
  state.sponsorSeasonFactor = nextFactor;
}

function ensureTvBroadcastContract(st){
  if(!st) return null;
  if(st.tvContract1Year && typeof st.tvContract1Year === 'object') return st.tvContract1Year;

  const club = typeof clubByName === 'function' ? clubByName(st.club) : null;
  const ovr = (typeof strength === 'function' && club) ? (strength(club) || 76) : 76;
  const comp = (typeof compById === 'function' && st.compId) ? compById(st.compId) : null;
  const division = comp?.id === 'bra-a' ? 1 : comp?.id === 'bra-b' ? 2 : 3;
  const multiplier = Math.pow(Math.max(55, ovr) / 72, 2.2) * (division === 1 ? 1 : division === 2 ? 0.38 : 0.16);
  const baseAnnual = Math.round(82000000 * multiplier);
  const broadcaster = getTvCompanies(baseAnnual)[0];
  const annualTotal = Math.round(baseAnnual * (Number(broadcaster?.annualFactor) || 1));

  st.tvContract1Year = {
    id: broadcaster?.id || 'globo_libra',
    name: broadcaster?.name || 'Emissora Oficial',
    annualTotal,
    monthly: Math.round(annualTotal / 12),
    channels: broadcaster?.channels || '',
    desc: broadcaster?.desc || '',
    advancedAmount: 0,
    advancedPaid: 0,
    advancedTaken: false
  };
  return st.tvContract1Year;
}

function monthlyFinancialProjection(socioData = null){
  const sponsorMonthly = totalSponsorMonthly();
  const adminMonthly = Math.round(sponsorMonthly * 0.03 * (state.infrastructure?.admin?.level || 1));
  const tvContract = ensureTvBroadcastContract(state);
  const socioMonthly = (socioData || getSocioTorcedorMeta()).currentIncome;
  const namingMonthly = state.namingRights?.monthsRemaining > 0 ? Math.max(0, Number(state.namingRights.monthlyValue) || 0) : 0;
  const store = state.storeConfig || { level: 1, pricing: 'normal', stock: 'normal' };
  let storeGross = store.level === 1 ? 25000 : store.level === 2 ? 65000 : 130000;
  if(store.pricing === 'popular') storeGross *= 1.25;
  else if(store.pricing === 'premium') storeGross *= 0.85;
  const storeMonthly = Math.round(storeGross * (1 - (store.stock === 'full' ? 0.65 : store.stock === 'lean' ? 0.45 : 0.55)));
  const homeMatches = (state.history || []).filter(match => Number(match.season) === Number(state.season) && (match.isHome === true || (match.isHome == null && norm(match.h) === norm(state.club))) && Number.isFinite(Number(match.gate)));
  const recentHome = homeMatches.slice(0, 8);
  const averageHomeRevenue = field => {
    const values = recentHome.map(match => Number(match[field])).filter(value => Number.isFinite(value) && value >= 0);
    if(values.length) return values.reduce((sum, value) => sum + value, 0) / values.length;
    return Math.max(0, Number(state.lastHome?.[field === 'gate' ? 'revenue' : field === 'shop' ? 'storeShop' : field]) || 0);
  };
  const monthlyGate = Math.round(averageHomeRevenue('gate') * 2);
  const monthlyParking = Math.round(averageHomeRevenue('parkRevenue') * 2);
  const monthlyMatchSales = Math.round(averageHomeRevenue('shop') * 2);
  const played = (state.history || []).filter(match => Number(match.season) === Number(state.season) && (match.isHome === true || match.isHome === false || norm(match.h) === norm(state.club) || norm(match.a) === norm(state.club))).slice(0, 12);
  const winRate = played.length ? played.filter(match => match.won ?? (norm(match.h) === norm(state.club) ? Number(match.hg) > Number(match.ag) : Number(match.ag) > Number(match.hg))).length / played.length : 0.5;
  const sponsorWinEstimate = Math.round(totalSponsorWinBonus() * 2 * winRate);
  const bankInstallments = (state.bankLoans || []).reduce((sum, loan) => sum + (Number(loan.remainingInstallments) > 0 ? Math.max(0, Number(loan.installmentValue) || 0) * 2 : 0), 0);
  const stadiumInstallment = Math.max(0, Number(state.stadiumRingData?.debt?.remaining) > 0 ? Number(state.stadiumRingData.debt.monthly) || 0 : 0);
  const revenue = {
    sponsors: sponsorMonthly,
    structures: monthlyFacilityIncome(),
    admin: adminMonthly,
    tv: Math.max(0, Number(tvContract?.monthly) || 0),
    members: socioMonthly,
    naming: namingMonthly,
    store: storeMonthly,
    gate: monthlyGate,
    parking: monthlyParking,
    matchSales: monthlyMatchSales,
    winBonuses: sponsorWinEstimate
  };
  const isClubSaf = typeof window.isClubSaf === 'function' ? window.isClubSaf(state) : (Boolean(state.clubIsSaf) || Boolean((state.club || '').match(/\bsaf\b/i)));
  const divExpense = isClubSaf && typeof window !== 'undefined' && window.AFM_LifeAndSharesPro?.calculateMonthlyClubDividendExpense
    ? window.AFM_LifeAndSharesPro.calculateMonthlyClubDividendExpense(state).totalClubDividendExpense
    : 0;

  const expenses = {
    payroll: totalMonthlyPayroll(),
    facilities: totalFacilitiesMonthlyExpense(state),
    scouts: getMonthlyScoutPayroll(state),
    marketing: Math.max(MARKETING_MINIMUM_WEEKLY, Number(state.marketingWeekly) || 36000) * 4,
    bankRepayments: bankInstallments,
    stadiumRepayments: stadiumInstallment
  };
  if(divExpense > 0) expenses.dividends = divExpense;
  const monthlyRevenue = Object.values(revenue).reduce((sum, value) => sum + value, 0);
  const monthlyExpenses = Object.values(expenses).reduce((sum, value) => sum + value, 0);
  const monthlyBalance = monthlyRevenue - monthlyExpenses;
  return { revenue, expenses, monthlyRevenue, monthlyExpenses, monthlyBalance, projectedClosingBalance: (Number(state.balance) || 0) + monthlyBalance, homeSample: recentHome.length };
}

/**
 * REGRA INVIOLÁVEL DO SISTEMA FINANCEIRO MENSAL, TV E PATROCÍNIOS:
 * Executa de forma atômica, contínua e retroativa o ciclo financeiro do clube:
 * 1. A cota mensal da TV oficial contratada (ex: Globo) é creditada e subtraída de 'Quanto Ainda Falta Receber'.
 * 2. As cotas mensais de patrocínio são creditadas e subtraem meses e valor restante do contrato.
 * 3. Todas as contas mensais (folha do elenco, staff, olheiros, marketing, estádio e bancos) são quitadas.
 * 4. Extrato transparente consolidado é enviado ao feed de notícias.
 */
function processClubMonthlyFinances(st, targetDate = st?.date){
  if(!st) return;
  const curDateStr = String(targetDate || st.date || '2026-01-01');
  const [yearStr, monthStr] = curDateStr.split('-');
  const curYear = parseInt(yearStr, 10) || Number(st.season) || 2026;
  const curMonth = parseInt(monthStr, 10) || 1;

  st.processedFinancialMonths = Array.isArray(st.processedFinancialMonths) ? st.processedFinancialMonths : [];

  // Gera todos os meses desde o início da temporada atual até o mês corrente
  const eligibleMonths = [];
  for(let m = 1; m <= curMonth; m++){
    const mStr = String(m).padStart(2, '0');
    eligibleMonths.push(`${curYear}-${mStr}`);
  }

  const pendingMonths = eligibleMonths.filter(ym => !st.processedFinancialMonths.includes(ym));
  if(pendingMonths.length === 0) return;

  const tvContract = ensureTvBroadcastContract(st);
  const socioData = typeof getSocioTorcedorMeta === 'function' ? getSocioTorcedorMeta(st) : { currentIncome: 50000 };

  pendingMonths.forEach(ym => {
    let monthTotalIncome = 0;
    let monthTotalExpenses = 0;

    // --- 1. RECEITAS MENSAIS ---
    // A. Cota de Transmissão da TV Oficial (Globo, Amazon, Record, etc.)
    if(tvContract){
      const annualTotal = Number(tvContract.annualTotal) || 11000000;
      let monthlyTv = Number(tvContract.monthly) || Math.round(annualTotal / 12);
      if(tvContract.advancedTaken){
        monthlyTv = Math.round(monthlyTv * 0.55);
      }
      if(monthlyTv > 0){
        st.balance = (Number(st.balance) || 0) + monthlyTv;
        st.income = (Number(st.income) || 0) + monthlyTv;
        monthTotalIncome += monthlyTv;

        tvContract.monthsPaid = (Number(tvContract.monthsPaid) || 0) + 1;
        tvContract.totalPaidToClub = (Number(tvContract.totalPaidToClub) || 0) + monthlyTv;

        st.news = Array.isArray(st.news) ? st.news : [];
        st.news.unshift(`📺 Cota de Transmissão (${tvContract.name}): +${fmtMoney(monthlyTv)} creditada no caixa do clube (${ym}).`);
      }
    }

    // B. Patrocínios Oficiais (Master, Mangas, Costas)
    ['master', 'sleeves', 'back'].forEach(slot => {
      const sp = st.sponsors?.[slot];
      if(sp && Number(sp.monthly) > 0){
        const spMonthly = Number(sp.monthly);
        st.balance = (Number(st.balance) || 0) + spMonthly;
        st.income = (Number(st.income) || 0) + spMonthly;
        monthTotalIncome += spMonthly;

        const curRemMonths = Number(sp.monthsRemaining ?? sp.contractMonthsRemaining ?? (Number(sp.years || sp.contractYears || 1) * 12));
        sp.monthsRemaining = Math.max(0, curRemMonths - 1);
        sp.contractMonthsRemaining = sp.monthsRemaining;
        sp.monthsPaid = (Number(sp.monthsPaid) || 0) + 1;
        sp.totalPaidToClub = (Number(sp.totalPaidToClub) || 0) + spMonthly;

        st.news = Array.isArray(st.news) ? st.news : [];
        st.news.unshift(`💰 Patrocínio (${sp.brand || sp.name || slot}): +${fmtMoney(spMonthly)} creditado no caixa (${ym}).`);
      }
    });

    // C. Sócio-Torcedor Mensal
    const socioIncome = Number(socioData.currentIncome) || 0;
    if(socioIncome > 0){
      st.balance = (Number(st.balance) || 0) + socioIncome;
      st.income = (Number(st.income) || 0) + socioIncome;
      monthTotalIncome += socioIncome;
    }

    // D. Naming Rights
    if(st.namingRights && Number(st.namingRights.monthsRemaining) > 0){
      const namingVal = Math.max(0, Number(state?.namingRights?.monthlyValue || st.namingRights.monthlyValue) || 0);
      if(namingVal > 0){
        st.balance = (Number(st.balance) || 0) + namingVal;
        st.income = (Number(st.income) || 0) + namingVal;
        monthTotalIncome += namingVal;
        st.namingRights.monthsRemaining = Math.max(0, st.namingRights.monthsRemaining - 1);
      }
    }

    // E. Estruturas e Bônus Administrativo
    const adminBonus = Math.round(totalSponsorMonthly(st) * 0.03 * (st.infrastructure?.admin?.level || 1));
    const facIncome = typeof monthlyFacilityIncome === 'function' ? monthlyFacilityIncome(st) : 0;
    const structureExtras = adminBonus + facIncome;
    if(structureExtras > 0){
      st.balance = (Number(st.balance) || 0) + structureExtras;
      st.income = (Number(st.income) || 0) + structureExtras;
      monthTotalIncome += structureExtras;
    }

    // --- 2. DESPESAS MENSAIS (CONTAS DO CLUBE) ---
    // A. Salários do Elenco
    const squadPayroll = typeof totalMonthlyPayroll === 'function' ? totalMonthlyPayroll() : 0;
    if(squadPayroll > 0){
      st.balance = (Number(st.balance) || 0) - squadPayroll;
      st.expense = (Number(st.expense) || 0) + squadPayroll;
      monthTotalExpenses += squadPayroll;
      st.news = Array.isArray(st.news) ? st.news : [];
      st.news.unshift(`👥 Pagamento de Salários: Folha do elenco (-${fmtMoney(squadPayroll)}) quitada ref. ${ym}.`);
    }

    // B. Manutenção & Staff
    const facilitiesExp = typeof totalFacilitiesMonthlyExpense === 'function' ? totalFacilitiesMonthlyExpense(st) : 0;
    if(facilitiesExp > 0){
      st.balance = (Number(st.balance) || 0) - facilitiesExp;
      st.expense = (Number(st.expense) || 0) + facilitiesExp;
      monthTotalExpenses += facilitiesExp;
    }

    // C. Salários dos Olheiros
    const scoutExp = typeof getMonthlyScoutPayroll === 'function' ? getMonthlyScoutPayroll(st) : 0;
    if(scoutExp > 0){
      st.balance = (Number(st.balance) || 0) - scoutExp;
      st.expense = (Number(st.expense) || 0) + scoutExp;
      monthTotalExpenses += scoutExp;
    }

    // D. Marketing Mensal (respeita piso reduzido de R$ 5k/sem para clube criado iniciante)
    const minMktWeekly = (st.isCustomClub || st.customClub?.isCustom)
      ? 5000
      : (typeof MARKETING_MINIMUM_WEEKLY !== 'undefined' ? MARKETING_MINIMUM_WEEKLY : 36000);
    const mktWeekly = Math.max(minMktWeekly, Number(st.marketingWeekly) || minMktWeekly);
    const mktMonthly = mktWeekly * 4;
    if(mktMonthly > 0){
      st.balance = (Number(st.balance) || 0) - mktMonthly;
      st.expense = (Number(st.expense) || 0) + mktMonthly;
      monthTotalExpenses += mktMonthly;
    }

    // E. Parcelas de Obras do Estádio
    if(st.stadiumRingData?.debt && st.stadiumRingData.debt.remaining > 0){
      const inst = Math.min(st.stadiumRingData.debt.remaining, Number(st.stadiumRingData.debt.monthly) || 0);
      if(inst > 0){
        st.balance = (Number(st.balance) || 0) - inst;
        st.debtPrincipalPaid = (Number(st.debtPrincipalPaid) || 0) + inst;
        st.stadiumRingData.debt.remaining = Math.max(0, st.stadiumRingData.debt.remaining - inst);
        st.stadiumRingData.debt.monthsLeft = Math.max(0, (Number(st.stadiumRingData.debt.monthsLeft) || 1) - 1);
        monthTotalExpenses += inst;
      }
    }

    // F. Parcelas Bancárias
    if(window.AFM_Guards && typeof window.AFM_Guards.processMonthlyBankInstallments === 'function'){
      try { window.AFM_Guards.processMonthlyBankInstallments(st, ym); } catch(e){}
    }

    // G & H. Economia Pessoal Mensal Isolada por Modo (Treinador vs Jogador)
    const isPlayerCareerNow = Boolean(
      st.gameMode === 'player' ||
      st.isPlayerMode === true ||
      (typeof window !== 'undefined' && window.isPlayerCareerActive?.(st))
    );
    if(isPlayerCareerNow){
      if(typeof window !== 'undefined' && window.AFM_PlayerEngine){
        if(typeof window.AFM_PlayerEngine.processMonthlyPlayerFinances === 'function'){
          try { window.AFM_PlayerEngine.processMonthlyPlayerFinances(st, `${ym}-01`); } catch(e){}
        }
        if(typeof window.AFM_PlayerEngine.processMonthlyAttributeTraining === 'function'){
          try { window.AFM_PlayerEngine.processMonthlyAttributeTraining(st, ym); } catch(e){}
        }
      }
    } else {
      if(window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.processMonthlyLifeAndDividendsTurn === 'function'){
        try { window.AFM_LifeAndSharesPro.processMonthlyLifeAndDividendsTurn(st, ym); } catch(e){}
      } else if(window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.payMonthlyCoachSalary === 'function'){
        try { window.AFM_LifeAndSharesPro.payMonthlyCoachSalary(st); } catch(e){}
      } else {
        const salary = Math.max(0, Number(st.managerSalary) || 9500);
        st.managerMoney = (Number(st.managerMoney) || 0) + salary;
        if(st.career) st.career.cash = st.managerMoney;
        st.managerFinanceHistory = Array.isArray(st.managerFinanceHistory) ? st.managerFinanceHistory : [];
        st.managerFinanceHistory.unshift({ date: st.date, desc: `Salário mensal de técnico (${st.club})`, amount: salary });
      }
    }

    // I. Rotina de Treinamento CT e Desgaste
    if(typeof applyMonthlyTrainingAndCommercial === 'function'){
      try { applyMonthlyTrainingAndCommercial(); } catch(e){}
    }
    st.stadiumMaintenance = Math.max(10, (st.stadiumMaintenance || 90) - 2);

    // Marca o mês como processado com segurança
    st.processedFinancialMonths.push(ym);

    // Notícia consolidada do fechamento
    st.news = Array.isArray(st.news) ? st.news : [];
    const netMonth = monthTotalIncome - monthTotalExpenses;
    st.news.unshift(`📒 BALANÇO FINANCEIRO DE ${ym}: Receitas (+${fmtMoney(monthTotalIncome)}) | Despesas (-${fmtMoney(monthTotalExpenses)}) | Resultado: ${netMonth >= 0 ? '+' : ''}${fmtMoney(netMonth)}.`);
    st.news = st.news.slice(0, 50);
  });
}
if(typeof window !== 'undefined'){
  window.processClubMonthlyFinances = processClubMonthlyFinances;
}

function processFitness(){
  const starters=new Set(state.lineup||[]);
  for(const p of state.squad){
    if(!p) continue;
    const isCtrl = Boolean(p.isControlled || p.isControlledAthlete || (state.controlledPlayerId != null && String(p.id) === String(state.controlledPlayerId)));
    if(!isCtrl){
      const med=state.infrastructure?.medical?.level||1;
      const isStarter = starters.has(playerKey(p));

      // Recuperação ou Desgaste Físico
      p.fitness = clamp((p.fitness??100) + (isStarter ? -(rnd(3,7)) + med : 5 + med), 55, 100);

      // Fadiga acumulada se jogar muitas rodadas seguidas
      if(isStarter){
        p.consecutiveStarts = (p.consecutiveStarts || 0) + 1;
        if(p.consecutiveStarts >= 3){
          p.fitness = clamp(p.fitness - 4, 45, 100);
        }
      } else {
        p.consecutiveStarts = 0;
      }

      // Veteranos de 34+ anos recuperam físico mais devagar
      if((p.age || 25) >= 34){
        p.fitness = clamp(p.fitness - 2, 45, 100);
      }

      // Moral do jogador
      p.morale = p.morale || 75;
      if(isStarter){
        p.morale = clamp(p.morale + rnd(1, 3), 35, 100);
      } else {
        if(playerOverall(p) >= 72){
          p.morale = clamp(p.morale - 2, 25, 100);
        }
      }
    } else if(typeof p.energy === 'number' && Number.isFinite(p.energy)){
      p.fitness = clamp(Math.round(p.energy), 0, 100);
    }

    // Recuperação de Lesões
    if(p.injuredRounds && p.injuredRounds > 0){
      p.injuredRounds--;
      if(p.injuredRounds <= 0){
        delete p.injuredRounds;
        delete p.injuryDesc;
        state.news.unshift(`🩺 ALTA MÉDICA: ${p.name} recuperou-se 100% da lesão e foi reintegrado ao elenco!`);
      }
    }

    // Cumprimento de Suspensão
    if(p.suspended && p.suspended > 0){
      p.suspended--;
      if(p.suspended <= 0){
        p.suspended = 0;
      }
    }
  }
}

function processDevelopment(){
  if(window.AFM_PlayerXPEvolution && typeof window.AFM_PlayerXPEvolution.processMonthlyTrainingXP === 'function'){
    window.AFM_PlayerXPEvolution.processMonthlyTrainingXP(state);
  }
  if(state.round%4!==0)return;
  const isCtrl = p => Boolean(p && (p.isControlled || p.isControlledAthlete || (state.controlledPlayerId != null && String(p.id) === String(state.controlledPlayerId))));
  const lvl=state.infrastructure?.training?.level||1;
  const starters = new Set(state.lineup || []);
  const candidates=state.squad.filter(p=>!isCtrl(p)&&(+p.age||25)<=25&&(p.potential||playerOverall(p))>playerOverall(p));
  const ctBonus = typeof trainingBonusPct === 'function' ? trainingBonusPct(lvl) : lvl;
  for(const p of candidates){
    const starterBonus = starters.has(playerKey(p)) ? 8 : 0;
    const ctChanceBonus = Math.round(ctBonus / 5);
    if((hashStr(playerKey(p)+'|'+state.round)%100)<8+lvl*3+starterBonus+ctChanceBonus){
      const oldOvr = playerOverall(p);
      p.fc=clamp(playerOverall(p)+1,40,p.potential||94);
      p.pes=p.pes?clamp(+p.pes+1,40,99):p.fc;
      if(starters.has(playerKey(p)) && playerOverall(p) > oldOvr){
        state.news.unshift(`⭐ EVOLUÇÃO: O jovem talento titular ${p.name} evoluiu para ${playerOverall(p)} OVR (CT Nível ${lvl} · +${ctBonus}% bônus de treino)!`);
      }
    }
  }

  // Bônus de Mentoria de Atleta Veterano
  if(state.activeMentorship && state.activeMentorship.menteeKey){
    const mentee = state.squad.find(p => playerKey(p) === state.activeMentorship.menteeKey);
    const mentor = state.squad.find(p => playerKey(p) === state.activeMentorship.mentorKey);
    if(mentee && !isCtrl(mentee) && mentor && Math.random() < 0.50 && playerOverall(mentee) < (mentee.potential || 90)){
      const old = playerOverall(mentee);
      mentee.fc = clamp(playerOverall(mentee) + 1, 40, mentee.potential || 94);
      mentee.pes = mentee.fc;
      mentee.morale = 100;
      if(playerOverall(mentee) > old){
        state.news.unshift(`🤝 MENTORIA: Sob a tutela do experiente ${mentor.name}, o jovem ${mentee.name} deu um salto para ${playerOverall(mentee)} OVR!`);
      }
    }
  }
}
if(typeof window !== 'undefined'){
  window.processFitness = processFitness;
  window.processDevelopment = processDevelopment;
}

function finalizeRound(userRes, winners, isKO){
  const comp=curComp();
  let win = false;
  let advanced = false;
  let isHome = false;
  let gf = 0;
  let ga = 0;
  // Recupera apenas um fixture válido que o chamador deixou de vincular ao resultado.
  if(!userRes){
    const scheduledUserFixture = (state.schedule?.[state.round] || []).find(g => Array.isArray(g) && (norm(g[0]) === norm(state.club) || norm(g[1]) === norm(state.club)));
    const alreadyRecorded = (state.history || []).some(h => h.competitionId === comp.id && Number(h.season) === Number(state.season) && Number(h.round) === Number(state.round + 1) && (norm(h.h) === norm(state.club) || norm(h.a) === norm(state.club)));
    if(scheduledUserFixture && !alreadyRecorded){
      const [home, away] = scheduledUserFixture;
      const [hg, ag] = simulateScore(home, away);
      applyResult(home, away, hg, ag);
      isHome = norm(home) === norm(state.club);
      gf = isHome ? hg : ag;
      ga = isHome ? ag : hg;
      const matchWinner = isKO ? (hg === ag ? (Math.random() < 0.5 ? home : away) : (hg > ag ? home : away)) : null;
      userRes = { h: home, a: away, hg, ag, winner: matchWinner, events: simulateUserGoalEvents(state.club, gf) };
      if(isKO){
        winners = Array.isArray(winners) ? winners : [];
        if(!winners.some(w => norm(w) === norm(matchWinner))) winners.push(matchWinner);
      }
      state.news.unshift(`📅 RECUPERAÇÃO DO CALENDÁRIO: a partida de ${state.club} foi simulada automaticamente para destravar a rodada (${hg} x ${ag}).`);
    }
  }
  if(userRes){
    isHome = (userRes.h === state.club) || (typeof norm === 'function' && norm(userRes.h) === norm(state.club));
    gf = isHome ? userRes.hg : userRes.ag;
    ga = isHome ? userRes.ag : userRes.hg;
    advanced=isKO?norm(userRes.winner)===norm(state.club):gf>ga;
    const draw=!isKO&&gf===ga;
    win=!isKO?gf>ga:advanced;
    let gate=0,shop=0,parkingRev=0;
    if(isHome){
      const att=attendanceProjection(userRes.a);
      gate=att.revenue;
      parkingRev=att.parkRevenue;
      shop=att.storeShop;
      state.lastHome={...att,opponent:userRes.a,date:state.date,shop,parkRevenue:parkingRev};
      state.trust.fans=clamp(state.trust.fans+ticketMoodDelta(),0,100);
    }
    const bonus=win?totalSponsorWinBonus():0;
    const roundSponsor = Math.round(totalSponsorMonthly() / 4);
    const rev=gate+parkingRev+shop+bonus+roundSponsor;
    const payroll=payrollPerRound();
    const facilitiesExp = typeof facilitiesExpensesPerRound === 'function' ? facilitiesExpensesPerRound(state) : 0;
    state.balance+=rev-payroll-facilitiesExp;
    state.income+=rev;
    state.expense+=payroll+facilitiesExp;

    // Pagamento de Bônus de Desempenho Contratuais (Vitória e Gols)
    let totalContractBonuses = 0;
    if(win){
      for(const p of state.squad){
        if(p.bonusWin && p.bonusWin > 0){
          totalContractBonuses += p.bonusWin;
        }
      }
    }
    if(gf > 0){
      for(const p of state.squad){
        if(p.bonusGoal && p.bonusGoal > 0){
          totalContractBonuses += (p.bonusGoal * gf);
        }
      }
    }
    if(totalContractBonuses > 0){
      state.balance -= totalContractBonuses;
      state.expense += totalContractBonuses;
      state.news.unshift(`💰 Pagamento de bônus aos atletas: ${fmtMoney(totalContractBonuses)} (${win ? 'bicho por vitória ' : ''}${gf > 0 ? '+ premiação por gols' : ''}).`);
    }

    const delta=win?3:draw?0:-3;
    state.trust.board=clamp(state.trust.board+delta,0,100);
    state.trust.fans=clamp(state.trust.fans+(win?4:draw?0:-4),0,100);
    state.trust.squad=clamp(state.trust.squad+(win?2:draw?0:-2),0,100);
    if(window.AFM_CoachRanking && typeof window.AFM_CoachRanking.onMatchFinished === 'function'){
      window.AFM_CoachRanking.onMatchFinished(state, userRes);
    }
    if(window.AFM_GlobalRanking && typeof window.AFM_GlobalRanking.updateConfidenceAfterMatch === 'function'){
      const derby = typeof isRivalryMatch === 'function' ? isRivalryMatch(state.club, isHome ? userRes.a : userRes.h) : false;
      window.AFM_GlobalRanking.updateConfidenceAfterMatch(state, {
        goalsFor: gf,
        goalsAgainst: ga,
        isHome,
        isDerby: derby
      });
      if(state.confidence){
        state.trust.board = state.confidence.board;
        state.trust.fans = state.confidence.fans;
        state.trust.squad = state.confidence.squad;
        state.boardConfidence = state.confidence.board;
      }
    }
    const penTxt=userRes.pens?` (${userRes.pens[0]}-${userRes.pens[1]} nos pênaltis)`:'';
    state.news.unshift(`${state.club} ${gf} x ${ga} ${isHome?userRes.a:userRes.h}${penTxt} — ${isKO?(advanced?'classificado':'eliminado'):(win?'vitória':draw?'empate':'derrota')}.`);
    if(isHome){
      if(state.parkingConcession){
        state.parkingConcession.totalEarned = (state.parkingConcession.totalEarned || 0) + parkingRev;
        state.news.unshift(`Público: ${state.lastHome.attendance.toLocaleString('pt-BR')} torcedores • Bilheteria ${fmtMoney(gate)} • Estacionamento (Repasse ${state.parkingConcession.revenueSharePct}% Concessão ${state.parkingConcession.companyName}) ${fmtMoney(parkingRev)}.`);
      } else {
        state.news.unshift(`Público: ${state.lastHome.attendance.toLocaleString('pt-BR')} torcedores • Bilheteria ${fmtMoney(gate)} • Estacionamento ${fmtMoney(parkingRev)}.`);
      }
    }
    userRes.events = Array.isArray(userRes.events) ? userRes.events.filter(event => event?.type === 'gol').slice(0, 20) : [];
    addPlayerMatchStats(comp.id, state.club, userRes.events);
    const oppClubRound = isHome ? userRes.a : userRes.h;
    if(ga > 0 && oppClubRound){
      const oppRecorded = userRes.events.filter(event => event?.type === 'gol' && norm(event.teamId) === norm(oppClubRound));
      addPlayerMatchStats(comp.id, oppClubRound, oppRecorded.length ? oppRecorded : simulateClubGoalEvents(oppClubRound, ga, comp.id));
    }
    state.history.unshift({
      ...userRes, round:state.round+1, season:Number(state.season), date:state.date,
      competitionId:comp.id, competitionName:comp.name,
      attendance:isHome?state.lastHome.attendance:null, gate:isHome?gate:null,
      parkRevenue:isHome?parkingRev:null, shop:isHome?shop:null, sponsorBonus:bonus, isHome, won:win
    });
    state.history = state.history.slice(0, 100);
    if(typeof syncCompetitionStatsComprehensive === 'function') syncCompetitionStatsComprehensive(comp.id);
    if(isKO&&!advanced){
      state.eliminated=true;
      state.knockoutEliminations = Array.isArray(state.knockoutEliminations) ? state.knockoutEliminations : [];
      const eliminationKey = `${Number(state.season)}|${comp.id}|${norm(state.club)}`;
      if(!state.knockoutEliminations.some(item => item.key === eliminationKey)){
        const eliminationRecord = { key:eliminationKey, season:Number(state.season), competitionId:comp.id, competitionName:comp.name, club:state.club, round:state.round+1, opponent:isHome?userRes.a:userRes.h, date:state.date, score:`${gf} x ${ga}` };
        state.knockoutEliminations.unshift(eliminationRecord);
        state.knockoutEliminations = state.knockoutEliminations.slice(0,100);
        openCustomModal('Fim da participação no mata-mata', `<div style="text-align:center;padding:10px"><div style="font-size:34px;margin-bottom:10px">🏆</div><h3 style="margin:0 0 10px;color:#f87171">Infelizmente, você não passou do mata-mata.</h3><p>${esc(state.club)} foi eliminado(a) da ${esc(comp.name)}.</p><p><b>${esc(eliminationRecord.opponent)}</b> · Placar ${esc(eliminationRecord.score)} · Fase ${eliminationRecord.round}</p><p class="small muted">A eliminação foi registrada no histórico desta carreira e aparecerá no encerramento da temporada.</p></div>`, null, 'Fechar', false, '560px');
      }
    }
    state.lastMatchSummary = { h: userRes.h, a: userRes.a, hg: userRes.hg, ag: userRes.ag, ga, isHome, won: win };
  }
  if(isKO){
    if(winners.length>1){
      const next=[];
      for(let i=0;i<winners.length;i+=2)if(winners[i+1])next.push([winners[i],winners[i+1]]);
      state.schedule.push(next);
      state.cupAlive=winners;
      if(advanced){
        const cupPrize = calculateCupPhasePrize(comp?.id || 'cup', `Fase ${state.round + 1}`, true, false);
        state.balance += cupPrize;
        state.income += cupPrize;
        state.news.unshift(`💰 PREMIAÇÃO DE FASE: +${fmtMoney(cupPrize)} creditados pela classificação de fase na ${comp.name}!`);
      }
    }else if(winners.length===1){
      state.cupAlive=winners;
      state.titles = state.titles || [];
      if(norm(winners[0])===norm(state.club)&&!state.titles.includes(comp.name)){
        // Bônus expressivo de sócios ao ser campeão
        if(state.socioTorcedor){
          const boost = Math.round(state.socioTorcedor.members * 0.45);
          state.socioTorcedor.members += boost;
          state.trust.fans = clamp(state.trust.fans + 25, 0, 100);
          state.news.unshift(`🏆 TÍTULO CONQUISTADO! Onda de novos sócios-torcedores invadiu o clube: +${boost.toLocaleString('pt-BR')} sócios cadastrados (+45%)!`);
        }
        state.titles.push(comp.name);
        const tourneyTitlePrize = calculateCupPhasePrize(comp?.id || 'cup', 'Final', true, true);
        if(tourneyTitlePrize > 0){
          state.balance += tourneyTitlePrize;
          state.income = (state.income || 0) + tourneyTitlePrize;
          state.news.unshift(`💰 PREMIAÇÃO DO TÍTULO: +${fmtMoney(tourneyTitlePrize)} creditados pela conquista da ${comp.name}!`);
        }
        state.news.unshift(`🏆 ${state.club} é CAMPEÃO da ${comp.name}!`);
        state.trust.board=clamp(state.trust.board+12,0,100);
        state.trust.fans=clamp(state.trust.fans+15,0,100);

        // Pagamento de Bônus de Título aos atletas com cláusula no contrato
        let totalTitleBonuses = 0;
        for(const p of state.squad){
          if(p.bonusTitle && p.bonusTitle > 0){
            totalTitleBonuses += p.bonusTitle;
          }
        }
        if(totalTitleBonuses > 0){
          state.balance -= totalTitleBonuses;
          state.expense += totalTitleBonuses;
          state.news.unshift(`🏅 Premiação de Campeão: ${fmtMoney(totalTitleBonuses)} pagos em bônus contratuais de título aos jogadores!`);
        }

        setTimeout(() => {
          showChampionTrophyCeremonyModal(comp, () => {
            save(); render();
          });
        }, 500);
      }
    }
  }
  state.round++;
  if(window.AFM_Guards && typeof window.AFM_Guards.cleanExpiredProposals === 'function'){
    window.AFM_Guards.cleanExpiredProposals(state, state.round);
  }
  if(window.AFM_GlobalRanking && typeof window.AFM_GlobalRanking.syncActiveSaveToRanking === 'function'){
    window.AFM_GlobalRanking.syncActiveSaveToRanking(state);
  }
  if(window.AFM_SquadAssistant && typeof window.AFM_SquadAssistant.applyMentorshipVeterans === 'function'){
    const mentorMsgs = window.AFM_SquadAssistant.applyMentorshipVeterans(state.squad);
    if(mentorMsgs && mentorMsgs.length){
      state.news = Array.isArray(state.news) ? state.news : [];
      mentorMsgs.forEach(m => state.news.unshift(`⭐ MENTORIA: ${m}`));
    }
  }
  if(typeof expireRoundLimitedOffers === 'function') expireRoundLimitedOffers(state.round);
  // Aporte semanal em marketing (rebalanceado por rodada)
    const mktWeeklyExp = Math.max(MARKETING_MINIMUM_WEEKLY, Number(state.marketingWeekly) || 36000);
  state.balance -= mktWeeklyExp;
  state.expense += mktWeeklyExp;
  applyMatchIncidents(state.lastMatchSummary || null);
  if(userRes && window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.processRoundMatchStats === 'function'){
    window.AFM_MarketLupaAndAging.processRoundMatchStats(state, { h: userRes.h, a: userRes.a, hg: userRes.hg, ag: userRes.ag, gf, ga, won: win, events: userRes.events });
  }
  if(typeof processFitness === 'function') processFitness();
  if(typeof processDevelopment === 'function') processDevelopment();
  processYouthDevelopment();
  processBankLoansOnRound();
  if(window.AFM30){
    try {
      window.AFM30.advanceTraining(state);
      window.AFM30.simulateYouthAcademy(state);
      window.AFM30.financialAudit(state);
      if(win){
        window.AFM30.audio.playCheer();
      } else {
        window.AFM30.audio.playWhistle();
      }
    } catch(err){
      recordAFMError('game-round-cycle', err);
      console.warn('AFM30 round cycle error:', err);
    }
  }

  // Avança a data respeitando partidas adicionais na mesma data
  advanceDateAfterMatch(state);

  if(typeof window !== 'undefined' && window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.processRoundTurn === 'function'){
    window.AFM_LifeAndSharesPro.processRoundTurn(state);
  }

  // Verifica se o clube recebe novas propostas de patrocínio com base na fama e fase do time
  if(state.round % 3 === 0 || Math.random() < 0.40){
    checkNewSponsorOffer();
  }

  // Propostas de aluguel do estádio e convites para shows musicais / festivais
  // One stadium rental/show opportunity every four rounds. Legacy saves without
  // metadata start their cooldown on the first proposal after this migration.
  const lastStadiumOfferRound = Number(state.lastStadiumCommercialOfferRound);
  if(!state.stadiumClubRental && !state.stadiumEventProposal &&
     (!Number.isFinite(lastStadiumOfferRound) || state.round < lastStadiumOfferRound || state.round - lastStadiumOfferRound >= 4)){
    if(state.lastStadiumCommercialOfferType !== 'show') generateStadiumEventProposal();
    else generateStadiumRentalProposal();
  }

  // Atualiza propostas de mercado para jogadores colocados à venda ou para empréstimo
  let newOffersCount = 0;
  const incomingOfferAlerts = [];
  state.transferOffers = state.transferOffers || {};
  state.loanOffers = state.loanOffers || {};
  // 1. Sincroniza atletas com 6 meses ou menos de contrato para a lista de venda
  syncExpiringContractsToTransferList(state);

  // 2. Propostas de Compra Definitiva: chegam gradualmente no decorrer das rodadas
  (state.transferListed || []).forEach(k => {
    const p = state.squad.find(q => playerKey(q) === k);
    if(p && !p.isLoan){
      state.transferOffers[k] = Array.isArray(state.transferOffers[k]) ? state.transferOffers[k] : [];
      if(state.transferOffers[k].length < 3){
        const ovr = playerOverall(p);
        const winOpen = isTransferWindowOpen(state.date);
        const chance = (winOpen ? 0.60 : 0.20) + (ovr >= 80 ? 0.15 : (ovr >= 72 ? 0.05 : -0.10));
        if(Math.random() < chance){
          const usedBuyers = state.transferOffers[k].map(o => o.buyer);
          const newOffer = generateSingleBuyerOffer(p, usedBuyers);
          if(newOffer){
            state.transferOffers[k].push(newOffer);
            newOffersCount++;
            state.news.unshift(`📬 MERCADO: O ${newOffer.buyer} enviou uma proposta oficial de ${fmtMoney(newOffer.price)} por ${p.name}!`);
            incomingOfferAlerts.push(`${p.name}: ${newOffer.buyer} ofereceu ${fmtMoney(newOffer.price)}`);
          }
        }
      }
    }
  });

  // 3. Propostas de Empréstimo: chegam gradualmente no decorrer das rodadas
  (state.loanListed || []).forEach(k => {
    const p = state.squad.find(q => playerKey(q) === k);
    if(p && !p.isLoan){
      state.loanOffers[k] = Array.isArray(state.loanOffers[k]) ? state.loanOffers[k] : [];
      if(state.loanOffers[k].length < 2){
        const chance = isTransferWindowOpen(state.date) ? 0.50 : 0.15;
        if(Math.random() < chance){
          const usedBuyers = state.loanOffers[k].map(o => o.buyer);
          const newOffer = generateSingleLoanOffer(p, usedBuyers);
          if(newOffer){
            state.loanOffers[k].push(newOffer);
            newOffersCount++;
            state.news.unshift(`🤝 EMPRÉSTIMO: O ${newOffer.buyer} enviou proposta para levar ${p.name} por empréstimo com taxa de ${fmtMoney(newOffer.fee)}!`);
            incomingOfferAlerts.push(`${p.name}: ${newOffer.buyer} propôs empréstimo (${fmtMoney(newOffer.fee)})`);
          }
        }
      }
    }
  });

  // 4. Limpa ofertas de atletas que não estão mais listados
  Object.keys(state.transferOffers).forEach(k => {
    if(!(state.transferListed || []).includes(k)) delete state.transferOffers[k];
  });
  Object.keys(state.loanOffers).forEach(k => {
    if(!(state.loanListed || []).includes(k)) delete state.loanOffers[k];
  });

  const listedKeys = []; if(false)
  for(const k of listedKeys){
    const p = state.squad.find(q => playerKey(q) === k);
    if(p){
      state.transferOffers[k] = generateBuyerOffers(p);
      state.loanOffers[k] = generateLoanOffers(p);
      newOffersCount++;
    }
  }
  if(newOffersCount > 0){
    state.news.unshift(`📬 Chegaram novas propostas de compra e empréstimo para seus jogadores na lista de transferências!`);
    const visibleAlerts = incomingOfferAlerts.slice(0, 2);
    const remainingAlerts = incomingOfferAlerts.length - visibleAlerts.length;
    toast(`📬 ${visibleAlerts.join(' • ')}${remainingAlerts > 0 ? ` • +${remainingAlerts} proposta(s)` : ''}`);
  }

  // 1. Simulação do Mercado Vivo da IA (Clubes da CPU negociam entre si)
  simulateAITransfers();

  // 2. Propostas Espontâneas da IA para Titulares do Usuário
  checkIncomingPlayerBids();

  // 3. Atualização das Estatísticas de Carreira do Treinador
  updateManagerCareerStats(userRes);

  // 4. Rede Social do Clube ("Voz da Torcida")
  updateFansSocialFeed(userRes);

  // 5. Fair Play Financeiro & Trava de Contratações se Dívida Estiver Atrasada
  checkFinancialFairPlay();

  if(state.round%4===0){
    try {
      const ymKey = state.date ? state.date.slice(0, 7) : `${state.season || 2026}-${Math.floor(state.round / 4) + 1}`;
      if(window.AFM_ManagerEconomy && typeof window.AFM_ManagerEconomy.processMonthlyTurn === 'function'){
        const econRes = window.AFM_ManagerEconomy.processMonthlyTurn(state);
        if(econRes && econRes.totalBusinessNet !== 0){
          state.news = Array.isArray(state.news) ? state.news : [];
          state.news.unshift(`💼 NEGÓCIOS DO TREINADOR: Fechamento mensal! Resultado líquido de seus empreendimentos: ${econRes.totalBusinessNet >= 0 ? '+' : ''}${fmtMoney(econRes.totalBusinessNet)}.`);
        }
      }
      if(window.AFM_Guards && typeof window.AFM_Guards.processMonthlyBankInstallments === 'function'){
        window.AFM_Guards.processMonthlyBankInstallments(state, ymKey);
      }
    } catch(err) {
      console.warn('Erro na virada mensal de economia:', err);
    }
    // Resfriamento de contrato com a diretoria (1 mês / 4 rodadas)
    if(state.managerContractCooldownRound && state.round >= state.managerContractCooldownRound){
      state.managerContractCooldownRound = null;
      state.news.unshift(`💼 DIRETORIA: O resfriamento de 1 mês terminou! Você pode propor nova renovação de contrato no Escritório.`);
    }

    const adminBonus=Math.round(totalSponsorMonthly()*.03*(state.infrastructure?.admin?.level||1));
    const fac=monthlyFacilityIncome();
    const extras=adminBonus+fac;
    if(extras > 0){
      state.balance+=extras;
      state.income+=extras;
      state.news.unshift(`Receitas extras de estruturas e bônus comercial (+${fmtMoney(extras)}) creditadas.`);
    }

    // Cotas de Direitos de Transmissão de TV Mensais (Realismo)
    const tvRights = comp.id === 'bra-a' ? 2200000 : comp.id === 'bra-b' ? 850000 : 350000;
    state.balance += tvRights;
    state.income += tvRights;
    state.news.unshift(`📺 Cotas de Transmissão de TV (+${fmtMoney(tvRights)}) creditadas na conta do clube.`);

    // Progresso das missões do Olheiro
    if(state.scoutMissions && state.scoutMissions.length > 0){
      state.scoutMissions.forEach(m => {
        m.roundsLeft--;
      });
      const finishedMissions = state.scoutMissions.filter(m => m.roundsLeft <= 0);
      state.scoutMissions = state.scoutMissions.filter(m => m.roundsLeft > 0);

      finishedMissions.forEach(m => {
        state.scoutReports = state.scoutReports || [];
        if(m.type === 'player'){
          const p = marketUniverse().find(x => playerKey(x) === m.playerKey);
          if(p){
            const minPot = (p.potential || playerOverall(p) + 4);
            const maxPot = minPot + 4;
            const rep = {
              date: state.date,
              type: 'player',
              playerKey: m.playerKey,
              name: p.name,
              club: p.club,
              pos: p.pos,
              age: p.age,
              overall: playerOverall(p),
              potentialRange: `${minPot} a ${maxPot} ⭐ (Potencial Revelado)`,
              contract: `Salário de ${fmtMoney(p.salary || Math.round(playerOverall(p)*650))}/mês • Vínculo até 2028`,
              seasonStatus: `${rnd(14,24)} jogos disputados • ${rnd(4,12)} gols • Média 7.${rnd(2,8)}`,
              injuryStatus: Math.random() < 0.2 ? 'Histórico recente de estiramento muscular (Atenção)' : '100% Íntegro • Excelente condição clínica'
            };
            state.scoutReports.unshift(rep);
            state.news.unshift(`🔍 RELATÓRIO DO OLHEIRO: Chegou a análise completa de ${p.name}! Consulte na aba Mercado > Olheiro.`);
          }
        } else if(m.type === 'promises'){
          let pool = marketUniverse().filter(p => (+p.age || 20) <= (m.age || 20));
          if(m.sector && m.sector !== 'all'){
            if(m.sector === 'GOL') pool = pool.filter(p => p.isGK || p.pos === 'GK');
            else if(m.sector === 'DEF') pool = pool.filter(p => ['CB', 'LB', 'RB', 'DF'].includes(p.pos));
            else if(m.sector === 'MEI') pool = pool.filter(p => ['DM', 'CM', 'AM', 'MF'].includes(p.pos));
            else if(m.sector === 'ATA') pool = pool.filter(p => ['ST', 'CF', 'RW', 'LW', 'FW'].includes(p.pos));
          }
          if(pool.length === 0) pool = marketUniverse().filter(p => (+p.age || 20) <= (m.age || 20));

          if(m.tier === 'normal'){
            // Promessas acessíveis para times menores (até R$ 2.5 Mi)
            let sub = pool.filter(p => calcValueMi(p) <= 2.5);
            if(sub.length >= 5) pool = sub;
          } else if(m.tier === 'bom'){
            // Promessas nacionais (R$ 2.5 Mi a R$ 22 Mi)
            let sub = pool.filter(p => calcValueMi(p) > 2.0 && calcValueMi(p) <= 22.0);
            if(sub.length >= 5) pool = sub;
          } else if(m.tier === 'elite'){
            // Elite internacional
            let sub = pool.filter(p => calcValueMi(p) > 20.0 || (+p.potential||playerOverall(p)) >= 85);
            if(sub.length >= 5) pool = sub;
          }

          const candidates = pool
            .sort((a,b) => (b.potential || playerOverall(b)) - (a.potential || playerOverall(a)))
            .slice(0, 5);

          candidates.forEach(cand => {
            const minPot = (cand.potential || playerOverall(cand) + 4);
            state.scoutReports.unshift({
              date: state.date,
              type: 'promise',
              tierName: m.tierName || 'Olheiro',
              playerKey: playerKey(cand),
              name: cand.name,
              club: cand.club,
              pos: cand.pos,
              age: cand.age,
              overall: playerOverall(cand),
              potentialRange: `${minPot} a ${minPot+4} ⭐ JOVEM DE OURO`,
              contract: `Contrato de Base / Transição • Valor de Mercado: ${fmtMoney(calcValueMi(cand)*1e6)}`,
              seasonStatus: 'Destaque mapeado pelo olheiro com relatório detalhado de rendimento',
              injuryStatus: 'Apto para transição profissional imediata'
            });
          });
          state.news.unshift(`🎯 RELATÓRIO DO OLHEIRO: A busca de promessas foi concluída (${m.tierName||'Olheiro'})! 5 jovens talentos foram mapeados para o clube.`);
        }
      });
    }

    // Progresso da Nova Arena
    if(state.newArenaData && state.newArenaData.underConstruction){
      state.newArenaData.roundsRemaining--;
      if(state.newArenaData.roundsRemaining <= 0){
        state.newArenaData.underConstruction = false;
        state.infrastructure.stadium.capacity = state.newArenaData.capacity;
        state.news.unshift(`🎉 INAUGURAÇÃO HISTÓRICA: A ${state.newArenaData.name} está pronta! O clube se muda com festa monumental da torcida!`);
        state.trust.fans = 100;
      }
    }

    // Cobrança mensal de parcelas de obras do estádio / arena
    if(state.stadiumRingData?.debt && state.stadiumRingData.debt.remaining > 0){
      const inst = Math.min(state.stadiumRingData.debt.remaining, state.stadiumRingData.debt.monthly);
      state.balance -= inst;
      state.debtPrincipalPaid = (state.debtPrincipalPaid || 0) + inst;
      state.stadiumRingData.debt.remaining = Math.max(0, state.stadiumRingData.debt.remaining - inst);
      state.stadiumRingData.debt.monthsLeft = Math.max(0, (state.stadiumRingData.debt.monthsLeft || 1) - 1);
      state.news.unshift(`🏗️ Parcela da obra do estádio (-${fmtMoney(inst)}) debitada no dia 1º.`);
    }

    // Receita mensal do Sócio-Torcedor creditada no caixa
    const socioData = getSocioTorcedorMeta();
    state.balance += socioData.currentIncome;
    state.income += socioData.currentIncome;
    state.news.unshift(`🎟️ Receita mensal de Sócio-Torcedor (+${fmtMoney(socioData.currentIncome)}) creditada no caixa.`);

    // Rotina mensal de CT (evolução de overall dos jogadores), Naming Rights e Loja Oficial
    applyMonthlyTrainingAndCommercial();

    // Desgaste natural do estádio nos jogos
    state.stadiumMaintenance = Math.max(10, (state.stadiumMaintenance || 90) - 2);

    // Todas as propostas de aluguel e shows são geradas pelo calendário
    // compartilhado de quatro rodadas em finalizeRound(). Não duplicar aqui:
    // a rotina mensal anterior permitia ignorar o intervalo econômico.

    // O pagamento é idempotente por mês e mantém a conta nova e a legada sincronizadas.
    if(window.AFM_LifeAndSharesPro?.payMonthlyCoachSalary){
      window.AFM_LifeAndSharesPro.payMonthlyCoachSalary(state);
    } else {
      if(typeof window.syncCoachSalaryWithLicenses === 'function') window.syncCoachSalaryWithLicenses(state);
      const salary = Math.max(0, Number(state.managerSalary) || 9500);
      state.managerMoney = (Number(state.managerMoney) || 0) + salary;
      state.managerFinanceHistory = Array.isArray(state.managerFinanceHistory) ? state.managerFinanceHistory : [];
      state.managerFinanceHistory.unshift({ date: state.date, desc: `Salário mensal de técnico (${state.club})`, amount: salary });
    }
    state.news.unshift(`📢 Ciclo mensal concluído: finanças, receitas de patrocinadores e relatórios comerciais atualizados.`);
  }

  // Checa fim de temporada
  const maxRounds = comp.rounds || (state.schedule?.length || 38);
  if(state.round >= maxRounds){
    const proceedSeasonEnd = () => {
      const pendingCompetitions = typeof getPendingClubCompetitions === 'function' ? getPendingClubCompetitions(state) : [];
      const pos = position();
      if(pendingCompetitions.length){
        const next = pendingCompetitions[0];
        state.news = Array.isArray(state.news) ? state.news : [];
        state.news.unshift(`📅 TEMPORADA EM ANDAMENTO: o campeonato principal acabou, mas ainda falta ${next.name}${next.detail ? ` (${next.detail})` : ''}${next.date ? ` em ${formatDatePtBr(next.date)}` : ''}. A virada do ano ficará bloqueada até concluir todas as competições.`);
        state.news = state.news.slice(0, 50);
        setTimeout(() => { view = 'calendario'; save(); render(); toast(`Próxima competição pendente: ${next.name}.`); }, 400);
      } else if(pos === 1){
        setTimeout(() => {
          showChampionTrophyCeremonyModal(comp, () => {
            showEndOfSeasonModal();
          });
        }, 500);
      } else {
        setTimeout(showEndOfSeasonModal, 400);
      }
    };

    // Coletiva de imprensa pós-partida com 3 perguntas olhando o placar
    if(userRes && typeof openPostMatchInterviewModal === 'function'){
      const isHomeFinal = (userRes.h === state.club) || (typeof norm === 'function' && norm(userRes.h) === norm(state.club));
      setTimeout(()=>{
        openPostMatchInterviewModal({
          gf: isHomeFinal ? userRes.hg : userRes.ag,
          ga: isHomeFinal ? userRes.ag : userRes.hg,
          opponent: isHomeFinal ? userRes.a : userRes.h
        }, proceedSeasonEnd);
      }, 400);
    } else {
      proceedSeasonEnd();
    }
  }

  state.preMatchInterviewDone = false;
  save();
  render();
}

