function simulateAITransfers(){
  if(!state) return;
  state.marketWorldFeed = state.marketWorldFeed || [];

  if(!isTransferWindowOpen(state.date) && Math.random() < 0.65) return;

  const allClubs = (window.BASE_CLUBS || []).filter(c => norm(c.name) !== norm(state.club));
  if(allClubs.length < 2) return;

  const count = rnd(1, 3);
  for(let i=0; i<count; i++){
    const buyer = allClubs[rnd(0, allClubs.length - 1)];
    const seller = allClubs.filter(c => c !== buyer)[rnd(0, allClubs.length - 2)];
    if(!buyer || !seller) continue;

    const firstNames = ['Enzo', 'Gabriel', 'Rodrigo', 'Arthur', 'Felipe', 'Matheus', 'Lucas', 'Thiago', 'Guilherme', 'Bruno', 'Nicolas', 'Gustavo', 'Luan'];
    const lastNames = ['Silva', 'Santos', 'Oliveira', 'Ferreira', 'Souza', 'Almeida', 'Pereira', 'Ribeiro', 'Costa', 'Rodrigues', 'Barbosa', 'Carvalho'];
    const pName = `${firstNames[rnd(0, firstNames.length - 1)]} ${lastNames[rnd(0, lastNames.length - 1)]}`;
    const pos = ['CB', 'LB', 'RB', 'CM', 'RW', 'LW', 'ST'][rnd(0, 6)];
    const ovr = rnd(66, 84);
    const fee = Math.round(rnd(15, 65) * 1000000);

    state.marketWorldFeed.unshift({
      date: state.date,
      playerName: pName,
      pos,
      ovr,
      buyer: buyer.name,
      seller: seller.name,
      fee
    });
  }

  if(state.marketWorldFeed.length > 30){
    state.marketWorldFeed = state.marketWorldFeed.slice(0, 30);
  }

  // Melhoria 10: Processamento de Cláusulas de Venda Futura (Sell-On 20%)
  if(Array.isArray(state.futureSaleClauses) && state.futureSaleClauses.length > 0 && Math.random() < 0.22){
    const cIdx = rnd(0, state.futureSaleClauses.length - 1);
    const clause = state.futureSaleClauses[cIdx];
    if(clause){
      const euroClubs = ['Real Madrid', 'Manchester City', 'Arsenal', 'Paris SG', 'Bayern de Munique', 'Chelsea', 'Juventus', 'Sporting CP', 'Benfica', 'Porto', 'Al-Hilal', 'Inter de Milão'];
      const destClub = euroClubs[rnd(0, euroClubs.length - 1)];
      const initialPrice = clause.initialPrice !== undefined && clause.initialPrice !== null ? Number(clause.initialPrice) : Number(clause.originalFee);
      const baseVal = Number.isFinite(initialPrice) && initialPrice > 0 ? initialPrice : 12000000;
      const resoldFee = Math.round(baseVal * (rnd(135, 275) / 100));
      const pctRaw = clause.sharePct !== undefined && clause.sharePct !== null ? Number(clause.sharePct) : (clause.sellOnPct !== undefined && clause.sellOnPct !== null ? Number(clause.sellOnPct) : 20);
      const pct = Number.isFinite(pctRaw) ? Math.max(0, Math.min(100, pctRaw)) : 20;
      const sellOnPct = pct / 100;
      const myProfit = Math.round(resoldFee * sellOnPct);

      state.balance = (state.balance || 0) + myProfit;
      state.income = (state.income || 0) + myProfit;
      state.news = state.news || [];
      state.news.unshift(`💰 VENDA FUTURA CONFIRMADA! ${clause.buyer || clause.club || 'O clube comprador'} revendeu ${clause.playerName} para o ${destClub} por ${fmtMoney(resoldFee)}. Seu clube recebeu ${fmtMoney(myProfit)} referente aos ${pct}% da cláusula de revenda!`);
      if(state.news.length > 50) state.news = state.news.slice(0, 50);

      state.marketWorldFeed = Array.isArray(state.marketWorldFeed) ? state.marketWorldFeed : [];
      state.marketWorldFeed.unshift({
        date: state.date,
        playerName: clause.playerName,
        pos: 'EX-ATLETA',
        ovr: 82,
        buyer: destClub,
        seller: clause.buyer,
        fee: resoldFee
      });
      state.marketWorldFeed = state.marketWorldFeed.slice(0, 30);

      toast(`💰 Cláusula de Revenda: +${fmtMoney(myProfit)} em caixa pela venda de ${clause.playerName} ao ${destClub}!`);
      try { window.AFM30?.audio?.playCoin?.(); } catch(e){ window.AFMErrorLog?.recordHandled(e, 'audio.playCoin'); }

      // Notificação em destaque e Modal Oficial de Direitos Econômicos
      setTimeout(() => {
        showSellOnFeeNotificationModal(clause, destClub, resoldFee, myProfit);
      }, 500);

      // Remove a cláusula concretizada
      state.futureSaleClauses.splice(cIdx, 1);
    }
  }
}

function shuffle(array){
  if(!Array.isArray(array)) return array;
  for(let i = array.length - 1; i > 0; i--){
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}
if(typeof window !== 'undefined') window.shuffle = shuffle;

function checkIncomingPlayerBids(){
  if(!state || !state.squad || !state.squad.length) return;

  // Investidas extraordinárias do mercado árabe, restritas às janelas oficiais.
  if(isTransferWindowOpen(state.date) && Math.random() < 0.28){
    const arabicClubs = ['Al-Hilal', 'Al-Nassr', 'Al-Ittihad', 'Al-Ahli', 'Al-Sadd', 'Al-Ain'];
    const lineupKeys = state.lineup || [];
    const candidates = state.squad.filter(p => {
      const ovr = playerOverall(p);
      return (lineupKeys.includes(playerKey(p)) || ovr >= 80 || Number(p.goals) >= 8 || Number(p.averageRating || p.rating) >= 7.2)
        && !p.injuryDays && !p.injuredRounds && !p.pendingTransfer && !p.isSold;
    }).sort((a,b) => {
      const score = p => playerOverall(p) * 2 + Math.min(24, Number(p.goals) || 0) + Math.max(0, Number(p.averageRating || p.rating) - 6) * 5 + ((Number(p.age) || 25) >= 29 ? 4 : 0);
      return score(b) - score(a);
    });
    const arabicTarget = candidates[0];
    if(arabicTarget){
      state.incomingBids = Array.isArray(state.incomingBids) ? state.incomingBids : [];
      const targetKey = playerKey(arabicTarget);
      if(!state.incomingBids.some(b => b.playerKey === targetKey && b.offerType === 'arabic')){
        const availableBuyers = arabicClubs.filter(c => norm(c) !== norm(state.club));
        const buyer = availableBuyers[rnd(0, availableBuyers.length - 1)];
        const baseValue = Math.max(50000, Math.round(calcValueMi(arabicTarget) * 1000000));
        const transferMultiplier = Math.round((1.5 + Math.random() * 1.5) * 100) / 100;
        const salaryMultiplier = rnd(3, 5);
        const fee = Math.round(baseValue * transferMultiplier);
        const offeredSalary = Math.round(playerSalary(arabicTarget) * salaryMultiplier);
        state.incomingBids = state.incomingBids.filter(b => b.playerKey !== targetKey);
        state.incomingBids.unshift({
          id: `arabic_bid_${Date.now()}_${Math.floor(Math.random() * 100000)}`,
          date: state.date, playerKey: targetKey, playerName: arabicTarget.name,
          ovr: playerOverall(arabicTarget), club: buyer, fee, sellOnPct: 0,
          counterOffered: false, offerType: 'arabic', transferMultiplier,
          receivedRound: Number(state.round) || 0, expiresAfterRound: (Number(state.round) || 0) + 3,
          offeredSalary, salaryMultiplier, discontentDays: 42
        });
        state.news = Array.isArray(state.news) ? state.news : [];
        state.news.unshift(`💎 INVESTIDA ÁRABE: ${buyer} oferece ${fmtMoney(fee)} por ${arabicTarget.name} (${transferMultiplier.toFixed(2).replace('.', ',')}× o valor de mercado) e promete salário ${salaryMultiplier}× maior. A diretoria considera uma oportunidade extraordinária.`);
        state.news = state.news.slice(0, 50);
        toast(`💎 Proposta árabe por ${arabicTarget.name}: ${fmtMoney(fee)} à vista!`);
        return;
      }
    }
  }

  // Enquanto uma oferta árabe aguarda decisão, preserve-a no topo da caixa de propostas.
  if((state.incomingBids || []).some(b => b.offerType === 'arabic')) return;

  // Chance de 30% por rodada de receber proposta por um titular
  if(Math.random() > 0.32) return;

  // Propostas espontâneas comuns: apenas para atletas na lista de venda ou com contrato acabando (<= 6m)
  const eligibleCandidates = (state.squad || []).filter(p => {
    const k = playerKey(p);
    return ((state.transferListed || []).includes(k) || isPlayerContractExpiringSoon(p, state)) && !p.isLoan && !p.injuryDays && !p.injuredRounds && !p.pendingTransfer && !p.isSold;
  });
  if(!eligibleCandidates.length) return;
  const lineupKeys = []; const starters = eligibleCandidates;
  // starters já definido a partir de eligibleCandidates
  if(!starters.length) return;

  // Escolhe o titular mais valorizado
  const target = starters.sort((a,b) => calcValueMi(b) - calcValueMi(a))[0];
  if(!target) return;

  const richClubs = ['Flamengo', 'Palmeiras', 'Atlético-MG', 'Botafogo', 'São Paulo', 'Corinthians', 'Grêmio', 'Internacional', 'Cruzeiro', 'Fluminense', 'Real Madrid', 'Chelsea', 'PSG', 'Al-Hilal', 'Manchester City'];
  const eligibleClubs = richClubs.filter(c => norm(c) !== norm(state.club));
  shuffle(eligibleClubs);

  // Se for jogador de alto valor, chance de 50% de haver disputa acirrada entre 2 ou 3 clubes pelo mesmo atleta
  const numClubs = Math.random() < 0.50 ? rnd(2, 3) : 1;
  const pickedClubs = eligibleClubs.slice(0, numClubs);

  const baseVal = Math.max(1, calcValueMi(target));
  state.incomingBids = state.incomingBids || [];

  // Substitui propostas anteriores deste mesmo atleta por esta nova rodada de negociações
  state.incomingBids = state.incomingBids.filter(b => b.playerKey !== playerKey(target));

  pickedClubs.forEach((clubName, idx) => {
    const mult = 1.20 + (idx * 0.12) + (Math.random() * 0.15);
    const fee = Math.round(baseVal * mult * 1000000);
    const sellOnPct = [15, 20, 25][rnd(0, 2)];

    state.incomingBids.push({
      id: `bid_${Date.now()}_${idx}`,
      date: state.date,
      playerKey: playerKey(target),
      playerName: target.name,
      ovr: playerOverall(target),
      club: clubName,
      fee: fee,
      sellOnPct: sellOnPct,
      counterOffered: false,
      receivedRound: Number(state.round) || 0,
      expiresAfterRound: (Number(state.round) || 0) + 3
    });
  });

  if(pickedClubs.length > 1){
    state.news.unshift(`🔥 LEILÃO MILIONÁRIO: ${pickedClubs.join(', ')} estão disputando a contratação do seu titular ${target.name}!`);
  } else {
    state.news.unshift(`💰 PROPOSTA OFICIAL MILIONÁRIA: O ${pickedClubs[0]} ofereceu ${fmtMoney(state.incomingBids[state.incomingBids.length-1].fee)} + 20% de venda futura por ${target.name}!`);
  }
  const targetBids = state.incomingBids.filter(b => b.playerKey === playerKey(target));
  const bestBid = targetBids.reduce((best, bid) => Math.max(best, Number(bid.fee) || 0), 0);
  toast(`📬 ${pickedClubs.length > 1 ? 'Leilão por' : 'Nova proposta por'} ${target.name}: ${pickedClubs.join(', ')} • ${fmtMoney(bestBid)}`);
}

function renderHomeBidsBanner(){
  const banner = $('#incomingBidsHomeBanner');
  if(!state.incomingBids || state.incomingBids.length === 0){
    if(banner) banner.remove();
    return;
  }
  if(banner){
    const titleEl = banner.querySelector('b');
    const descEl = banner.querySelector('.bid-desc-text');
    const btnEl = banner.querySelector('#btnOpenIncomingBidFromCentral');
    const firstBid = state.incomingBids[0];
    if(titleEl){
      titleEl.textContent = firstBid.offerType === 'arabic' ? '💎 INVESTIDA ÁRABE IRRECUSÁVEL!' : (state.incomingBids.length > 1 ? `🔥 LEILÃO MILIONÁRIO! ${state.incomingBids.length} CLUBES NA DISPUTA!` : 'PROPOSTA MILIONÁRIA OFICIAL!');
    }
    if(descEl){
      descEl.innerHTML = state.incomingBids.length > 1
        ? `${state.incomingBids.map(b => `<b>${esc(b.club)}</b>`).join(', ')} fizeram propostas oficiais por <b>${esc(firstBid.playerName)}</b>!`
        : (firstBid.offerType === 'arabic'
          ? `O <b>${esc(firstBid.club)}</b> oferece <b>${fmtMoney(firstBid.fee)}</b> à vista e salário de <b>${firstBid.salaryMultiplier}×</b> para <b>${esc(firstBid.playerName)}</b>.`
          : `O <b>${esc(firstBid.club)}</b> ofereceu <b>${fmtMoney(firstBid.fee)}</b> por <b>${esc(firstBid.playerName)}</b> (+${firstBid.sellOnPct}% futura)`);
    }
    if(btnEl){
      btnEl.textContent = state.incomingBids.length > 1 ? `Ver Propostas (${state.incomingBids.length}) >` : 'Ver Proposta >';
    }
  }
}

function openIncomingBidModal(selectedBidId){
  if(!state.incomingBids || state.incomingBids.length === 0){
    toast('Nenhuma proposta oficial ativa no momento.');
    closeCustomModal();
    renderHomeBidsBanner();
    render();
    return;
  }

  // Identifica o jogador disputado
  const firstBid = state.incomingBids[0];
  const p = (state.squad || []).find(x => playerKey(x) === firstBid.playerKey);
  if(!p){
    state.incomingBids = [];
    toast('Jogador negociado ou não faz mais parte do elenco.');
    closeCustomModal();
    renderHomeBidsBanner();
    render();
    return;
  }

  const bidsCount = state.incomingBids.length;
  const winInfo = (typeof getTransferWindowInfo === 'function') ? getTransferWindowInfo(state.date) : { open: false };
  const isWindowOpen = Boolean(winInfo.open || state.freeTransferWindow || (state.isPreSeason && Number(state.preSeasonDays) > 0) || (typeof isTransferWindowOpen === 'function' && isTransferWindowOpen(state.date)));

  const counterRelationChance = bid => {
    const requestedPct = Number(bid.requestedSellOnPct ?? bid.sellOnPct ?? 0);
    const currentPct = Number(bid.sellOnPct) || 0;
    const feeRatio = Math.max(0, Number(bid.fee) || 0) / Math.max(1, calcValueMi(p) * 1000000);
    const feeScore = Math.max(-12, Math.min(12, (feeRatio - 1.5) * 8));
    return Math.max(8, Math.min(92, Math.round(60 + feeScore + (bid.offerType === 'arabic' ? 4 : 0) - Math.max(0, requestedPct - currentPct) * 0.55)));
  };

  openCustomModal(
    firstBid.offerType === 'arabic' ? '💎 Investida Árabe • Proposta Extraordinária' : (bidsCount > 1 ? '💼 Leilão de Transferência • Múltiplos Clubes Interessados' : '💼 Proposta Oficial de Transferência Recebida'),
    `
      <!-- Cabeçalho do Atleta Alvo -->
      <div style="background:#131826;border:1px solid rgba(255,255,255,0.08);border-radius:14px;padding:14px;margin-bottom:14px;display:flex;align-items:center;gap:14px">
        <div style="width:52px;height:52px;border-radius:50%;background:#1e1a38;display:flex;align-items:center;justify-content:center;border:2px solid #7c3aed;overflow:hidden;flex-shrink:0">
          ${typeof playerPhoto === 'function' ? playerPhoto(p, 52) : ''}
        </div>
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <span style="font-size:17px;font-weight:900;color:#fff">${esc(p.name)}</span>
            <span class="pill" style="font-size:10px;background:#7c3aed;color:#fff;font-weight:800">${p.pos}</span>
            <span class="pill" style="font-size:10px;background:rgba(34,197,94,0.15);color:#22c55e;font-weight:800">${playerOverall(p)} OVR</span>
            <span class="pill" style="font-size:10px;background:rgba(255,255,255,0.08);color:rgba(255,255,255,0.6)">${p.age || 24} anos</span>
          </div>
          <div style="font-size:11px;color:${bidsCount > 1 ? '#facc15' : 'rgba(255,255,255,0.6)'};margin-top:4px;font-weight:${bidsCount > 1 ? '800' : 'normal'}">
            ${bidsCount > 1
              ? `🔥 ${bidsCount} CLUBES ENVIARAM OFERTAS OFICIAIS! Escolha o melhor destino ou tente contraproposta (+20%).`
              : firstBid.offerType === 'arabic'
              ? `💎 PROPOSTA FORA DO PADRÃO: o clube oferece ${firstBid.salaryMultiplier}× seu salário atual (${fmtMoney(playerSalary(p))} → ${fmtMoney(firstBid.offeredSalary)}) e ${fmtMoney(firstBid.fee)} pelo passe. Se a diretoria recusar, o jogador ficará insatisfeito temporariamente.`
              : `Chegou uma proposta timbrada com oferta oficial irrevogável na mesa da diretoria.`}
          </div>
        </div>
      </div>

      <!-- Status da Janela de Transferências e Nova Regra de Vendas -->
      <div style="background:${isWindowOpen ? 'rgba(34,197,94,0.12)' : 'rgba(234,179,8,0.12)'};border:1px solid ${isWindowOpen ? 'rgba(34,197,94,0.35)' : 'rgba(234,179,8,0.35)'};border-radius:12px;padding:10px 14px;margin-bottom:14px;display:flex;align-items:center;gap:10px">
        <span style="font-size:22px">${isWindowOpen ? '🟢' : '🔒'}</span>
        <div style="font-size:11px;color:#fff;line-height:1.4">
          <b style="color:${isWindowOpen ? '#4ade80' : '#fde047'};text-transform:uppercase;letter-spacing:0.5px">${isWindowOpen ? 'Janela de Transferências Aberta' : 'Regra Oficial: Janela de Transferências Fechada'}</b><br>
          ${isWindowOpen
            ? 'Ao aceitar a proposta, a venda é concluída e o atleta se transferirá imediatamente ao clube comprador.'
            : 'O valor da venda entrará imediatamente no caixa do clube. O atleta receberá a <b>tag de VENDIDO</b> e continuará jogando pela sua equipe até a reabertura da janela de transferências, quando se apresentará ao novo clube!'}
        </div>
      </div>

      <!-- Lista de Clubes Interessados e suas Propostas -->
      <div style="max-height:420px;overflow-y:auto;display:flex;flex-direction:column;gap:12px;padding-right:4px">
        ${state.incomingBids.map(b => `
          <div class="incoming-bid-card" id="card_bid_${b.id}" style="background:#161c2d;border:1px solid ${b.counterOffered ? '#22c55e' : 'rgba(255,255,255,0.1)'};border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:10px;transition:all 0.2s">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div style="display:flex;align-items:center;gap:10px">
                <span style="font-size:24px">🏛️</span>
                <div>
                  <div style="color:#fff;font-size:15px;font-weight:900">${esc(b.club)}</div>
                  <div style="font-size:10px;color:${b.offerType === 'arabic' ? '#fbbf24' : 'rgba(255,255,255,0.5)'}">${b.offerType === 'arabic' ? `💎 INVESTIDA ÁRABE · ${b.transferMultiplier}× valor de mercado` : 'Proposta Oficial Irrevogável'}</div>
                </div>
              </div>
              ${b.counterOffered ? `
                <span class="pill good" style="font-size:10px;font-weight:900;background:rgba(34,197,94,0.15);color:#22c55e;border:1px solid #22c55e">✓ CONTRAPROPOSTA ACEITA</span>
              ` : ''}
            </div>

            <!-- Valores Financeiros da Oferta -->
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;text-align:center">
              <div style="background:rgba(34,197,94,0.12);border:1px solid rgba(34,197,94,0.3);border-radius:10px;padding:8px">
                <div style="font-size:10px;color:rgba(255,255,255,0.5);text-transform:uppercase">Valor à Vista</div>
                <div id="bidFeeDisplay_${b.id}" style="font-size:18px;font-weight:900;color:#22c55e;transition:all 0.3s">${fmtMoney(b.fee)}</div>
              </div>
              <div style="background:rgba(56,189,248,0.12);border:1px solid rgba(56,189,248,0.3);border-radius:10px;padding:8px">
                <div style="font-size:10px;color:rgba(255,255,255,0.5);text-transform:uppercase">${b.offerType === 'arabic' ? 'Salário oferecido ao jogador' : 'Cláusula Futura'}</div>
                <div ${b.offerType === 'arabic' ? `id="bidSalaryDisplay_${b.id}"` : ''} style="font-size:18px;font-weight:900;color:#38bdf8">${b.offerType === 'arabic' ? `${fmtMoney(b.offeredSalary)}/mês · ${b.salaryMultiplier}×` : `${b.sellOnPct}% de Venda Futura`}</div>
                <label style="display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap;margin-top:7px;font-size:10px;color:#bae6fd;font-weight:800">${b.offerType === 'arabic' ? 'CONTRAPROPOSTA · % DE REVENDA FUTURA' : 'CONTRAPROPOSTA · VENDA FUTURA'} <select class="selBidSellOnPct" data-id="${b.id}" ${b.counterOffered ? 'disabled' : ''} style="background:#0f172a;color:#fff;border:1px solid #38bdf8;border-radius:6px;padding:4px 6px;font-weight:900"><option value="0" ${Number(b.requestedSellOnPct ?? b.sellOnPct)===0?'selected':''}>0%</option>${[5,10,15,20,25,30,35,40,50].map(pct=>`<option value="${pct}" ${Number(b.requestedSellOnPct ?? b.sellOnPct)===pct?'selected':''}>${pct}%</option>`).join('')}</select></label>
              </div>
            </div>

            ${(() => { const chance = counterRelationChance(b); const color = chance >= 70 ? '#22c55e' : chance >= 45 ? '#f59e0b' : '#ef4444'; return `
              <div class="bid-relation-panel" style="background:rgba(8,15,30,.75);border:1px solid rgba(148,163,184,.22);border-radius:10px;padding:10px 12px">
                <div style="display:flex;justify-content:space-between;gap:8px;align-items:center;font-size:10px;font-weight:900;color:#cbd5e1"><span>📊 RELAÇÃO DA CONTRAPROPOSTA</span><span class="bid-relation-label" style="color:${color}">${chance}% de chance estimada</span></div>
                <div class="bid-relation-track" style="height:8px;background:#263244;border-radius:999px;overflow:hidden;margin-top:7px"><div class="bid-relation-bar" style="width:${chance}%;height:100%;background:${color};border-radius:999px;transition:width .2s,background .2s"></div></div>
                <div class="bid-relation-note" style="font-size:10px;color:#94a3b8;margin-top:6px">${chance >= 70 ? 'Boa relação: o clube tende a negociar.' : chance >= 45 ? 'Negociação equilibrada: o clube pode aceitar ou recusar.' : 'Pedido agressivo: há risco elevado de recusa.'} A chance é estimada; o resultado ainda é probabilístico.</div>
              </div>`; })()}

            <!-- Botões de Ação para cada Proposta -->
            <div style="display:grid;grid-template-columns:1.3fr 1.1fr 0.8fr;gap:8px;margin-top:2px">
              <button class="btn primary btnAcceptSingleBid" data-id="${b.id}" style="background:#16a34a;border:none;font-weight:900;padding:10px 8px;font-size:12px;border-radius:8px;cursor:pointer">
                ${isWindowOpen ? '✅ Aceitar e Vender Agora' : '🏷️ Aceitar Venda (Sai na Janela)'}
              </button>
              <button class="btn btnCounterSingleBid" data-id="${b.id}" ${b.counterOffered ? 'disabled style="background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.3);border:none;padding:10px 8px;font-size:12px;border-radius:8px;cursor:not-allowed"' : 'style="background:#7c3aed;color:#fff;border:none;font-weight:900;padding:10px 8px;font-size:12px;border-radius:8px;cursor:pointer"'}>
                ${b.counterOffered ? '✓ Contraproposta aceita' : (b.offerType === 'arabic' ? '📈 Pedir +20%' : '🤝 Negociar oferta + cláusula')}
              </button>
              <button class="btn btnRejectSingleBid" data-id="${b.id}" style="background:rgba(239,68,68,0.2);color:#ef4444;border:1px solid rgba(239,68,68,0.4);font-weight:900;padding:10px 8px;font-size:12px;border-radius:8px;cursor:pointer">
                ❌ Recusar
              </button>
            </div>
          </div>
        `).join('')}
      </div>
    `,
    null,
    'Fechar',
    false
  );

  $$('.selBidSellOnPct').forEach(sel => {
    sel.onchange = () => {
      const bid = (state.incomingBids || []).find(item => item.id === sel.dataset.id);
      if(!bid || bid.counterOffered) return;
      const pct = Number(sel.value);
      if(![0,5,10,15,20,25,30,35,40,50].includes(pct)) return;
      bid.requestedSellOnPct = pct;
      save();
      const card = $(`#card_bid_${bid.id}`);
      const panel = card?.querySelector('.bid-relation-panel');
      if(panel){
        const chance = counterRelationChance(bid);
        const color = chance >= 70 ? '#22c55e' : chance >= 45 ? '#f59e0b' : '#ef4444';
        const label = panel.querySelector('.bid-relation-label');
        const bar = panel.querySelector('.bid-relation-bar');
        const note = panel.querySelector('.bid-relation-note');
        if(label){label.textContent = `${chance}% de chance estimada`;label.style.color = color;}
        if(bar){bar.style.width = `${chance}%`;bar.style.background = color;}
        if(note) note.textContent = chance >= 70 ? 'Boa relação: o clube tende a negociar.' : chance >= 45 ? 'Negociação equilibrada: o clube pode aceitar ou recusar.' : 'Pedido agressivo: há risco elevado de recusa.';
      }
      toast(`Contraproposta definida: ${pct}% de participação em uma futura revenda.`);
    };
  });

  // 1. ACEITAR E VENDER PARA O CLUBE ESCOLHIDO
  $$('.btnAcceptSingleBid').forEach(btn => {
    btn.onclick = () => {
      const bidId = btn.dataset.id;
      const b = (state.incomingBids || []).find(x => x.id === bidId);
      if(!b) return;

      const playerToSell = (state.squad || []).find(x => playerKey(x) === b.playerKey);
      if(!playerToSell){
        toast('Jogador não encontrado no elenco.');
        closeCustomModal();
        render();
        return;
      }

      state.balance += b.fee;
      state.income = (state.income || 0) + b.fee;

      // O percentual selecionado faz parte dos termos de venda para todos os tipos de oferta,
      // mesmo quando o usuário aceita a proposta original sem contrapropor.
      if(b.counterOffered || b.requestedSellOnPct !== undefined){
        b.sellOnPct = Math.max(0, Math.min(50, Number(b.requestedSellOnPct ?? b.sellOnPct) || 0));
      }
      const finalSellOnPct = Number(b.sellOnPct) || 0;
      if(finalSellOnPct > 0){
        state.futureSaleClauses = state.futureSaleClauses || [];
        state.futureSaleClauses.push({
          playerName: playerToSell.name,
          playerKey: b.playerKey,
          club: b.club,
          sellOnPct: finalSellOnPct,
          sharePct: finalSellOnPct,
          buyer: b.club,
          initialPrice: b.fee,
          date: state.date,
          originalFee: b.fee
        });
      }

      const winInfo = (typeof getTransferWindowInfo === 'function') ? getTransferWindowInfo(state.date) : { open: false };
      const isWindowOpen = Boolean(winInfo.open || state.freeTransferWindow || (state.isPreSeason && Number(state.preSeasonDays) > 0) || (typeof isTransferWindowOpen === 'function' && isTransferWindowOpen(state.date)));

      // Remove TODAS as propostas pendentes para este jogador (já que foi vendido!)
      state.incomingBids = (state.incomingBids || []).filter(x => x.playerKey !== b.playerKey);
      state.transferListed = (state.transferListed || []).filter(k => k !== b.playerKey);
      state.loanListed = (state.loanListed || []).filter(k => k !== b.playerKey);
      if(state.transferOffers) delete state.transferOffers[b.playerKey];
      if(state.loanOffers) delete state.loanOffers[b.playerKey];

      if(!isWindowOpen){
        // FORA DA JANELA: Marca a venda, credita o valor e o atleta fica com a tag de VENDIDO jogando até a janela abrir
        playerToSell.pendingTransfer = {
          type: 'sale',
          buyerClub: b.club,
          sellerClub: state.club,
          date: state.date,
          fee: b.fee,
          price: b.fee,
          sellOnPct: finalSellOnPct,
          offerType: b.offerType || 'millionaire',
          salaryMultiplier: b.salaryMultiplier || 1,
          offeredSalary: b.offeredSalary || 0
        };
        playerToSell.isSold = true;
        playerToSell.soldTo = b.club;
        playerToSell.soldDate = state.date;
        playerToSell.soldFee = b.fee;

        state.transfers = state.transfers || [];
        state.transfers.unshift({
          type: 'out',
          name: playerToSell.name,
          from: state.club,
          to: b.club,
          value: b.fee,
          date: state.date,
          pending: true
        });

        state.news.unshift(b.offerType === 'arabic'
          ? `💎 NEGÓCIO HISTÓRICO AGENDADO: ${playerToSell.name} foi vendido ao ${b.club} por ${fmtMoney(b.fee)} (oferta de ${b.transferMultiplier}× o valor de mercado). O atleta continuará no ${state.club} com a tag de VENDIDO e só se apresentará ao novo clube na reabertura da janela de transferências!`
          : `🤝 VENDA AGENDADA: ${playerToSell.name} foi vendido ao ${b.club} por ${fmtMoney(b.fee)} (+${finalSellOnPct}% de venda futura). O jogador defenderá o ${state.club} com a tag de VENDIDO até a abertura oficial da janela de transferências!`);
        state.news = state.news.slice(0, 50);

        closeCustomModal();
        save();
        renderHomeBidsBanner();
        render();
        toast(`🏷️ Venda acordada! ${fmtMoney(b.fee)} no caixa. ${playerToSell.name} jogará pelo seu clube com a tag de VENDIDO até a reabertura da janela!`);
        return;
      }

      // COM A JANELA ABERTA: O atleta se transfere imediatamente
      state.marketWorldFeed = state.marketWorldFeed || [];
      state.marketWorldFeed.unshift({
        player: playerToSell.name,
        pos: playerToSell.pos,
        ovr: playerOverall(playerToSell),
        from: state.club,
        to: b.club,
        fee: b.fee,
        date: state.date
      });
      state.marketWorldFeed = state.marketWorldFeed.slice(0, 30);

      state.transfers = state.transfers || [];
      state.transfers.unshift({
        type: 'out',
        name: playerToSell.name,
        from: state.club,
        to: b.club,
        value: b.fee,
        fee: b.fee,
        date: state.date
      });

      state.playerMoves = state.playerMoves || {};
      state.playerMoves[b.playerKey] = b.club;
      state.playerMoves[norm(playerToSell.name)] = b.club;

      // Remove jogador do elenco e da escalação
      state.squad = state.squad.filter(x => playerKey(x) !== b.playerKey);
      state.lineup = (state.lineup || []).filter(k => k !== b.playerKey);
      if(typeof optimizeLineup === 'function') optimizeLineup();

      state.news.unshift(b.offerType === 'arabic'
        ? `💎 NEGÓCIO HISTÓRICO: ${playerToSell.name} foi vendido ao ${b.club} por ${fmtMoney(b.fee)} (oferta de ${b.transferMultiplier}× o valor de mercado). Salário prometido ao atleta: ${fmtMoney(b.offeredSalary)}/mês.`
        : `🤝 TRANSFERÊNCIA CONCLUÍDA: ${playerToSell.name} foi vendido ao ${b.club} por ${fmtMoney(b.fee)} com ${finalSellOnPct}% de participação na venda futura!`);
      state.news = state.news.slice(0, 50);
      closeCustomModal();
      save();
      renderHomeBidsBanner();
      render();
      toast(`🎉 Venda concretizada! ${fmtMoney(b.fee)} creditados no caixa do clube.`);
    };
  });

  // 2. PEDIR +20% (ATUALIZA VALORES NA HORA OU RETIRA A PROPOSTA SE O TIME NEGAR)
  $$('.btnCounterSingleBid').forEach(btn => {
    btn.onclick = () => {
      const bidId = btn.dataset.id;
      const b = (state.incomingBids || []).find(x => x.id === bidId);
      if(!b || b.counterOffered) return;

      btn.disabled = true;
      btn.textContent = '⏳ Negociando...';

      // The visible relationship meter is the actual acceptance probability.
      const relationChance = counterRelationChance(b);
      const accepted = Math.random() * 100 < relationChance;
      if(accepted){
        const negotiatedSellOnPct = Number(b.requestedSellOnPct ?? b.sellOnPct ?? 0);
        b.fee = Math.round(b.fee * 1.20);
        b.sellOnPct = Math.max(0, Math.min(50, negotiatedSellOnPct));
        if(b.offerType === 'arabic'){
          const arabicPlayer = (state.squad || []).find(p => playerKey(p) === b.playerKey);
          b.offeredSalary = Math.round((Number(b.offeredSalary) || playerSalary(arabicPlayer || {})) * 1.20);
        }
        b.counterOffered = true;
        save();
        toast(b.offerType === 'arabic'
          ? `🎉 O ${b.club} aceitou a contraproposta e aumentou a proposta para ${fmtMoney(b.fee)}, com ${b.sellOnPct}% de participação na revenda!`
          : `🎉 ${b.club} aceitou ${fmtMoney(b.fee)} + ${b.sellOnPct}% de participação em uma futura revenda!`);

        // Atualiza os valores NA HORA visualmente no card
        const feeEl = $(`#bidFeeDisplay_${b.id}`);
        if(feeEl){
          feeEl.textContent = fmtMoney(b.fee);
          feeEl.style.transform = 'scale(1.2)';
          feeEl.style.color = '#4ade80';
          setTimeout(() => { feeEl.style.transform = 'scale(1)'; }, 280);
        }
        if(b.offerType === 'arabic'){
          const salaryEl = $(`#bidSalaryDisplay_${b.id}`);
          if(salaryEl) salaryEl.textContent = `${fmtMoney(b.offeredSalary)}/mês · ${b.salaryMultiplier}×`;
        }
        const sellOnSelect = $(`#card_bid_${b.id} .selBidSellOnPct`);
        if(sellOnSelect){ sellOnSelect.value = String(b.sellOnPct); sellOnSelect.disabled = true; sellOnSelect.title = `Cláusula negociada: ${b.sellOnPct}%`; }
        const relationPanel = $(`#card_bid_${b.id} .bid-relation-panel`);
        if(relationPanel){
          const label = relationPanel.querySelector('.bid-relation-label');
          const note = relationPanel.querySelector('.bid-relation-note');
          // Preserva a chance sorteada antes de atualizar o valor da oferta.
          if(label) label.textContent = `${relationChance}% de chance estimada`;
          if(note) note.textContent = 'Contraproposta aceita. Esta foi a chance estimada usada na decisão.';
        }
        btn.textContent = '✓ +20% Negociado';
        btn.style.background = 'rgba(255,255,255,0.06)';
        btn.style.color = 'rgba(255,255,255,0.3)';
        btn.style.cursor = 'not-allowed';

        const card = $(`#card_bid_${b.id}`);
        if(card){
          card.style.borderColor = '#22c55e';
          card.style.boxShadow = '0 0 16px rgba(34,197,94,0.35)';
        }

        renderHomeBidsBanner();
      } else {
        // Se o clube negar: retira a proposta imediatamente!
        toast(`🚫 O ${b.club} recusou pagar mais e retirou a proposta oficial.`);
        state.incomingBids = (state.incomingBids || []).filter(x => x.id !== bidId);
        save();
        renderHomeBidsBanner();

        // Se ainda sobrarem propostas de outros clubes para o jogador
        if(state.incomingBids.length > 0){
          openIncomingBidModal();
        } else {
          // Se não sobrar nenhuma proposta, fecha o modal e atualiza a tela na hora
          closeCustomModal();
          render();
        }
      }
    };
  });

  // 3. RECUSAR PROPOSTA DE UM CLUBE ESPECÍFICO
  $$('.btnRejectSingleBid').forEach(btn => {
    btn.onclick = () => {
      const bidId = btn.dataset.id;
      const b = (state.incomingBids || []).find(x => x.id === bidId);
      const clubName = b ? b.club : 'Clube';
      if(b?.offerType === 'arabic'){
        const unhappyPlayer = (state.squad || []).find(x => playerKey(x) === b.playerKey);
        if(unhappyPlayer){
          unhappyPlayer.morale = clamp((Number(unhappyPlayer.morale) || 70) - 18, 10, 100);
          unhappyPlayer.wantsTransfer = true;
          unhappyPlayer.transferDiscontentDays = Math.max(Number(unhappyPlayer.transferDiscontentDays) || 0, Number(b.discontentDays) || 42);
          unhappyPlayer.transferDiscontentReason = `Oferta milionária recusada por ${b.club}`;
          state.news.unshift(`😠 INSATISFAÇÃO NO ELENCO: ${unhappyPlayer.name} ficou descontente após a recusa da proposta de ${b.club}. Ele quer ser negociado e perdeu 18 pontos de moral temporariamente.`);
          state.news = state.news.slice(0, 50);
        }
      }
      state.incomingBids = (state.incomingBids || []).filter(x => x.id !== bidId);
      save();
      toast(`Proposta do ${clubName} recusada.`);
      renderHomeBidsBanner();

      if(state.incomingBids.length > 0){
        openIncomingBidModal();
      } else {
        closeCustomModal();
        render();
      }
    };
  });
}

// =========================================================================
// SISTEMA DE SUGESTÕES DINÂMICAS DA COMISSÃO TÉCNICA & DIRETORIA
// =========================================================================

function getPendingSuggestion(){
  if(!state) return null;
  if(state.suggestionHandledRound === state.round) return null;
  if(state.pendingSuggestion) return state.pendingSuggestion;

  const suggestionsList = [
    {
      id: 'tatico',
      dept: 'COMISSÃO TÉCNICA',
      icon: '📋',
      title: 'Compactação Tática & Treino de Bolas Paradas',
      desc: 'O auxiliar técnico identificou brechas na defesa do próximo rival e propõe treino intensivo de posicionamento e bolas paradas.',
      impact: 'Moral do elenco +5% e entrosamento tático elevado para o jogo.',
      type: 'morale_tactics'
    },
    {
      id: 'fisio',
      dept: 'DEPARTAMENTO DE FISIOLOGIA',
      icon: '🧊',
      title: 'Sessão Regenerativa com Crioterapia & Banheira de Gelo',
      desc: 'Os fisiologistas recomendam imersão em gelo e massoterapia para eliminar o desgaste muscular acumulado nas pernas dos atletas.',
      impact: 'Recupera +12% de energia física de todo o elenco.',
      type: 'energy_boost'
    },
    {
      id: 'ataque',
      dept: 'PREPARADOR OFENSIVO',
      icon: '🎯',
      title: 'Calibragem de Chutes a Gol & Treino de Pênaltis',
      desc: 'O preparador de ataque sugere 1 hora extra de finalizações, pontaria calibrada e cobranças de pênalti com meias e atacantes.',
      impact: 'Moral +8% dos homens de frente e pontaria afiada.',
      type: 'attack_boost'
    },
    {
      id: 'marketing',
      dept: 'DIRETORIA DE MARKETING',
      icon: '📣',
      title: 'Treino Aberto Festivo com Apoio da Torcida',
      desc: 'A diretoria sugere abrir as arquibancadas do estádio para um treino festivo com os torcedores para incendiar os ânimos da equipe.',
      impact: 'Apoio da torcida +4% e moral geral da equipe +6%.',
      type: 'fan_morale'
    }
  ];

  const idx = Math.abs(Number(state.round || 0)) % suggestionsList.length;
  state.pendingSuggestion = suggestionsList[idx];
  return state.pendingSuggestion;
}

function acceptPendingSuggestion(){
  const sug = getPendingSuggestion();
  if(!sug) return;

  if(sug.type === 'morale_tactics'){
    state.squad = (state.squad || []).map(p => ({ ...p, morale: clamp((Number(p.morale) || 70) + 5, 0, 100) }));
    toast('✅ Sugestão aprovada! Treino tático concluído e moral +5%!');
  } else if(sug.type === 'energy_boost'){
    state.squad = (state.squad || []).map(p => ({ ...p, energy: clamp((Number(p.energy) || 70) + 12, 0, 100) }));
    toast('✅ Crioterapia realizada! Todo o time recuperou +12% de energia física!');
  } else if(sug.type === 'attack_boost'){
    state.squad = (state.squad || []).map(p => ['ST','CF','RW','LW','CAM','AM'].includes(p.pos) ? { ...p, morale: clamp((Number(p.morale) || 70) + 8, 0, 100) } : p);
    toast('✅ Treino ofensivo concluído! Atacantes afiados e moral +8%!');
  } else if(sug.type === 'fan_morale'){
    state.squad = (state.squad || []).map(p => ({ ...p, morale: clamp((Number(p.morale) || 70) + 6, 0, 100) }));
    state.fanSupport = clamp((Number(state.fanSupport) || 75) + 4, 0, 100);
    toast('✅ Treino aberto realizado! A torcida compareceu em peso e inflamou o time!');
  }

  // Marca sugestão tratada para a rodada atual e remove da tela imediatamente
  state.suggestionHandledRound = state.round;
  state.pendingSuggestion = null;
  state.pendingDecision = null;
  state.trainingSuggestionPending = false;
  save();
  render();
}

function dismissPendingSuggestion(){
  state.suggestionHandledRound = state.round;
  state.pendingSuggestion = null;
  state.pendingDecision = null;
  state.trainingSuggestionPending = false;
  save();
  toast('Sugestão dispensada para esta rodada.');
  render();
}

function updateManagerCareerStats(userRes){
  if(!state) return;
  state.managerCareer = state.managerCareer || {
    matches: 0,
    wins: 0,
    draws: 0,
    losses: 0,
    goalsFor: 0,
    goalsAgainst: 0,
    titles: 0
  };

  if(userRes){
    state.managerCareer.matches++;
    const isHome = userRes.h === state.club;
    const gf = isHome ? userRes.hg : userRes.ag;
    const ga = isHome ? userRes.ag : userRes.hg;
    state.managerCareer.goalsFor += gf;
    state.managerCareer.goalsAgainst += ga;

    if(gf > ga) state.managerCareer.wins++;
    else if(gf === ga) state.managerCareer.draws++;
    else state.managerCareer.losses++;
  }
}

