// =========================================================================
// NORMALIZADOR DE POSIÇÕES & ALOCAÇÃO SEGURA NA ESCALAÇÃO (MODO JOGADOR)
// =========================================================================
function normalizePlayerPositionCode(rawPos) {
  const p = String(rawPos || 'ST').trim().toUpperCase();
  if (['GK', 'GOL', 'GOLEIRO'].includes(p)) return 'GK';
  if (['CB', 'ZAG', 'ZAGUEIRO'].includes(p)) return 'CB';
  if (['LB', 'LE', 'LATERAL ESQUERDO'].includes(p)) return 'LB';
  if (['RB', 'LD', 'LATERAL DIREITO'].includes(p)) return 'RB';
  if (['CDM', 'VOL', 'VOLANTE'].includes(p)) return 'CDM';
  if (['CM', 'MC', 'MEIA CENTRAL'].includes(p)) return 'CM';
  if (['CAM', 'MEI', 'MEIA ATACANTE', 'MO'].includes(p)) return 'CAM';
  if (['LW', 'PE', 'PONTA ESQUERDA', 'ME'].includes(p)) return 'LW';
  if (['RW', 'PD', 'PONTA DIREITA', 'MD'].includes(p)) return 'RW';
  if (['ST', 'CA', 'ATA', 'CF', 'SA', 'ATACANTE', 'CENTROAVANTE'].includes(p)) return 'ST';
  return 'ST';
}
window.normalizePlayerPositionCode = normalizePlayerPositionCode;

function getPreferredLineupSlots(normPos, formationName = null) {
  if (normPos === 'GK') return [0];
  const activeFormKey = formationName || (typeof state !== 'undefined' && state?.formation) || '4-3-3';
  const formArr = (typeof FORMATIONS !== 'undefined' && (FORMATIONS[activeFormKey] || FORMATIONS['4-3-3'])) || null;
  if (Array.isArray(formArr) && formArr.length === 11) {
    const roleEquiv = {
      RB: ['RB', 'RWB'],
      LB: ['LB', 'LWB'],
      CB: ['CB'],
      CDM: ['DM', 'CDM'],
      CM: ['CM', 'DM', 'AM'],
      CAM: ['AM', 'CAM', 'CM'],
      RW: ['RW', 'RM'],
      LW: ['LW', 'LM'],
      ST: ['ST', 'CF']
    };
    const exactRoles = roleEquiv[normPos] || [normPos];
    const scored = [];
    for (let idx = 1; idx < 11; idx++) {
      const slot = formArr[idx] || {};
      const r = String(slot.r || '').toUpperCase();
      let score = 0;
      if (exactRoles[0] === r) score += 100;
      else if (exactRoles.includes(r)) score += 75;
      else if (normPos === 'ST' && ['LW', 'RW', 'AM'].includes(r)) score += 40;
      else if ((normPos === 'LW' || normPos === 'RW') && ['ST', 'AM', 'LM', 'RM'].includes(r)) score += 45;
      else if (normPos === 'CAM' && ['CM', 'LW', 'RW', 'ST'].includes(r)) score += 45;
      else if (normPos === 'CDM' && ['CM', 'CB'].includes(r)) score += 45;
      else if ((normPos === 'LB' || normPos === 'RB') && r === 'CB') score += 35;

      // Alinhamento estrito de corredor lateral (Esquerda x < 40, Direita x > 60, Centro próximo de 50)
      const sx = Number(slot.x ?? 50);
      if ((normPos === 'LB' || normPos === 'LW') && sx < 40) score += 20;
      else if ((normPos === 'RB' || normPos === 'RW') && sx > 60) score += 20;
      else if (['CB', 'CDM', 'CM', 'CAM', 'ST'].includes(normPos)) score += Math.max(0, 15 - Math.abs(sx - 50) * 0.3);

      scored.push({ idx, score });
    }
    scored.sort((a, b) => b.score - a.score || a.idx - b.idx);
    return scored.map(s => s.idx);
  }
  // Fallback alinhado ao 4-3-3 canônico (0=GK, 1=LB, 2=CB, 3=CB, 4=RB, 5=CM, 6=DM, 7=CM, 8=LW, 9=ST, 10=RW)
  const map = {
    GK: [0],
    LB: [1, 4],
    CB: [2, 3, 1, 4],
    RB: [4, 1],
    CDM: [6, 5, 7],
    CM: [5, 7, 6],
    CAM: [7, 5, 9],
    LW: [8, 9, 10],
    ST: [9, 8, 10],
    RW: [10, 9, 8]
  };
  return map[normPos] || [9, 10, 8];
}
window.getPreferredLineupSlots = getPreferredLineupSlots;

function placeUserPlayerInCorrectSlot(lineup, userPlayer, squadPool = []) {
  if (!Array.isArray(lineup) || !userPlayer) return lineup;
  const normPos = normalizePlayerPositionCode(userPlayer.pos || userPlayer.position);
  userPlayer.isUserPlayer = true;
  userPlayer.normalizedPos = normPos;

  // 1. Remove qualquer duplicata do atleta do usuário na escalação
  const userId = userPlayer.id || userPlayer.name;
  for (let i = lineup.length - 1; i >= 0; i--) {
    const item = lineup[i];
    if (item && (item.isUserPlayer || String(item.id) === String(userId) || item.name === userPlayer.name)) {
      lineup.splice(i, 1);
    }
  }

  // 2. Garante que o índice 0 SEMPRE tenha um Goleiro real se o usuário NÃO for GK
  if (normPos !== 'GK') {
    const firstIsGk = lineup[0] && normalizePlayerPositionCode(lineup[0].pos || lineup[0].position) === 'GK';
    if (!firstIsGk) {
      const gkIdx = lineup.findIndex(pl => pl && normalizePlayerPositionCode(pl.pos || pl.position) === 'GK');
      if (gkIdx > 0) {
        const [gk] = lineup.splice(gkIdx, 1);
        lineup.unshift(gk);
      } else {
        const reserveGk = (squadPool || []).find(pl => String(pl?.id) !== String(userId) && normalizePlayerPositionCode(pl.pos || pl.position) === 'GK');
        if (reserveGk) {
          lineup.unshift({ ...reserveGk });
        } else {
          lineup.unshift({
            id: `emergency-gk-${userPlayer.club || 'club'}`,
            name: 'Goleiro Titular',
            pos: 'GK',
            position: 'GK',
            fc: 65,
            pes: 65,
            isGK: true
          });
        }
      }
    }
  }

  // 3. Encontra o slot tático exato da posição do usuário (nunca slot 0 se normPos !== 'GK')
  const preferredSlots = getPreferredLineupSlots(normPos);
  let targetSlot = preferredSlots.find(idx => {
    if (normPos !== 'GK' && idx === 0) return false;
    return idx < lineup.length && normalizePlayerPositionCode(lineup[idx]?.pos) === normPos;
  });

  if (targetSlot === undefined) {
    targetSlot = preferredSlots.find(idx => (normPos === 'GK' || idx > 0) && idx < lineup.length);
  }
  if (targetSlot === undefined) {
    targetSlot = normPos === 'GK' ? 0 : Math.min(10, Math.max(1, lineup.length - 1));
  }

  // 4. Substitui o jogador daquele slot mantendo exatos 11 atletas
  if (lineup.length >= 11) {
    lineup[targetSlot] = userPlayer;
  } else {
    lineup.splice(targetSlot, 0, userPlayer);
  }

  // 5. Preenche até 11 se necessário
  while (lineup.length < 11) {
    const extra = (squadPool || []).find(pl => pl && String(pl.id) !== String(userId) && !lineup.some(l => String(l.id) === String(pl.id)));
    if (extra) {
      lineup.push(extra);
    } else {
      const idx = lineup.length;
      lineup.push({
        id: `emergency-${idx}-${userPlayer.club || 'club'}`,
        name: `Atleta ${idx + 1}`,
        pos: 'CM',
        fc: 60,
        fitness: 100
      });
    }
  }

  // 6. Trava absoluta de segurança: se normPos !== 'GK', slot 0 NUNCA pode ser userPlayer
  if (normPos !== 'GK') {
    if (lineup[0] === userPlayer || String(lineup[0]?.id) === String(userId) || normalizePlayerPositionCode(lineup[0]?.pos) !== 'GK') {
      const actualGkIdx = lineup.findIndex((pl, idx) => idx > 0 && normalizePlayerPositionCode(pl?.pos) === 'GK');
      if (actualGkIdx > 0) {
        [lineup[0], lineup[actualGkIdx]] = [lineup[actualGkIdx], lineup[0]];
      }
    }
    const finalUserIdx = lineup.findIndex(pl => pl === userPlayer || String(pl?.id) === String(userId));
    if (finalUserIdx === 0) {
      const safeSlot = targetSlot > 0 ? targetSlot : (preferredSlots.find(s => s > 0) || 9);
      [lineup[0], lineup[safeSlot]] = [lineup[safeSlot], lineup[0]];
    }
  }

  return lineup.slice(0, 11);
}
window.placeUserPlayerInCorrectSlot = placeUserPlayerInCorrectSlot;

let isStartingLiveMatch = false;
function alignPlayerCareerStarter(starters, formation, athlete, squad = starters){
  const gkIndex = formation.findIndex(slot => isGoalkeeperPosition(slot?.r));
  if(gkIndex < 0 || gkIndex >= starters.length) return starters;
  const naturalPosition = String(athlete?.pos || athlete?.position || state.playerCareerState?.position || '').toUpperCase().trim();
  let keeperIndex = starters.findIndex(player => isGoalkeeperPosition(player?.pos));
  if(keeperIndex < 0){
    const keeper = (squad || []).find(player => isGoalkeeperPosition(player?.pos) && (String(player?.id) !== String(athlete?.id) || isGoalkeeperPosition(naturalPosition)));
    const athleteAtGoal = Boolean(athlete) && String(starters[gkIndex]?.id) === String(athlete.id) && !isGoalkeeperPosition(naturalPosition);
    if(athleteAtGoal){
      const forwardSlot = formation.findIndex((slot, index) => index !== gkIndex && ['ST','CF','LW','RW','AM','CM'].includes(String(slot?.r || '').toUpperCase()));
      if(forwardSlot >= 0 && forwardSlot < starters.length){
        [starters[gkIndex], starters[forwardSlot]] = [starters[forwardSlot], starters[gkIndex]];
      }
    }
    starters[gkIndex] = keeper || {
      id: `emergency-gk-${String(athlete?.id || 'career')}`,
      name: 'Goleiro reserva', pos: 'GK', club: state.club, fc: 45, overall: 45
    };
    keeperIndex = gkIndex;
  } else if(keeperIndex !== gkIndex && keeperIndex < formation.length){
    [starters[gkIndex], starters[keeperIndex]] = [starters[keeperIndex], starters[gkIndex]];
  }
  if(!athlete) return starters;
  const athleteIndex = starters.findIndex(player => String(player?.id) === String(athlete.id));
  if(athleteIndex < 0) return starters;
  const compatible = {
    ST: ['ST','CF'], ATA: ['ST','CF'], CA: ['ST','CF'], CF: ['CF','ST'], LW: ['LW','LM'], RW: ['RW','RM'],
    LM: ['LM','LW'], RM: ['RM','RW'], AM: ['AM','CM'], CM: ['CM','AM','DM'],
    DM: ['DM','CM'], LB: ['LB','LWB'], RB: ['RB','RWB'],
    LWB: ['LWB','LB'], RWB: ['RWB','RB'], CB: ['CB'], ZAG: ['CB'],
    VOL: ['DM','CM'], MEI: ['AM','CM'], PON: ['LW','RW'], GK: ['GK'], GOL: ['GK']
  };
  const allowed = compatible[naturalPosition] || [naturalPosition];
  const compatibleIndex = formation.findIndex((slot, index) => index !== gkIndex && allowed.includes(String(slot?.r || '').toUpperCase()));
  const targetIndex = isGoalkeeperPosition(naturalPosition)
    ? gkIndex
    : (compatibleIndex >= 0 ? compatibleIndex : formation.findIndex((slot, index) => index !== gkIndex && !isGoalkeeperPosition(slot?.r)));
  if(targetIndex >= 0 && targetIndex !== athleteIndex && targetIndex < starters.length){
    [starters[athleteIndex], starters[targetIndex]] = [starters[targetIndex], starters[athleteIndex]];
  }
  return starters;
}
window.alignPlayerCareerStarter = alignPlayerCareerStarter;

function startLiveMatch(){
  if(isStartingLiveMatch) return;
  if(typeof repairSaveIfCorrupted === 'function' && repairSaveIfCorrupted(state)) save();
  if(state.gameMode === 'player' && !window.AFM_PlayerEngine?.isPlayerAvailableForMatch?.(state)){
    toast('🩺 Com condição abaixo de 50%, você não foi relacionado. Simule a partida para descansar e recuperar energia.');
    return;
  }
  const matchGate = canStartMatch();
  if(!matchGate.canStart){
    if(matchGate.status === 'season_finished'){ showEndOfSeasonModal(); return; }
    if(matchGate.status === 'other_competitions_pending'){
      openNextPendingCompetitionFixture(matchGate.nextFixture || getNextPendingClubFixture(state));
      return;
    }
    if(matchGate.status === 'future'){
      state.date = matchGate.matchDate;
      state.currentDate = matchGate.matchDate;
      state.currentDateFormatted = formatDatePtBr(matchGate.matchDate);
    } else if(matchGate.status === 'no_fixture' || matchGate.isBye){
      toast('🏖️ Seu clube está de folga nesta rodada. Simulando os jogos dos adversários...');
      simulateQuickRound();
      return;
    } else if(matchGate.status === 'missed'){
      toast('⚠️ A data da partida já passou. Simulando esta rodada para recuperar o calendário.');
      simulateQuickRound();
      return;
    } else {
      toast(`⚠️ ${matchGate.reason}`);
      return;
    }
  }

  isStartingLiveMatch = true;
  try {
    const activeMatch = typeof getActualCurrentMatch === 'function' ? getActualCurrentMatch(state) : null;
    if(!stateLeagueMatchSession && !continentalMatchSession && !copaMatchSession && activeMatch && activeMatch.type === 'estadual' && activeMatch.competitionId && Number.isInteger(activeMatch.roundIndex)){
      isStartingLiveMatch = false;
      return beginStateLeagueMatch(activeMatch.competitionId, activeMatch.roundIndex);
    }
    if(!stateLeagueMatchSession && !continentalMatchSession && !copaMatchSession && activeMatch && activeMatch.type === 'copa' && Number.isInteger(activeMatch.fixtureIndex)){
      isStartingLiveMatch = false;
      return beginCopaDoBrasilLiveMatch(activeMatch.fixtureIndex, activeMatch.phaseName || copaCurrentPhase);
    }
    if(!stateLeagueMatchSession && !continentalMatchSession && !copaMatchSession && activeMatch && activeMatch.type === 'continental' && activeMatch.competitionId && activeMatch.matchId){
      isStartingLiveMatch = false;
      return beginContinentalLiveMatch(activeMatch.competitionId, activeMatch.matchId);
    }
    if(state && state.isPreSeason && state.preSeasonDays > 0){
      state.isPreSeason = false;
      state.preSeasonDays = 0;
      state.date = getDateForRound(state.round || 0, state.season);
    }
    const fixtures = currentFixtures();
    if(!fixtures.length || (state.round >= (state.schedule?.length || 1))){
      showEndOfSeasonModal();
      return;
    }
    let f = userFixture();
  if(!f){
    const opp = state.teams?.find(t => norm(t.name) !== norm(state.club))?.name || 'Adversário';
    f = [state.club, opp];
    if(Array.isArray(state.schedule) && state.schedule[state.round]){
      state.schedule[state.round].push(f);
    }
  }

  const [home, away] = f;
  const comp = curComp();
  const isKO = copaMatchSession ? true : continentalMatchSession ? (continentalMatchSession.tournament?.phase !== 'groups') : (comp.type === 'knockout');
  const isUserHome = norm(home) === norm(state.club);

  const otherResults = [];
  const winners = [];
  fixtures.forEach(([h,a])=>{
    if((norm(h) === norm(home) && norm(a) === norm(away)) || (norm(h) === norm(state.club) || norm(a) === norm(state.club))) return;
    const [hg, ag] = simulateScore(h,a);
    let win = null, pen = null;
    if(stateLeagueMatchSession || continentalMatchSession || copaMatchSession){
      // Parallel matches are handled by their own competition engines.
      return;
    }
  if(isKO){
      if(hg===ag){
        let hp=rnd(3,6), ap=rnd(2,6); if(hp===ap) ap=hp===6?5:hp+1;
        pen=[hp,ap]; win=hp>ap?h:a;
      } else win=hg>ag?h:a;
      winners.push(win);
    }
    // Armazena para aplicar SOMENTE após o apito final do jogo
    otherResults.push({h,a,hg,ag,win,pen});
  });

  const hs = teamStrengthByName(home);
  const as = teamStrengthByName(away);
  const oppName = isUserHome ? away : home;
  const proj = attendanceProjection(oppName);

  const hostClubObj = clubByName(home) || { stadium: 'Estádio Genérico', capacity: 15000 };
  const stadiumProfile = typeof window.AFM_REAL_FOOTBALL?.renderer?.getStadiumProfile === 'function'
    ? window.AFM_REAL_FOOTBALL.renderer.getStadiumProfile(home, isUserHome ? state : null)
    : { id: 'generic', name: hostClubObj.stadium || 'Estádio Genérico', style: 'generic', primary: '#334155', secondary: '#64748b', roof: 'partial', capacity: hostClubObj.capacity || 22000 };
  const savedStadiumName = isUserHome
    ? (state.stadiumCustomization?.name || state.stadiumName || state.stadium?.name || state.namingRights?.stadiumName || stadiumProfile.name)
    : stadiumProfile.name;
  const stadiumName = savedStadiumName || (isUserHome ? `Estádio do ${state.club}` : 'Estádio Genérico');
  const stadiumCap = isUserHome ? (state.infrastructure?.stadium?.capacity || 18000) : (stadiumProfile.capacity || hostClubObj.capacity || 22000);
  const stadiumPitch = isUserHome ? (state.stadiumPitchType || 'natural') : 'natural';
  const stadiumUpgrades = isUserHome ? (state.stadiumUpgrades || {}) : { chairs: true, screen: false, ledRing: false, flares: false, ledLights: true };
  const attendance = isUserHome ? proj.attendance : Math.round(stadiumCap * clamp(0.3 + (hs/150), 0.15, 0.95));
  const attendanceForceBonus = isUserHome
    ? Math.min(5, Math.max(0, Number(proj?.attendanceForceBonus) || stadiumAttendanceStrengthBonus(attendance, stadiumCap)))
    : stadiumAttendanceStrengthBonus(attendance, stadiumCap);

  // Constrói os 11 titulares para cada equipe com validação rigorosa de posições e funções táticas
  function buildMatchTeam(teamName, isUser, isHomeSide, teamTac){
    const formKey = isUser ? (state.formation || '4-3-3') : (teamTac?.formation || '4-3-3');
    const formDef = FORMATIONS[formKey] || FORMATIONS['4-3-3'];
    const presetObj = FC27_PRESETS[formKey] || FC27_PRESETS['4-3-3'] || {};
    const tac = teamTac || (isUser ? getClubTacticalProfile(teamName, true) : getClubTacticalProfile(teamName, false));
    const players = [];

    function calcPlayerAttrs(pName, pPos, ovr){
      const isGk = pPos === 'GK';
      const o = ovr || 65;
      const h = hashStr(pName || '');
      const r1 = (h % 7) - 3;
      const r2 = ((h >> 3) % 7) - 3;
      const r3 = ((h >> 6) % 7) - 3;

      const isWinger = ['LW','RW','LM','RM'].includes(pPos);
      const isStriker = ['ST','CF'].includes(pPos);
      const isMid = ['CM','AM'].includes(pPos);
      const isDM = pPos === 'DM';
      const isCB = pPos === 'CB';
      const isFB = ['LB','RB'].includes(pPos);

      const basePace = isGk ? 45 + (o - 60) * 0.35 : (isWinger ? o + 6 : isStriker || isFB ? o + 3 : isMid ? o - 2 : o - 4);
      const pace = clamp(Math.round(basePace + r1), 35, 99);
      const acceleration = clamp(Math.round(pace + (isWinger ? 2 : -1) + r2), 35, 99);
      const sprintSpeed = clamp(Math.round(pace + (isStriker ? 2 : 0) + r3), 35, 99);

      const baseShooting = isGk ? 15 : (isStriker ? o + 7 : isWinger || pPos === 'AM' ? o + 3 : isMid ? o - 2 : o - 14);
      const shooting = clamp(Math.round(baseShooting + r2), 15, 99);
      const finishing = clamp(Math.round((isStriker ? o + 8 : isWinger ? o + 2 : shooting - 4) + r1), 15, 99);

      const basePassing = isGk ? 55 + (o - 60) * 0.45 : (isMid ? o + 6 : isDM ? o + 4 : isFB ? o + 1 : isWinger ? o + 2 : o - 3);
      const passing = clamp(Math.round(basePassing + r3), 25, 99);
      const shortPassing = clamp(Math.round(passing + (isMid || isDM ? 3 : 0) + r1), 25, 99);
      const longPassing = clamp(Math.round(passing + (isDM || isCB ? 2 : -2) + r2), 25, 99);
      const vision = clamp(Math.round((isMid || pPos === 'AM' ? o + 7 : isDM ? o + 4 : passing - 3) + r2), 25, 99);

      const baseDribbling = isGk ? 25 : (isWinger ? o + 7 : pPos === 'AM' ? o + 5 : isStriker ? o + 2 : isMid ? o + 3 : o - 5);
      const dribbling = clamp(Math.round(baseDribbling + r1), 20, 99);
      const ballControl = clamp(Math.round(dribbling + (isMid || isStriker ? 2 : 0) + r3), 20, 99);

      const baseDefending = isGk ? 30 : (isCB ? o + 7 : isDM ? o + 5 : isFB ? o + 3 : o - 18);
      const defending = clamp(Math.round(baseDefending + r2), 20, 99);
      const marking = clamp(Math.round(defending + (isCB ? 2 : 0) + r1), 20, 99);
      const interceptions = clamp(Math.round(defending + (isDM || isCB ? 3 : 0) + r3), 20, 99);
      const tackling = clamp(Math.round(defending + (isCB || isDM ? 2 : 0) + r2), 20, 99);

      const basePhysical = isGk ? o - 2 : (isCB || isStriker ? o + 5 : isDM ? o + 4 : o);
      const strength = clamp(Math.round(basePhysical + r3), 35, 99);
      const stamina = clamp(Math.round((isMid || isFB || isDM ? o + 6 : o + 2) + r1), 40, 99);
      const aggression = clamp(Math.round((isCB || isDM ? o + 5 : o - 2) + r2), 30, 99);

      const positioning = clamp(Math.round((isStriker || isCB ? o + 5 : isMid ? o + 3 : o) + r1), 30, 99);
      const composure = clamp(Math.round(o + r2), 35, 99);
      const reactions = clamp(Math.round((isGk ? o + 6 : o + 2) + r3), 35, 99);
      const heading = clamp(Math.round((isCB || isStriker ? o + 7 : o - 10) + r1), 20, 99);
      const crossing = clamp(Math.round((isFB || isWinger ? o + 7 : o - 12) + r3), 20, 99);

      return {
        pace, acceleration, sprintSpeed,
        shooting, finishing,
        passing, vision, shortPassing, longPassing,
        dribbling, ballControl,
        strength, stamina, aggression,
        positioning, interceptions, defending, marking, tackling,
        composure, reactions, heading, crossing
      };
    }

    if(isUser){
      const lineupKeys = state.lineup || [];
      const controlledAthlete = state.gameMode === 'player'
        ? ((typeof window.getControlledPlayer === 'function' ? window.getControlledPlayer(state) : null) ||
           (state.squad || []).find(p => String(p.id) === String(state.controlledPlayerId) || p.isControlled || p.isControlledAthlete || p.isUserPlayer))
        : null;
      const playerTooTired = Boolean(controlledAthlete && !window.AFM_PlayerEngine?.isPlayerAvailableForMatch?.(state));
      const selectedStarters = lineupKeys.map(k => findSquadPlayerByKey(k)).filter(p => p && !(playerTooTired && String(p.id) === String(controlledAthlete?.id)));
      let starters = [...selectedStarters.slice(0, 11)];

      // 1. Preenche até 11 titulares usando o elenco disponível
      const usedStarterKeys = new Set(starters.map(p => playerKey(p)));
      while(starters.length < 11){
        const extra = (state.squad || []).find(p => !usedStarterKeys.has(playerKey(p)) && !(playerTooTired && String(p.id) === String(controlledAthlete?.id)));
        if(extra){ starters.push(extra); usedStarterKeys.add(playerKey(extra)); }
        else break;
      }
      while(starters.length < 11){
        const idx = starters.length;
        starters.push({
          id: `emergency-${idx}-` + norm(state.club),
          marketKey: `emergency-${idx}:` + norm(state.club),
          name: `Atleta ${idx + 1} ` + state.club,
          club: state.club,
          pos: idx === 0 ? 'GK' : (formDef[idx]?.r || 'CM'),
          fc: 60, pes: 60, morale: 70, fitness: 100
        });
      }

      // 2. No Modo Jogador, aloca com proteção absoluta do slot 0 (goleiro)
      if(state.gameMode === 'player' && controlledAthlete && !playerTooTired){
        const pTrust = Number(state.playerCareerState?.managerTrust || state.playerCareerState?.trust || 45);
        const isStarterRole = state.playerCareerState?.role === 'Titular' || pTrust >= 60 || starters.some(p => String(p.id) === String(controlledAthlete.id));
        if(isStarterRole){
          starters = placeUserPlayerInCorrectSlot(starters, controlledAthlete, state.squad);
        } else {
          // Começa no banco (Reserva Imediato): remove da titularidade inicial se tiver sido inserido
          const userIdx = starters.findIndex(p => String(p.id) === String(controlledAthlete.id));
          if(userIdx >= 0){
            const subCand = (state.squad || []).find(p => String(p.id) !== String(controlledAthlete.id) && !starters.some(st => String(st.id) === String(p.id)));
            if(subCand) starters[userIdx] = subCand;
          }
          if(normalizePlayerPositionCode(starters[0]?.pos) !== 'GK'){
            const realGk = starters.find(p => normalizePlayerPositionCode(p.pos) === 'GK') || (state.squad || []).find(p => normalizePlayerPositionCode(p.pos) === 'GK');
            if(realGk){
              const gIdx = starters.indexOf(realGk);
              if(gIdx > 0){ [starters[0], starters[gIdx]] = [starters[gIdx], starters[0]]; }
              else { starters[0] = realGk; }
            }
          }
        }
      } else {
        alignPlayerCareerStarter(starters, formDef, playerTooTired ? null : controlledAthlete, state.squad);
      }

      for(let i=0; i<11; i++){
        const p = starters[i] || { name: `Jogador ${i+1}`, pos: formDef[i]?.r || (i === 0 ? 'GK' : 'CM'), fc: 65 };
        const isUserAthlete = Boolean(state.gameMode === 'player' && controlledAthlete && (String(p.id) === String(controlledAthlete.id) || p.isControlledAthlete || p.isUserPlayer));
        const normPos = normalizePlayerPositionCode(isUserAthlete ? (controlledAthlete.pos || controlledAthlete.position || p.pos) : p.pos);
        const isGoalkeeper = isUserAthlete
          ? (normPos === 'GK')
          : (i === 0 || formDef[i]?.r === 'GK' || normPos === 'GK');
        let slot = formDef[i] || { r: isGoalkeeper ? 'GK' : (normPos || 'CM'), x: 50, y: isGoalkeeper ? 89 : 50 };
        if (isUserAthlete && normPos !== 'GK' && (slot.r === 'GK' || i === 0)) {
          const fwdSlot = formDef.slice().reverse().find(s => s && s.r !== 'GK') || { r: normPos, x: 50, y: 25 };
          slot = fwdSlot;
        }
        const effectiveOvr = (typeof getPlayerEffectiveOverall === 'function') ? getPlayerEffectiveOverall(p, isGoalkeeper ? 'GK' : slot.r) : (playerOverall(p) || 65);
        const ovr = effectiveOvr || playerOverall(p) || 65;
        const attrs = calcPlayerAttrs(p.name, isGoalkeeper ? 'GK' : slot.r, ovr);

        // Atribuição de Role/Focus customizado ou preset
        const customRoleKey = state.tactics?.playerRoles?.[playerKey(p)] || state.tactics?.playerRoles?.[i];
        let role = customRoleKey ? getPlayerRoleDef(slot.r, customRoleKey) : null;
        if(!role){
          const presetRoleItem = presetObj.roles?.[i];
          role = presetRoleItem ? getPlayerRoleDef(slot.r, presetRoleItem.role) : (TACTICAL_ROLES[slot.r]?.[0] || { id: 'std', role: 'Padrao', focus: 'Balanced', name: 'Padrão' });
        }

        let baseXPct, baseYPct;
        if(isGoalkeeper){
          baseXPct = isHomeSide ? 3.5 : 96.5;
          baseYPct = 50;
        } else {
          const depth = (100 - slot.y) * 0.44;
          const tacLine = tac.lineHeight || 60;
          const lineShift = (tacLine - 60) * 0.14;
          const isBackline = slot.y > 60;
          const depthMod = isBackline ? lineShift * 0.8 : lineShift * 0.4;
          baseXPct = isHomeSide ? clamp(3.5 + depth + depthMod, 10, 52) : clamp(100 - (3.5 + depth + depthMod), 48, 90);

          const isAttacker = slot.y < 40;
          const widthVal = isAttacker ? (tac.attackingWidth || 60) : (tac.defensiveWidth || 50);
          const widthDiff = isAttacker ? (widthVal - 60) : (widthVal - 50);
          const centeredY = slot.x - 50;
          baseYPct = clamp(50 + centeredY * (1 + widthDiff * 0.007), 8, 92);
        }

        players.push({
          type: 'PLAYER',
          id: `u-${i}`,
          key: playerKey(p),
          name: p.name.split(' ').pop() || p.name,
          fullName: p.name,
          pos: isGoalkeeper ? 'GK' : (normPos || slot.r || p.pos || 'CM'),
          roleId: role.id,
          roleName: role.role || role.name,
          roleFocus: role.focus,
          roleDef: role,
          depthRuns: role.depthRuns || 0,
          boxPresence: role.boxPresence || 0,
          buildUpDrop: role.buildUpDrop || 0,
          offsideRisk: role.offsideRisk || 0,
          shotTendency: role.shotTendency || 0,
          creativePassing: role.creativePassing || 0,
          widthMaintenance: role.widthMaintenance || 0,
          halfSpaceOcc: role.halfSpaceOcc || 0,
          pressIntensity: role.pressIntensity || 50,
          coverDefense: role.coverDefense || 50,
          staminaCost: role.staminaCost || 25,
          overall: ovr,
          attrs,
          stamina: 100,
          isGK: isGoalkeeper,
          canScore: !isGoalkeeper,
          canShoot: !isGoalkeeper,
          canAssist: true,
          isCaptain: (state.setPieces?.captain === playerKey(p) || (!state.setPieces?.captain && i === 1)),
          team: isHomeSide ? 'home' : 'away',
          clubId: teamName,
          teamId: isHomeSide ? 'home' : 'away',
          isUser: true,
          careerPlayerId: p.id,
          isControlledAthlete: Boolean(isUserAthlete),
          wasStarter: Boolean(isUserAthlete),
          enteredMinute: 0,
          photo: resolvePlayerPhotoUrl(p) || null,
          x: baseXPct,
          y: baseYPct,
          baseX: baseXPct,
          baseY: baseYPct,
          targetX: baseXPct,
          targetY: baseYPct,
          vx: 0, vy: 0,
          animFrame: 0,
          hasBall: false
        });
      }
    } else {
      const liveOpp = livePlayers.filter(p => norm(p.club) === norm(teamName));
      let oppRoster = (liveOpp.length >= 11 ? [...liveOpp] : null);
      if(!oppRoster || !Array.isArray(oppRoster) || oppRoster.length < 11){
        const fallback = generatedRosterForClub(teamName);
        oppRoster = Array.isArray(oppRoster) ? [...oppRoster, ...fallback] : fallback;
      }
      let oppGK = oppRoster.find(p => isGoalkeeperPosition(p.pos)) || oppRoster[0];
      if(!oppGK){
        oppGK = { name: `Goleiro ${teamName}`, pos: 'GK', fc: 65, pes: 65 };
      }
      let oppOutfield = oppRoster.filter(p => p !== oppGK && !isGoalkeeperPosition(p.pos));
      while(oppOutfield.length < 10){
        const idx = oppOutfield.length;
        oppOutfield.push({
          name: `${NAMES[idx % NAMES.length]} ${LAST[idx % LAST.length]}`,
          pos: formDef[idx + 1]?.r || 'CM',
          fc: 64, pes: 64
        });
      }

      for(let i=0; i<11; i++){
        const isGoalkeeper = (i === 0);
        let p;
        if(isGoalkeeper){
          p = oppGK;
        } else {
          p = oppOutfield[i - 1] || oppRoster.find(x => x !== oppGK && !players.some(pl => pl.fullName === x.name)) || { name: `${NAMES[i%NAMES.length]} ${LAST[i%LAST.length]}`, pos: formDef[i]?.r || 'CM', fc: 64 };
        }
        const slot = formDef[i] || { r: isGoalkeeper ? 'GK' : 'CM', x: 50, y: isGoalkeeper ? 89 : 50 };
        const ovr = playerOverall(p) || p.fc || p.pes || 64;
        const attrs = calcPlayerAttrs(p.name, isGoalkeeper ? 'GK' : slot.r, ovr);
        const presetRoleItem = presetObj.roles?.[i];
        const role = presetRoleItem ? getPlayerRoleDef(slot.r, presetRoleItem.role) : getPlayerRoleDef(slot.r, null);

        let baseXPct, baseYPct;
        if(isGoalkeeper){
          baseXPct = isHomeSide ? 3.5 : 96.5;
          baseYPct = 50;
        } else {
          const depth = (100 - slot.y) * 0.44;
          const tacLine = tac.lineHeight || 60;
          const lineShift = (tacLine - 60) * 0.14;
          const isBackline = slot.y > 60;
          const depthMod = isBackline ? lineShift * 0.8 : lineShift * 0.4;
          baseXPct = isHomeSide ? clamp(3.5 + depth + depthMod, 10, 52) : clamp(100 - (3.5 + depth + depthMod), 48, 90);

          const isAttacker = slot.y < 40;
          const widthVal = isAttacker ? (tac.attackingWidth || 60) : (tac.defensiveWidth || 50);
          const widthDiff = isAttacker ? (widthVal - 60) : (widthVal - 50);
          const centeredY = slot.x - 50;
          baseYPct = clamp(50 + centeredY * (1 + widthDiff * 0.007), 8, 92);
        }

        players.push({
          type: 'PLAYER',
          id: `opp-${i}`,
          key: `opp-${i}`,
          name: p.name.split(' ').pop() || p.name,
          fullName: p.name,
          pos: isGoalkeeper ? 'GK' : (slot.r || p.pos || 'CM'),
          roleId: role.id,
          roleName: role.role || role.name,
          roleFocus: role.focus,
          roleDef: role,
          depthRuns: role.depthRuns || 0,
          boxPresence: role.boxPresence || 0,
          buildUpDrop: role.buildUpDrop || 0,
          offsideRisk: role.offsideRisk || 0,
          shotTendency: role.shotTendency || 0,
          creativePassing: role.creativePassing || 0,
          widthMaintenance: role.widthMaintenance || 0,
          halfSpaceOcc: role.halfSpaceOcc || 0,
          pressIntensity: role.pressIntensity || 50,
          coverDefense: role.coverDefense || 50,
          staminaCost: role.staminaCost || 25,
          overall: ovr,
          attrs,
          stamina: 100,
          isGK: isGoalkeeper,
          canScore: !isGoalkeeper,
          canShoot: !isGoalkeeper,
          canAssist: true,
          isCaptain: (i === 1),
          team: isHomeSide ? 'home' : 'away',
          clubId: teamName,
          teamId: isHomeSide ? 'home' : 'away',
          isUser: false,
          photo: null,
          x: baseXPct,
          y: baseYPct,
          baseX: baseXPct,
          baseY: baseYPct,
          targetX: baseXPct,
          targetY: baseYPct,
          vx: 0, vy: 0,
          animFrame: 0,
          hasBall: false
        });
      }
    }

    // REGRA DE OURO: Garantia estrita de exatamente 11 atletas escalados em campo
    while(players.length < 11){
      const i = players.length;
      const isGoalkeeper = (i === 0);
      const slot = formDef[i] || { r: isGoalkeeper ? 'GK' : 'CM', x: 50, y: isGoalkeeper ? 89 : 50 };
      const role = getPlayerRoleDef(slot.r, null);
      let baseXPct, baseYPct;
      if(isGoalkeeper){
        baseXPct = isHomeSide ? 3.5 : 96.5;
        baseYPct = 50;
      } else {
        const depth = (100 - slot.y) * 0.44;
        baseXPct = isHomeSide ? clamp(3.5 + depth, 12, 48) : clamp(100 - (3.5 + depth), 52, 88);
        baseYPct = clamp(slot.x, 10, 90);
      }
      players.push({
        type: 'PLAYER',
        id: `${isHomeSide?'h':'a'}-fill-${i}`,
        key: `${isHomeSide?'h':'a'}-fill-${i}`,
        name: `Jogador ${i+1}`,
        fullName: `Jogador ${i+1}`,
        pos: isGoalkeeper ? 'GK' : (slot.r || 'CM'),
        roleId: role.id,
        roleName: role.role || role.name,
        roleFocus: role.focus,
        roleDef: role,
        depthRuns: role.depthRuns || 0,
        boxPresence: role.boxPresence || 0,
        buildUpDrop: role.buildUpDrop || 0,
        offsideRisk: role.offsideRisk || 0,
        shotTendency: role.shotTendency || 0,
        creativePassing: role.creativePassing || 0,
        widthMaintenance: role.widthMaintenance || 0,
        halfSpaceOcc: role.halfSpaceOcc || 0,
        pressIntensity: role.pressIntensity || 50,
        coverDefense: role.coverDefense || 50,
        staminaCost: role.staminaCost || 25,
        overall: 65,
        attrs: calcPlayerAttrs(`Jogador ${i+1}`, isGoalkeeper ? 'GK' : slot.r, 65),
        stamina: 100,
        isGK: isGoalkeeper,
        canScore: !isGoalkeeper,
        canShoot: !isGoalkeeper,
        canAssist: true,
        isCaptain: (i === 1),
        team: isHomeSide ? 'home' : 'away',
        clubId: teamName,
        teamId: isHomeSide ? 'home' : 'away',
        isUser,
        photo: null,
        x: baseXPct,
        y: baseYPct,
        baseX: baseXPct,
        baseY: baseYPct,
        targetX: baseXPct,
        targetY: baseYPct,
        vx: 0, vy: 0,
        animFrame: 0,
        hasBall: false
      });
    }

    return players.slice(0, 11);
  }

  const hTac = getClubTacticalProfile(home, isUserHome);
  const aTac = getClubTacticalProfile(away, !isUserHome);
  const resolveMatchClubKit = (clubNameStr, isAwaySide, opponentPrimaryHex = null) => {
    const nClub = norm(clubNameStr);
    const customEntry = (state?.customClub && norm(state.customClub.name) === nClub)
      ? { home: state.customClub.homeKit, away: state.customClub.awayKit, third: state.customClub.thirdKit, gk: state.customClub.gkKit }
      : (window.CUSTOM_CLUB_KITS && window.CUSTOM_CLUB_KITS[nClub] ? window.CUSTOM_CLUB_KITS[nClub] : null);
    if(customEntry){
      let chosen = isAwaySide ? (customEntry.away || customEntry.home) : (customEntry.home || customEntry.away);
      if(opponentPrimaryHex && chosen?.shirtColor && String(chosen.shirtColor).toLowerCase() === String(opponentPrimaryHex).toLowerCase()){
        chosen = customEntry.third || (isAwaySide ? customEntry.home : customEntry.away) || chosen;
      }
      if(chosen){
        return {
          primary: chosen.shirtColor || '#1e3a8a',
          secondary: chosen.secondaryColor || '#ffffff',
          shorts: chosen.shortsColor || chosen.shirtColor || '#1e3a8a',
          socks: chosen.socksColor || '#ffffff',
          numberColor: chosen.numberColor || '#ffffff',
          style: chosen.style || 'solid',
          gkPrimary: customEntry.gk?.shirtColor || '#10b981',
          gkShorts: customEntry.gk?.shortsColor || '#064e3b'
        };
      }
    }
    return window.AFM_REAL_FOOTBALL ? window.AFM_REAL_FOOTBALL.getClubKit(clubNameStr, isAwaySide) : null;
  };
  const homeKit = resolveMatchClubKit(home, false, null);
  const awayKit = resolveMatchClubKit(away, true, homeKit?.primary || null);
  const homePlayers = buildMatchTeam(home, isUserHome, true, hTac);
  const awayPlayers = buildMatchTeam(away, !isUserHome, false, aTac);
  homePlayers.forEach(p => { p.kit = p.isGK && homeKit?.gkPrimary ? { ...homeKit, primary: homeKit.gkPrimary, shorts: homeKit.gkShorts || homeKit.shorts } : homeKit; p.clubName = home; });
  awayPlayers.forEach(p => { p.kit = p.isGK && awayKit?.gkPrimary ? { ...awayKit, primary: awayKit.gkPrimary, shorts: awayKit.gkShorts || awayKit.shorts } : awayKit; p.clubName = away; });

  const rivalry = isRivalryMatch(home, away);
  const matchSeed = (Date.now() ^ (Math.random() * 0x100000000)) >>> 0;

  const referee = {
    type: 'REFEREE',
    id: `ref_${matchSeed}`,
    name: 'Árbitro Principal',
    x: 50,
    y: 50,
    baseX: 50,
    baseY: 50,
    animFrame: 0,
    canScore: false,
    canShoot: false,
    canAssist: false,
    isGK: false
  };

  liveMatchState = {
    matchId: 'MAT_' + Date.now() + '_' + Math.floor(Math.random() * 10000),
    seed: matchSeed,
    prng: createMatchPRNG(matchSeed),
    simMinute: 0,
    simTicks: 0,
    renderTicks: 0,
    simAccumulator: 0,
    lastLoopTime: (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now(),
    debugMode: false,
    home, away, isKO,
    hg: 0, ag: 0,
    timeSec: 0, // 0 a 5400 segundos (90 min)
    minute: 0,
    playing: true,
    speed: state.simSpeed === 'fast' ? 2 : state.simSpeed === 'instant' ? 40 : 1, // 1, 2, 5, 10, 20, 40
    isNight: (Math.random() < 0.50) || (state.weather && state.weather.includes('Noite')),
    derby: rivalry?.isRivalry ? rivalry.derbyName : '',
    balloons: [],
    varCheck: null,
    events: [
      { id: `MAT_${Date.now()}_ev_0`, matchId: 'MAT_' + Date.now(), min: 0, type: 'whistle', text: `${rivalry?.isRivalry ? `🔥 GRANDE CLÁSSICO: ${rivalry.derbyName.toUpperCase()}! ` : ''}Começa o jogo! ${home} e ${away} em campo no ${stadiumName}.` }
    ],
    timeline: [],
    recentPlayPatterns: [],
    referee,
    stats: {
      posH: 50, posA: 50,
      shotsH: 0, shotsA: 0,
      targetH: 0, targetA: 0,
      xGH: 0.0, xGA: 0.0,
      foulsH: 0, foulsA: 0,
      cornersH: 0, cornersA: 0,
      yellowsH: 0, yellowsA: 0,
      redsH: 0, redsA: 0
    },
    stadium: {
      name: stadiumName,
      profile: stadiumProfile,
      customization: isUserHome ? (state.stadiumCustomization || {}) : {},
      capacity: stadiumCap,
      attendance,
      pitch: stadiumPitch,
      upgrades: stadiumUpgrades
    },
    attendanceForceBonus,
    homePosture: 'Equilibrada',
    awayPosture: 'Equilibrada',
    prelecao: 'Sem preleção',
    subsLeft: 5,
    homeKit,
    awayKit,
    homeSubs: { count: 0, windowsUsed: 0, lastMin: -1 },
    awaySubs: { count: 0, windowsUsed: 0, lastMin: -1 },
    stoppage1H: window.AFM_REAL_FOOTBALL ? window.AFM_REAL_FOOTBALL.rules.calculateStoppageTime(1, []) : 2,
    stoppage2H: window.AFM_REAL_FOOTBALL ? window.AFM_REAL_FOOTBALL.rules.calculateStoppageTime(2, []) : 4,
    stoppageBoard1HShown: false,
    stoppageBoard2HShown: false,
    autoSubAssistant: true,
    halftimeTriggered: false,
    homePlayers,
    awayPlayers,
    playerCareerAvailableForMatch: window.AFM_PlayerEngine?.isPlayerAvailableForMatch?.(state) ?? state.gameMode !== 'player',
    homeTac: hTac,
    awayTac: aTac,
    tacticsDynamics: calculateTacticalMatchDynamics(home, away, hTac, aTac, hs, as),
    otherResults,
    ball: {
      x: 50, y: 50, z: 0,
      vx: 0, vy: 0, vz: 0,
      carrier: homePlayers.find(p => !p.isGK && ['CM','DM','AM'].includes(p.pos)) || homePlayers[9] || homePlayers[0],
      mode: 'play',
      state: 'play'
    },
    particles: [],
    soundMuted: false,
    phase: 'FIRST_HALF',
    subbedOut: [],
    winners,
    done: false
  };
  if(typeof window !== 'undefined') window.liveMatchState = liveMatchState;

  if(state.gameMode === 'player'){
    const playerTeam = isUserHome ? liveMatchState.homePlayers : liveMatchState.awayPlayers;
    const controlledPlayer = playerTeam.find(p => p.isControlledAthlete);
    liveMatchState.controlledAthleteOnPitch = Boolean(controlledPlayer);
    if(controlledPlayer){
      if(typeof syncControlledAthletePitchSlotAndCoords === 'function'){
        syncControlledAthletePitchSlotAndCoords(liveMatchState, true);
      }
      liveMatchState.events.unshift({ min: 0, type: 'lineup', text: `✅ ${controlledPlayer.fullName || controlledPlayer.name} foi escalado como titular do ${state.club}.` });
    }
  }

  if (window.afmAudio) {
    window.afmAudio.startCrowdAmbient(home, comp?.id);
    window.afmAudio.playSFX('whistle_start');
  } else {
    playWhistleSound();
  }
  renderLiveMatchModal();
  const playerTeam = isUserHome ? liveMatchState.homePlayers : liveMatchState.awayPlayers;
  const controlledPlayer = playerTeam.find(p => p.isControlledAthlete);
  if(controlledPlayer){
    showLiveBanner(`⭐ VOCÊ COMEÇA COMO TITULAR: ${controlledPlayer.fullName || controlledPlayer.name}!`, 'tactics', 3500);
    toast(`⭐ Você foi escalado como titular do ${state.club}!`);
  }
  } finally {
    setTimeout(() => { isStartingLiveMatch = false; }, 400);
  }
}

function renderLiveMatchModal(){
  let el = $('#matchModalContainer');
  if(!el){
    el = document.createElement('div');
    el.id = 'matchModalContainer';
    if(document.body && typeof document.body.appendChild === 'function') document.body.appendChild(el);
  }

  const s = liveMatchState;
  if(!s){ el.remove(); return; }

  const comp = curComp();
  const occPct = Math.round(clamp(((s.stadium?.attendance || 15000) / (s.stadium?.capacity || 20000)) * 100, 1, 100));
  const minDisplay = String(Math.floor(s.timeSec / 60)).padStart(2, '0');
  const secDisplay = String(Math.floor(s.timeSec % 60)).padStart(2, '0');

  el.innerHTML = `
    <div class="live-match-fullscreen">
      <!-- HEADER COM BREADCRUMB E PLACAR FLUTUANTE -->
      <div class="live-match-header">
        <div class="live-match-breadcrumb">
          INÍCIO &gt; CARREIRA ${esc(state.club.toUpperCase())} &gt; ${esc(s.home.slice(0,3).toUpperCase())} X ${esc(s.away.slice(0,3).toUpperCase())} &gt; <span style="color:#22c55e">AO VIVO</span>
        </div>

        <div class="live-scoreboard-floating">
          <div class="live-scoreboard-comp">
            🏆 ${esc(comp.name.toUpperCase())} · RODADA ${state.round + 1}
          </div>
          <div class="live-scoreboard-main">
            <div class="live-scoreboard-team">
              ${clubBadge(s.home, 26)}
              <span>${esc(s.home)}</span>
            </div>
            <div class="live-scoreboard-score">
              <span id="liveScoreH">${s.hg}</span> . <span id="liveScoreA">${s.ag}</span>
            </div>
            <div class="live-scoreboard-team">
              <span>${esc(s.away)}</span>
              ${clubBadge(s.away, 26)}
            </div>
          </div>
          <div class="live-scoreboard-clock" id="liveClockDisplay">
            ${minDisplay}:${secDisplay}
          </div>
        </div>

        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <button class="live-ctrl-btn" id="btnToggle2D3D" style="background:${(s.renderMode || '3d') === '2d' ? 'rgba(59,130,246,0.3)' : 'linear-gradient(135deg,#7c3aed,#2563eb)'};border:1px solid #818cf8;color:#fff;font-weight:800;padding:5px 12px;border-radius:6px;font-size:11px" title="Alternar entre Estádio 3D e Visão 2D">
            ${(s.renderMode || '3d') === '2d' ? '📐 VER EM 2D' : '🏟️ VER EM 3D'}
          </button>
          <div class="live-cam-group" style="display:inline-flex;background:rgba(15,23,42,0.85);border:1px solid rgba(255,255,255,0.15);border-radius:6px;padding:2px;gap:2px">
            <button class="live-ctrl-btn ${(!s.cameraMode || s.cameraMode === 'lateral' || s.cameraMode === 'tv') ? 'active' : ''}" id="btnCamLateral" style="padding:4px 8px;font-size:11px;font-weight:700">Lateral</button>
            <button class="live-ctrl-btn ${s.cameraMode === 'ball' ? 'active' : ''}" id="btnCamBall" style="padding:4px 8px;font-size:11px;font-weight:700">Bola</button>
            <button class="live-ctrl-btn ${s.cameraMode === 'goal' ? 'active' : ''}" id="btnCamGoal" style="padding:4px 8px;font-size:11px;font-weight:700">Gol</button>
          </div>
          <button class="live-ctrl-btn" id="btnLiveClose" style="background:rgba(239,68,68,0.2);border-color:#ef4444;color:#fca5a5" title="Sair / Fechar">
            ✕ Fechar
          </button>
        </div>
      </div>

      <!-- CORPO PRINCIPAL COM CAMPO 2.5D E LATERAL DE NARRAÇÃO -->
      <div class="live-body-layout">
        <div class="live-canvas-area" id="liveCanvasArea">
          <div class="live-canvas-wrapper">
            <!-- PILLS FLUTUANTES SOBRE O CAMPO -->
            <div class="live-pitch-pills">
              <div class="live-pitch-pill gold">
                ${esc((s.stadium?.name || 'Estádio Municipal').toUpperCase())} · PÚBLICO <b>${(s.stadium?.attendance || 12000).toLocaleString('pt-BR')}</b>
              </div>
              <div class="live-pitch-pill">
                ${esc(s.home.slice(0,3).toUpperCase())}: ${esc((s.homePosture || 'Equilibrada').toUpperCase())}
              </div>
              <div class="live-pitch-pill" id="livePillAwayPosture">
                ${esc(s.away.slice(0,3).toUpperCase())}: ${esc((s.awayPosture || 'Equilibrada').toUpperCase())}
              </div>
              ${s.prelecao && s.prelecao !== 'Sem preleção' ? `
                <div class="live-pitch-pill" id="livePillPrelecao" style="background:rgba(168,85,247,0.3);border-color:#a855f7;color:#e9d5ff">
                  🗣️ PRELEÇÃO: ${esc(s.prelecao.toUpperCase())}
                </div>
              ` : ''}
            </div>

            <!-- OVERLAY DE PAUSA -->
            <div class="live-pause-pill" id="livePauseOverlay" style="display:${s.playing ? 'none' : 'inline-flex'}">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M6 4l14 8-14 8z"></path></svg>
              <span>Pausado · toque para continuar</span>
            </div>

            <!-- CANVAS 1280x720 DA TRANSMISSÃO -->
            <canvas id="liveMatchCanvas" class="live-match-canvas" width="1280" height="720" aria-label="Transmissão da partida"></canvas>
          </div>
        </div>

        <!-- SIDEBAR DE NARRAÇÃO AO VIVO -->
        <div class="live-sidebar">
          <div class="live-sidebar-header">
            <span>• NARRAÇÃO AO VIVO</span>
            <span style="font-size:11px;background:#ef4444;color:#fff;padding:2px 6px;border-radius:4px" id="liveEventCount">${s.events.length}</span>
          </div>
          <div class="live-sidebar-feed" id="liveEventList">
            ${s.events.map(e => `
              <div class="live-sidebar-item ${e.type === 'gol' ? 'gol' : e.type === 'yellow' ? 'yellow' : e.type === 'red' ? 'red' : e.type === 'save' ? 'save' : ''}">
                <b style="color:#fbbf24">${e.min}'</b>
                <div>${esc(e.text)}</div>
              </div>
            `).join('')}
          </div>
        </div>
      </div>

      <!-- DOCK INFERIOR COM ESTATÍSTICAS E CONTROLES -->
      <div class="live-bottom-dock">
        <div class="live-dock-stats">
          <div class="live-dock-stats-row">
            <span id="liveShotsLabel">${s.stats.shotsH} FINALIZAÇÕES ${s.stats.shotsA}</span>
            <span>
              🟨 ${s.stats.yellowsH} 🟥 ${s.stats.redsH} &nbsp;&nbsp; CARTÕES &nbsp;&nbsp; 🟨 ${s.stats.yellowsA} 🟥 ${s.stats.redsA}
            </span>
          </div>
          <div class="live-shots-bar">
            <div class="live-shots-fill-home" id="liveShotsFillH" style="width:${(s.stats.shotsH+s.stats.shotsA) > 0 ? (s.stats.shotsH/(s.stats.shotsH+s.stats.shotsA)*100) : 50}%"></div>
            <div class="live-shots-fill-away" id="liveShotsFillA" style="width:${(s.stats.shotsH+s.stats.shotsA) > 0 ? (s.stats.shotsA/(s.stats.shotsH+s.stats.shotsA)*100) : 50}%"></div>
          </div>
          <div class="live-dock-subtext">
            ${esc((s.stadium?.name || 'Estádio Municipal').toUpperCase())} · Público presente <b>${(s.stadium?.attendance || 12000).toLocaleString('pt-BR')}</b> (${occPct}% da capacidade)
          </div>
        </div>

        ${!s.done ? (Boolean(state?.gameMode === 'player' || state?.playerCareerState) ? `
          <!-- BARRA DE COMANDOS DO CRAQUE: MODO JOGADOR (BE A PRO) -->
          <div class="live-craque-commands" style="display:flex;gap:8px;align-items:center;padding:8px 14px;background:linear-gradient(135deg, rgba(6,78,59,0.95), rgba(15,23,42,0.95));border-top:2px solid #10b981;flex-wrap:wrap">
            <span style="font-size:11px;font-weight:900;color:#6ee7b7;letter-spacing:0.5px">★ COMANDOS DO CRAQUE:</span>
            <button type="button" class="live-craque-btn" id="btnCraqueCallBall" style="background:rgba(56,189,248,0.2);border:1px solid #38bdf8;color:#bae6fd;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              ⚽ Pedir a Bola
            </button>
            <button type="button" class="live-craque-btn" id="btnCraqueShoot" style="background:rgba(239,68,68,0.2);border:1px solid #ef4444;color:#fca5a5;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              🎯 Chutar a Gol
            </button>
            <button type="button" class="live-craque-btn" id="btnCraqueSprint" style="background:rgba(234,179,8,0.2);border:1px solid #eab308;color:#fef08a;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              ⚡ Arrancada / Pique
            </button>
            <button type="button" class="live-craque-btn" id="btnCraquePress" style="background:rgba(168,85,247,0.2);border:1px solid #a855f7;color:#e9d5ff;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              🛡️ Pressionar Marcação
            </button>
            <button type="button" class="live-craque-btn" id="btnCraqueStaminaStatus" style="background:rgba(16,185,129,0.25);border:1px solid #10b981;color:#6ee7b7;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:900;cursor:pointer;margin-left:auto">
              ⭐ MEU CRAQUE & FÔLEGO
            </button>
          </div>
        ` : `
          <!-- BARRA DE GRITOS DA BEIRA DO CAMPO (MODO TREINADOR) -->
          <div class="live-coach-shouts" style="display:flex;gap:8px;align-items:center;padding:8px 14px;background:rgba(15,23,42,0.92);border-top:1px solid rgba(255,255,255,0.08);flex-wrap:wrap">
            <span style="font-size:11px;font-weight:900;color:#38bdf8;letter-spacing:0.5px">🗣️ BEIRA DO CAMPO:</span>
            <button class="live-shout-btn" data-shout="press" style="background:rgba(239,68,68,0.2);border:1px solid #ef4444;color:#fca5a5;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              🔥 Subir Linhas & Pressão
            </button>
            <button class="live-shout-btn" data-shout="calm" style="background:rgba(56,189,248,0.2);border:1px solid #38bdf8;color:#bae6fd;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              🧠 Calma & Posse de Bola
            </button>
            <button class="live-shout-btn" data-shout="counter" style="background:rgba(234,179,8,0.2);border:1px solid #eab308;color:#fef08a;padding:5px 12px;border-radius:6px;font-size:11px;font-weight:800;cursor:pointer">
              🎯 Fechar Espaços & Contragolpe
            </button>
            ${s.coachShout ? `<span style="font-size:11px;color:#22c55e;font-weight:800;margin-left:auto">✓ Instrução em andamento</span>` : ''}
          </div>
        `) : ''}

        ${s.done ? `
          <div class="live-postmatch-diag" style="margin:8px 14px;padding:12px 16px;background:rgba(15,23,42,0.96);border:1px solid #38bdf8;border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,0.6)">
            <div style="display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(56,189,248,0.25);padding-bottom:6px;margin-bottom:8px">
              <span style="font-size:13px;font-weight:900;color:#38bdf8;letter-spacing:0.5px">🧠 DIAGNÓSTICO TÁTICO PÓS-JOGO</span>
              <span style="font-size:11px;font-weight:800;color:#facc15">xG: ${s.stats.xGH} vs ${s.stats.xGA}</span>
            </div>
            <div style="font-size:12px;color:#e2e8f0;line-height:1.5;margin-bottom:8px">
              ${(function(){
                const isHomeUser = norm(s.home) === norm(state.club);
                const uGoals = isHomeUser ? s.hg : s.ag;
                const oGoals = isHomeUser ? s.ag : s.hg;
                const uXG = isHomeUser ? s.stats.xGH : s.stats.xGA;
                const oXG = isHomeUser ? s.stats.xGA : s.stats.xGH;
                if(uGoals > oGoals){
                  return `<b>Vitória construída com autoridade tática!</b> A equipe executou com maestria a formação <i>${esc(state.formation || '4-3-3')}</i>, criando <b>${uXG} xG</b> e convertendo com eficiência, enquanto as coberturas defensivas neutralizaram o contra-ataque adversário.`;
                } else if(uGoals < oGoals){
                  return `<b>Revés tático!</b> A equipe teve dificuldades em fechar as entrelinhas e concedeu <b>${oXG} xG</b> ao adversário. Recomenda-se ajustar as funções defensivas e a postura em transições.`;
                } else {
                  return `<b>Empate truncado!</b> Confronto equilibrado em que ambas as formações táticas travaram a criação pelo meio de campo.`;
                }
              })()}
            </div>
            <div style="display:flex;gap:14px;font-size:11px;color:#94a3b8;flex-wrap:wrap">
              <span>🎯 Finalizações: <b>${s.stats.shotsH} x ${s.stats.shotsA}</b></span>
              <span>🧤 No Alvo: <b>${s.stats.targetH} x ${s.stats.targetA}</b></span>
              <span>🚩 Escanteios: <b>${s.stats.cornersH} x ${s.stats.cornersA}</b></span>
              <span>🛡️ Faltas: <b>${s.stats.foulsH} x ${s.stats.foulsA}</b></span>
            </div>
          </div>
        ` : ''}

        <div class="live-dock-controls">
          ${!s.done ? `
            <button class="live-ctrl-btn ${s.speed === 1 ? 'active' : ''}" id="btnLiveSpeed1">1x</button>
            <button class="live-ctrl-btn ${s.speed === 2 ? 'active' : ''}" id="btnLiveSpeed2">2x</button>
            <button class="live-ctrl-btn ${s.speed === 5 ? 'active' : ''}" id="btnLiveSpeed5">5x</button>
            <button class="live-ctrl-btn ${s.speed === 10 ? 'active' : ''}" id="btnLiveSpeed10">10x</button>
            <button class="live-ctrl-btn ${s.speed === 20 ? 'active' : ''}" id="btnLiveSpeed20">20x</button>
            <button class="live-ctrl-btn ${s.speed === 40 ? 'active' : ''}" id="btnLiveSpeed40">40x</button>

            <button class="live-ctrl-btn play-circle" id="btnLivePlayToggle" title="Pausar / Continuar">
              ${s.playing ? '⏸' : '▶'}
            </button>

            <button class="live-ctrl-btn" id="btnLiveForward1" title="Avançar 1 minuto no jogo">⏩ 1 min</button>
            <button class="live-ctrl-btn green-tactics" id="btnLiveTactics" title="Substituições e Tática">
              ${(state?.gameMode === 'player' || state?.playerCareerState) ? '⭐ MEU CRAQUE' : '⚡ MEXER NO TIME'}
            </button>
            ${s.phase === 'FIRST_HALF' ? `<button class="live-ctrl-btn" id="btnLiveSkipHalf" title="Pular para o intervalo">⏩| PULAR 1º TEMPO</button>` : (s.phase === 'HALF_TIME' ? `<button class="live-ctrl-btn" id="btnLiveSkipHalf" title="Iniciar 2º Tempo">▶ INICIAR 2º TEMPO</button>` : '')}
            <button class="live-ctrl-btn" id="btnLiveSkipEnd" title="Simular até o apito final">⏭| IR AO FIM</button>
            <button class="live-ctrl-btn" id="btnLiveSound" title="Ligar/Desligar som">
              ${s.soundMuted ? '🔇 MUDO' : '🔊 SOM'}
            </button>
          ` : `
            <div style="display:flex;align-items:center;justify-content:center;gap:14px;width:100%;flex-wrap:wrap;padding:4px 0">
              <button class="live-ctrl-btn" id="btnLiveSound" title="Ligar/Desligar som" style="padding:10px 18px;font-size:12px">
                ${s.soundMuted ? '🔇 MUDO' : '🔊 SOM'}
              </button>
              <button class="live-ctrl-btn" id="btnLiveAdvanceRound" style="background:#22c55e;color:#052e16;font-weight:900;font-size:14px;padding:12px 36px;border-radius:10px;box-shadow:0 0 24px rgba(34,197,94,0.5);border:none;cursor:pointer">
                AVANÇAR RODADA ➔
              </button>
            </div>
          `}
        </div>
      </div>
    </div>
  `;

  // Inicializa o Canvas e inicia o renderizador loop
  setupLiveCanvasLoop();
  bindLiveMatchEvents();
}

function showLiveBalloon(x, y, text, color){
  if(!liveMatchState) return;
  liveMatchState.balloons = liveMatchState.balloons || [];
  const textStr = String(text || '');
  const existing = liveMatchState.balloons.find(b => b.text === textStr && (b.maxLife - b.life) < 1.4);
  if(existing) return;
  if(liveMatchState.balloons.length >= 2) liveMatchState.balloons.shift();
  const speed = Math.max(1, liveMatchState.speed || 1);
  const balloonLife = speed >= 20 ? 0.6 : speed >= 10 ? 0.9 : speed >= 2 ? 1.3 : 2.2;
  liveMatchState.balloons.push({
    x: clamp(Number(x) || 50, 14, 86),
    y: clamp(Number(y) || 50, 18, 82),
    text: textStr,
    color: color || '#fbbf24',
    life: balloonLife,
    maxLife: balloonLife
  });
}

function showLiveBanner(text, type, durationMs){
  const overlay = $('#livePauseOverlay');
  if(overlay && text){
    const origHtml = overlay.innerHTML;
    overlay.innerHTML = `<span>${esc(text)}</span>`;
    overlay.style.display = 'inline-flex';
    const sSpeed = (liveMatchState && liveMatchState.speed) ? Math.max(1, liveMatchState.speed) : 1;
    // Em velocidades aceleradas (2x, 5x, 10x, 20x, 40x), escala o tempo do banner para não tampar o campo
    const scaledDuration = Math.max(500, Math.round((durationMs || 3000) / (sSpeed >= 20 ? (sSpeed * 0.35) : sSpeed >= 5 ? (sSpeed * 0.45) : Math.max(1, sSpeed * 0.6))));
    setTimeout(() => {
      if(liveMatchState && !liveMatchState.playing){
        overlay.innerHTML = origHtml;
      } else if(overlay) {
        overlay.style.display = 'none';
        overlay.innerHTML = origHtml;
      }
    }, scaledDuration);
  }
}

function selectLivePassTarget(players, passer, minForward = 1.5, maxDistance = 26) {
  if(!passer) return null;
  const direction = passer.team === 'home' ? 1 : -1;
  const px = Number(passer.x) || 50, py = Number(passer.y) || 50;
  const isPlayerMode = Boolean(state?.gameMode === 'player' || state?.playerCareerState);
  const now = Date.now();
  const callActive = liveMatchState && liveMatchState.craqueCallBallUntil && now < liveMatchState.craqueCallBallUntil;

  const choices = (players || []).filter(p => p && p !== passer && !p.isGK && !p.redCard && p.team === passer.team).map(player => {
    const dx = ((Number(player.x) || 50) - px) * direction;
    const dy = Math.abs((Number(player.y) || 50) - py);
    const distance = Math.hypot(dx, dy);
    let score = dx * 1.35 - dy * 0.32 - distance * 0.12 + (Number(player.depthRuns) || 0) * 0.025 + (Number(player.creativePassing) || 0) * 0.004;

    if(isPlayerMode && player.isControlledAthlete){
      if(callActive){
        score += 180; // 85%+ de chance se pediu a bola
      } else {
        score += 38; // 45% a 60% de peso prioritário para acionar o craque do usuário
      }
    }
    return { player, forward: dx, distance, score };
  }).filter(row => (callActive && row.player.isControlledAthlete) || (row.forward >= (minForward - 1.2) && row.distance <= (maxDistance + 14))).sort((a, b) => b.score - a.score);
  return choices[0]?.player || null;
}
window.selectLivePassTarget = selectLivePassTarget;

function startLivePass(s, passer, receiver, options = {}) {
  if(!s || !s.ball || !passer || !receiver || passer === receiver || passer.team !== receiver.team || passer.isGK || passer.redCard || receiver.isGK || receiver.redCard) return false;
  const ball = s.ball;
  const direction = passer.team === 'home' ? 1 : -1;
  ball.mode = 'pass';
  ball.startX = clamp((Number(passer.x) || 50) + direction * 1.2, 2, 98);
  ball.startY = clamp(Number(passer.y) || 50, 6, 94);
  ball.x = ball.startX; ball.y = ball.startY; ball.z = 0;
  ball.vx = 0; ball.vy = 0; ball.vz = 0;
  ball.progress = 0;
  ball.curveZ = 2.2;
  ball.passTarget = receiver;
  ball.passer = passer;
  ball.carrier = null;
  ball.liveDecisionCooldown = Math.max(35, Number(options.cooldownFrames) || 110);
  ball.isHomeAttacking = passer.team === 'home';
  passer.hasBall = false;
  receiver.hasBall = false;
  if(s.stats){
    if(passer.team === 'home') s.stats.passesH = (s.stats.passesH || 0) + 1;
    else s.stats.passesA = (s.stats.passesA || 0) + 1;
  }
  if(options.logEvent && Array.isArray(s.events)){
    s.events.unshift({ min: Number(s.minute) || 0, type: 'pass', text: '🔁 ' + (passer.fullName || passer.name || 'Jogador') + ' toca para ' + (receiver.fullName || receiver.name || 'companheiro') + ' e a equipe progride com a bola.' });
  }
  return true;
}

function startLiveShot(s, shooter){
  if(!s || !s.ball || !shooter) return;
  const isHomeAttacking = shooter.team === 'home';
  s.ball.carrier = null;
  s.ball.mode = 'shot';
  s.ball.shooter = shooter;
  s.ball.startX = shooter.x;
  s.ball.startY = shooter.y;
  s.ball.targetX = isHomeAttacking ? 99.5 : 0.5;
  s.ball.targetY = 50 + ((Math.random() * 16) - 8);
  s.ball.progress = 0;
  s.ball.curveZ = 5.5;

  const visualRoll = Math.random();
  s.ball.shotOutcome = visualRoll < 0.52 ? 'save' : visualRoll < 0.79 ? 'blocked' : visualRoll < 0.96 ? 'miss' : 'post';
  s.ball.isCorner = false;
  s.ball.isRebound = false;
  s.ball.liveDecisionCooldown = 180;
}

function updateLiveCanvasPositions(s){
  if(!s || !Array.isArray(s.homePlayers) || !Array.isArray(s.awayPlayers)) return;

  const isPlaying = s.playing && !s.done && s.phase !== 'HALF_TIME';
  const speed = Math.max(1, s.speed || 1);
  // Multiplicador de velocidade suave para animação 60 FPS fluida em qualquer velocidade (1x a 40x)
  const animSpeedMult = isPlaying ? Math.min(8.0, 1 + (speed - 1) * 0.28) : 1.0;
  const ball = s.ball || { x: 50, y: 50, z: 0, vx: 0, vy: 0, vz: 0, carrier: null, mode: 'play' };
  s.ball = ball;
  if(isPlaying && Number(ball.liveDecisionCooldown) > 0) {
    ball.liveDecisionCooldown = Math.max(0, ball.liveDecisionCooldown - animSpeedMult);
  }
  const allPlayers = [...s.homePlayers, ...s.awayPlayers];

  // 1. Trata o modo de chute (Shot Animation)
  if(ball.mode === 'shot'){
    const shotStep = (isPlaying ? 0.055 : 0.015) * animSpeedMult;
    ball.progress = (ball.progress || 0) + shotStep;
    const startX = ball.startX ?? 50;
    const startY = ball.startY ?? 50;
    const tgtX = ball.targetX ?? 50;
    const tgtY = ball.targetY ?? 50;
    const p = clamp(ball.progress, 0, 1);

    ball.x = startX + (tgtX - startX) * p;
    ball.y = startY + (tgtY - startY) * p;
    ball.z = Math.sin(p * Math.PI) * (ball.curveZ || 6);

    ball.trail = ball.trail || [];
    ball.trail.push({ x: ball.x, y: ball.y, z: ball.z, alpha: 1.0 });

    // Goleiro adversário mergulha na direção do chute
    const oppGk = (ball.shooter?.team === 'home' ? s.awayPlayers : s.homePlayers).find(x => x.isGK) || allPlayers[0];
    if(oppGk){
      oppGk.diveTimer = 1.8;
      oppGk.diving = true;
      oppGk.y += (tgtY - oppGk.y) * 0.18 * animSpeedMult;
      oppGk.animFrame = (oppGk.animFrame || 0) + 0.25 * animSpeedMult;
    }

    if(p >= 1){
      ball.mode = 'play';
      ball.progress = 0;
      ball.z = 0;
      ball.vx = 0;
      ball.vy = 0;

      if(ball.shotOutcome === 'gol'){
        if(ball.shooter) ball.shooter.celebrateTimer = 3.0;
        showLiveBalloon(ball.x, ball.y, '⚽ GOOOOL!', '#facc15');
        ball.x = 50;
        ball.y = 50;
        const otherSide = ball.shooter?.team === 'home' ? s.awayPlayers : s.homePlayers;
        ball.carrier = otherSide.find(x => !x.isGK && !x.redCard) || otherSide[0];
      } else if(ball.shotOutcome === 'save'){
        if(oppGk) oppGk.diveTimer = 2.0;
        if(ball.isCorner){
          showLiveBalloon(ball.x, ball.y, '🧤 DEFESASSA P/ ESCANTEIO!', '#38bdf8');
          ball.x = ball.shooter?.team === 'home' ? 99 : 1;
          ball.y = ball.y < 50 ? 5 : 95;
          const cornerTaker = (ball.shooter?.team === 'home' ? s.homePlayers : s.awayPlayers).find(x => !x.isGK) || allPlayers[0];
          ball.carrier = cornerTaker;
        } else if(ball.isRebound){
          showLiveBalloon(ball.x, ball.y, '🧤 ESPALMOU! REBOTE VIVO!', '#f97316');
          ball.mode = 'loose';
          ball.x = clamp(ball.x + (ball.shooter?.team === 'home' ? -12 : 12), 14, 86);
          ball.y = clamp(ball.y + ((ball.y > 50) ? -8 : 8), 20, 80);
          ball.carrier = null;
        } else {
          showLiveBalloon(ball.x, ball.y, '🧤 DEFESA SEGURA!', '#22c55e');
          ball.carrier = oppGk;
          ball.x = oppGk ? oppGk.x : 50;
          ball.y = oppGk ? oppGk.y : 50;
        }
      } else if(ball.shotOutcome === 'blocked'){
        showLiveBalloon(ball.x, ball.y, '🛡️ CHUTE TRAVADO NA ZAGA!', '#38bdf8');
        ball.mode = 'loose';
        ball.x = clamp(ball.x + (ball.shooter?.team === 'home' ? -6 : 6), 12, 88);
        ball.y = clamp(ball.y + ((ball.y > 50) ? 10 : -10), 10, 90);
        ball.carrier = null;
      } else if(ball.shotOutcome === 'post'){
        showLiveBalloon(ball.x, ball.y, '💥 NA TRAVE!', '#ef4444');
        ball.mode = 'loose';
        ball.x = clamp(ball.x + (ball.shooter?.team === 'home' ? -8 : 8), 12, 88);
        ball.y = clamp(ball.y + ((ball.y > 50) ? 6 : -6), 15, 85);
        ball.carrier = null;
      } else {
        showLiveBalloon(ball.x, ball.y, '⚡ TIRO DE META!', '#94a3b8');
        ball.carrier = oppGk;
        ball.x = oppGk ? oppGk.x : (ball.shooter?.team === 'home' ? 95 : 5);
        ball.y = oppGk ? oppGk.y : 50;
      }
    }
  } else if(ball.mode === 'pass'){
    // 1.1 Trata o modo de passe (Pass Animation)
    const passStep = (isPlaying ? 0.08 : 0.02) * animSpeedMult;
    ball.progress = (ball.progress || 0) + passStep;
    const startX = ball.startX ?? 50;
    const startY = ball.startY ?? 50;
    const tgt = ball.passTarget || { x: 50, y: 50 };
    const p = clamp(ball.progress, 0, 1);

    ball.x = startX + (tgt.x - startX) * p;
    ball.y = startY + (tgt.y - startY) * p;
    ball.z = Math.sin(p * Math.PI) * (ball.curveZ || 2.2);

    if(p >= 1){
      ball.mode = 'play';
      ball.progress = 0;
      ball.z = 0;
      ball.carrier = ball.passTarget || null;
      if(ball.carrier) ball.carrier.hasBall = true;
      ball.passTarget = null;
      ball.passer = null;
    }
  }

  if(window.AFM_REAL_FOOTBALL?.rules?.handleLiveMatchAction){
    window.AFM_REAL_FOOTBALL.rules.handleLiveMatchAction(s, isPlaying, showLiveBalloon, startLivePass, startLiveShot);
  } else if(isPlaying && ball.mode === 'play' && ball.carrier && !ball.carrier.isGK && !ball.carrier.redCard && Number(ball.liveDecisionCooldown || 0) <= 0){
    const carrierForPass = ball.carrier;
    const passTarget = selectLivePassTarget(carrierForPass.team === 'home' ? s.homePlayers : s.awayPlayers, carrierForPass, 1.5, 25);
    if(passTarget) {
      startLivePass(s, carrierForPass, passTarget, { cooldownFrames: 24 });
    } else {
      ball.liveDecisionCooldown = 24;
    }
  }

  // 2. Valida ou transfere portador da bola (carrier)
  let carrier = ball.carrier;
  if(carrier && carrier.redCard){
    carrier = null;
    ball.carrier = null;
  }

  // Se bola solta, jogador mais próximo domina
  if(!carrier && ball.mode !== 'shot' && ball.mode !== 'pass'){
    let minDist = 999;
    let nearest = null;
    allPlayers.forEach(p => {
      if(p.redCard) return;
      const d = Math.hypot(p.x - ball.x, p.y - ball.y);
      if(d < minDist){ minDist = d; nearest = p; }
    });
    if(nearest && minDist < 5.0){
      carrier = nearest;
      ball.carrier = nearest;
      ball.vx = 0; ball.vy = 0; ball.z = 0;
      ball.mode = 'play';
    } else if(nearest){
      // Jogador mais próximo corre até a bola
      const dx = ball.x - nearest.x;
      const dy = ball.y - nearest.y;
      const dist = Math.hypot(dx, dy) || 1;
      nearest.x += (dx / dist) * 0.45 * animSpeedMult;
      nearest.y += (dy / dist) * 0.45 * animSpeedMult;
      nearest.animFrame = (nearest.animFrame || 0) + 0.25 * animSpeedMult;
    }
  }

  // 3. Atualiza os 22 jogadores (executa de forma contínua em qualquer velocidade)
  allPlayers.forEach(p => {
    if(p.redCard) return;

    p.animFrame = (p.animFrame || 0) + (isPlaying ? 0.22 : 0.04) * animSpeedMult;
    if(p.celebrateTimer > 0) p.celebrateTimer -= 0.03 * animSpeedMult;
    p.celebrating = (p.celebrateTimer > 0);
    if(p.diveTimer > 0) p.diveTimer -= 0.03 * animSpeedMult;
    p.diving = (p.diveTimer > 0);

    const hasTheBall = (carrier === p && ball.mode === 'play');
    p.hasBall = hasTheBall;
    const isHome = (p.team === 'home');
    const teamHasBall = carrier ? (carrier.team === p.team) : (ball.isHomeAttacking === isHome);

    if(p.isControlledAthlete && Number.isFinite(Number(p.lockedCanonicalBaseX)) && Number.isFinite(Number(p.lockedCanonicalBaseY))){
      p.baseX = p.lockedCanonicalBaseX;
      p.baseY = p.lockedCanonicalBaseY;
    }

    let tX = Number.isFinite(Number(p.baseX)) ? Number(p.baseX) : (Number(p.x) || 50);
    let tY = Number.isFinite(Number(p.baseY)) ? Number(p.baseY) : (Number(p.y) || 50);

    if(hasTheBall){
      // Portador conduz a bola em direção ao gol adversário
      const paceSpeed = (0.55 + ((p.attrs?.pace || p.overall || 65) - 60) * 0.005) * animSpeedMult;
      if(isHome){
        tX = clamp(p.x + paceSpeed + (p.depthRuns ? 0.25 : 0), 4, 96);
      } else {
        tX = clamp(p.x - paceSpeed - (p.depthRuns ? 0.25 : 0), 4, 96);
      }
      tY = clamp(p.y + Math.sin(p.animFrame * 0.7) * 0.35, 14, 86);

      // Bola conduzida nos pés
      ball.x = p.x + (isHome ? 1.4 : -1.4);
      ball.y = p.y;
      ball.z = Math.abs(Math.sin(p.animFrame * 1.5)) * 0.3;
      ball.spin = (ball.spin || 0) + 0.25 * animSpeedMult;

    } else if(teamHasBall){
      // Time atacando: avança e ocupa espaços
      const ballProgress = isHome ? ball.x : 100 - ball.x;
      const advanceSize = clamp(8 + (ballProgress - 30) * 0.38, 6, 27);
      const advance = isHome ? advanceSize : -advanceSize;
      const depthBonus = (p.depthRuns || 0) * (isHome ? 0.12 : -0.12);
      const halfSpaceShift = p.halfSpaceOcc ? (p.baseY < 50 ? 5 : -5) : 0;

      if(!p.isGK){
        tX = clamp(p.baseX + advance + depthBonus, 5, 95);
        tY = clamp(p.baseY + halfSpaceShift, 12, 88);
      }
    } else {
      // Time defendendo: recua e compacta (atacante controlado permanece avançado como referência de contra-ataque, nunca caindo atrás dos volantes!)
      const isCtrlForward = Boolean(p.isControlledAthlete && (p.posGroup === 'ATA' || p.posGroup === 'PON' || ['ST', 'CF', 'LW', 'RW'].includes(p.pos)));
      const dropMag = isCtrlForward ? 2.5 : 7;
      const drop = isHome ? -dropMag : dropMag;
      const followBallY = (ball.y - p.baseY) * (isCtrlForward ? 0.15 : 0.25);

      if(!p.isGK){
        tX = clamp(p.baseX + drop, 10, 90);
        tY = clamp(p.baseY + followBallY, 14, 86);
      }

      // Pressão ativa no portador da bola
      if(carrier && (p.pressIntensity > 45 || p.attrs?.tackling > 70)){
        const dist = Math.hypot(p.x - carrier.x, p.y - carrier.y);
        if(dist < 22){
          tX += (carrier.x - p.x) * 0.35;
          tY += (carrier.y - p.y) * 0.35;
        }
      }
    }

    if(p.isGK){
      tY = clamp(35 + (ball.y * 0.3), 38, 62);
      tX = p.baseX + (isHome ? (ball.x * 0.05) : -((100 - ball.x) * 0.05));
    }

    p.targetX = tX;
    p.targetY = tY;

    // Suavização adaptativa calibrada para 60 FPS estável sem atraso do boneco
    const baseLerp = isPlaying ? 0.06 : 0.02;
    const lerpSpeed = Math.min(0.40, baseLerp * animSpeedMult);
    p.x += (p.targetX - p.x) * lerpSpeed;
    p.y += (p.targetY - p.y) * lerpSpeed;
  });

  // 4. Movimento de bola solta
  if(!carrier && ball.mode !== 'shot' && ball.mode !== 'pass'){
    ball.x += (ball.vx || 0) * animSpeedMult;
    ball.y += (ball.vy || 0) * animSpeedMult;
    ball.z = Math.max(0, (ball.z || 0) + (ball.vz || 0) * animSpeedMult);

    ball.vx = (ball.vx || 0) * 0.94;
    ball.vy = (ball.vy || 0) * 0.94;
    ball.vz = (ball.vz || 0) - 0.15 * animSpeedMult;
    ball.spin = (ball.spin || 0) + 0.1 * animSpeedMult;

    if(ball.z <= 0){
      ball.z = 0;
      if(Math.abs(ball.vz || 0) > 0.3) ball.vz = -(ball.vz || 0) * 0.4;
      else ball.vz = 0;
    }

    if(ball.x < 2 || ball.x > 98) ball.vx = -ball.vx * 0.6;
    if(ball.y < 6 || ball.y > 94) ball.vy = -ball.vy * 0.6;
    ball.x = clamp(ball.x, 2, 98);
    ball.y = clamp(ball.y, 6, 94);
  }

  // 5. Movimentação do árbitro
  if(s.referee){
    const ref = s.referee;
    ref.animFrame = (ref.animFrame || 0) + (isPlaying ? 0.16 : 0.03) * animSpeedMult;
    const tgtRefX = clamp((ball.x + 50) * 0.5, 28, 72);
    const tgtRefY = clamp((ball.y + 50) * 0.5 + 8, 22, 78);
    ref.x += (tgtRefX - ref.x) * (0.04 * animSpeedMult);
    ref.y += (tgtRefY - ref.y) * (0.04 * animSpeedMult);
  }
}

let liveCanvasAnimId = null;

let liveLoopGeneration = 0;

function tickLiveMatchFrame(s, dtMsOverride = null){
  if(!s) return;
  s.renderTicks = (s.renderTicks || 0) + 1;

  const stop1H = Number(s.stoppage1H) || 2;
  const stop2H = Number(s.stoppage2H) || 4;
  const maxAllowedMin = (s.phase === 'FIRST_HALF')
    ? (45 + stop1H)
    : (s.phase === 'EXTRA_TIME_1' ? 105 : (s.phase === 'EXTRA_TIME_2' ? 120 : (90 + stop2H)));
  const maxAllowedTimeSec = maxAllowedMin * 60;

  if(s.timeSec >= maxAllowedTimeSec && !s.done && s.phase !== 'HALF_TIME'){
    s.timeSec = maxAllowedTimeSec;
    s.minute = maxAllowedMin;
    s.playing = false;
    if(s.phase === 'FIRST_HALF'){
      s.halftimeTriggered = true;
      transitionMatchPhase('HALF_TIME');
      if(window.afmAudio) window.afmAudio.playSFX('whistle_halftime'); else playWhistleSound();
      s.events.unshift({ min: s.minute, type: 'whistle', text: `⏱ Fim do 1º tempo! ${s.home} ${s.hg} x ${s.ag} ${s.away}. As equipes descem para o vestiário.` });
      updateScoreDisplay();
      updateLiveSidebarEvents();
      renderLiveMatchModal();
      openHalftimeModal();
    } else {
      s.done = true;
      transitionMatchPhase('FULL_TIME');
      if(window.afmAudio) window.afmAudio.playSFX('whistle_end'); else playWhistleSound();
      s.events.unshift({ min: s.minute, type: 'whistle', text: `🏁 Fim de partida! ${s.home} ${s.hg} x ${s.ag} ${s.away}. O árbitro apita o final do jogo!` });
      updateScoreDisplay();
      updateLiveSidebarEvents();
      finishLiveMatch();
      renderLiveMatchModal();
    }
  }

  if(s.playing && !s.done && s.phase !== 'HALF_TIME'){
    const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    if(!s.lastLoopTime) s.lastLoopTime = now;
    const dtMs = dtMsOverride !== null ? Math.max(0, Math.min(Number(dtMsOverride) || 16.67, 250)) : Math.min(now - s.lastLoopTime, 250);
    s.lastLoopTime = now;

    const speed = Math.max(1, s.speed || 1);
    const msPerSec = Math.max(0.1, (1000 / 60) / speed);
    s.secAccumulator = (s.secAccumulator || 0) + dtMs;

    let clockSteps = 0;
    while(s.secAccumulator >= msPerSec && s.playing && !s.done && s.phase !== 'HALF_TIME' && clockSteps++ < 1200){
      if(s.timeSec >= maxAllowedTimeSec){
        s.timeSec = maxAllowedTimeSec;
        s.minute = maxAllowedMin;
        s.secAccumulator = 0;
        break;
      }

      s.secAccumulator -= msPerSec;
      s.liveSubSec = (s.liveSubSec || 0) + 1;
      s.timeSec = (s.timeSec || 0) + 1;

      if(s.liveSubSec >= 60){
        s.liveSubSec = 0;
        if(s.minute < maxAllowedMin){
          simulateMinute(s, s.minute + 1);
        }
      }
    }

    if(s.playing || s.done){
      const curMin = Math.min(maxAllowedMin, Math.floor((s.timeSec || 0) / 60));
      const curSec = Math.floor((s.timeSec || 0) % 60);
      const clk = $('#liveClockDisplay');
      if(clk){
        clk.textContent = `${String(curMin).padStart(2, '0')}:${String(curSec).padStart(2, '0')}`;
      }
    }
  } else {
    s.lastLoopTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  }
}
if(typeof window !== 'undefined') window.tickLiveMatchFrame = tickLiveMatchFrame;

function setupLiveCanvasLoop(){
  const myGen = ++liveLoopGeneration;
  if(liveCanvasAnimId) cancelAnimationFrame(liveCanvasAnimId);
  const canvas = $('#liveMatchCanvas');
  if(!canvas || typeof canvas.getContext !== 'function') return;
  const ctx = canvas.getContext('2d');
  if(!ctx) return;

  function loop(){
    if(myGen !== liveLoopGeneration) return;
    const s = liveMatchState;
    if(!s || !$('#liveMatchCanvas')){
      cancelAnimationFrame(liveCanvasAnimId);
      return;
    }

    try {
      tickLiveMatchFrame(s);
      if(myGen !== liveLoopGeneration) return;
      updateLiveCanvasPositions(s);
      drawLiveStadium(ctx, s);
    } catch(err){
      if(!window.__afmLiveRenderErrorLogged){
        window.__afmLiveRenderErrorLogged = true;
        recordAFMError('live-match-render', err);
      }
      console.warn('Live match render loop error:', err);
    }

    if(myGen === liveLoopGeneration){
      liveCanvasAnimId = requestAnimationFrame(loop);
    }
  }
  liveCanvasAnimId = requestAnimationFrame(loop);
}

// Projeção perspectiva 2.5D (px, py em porcentagem 0..100)
function proj(px, py){
  const t = clamp(py / 100, 0, 1);
  const screenY = 190 + t * 340;
  const leftX = 240 - t * 200;
  const rightX = 1040 + t * 200;
  const screenX = leftX + (px / 100) * (rightX - leftX);
  return { x: screenX, y: screenY };
}


function draw2DTacticalPitch(ctx, s){
  ctx.clearRect(0, 0, 1280, 720);

  // Fundo do radar tático
  ctx.fillStyle = '#080d1a';
  ctx.fillRect(0, 0, 1280, 720);

  // Retângulo do gramado 2D
  const x0 = 70, y0 = 40, pw = 1140, ph = 640;

  // Faixas do gramado
  const stripes = 14;
  for(let i=0; i<stripes; i++){
    ctx.fillStyle = (i % 2 === 0) ? '#164e2d' : '#1a5c35';
    ctx.fillRect(x0 + (i / stripes) * pw, y0, pw / stripes, ph);
  }

  // Linhas do campo em 2D
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2.5;
  ctx.strokeRect(x0, y0, pw, ph);

  // Linha de meio-campo
  ctx.beginPath();
  ctx.moveTo(x0 + pw / 2, y0);
  ctx.lineTo(x0 + pw / 2, y0 + ph);
  ctx.stroke();

  // Círculo central
  ctx.beginPath();
  ctx.arc(x0 + pw / 2, y0 + ph / 2, 70, 0, Math.PI * 2);
  ctx.stroke();

  // Ponto central
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(x0 + pw / 2, y0 + ph / 2, 4, 0, Math.PI * 2);
  ctx.fill();

  // Áreas Esquerda
  ctx.strokeRect(x0, y0 + ph * 0.22, pw * 0.165, ph * 0.56);
  ctx.strokeRect(x0, y0 + ph * 0.36, pw * 0.055, ph * 0.28);
  ctx.beginPath();
  ctx.arc(x0 + pw * 0.11, y0 + ph / 2, 3.5, 0, Math.PI * 2);
  ctx.fill();

  // Áreas Direita
  ctx.strokeRect(x0 + pw * 0.835, y0 + ph * 0.22, pw * 0.165, ph * 0.56);
  ctx.strokeRect(x0 + pw * 0.945, y0 + ph * 0.36, pw * 0.055, ph * 0.28);
  ctx.beginPath();
  ctx.arc(x0 + pw * 0.89, y0 + ph / 2, 3.5, 0, Math.PI * 2);
  ctx.fill();

  // Traves 2D
  ctx.fillStyle = '#f8fafc';
  ctx.fillRect(x0 - 10, y0 + ph * 0.44, 10, ph * 0.12);
  ctx.fillRect(x0 + pw, y0 + ph * 0.44, 10, ph * 0.12);

  // Jogadores em 2D (Discos Táticos)
  const homeKit = s.homeKit?.primary || '#2563eb';
  const awayKit = s.awayKit?.primary || '#dc2626';

  const allPlayers = [...(s.homePlayers || []), ...(s.awayPlayers || [])];
  allPlayers.forEach(p => {
    const px = x0 + (clamp(p.x, 0, 100) / 100) * pw;
    const py = y0 + (clamp(p.y, 0, 100) / 100) * ph;
    const isHome = p.team === 'home';
    const isCarrier = s.ball?.carrier === p;

    // Sombra
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.arc(px, py + 2, 12, 0, Math.PI * 2);
    ctx.fill();

    // Halo no condutor
    if(isCarrier){
      ctx.strokeStyle = '#facc15';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(px, py, 16, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Disco
    ctx.fillStyle = p.isGK ? '#f59e0b' : (isHome ? homeKit : awayKit);
    ctx.beginPath();
    ctx.arc(px, py, 11, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Número
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 8.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(p.num || String(p.name || '').slice(0, 3).toUpperCase(), px, py);

    // Etiqueta com nome
    ctx.fillStyle = 'rgba(15,23,42,0.85)';
    ctx.fillRect(px - 25, py + 14, 50, 12);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 7.5px Inter, sans-serif';
    ctx.fillText(String(p.name || '').slice(0, 8), px, py + 20);
  });

  // Árbitro 2D
  if(s.referee){
    const rx = x0 + (clamp(s.referee.x, 0, 100) / 100) * pw;
    const ry = y0 + (clamp(s.referee.y, 0, 100) / 100) * ph;
    ctx.fillStyle = '#facc15';
    ctx.beginPath();
    ctx.arc(rx, ry, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  // Bola 2D
  if(s.ball){
    const bx = x0 + (clamp(s.ball.x, 0, 100) / 100) * pw;
    const by = y0 + (clamp(s.ball.y, 0, 100) / 100) * ph;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(bx, by, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  // Badge 2D
  ctx.fillStyle = 'rgba(15,23,42,0.85)';
  ctx.fillRect(x0 + 10, y0 + 10, 130, 22);
  ctx.strokeStyle = 'rgba(56,189,248,0.4)';
  ctx.lineWidth = 1;
  ctx.strokeRect(x0 + 10, y0 + 10, 130, 22);
  ctx.fillStyle = '#38bdf8';
  ctx.font = 'bold 10px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('📐 RADAR TÁTICO 2D', x0 + 75, y0 + 21);
}

function drawLiveStadium(ctx, s){
  if(s.renderMode === '2d'){
    draw2DTacticalPitch(ctx, s);
    return;
  }

  ctx.clearRect(0, 0, 1280, 720);

  // Camera e estadio isolados para que uma falha de geometria nao deixe a tela preta.
  let cameraApplied = false;
  let stadiumRenderFailed = false;
  const renderer = window.AFM_REAL_FOOTBALL?.renderer;
  try {
    if(renderer?.applyTvBroadcastCamera){ renderer.applyTvBroadcastCamera(ctx, s, proj); cameraApplied = true; }
    if(renderer?.draw4SectorsStadium){ renderer.draw4SectorsStadium(ctx, s, proj); }
    else {
      const sky=ctx.createLinearGradient(0,0,0,220);sky.addColorStop(0,'#77b7ec');sky.addColorStop(1,'#d6e9fa');ctx.fillStyle=sky;ctx.fillRect(0,0,1280,220);
      ctx.fillStyle='#475569';ctx.fillRect(0,125,1280,90);ctx.fillStyle='#cbd5e1';for(let row=0;row<6;row++){const y=135+row*12,inset=row*23;ctx.fillRect(inset,y,1280-inset*2,8);}
    }
  } catch(stadiumRenderError) {
    stadiumRenderFailed = true;
    console.warn('Falha no desenho do estadio; mantendo a transmissao visivel:', stadiumRenderError);
  } finally {
    if(cameraApplied&&renderer?.restoreTvBroadcastCamera){try{renderer.restoreTvBroadcastCamera(ctx,s);}catch(restoreError){console.warn('Falha ao restaurar camera de TV:',restoreError);}}
    if(typeof ctx.setTransform==='function')ctx.setTransform(1,0,0,1,0,0);
  }
  if(stadiumRenderFailed){
    // Recria um cenario de transmissao util se um detalhe arquitetonico lancar excecao.
    ctx.fillStyle='#0b1522';ctx.fillRect(0,0,1280,720);
    const sky=ctx.createLinearGradient(0,0,0,210);sky.addColorStop(0,'#7db9ee');sky.addColorStop(1,'#e2effb');ctx.fillStyle=sky;ctx.fillRect(0,0,1280,205);
    ctx.fillStyle='#334155';ctx.fillRect(0,135,1280,75);ctx.fillStyle='#cbd5e1';for(let y=145;y<205;y+=10)ctx.fillRect(100,y,1080,4);
  }

  // 4. Gramado em Perspectiva (Trapezóide)
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(240, 190);
  ctx.lineTo(1040, 190);
  ctx.lineTo(1240, 530);
  ctx.lineTo(40, 530);
  ctx.closePath();
  ctx.clip();

  // Faixas do gramado: no estádio da carreira respeita a paleta salva no preview 3D.
  const isSynthetic = s.stadium.pitch === 'synthetic';
  const isHybrid = s.stadium.pitch === 'hybrid';
  const customStadium = s.stadium?.profile?.id === 'career-stadium';
  const grassBase = customStadium ? (s.stadium.customization?.grassColor || s.stadium.profile.grassColor || '#14532d') : '#14532d';
  const grassStripeA = customStadium ? (s.stadium.customization?.grassStripeA || '#15803d') : (isSynthetic ? '#229854' : isHybrid ? '#248645' : '#2d8c4e');
  const grassStripeB = customStadium ? (s.stadium.customization?.grassStripeB || '#16a34a') : (isSynthetic ? '#27a35c' : isHybrid ? '#2b984f' : '#359f5a');
  ctx.fillStyle = grassBase;
  ctx.fillRect(0, 190, 1280, 340);
  const stripes = 12;
  for(let i=0; i<stripes; i++){
    const x0 = (i / stripes) * 100;
    const x1 = ((i + 1) / stripes) * 100;
    const p0t = proj(x0, 0), p1t = proj(x1, 0);
    const p1b = proj(x1, 100), p0b = proj(x0, 100);

    ctx.beginPath();
    ctx.moveTo(p0t.x, p0t.y);
    ctx.lineTo(p1t.x, p1t.y);
    ctx.lineTo(p1b.x, p1b.y);
    ctx.lineTo(p0b.x, p0b.y);
    ctx.closePath();

    if(customStadium){
      ctx.fillStyle = (i % 2 === 0) ? grassStripeA : grassStripeB;
    } else if(isSynthetic){
      ctx.fillStyle = (i % 2 === 0) ? '#229854' : '#27a35c';
    } else if(isHybrid){
      ctx.fillStyle = (i % 2 === 0) ? '#248645' : '#2b984f';
    } else {
      ctx.fillStyle = (i % 2 === 0) ? '#2d8c4e' : '#359f5a';
    }
    ctx.fill();
  }

  // Textura sutil sintética se for grama sintética
  if(isSynthetic){
    ctx.strokeStyle = 'rgba(0,0,0,0.04)';
    ctx.lineWidth = 1;
    for(let sy=200; sy<530; sy+=12){
      ctx.beginPath(); ctx.moveTo(40, sy); ctx.lineTo(1240, sy); ctx.stroke();
    }
  }

  // 5. Marcações do Campo em Perspectiva
  ctx.strokeStyle = 'rgba(255,255,255,0.85)';
  ctx.lineWidth = 2.5;

  // Linhas Laterais e de Fundo
  const cTL = proj(0, 0), cTR = proj(100, 0), cBR = proj(100, 100), cBL = proj(0, 100);
  ctx.beginPath();
  ctx.moveTo(cTL.x, cTL.y);
  ctx.lineTo(cTR.x, cTR.y);
  ctx.lineTo(cBR.x, cBR.y);
  ctx.lineTo(cBL.x, cBL.y);
  ctx.closePath();
  ctx.stroke();

  // Linha do Meio de Campo
  const mTop = proj(50, 0), mBot = proj(50, 100);
  ctx.beginPath();
  ctx.moveTo(mTop.x, mTop.y);
  ctx.lineTo(mBot.x, mBot.y);
  ctx.stroke();

  // Círculo Central em Perspectiva (Elipse)
  const center = proj(50, 50);
  ctx.beginPath();
  ctx.ellipse(center.x, center.y, 65, 32, 0, 0, Math.PI * 2);
  ctx.stroke();

  // Ponto Central
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(center.x, center.y, 3, 0, Math.PI * 2);
  ctx.fill();

  // Área Grande Esquerda (Home)
  const gL_tl = proj(16.5, 22), gL_tr = proj(16.5, 78);
  const gL_bl = proj(0, 78), gL_br = proj(0, 22);
  ctx.beginPath();
  ctx.moveTo(gL_br.x, gL_br.y);
  ctx.lineTo(gL_tl.x, gL_tl.y);
  ctx.lineTo(gL_tr.x, gL_tr.y);
  ctx.lineTo(gL_bl.x, gL_bl.y);
  ctx.stroke();

  // Pequena Área Esquerda
  const sL_tl = proj(5.5, 36), sL_tr = proj(5.5, 64);
  const sL_bl = proj(0, 64), sL_br = proj(0, 36);
  ctx.beginPath();
  ctx.moveTo(sL_br.x, sL_br.y);
  ctx.lineTo(sL_tl.x, sL_tl.y);
  ctx.lineTo(sL_tr.x, sL_tr.y);
  ctx.lineTo(sL_bl.x, sL_bl.y);
  ctx.stroke();

  // Área Grande Direita (Away)
  const gR_tl = proj(83.5, 22), gR_tr = proj(83.5, 78);
  const gR_bl = proj(100, 78), gR_br = proj(100, 22);
  ctx.beginPath();
  ctx.moveTo(gR_br.x, gR_br.y);
  ctx.lineTo(gR_tl.x, gR_tl.y);
  ctx.lineTo(gR_tr.x, gR_tr.y);
  ctx.lineTo(gR_bl.x, gR_bl.y);
  ctx.stroke();

  // Pequena Área Direita
  const sR_tl = proj(94.5, 36), sR_tr = proj(94.5, 64);
  const sR_bl = proj(100, 64), sR_br = proj(100, 36);
  ctx.beginPath();
  ctx.moveTo(sR_br.x, sR_br.y);
  ctx.lineTo(sR_tl.x, sR_tl.y);
  ctx.lineTo(sR_tr.x, sR_tr.y);
  ctx.lineTo(sR_bl.x, sR_bl.y);
  ctx.stroke();

  // Bandeirinhas de Escanteio nos 4 cantos
  [cTL, cTR, cBR, cBL].forEach((pt, idx) => {
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(pt.x, pt.y);
    ctx.lineTo(pt.x, pt.y - 14);
    ctx.stroke();

    ctx.fillStyle = idx % 2 === 0 ? '#ef4444' : '#fbbf24';
    ctx.beginPath();
    ctx.moveTo(pt.x, pt.y - 14);
    ctx.lineTo(pt.x + 8, pt.y - 10);
    ctx.lineTo(pt.x, pt.y - 6);
    ctx.closePath();
    ctx.fill();
  });

  ctx.restore();

  // Borda de Anel de LED ao redor do campo se comprado
  if(s.stadium.upgrades?.ledRing){
    ctx.strokeStyle = 'rgba(168,85,247,0.7)';
    ctx.lineWidth = 3;
    ctx.strokeRect(36, 186, 1208, 348);
  }

  // 6. Traves e Redes em 3D Realistas
  if(window.AFM_REAL_FOOTBALL?.renderer?.drawRealistic3DGoals){
    window.AFM_REAL_FOOTBALL.renderer.drawRealistic3DGoals(ctx, proj);
  } else {
    // Gol Esquerdo
    const gL_top = proj(0, 42), gL_bot = proj(0, 58);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 3.5;
    ctx.beginPath();
    ctx.moveTo(gL_top.x, gL_top.y);
    ctx.lineTo(gL_top.x - 22, gL_top.y - 18);
    ctx.lineTo(gL_bot.x - 22, gL_bot.y - 18);
    ctx.lineTo(gL_bot.x, gL_bot.y);
    ctx.stroke();
    // Rede esquerda
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.beginPath();
    ctx.moveTo(gL_top.x, gL_top.y);
    ctx.lineTo(gL_top.x - 22, gL_top.y - 18);
    ctx.lineTo(gL_bot.x - 22, gL_bot.y - 18);
    ctx.lineTo(gL_bot.x, gL_bot.y);
    ctx.closePath();
    ctx.fill();

    // Gol Direito
    const gR_top = proj(100, 42), gR_bot = proj(100, 58);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 3.5;
    ctx.beginPath();
    ctx.moveTo(gR_top.x, gR_top.y);
    ctx.lineTo(gR_top.x + 22, gR_top.y - 18);
    ctx.lineTo(gR_bot.x + 22, gR_bot.y - 18);
    ctx.lineTo(gR_bot.x, gR_bot.y);
    ctx.stroke();
    // Rede direita
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.beginPath();
    ctx.moveTo(gR_top.x, gR_top.y);
    ctx.lineTo(gR_top.x + 22, gR_top.y - 18);
    ctx.lineTo(gR_bot.x + 22, gR_bot.y - 18);
    ctx.lineTo(gR_bot.x, gR_bot.y);
    ctx.closePath();
    ctx.fill();
  }

  // 7. Bancos de Reservas e Cabine do VAR Física na Linha Inferior
  drawDugouts(ctx, s);
  if(window.AFM_REAL_FOOTBALL?.renderer?.drawPitchsideVarBooth){
    window.AFM_REAL_FOOTBALL.renderer.drawPitchsideVarBooth(ctx, proj, s);
  }

  // Bandeirinhas (Linesmen) nas laterais do campo
  if(s.linesmen && window.AFM_REAL_FOOTBALL?.renderer?.drawRealisticLinesman){
    s.linesmen.forEach(lm => window.AFM_REAL_FOOTBALL.renderer.drawRealisticLinesman(ctx, lm, proj));
  }

  // Linha Virtual de Impedimento 3D Calibrada
  if(window.AFM_REAL_FOOTBALL?.renderer?.draw3DOffsideLine){
    window.AFM_REAL_FOOTBALL.renderer.draw3DOffsideLine(ctx, s, proj);
  }

  // 8. Desenha Todos os Jogadores e Árbitro Ordenados por Y (profundidade)
  const pitchEntities = [...s.homePlayers, ...s.awayPlayers];
  if(s.referee) pitchEntities.push(s.referee);
  pitchEntities.sort((a, b) => a.y - b.y);

  pitchEntities.forEach(ent => {
    if(ent.type === 'REFEREE'){
      drawRefereeSprite(ctx, ent);
    } else {
      drawPlayerSprite(ctx, ent, s.ball?.carrier === ent);
    }
  });

  // 9. Desenha a Bola de Futebol
  drawBall(ctx, s.ball);

  // 10. Efeitos de Sinalizadores e Fumaça se comprados
  if(s.stadium.upgrades?.flares && s.particles.length){
    s.particles.forEach((pt, idx) => {
      ctx.fillStyle = pt.color;
      ctx.beginPath();
      ctx.arc(pt.x, pt.y, pt.size, 0, Math.PI * 2);
      ctx.fill();
      pt.y -= pt.vy;
      pt.size += 0.15;
      pt.alpha -= 0.02;
    });
    s.particles = s.particles.filter(pt => pt.alpha > 0);
  }

  // 11. Restaura Transformação da Câmera TV antes de desenhar HUD Fixo na Tela
  if(window.AFM_REAL_FOOTBALL?.renderer?.restoreTvBroadcastCamera){
    window.AFM_REAL_FOOTBALL.renderer.restoreTvBroadcastCamera(ctx, s);
  }

  // 12. Desenha Balões de HQ / Expressões de Gol
  drawLiveBalloons(ctx, s);

  // 13. Desenha Overlay do VAR de Transmissão se ativo
  if(window.AFM_REAL_FOOTBALL?.renderer?.drawBroadcastVarOverlay){
    window.AFM_REAL_FOOTBALL.renderer.drawBroadcastVarOverlay(ctx, s);
  } else if(s.varCheck){
    drawVarOverlay(ctx, s);
  }

  // 14. Iluminação de Holofotes Noturnos se jogo à noite
  if(s.isNight) drawFloodlights(ctx, s);
}

function drawLiveBalloons(ctx, s){
  if(!s.balloons || !s.balloons.length) return;
  s.balloons.forEach(b => {
    const pt = proj(b.x, b.y);
    const rise = (1 - (b.life / b.maxLife)) * 35;
    const alpha = clamp(b.life / (b.maxLife * 0.4), 0, 1);

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(pt.x, pt.y - 30 - rise);

    ctx.font = '900 13px Inter, sans-serif';
    const textWidth = ctx.measureText(b.text).width;
    const bw = textWidth + 24;
    const bh = 28;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.92)';
    ctx.strokeStyle = b.color || '#fbbf24';
    ctx.lineWidth = 2.5;
    ctx.shadowColor = b.color || '#fbbf24';
    ctx.shadowBlur = 10;

    ctx.beginPath();
    ctx.roundRect(-bw/2, -bh/2, bw, bh, 8);
    ctx.fill();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(-4, bh/2);
    ctx.lineTo(0, bh/2 + 6);
    ctx.lineTo(4, bh/2);
    ctx.closePath();
    ctx.fillStyle = b.color || '#fbbf24';
    ctx.fill();

    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(b.text, 0, 0);

    ctx.restore();

    b.life -= 0.04;
  });
  s.balloons = s.balloons.filter(b => b.life > 0);
}

function drawVarOverlay(ctx, s){
  const v = s.varCheck;
  if(!v) return;

  const p1 = proj(35, 10), p2 = proj(35, 90);
  const p3 = proj(37, 10), p4 = proj(37, 90);

  ctx.save();
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#3b82f6';
  ctx.setLineDash([8, 6]);
  ctx.beginPath();
  ctx.moveTo(p1.x, p1.y);
  ctx.lineTo(p2.x, p2.y);
  ctx.stroke();

  ctx.strokeStyle = '#ef4444';
  ctx.beginPath();
  ctx.moveTo(p3.x, p3.y);
  ctx.lineTo(p4.x, p4.y);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = 'rgba(5, 8, 22, 0.92)';
  ctx.strokeStyle = '#38bdf8';
  ctx.lineWidth = 2;
  ctx.shadowColor = '#0284c7';
  ctx.shadowBlur = 18;
  ctx.fillRect(440, 20, 400, 50);
  ctx.strokeRect(440, 20, 400, 50);

  ctx.shadowBlur = 0;
  ctx.fillStyle = '#38bdf8';
  ctx.font = '900 13px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(v.text || '🖥️ VAR - CHECANDO LANCE NO MONITOR...', 640, 42);

  const pr = clamp(1 - (v.timer / 2.4), 0, 1);
  ctx.fillStyle = '#10b981';
  ctx.fillRect(450, 58, 380 * pr, 4);

  ctx.restore();
}

function drawFloodlights(ctx, s){
  ctx.save();
  const lights = [
    { x: 180, y: 70, targetX: 520, targetY: 360 },
    { x: 1100, y: 70, targetX: 760, targetY: 360 }
  ];

  lights.forEach(l => {
    const grad = ctx.createRadialGradient(l.targetX, l.targetY, 40, l.targetX, l.targetY, 450);
    grad.addColorStop(0, 'rgba(255, 255, 255, 0.08)');
    grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 1280, 720);
  });
  ctx.restore();
}

// Desenha os Bancos de Reservas com reservas e técnicos
// Desenha os Bancos de Reservas com reservas e técnicos (Estrutura 3D Acrílica Realista BRFC27)
function drawDugouts(ctx, s){
  const by = 538;
  const hKitColor = s.homeKit?.primary || '#f59e0b';
  const aKitColor = s.awayKit?.primary || '#15803d';
  const ticks = s.renderTicks || 0;

  // Função auxiliar para desenhar um abrigo 3D completo com acrílico curvo, 7 reservas e área técnica
  function renderBench(x0, w, h, kitColor, isHome, coachName){
    // 1. Área Técnica demarcada no gramado com linhas tracejadas
    ctx.save();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.45)';
    ctx.lineWidth = 1.2;
    ctx.setLineDash([5, 4]);
    const techBoxX = isHome ? (x0 + w - 10) : (x0 - 50);
    ctx.strokeRect(techBoxX, by - 16, 60, 24);
    ctx.setLineDash([]);
    ctx.restore();

    // 2. Plataforma e Base do Banco de Reservas (Concreto e Aço)
    ctx.fillStyle = '#0f172a';
    ctx.beginPath();
    ctx.roundRect(x0, by + 4, w, 28, [4, 4, 6, 6]);
    ctx.fill();
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Faixa com a cor do clube na base
    ctx.fillStyle = kitColor;
    ctx.fillRect(x0 + 4, by + 30, w - 8, 2);

    // 3. Parede de Fundo do Abrigo
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(x0 + 2, by - 14, w - 4, 20);

    // 4. 7 Assentos Tipo Concha e Atletas Reservas Sentados
    const seatW = (w - 16) / 7;
    for(let i = 0; i < 7; i++){
      const sx = x0 + 8 + i * seatW;

      // Encosto do assento esportivo
      ctx.fillStyle = '#090d16';
      ctx.beginPath();
      ctx.roundRect(sx, by - 10, seatW - 3, 16, [4, 4, 1, 1]);
      ctx.fill();

      // Centro do assento com a cor do clube
      ctx.fillStyle = kitColor;
      ctx.fillRect(sx + 2, by - 8, seatW - 7, 12);

      // Silhueta do jogador reserva sentado
      ctx.fillStyle = kitColor;
      ctx.beginPath();
      ctx.roundRect(sx + 3, by - 6, seatW - 9, 13, [3, 3, 0, 0]);
      ctx.fill();

      // Cabeça com tom de pele variado
      const skinTones = ['#fed7aa', '#fcd34d', '#d97706', '#92400e', '#78350f'];
      ctx.fillStyle = skinTones[(i * 3 + (isHome ? 1 : 2)) % skinTones.length];
      ctx.beginPath();
      ctx.arc(sx + (seatW - 3) / 2, by - 11, 3.2, 0, Math.PI * 2);
      ctx.fill();

      // Cabelo
      ctx.fillStyle = (i % 2 === 0) ? '#111827' : '#451a03';
      ctx.beginPath();
      ctx.arc(sx + (seatW - 3) / 2, by - 12.5, 3.2, Math.PI, Math.PI * 2);
      ctx.fill();
    }

    // 5. Cobertura Curva de Acrílico Translúcido (Glass Acrylic Canopy)
    ctx.save();
    const canopyGrad = ctx.createLinearGradient(x0, by - 24, x0, by + 10);
    canopyGrad.addColorStop(0, 'rgba(207, 227, 242, 0.42)');
    canopyGrad.addColorStop(0.5, 'rgba(186, 230, 253, 0.22)');
    canopyGrad.addColorStop(1, 'rgba(207, 227, 242, 0.08)');
    ctx.fillStyle = canopyGrad;

    ctx.beginPath();
    ctx.moveTo(x0, by + 12);
    ctx.quadraticCurveTo(x0, by - 24, x0 + 18, by - 24);
    ctx.lineTo(x0 + w - 18, by - 24);
    ctx.quadraticCurveTo(x0 + w, by - 24, x0 + w, by + 12);
    ctx.closePath();
    ctx.fill();

    // Tubulação de aço metálico da cobertura (arco estrutural)
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1.8;
    ctx.stroke();

    // Nervuras metálicas intermediárias
    ctx.strokeStyle = 'rgba(226, 232, 240, 0.5)';
    ctx.lineWidth = 1;
    for(let r = 1; r <= 3; r++){
      const rx = x0 + (r / 4) * w;
      ctx.beginPath();
      ctx.moveTo(rx, by + 10);
      ctx.lineTo(rx, by - 24);
      ctx.stroke();
    }

    // Brilho especular (reflexo de vidro / luz diagonal)
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    ctx.beginPath();
    ctx.moveTo(x0 + 14, by - 22);
    ctx.lineTo(x0 + 36, by - 22);
    ctx.lineTo(x0 + 20, by + 6);
    ctx.lineTo(x0 + 6, by + 6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // 6. Treinador em pé na Área Técnica
    const coachWave = Math.sin(ticks * 0.08 + (isHome ? 0 : 2)) * 2;
    const coachX = isHome ? (x0 + w + 16) : (x0 - 24);
    const coachY = by - 8 + coachWave;

    // Sombra do técnico no gramado
    ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
    ctx.beginPath();
    ctx.ellipse(coachX + 4.5, by + 8, 7, 3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Corpo / Terno do Treinador
    ctx.fillStyle = isHome ? '#0284c7' : '#dc2626';
    ctx.beginPath();
    ctx.roundRect(coachX, coachY, 9, 16, [2, 2, 0, 0]);
    ctx.fill();

    // Braço gesticulando
    ctx.strokeStyle = isHome ? '#0284c7' : '#dc2626';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(coachX + (isHome ? 9 : 0), coachY + 4);
    ctx.lineTo(coachX + (isHome ? 15 : -6), coachY + 8 + coachWave);
    ctx.stroke();

    // Cabeça do técnico
    ctx.fillStyle = '#fed7aa';
    ctx.beginPath();
    ctx.arc(coachX + 4.5, coachY - 4, 3.8, 0, Math.PI * 2);
    ctx.fill();

    // Cabelo do técnico
    ctx.fillStyle = '#334155';
    ctx.beginPath();
    ctx.arc(coachX + 4.5, coachY - 5.5, 3.8, Math.PI, Math.PI * 2);
    ctx.fill();

    // Plaquinha elegante com nome do treinador
    ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
    ctx.beginPath();
    ctx.roundRect(coachX - 24, by + 12, 58, 12, 3);
    ctx.fill();
    ctx.strokeStyle = kitColor;
    ctx.lineWidth = 0.8;
    ctx.stroke();

    ctx.fillStyle = '#f8fafc';
    ctx.font = 'bold 7.5px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(coachName, coachX + 5, by + 18);
  }

  // 1. Banco Mandante (Home - Esquerda)
  const managerName = typeof state !== 'undefined' && state.gameMode === 'player' ? (state.coachName || 'Treinador da IA') : state?.manager;
  const homeManager = managerName ? `TÉC. ${managerName.split(' ')[0].toUpperCase()}` : `TÉC. ${(s.home || 'CASA').slice(0, 4).toUpperCase()}`;
  renderBench(240, 195, 32, hKitColor, true, homeManager);

  // 2. Banco Visitante (Away - Direita)
  const awayManager = `TÉC. ${(s.away || 'VISITANTE').slice(0, 6).toUpperCase()}`;
  renderBench(845, 195, 32, aKitColor, false, awayManager);
}

function drawPlayerSprite(ctx, p, hasBall){
  if(p.redCard) return; // Jogador expulso não aparece no campo!
  const pt = proj(p.x, p.y);
  const scale = 0.8 + (p.y / 100) * 0.45; // Jogadores na parte inferior são maiores

  if(p.isControlledAthlete){
    ctx.save();
    ctx.strokeStyle = '#facc15';
    ctx.fillStyle = '#facc15';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.ellipse(pt.x, pt.y + 3, 12 * scale, 5 * scale, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(pt.x, pt.y - 40 * scale);
    ctx.lineTo(pt.x - 6 * scale, pt.y - 49 * scale);
    ctx.lineTo(pt.x + 6 * scale, pt.y - 49 * scale);
    ctx.closePath();
    ctx.fill();
    ctx.font = 'bold 8px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = '#000';
    ctx.shadowBlur = 4;
    ctx.fillText('VOCÊ', pt.x, pt.y - 53 * scale);
    ctx.restore();
  }

  if(window.AFM_REAL_FOOTBALL?.renderer?.drawRealistic3DPlayer){
    window.AFM_REAL_FOOTBALL.renderer.drawRealistic3DPlayer(ctx, p, hasBall, proj, scale);
    return;
  }

  ctx.save();
  ctx.translate(pt.x, pt.y);

  // Se o goleiro estiver mergulhando para espalmar:
  if(p.diving){
    const angle = (p.diveDir || 1) * Math.PI * 0.28;
    ctx.rotate(angle);
  }

  // Sombra sob os pés (escala com a altura se estiver mergulhando ou saltando)
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 8 * scale, 3.5 * scale, 0, 0, Math.PI * 2);
  ctx.fill();

  // Indicador amarelo/ouro para o jogador com a posse de bola
  if(hasBall){
    ctx.strokeStyle = '#facc15';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.ellipse(0, 0, 14 * scale, 6 * scale, 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Se estiver comemorando gol:
  if(p.celebrating){
    // Estrela/brilho no topo
    ctx.fillStyle = '#facc15';
    ctx.beginPath();
    ctx.arc(0, -38 * scale, 3 * scale, 0, Math.PI * 2);
    ctx.fill();
  }

  // Pés / Chuteiras (animadas conforme a corrida ou chute)
  const isKicking = (p.kickTimer || 0) > 0;
  const legOffset = isKicking ? (8 * scale) : Math.sin(p.animFrame || 0) * (4 * scale);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(-4 * scale, -4 * scale + legOffset, 3 * scale, 5 * scale);
  ctx.fillRect(1 * scale, -4 * scale - legOffset, 3 * scale, 5 * scale);

  // Shorts
  ctx.fillStyle = p.isGK ? '#15803d' : (p.team === 'home' ? '#ffffff' : '#0f172a');
  ctx.fillRect(-5 * scale, -11 * scale, 10 * scale, 7 * scale);

  // Tronco / Camisa
  if(p.isGK){
    ctx.fillStyle = '#22c55e'; // Goleiro com uniforme verde limão neon
  } else if(p.team === 'home'){
    ctx.fillStyle = '#1e3a8a'; // Mandante azul marinho
  } else {
    ctx.fillStyle = '#dc2626'; // Visitante vermelho
  }
  ctx.fillRect(-6 * scale, -21 * scale, 12 * scale, 10 * scale);

  // Braçadeira de Capitão Amarela 'C'
  if(p.isCaptain){
    ctx.fillStyle = '#facc15';
    ctx.fillRect(-8 * scale, -18 * scale, 3.2 * scale, 4.5 * scale);
  }

  // Braços / Luvas (levantados em comemoração \o/ ou posicionados de goleiro)
  ctx.fillStyle = p.isGK ? '#facc15' : '#fed7aa';
  if(p.celebrating){
    // Braços erguidos para cima!
    ctx.fillRect(-9 * scale, -30 * scale, 3 * scale, 11 * scale);
    ctx.fillRect(6 * scale, -30 * scale, 3 * scale, 11 * scale);
  } else if(p.diving){
    // Braços esticados para frente/lado do mergulho
    ctx.fillRect(-12 * scale, -22 * scale, 6 * scale, 4 * scale);
    ctx.fillRect(6 * scale, -22 * scale, 6 * scale, 4 * scale);
  } else {
    ctx.fillRect(-8 * scale, -19 * scale - legOffset * 0.5, 3 * scale, 7 * scale);
    ctx.fillRect(5 * scale, -19 * scale + legOffset * 0.5, 3 * scale, 7 * scale);
  }

  // Cabeça e Cabelo
  ctx.fillStyle = '#fed7aa'; // Pele
  ctx.beginPath();
  ctx.arc(0, -25 * scale, 5 * scale, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = (hashStr(p.name) % 3 === 0) ? '#172554' : (hashStr(p.name) % 2 === 0) ? '#451a03' : '#713f12';
  ctx.beginPath();
  ctx.arc(0, -27 * scale, 5 * scale, Math.PI, Math.PI * 2);
  ctx.fill();

  // Nome do jogador abaixo dele
  ctx.fillStyle = '#ffffff';
  ctx.font = `bold ${Math.round(8 * scale)}px Inter, sans-serif`;
  ctx.textAlign = 'center';
  ctx.shadowColor = '#000000';
  ctx.shadowBlur = 4;
  ctx.fillText(p.name, 0, 11 * scale);
  ctx.shadowBlur = 0;

  ctx.restore();
}

// Desenha o sprite do árbitro no gramado com uniforme e movimentação distinta
function drawRefereeSprite(ctx, ref){
  if(!ref) return;
  const pt = proj(ref.x, ref.y);
  const scale = 0.8 + (ref.y / 100) * 0.45;
  ctx.save();
  ctx.translate(pt.x, pt.y);

  // Sombra
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 7 * scale, 3 * scale, 0, 0, Math.PI * 2);
  ctx.fill();

  // Pernas
  const legOffset = Math.sin(ref.animFrame || 0) * (3 * scale);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(-3 * scale, -4 * scale + legOffset, 2.5 * scale, 5 * scale);
  ctx.fillRect(1 * scale, -4 * scale - legOffset, 2.5 * scale, 5 * scale);

  // Shorts
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(-4.5 * scale, -10 * scale, 9 * scale, 6 * scale);

  // Camisa de Árbitro (Amarelo Neon fluorescente #eab308)
  ctx.fillStyle = '#eab308';
  ctx.fillRect(-5 * scale, -20 * scale, 10 * scale, 10 * scale);

  // Gola preta
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(-2 * scale, -20 * scale, 4 * scale, 2.5 * scale);

  // Braços
  ctx.fillStyle = '#fed7aa';
  ctx.fillRect(-7 * scale, -18 * scale, 2.5 * scale, 7 * scale);
  ctx.fillRect(4.5 * scale, -18 * scale, 2.5 * scale, 7 * scale);

  // Cabeça
  ctx.fillStyle = '#fed7aa';
  ctx.beginPath();
  ctx.arc(0, -25 * scale, 4.5 * scale, 0, Math.PI * 2);
  ctx.fill();

  // Cabelo preto
  ctx.fillStyle = '#1e293b';
  ctx.beginPath();
  ctx.arc(0, -26.5 * scale, 4.5 * scale, Math.PI, Math.PI * 2);
  ctx.fill();

  // Nome "Árbitro"
  ctx.fillStyle = '#fef08a';
  ctx.font = `bold ${Math.round(7.5 * scale)}px Inter, sans-serif`;
  ctx.textAlign = 'center';
  ctx.shadowColor = '#000000';
  ctx.shadowBlur = 4;
  ctx.fillText('Árbitro', 0, 11 * scale);
  ctx.shadowBlur = 0;

  ctx.restore();
}

// Desenha a Bola com sombra 3D, rotação e rastro de chute
function drawBall(ctx, b){
  if(!b) return;
  if(window.AFM_REAL_FOOTBALL?.renderer?.drawRealistic3DBall){
    window.AFM_REAL_FOOTBALL.renderer.drawRealistic3DBall(ctx, b, proj);
    return;
  }
  const pt = proj(b.x, b.y);
  const ballAlt = (b.z || 0);
  const ballY = pt.y - ballAlt * 2.2;

  // 1. Rastro de movimento do chute
  if(b.trail && b.trail.length){
    b.trail.forEach(t => {
      const tPt = proj(t.x, t.y);
      const tY = tPt.y - (t.z || 0) * 2.2;
      ctx.fillStyle = `rgba(250, 204, 21, ${t.alpha * 0.5})`;
      ctx.beginPath();
      ctx.arc(tPt.x, tY - 4, 3 * (t.alpha || 1), 0, Math.PI * 2);
      ctx.fill();
      t.alpha -= 0.08;
    });
    b.trail = b.trail.filter(t => t.alpha > 0);
  }

  // 2. Sombra 3D da bola no gramado (fica menor e mais suave quando a bola sobe)
  const shadowScale = clamp(1 - ballAlt / 20, 0.35, 1.0);
  const shadowAlpha = clamp(0.4 - ballAlt / 35, 0.12, 0.45);
  ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
  ctx.beginPath();
  ctx.ellipse(pt.x, pt.y, 4.5 * shadowScale, 2.4 * shadowScale, 0, 0, Math.PI * 2);
  ctx.fill();

  // 3. Bola de Futebol com gomos e rotação
  ctx.save();
  ctx.translate(pt.x, ballY - 4);
  ctx.rotate(b.spin || 0);

  // Corpo da bola branca
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(0, 0, 4.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#0f172a';
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // Detalhe pentágono no centro da bola (estilo clássico Telstar)
  ctx.fillStyle = '#0f172a';
  ctx.beginPath();
  ctx.arc(0, 0, 1.6, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

function generateGoalNarration(shooter, teamName, isHome){
  const ovr = shooter?.overall || 65;
  const name = shooter?.name || 'Atacante';

  // Jogadores com Overall 80+ têm chance de gol antológico de bicicleta ou voleio
  if(ovr >= 80 && Math.random() < 0.45){
    const specials = [
      `🚲 GOLAÇO ANTOLÓGICO DE BICICLETA! ${name} acerta uma bicicleta perfeita no ângulo indefensável! Pintura histórica do ${teamName}!`,
      `🎯 OBRA DE ARTE DE TRIVELA! ${name} chapa de três dedos na gaveta! Curva espetacular estufando as redes para o ${teamName}!`,
      `🚀 VOLEIO CINEMATOGRÁFICO! ${name} pega de primeira na veia, a bola explode no travessão e entra! Golaço do ${teamName}!`
    ];
    return specials[Math.floor(Math.random() * specials.length)];
  }

  // Jogadores com Overall 74+ têm chance de trivela ou chutaço no ângulo
  if(ovr >= 74 && Math.random() < 0.50){
    const highMoves = [
      `🎯 GOL DE TRIVELA! ${name} bate com curva venenosa de fora da área e encontra o cantinho para o ${teamName}!`,
      `💥 BOMBAÇA NO ÂNGULO! ${name} solta um míssil teleguiado de média distância! O goleiro nem pulou! Gol do ${teamName}!`,
      `⚡ DRIBLE DESCONCERTANTE E GOL! ${name} entorta o zagueiro com ginga brasileira e toca com categoria para o ${teamName}!`
    ];
    return highMoves[Math.floor(Math.random() * highMoves.length)];
  }

  const standard = [
    `⚽ GOL DO ${teamName}! ${name} recebe passe açucarado e bate cruzado firme no cantinho!`,
    `⚽ TESTAÇO CERTEIRO! ${name} sobe no terceiro andar após cruzamento e estufa o barbante para o ${teamName}!`,
    `⚽ É REDE! ${name} aproveita sobra de bola na grande área e fuzila sem chances de defesa para o ${teamName}!`
  ];
  return standard[Math.floor(Math.random() * standard.length)];
}

function getPostureConfig(posture){
  switch(posture){
    case 'Retranca':
      return { lineOffset: -16, pressSpeed: 0.05, shotFreq: 0.022, tackleBonus: 0.18, stamBurn: 0.75, speedMult: 0.85 };
    case 'Defensiva':
      return { lineOffset: -9, pressSpeed: 0.07, shotFreq: 0.032, tackleBonus: 0.10, stamBurn: 0.88, speedMult: 0.92 };
    case 'Ofensiva':
      return { lineOffset: +13, pressSpeed: 0.11, shotFreq: 0.065, tackleBonus: 0.00, stamBurn: 1.25, speedMult: 1.15 };
    case 'Pressão total':
      return { lineOffset: +23, pressSpeed: 0.16, shotFreq: 0.090, tackleBonus: 0.22, stamBurn: 1.70, speedMult: 1.30 };
    default: // Equilibrada
      return { lineOffset: 0, pressSpeed: 0.08, shotFreq: 0.045, tackleBonus: 0.00, stamBurn: 1.0, speedMult: 1.0 };
  }
}

// =========================================================================
// MATCH ENGINE DESACOPLADO E DETERMINÍSTICO (Mulberry32 PRNG & Phase Engine)
// =========================================================================

function createMatchPRNG(seed){
  let s = (Number(seed) >>> 0) || 123456789;
  return function(){
    s = (s + 0x6D2B79F5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function evaluateAiCoachAdjustments(s, min){
  if(!s || s.done) return;
  // Ajustes da IA adversária e do auxiliar aos 60', 75' e 82'
  const isUserHome = (norm(s.home) === norm(state.club));
  const cpuTeam = isUserHome ? s.away : s.home;
  const cpuPlayers = isUserHome ? s.awayPlayers : s.homePlayers;
  const userScore = isUserHome ? s.hg : s.ag;
  const cpuScore = isUserHome ? s.ag : s.hg;
  const diff = cpuScore - userScore;

  // 1. Substituição por cansaço da IA (60' a 75')
  if(min >= 60 && min <= 75 && (min % 5 === 0)){
    const tiredPlayer = cpuPlayers.find(p => !p.isGK && !p.redCard && (p.stamina || 100) < 58 && !p.isSubbed);
    if(tiredPlayer && (!s.cpuSubsCount || s.cpuSubsCount < 5)){
      s.cpuSubsCount = (s.cpuSubsCount || 0) + 1;
      tiredPlayer.isSubbed = true;

      let subName = '';
      // Busca reservas autênticos do próprio clube em LIVE_PLAYERS
      if(typeof window !== 'undefined' && Array.isArray(window.LIVE_PLAYERS)){
        const benchLive = window.LIVE_PLAYERS.filter(lp =>
          norm(lp.club) === norm(cpuTeam) &&
          !cpuPlayers.some(cp => norm(cp.name) === norm(lp.name)) &&
          lp.pos !== 'GK'
        );
        if(benchLive.length > 0){
          subName = benchLive[(s.cpuSubsCount - 1) % benchLive.length].name;
        }
      }
      // Ou na squad ativa da carreira
      if(!subName && state?.teams && state.teams[cpuTeam] && Array.isArray(state.teams[cpuTeam].squad)){
        const squadBench = state.teams[cpuTeam].squad.filter(p =>
          !cpuPlayers.some(cp => norm(cp.name) === norm(p.name)) && p.pos !== 'GK'
        );
        if(squadBench.length > 0){
          subName = squadBench[(s.cpuSubsCount - 1) % squadBench.length].name;
        }
      }
      // Fallback inteligente
      if(!subName){
        const subNames = ['Matheusinho', 'Lucas Moura', 'Rodrigo Silva', 'Paulinho', 'Danilo'];
        subName = subNames[s.cpuSubsCount % subNames.length];
      }

      tiredPlayer.name = subName;
      tiredPlayer.fullName = `${subName} (Sub)`;
      tiredPlayer.stamina = 100;
      s.events.unshift({
        min,
        type: 'whistle',
        text: `🔄 SUBSTITUIÇÃO NO ${cpuTeam}: Entra ${subName} com fôlego renovado para reorganizar as linhas táticas.`
      });
    }
  }

  // 2. Mudança tática por contexto de placar aos 75'+
  if(min >= 75 && !s.cpuTacticalShiftDone){
    if(diff < 0){
      // CPU perdendo: avança linhas, sobe pressão e assume postura ofensiva
      s.cpuTacticalShiftDone = true;
      if(isUserHome) s.awayPosture = 'Pressão total'; else s.homePosture = 'Pressão total';
      s.events.unshift({
        min,
        type: 'whistle',
        text: `⚡ AJUSTE TÁTICO DO ${cpuTeam}: O treinador manda adiantar todas as linhas, aciona o bloco alto e parte para o abafa final!`
      });
    } else if(diff > 0){
      // CPU vencendo por 1+: recua para retranca segura e fecha espaços
      s.cpuTacticalShiftDone = true;
      if(isUserHome) s.awayPosture = 'Retranca'; else s.homePosture = 'Retranca';
      s.events.unshift({
        min,
        type: 'whistle',
        text: `🛡️ AJUSTE TÁTICO DO ${cpuTeam}: O treinador fecha as linhas na entrada da grande área e aposta no contra-ataque veloz.`
      });
    }
  }
}

function simulateMinute(s, min){
  if(!s || s.done) return;
  s.minute = min;
  s.simMinute = min;
  s.simTicks = (s.simTicks || 0) + 1;
  s.timeSec = min * 60;

  // Inicializa estatísticas avançadas se necessário
  s.stats.passesH = s.stats.passesH || 0;
  s.stats.passesA = s.stats.passesA || 0;
  s.stats.passAccH = s.stats.passAccH || 82;
  s.stats.passAccA = s.stats.passAccA || 82;
  s.stats.tacklesH = s.stats.tacklesH || 0;
  s.stats.tacklesA = s.stats.tacklesA || 0;
  s.stats.interceptionsH = s.stats.interceptionsH || 0;
  s.stats.interceptionsA = s.stats.interceptionsA || 0;
  s.stats.crossesH = s.stats.crossesH || 0;
  s.stats.crossesA = s.stats.crossesA || 0;
  s.stats.offsidesH = s.stats.offsidesH || 0;
  s.stats.offsidesA = s.stats.offsidesA || 0;
  s.stats.savesH = s.stats.savesH || 0;
  s.stats.savesA = s.stats.savesA || 0;

  s.liveSubSec = 0;
  const minDisp = String(min).padStart(2, '0');
  const secDisp = String(Math.floor((s.timeSec || 0) % 60)).padStart(2, '0');
  const clk = $('#liveClockDisplay');
  if(clk) clk.textContent = `${minDisp}:${secDisp}`;

  // 1. Postura tática e desgaste de Stamina por minuto de jogo
  const hCfg = getPostureConfig(s.homePosture || 'Equilibrada');
  const aCfg = getPostureConfig(s.awayPosture || 'Equilibrada');
  const pitchBurn = s.stadium.pitch === 'synthetic' ? 1.25 : 1.0;
  const baseBurnPerMin = 0.38 * pitchBurn;

  const isUserHome = (norm(s.home) === norm(state.club));
  const speech = s.prelecao || 'Sem preleção';
  let speechShotMod = 1.0, speechTackleMod = 1.0, speechPassMod = 1.0, speechStamMod = 1.0;
  if(speech === 'Manter a calma'){ speechPassMod = 1.25; speechStamMod = 0.85; }
  else if(speech === 'Cobrar o time'){ speechShotMod = 1.25; speechStamMod = 1.10; }
  else if(speech === 'Elogiar o time'){ speechShotMod = 1.15; speechStamMod = 0.95; }
  else if(speech === 'Pedir raça'){ speechTackleMod = 1.30; speechStamMod = 1.25; }

  s.homePlayers.forEach(p => {
    if(!p.isGK){
      const roleStamMult = 1.0 + ((p.staminaCost || 25) - 25) * 0.015;
      const pressMult = 1.0 + (((s.homeTac?.pressIntensity || 65) - 65) * 0.005);
      const stamMod = hCfg.stamBurn * (isUserHome ? speechStamMod : 1.0) * roleStamMult * Math.max(0.7, pressMult);
      p.stamina = Math.max(15, (p.stamina || 100) - baseBurnPerMin * stamMod);
    }
  });
  s.awayPlayers.forEach(p => {
    if(!p.isGK){
      const roleStamMult = 1.0 + ((p.staminaCost || 25) - 25) * 0.015;
      const pressMult = 1.0 + (((s.awayTac?.pressIntensity || 65) - 65) * 0.005);
      const stamMod = aCfg.stamBurn * (!isUserHome ? speechStamMod : 1.0) * roleStamMult * Math.max(0.7, pressMult);
      p.stamina = Math.max(15, (p.stamina || 100) - baseBurnPerMin * stamMod);
    }
  });

  // 2. IA do Treinador: ajustes aos 60', 75' e reação ao placar
  evaluateAiCoachAdjustments(s, min);

  // Modo Jogador: entrada garantida do atleta reserva no 2º tempo (58') + blindagem contínua de posição exata em campo
  if(state?.gameMode === 'player' || state?.playerCareerState){
    if(!s.controlledAthleteOnPitch && min >= 58 && min <= 65){
      if(typeof triggerPlayerCareerSubstitution === 'function'){
        triggerPlayerCareerSubstitution(s);
      }
    }
    if(s.controlledAthleteOnPitch && typeof syncControlledAthletePitchSlotAndCoords === 'function'){
      syncControlledAthletePitchSlotAndCoords(s, false);
    }
  }

  // 3. Força e posse de bola relativa
  const homeCrowdBonus = Math.min(5, Math.max(0, Number(s.attendanceForceBonus ?? (norm(s.home) === norm(state?.club) ? attendanceProjection(s.away)?.attendanceForceBonus : stadiumAttendanceStrengthBonus(s.stadium?.attendance, s.stadium?.capacity))) || 0));
  const hs = (teamStrengthByName(s.home) + homeCrowdBonus) * 1.08;
  const as = teamStrengthByName(s.away);
  const hStamAvg = s.homePlayers.reduce((acc, p) => acc + (p.stamina || 100), 0) / 11;
  const aStamAvg = s.awayPlayers.reduce((acc, p) => acc + (p.stamina || 100), 0) / 11;
  const hStamFactor = 0.85 + 0.15 * (hStamAvg / 100);
  const aStamFactor = 0.85 + 0.15 * (aStamAvg / 100);

  const effH = hs * hStamFactor * (hCfg.speedMult || 1.0);
  const effA = as * aStamFactor * (aCfg.speedMult || 1.0);

  const hBuildUp = s.homeTac?.buildUpStyle || 'Balanced';
  const aBuildUp = s.awayTac?.buildUpStyle || 'Balanced';
  const hPress = s.homeTac?.pressIntensity || 65;
  const aPress = s.awayTac?.pressIntensity || 65;
  let tacPosShareMod = 0;
  if(hBuildUp === 'Possession') tacPosShareMod += 0.05;
  else if(hBuildUp === 'Short Passing') tacPosShareMod += 0.03;
  else if(hBuildUp === 'Direct' || hBuildUp === 'Counter Attack') tacPosShareMod -= 0.04;
  if(aBuildUp === 'Possession') tacPosShareMod -= 0.05;
  else if(aBuildUp === 'Short Passing') tacPosShareMod -= 0.03;
  else if(aBuildUp === 'Direct' || aBuildUp === 'Counter Attack') tacPosShareMod += 0.04;
  tacPosShareMod += (hPress - aPress) * 0.0012;

  const posShareH = clamp(effH / (effH + effA) + tacPosShareMod, 0.24, 0.76);
  s.stats.posH = Math.round(s.stats.posH * 0.94 + (posShareH * 100) * 0.06);
  s.stats.posA = 100 - s.stats.posH;

  const previousCarrier = s.ball?.carrier && !s.ball.carrier.redCard ? s.ball.carrier : null;
  const retainPossession = !!(previousCarrier && s.ball?.mode !== 'shot' && s.prng() < 0.68);
  const isHomeAttacking = retainPossession ? previousCarrier.team === 'home' : s.prng() < posShareH;
  let isHome = isHomeAttacking;
  let attTeam = isHome ? s.home : s.away;
  let defTeam = isHome ? s.away : s.home;
  let attPlayers = isHome ? s.homePlayers : s.awayPlayers;
  let defPlayers = isHome ? s.awayPlayers : s.homePlayers;
  let attCfg = isHome ? hCfg : aCfg;
  let defCfg = isHome ? aCfg : hCfg;

  // Atualiza passes computados da rodada do minuto
  if(isHome){
    s.stats.passesH += Math.round(5 + s.prng() * 4);
    s.stats.passesA += Math.round(2 + s.prng() * 2);
  } else {
    s.stats.passesA += Math.round(5 + s.prng() * 4);
    s.stats.passesH += Math.round(2 + s.prng() * 2);
  }

  // =========================================================================
  // MÁQUINA DE ESTADOS TÁTICA (BUILD_UP -> PROGRESSION -> FINAL_THIRD -> SHOT)
  // =========================================================================
  let possessionPhase = 'BUILD_UP';
  let isCounterAttack = false;

  // FASE 1: BUILD_UP (Construção / Saída de Bola sob pressão)
  const defTacPress = isHome ? (s.awayTac?.pressIntensity || 65) : (s.homeTac?.pressIntensity || 65);
  const defPressBonus = (defCfg.posture === 'Pressão total' ? 0.08 : defCfg.posture === 'Ofensiva' ? 0.04 : 0) + ((defTacPress - 65) * 0.0018);
  const buildUpRoll = s.prng();
  const hasUserControlledOnAttack = Boolean(
    (state?.gameMode === 'player' || state?.playerCareerState) &&
    attPlayers.some(p => p && p.isControlledAthlete && !p.isGK && !p.redCard)
  );
  if(buildUpRoll < 0.08 + defPressBonus){
    // TURNOVER: Perda de bola pressionada na zaga gerando contra-ataque veloz!
    if(isHome) s.stats.interceptionsA++; else s.stats.interceptionsH++;
    isHome = !isHome;
    attTeam = isHome ? s.home : s.away;
    defTeam = isHome ? s.away : s.home;
    attPlayers = isHome ? s.homePlayers : s.awayPlayers;
    defPlayers = isHome ? s.awayPlayers : s.homePlayers;
    attCfg = isHome ? hCfg : aCfg;
    defCfg = isHome ? aCfg : hCfg;
    isCounterAttack = true;
    possessionPhase = 'FINAL_THIRD';
  } else if(buildUpRoll < 0.18 + defPressBonus){
    // Falta tática da equipe adversária travando a saída de bola
    if(isHome) s.stats.foulsA++; else s.stats.foulsH++;
    const nonGkDef = defPlayers.filter(p => p && !p.isGK && !p.redCard);
    const defP = (nonGkDef.length > 0)
      ? (nonGkDef[Math.floor(s.prng() * nonGkDef.length)] || nonGkDef[0])
      : (defPlayers.find(p => p && !p.redCard) || defPlayers[0] || { name: 'Defensor' });
    s.events.unshift({ min, type: 'whistle', text: `⚠️ Falta tática de ${defP.name || 'Defensor'} (${defTeam}) travando o início da jogada do ${attTeam}.` });
    if(window.afmAudio) window.afmAudio.playSFX('whistle_foul');
    possessionPhase = 'RESTART';
  } else if(buildUpRoll < (hasUserControlledOnAttack ? 0.36 : 0.52)){
    // Circulação paciente de bola entre zagueiros e laterais (manutenção de posse)
    if(isHome) s.stats.passesH += 4; else s.stats.passesA += 4;
    possessionPhase = 'RESTART';
  } else {
    possessionPhase = 'PROGRESSION';
  }

  // FASE 2: PROGRESSION (Meio de Campo / Transição)
  if(possessionPhase === 'PROGRESSION'){
    const midRoll = s.prng();
    const midFailCutoff = hasUserControlledOnAttack ? 0.54 : 0.72;
    if(midRoll < 0.26){
      // Interceptação ou desarme da zaga no meio-campo
      if(isHome) { s.stats.interceptionsA++; s.stats.tacklesA++; }
      else { s.stats.interceptionsH++; s.stats.tacklesH++; }
    } else if(midRoll < 0.42){
      // RECYCLE_POSSESSION: Meio-campo recua e inverte o corredor pacientemente
      if(isHome) s.stats.passesH += 5; else s.stats.passesA += 5;
    } else if(midRoll < midFailCutoff){
      // Falta no meio-campo com possível cartão amarelo
      if(isHome) s.stats.foulsA++; else s.stats.foulsH++;
      const nonGkDef = defPlayers.filter(p => p && !p.isGK && !p.redCard);
      const defP = (nonGkDef.length > 0)
        ? (nonGkDef[Math.floor(s.prng() * nonGkDef.length)] || nonGkDef[0])
        : (defPlayers.find(p => p && !p.redCard) || defPlayers[0] || { name: 'Defensor' });
      if(s.prng() < 0.16){
        if(!defP.yellowCards){
          defP.yellowCards = 1;
          if(isHome) s.stats.yellowsA++; else s.stats.yellowsH++;
          s.events.unshift({ min, type: 'yellow', text: `🟨 Cartão amarelo para ${defP.name || 'Defensor'} (${defTeam}) por entrada dura no círculo central.` });
          if(window.afmAudio) window.afmAudio.playSFX('whistle_card');
        } else if(defP.yellowCards === 1 && !defP.redCard){
          defP.yellowCards = 2;
          defP.redCard = true;
          if(isHome){ s.stats.yellowsA++; s.stats.redsA++; } else { s.stats.yellowsH++; s.stats.redsH++; }
          s.events.unshift({ min, type: 'red', text: `🟥 Segundo cartão amarelo e EXPULSÃO de ${defP.name || 'Defensor'} (${defTeam})! Deixa seu time com um a menos!` });
          if(window.afmAudio) window.afmAudio.playSFX('whistle_card');
        }
      } else {
        s.events.unshift({ min, type: 'whistle', text: `⚠️ Falta marcada de ${defP.name || 'Defensor'} sobre o meia do ${attTeam}.` });
        if(window.afmAudio) window.afmAudio.playSFX('whistle_foul');
      }
    } else {
      // Infiltração e passe vertical bem-sucedido: avança ao terço final!
      possessionPhase = 'FINAL_THIRD';
    }
  }

  // FASE 3: FINAL_THIRD & CHANCE_CREATION (Último Terço e Resolução Ofensiva)
  if(possessionPhase === 'FINAL_THIRD'){
    // O ataque escolhe o jogador de linha mais adiantado; a finalização só acontece na zona ofensiva.
    const fwPool = attPlayers.filter(p => p && !p.isGK && !p.redCard && ['ST','CF','RW','LW','AM','CM'].includes(p.pos));
    const goalProgressOf = p => isHome ? (Number(p?.x) || 50) : 100 - (Number(p?.x) || 50);
    const rankedForwards = [...fwPool].sort((a, b) => goalProgressOf(b) - goalProgressOf(a));
    const topOptions = rankedForwards.slice(0, Math.min(3, rankedForwards.length));
    const continuingAttacker = previousCarrier && attPlayers.includes(previousCarrier) && !previousCarrier.isGK && !previousCarrier.redCard && ['ST','CF','RW','LW','AM','CM'].includes(previousCarrier.pos)
      ? previousCarrier
      : null;
    const lineAtt = attPlayers.filter(p => p && !p.isGK && !p.redCard);
    const isPlayerCareerActive = Boolean(state?.gameMode === 'player' || state?.playerCareerState);
    const userIsHomeTeam = (typeof norm === 'function' ? norm(s.home) === norm(state?.club) : s.home === state?.club);
    const isUserTeamAttacking = isHome === userIsHomeTeam;
    const userAthlete = isPlayerCareerActive && isUserTeamAttacking
      ? attPlayers.find(p => p.isControlledAthlete && !p.redCard && !p.isGK)
      : null;
    const isCallBallActive = s.craqueCallBallUntil && Date.now() < s.craqueCallBallUntil;

    // Protagonismo ampliado do atleta do usuário no terço final (78% normal / 100% ao pedir bola)
    if(userAthlete && (isCallBallActive || s.prng() < 0.78)){
      s.ball.carrier = userAthlete;
    } else {
      s.ball.carrier = continuingAttacker || (topOptions.length ? topOptions[Math.floor(s.prng() * topOptions.length)] : (lineAtt[Math.floor(s.prng() * lineAtt.length)] || attPlayers[0] || { name: 'Atacante', pos: 'ST' }));
    }
    s.ball.isHomeAttacking = isHome;

    // Se a bola estiver com o atleta do usuário no ataque, chance maior de disparar o Momento Decisivo (a cada 5 min)
    if(userAthlete && s.ball.carrier === userAthlete && !s.craqueDecisionActive && (!s.lastCraqueMomentMin || (min - s.lastCraqueMomentMin) >= 5)){
      s.lastCraqueMomentMin = min;
      setTimeout(() => {
        if(!s.done && typeof triggerCraqueDecisionMoment === 'function'){
          triggerCraqueDecisionMoment(s, userAthlete);
        }
      }, 100);
    }

    const shootZoneProgress = 68;
    let carrierProgress = goalProgressOf(s.ball.carrier);
    if(carrierProgress < shootZoneProgress){
      // O atleta controlado conduz até a zona de finalização sem travar em 67.5 < 68!
      const dir = isHome ? 1 : -1;
      const maxBurst = (userAthlete && s.ball.carrier === userAthlete) ? 26 : 18;
      const advance = Math.min(maxBurst, (shootZoneProgress + 2) - carrierProgress);
      s.ball.carrier.x = clamp((Number(s.ball.carrier.x) || 50) + dir * advance, 4, 96);
      s.ball.x = s.ball.carrier.x;
      s.ball.y = s.ball.carrier.y;
      carrierProgress = goalProgressOf(s.ball.carrier);
    }

    if(carrierProgress < shootZoneProgress){
      const receiver = selectLivePassTarget(attPlayers, s.ball.carrier, 0.8, 30);
      if(receiver){
        startLivePass(s, s.ball.carrier, receiver, { logEvent: true, cooldownFrames: 110 });
      }
    } else {
      const boxRoll = s.prng();
      const nonGkDef = defPlayers.filter(p => p && !p.isGK && !p.redCard);
      const safeDefP = (nonGkDef.length > 0)
        ? (nonGkDef[Math.floor(s.prng() * nonGkDef.length)] || nonGkDef[0])
        : (defPlayers.find(p => p && !p.redCard) || defPlayers[0] || { name: 'Defensor' });

      if(boxRoll < 0.05){
        // PÊNALTI!
        executePenaltySim(s, min, s.ball.carrier, safeDefP, isHome);
      } else if(boxRoll < 0.16){
        // FALTA PERIGOSA NA ENTRADA DA ÁREA!
        executeFreeKickSim(s, min, s.ball.carrier, safeDefP, isHome);
      } else if(boxRoll < 0.34){
        // Desarme limpo na área desviado para ESCANTEIO
        if(isHome) { s.stats.cornersH++; s.stats.tacklesA++; }
        else { s.stats.cornersA++; s.stats.tacklesH++; }
        s.events.unshift({ min, type: 'corner', text: `🚩 Escanteio para o ${attTeam}! A zaga trava a infiltração no momento exato e desvia pela linha de fundo.` });
        showLiveBalloon(isHome ? 99 : 1, 50, '🚩 ESCANTEIO!', '#38bdf8');
      } else {
        // FINALIZAÇÃO A GOL! O carregador vem do terço final.
        executeShotSim(s, min, attPlayers, defPlayers, isHome, attCfg, attTeam, defTeam, isCounterAttack);
      }
    }
  } else {
    // Construção: mantém a posse e tenta uma ligação curta/vertical real com um companheiro.
    const carrierPool = attPlayers.filter(p => !p.isGK && !p.redCard);
    const activeCarrier = s.ball?.carrier && attPlayers.includes(s.ball.carrier) && !s.ball.carrier.isGK && !s.ball.carrier.redCard ? s.ball.carrier : null;
    const builders = carrierPool.filter(p => ['CB','LB','RB','DM','CM','AM'].includes(p.pos));
    const carrier = activeCarrier || (builders.length ? builders[Math.floor(s.prng() * builders.length)] : carrierPool[Math.floor(s.prng() * carrierPool.length)]) || attPlayers[9];
    s.ball.carrier = carrier;
    s.ball.isHomeAttacking = isHome;
    const receiver = selectLivePassTarget(attPlayers, carrier, 0.8, 24);
    if(receiver) startLivePass(s, carrier, receiver, { logEvent: true, cooldownFrames: 110 });
  }

  // Atualiza placar e feed na interface
  if(min % 10 === 0 && window.AFM_Competitions && typeof window.AFM_Competitions.simulateLiveParallelMatches === 'function'){
    if(!s.parallelFixtures && state.fixtures){
      const otherMatches = (state.fixtures[state.round] || []).filter(f => norm(f[0]) !== norm(s.home) && norm(f[1]) !== norm(s.home));
      s.parallelFixtures = otherMatches.map(f => ({ homeName: f[0], awayName: f[1], homeGoals: 0, awayGoals: 0 }));
    }
    if(s.parallelFixtures && s.parallelFixtures.length){
      const parallelEvents = window.AFM_Competitions.simulateLiveParallelMatches(s.parallelFixtures, min);
      if(parallelEvents && parallelEvents.length){
        parallelEvents.forEach(pEv => {
          s.events.unshift({ min, type: 'whistle', text: pEv.text });
        });
      }
    }
  }
  updateScoreDisplay();
  updateLiveSidebarEvents();

  // Verificação de Intervalo com Acréscimos Realistas
  if(min === 45 && !s.stoppageBoard1HShown){
    s.stoppageBoard1HShown = true;
    if(window.AFM_REAL_FOOTBALL?.rules?.calculateStoppageTime){
      s.stoppage1H = window.AFM_REAL_FOOTBALL.rules.calculateStoppageTime(s.events, 1);
    }
    const stop1H = s.stoppage1H || 2;
    s.events.unshift({ min: 45, type: 'referee', text: `🚩 Placa de acréscimos levantada pelo 4º árbitro: +${stop1H} min no 1º tempo!` });
    toast(`🚩 +${stop1H}' de acréscimos no 1º tempo!`);
  }
  const stop1H = s.stoppage1H || 2;

  if(min >= (45 + stop1H) && s.phase === 'FIRST_HALF'){
    s.halftimeTriggered = true;
    s.playing = false;
    transitionMatchPhase('HALF_TIME');
    if(window.afmAudio){
      window.afmAudio.playSFX('whistle_halftime');
    } else {
      playWhistleSound();
    }
    s.events.unshift({ min: 45 + stop1H, type: 'whistle', text: `⏱ Fim do 1º tempo! ${s.home} ${s.hg} x ${s.ag} ${s.away}. As equipes descem para o vestiário.` });
    updateScoreDisplay();
    updateLiveSidebarEvents();
    renderLiveMatchModal();
    openHalftimeModal();
    return;
  }

  // Verificação de Final do Tempo Regulamentar com Acréscimos
  if(min === 90 && !s.stoppageBoard2HShown && (s.phase === 'SECOND_HALF' || s.phase === 'HALF_TIME')){
    s.stoppageBoard2HShown = true;
    if(window.AFM_REAL_FOOTBALL?.rules?.calculateStoppageTime){
      s.stoppage2H = window.AFM_REAL_FOOTBALL.rules.calculateStoppageTime(s.events, 2);
    }
    const stop2H = s.stoppage2H || 4;
    s.events.unshift({ min: 90, type: 'referee', text: `🚩 Placa de acréscimos levantada pelo 4º árbitro: +${stop2H} min no 2º tempo!` });
    toast(`🚩 +${stop2H}' de acréscimos no 2º tempo!`);
  }
  const stop2H = s.stoppage2H || 4;

  if(min >= (90 + stop2H) && (s.phase === 'SECOND_HALF' || s.phase === 'HALF_TIME')){
    if(s.isKO && s.hg === s.ag){
      s.phase = 'EXTRA_TIME_1';
      s.events.unshift({ min: 90 + stop2H, type: 'whistle', text: `⏱ Fim do tempo regulamentar (${s.hg} x ${s.ag})! O confronto vai para a PRORROGAÇÃO!` });
      toast('⏱ Prorrogação: 2 tempos de 15 minutos!');
      updateScoreDisplay();
      updateLiveSidebarEvents();
      return;
    }
    s.playing = false;
    transitionMatchPhase('FULL_TIME');
    finishLiveMatch();
    return;
  }

  // Prorrogação 1º Tempo (91' a 105')
  if(s.phase === 'EXTRA_TIME_1' && min >= 105){
    s.phase = 'EXTRA_TIME_2';
    s.events.unshift({ min: 105, type: 'whistle', text: `⏱ Fim do 1º tempo da prorrogação! ${s.home} ${s.hg} x ${s.ag} ${s.away}. Inversão rápida de lados.` });
    updateScoreDisplay();
    updateLiveSidebarEvents();
    return;
  }

  // Prorrogação 2º Tempo (106' a 120')
  if(s.phase === 'EXTRA_TIME_2' && min >= 120){
    s.playing = false;
    transitionMatchPhase('FULL_TIME');
    finishLiveMatch();
    return;
  }
}

if(typeof window !== 'undefined'){
  window.AFM_LiveMatch = window.AFM_LiveMatch || {};
  window.AFM_LiveMatch.updateLiveCanvasPositions = updateLiveCanvasPositions;
  window.AFM_LiveMatch.simulateMinute = simulateMinute;
}

// =========================================================================
// PADRÕES DE JOGADA, VALIDAÇÃO DE ENTIDADES E EVENTOS DO MATCH ENGINE
// =========================================================================
const PLAY_PATTERNS = [
  { id: 'through_ball', name: 'Passe em Profundidade', text: 'descola belo passe enfiado nas costas dos zagueiros', chanceType: 'throughBall', xGMod: 1.25 },
  { id: 'crossing', name: 'Cruzamento na Área', text: 'alça bola açucarada na grande área', chanceType: 'cross', xGMod: 1.10 },
  { id: 'cutback', name: 'Passe para Trás / Cutback', text: 'vai ao fundo e rola para trás na entrada da área', chanceType: 'cutback', xGMod: 1.35 },
  { id: 'counter_attack', name: 'Contra-Ataque Veloz', text: 'dispara em transição fulminante com superioridade numérica', chanceType: 'counterAttack', xGMod: 1.30 },
  { id: 'tabela_one_two', name: 'Tabela Rápida', text: 'tabela de primeira na entrada da área com agilidade', chanceType: 'oneTwo', xGMod: 1.20 },
  { id: 'dribble_run', name: 'Jogada Individual', text: 'deixa o marcador no chão com lindo drible de corpo', chanceType: 'individualDribble', xGMod: 1.18 },
  { id: 'long_shot', name: 'Chute de Longe', text: 'limpa o lance e solta uma bomba de fora da área', chanceType: 'longShot', xGMod: 0.85 },
  { id: 'ball_recovery', name: 'Pressão Alta', text: 'recupera a posse na saída de bola com pressão agressiva', chanceType: 'counterAttack', xGMod: 1.25 },
  { id: 'short_build', name: 'Construção Curta', text: 'troca passes com paciência até encontrar a brecha', chanceType: 'cutback', xGMod: 1.05 }
];

function selectPlayPattern(s, attCfg, isHomeAttacking, shooter, assist){
  s.recentPlayPatterns = s.recentPlayPatterns || [];
  const posture = attCfg?.posture || 'Equilibrada';

  // Modular probabilidade baseada na função do Atacante e Assistente
  const weights = PLAY_PATTERNS.map(pat => {
    let w = 1.0;
    if(shooter?.roleName === 'Advanced Forward' && pat.id === 'through_ball') w *= 2.8;
    if(shooter?.roleName === 'Target Forward' && pat.id === 'crossing') w *= 2.6;
    if(shooter?.roleName === 'False 9' && (pat.id === 'tabela_one_two' || pat.id === 'cutback')) w *= 2.4;
    if(shooter?.roleName === 'Poacher' && pat.id === 'cutback') w *= 2.2;
    if(assist?.roleName === 'Deep-Lying Playmaker' && pat.id === 'through_ball') w *= 2.5;
    if(assist?.roleName === 'Winger' && pat.id === 'crossing') w *= 2.6;
    if(assist?.roleName === 'Inside Forward' && pat.id === 'cutback') w *= 2.2;

    if(posture === 'Retranca' && pat.id === 'counter_attack') w *= 2.5;
    if(posture === 'Pressão total' && pat.id === 'ball_recovery') w *= 2.2;
    if(posture === 'Ofensiva' && pat.id === 'through_ball') w *= 1.8;

    if(s.recentPlayPatterns.slice(-2).includes(pat.name)) w *= 0.25;
    return w;
  });

  const total = weights.reduce((a, b) => a + b, 0);
  let roll = s.prng() * total;
  let chosen = PLAY_PATTERNS[0];
  for(let i = 0; i < PLAY_PATTERNS.length; i++){
    roll -= weights[i];
    if(roll <= 0){
      chosen = PLAY_PATTERNS[i];
      break;
    }
  }

  s.recentPlayPatterns.push(chosen.name);
  if(s.recentPlayPatterns.length > 8) s.recentPlayPatterns.shift();
  return chosen;
}

function validateGoalScorer(shooter, attTeam, s){
  if(!shooter) return false;
  if(shooter.type !== 'PLAYER') return false;
  if(shooter.canScore === false && !shooter.isPenalty) return false;
  const isHome = (attTeam === s.home);
  const teamList = isHome ? s.homePlayers : s.awayPlayers;
  const found = teamList.find(p => p.id === shooter.id);
  if(!found) return false;
  if(found.redCard) return false;
  return true;
}

function validateAssist(assist, attTeam, s){
  if(!assist) return false;
  if(assist.type !== 'PLAYER') return false;
  const isHome = (attTeam === s.home);
  const teamList = isHome ? s.homePlayers : s.awayPlayers;
  return !!teamList.find(p => p.id === assist.id && !p.redCard);
}

function validateMatchEntity(ent, s){
  if(!ent || !s) return false;
  if(ent.type === 'REFEREE') return true;
  if(Array.isArray(s.homePlayers) && s.homePlayers.some(p => p === ent || (ent.id && p.id === ent.id) || (ent.key && p.key === ent.key))) return true;
  if(Array.isArray(s.awayPlayers) && s.awayPlayers.some(p => p === ent || (ent.id && p.id === ent.id) || (ent.key && p.key === ent.key))) return true;
  return false;
}

function validateMatchEvent(evt, s){
  if(!evt) return false;
  if(!evt.matchId || evt.matchId !== s.matchId) return false;
  return true;
}

function executeShotSim(s, min, attPlayers, defPlayers, isHomeAttacking, attCfg, attTeam, defTeam, isCounterAttack=false){
  const forwards = attPlayers.filter(p => p && ['ST', 'CF', 'RW', 'LW', 'AM'].includes(p.pos) && !p.redCard && !p.isGK);
  const liveCarrier = s.ball?.carrier;
  const lineAtt = attPlayers.filter(p => p && !p.isGK && !p.redCard);
  const controlledAttacker = (state?.gameMode === 'player' || state?.playerCareerState)
    ? attPlayers.find(p => p && p.isControlledAthlete && !p.isGK && !p.redCard)
    : null;
  const ctrlPosGroup = controlledAttacker && window.AFM_PlayerEngine?.normalizePlayerPosGroup
    ? window.AFM_PlayerEngine.normalizePlayerPosGroup(controlledAttacker.naturalPos || controlledAttacker.pos)
    : null;
  const preferCtrlShooter = Boolean(controlledAttacker && ['ATA', 'PON', 'MEI'].includes(ctrlPosGroup) && s.prng() < 0.68);
  const shooter = preferCtrlShooter
    ? controlledAttacker
    : ((liveCarrier && attPlayers.includes(liveCarrier) && !liveCarrier.isGK && !liveCarrier.redCard)
      ? liveCarrier
      : ((forwards.length && s.prng() < 0.84)
        ? forwards[Math.floor(s.prng() * forwards.length)]
        : (lineAtt.length ? lineAtt[Math.floor(s.prng() * lineAtt.length)] : (attPlayers[0] || { name: 'Atacante', pos: 'ST' }))));

  if(!validateMatchEntity(shooter, s) || shooter.isGK) return;

  const gk = defPlayers.find(p => p.isGK) || defPlayers[0] || { name: 'Goleiro', overall: 65, attrs: { reactions: 65, positioning: 65 } };

  // Assistente em potencial (prioriza o atleta controlado caso outro companheiro finalize!)
  const assistCandidates = attPlayers.filter(p => !p.isGK && p !== shooter && !p.redCard);
  const preferCtrlAssist = Boolean(controlledAttacker && controlledAttacker !== shooter && ['MEI', 'PON', 'VOL', 'LAT', 'ATA'].includes(ctrlPosGroup) && s.prng() < 0.58);
  let assist = preferCtrlAssist
    ? controlledAttacker
    : ((assistCandidates.length && s.prng() < 0.74)
      ? assistCandidates[Math.floor(s.prng() * assistCandidates.length)]
      : null);
  if(assist && !validateAssist(assist, attTeam, s)) assist = null;

  const pattern = isCounterAttack
    ? PLAY_PATTERNS.find(p => p.id === 'counter_attack') || PLAY_PATTERNS[3]
    : selectPlayPattern(s, attCfg, isHomeAttacking, shooter, assist);

  if(isHomeAttacking) s.stats.shotsH++; else s.stats.shotsA++;
  if(shooter) shooter.shots = (shooter.shots || 0) + 1;
  if(pattern.id === 'crossing'){
    if(isHomeAttacking) s.stats.crossesH++; else s.stats.crossesA++;
  }

  // Interação Tática Especial: Linha Alta adversária vs Advanced Forward
  const defTac = isHomeAttacking ? (s.awayTac || {}) : (s.homeTac || {});
  const defLineHeight = Number(defTac.lineHeight) || 60;
  let throughBallBonus = 0;
  if(shooter.roleName === 'Advanced Forward' && defLineHeight >= 65){
    throughBallBonus = 0.08;
    if(s.prng() < 0.14){
      if(isHomeAttacking) s.stats.offsidesH++; else s.stats.offsidesA++;
      s.events.unshift({
        min,
        type: 'whistle',
        text: `🚩 IMPEDIMENTO! ${shooter.name} disparou nas costas da zaga mas foi flagrado em posição irregular pela arbitragem.`
      });
      return;
    }
  }

  // Cálculo granular de xG baseado em atributos técnicos e contexto do lance
  const finishAttr = shooter.attrs?.finishing || shooter.overall || 65;
  const compAttr = shooter.attrs?.composure || shooter.overall || 65;
  const assistPassAttr = assist?.attrs?.passing || 65;
  const gkReactAttr = gk.attrs?.reactions || gk.overall || 65;
  const gkPosAttr = gk.attrs?.positioning || gk.overall || 65;
  const gkQuality = (gkReactAttr * 0.6 + gkPosAttr * 0.4);

  const baseShotXG = (0.10 + (finishAttr - gkQuality) * 0.0030 + (compAttr - 65) * 0.0015 + (assistPassAttr - 65) * 0.0012 + throughBallBonus) * (pattern.xGMod || 1.0);
  const shotXG = clamp(+baseShotXG.toFixed(2), 0.05, 0.40);

  if(isHomeAttacking) s.stats.xGH = +(s.stats.xGH + shotXG).toFixed(2);
  else s.stats.xGA = +(s.stats.xGA + shotXG).toFixed(2);

  // Configuração da trajetória visual do chute no campo 2.5D
  s.ball.carrier = null;
  s.ball.mode = 'shot';
  s.ball.shooter = shooter;
  s.ball.passer = assist;
  s.ball.startX = shooter.x;
  s.ball.startY = shooter.y;
  s.ball.targetX = isHomeAttacking ? 99.5 : 0.5;
  s.ball.targetY = 50 + ((s.prng() * 16) - 8);
  s.ball.progress = 0;
  s.ball.curveZ = 6.0;

  const roll = s.prng();
  const second = Math.floor(s.prng() * 59);

  const assistRoleName = assist ? (assist.roleName || 'Meia') : '';
  const shooterRoleName = shooter.roleName || 'Atacante';
  const causalChainText = assist
    ? `${assist.name} (${assistRoleName}) ${pattern.text} e acha ${shooter.name} (${shooterRoleName})`
    : `${shooter.name} (${shooterRoleName}) ${pattern.text}`;

  // 1. GOL CONFIRMADO
  if(roll < shotXG){
    if(!validateGoalScorer(shooter, attTeam, s)) return;
    s.ball.shotOutcome = 'gol';
    if(isHomeAttacking) { s.hg++; s.stats.targetH++; }
    else { s.ag++; s.stats.targetA++; }
    if(window.afmAudio){
      window.afmAudio.playSFX('goal_celebration');
      window.afmAudio.boostCrowdCheer(4);
    } else {
      playCheerSound();
    }

    const goalTxt = `⚽ GOL DO ${attTeam}! ${causalChainText}, que chapa com precisão estufando a rede de ${gk.name}! (xG: ${shotXG}) aos ${min}'!`;

    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'gol',
      teamId: attTeam,
      playerId: shooter.id,
      relatedPlayerId: assist?.id || null,
      pattern: pattern.name,
      context: `Placar: ${s.home} ${s.hg} x ${s.ag} ${s.away}`,
      text: goalTxt,
      xG: shotXG,
      scorer: shooter.fullName || shooter.name,
      assist: assist?.fullName || assist?.name || null
    };

    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBanner(`⚽ GOL DO ${attTeam}! ${shooter.name} aos ${min}'!`, 'gol', 3500);
    s.lastScorer = shooter;
  }
  // 2. DEFESA DO GOLEIRO (No alvo)
  else if(roll < shotXG + 0.38){
    s.ball.shotOutcome = 'save';
    if(isHomeAttacking) { s.stats.targetH++; s.stats.savesA++; }
    else { s.stats.targetA++; s.stats.savesH++; }
    if(window.afmAudio) window.afmAudio.playSFX('crowd_gasp');

    const defRoll = s.prng();
    if(defRoll < 0.48){
      // Espalma para escanteio
      s.ball.isCorner = true;
      if(isHomeAttacking) s.stats.cornersH++; else s.stats.cornersA++;
      const evt = {
        id: `${s.matchId}_ev_${s.events.length + 1}`,
        matchId: s.matchId,
        min,
        second,
        type: 'save',
        teamId: attTeam,
        playerId: shooter.id,
        relatedPlayerId: gk?.id || null,
        pattern: pattern.name,
        text: `🧤 ESPALMOU! ${causalChainText}, mas ${gk.name} salta com agilidade incrível e espalma para escanteio! (xG: ${shotXG})`,
        xG: shotXG
      };
      if(validateMatchEvent(evt, s)) s.events.unshift(evt);
      showLiveBalloon(s.ball.targetX, s.ball.targetY, '🧤 DEFESASSA P/ ESCANTEIO!', '#38bdf8');
    } else if(defRoll < 0.70){
      // Rebote vivo na área
      s.ball.isRebound = true;
      const evt = {
        id: `${s.matchId}_ev_${s.events.length + 1}`,
        matchId: s.matchId,
        min,
        second,
        type: 'save',
        teamId: attTeam,
        playerId: shooter.id,
        relatedPlayerId: gk?.id || null,
        pattern: pattern.name,
        text: `🧤 REBOTE VIVO! ${causalChainText}. Chute cruzado espalmado por ${gk.name}, e a bola fica viva dentro da área! (xG: ${shotXG})`,
        xG: shotXG
      };
      if(validateMatchEvent(evt, s)) s.events.unshift(evt);
      showLiveBalloon(s.ball.targetX, s.ball.targetY, '🧤 REBOTE VIVO!', '#f97316');
    } else {
      // Defesa segura
      const evt = {
        id: `${s.matchId}_ev_${s.events.length + 1}`,
        matchId: s.matchId,
        min,
        second,
        type: 'save',
        teamId: attTeam,
        playerId: shooter.id,
        relatedPlayerId: gk?.id || null,
        pattern: pattern.name,
        text: `🧤 DEFESA SEGURA! ${causalChainText}. Finalização rasteira bem defendida e segurada por ${gk.name}.`,
        xG: shotXG
      };
      if(validateMatchEvent(evt, s)) s.events.unshift(evt);
      showLiveBalloon(s.ball.targetX, s.ball.targetY, '🧤 DEFESA SEGURA!', '#22c55e');
    }
  }
  // 3. CHUTE BLOQUEADO PELA ZAGA
  else if(roll < shotXG + 0.52){
    s.ball.shotOutcome = 'blocked';
    const def = defPlayers.filter(p => !p.isGK && ['CB','LB','RB','DM'].includes(p.pos))[0] || defPlayers[1];
    if(isHomeAttacking) s.stats.interceptionsA++; else s.stats.interceptionsH++;
    if(s.prng() < 0.48){
      if(isHomeAttacking) s.stats.cornersH++; else s.stats.cornersA++;
    }
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'whistle',
      teamId: attTeam,
      playerId: shooter.id,
      pattern: pattern.name,
      text: `🛡️ BLOQUEIO PROVIDENCIAL! ${causalChainText}. ${def?.name || 'Zagueiro'} se atira no carrinho e trava a finalização de ${shooter.name}!`
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBalloon(shooter.x + (isHomeAttacking ? 5 : -5), shooter.y, '🛡️ TRAVADO!', '#38bdf8');
  }
  // 4. BOLA NA TRAVE (Taxa calibrada para o futebol real ~3%)
  else if(roll < shotXG + 0.55){
    s.ball.shotOutcome = 'post';
    if(window.afmAudio) window.afmAudio.playSFX('goal_post');
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'post',
      teamId: attTeam,
      playerId: shooter.id,
      pattern: pattern.name,
      text: `💥 NA TRAVE! ${causalChainText}. ${shooter.name} solta uma bomba que explode no travessão! (xG: ${shotXG})`,
      xG: shotXG
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBalloon(s.ball.targetX, s.ball.targetY, '💥 NA TRAVE!', '#ef4444');
  }
  // 5. CHUTE PARA FORA
  else {
    s.ball.shotOutcome = 'miss';
    if(window.afmAudio && roll < shotXG + 0.76) window.afmAudio.playSFX('crowd_gasp');
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'miss',
      teamId: attTeam,
      playerId: shooter.id,
      pattern: pattern.name,
      text: `⚡ PRA FORA! ${causalChainText}. O arremate de ${shooter.name} tira tinta da trave e se perde pela linha de fundo.`
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
  }
}

function executePenaltySim(s, min, att, def, isHomeAttacking){
  const attTeam = isHomeAttacking ? s.home : s.away;
  const defTeam = isHomeAttacking ? s.away : s.home;
  const attPlayers = isHomeAttacking ? s.homePlayers : s.awayPlayers;
  const defPlayers = isHomeAttacking ? s.awayPlayers : s.homePlayers;
  const kicker = attPlayers.filter(p => !p.isGK && !p.redCard).sort((a,b)=>(b.overall||65)-(a.overall||65))[0] || att;
  const gk = defPlayers.find(p => p.isGK) || defPlayers[0] || { name: 'Goleiro', overall: 65 };

  if(!validateMatchEntity(kicker, s)) return;
  kicker.isPenalty = true;

  if(isHomeAttacking) s.stats.shotsH++; else s.stats.shotsA++;
  const penXG = 0.76;
  if(isHomeAttacking) s.stats.xGH = +(s.stats.xGH + penXG).toFixed(2);
  else s.stats.xGA = +(s.stats.xGA + penXG).toFixed(2);

  s.ball.carrier = null;
  s.ball.mode = 'shot';
  s.ball.shooter = kicker;
  s.ball.startX = isHomeAttacking ? 88.5 : 11.5;
  s.ball.startY = 50;
  s.ball.targetX = isHomeAttacking ? 99.5 : 0.5;
  s.ball.targetY = 50 + ((s.prng() * 12) - 6);
  s.ball.progress = 0;
  s.ball.curveZ = 3.5;

  const roll = s.prng();
  const second = Math.floor(s.prng() * 59);

  if(roll < penXG){
    if(!validateGoalScorer(kicker, attTeam, s)) return;
    s.ball.shotOutcome = 'gol';
    if(isHomeAttacking) { s.hg++; s.stats.targetH++; } else { s.ag++; s.stats.targetA++; }
    if(window.afmAudio){
      window.afmAudio.playSFX('goal_celebration');
      window.afmAudio.boostCrowdCheer(4);
    } else {
      playCheerSound();
    }
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'gol',
      teamId: attTeam,
      playerId: kicker.id,
      pattern: 'Pênalti',
      context: `Pênalti convertido | Placar: ${s.home} ${s.hg} x ${s.ag} ${s.away}`,
      text: `🎯 GOL DE PÊNALTI! ${kicker.name} desloca ${gk.name} e marca com categoria para o ${attTeam}!`,
      xG: penXG,
      scorer: kicker.name
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBanner(`⚽ GOL DE PÊNALTI DO ${attTeam}!`, 'gol', 3500);
    s.lastScorer = kicker;
  } else {
    s.ball.shotOutcome = 'save';
    if(isHomeAttacking) { s.stats.targetH++; s.stats.savesA++; }
    else { s.stats.targetA++; s.stats.savesH++; }
    if(window.afmAudio) window.afmAudio.playSFX('crowd_gasp');
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'save',
      teamId: attTeam,
      playerId: kicker.id,
      relatedPlayerId: gk?.id || null,
      pattern: 'Pênalti',
      text: `🧤 DEFENDEU O PÊNALTI! ${gk.name} salta com agilidade no canto e espalma a cobrança de ${kicker.name}!`,
      xG: penXG
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBalloon(s.ball.targetX, s.ball.targetY, '🧤 PÊNALTI DEFENDIDO!', '#22c55e');
  }
}

function executeFreeKickSim(s, min, att, def, isHomeAttacking){
  const attTeam = isHomeAttacking ? s.home : s.away;
  const defTeam = isHomeAttacking ? s.away : s.home;
  const attPlayers = isHomeAttacking ? s.homePlayers : s.awayPlayers;
  const defPlayers = isHomeAttacking ? s.awayPlayers : s.homePlayers;
  const kicker = attPlayers.filter(p => !p.isGK && !p.redCard).sort((a,b)=>(b.overall||65)-(a.overall||65))[0] || att;
  const gk = defPlayers.find(p => p.isGK) || defPlayers[0] || { name: 'Goleiro', overall: 65 };

  if(!validateMatchEntity(kicker, s)) return;

  if(isHomeAttacking) s.stats.shotsH++; else s.stats.shotsA++;
  const fkXG = 0.12;
  if(isHomeAttacking) s.stats.xGH = +(s.stats.xGH + fkXG).toFixed(2);
  else s.stats.xGA = +(s.stats.xGA + fkXG).toFixed(2);

  s.ball.carrier = null;
  s.ball.mode = 'shot';
  s.ball.shooter = kicker;
  s.ball.startX = att.x;
  s.ball.startY = att.y;
  s.ball.targetX = isHomeAttacking ? 99.5 : 0.5;
  s.ball.targetY = 50 + ((s.prng() * 12) - 6);
  s.ball.progress = 0;
  s.ball.curveZ = 6.5;

  const roll = s.prng();
  const second = Math.floor(s.prng() * 59);

  if(roll < fkXG){
    if(!validateGoalScorer(kicker, attTeam, s)) return;
    s.ball.shotOutcome = 'gol';
    if(isHomeAttacking) { s.hg++; s.stats.targetH++; } else { s.ag++; s.stats.targetA++; }
    if(window.afmAudio){
      window.afmAudio.playSFX('goal_celebration');
      window.afmAudio.boostCrowdCheer(4);
    } else {
      playCheerSound();
    }
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'gol',
      teamId: attTeam,
      playerId: kicker.id,
      pattern: 'Falta Direta',
      text: `🎯 GOLAÇO DE FALTA! ${kicker.name} acerta o ângulo com curva perfeita sem chances para ${gk.name}!`,
      xG: fkXG,
      scorer: kicker.name
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBanner(`⚽ GOLAÇO DE FALTA DO ${attTeam}!`, 'gol', 3500);
    s.lastScorer = kicker;
  } else if(roll < fkXG + 0.40){
    s.ball.shotOutcome = 'save';
    if(isHomeAttacking) s.stats.targetH++; else s.stats.targetA++;
    if(window.afmAudio) window.afmAudio.playSFX('crowd_gasp');
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'save',
      teamId: attTeam,
      playerId: kicker.id,
      relatedPlayerId: gk?.id || null,
      pattern: 'Falta Direta',
      text: `🧤 DEFESA! ${gk.name} espalma cobrança de falta venenosa de ${kicker.name} para escanteio.`,
      xG: fkXG
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
    showLiveBalloon(s.ball.targetX, s.ball.targetY, '🧤 DEFESA!', '#22c55e');
    if(isHomeAttacking) s.stats.cornersH++; else s.stats.cornersA++;
  } else {
    s.ball.shotOutcome = 'miss';
    const evt = {
      id: `${s.matchId}_ev_${s.events.length + 1}`,
      matchId: s.matchId,
      min,
      second,
      type: 'whistle',
      teamId: attTeam,
      playerId: kicker.id,
      pattern: 'Falta Direta',
      text: `⚠️ Falta perigosa cobrada por ${kicker.name} explode na barreira defensiva.`
    };
    if(validateMatchEvent(evt, s)) s.events.unshift(evt);
  }
}

function simulateMatchSegment(startMin, endMin){
  const s = liveMatchState;
  if(!s || s.done) return;
  const targetMin = Math.min(90, endMin);
  while(s.minute < targetMin && !s.done){
    simulateMinute(s, s.minute + 1);
  }
}

function updateTelemetryHud(s){
  // Telemetria interna desativada na interface visual de transmissão
}

function updateLiveMatchPhysics(dtSec){
  const s = liveMatchState;
  if(!s || s.done) return;
  updateLiveCanvasPositions(s);
}


function resetKickoff(restartingTeam){
  const s = liveMatchState;
  s.ball.mode = 'dribble';
  s.ball.x = 50; s.ball.y = 50; s.ball.z = 0;
  s.ball.trail = [];
  const team = restartingTeam === 'home' ? s.homePlayers : s.awayPlayers;
  // Reposiciona jogadores nas suas bases para o reinício
  [...s.homePlayers, ...s.awayPlayers].forEach(p => {
    p.x = p.baseX;
    p.y = p.baseY;
    p.diving = false;
    p.celebrating = false;
    p.kickTimer = 0;
  });
  s.ball.carrier = team[9] || team[0];
}

function updateScoreDisplay(){
  const s = liveMatchState;
  if(!s || !s.stats) return;
  const sh = $('#liveScoreH'); if(sh) sh.textContent = s.hg;
  const sa = $('#liveScoreA'); if(sa) sa.textContent = s.ag;
  const shotsL = $('#liveShotsLabel');
  if(shotsL) shotsL.textContent = `${s.stats.shotsH} FINALIZAÇÕES ${s.stats.shotsA}`;
  const fillH = $('#liveShotsFillH'), fillA = $('#liveShotsFillA');
  const tot = s.stats.shotsH + s.stats.shotsA;
  if(fillH && fillA){
    fillH.style.width = tot > 0 ? `${(s.stats.shotsH/tot)*100}%` : '50%';
    fillA.style.width = tot > 0 ? `${(s.stats.shotsA/tot)*100}%` : '50%';
  }
}

function updateLiveSidebarEvents(){
  const s = liveMatchState;
  if(!s || !Array.isArray(s.events)) return;
  const evList = $('#liveEventList');
  if(evList){
    evList.innerHTML = s.events.map(e => `
      <div class="live-sidebar-item ${e.type === 'gol' ? 'gol' : e.type === 'yellow' ? 'yellow' : e.type === 'red' ? 'red' : e.type === 'save' ? 'save' : ''}">
        <b style="color:#fbbf24">${e.min}'</b>
        <div>${esc(e.text)}</div>
      </div>
    `).join('');
  }
  const count = $('#liveEventCount');
  if(count) count.textContent = s.events.length;
}


// =========================================================================
// SISTEMA DE MOMENTOS DECISIVOS & STATUS AO VIVO DO CRAQUE (MODO JOGADOR)
// =========================================================================
function triggerCraqueDecisionMoment(s = liveMatchState, ath = null) {
  if (!s || s.done || s.craqueDecisionActive) return;
  const userIsHome = (typeof norm === 'function' ? norm(s.home) === norm(state?.club) : s.home === state?.club);
  const myTeam = userIsHome ? s.homePlayers : s.awayPlayers;
  const userAth = ath || (myTeam || []).find(p => p.isControlledAthlete && !p.redCard);
  if (!userAth) return;

  s.craqueDecisionActive = true;
  s.paused = true;

  const container = document.getElementById('matchModalContainer') || document.body;
  let overlay = document.getElementById('craqueDecisionOverlay');
  if (overlay) overlay.remove();

  overlay = document.createElement('div');
  overlay.id = 'craqueDecisionOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:100050;background:rgba(10,15,29,0.88);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:16px;animation:fadeInCraque 0.25s ease-out;';

  const normPos = normalizePlayerPositionCode(userAth.pos || 'ST');
  const isAttacker = ['ST', 'CF', 'LW', 'RW', 'CAM', 'CM'].includes(normPos);
  const isDefender = ['CB', 'LB', 'RB', 'CDM'].includes(normPos);

  const attrs = userAth.attrs || {};
  const fin = Number(attrs.finishing || userAth.overall || 65);
  const sho = Number(attrs.shooting || userAth.overall || 65);
  const dri = Number(attrs.dribbling || userAth.overall || 65);
  const pas = Number(attrs.passing || userAth.overall || 65);
  const pac = Number(attrs.pace || userAth.overall || 65);
  const def = Number(attrs.defending || attrs.tackling || userAth.overall || 65);
  const str = Number(attrs.strength || userAth.overall || 65);

  let options = [];
  if (isAttacker) {
    options = [
      {
        id: 'placed_shot',
        icon: '🎯',
        title: 'Chute Colocado no Canto',
        desc: `Finalização com curva e precisão (Fin: ${fin} · OVR ${userAth.overall || 65})`,
        chance: Math.min(85, Math.max(30, Math.round(fin * 0.75 + 15))),
        color: '#10b981'
      },
      {
        id: 'power_shot',
        icon: '💥',
        title: 'Bomba de Primeira',
        desc: `Chute forte no ângulo (Força/Chute: ${sho})`,
        chance: Math.min(80, Math.max(25, Math.round(sho * 0.72 + 12))),
        color: '#ef4444'
      },
      {
        id: 'dribble_box',
        icon: '⚡',
        title: 'Driblar e Invadir a Área',
        desc: `Finta no marcador para ficar cara a cara (Drible: ${dri} · Vel: ${pac})`,
        chance: Math.min(85, Math.max(28, Math.round((dri + pac) * 0.38 + 15))),
        color: '#f59e0b'
      },
      {
        id: 'assist_pass',
        icon: '🤝',
        title: 'Passe na Medida (Assistência)',
        desc: `Deixar o companheiro livre na cara do gol (Passe: ${pas})`,
        chance: Math.min(88, Math.max(35, Math.round(pas * 0.78 + 14))),
        color: '#38bdf8'
      }
    ];
  } else if (isDefender) {
    options = [
      {
        id: 'tackle_clean',
        icon: '🛡️',
        title: 'Desarme Limpo & Saída',
        desc: `Bote certeiro sem falta (Desarme: ${def})`,
        chance: Math.min(85, Math.max(30, Math.round(def * 0.76 + 15))),
        color: '#10b981'
      },
      {
        id: 'long_counter',
        icon: '🚀',
        title: 'Lançamento em Contra-Golpe',
        desc: `Passe longo nas costas da zaga (Passe: ${pas})`,
        chance: Math.min(82, Math.max(28, Math.round(pas * 0.74 + 12))),
        color: '#38bdf8'
      },
      {
        id: 'shield_ball',
        icon: '💪',
        title: 'Proteção de Corpo & Giro',
        desc: `Impor físico e reter a posse (Físico: ${str})`,
        chance: Math.min(86, Math.max(32, Math.round(str * 0.76 + 14))),
        color: '#f59e0b'
      },
      {
        id: 'long_shot',
        icon: '💥',
        title: 'Bomba de Longe',
        desc: `Finalização de média distância (Chute: ${sho})`,
        chance: Math.min(65, Math.max(20, Math.round(sho * 0.60 + 8))),
        color: '#ef4444'
      }
    ];
  } else {
    options = [
      { id: 'gk_left', icon: '🧤', title: 'Salto no Canto Esquerdo', desc: 'Fechar ângulo esquerdo', chance: 68, color: '#10b981' },
      { id: 'gk_center', icon: '🧤', title: 'Segurar Firme no Centro', desc: 'Espalmar ou encaixar no meio', chance: 75, color: '#38bdf8' },
      { id: 'gk_right', icon: '🧤', title: 'Salto no Canto Direito', desc: 'Fechar ângulo direito', chance: 68, color: '#f59e0b' },
      { id: 'gk_counter', icon: '⚡', title: 'Reposição Rápida', desc: 'Armar contra-ataque rápido', chance: 80, color: '#a855f7' }
    ];
  }

  overlay.innerHTML = `
    <div style="background:#0f172a;border:2px solid #38bdf8;box-shadow:0 0 35px rgba(56,189,248,0.45);border-radius:16px;max-width:540px;width:100%;padding:22px;color:#fff;font-family:'Inter',sans-serif;position:relative">
      <div style="display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:12px;margin-bottom:14px">
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-size:24px">⚡</span>
          <div>
            <div style="font-size:15px;font-weight:900;color:#38bdf8;letter-spacing:0.5px">MOMENTO DECISIVO DO CRAQUE</div>
            <div style="font-size:11px;color:#94a3b8">${esc(userAth.fullName || userAth.name)} (#${userAth.num || 10}) · ${normPos} · ${s.minute || 0}' min</div>
          </div>
        </div>
        <div style="font-size:12px;font-weight:900;background:rgba(56,189,248,0.15);border:1px solid #38bdf8;padding:4px 10px;border-radius:8px;color:#38bdf8">
          ${s.hg} x ${s.ag}
        </div>
      </div>
      <p style="font-size:12px;color:#cbd5e1;margin-bottom:14px;line-height:1.4">
        A jogada clama pela sua liderança! Escolha como o seu craque vai resolver o lance:
      </p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
        ${options.map(opt => `
          <button type="button" class="btn-craque-decision-opt" data-opt-id="${opt.id}" style="background:rgba(30,41,59,0.85);border:1px solid ${opt.color};padding:12px;border-radius:10px;text-align:left;cursor:pointer;transition:all 0.15s ease">
            <div style="font-size:13px;font-weight:900;color:#fff;margin-bottom:3px">${opt.icon} ${opt.title}</div>
            <div style="font-size:10px;color:#94a3b8;margin-bottom:6px">${opt.desc}</div>
            <div style="font-size:11px;font-weight:900;color:${opt.color}">Chance estimada: ${opt.chance}%</div>
          </button>
        `).join('')}
      </div>
      <div style="text-align:center">
        <button type="button" id="btnCancelCraqueDecision" style="background:none;border:none;color:#64748b;font-size:11px;cursor:pointer;text-decoration:underline">
          Deixar a jogada correr normalmente
        </button>
      </div>
    </div>
  `;

  container.appendChild(overlay);

  overlay.querySelectorAll('.btn-craque-decision-opt').forEach(btn => {
    btn.onclick = () => {
      const optId = btn.getAttribute('data-opt-id');
      const opt = options.find(o => o.id === optId);
      overlay.remove();
      s.craqueDecisionActive = false;
      resolveCraqueDecision(s, userAth, opt);
    };
  });

  const btnCancel = overlay.querySelector('#btnCancelCraqueDecision');
  if (btnCancel) {
    btnCancel.onclick = () => {
      overlay.remove();
      s.craqueDecisionActive = false;
      s.paused = false;
    };
  }
}
window.triggerCraqueDecisionMoment = triggerCraqueDecisionMoment;

function resolveCraqueDecision(s, userAth, opt) {
  if (!s || !userAth || !opt) {
    if (s) s.paused = false;
    return;
  }
  const isHome = userAth.team === 'home';
  const oppGk = (isHome ? s.awayPlayers : s.homePlayers).find(p => p.isGK) || { name: 'Goleiro' };
  const roll = Math.random() * 100;
  const isSuccess = roll <= opt.chance;
  const curMin = s.minute || 1;

  if (opt.id === 'placed_shot' || opt.id === 'power_shot' || opt.id === 'long_shot') {
    userAth.shots = (userAth.shots || 0) + 1;
    if (isHome) s.stats.shotsH = (s.stats.shotsH || 0) + 1;
    else s.stats.shotsA = (s.stats.shotsA || 0) + 1;

    if (isSuccess) {
      if (isHome) s.hg++; else s.ag++;
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'gol',
        playerId: userAth.id || userAth.careerPlayerId,
        scorer: userAth.fullName || userAth.name,
        text: `⚽ GOOOOOOL DO CRAQUE! ${userAth.fullName || userAth.name} executa um ${opt.title.toLowerCase()} indefensável e estufa as redes no ângulo!`
      });
      userAth.matchRating = Math.min(10.0, +(Number(userAth.matchRating || 6.5) + 0.8).toFixed(1));
      userAth.goals = (userAth.goals || 0) + 1;
      if (typeof showLiveBalloon === 'function') showLiveBalloon(userAth.x, userAth.y, '⚽ GOOOOOL!', '#22c55e');
      if (typeof showLiveBanner === 'function') showLiveBanner(`⚽ GOOOOOOL DE ${userAth.fullName || userAth.name}!`, 'goal', 4000);
      if (window.afmAudio) window.afmAudio.playSFX('goal_cheer');
    } else {
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'shot',
        text: `🧤 QUASE! ${userAth.fullName || userAth.name} arrisca ${opt.title.toLowerCase()}, mas ${oppGk.name} faz uma grande defesa!`
      });
      userAth.matchRating = Math.min(10.0, +(Number(userAth.matchRating || 6.5) + 0.2).toFixed(1));
      if (typeof showLiveBalloon === 'function') showLiveBalloon(userAth.x, userAth.y, '🧤 DEFESA DO GOLEIRO!', '#38bdf8');
    }
  } else if (opt.id === 'assist_pass' || opt.id === 'long_counter') {
    const companions = (isHome ? s.homePlayers : s.awayPlayers).filter(p => p !== userAth && !p.isGK && !p.redCard);
    const companion = companions[Math.floor(Math.random() * companions.length)] || { name: 'Companheiro' };

    if (isSuccess) {
      if (isHome) s.hg++; else s.ag++;
      if (isHome) s.stats.shotsH = (s.stats.shotsH || 0) + 1;
      else s.stats.shotsA = (s.stats.shotsA || 0) + 1;
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'gol',
        playerId: companion.id,
        relatedPlayerId: userAth.id || userAth.careerPlayerId,
        scorer: companion.name,
        assist: userAth.fullName || userAth.name,
        text: `⚽ GOL DO ${userAth.clubId || (isHome ? s.home : s.away)}! Assistência mágica de ${userAth.fullName || userAth.name} para a finalização certeira de ${companion.name}!`
      });
      userAth.matchRating = Math.min(10.0, +(Number(userAth.matchRating || 6.5) + 0.6).toFixed(1));
      userAth.assists = (userAth.assists || 0) + 1;
      if (typeof showLiveBanner === 'function') showLiveBanner(`🎯 ASSISTÊNCIA DE ${userAth.name}!`, 'goal', 3500);
      if (window.afmAudio) window.afmAudio.playSFX('goal_cheer');
    } else {
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'foul',
        text: `🛡️ A zaga adversária antecipou o passe de ${userAth.name} e cortou o perigo.`
      });
      userAth.matchRating = Math.min(10.0, +(Number(userAth.matchRating || 6.5) + 0.1).toFixed(1));
    }
  } else if (opt.id === 'dribble_box' || opt.id === 'shield_ball') {
    if (isSuccess) {
      userAth.x = clamp(userAth.x + (isHome ? 12 : -12), 4, 96);
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'sub',
        text: `⚡ DRIBLE DESCONCERTANTE! ${userAth.fullName || userAth.name} limpa o lance com categoria e avança livre!`
      });
      userAth.matchRating = Math.min(10.0, +(Number(userAth.matchRating || 6.5) + 0.4).toFixed(1));
      if (typeof showLiveBalloon === 'function') showLiveBalloon(userAth.x, userAth.y, '⚡ QUE DRIBLE!', '#f59e0b');
    } else {
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'sub',
        text: `🛡️ O marcador travou a arrancada de ${userAth.name} e afastou o perigo.`
      });
    }
  } else if (opt.id === 'tackle_clean') {
    if (isSuccess) {
      if (isHome) s.stats.tacklesH = (s.stats.tacklesH || 0) + 1;
      else s.stats.tacklesA = (s.stats.tacklesA || 0) + 1;
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'sub',
        text: `🛡️ DESARME MONSTRUOSO! ${userAth.fullName || userAth.name} dá o bote limpo e retoma a posse!`
      });
      userAth.matchRating = Math.min(10.0, +(Number(userAth.matchRating || 6.5) + 0.4).toFixed(1));
      s.ball.carrier = userAth;
      if (typeof showLiveBalloon === 'function') showLiveBalloon(userAth.x, userAth.y, '🛡️ DESARME!', '#10b981');
    } else {
      s.events = s.events || [];
      s.events.unshift({
        min: curMin,
        type: 'foul',
        text: `⚠️ Falta cometida por ${userAth.name} ao tentar o bote na intermediária.`
      });
    }
  }

  if (typeof updateScoreDisplay === 'function') updateScoreDisplay();
  if (typeof updateLiveSidebarEvents === 'function') updateLiveSidebarEvents();
  s.paused = false;
}
window.resolveCraqueDecision = resolveCraqueDecision;

function showCraqueLiveStatusModal(s = liveMatchState) {
  if (!s) return;
  const userIsHome = (typeof norm === 'function' ? norm(s.home) === norm(state?.club) : s.home === state?.club);
  const myTeam = userIsHome ? s.homePlayers : s.awayPlayers;
  const ath = (myTeam || []).find(p => p.isControlledAthlete) || (state?.squad || []).find(p => String(p.id) === String(state?.controlledPlayerId));
  if (!ath) return;

  const container = document.getElementById('matchModalContainer') || document.body;
  let modal = document.getElementById('craqueLiveStatusModal');
  if (modal) modal.remove();

  modal = document.createElement('div');
  modal.id = 'craqueLiveStatusModal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:100060;background:rgba(10,15,29,0.85);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:16px;animation:fadeInCraque 0.2s ease-out;';

  const rating = Number(ath.matchRating || 6.5).toFixed(1);
  const goals = Number(ath.goals || 0);
  const assists = Number(ath.assists || 0);
  const shots = Number(ath.shots || ath.fin || 0);
  const stam = Math.round(Number(ath.stamina || 100));
  const normPos = normalizePlayerPositionCode(ath.pos || 'ST');

  const goalsDone = goals >= 1;
  const ratingDone = Number(rating) >= 7.0;
  const passDone = (s.stats?.passAccH || 82) >= 75;

  modal.innerHTML = `
    <div style="background:#0f172a;border:2px solid #10b981;box-shadow:0 0 30px rgba(16,185,129,0.35);border-radius:16px;max-width:500px;width:100%;padding:20px;color:#fff;font-family:'Inter',sans-serif;position:relative">
      <div style="display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:12px;margin-bottom:14px">
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-size:26px">⭐</span>
          <div>
            <div style="font-size:16px;font-weight:900;color:#6ee7b7">${esc(ath.fullName || ath.name)}</div>
            <div style="font-size:11px;color:#94a3b8">#${ath.num || 10} · ${normPos} · ${esc(state?.club || '')}</div>
          </div>
        </div>
        <div style="text-align:right">
          <div style="font-size:20px;font-weight:900;color:#facc15">${rating}</div>
          <div style="font-size:10px;color:#94a3b8">NOTA AO VIVO</div>
        </div>
      </div>

      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:14px">
        <div style="background:rgba(30,41,59,0.7);padding:8px 4px;border-radius:8px;text-align:center">
          <div style="font-size:10px;color:#94a3b8">⚽ GOLS</div>
          <div style="font-size:15px;font-weight:900;color:#22c55e">${goals}</div>
        </div>
        <div style="background:rgba(30,41,59,0.7);padding:8px 4px;border-radius:8px;text-align:center">
          <div style="font-size:10px;color:#94a3b8">🎯 ASSIST</div>
          <div style="font-size:15px;font-weight:900;color:#38bdf8">${assists}</div>
        </div>
        <div style="background:rgba(30,41,59,0.7);padding:8px 4px;border-radius:8px;text-align:center">
          <div style="font-size:10px;color:#94a3b8">🚀 CHUTES</div>
          <div style="font-size:15px;font-weight:900;color:#f59e0b">${shots}</div>
        </div>
        <div style="background:rgba(30,41,59,0.7);padding:8px 4px;border-radius:8px;text-align:center">
          <div style="font-size:10px;color:#94a3b8">⚡ FÔLEGO</div>
          <div style="font-size:15px;font-weight:900;color:#facc15">${stam}%</div>
        </div>
        <div style="background:rgba(30,41,59,0.7);padding:8px 4px;border-radius:8px;text-align:center">
          <div style="font-size:10px;color:#94a3b8">STATUS</div>
          <div style="font-size:11px;font-weight:900;color:#10b981">${ath.wasStarter ? 'Titular' : 'Em Campo'}</div>
        </div>
      </div>

      <div style="margin-bottom:14px">
        <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px">
          <span style="color:#94a3b8">Desgaste Físico:</span>
          <span style="font-weight:800;color:${stam > 50 ? '#10b981' : '#ef4444'}">${stam}% Restante</span>
        </div>
        <div style="background:#1e293b;border-radius:6px;height:8px;overflow:hidden">
          <div style="width:${stam}%;height:100%;background:linear-gradient(90deg, #10b981, #facc15)"></div>
        </div>
      </div>

      <div style="background:rgba(30,41,59,0.6);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:12px;margin-bottom:16px">
        <div style="font-size:11px;font-weight:900;color:#38bdf8;margin-bottom:8px">📋 METAS DO TREINADOR NA PARTIDA:</div>
        <div style="display:flex;flex-direction:column;gap:6px;font-size:11px">
          <div style="color:${goalsDone ? '#10b981' : '#94a3b8'}">
            ${goalsDone ? '✅' : '⏳'} Participar de 1 gol (Marcado ou Assistência)
          </div>
          <div style="color:${ratingDone ? '#10b981' : '#94a3b8'}">
            ${ratingDone ? '✅' : '⏳'} Obter nota média individual de 7.0+ (Atual: ${rating})
          </div>
          <div style="color:${passDone ? '#10b981' : '#94a3b8'}">
            ${passDone ? '✅' : '⏳'} Manter precisão de passes da equipe acima de 75%
          </div>
        </div>
      </div>

      <button type="button" id="btnCloseCraqueLiveStatus" style="width:100%;background:#10b981;color:#000;font-weight:900;padding:10px;border-radius:8px;border:none;cursor:pointer;font-size:12px">
        VOLTAR AO JOGO
      </button>
    </div>
  `;

  container.appendChild(modal);

  const btnClose = modal.querySelector('#btnCloseCraqueLiveStatus');
  if (btnClose) {
    btnClose.onclick = () => modal.remove();
  }
}
window.showCraqueLiveStatusModal = showCraqueLiveStatusModal;

function bindLiveMatchEvents(){
  const s = liveMatchState;
  if(!s) return;

  // Toggle Pausa / Play
  const btnPlay = $('#btnLivePlayToggle');
  const overlay = $('#livePauseOverlay');
  const canvas = $('#liveMatchCanvas');

  function togglePlay(){
    if(s.phase === 'HALF_TIME'){
      $('#halftimeModalContainer')?.remove();
      if((state?.gameMode === 'player' || state?.playerCareerState) && s.shouldSubPlayerAtHalftime && typeof window.triggerPlayerCareerSubstitution === 'function'){
        window.triggerPlayerCareerSubstitution(s);
      }
      transitionMatchPhase('SECOND_HALF');
      s.phase = 'SECOND_HALF';
      s.minute = 45;
      s.timeSec = 2700;
      s.secAccumulator = 0;
      s.lastLoopTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      s.playing = true;
      if(btnPlay) btnPlay.textContent = '⏸';
      if(overlay) overlay.style.display = 'none';
      if(window.afmAudio){
        window.afmAudio.playSFX('whistle_start');
      } else {
        playWhistleSound();
      }
      return;
    }
    s.playing = !s.playing;
    if(btnPlay) btnPlay.textContent = s.playing ? '⏸' : '▶';
    if(overlay) overlay.style.display = s.playing ? 'none' : 'inline-flex';
  }

  if(btnPlay) btnPlay.onclick = togglePlay;
  if(overlay) overlay.onclick = togglePlay;
  if(canvas){
    canvas.onclick = () => {
      // Se estiver pausado, tocar no campo retoma a partida imediatamente
      if(!s.playing){
        togglePlay();
      }
    };
  }

  // Velocidades (1x, 2x, 5x, 10x, 20x, 40x)
  const speedButtons = [
    { speed: 1, btn: $('#btnLiveSpeed1') },
    { speed: 2, btn: $('#btnLiveSpeed2') },
    { speed: 5, btn: $('#btnLiveSpeed5') },
    { speed: 10, btn: $('#btnLiveSpeed10') },
    { speed: 20, btn: $('#btnLiveSpeed20') },
    { speed: 40, btn: $('#btnLiveSpeed40') },
  ];
  function setSpeed(v){
    const validSpeeds = [1, 2, 5, 10, 20, 40];
    const cleanSpeed = validSpeeds.includes(Number(v)) ? Number(v) : 1;
    s.speed = cleanSpeed;
    s.secAccumulator = 0;
    s.lastLoopTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    if(window.AFM_LiveMatchHUD) window.AFM_LiveMatchHUD.speedMultiplier = cleanSpeed;
    speedButtons.forEach(({ speed, btn }) => {
      if(!btn) return;
      btn.classList.toggle('active', speed === cleanSpeed);
    });
  }
  speedButtons.forEach(({ speed, btn }) => {
    if(btn) btn.onclick = () => setSpeed(speed);
  });

  // Botões de avanço e retrocesso sincronizados com a simulação real de minutos
  const btnRew10 = $('#btnLiveRewind10');
  if(btnRew10) btnRew10.onclick = () => {
    const minFloorSec = (s.minute || 0) * 60;
    s.timeSec = Math.max(minFloorSec, (s.timeSec || 0) - 10);
    s.liveSubSec = Math.max(0, (s.timeSec || 0) - minFloorSec);
    toast('Voltando 10 segundos!');
  };

  const btnFwd1 = $('#btnLiveForward1');
  if(btnFwd1) btnFwd1.onclick = () => {
    if(s.done || s.phase === 'HALF_TIME') return;
    const stop1H = Number(s.stoppage1H) || 2;
    const stop2H = Number(s.stoppage2H) || 4;
    const maxMin = s.phase === 'FIRST_HALF' ? (45 + stop1H) : (90 + stop2H);
    if(s.minute < maxMin){
      simulateMinute(s, s.minute + 1);
      s.timeSec = Math.min(maxMin * 60, s.minute * 60);
      s.liveSubSec = 0;
      s.secAccumulator = 0;
      updateScoreDisplay();
      updateLiveSidebarEvents();
    }
    toast('Avançando 1 minuto!');
  };

  // Botão Mexer no Time / Tática
  const btnTactics = $('#btnLiveTactics');
  if(btnTactics) btnTactics.onclick = () => {
    s.playing = false;
    if(btnPlay) btnPlay.textContent = '▶';
    if(overlay) overlay.style.display = 'inline-flex';
    openHalftimeModal(true);
  };

  // Pular para o Intervalo ou Iniciar 2º Tempo (Contextual)
  const btnSkipHalf = $('#btnLiveSkipHalf');
  if(btnSkipHalf) btnSkipHalf.onclick = () => {
    if(s.phase === 'FIRST_HALF'){
      simulateMatchSegment(s.minute, 45);
      s.timeSec = 2700;
      s.minute = 45;
      s.halftimeTriggered = true;
      transitionMatchPhase('HALF_TIME');
      s.playing = false;
      if(window.afmAudio){
        window.afmAudio.playSFX('whistle_halftime');
      } else {
        playWhistleSound();
      }
      s.events.unshift({ min: 45, type: 'whistle', text: `⏱ Fim do 1º tempo! ${s.home} ${s.hg} x ${s.ag} ${s.away}. As equipes descem para o vestiário.` });
      updateScoreDisplay();
      updateLiveSidebarEvents();
      renderLiveMatchModal();
      openHalftimeModal();
    } else if(s.phase === 'HALF_TIME'){
      $('#halftimeModalContainer')?.remove();
      if((state?.gameMode === 'player' || state?.playerCareerState) && s.shouldSubPlayerAtHalftime && typeof window.triggerPlayerCareerSubstitution === 'function'){
        window.triggerPlayerCareerSubstitution(s);
      }
      transitionMatchPhase('SECOND_HALF');
      s.phase = 'SECOND_HALF';
      s.minute = 45;
      s.timeSec = 2700;
      s.secAccumulator = 0;
      s.lastLoopTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      s.playing = true;
      if(window.afmAudio){
        window.afmAudio.playSFX('whistle_start');
      } else {
        playWhistleSound();
      }
      renderLiveMatchModal();
      toast('Bola rolando para a etapa complementar!');
    } else {
      toast('A primeira etapa da partida já foi encerrada!');
    }
  };

  // Simular até o fim
  const btnSkipEnd = $('#btnLiveSkipEnd');
  if(btnSkipEnd) btnSkipEnd.onclick = () => {
    simulateMatchSegment(s.minute, 90);
    s.timeSec = 5400;
    s.minute = 90;
    updateScoreDisplay();
    updateLiveSidebarEvents();
    finishLiveMatch();
  };

  // Som Ligar/Desligar
  const btnSound = $('#btnLiveSound');
  if(btnSound) btnSound.onclick = () => {
    s.soundMuted = !s.soundMuted;
    if(window.afmAudio){
      window.afmAudio.toggleCrowdAudio(!s.soundMuted);
      window.afmAudio.toggleSFXAudio(!s.soundMuted);
      if(s.soundMuted){
        window.afmAudio.stopCrowdAmbient();
      } else {
        if(!s.done) window.afmAudio.startCrowdAmbient(s.home, comp?.id);
      }
    }
    btnSound.textContent = s.soundMuted ? '🔇 MUDO' : '🔊 SOM';
    toast(s.soundMuted ? 'Áudio da partida desativado' : 'Áudio da partida ativado');
  };

  // Alternar entre Estádio 3D e Visão 2D
  const btn2D3D = $('#btnToggle2D3D');
  if(btn2D3D) btn2D3D.onclick = () => {
    s.renderMode = (s.renderMode === '2d') ? '3d' : '2d';
    toast(s.renderMode === '2d' ? '📐 Visão Tática 2D Ativada' : '🏟️ Estádio 3D Ativado');
    renderLiveMatchModal();
  };

  // Câmera Lateral, Bola e Gol
  const btnCamLat = $('#btnCamLateral');
  if(btnCamLat) btnCamLat.onclick = () => {
    s.cameraMode = 'lateral';
    if(s.camera) s.camera.mode = 'lateral';
    toast('🎥 Câmera Lateral / Visão Ampla Ativada');
    renderLiveMatchModal();
  };
  const btnCamBall = $('#btnCamBall');
  if(btnCamBall) btnCamBall.onclick = () => {
    s.cameraMode = 'ball';
    if(s.camera) s.camera.mode = 'ball';
    toast('⚽ Câmera Foco na Bola Ativada');
    renderLiveMatchModal();
  };
  const btnCamGoal = $('#btnCamGoal');
  if(btnCamGoal) btnCamGoal.onclick = () => {
    s.cameraMode = 'goal';
    if(s.camera) s.camera.mode = 'goal';
    toast('🥅 Câmera Foco no Gol Ativada');
    renderLiveMatchModal();
  };

  // Alternar Câmera de Transmissão (TV Dinâmica vs Panorâmica)
  const btnCam = $('#btnToggleLiveCam');
  if(btnCam){
    btnCam.onclick = () => {
      s.camera = s.camera || { mode: 'tv' };
      s.camera.mode = s.camera.mode === 'tv' ? 'wide' : 'tv';
      btnCam.textContent = s.camera.mode === 'tv' ? '🎥 TV Dinâmica' : '🏟️ Panorâmica';
      toast(s.camera.mode === 'tv' ? '🎥 Câmera de TV Ativada: seguindo o lance e a bola!' : '🏟️ Câmera Panorâmica Ativada: visão ampla do estádio');
    };
  }

  // Fechar
  const btnClose = $('#btnLiveClose');
  if(btnClose) btnClose.onclick = () => {
    if(s.done){
      finalizeMatchRound();
      return;
    }
    if(confirm('Deseja realmente sair da transmissão ao vivo e avançar a rodada?')){
      simulateMatchSegment(s.minute || 0, 90);
      s.minute = 90;
      s.timeSec = 5400;
      finishLiveMatch();
      finalizeMatchRound();
    }
  };

  const btnAdv = $('#btnLiveAdvanceRound');
  if(btnAdv) btnAdv.onclick = () => {
    finalizeMatchRound();
  };

  // Gritos da Beira do Campo (Melhoria 3)
  $$('.live-shout-btn').forEach(btn => {
    btn.onclick = () => {
      const type = btn.dataset.shout;
      playWhistleSound();
      s.coachShout = type;
      const desc = type === 'press'
        ? 'Professor gesticula na beira do gramado e manda adiantar as linhas com marcação alta!'
        : type === 'calm'
        ? 'Professor pede calma, valorização da posse de bola e paciência na armação.'
        : 'Professor fecha o bloco na entrada da área e aposta no contra-ataque em velocidade!';
      s.events.unshift({ min: Math.floor(s.timeSec/60), type: 'whistle', text: `🗣️ INSTRUÇÃO DO TREINADOR: ${desc}` });
      updateLiveSidebarEvents();
      showLiveBanner(`🗣️ BEIRA DO CAMPO: ${btn.textContent.trim()}!`, 'tactics', 3500);
      toast('Instrução repassada aos atletas em campo!');
    };
  });

  // COMANDOS DO CRAQUE: Ações em tempo real do atleta em campo (Modo Jogador)
  const isPlayerMode = Boolean(state?.gameMode === 'player' || state?.playerCareerState);
  if(isPlayerMode){
    const userIsHome = norm(s.home) === norm(state.club);
    const myTeam = userIsHome ? s.homePlayers : s.awayPlayers;
    const findMyAthlete = () => (myTeam || []).find(p => p.isControlledAthlete);

    const btnCall = $('#btnCraqueCallBall');
    if(btnCall){
      btnCall.onclick = () => {
        const ath = findMyAthlete();
        if(!ath) return toast('Aguarde sua entrada em campo para comandar as jogadas!');
        s.craqueCallBallUntil = Date.now() + 6000;
        if(s.ball && s.ball.carrier && s.ball.carrier.team === ath.team && s.ball.carrier !== ath){
          startLivePass(s, s.ball.carrier, ath, { logEvent: true, cooldownFrames: 30 });
          showLiveBanner('⚽ VOCÊ RECEBEU O PASSE!', 'tactics', 2500);
          toast('⚽ Companheiro tocou a bola para você!');
        } else {
          showLiveBanner('🗣️ PEDINDO A BOLA!', 'tactics', 2000);
          toast('🗣️ Você gesticulou pedindo a bola! Companheiros procurando o craque.');
        }
        if(s.ball && s.ball.carrier === ath && !s.craqueDecisionActive){
          triggerCraqueDecisionMoment(s, ath);
        }
      };
    }

    const btnShoot = $('#btnCraqueShoot');
    if(btnShoot){
      btnShoot.onclick = () => {
        const ath = findMyAthlete();
        if(!ath) return toast('Aguarde sua entrada em campo para finalizar a gol!');
        if(s.ball && s.ball.carrier === ath){
          triggerCraqueDecisionMoment(s, ath);
        } else {
          s.craqueCallBallUntil = Date.now() + 5000;
          showLiveBanner('🎯 PREPARADO PARA FINALIZAR!', 'tactics', 2000);
          toast('🎯 Preparado para o chute! Pedindo a bola na área...');
        }
      };
    }

    const btnSprint = $('#btnCraqueSprint');
    if(btnSprint){
      btnSprint.onclick = () => {
        const ath = findMyAthlete();
        if(!ath) return toast('Aguarde sua entrada em campo!');
        ath.stamina = Math.max(10, (ath.stamina || 100) - 2);
        const dir = ath.team === 'home' ? 1 : -1;
        ath.x = clamp((ath.x || 50) + dir * 8, 4, 96);
        showLiveBanner('⚡ ARRANCADA EXPLOSIVA!', 'tactics', 2000);
        toast('⚡ Arrancada em velocidade (+35%)! Infiltração aberta no ataque!');
      };
    }

    const btnPress = $('#btnCraquePress');
    if(btnPress){
      btnPress.onclick = () => {
        const ath = findMyAthlete();
        if(!ath) return toast('Aguarde sua entrada em campo!');
        if(s.ball){
          ath.x = clamp((ath.x * 0.6) + (s.ball.x * 0.4), 4, 96);
          ath.y = clamp((ath.y * 0.6) + (s.ball.y * 0.4), 4, 96);
          if(s.ball.carrier && s.ball.carrier.team !== ath.team && Math.hypot(ath.x - s.ball.carrier.x, ath.y - s.ball.carrier.y) < 12){
            if(Math.random() < 0.55){
              s.ball.carrier = ath;
              s.events = s.events || [];
              s.events.unshift({ min: s.minute || 1, type: 'sub', text: `🛡️ ROUBADA DE BOLA! ${ath.name} pressiona e recupera a posse no ataque!` });
              showLiveBalloon(ath.x, ath.y, '🛡️ BOLA RECUPERADA!', '#10b981');
            }
          }
        }
        showLiveBanner('🛡️ PRESSÃO NA MARCAÇÃO!', 'tactics', 2000);
        toast('🛡️ Você fechou os espaços e pressionou a saída adversária!');
      };
    }

    const btnStamina = $('#btnCraqueStaminaStatus');
    if(btnStamina){
      btnStamina.onclick = () => {
        showCraqueLiveStatusModal(s);
      };
    }
  }
}

// -------------------------------------------------------------
// BLINDAGEM PERMANENTE DE POSIÇÃO EXATA & COORDENADAS DO ATLETA (BE A PRO)
// -------------------------------------------------------------
function resolveCanonicalTacticalCodeForGroup(posGroup, rawPos = ''){
  const raw = String(rawPos || '').trim().toUpperCase();
  if(posGroup === 'GOL') return 'GK';
  if(posGroup === 'ZAG') return 'CB';
  if(posGroup === 'LAT') return (raw === 'LB' || raw === 'LE' || raw === 'LWB') ? 'LB' : (raw === 'RB' || raw === 'LD' || raw === 'RWB') ? 'RB' : 'RB';
  if(posGroup === 'VOL') return (raw === 'DM' || raw === 'CDM' || raw === 'VOL') ? 'DM' : 'CM';
  if(posGroup === 'MEI') return 'AM';
  if(posGroup === 'PON') return (raw === 'RW' || raw === 'PD' || raw === 'RM') ? 'RW' : 'LW';
  return 'ST'; // ATA, ST, CF, CA
}

function getCanonicalSlotProfileForGroup(posGroup, tacticalCode, isHomeSide){
  // Coordenadas base exatas por grupo posicional (Home ataca p/ direita x: 3.5 -> 96.5; Away ataca p/ esquerda x: 96.5 -> 3.5)
  let homeBaseX = 54.0, baseY = 50, depthRuns = 88, boxPresence = 92, shotTendency = 92, creativePassing = 68, halfSpaceOcc = 0, pressIntensity = 62, roleName = 'Advanced Forward';
  if(posGroup === 'GOL'){
    homeBaseX = 3.5; baseY = 50; depthRuns = 0; boxPresence = 0; shotTendency = 0; creativePassing = 40; pressIntensity = 10; roleName = 'Goalkeeper';
  } else if(posGroup === 'ZAG'){
    homeBaseX = 18.5; baseY = 38; depthRuns = 8; boxPresence = 20; shotTendency = 15; creativePassing = 50; pressIntensity = 65; roleName = 'Ball-Playing Defender';
  } else if(posGroup === 'LAT'){
    homeBaseX = 25.0; baseY = tacticalCode === 'LB' ? 14 : 86; depthRuns = 55; boxPresence = 25; shotTendency = 30; creativePassing = 68; pressIntensity = 68; roleName = 'Wing-Back';
  } else if(posGroup === 'VOL'){
    homeBaseX = tacticalCode === 'DM' ? 30.0 : 36.0; baseY = 50; depthRuns = tacticalCode === 'DM' ? 22 : 45; boxPresence = 35; shotTendency = 42; creativePassing = 78; pressIntensity = 75; roleName = tacticalCode === 'DM' ? 'Deep-Lying Playmaker' : 'Box-to-Box';
  } else if(posGroup === 'MEI'){
    homeBaseX = 43.5; baseY = 50; depthRuns = 70; boxPresence = 68; shotTendency = 78; creativePassing = 92; halfSpaceOcc = 1; pressIntensity = 58; roleName = 'Playmaker';
  } else if(posGroup === 'PON'){
    homeBaseX = 49.0; baseY = tacticalCode === 'RW' ? 82 : 18; depthRuns = 85; boxPresence = 80; shotTendency = 84; creativePassing = 78; halfSpaceOcc = 1; pressIntensity = 62; roleName = 'Inside Forward';
  } else {
    // ATA / ST / CF: Centroavante de referência na linha mais avançada do time (sempre à frente de volantes/meias)!
    homeBaseX = 54.0; baseY = 50; depthRuns = 92; boxPresence = 95; shotTendency = 92; creativePassing = 68; halfSpaceOcc = 0; pressIntensity = 62; roleName = 'Advanced Forward';
  }
  const baseX = isHomeSide ? homeBaseX : Number((100 - homeBaseX).toFixed(1));
  return { baseX, baseY, depthRuns, boxPresence, shotTendency, creativePassing, halfSpaceOcc, pressIntensity, roleName };
}

function syncControlledAthletePitchSlotAndCoords(s = liveMatchState, snapCurrentPos = false){
  const st = (typeof state !== 'undefined' && state) || (typeof window !== 'undefined' && window.state);
  if(!s || !st || !(st.gameMode === 'player' || st.playerCareerState)) return false;
  const athlete = ((typeof window.getControlledPlayer === 'function' ? window.getControlledPlayer(st) : null) ||
                   (st.squad || []).find(p => String(p.id) === String(st.controlledPlayerId) || p.isControlled));
  if(!athlete) return false;

  const userIsHome = (typeof norm === 'function' ? norm(s.home) === norm(st.club) : (s.home === st.club));
  const myTeam = userIsHome ? s.homePlayers : s.awayPlayers;
  if(!Array.isArray(myTeam) || !myTeam.length) return false;

  const pitchEntity = myTeam.find(p => p && (p.isControlledAthlete || (athlete.id != null && (String(p.id) === String(athlete.id) || String(p.careerPlayerId) === String(athlete.id)))));
  if(!pitchEntity) return false;

  const rawNatural = athlete.pos || athlete.position || st.playerCareerState?.position || 'ATA';
  const posGroup = window.AFM_PlayerEngine?.normalizePlayerPosGroup
    ? window.AFM_PlayerEngine.normalizePlayerPosGroup(rawNatural)
    : (['GOL','GK'].includes(String(rawNatural).toUpperCase()) ? 'GOL' : 'ATA');
  const tacticalCode = resolveCanonicalTacticalCodeForGroup(posGroup, rawNatural);
  const slotProfile = getCanonicalSlotProfileForGroup(posGroup, tacticalCode, userIsHome);

  // Proteção absoluta: atleta de linha JAMAIS fica no slot 0 / GK
  if(posGroup !== 'GOL' && (pitchEntity.isGK || myTeam[0] === pitchEntity)){
    const swapIdx = myTeam.findIndex((p, idx) => idx > 0 && p && !p.isGK);
    if(swapIdx > 0){
      const other = myTeam[swapIdx];
      [myTeam[0], myTeam[swapIdx]] = [myTeam[swapIdx], myTeam[0]];
      other.isGK = true;
      other.pos = 'GK';
      other.baseX = userIsHome ? 3.5 : 96.5;
      other.baseY = 50;
    }
  }

  // Sincroniza atributos reais efetivos do atleta criado (chuteira + patrocínio + staff)
  const effAttrs = window.AFM_PlayerEngine?.getPlayerEffectiveAttributes
    ? window.AFM_PlayerEngine.getPlayerEffectiveAttributes(st, athlete)
    : (athlete.attributes || {});
  const effOvr = window.AFM_PlayerEngine?.calculatePlayerOverall
    ? window.AFM_PlayerEngine.calculatePlayerOverall(effAttrs, rawNatural)
    : (Number(athlete.ovr || athlete.overall || st.playerCareerState?.overall) || 45);

  pitchEntity.isControlledAthlete = true;
  pitchEntity.naturalPos = rawNatural;
  pitchEntity.posGroup = posGroup;
  pitchEntity.pos = tacticalCode;
  pitchEntity.isGK = (posGroup === 'GOL');
  pitchEntity.canScore = (posGroup !== 'GOL');
  pitchEntity.canShoot = (posGroup !== 'GOL');
  pitchEntity.canAssist = true;
  pitchEntity.overall = effOvr;
  pitchEntity.ovr = effOvr;
  pitchEntity.roleName = slotProfile.roleName;
  pitchEntity.depthRuns = slotProfile.depthRuns;
  pitchEntity.boxPresence = slotProfile.boxPresence;
  pitchEntity.shotTendency = slotProfile.shotTendency;
  pitchEntity.creativePassing = slotProfile.creativePassing;
  pitchEntity.halfSpaceOcc = slotProfile.halfSpaceOcc;
  pitchEntity.pressIntensity = slotProfile.pressIntensity;
  pitchEntity.baseX = slotProfile.baseX;
  pitchEntity.baseY = slotProfile.baseY;
  pitchEntity.lockedCanonicalBaseX = slotProfile.baseX;
  pitchEntity.lockedCanonicalBaseY = slotProfile.baseY;

  // Se outro NPC ficou com baseX/baseY colidente na mesma vaga após substituição, desloca o NPC suavemente para manter separação tática
  myTeam.forEach(mate => {
    if(!mate || mate === pitchEntity || mate.isGK) return;
    if(Math.abs((Number(mate.baseX) || 50) - slotProfile.baseX) < 3 && Math.abs((Number(mate.baseY) || 50) - slotProfile.baseY) < 6){
      mate.baseY = slotProfile.baseY <= 50 ? Math.min(82, slotProfile.baseY + 18) : Math.max(18, slotProfile.baseY - 18);
    }
  });
  pitchEntity.attrs = {
    ...(pitchEntity.attrs || {}),
    pace: Number(effAttrs.vel ?? effAttrs.pace) || effOvr,
    acceleration: Number(effAttrs.vel ?? effAttrs.pace) || effOvr,
    sprintSpeed: Number(effAttrs.vel ?? effAttrs.pace) || effOvr,
    shooting: Number(effAttrs.chu ?? effAttrs.shooting) || effOvr,
    finishing: Math.min(99, (Number(effAttrs.chu ?? effAttrs.shooting) || effOvr) + (posGroup === 'ATA' ? 4 : 2)),
    passing: Number(effAttrs.pas ?? effAttrs.passing) || effOvr,
    vision: Number(effAttrs.pas ?? effAttrs.passing) || effOvr,
    shortPassing: Number(effAttrs.pas ?? effAttrs.passing) || effOvr,
    dribbling: Number(effAttrs.dri ?? effAttrs.dribbling) || effOvr,
    ballControl: Number(effAttrs.dri ?? effAttrs.dribbling) || effOvr,
    defending: Number(effAttrs.def ?? effAttrs.defending) || effOvr,
    tackling: Number(effAttrs.def ?? effAttrs.defending) || effOvr,
    interceptions: Number(effAttrs.def ?? effAttrs.defending) || effOvr,
    strength: Number(effAttrs.fis ?? effAttrs.physical) || effOvr,
    composure: Math.min(99, Math.max(50, effOvr + 5)),
    positioning: Math.min(99, Math.max(50, effOvr + 6)),
    reactions: Math.min(99, Math.max(50, effOvr + 5))
  };

  if(snapCurrentPos || !Number.isFinite(Number(pitchEntity.x))){
    pitchEntity.x = slotProfile.baseX;
    pitchEntity.y = slotProfile.baseY;
    pitchEntity.targetX = slotProfile.baseX;
    pitchEntity.targetY = slotProfile.baseY;
  }
  return true;
}
if(typeof window !== 'undefined') window.syncControlledAthletePitchSlotAndCoords = syncControlledAthletePitchSlotAndCoords;

// -------------------------------------------------------------
// SUBSTITUIÇÃO DO ATLETA CONTROLADO NO MODO JOGADOR (BE A PRO)
// -------------------------------------------------------------
function triggerPlayerCareerSubstitution(s = liveMatchState){
  const st = (typeof state !== 'undefined' && state) || (typeof window !== 'undefined' && window.state);
  if(!s || !st) return false;
  const isPlayerMode = Boolean(st.gameMode === 'player' || st.playerCareerState || st.controlledPlayerId);
  if(!isPlayerMode) return false;
  if(Number(s.subsLeft) <= 0 || s.playerCareerAvailableForMatch === false) return false;

  const athlete = ((typeof window.getControlledPlayer === 'function' ? window.getControlledPlayer(st) : null) ||
                   (st.squad || []).find(p => String(p.id) === String(st.controlledPlayerId)) ||
                   (st.squad || [])[0]);
  if(!athlete) return false;

  const userIsHome = (typeof norm === 'function' ? norm(s.home) === norm(st.club) : (s.home === st.club));
  const myTeam = userIsHome ? s.homePlayers : s.awayPlayers;
  if(!Array.isArray(myTeam) || myTeam.length === 0) return false;

  // Verifica se o atleta já está em campo (garantindo sincronia de coordenadas!)
  const alreadyOnPitch = myTeam.find(p => p.isControlledAthlete || (athlete.id && (String(p.id) === String(athlete.id) || String(p.careerPlayerId) === String(athlete.id))) || (athlete.key && p.key === athlete.key));
  if(alreadyOnPitch){
    alreadyOnPitch.isControlledAthlete = true;
    s.controlledAthleteOnPitch = true;
    syncControlledAthletePitchSlotAndCoords(s, false);
    return true;
  }

  // Normaliza grupo posicional PT/EN (ATA == ST/CF, PON == LW/RW, MEI == AM, VOL == DM/CM, LAT == LB/RB, ZAG == CB, GOL == GK)
  const rawAthletePos = athlete.pos || athlete.position || st.playerCareerState?.position || 'ATA';
  const normGroupFn = window.AFM_PlayerEngine?.normalizePlayerPosGroup || (p => String(p || 'ATA').toUpperCase());
  const athleteGroup = normGroupFn(rawAthletePos);

  let subIndex = -1;
  if(athleteGroup === 'GOL'){
    subIndex = myTeam.findIndex(p => p && p.isGK);
    if(subIndex < 0) subIndex = 0;
  } else {
    const outfieldPlayers = myTeam.map((p, idx) => ({ p, idx, group: normGroupFn(p.naturalPos || p.pos) })).filter(item => !item.p.isGK && item.idx !== 0);
    // 1º: Prioridade absoluta para companheiro do MESMO grupo posicional (ex: ATA entra no lugar de ST/CF!)
    const exactGroupMatches = outfieldPlayers.filter(item => item.group === athleteGroup);
    if(exactGroupMatches.length){
      exactGroupMatches.sort((a, b) => (Number(a.p.stamina) || 100) - (Number(b.p.stamina) || 100));
      subIndex = exactGroupMatches[0].idx;
    } else {
      // 2º: Grupo adjacente compatível (ex: PON <-> ATA/MEI, MEI <-> VOL/ATA) para manter equilíbrio tático do time
      const adjacentMap = {
        ATA: ['PON', 'MEI'],
        PON: ['ATA', 'MEI'],
        MEI: ['PON', 'VOL', 'ATA'],
        VOL: ['MEI', 'LAT', 'ZAG'],
        LAT: ['VOL', 'ZAG', 'PON'],
        ZAG: ['VOL', 'LAT']
      };
      const adjGroups = adjacentMap[athleteGroup] || [];
      const adjMatches = outfieldPlayers.filter(item => adjGroups.includes(item.group));
      if(adjMatches.length){
        adjMatches.sort((a, b) => (Number(a.p.stamina) || 100) - (Number(b.p.stamina) || 100));
        subIndex = adjMatches[0].idx;
      } else {
        outfieldPlayers.sort((a, b) => (Number(a.p.stamina) || 100) - (Number(b.p.stamina) || 100));
        subIndex = outfieldPlayers[0] ? outfieldPlayers[0].idx : (myTeam.length - 1);
      }
    }
  }

  const subbedOut = myTeam[subIndex];
  if(!subbedOut) return false;

  const outName = subbedOut.name || 'Titular';
  const outNum = subbedOut.num || 11;
  const replacedPlayerId = subbedOut.id;
  const athleteName = athlete.name || st.playerCareerState?.athleteName || 'Atleta';
  const athleteNum = athlete.number || st.playerCareerState?.shirtNumber || 10;
  const curMin = Math.max(1, Number(s.minute) || 45);
  const tacticalCode = resolveCanonicalTacticalCodeForGroup(athleteGroup, rawAthletePos);

  subbedOut.id = athlete.id;
  subbedOut.name = athleteName;
  subbedOut.shortName = athleteName.split(' ').pop() || athleteName;
  subbedOut.fullName = athlete.fullName || athleteName;
  subbedOut.num = athleteNum;
  subbedOut.naturalPos = rawAthletePos;
  subbedOut.pos = tacticalCode;
  subbedOut.isGK = (athleteGroup === 'GOL');
  subbedOut.ovr = athlete.ovr || 40;
  subbedOut.overall = athlete.ovr || 40;
  subbedOut.stamina = 100;
  subbedOut.careerPlayerId = athlete.id;
  subbedOut.enteredMinute = curMin;
  subbedOut.wasStarter = false;
  subbedOut.isControlledAthlete = true;
  subbedOut.canScore = (athleteGroup !== 'GOL');
  subbedOut.canShoot = (athleteGroup !== 'GOL');

  // Posiciona imediatamente na coordenada exata da posição natural do atleta!
  syncControlledAthletePitchSlotAndCoords(s, true);

  if(s.subsLeft > 0) s.subsLeft--;

  s.events = s.events || [];
  s.events.unshift({
    min: curMin,
    type: 'sub',
    playerId: athlete.id,
    replacedPlayerId,
    text: `🟦 SUBSTITUIÇÃO NO ${userIsHome ? s.home : s.away}! Sai ${outName} (#${outNum}) e entra o jovem craque ${athleteName} (#${athleteNum}) na posição ${rawAthletePos}!`
  });

  s.controlledAthleteOnPitch = true;
  if(typeof updateScoreDisplay === 'function') updateScoreDisplay();
  if(typeof updateLiveSidebarEvents === 'function') updateLiveSidebarEvents();
  if(typeof showLiveBanner === 'function') showLiveBanner(`⚽ VOCÊ ENTROU EM CAMPO (${rawAthletePos})! ${athleteName} (#${athleteNum})`, 'tactics', 4000);
  if(typeof toast === 'function') toast(`⚽ Você entrou em campo aos ${curMin}' (${rawAthletePos})!`);
  return true;
}
window.triggerPlayerCareerSubstitution = triggerPlayerCareerSubstitution;

// -------------------------------------------------------------
// MODAL DE INTERVALO & SUBSTITUIÇÕES COM CANSAÇO (SCREENSHOT 4)
// -------------------------------------------------------------
let halftimeSelectedStarterKey = null;

function openHalftimeModal(isQuickTactics = false){
  const s = liveMatchState;
  if(!s) return;
  if((state?.gameMode === 'player' || state?.playerCareerState) && window.AFM_PlayerMode && typeof window.AFM_PlayerMode.openPlayerCareerHalftimeModal === 'function'){
    return window.AFM_PlayerMode.openPlayerCareerHalftimeModal(isQuickTactics);
  }
  const userIsHome = norm(s.home) === norm(state.club);

  let modalEl = $('#halftimeModalContainer');
  if(!modalEl){
    modalEl = document.createElement('div');
    modalEl.id = 'halftimeModalContainer';
    document.body.appendChild(modalEl);
  }

  const scoreText = s.hg === s.ag
    ? 'empatando'
    : (userIsHome ? (s.hg > s.ag ? 'vencendo' : 'perdendo') : (s.ag > s.hg ? 'vencendo' : 'perdendo'));

  const userStarters = (userIsHome ? s.homePlayers : s.awayPlayers);
  const rosterKeeper = state.squad.find(p => isGoalkeeperPosition(p.pos) && userStarters.some(mp => mp.key === playerKey(p)));
  const halftimeKeeper = (rosterKeeper && userStarters.find(mp => mp.key === playerKey(rosterKeeper))) || userStarters.find(p => p.isGK || isGoalkeeperPosition(p.pos));
  if(halftimeKeeper){
    const keeperIndex = userStarters.indexOf(halftimeKeeper);
    // Preserva a escalação escolhida pelo treinador sem reordenar arbitrariamente
    userStarters.forEach(matchPlayer => {
      const rosterPlayer = state.squad.find(p => playerKey(p) === matchPlayer.key);
      matchPlayer.isGK = matchPlayer === halftimeKeeper;
      if(matchPlayer.isGK){ matchPlayer.pos = 'GK'; matchPlayer.canScore = false; matchPlayer.canShoot = false; }
      else if(rosterPlayer && rosterPlayer.pos){ matchPlayer.pos = rosterPlayer.pos; matchPlayer.canScore = true; matchPlayer.canShoot = true; }
    });
    const horizontalSlots = window.HORIZONTAL_FORMATIONS?.[state.formation || '4-3-3'] || window.HORIZONTAL_FORMATIONS?.['4-3-3'];
    if(horizontalSlots){
      userStarters.forEach((matchPlayer, idx) => {
        const slot = horizontalSlots[idx];
        if(!slot) return;
        const targetX = userIsHome ? Number(slot.x) : 100 - Number(slot.x);
        const targetY = Number(slot.y);
        matchPlayer.baseX = targetX; matchPlayer.baseY = targetY;
        matchPlayer.targetX = targetX; matchPlayer.targetY = targetY;
      });
    }
  }
  const starterKeys = userStarters.map(p => p.key);
  s.subbedOut = Array.isArray(s.subbedOut) ? s.subbedOut : [];
  const userBench = state.squad.filter(p => !starterKeys.includes(playerKey(p)) && !s.subbedOut.includes(playerKey(p)));
  const currentForm = state.formation || '4-3-3';
  const formDef = FORMATIONS[currentForm] || FORMATIONS['4-3-3'];

  const speechDescriptions = {
    'Manter a calma': '🛡️ <b>Efeito em Campo:</b> Passes mais calmos (+35% precisão), -50% faltas desnecessárias e preservação de fôlego (-15% de desgaste).',
    'Cobrar o time': '⚡ <b>Efeito em Campo:</b> Postura enérgica, busca rápida pelo gol (+30% chutes ao gol) e maior entrega (+10% desgaste).',
    'Elogiar o time': '⭐ <b>Efeito em Campo:</b> Moral no auge (+20% pontaria nas finalizações e defesas acrobáticas do goleiro).',
    'Pedir raça': '🔥 <b>Efeito em Campo:</b> Intensidade máxima em divididas (+40% desarmes vencidos), marcação colada e desgaste acelerado (+25%).'
  };

  const currentPosture = (userIsHome ? s.homePosture : s.awayPosture) || 'Equilibrada';
  const postureDescriptions = {
    'Retranca': '🧱 <b>Efeito em Campo:</b> Linhas recuadas até a grande área (-16m), tranca os espaços e poupa físico (-25% desgaste).',
    'Defensiva': '🛡️ <b>Efeito em Campo:</b> Linhas baixas (-9m), proteção à zaga e escape veloz nos contra-ataques.',
    'Equilibrada': '⚖️ <b>Efeito em Campo:</b> Posicionamento base (0m), jogo cadenciado e equilíbrio entre ataque e defesa.',
    'Ofensiva': '⚔️ <b>Efeito em Campo:</b> Linhas adiantadas (+13m), laterais no apoio e maior presença no ataque (+25% desgaste).',
    'Pressão total': '🔥 <b>Efeito em Campo:</b> Blitz no campo adversário (+23m), abafa na saída de bola e desgaste físico máximo (+70%).'
  };

  modalEl.innerHTML = `
    <div class="halftime-overlay">
      <div class="halftime-card">
        <!-- HEADER COMPACTO -->
        <div class="halftime-header" style="padding-bottom:4px">
          <div class="halftime-title-group">
            <h2 style="font-size:16px;font-weight:900;letter-spacing:1px;margin:0">${isQuickTactics ? 'SUBSTITUIÇÃO E TÁTICA' : 'INTERVALO'}</h2>
            <div class="sub" style="font-size:10px;font-weight:800;color:#c084fc">VESTIÁRIO DO ${esc(state.club.toUpperCase())} · <span style="color:#facc15;font-weight:700">${scoreText}</span></div>
          </div>
          <div class="halftime-scoreboard-badge" style="padding:3px 10px;background:rgba(0,0,0,0.6);border:1px solid rgba(255,255,255,0.15);border-radius:8px">
            ${clubBadge(s.home, 22)}
            <span style="font-size:15px;font-weight:900;letter-spacing:2px;margin:0 6px">${s.hg} - ${s.ag}</span>
            ${clubBadge(s.away, 22)}
          </div>
        </div>

        <!-- SEÇÃO PRELEÇÃO E POSTURA TÁTICA COMPACTA -->
        <div class="halftime-tactics-bar" style="display:flex;gap:6px;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.02);padding:4px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.06);flex-shrink:0;flex-wrap:wrap">
          <div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap">
            <span style="font-size:10px;font-weight:900;color:#a855f7">🗣️ PRELEÇÃO:</span>
            <div class="halftime-speech-row" style="display:flex;gap:3px;flex-wrap:wrap">
              ${['Manter a calma', 'Cobrar o time', 'Elogiar o time', 'Pedir raça'].map(t => `
                <button class="btn-halftime-speech ${s.prelecao === t ? 'active' : ''}" data-speech="${t}" style="font-size:10px;font-weight:800;padding:2px 7px;border-radius:5px">
                  ${t}
                </button>
              `).join('')}
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap">
            <span style="font-size:10px;font-weight:900;color:#38bdf8">⚔️ POSTURA:</span>
            <div class="halftime-speech-row" style="display:flex;gap:3px;flex-wrap:wrap">
              ${['Retranca', 'Defensiva', 'Equilibrada', 'Ofensiva', 'Pressão total'].map(p => `
                <button class="btn-halftime-speech ${(userIsHome ? s.homePosture : s.awayPosture) === p ? 'active' : ''}" data-posture="${p}" style="font-size:10px;font-weight:800;padding:2px 6px;border-radius:5px">
                  ${p}
                </button>
              `).join('')}
            </div>
          </div>
        </div>

        <!-- SEÇÃO SUBSTITUIÇÕES COM ESTRUTURA RÍGIDA DE 2 COLUNAS (.tactics-modal-container) -->
        <div style="flex:1;display:flex;flex-direction:column;min-height:0;gap:4px">
          <div style="display:flex;justify-content:space-between;align-items:center;background:#141d2c;padding:4px 10px;border-radius:8px;flex-shrink:0;gap:6px;flex-wrap:wrap">
            <span style="font-size:11px;color:rgba(255,255,255,0.9);font-weight:700">
              👉 <b>Clique em quem sai e em quem entra</b> para substituir
            </span>
            <div style="display:flex;align-items:center;gap:6px">
              <span id="halftimePitchFormTitle" style="font-size:10px;font-weight:900;color:#38bdf8">FORMAÇÃO:</span>
              <!-- Seletor de Formações Compacto -->
              <div style="display:flex;gap:2px;overflow-x:auto;max-width:260px">
                ${['4-3-3', '4-4-2', '3-5-2', '4-2-3-1', '5-3-2', '4-1-4-1', '4-5-1', '3-4-3'].map(f => `
                  <button class="btn btnFormSelectHalftime ${currentForm === f ? 'primary' : ''}" data-form="${f}" style="font-size:9px;padding:2px 5px;font-weight:900;border-radius:4px;white-space:nowrap">
                    ${f}
                  </button>
                `).join('')}
              </div>
              <span style="font-size:10px;font-weight:900;color:#facc15;background:rgba(250,204,21,0.15);padding:2px 6px;border-radius:5px;border:1px solid #facc15;white-space:nowrap">
                ${s.subsLeft} trocas
              </span>
            </div>
          </div>

          <!-- CONTAINER OFICIAL DE 2 COLUNAS (FLEX-NOWRAP) -->
          <div class="tactics-modal-container" id="halftimeTacticsContainer" style="flex:1;height:auto;min-height:0">
            <!-- COLUNA 1: GRAMADO VERTICAL OFICIAL -->
            <div class="tactics-pitch-wrapper" id="halftimePitchBox">
              ${renderVerticalTacticsPitch(userStarters, currentForm, { isHalftime: true, selectedStarterKey: halftimeSelectedStarterKey })}
            </div>

            <!-- COLUNA 2: BANCO DE RESERVAS LATERAL ORGANIZADO -->
            <div class="tactics-bench-wrapper" id="halftimeBenchWrapper">
              <div style="font-size:12px;font-weight:900;color:#94a3b8;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0">
                <span>BANCO DE RESERVAS</span>
                <span style="color:#22c55e;font-size:11px;font-weight:800">${userBench.length} disponíveis</span>
              </div>
              <div style="flex:1;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding-right:2px">
                ${userBench.map(p => {
                  const pOvr = playerOverall(p);
                  return `
                    <div class="bench-player-row" data-bench-key="${esc(playerKey(p))}" data-player-pos="${esc(p.pos)}" title="Clique para selecionar e substituir">
                      ${playerPhoto(p, 36)}
                      <div style="flex:1;min-width:0;margin-left:8px">
                        <div style="display:flex;justify-content:space-between;align-items:center">
                          <b style="font-size:12px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(p.name)}</b>
                          <span class="rating-pill ${ratingClass(pOvr)}">${pOvr}</span>
                        </div>
                        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:2px;font-size:10px">
                          <span style="color:#c084fc;font-weight:800">${esc(p.pos)}</span>
                          <span style="color:#22c55e;font-weight:700">100% energia</span>
                        </div>
                      </div>
                    </div>
                  `;
                }).join('')}
              </div>
              <div style="margin-top:8px;background:#101726;padding:8px 10px;border-radius:8px;font-size:10px;color:rgba(255,255,255,0.7);flex-shrink:0;line-height:1.3">
                💡 <b>Dica:</b> Clique no titular e no reserva (ou vice-versa) para trocar. Slots indicam 🟢 <b>VERDE (★ IDEAL)</b>, 🟡 <b>AMARELO (ADAPTADA)</b> e 🔴 <b>VERMELHO (INCOMPATÍVEL)</b>!
              </div>
            </div>
          </div>
        </div>

        <!-- FOOTER COM CHECKBOX E BOTÃO DE CONTINUAR -->
        <div class="halftime-footer" style="padding-top:8px;border-top:1px solid rgba(255,255,255,0.08);display:flex;justify-content:space-between;align-items:center;flex-shrink:0">
          <label style="display:flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:rgba(255,255,255,0.85);cursor:pointer">
            <input type="checkbox" id="chkAutoSubAssistant" ${s.autoSubAssistant ? 'checked' : ''} style="width:16px;height:16px">
            <span>O auxiliar técnico faz as trocas que sobrarem automaticamente</span>
          </label>

          <button class="btn primary" id="btnResumeSecondHalf" style="font-size:14px;font-weight:900;padding:10px 28px;border-radius:10px;box-shadow:0 0 20px rgba(168,85,247,0.6);cursor:pointer">
            ${isQuickTactics ? '▶ RETOMAR PARTIDA' : '▶ COMEÇAR O 2º TEMPO'}
          </button>
        </div>
      </div>
    </div>
  `;

  // Preleção click sem reiniciar o modal / sem scroll jump
  $$('.btn-halftime-speech[data-speech]').forEach(b => {
    b.onclick = (e) => {
      e.stopPropagation();
      const speech = b.dataset.speech;
      s.prelecao = speech;
      $$('.btn-halftime-speech[data-speech]').forEach(btn => btn.classList.toggle('active', btn.dataset.speech === speech));
      const descEl = $('#halftimeSpeechDesc');
      if(descEl) descEl.innerHTML = speechDescriptions[speech] || '';
      toast(`Preleção definida: ${speech}!`);
    };
  });

  // Postura click sem reiniciar o modal / sem scroll jump
  $$('.btn-halftime-speech[data-posture]').forEach(b => {
    b.onclick = (e) => {
      e.stopPropagation();
      const posture = b.dataset.posture;
      if(userIsHome) s.homePosture = posture;
      else s.awayPosture = posture;
      $$('.btn-halftime-speech[data-posture]').forEach(btn => {
        const isAct = btn.dataset.posture === posture;
        btn.classList.toggle('active', isAct);
        btn.textContent = `${btn.dataset.posture} ${isAct ? '(atual)' : ''}`;
      });
      const descEl = $('#halftimePostureDesc');
      if(descEl) descEl.innerHTML = postureDescriptions[posture] || '';
      toast(`Postura tática alterada para ${posture}!`);
    };
  });

  function executeHalftimeSub(starterKey, benchKey, targetSlotIndex){
    const tracker = userIsHome ? s.homeSubs : s.awaySubs;
    const isHT = (s.phase === 'HALF_TIME');
    const isET = (s.phase && s.phase.startsWith('EXTRA'));
    const check = window.AFM_REAL_FOOTBALL ? window.AFM_REAL_FOOTBALL.rules.canSubstitute(tracker, s.minute, isHT, isET) : { allowed: s.subsLeft > 0, remainingSubs: s.subsLeft };
    if(!check.allowed){
      toast(check.reason || 'Você já atingiu o limite de substituições ou paradas nesta partida!');
      return;
    }
    const userStarters = (userIsHome ? s.homePlayers : s.awayPlayers);
    const keyOf = p => p?.key || (typeof playerKey === 'function' ? playerKey(p) : p?.id);

    // Identifica com precisão quem é o titular saindo e quem é o reserva entrando
    let actualStarterKey = starterKey;
    let actualBenchKey = benchKey;
    let targetIdx = userStarters.findIndex(p => keyOf(p) === starterKey);

    if(targetIdx < 0 && Number.isInteger(targetSlotIndex) && targetSlotIndex >= 0 && targetSlotIndex < userStarters.length){
      targetIdx = targetSlotIndex;
      actualStarterKey = keyOf(userStarters[targetIdx]);
    }

    // Se estiver invertido (benchKey era o titular e starterKey era o reserva)
    if(targetIdx < 0){
      const revIdx = userStarters.findIndex(p => keyOf(p) === benchKey);
      if(revIdx >= 0){
        targetIdx = revIdx;
        actualStarterKey = benchKey;
        actualBenchKey = starterKey;
      }
    }

    if(targetIdx === -1) return toast('Selecione um titular válido em campo para substituir.');

    const benchPlayer = state.squad.find(p => playerKey(p) === actualBenchKey);
    if(!benchPlayer) return toast('Jogador reserva não encontrado no elenco.');

    s.subbedOut = Array.isArray(s.subbedOut) ? s.subbedOut : [];
    if(s.subbedOut.includes(actualBenchKey)){
      toast('Este atleta já foi substituído nesta partida e não pode retornar ao gramado!');
      return;
    }

    const oldPlayer = userStarters[targetIdx];
    const oldKey = keyOf(oldPlayer);
    s.subbedOut.push(oldKey);

    const isGKSlot = (targetIdx === 0);
    const currentForm = state.formation || '4-3-3';
    const formDef = FORMATIONS[currentForm] || FORMATIONS['4-3-3'];
    const slotRole = isGKSlot ? 'GK' : (formDef[targetIdx]?.r || oldPlayer.pos || 'CM');
    const effectiveOvr = (typeof getPlayerEffectiveOverall === 'function')
      ? getPlayerEffectiveOverall(benchPlayer, slotRole)
      : (playerOverall(benchPlayer) || 65);

    const newPlayerObj = {
      ...oldPlayer,
      id: playerKey(benchPlayer),
      key: playerKey(benchPlayer),
      name: benchPlayer.name.split(' ').pop() || benchPlayer.name,
      fullName: benchPlayer.name,
      pos: isGKSlot ? 'GK' : (benchPlayer.pos || slotRole),
      overall: effectiveOvr || 65,
      stamina: 100, // Entra 100% descansado
      speed: benchPlayer.vel || benchPlayer.speed || effectiveOvr,
      pass: benchPlayer.pas || benchPlayer.pass || effectiveOvr,
      shoot: benchPlayer.fin || benchPlayer.shoot || effectiveOvr,
      defense: benchPlayer.des || benchPlayer.defense || effectiveOvr,
      isUser: true,
      team: userIsHome ? 'home' : 'away',
      isGK: isGKSlot,
      canScore: !isGKSlot,
      canShoot: !isGKSlot,
      photo: resolvePlayerPhotoUrl(benchPlayer) || null
    };

    userStarters[targetIdx] = newPlayerObj;

    // Se o jogador substituído estava com a bola, passa a posse ao novo atleta
    if(s.ball && s.ball.carrier && s.ball.carrier.key === oldKey){
      s.ball.carrier = newPlayerObj;
    }

    // Sincroniza com a escalação persistida do clube
    if(Array.isArray(state.lineup)){
      const lineIdx = state.lineup.indexOf(oldKey);
      if(lineIdx !== -1){
        state.lineup[lineIdx] = playerKey(benchPlayer);
      } else if(targetIdx >= 0 && targetIdx < 11){
        state.lineup[targetIdx] = playerKey(benchPlayer);
      }
    }

    newPlayerObj.kit = userIsHome ? s.homeKit : s.awayKit;
    newPlayerObj.clubName = userIsHome ? s.home : s.away;

    if(window.AFM_REAL_FOOTBALL){
      window.AFM_REAL_FOOTBALL.rules.recordSubstitution(tracker, s.minute, isHT);
      s.subsLeft = Math.max(0, check.remainingSubs - 1);
    } else {
      s.subsLeft--;
    }
    s.events.unshift({
      min: s.minute,
      type: 'sub',
      text: `🔁 Substituição no ${state.club}: Sai ${oldPlayer.name} (${Math.round(oldPlayer.stamina)}% energia), entra ${benchPlayer.name} descansado!`
    });
    updateLiveSidebarEvents();

    toast(`🔁 Substituição confirmada: ${benchPlayer.name} entra no lugar de ${oldPlayer.name}!`);
    halftimeSelectedStarterKey = null;
    save();
    openHalftimeModal(isQuickTactics);
  }

  function swapHalftimeStarters(k1, k2, idx1Arg, idx2Arg){
    const userStarters = (userIsHome ? s.homePlayers : s.awayPlayers);
    const keyOf = p => p?.key || (typeof playerKey === 'function' ? playerKey(p) : p?.id);
    let idx1 = userStarters.findIndex(p => keyOf(p) === k1);
    let idx2 = userStarters.findIndex(p => keyOf(p) === k2);
    if(idx1 < 0 && Number.isInteger(idx1Arg)) idx1 = idx1Arg;
    if(idx2 < 0 && Number.isInteger(idx2Arg)) idx2 = idx2Arg;

    if(idx1 !== -1 && idx2 !== -1 && idx1 !== idx2){
      const tmpPlayer = userStarters[idx1];
      userStarters[idx1] = userStarters[idx2];
      userStarters[idx2] = tmpPlayer;

      // Atualiza funções de goleiro se um dos slots for o gol (índice 0)
      userStarters.forEach((mp, i) => {
        mp.isGK = (i === 0);
        if(i === 0){
          mp.pos = 'GK';
          mp.canScore = false;
          mp.canShoot = false;
        } else {
          mp.canScore = true;
          mp.canShoot = true;
        }
      });

      // Sincroniza com state.lineup
      if(Array.isArray(state.lineup)){
        const lIdx1 = state.lineup.indexOf(k1);
        const lIdx2 = state.lineup.indexOf(k2);
        if(lIdx1 !== -1 && lIdx2 !== -1){
          [state.lineup[lIdx1], state.lineup[lIdx2]] = [state.lineup[lIdx2], state.lineup[lIdx1]];
        } else if(idx1 < state.lineup.length && idx2 < state.lineup.length){
          [state.lineup[idx1], state.lineup[idx2]] = [state.lineup[idx2], state.lineup[idx1]];
        }
      }

      toast(`Posições invertidas entre ${userStarters[idx1].name} e ${userStarters[idx2].name}!`);
      save();
      openHalftimeModal(isQuickTactics);
    }
  }

  // Mudança de Formação no intervalo
  $$('.btnFormSelectHalftime').forEach(b => {
    b.onclick = (e) => {
      e.stopPropagation();
      const newForm = b.dataset.form;
      state.formation = newForm;
      openHalftimeModal(isQuickTactics);
      toast(`Formação alterada para ${newForm}!`);
    };
  });

  // Ativação dos manipuladores de Arraste e Clique (Drag & Drop + Click-to-swap)
  setupTacticsInteractions({
    containerEl: $('#halftimeTacticsContainer'),
    starters: userStarters,
    bench: userBench,
    onSwap: (targetStarterKey, benchKey, targetSlotIndex) => {
      executeHalftimeSub(targetStarterKey, benchKey, targetSlotIndex);
    },
    onStarterSwap: (key1, key2, idx1, idx2) => {
      swapHalftimeStarters(key1, key2, idx1, idx2);
    },
    isHalftime: true
  });

  // IA Tática Reativa da CPU no Intervalo
  function applyCpuReactiveHalftimeTactics(s) {
    try {
      const cpuIsHome = !userIsHome;
      const cpuClub = cpuIsHome ? s.home : s.away;
      const cpuGoals = cpuIsHome ? s.hg : s.ag;
      const userGoals = cpuIsHome ? s.ag : s.hg;
      const diff = cpuGoals - userGoals;

      if (diff <= -2) {
        if (cpuIsHome) s.homePosture = 'Pressão Total';
        else s.awayPosture = 'Pressão Total';
        s.events.unshift({
          min: 46,
          type: 'tactic',
          text: `⚡ [Tática da CPU] O técnico do ${cpuClub} adiantou as linhas e colocou a equipe em PRESSÃO TOTAL para buscar a virada!`
        });
        toast(`⚡ Atenção: O ${cpuClub} adotou postura de Pressão Total no 2º tempo!`);
      } else if (diff === -1) {
        if (cpuIsHome) s.homePosture = 'Ofensiva';
        else s.awayPosture = 'Ofensiva';
        s.events.unshift({
          min: 46,
          type: 'tactic',
          text: `⚡ [Tática da CPU] O técnico do ${cpuClub} alterou a postura para OFENSIVA em busca do empate.`
        });
        toast(`⚡ O ${cpuClub} voltou para o 2º tempo com postura Ofensiva!`);
      } else if (diff >= 1) {
        if (cpuIsHome) s.homePosture = 'Contra-Ataque';
        else s.awayPosture = 'Contra-Ataque';
        s.events.unshift({
          min: 46,
          type: 'tactic',
          text: `🛡️ [Tática da CPU] O técnico do ${cpuClub} recuou as linhas para compactar a defesa e explorar o CONTRA-ATAQUE.`
        });
      }
    } catch (e) {
      // Ignora silenciosamente para manter estabilidade
    }
  }

  // Retomar 2º tempo
  const chkAux = $('#chkAutoSubAssistant');
  if(chkAux) chkAux.onchange = () => { s.autoSubAssistant = chkAux.checked; };

  const btnResume = $('#btnResumeSecondHalf');
  if(btnResume){
    btnResume.onclick = () => {
      $('#halftimeModalContainer')?.remove();
      if(s.phase === 'HALF_TIME' && !isQuickTactics){
        if((state?.gameMode === 'player' || state?.playerCareerState) && s.shouldSubPlayerAtHalftime && typeof window.triggerPlayerCareerSubstitution === 'function'){
          window.triggerPlayerCareerSubstitution(s);
        }
        applyCpuReactiveHalftimeTactics(s);
        transitionMatchPhase('SECOND_HALF');
        s.phase = 'SECOND_HALF';
        s.minute = Math.max(45, Number(s.minute) || 45);
        s.timeSec = Math.max(2700, Number(s.timeSec) || 2700);
      }
      s.secAccumulator = 0;
      s.lastLoopTime = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      s.playing = true;
      const playBtn = $('#btnLivePlayToggle');
      if(playBtn) playBtn.textContent = '⏸';
      const overlay = $('#livePauseOverlay');
      if(overlay) overlay.style.display = 'none';
      if(window.afmAudio){
        window.afmAudio.playSFX('whistle_start');
      } else {
        playWhistleSound();
      }
      renderLiveMatchModal();
      toast(isQuickTactics ? 'Partida retomada com os novos ajustes táticos!' : 'Bola rolando para a etapa complementar!');
    };
  }
}

function finishLiveMatch(){
  const s = liveMatchState;
  if(!s || s.done) return;
  s.done = true;
  s.playing = false;
  transitionMatchPhase('FULL_TIME');
  if(window.afmAudio){
    window.afmAudio.playSFX('whistle_end');
    window.afmAudio.stopCrowdAmbient();
  } else {
    playWhistleSound();
  }

  let winner = null, pens = null;
  if(s.isKO){
    if(s.hg === s.ag){
      const isUserMatch = norm(s.home) === norm(state.club) || norm(s.away) === norm(state.club);
      if(isUserMatch && window.AFM_LiveMatchHUD && typeof window.AFM_LiveMatchHUD.openPenaltyShootoutModal === 'function'){
        window.AFM_LiveMatchHUD.openPenaltyShootoutModal(s, ({ homeScore, awayScore }) => {
          s.pens = [homeScore, awayScore];
          s.winner = homeScore > awayScore ? s.home : s.away;
          s.winners.push(s.winner);
          s.events.unshift({ min: 90, type: 'whistle', text: `🎯 Pênaltis: ${s.home} ${homeScore} x ${awayScore} ${s.away}. Vencedor: ${s.winner}!` });
          applyResult(s.home, s.away, s.hg, s.ag);
          if(Array.isArray(s.otherResults)){
            s.otherResults.forEach(res => {
              applyResult(res.h, res.a, res.hg, res.ag);
            });
          }
          updateLiveSidebarEvents();
          renderLiveMatchModal();
        });
        return;
      }
      let hp = rnd(3, 6), ap = rnd(2, 6);
      if(hp === ap) ap = hp === 6 ? 5 : hp + 1;
      pens = [hp, ap];
      winner = hp > ap ? s.home : s.away;
      s.events.unshift({ min: 90, type: 'whistle', text: `🎯 Pênaltis: ${s.home} ${pens[0]} x ${pens[1]} ${s.away}. Vencedor: ${winner}!` });
    } else {
      winner = s.hg > s.ag ? s.home : s.away;
    }
    s.winners.push(winner);
  }

  s.winner = winner;
  s.pens = pens;
  applyResult(s.home, s.away, s.hg, s.ag);
  if(Array.isArray(s.otherResults)){
    s.otherResults.forEach(res => {
      applyResult(res.h, res.a, res.hg, res.ag);
    });
  }
  s.events.unshift({ min: 90, type: 'whistle', text: `🏁 Fim de partida! ${s.home} ${s.hg} x ${s.ag} ${s.away}.` });
  updateLiveSidebarEvents();
  renderLiveMatchModal();
}

function finalizeMatchRound(){
  if(window.AFM_Guards && typeof window.AFM_Guards.runWithTurnLock === 'function'){
    if(!window.AFM_Guards.runWithTurnLock(() => true)) return;
  }
  const finishingStateLeagueMatch = Boolean(stateLeagueMatchSession);

  const s = liveMatchState;
  if(!s) return;
  const userRes = {
    h: s.home, a: s.away,
    hg: s.hg, ag: s.ag,
    winner: s.winner, pens: s.pens,
    events: (s.events || []).filter(event => event?.type === 'gol')
  };
  const winners = s.winners;
  const isKO = s.isKO;
  const finishingContinentalMatch = Boolean(continentalMatchSession);
  const finishingCopaMatch = Boolean(copaMatchSession);
  const stateLeagueFixture = finishingStateLeagueMatch ? stateLeagueMatchSession.data.fixtures.find(f=>Number(f.roundIndex)===Number(stateLeagueMatchSession.roundIndex)&&norm(f.home)===norm(stateLeagueMatchSession.fixture[0])&&norm(f.away)===norm(stateLeagueMatchSession.fixture[1])) : null;
  if(finishingStateLeagueMatch && stateLeagueFixture && (stateLeagueFixture.played===true || stateLeagueFixture.result || (state.history||[]).some(h=>h.competitionId===stateLeagueMatchSession.competitionId&&Number(h.season)===Number(state.season)&&((norm(h.h)===norm(userRes.h)&&norm(h.a)===norm(userRes.a))||(norm(h.h)===norm(userRes.a)&&norm(h.a)===norm(userRes.h)))))){
    if(liveCanvasAnimId) cancelAnimationFrame(liveCanvasAnimId);
    $('#matchModalContainer')?.remove();
    liveMatchState=null;
    restorePrimaryLeagueAfterStateMatch();
    save(); render();
    toast('Esta partida estadual já tinha resultado salvo; a partida duplicada foi descartada.');
    return;
  }

  let playerPerformanceReport = null;
  if(state.gameMode === 'player' && state.playerCareerState && !s.playerPerformanceProcessed){
    s.playerPerformanceProcessed = true;
    const isUserHome = norm(s.home) === norm(state.club);
    const playerTeam = isUserHome ? s.homePlayers : s.awayPlayers;
    const hasControlledId = state.controlledPlayerId != null;
    const athlete = hasControlledId ? (state.squad || []).find(p => String(p.id) === String(state.controlledPlayerId)) : null;
    const nameMatches = value => {
      const candidate = norm(value || '');
      return !!candidate && [athlete?.name, athlete?.fullName, state.playerCareerState.athleteName]
        .some(name => norm(name || '') === candidate);
    };
    const matchAthlete = (playerTeam || []).find(p => p.isControlledAthlete ||
      (hasControlledId && (String(p.id) === String(state.controlledPlayerId) || String(p.careerPlayerId) === String(state.controlledPlayerId))) || nameMatches(p.name));
    const goalEvents = (s.events || []).filter(event => event.type === 'gol');
    const eventHasPlayerId = (eventId, playerId) => eventId != null && playerId != null && String(eventId) === String(playerId);
    const scorerEvents = matchAthlete ? goalEvents.filter(event =>
      eventHasPlayerId(event.playerId, matchAthlete.id) ||
      eventHasPlayerId(event.playerId, matchAthlete.careerPlayerId) ||
      nameMatches(event.scorer)
    ) : [];
    const assistEvents = matchAthlete ? goalEvents.filter(event =>
      eventHasPlayerId(event.relatedPlayerId, matchAthlete.id) ||
      eventHasPlayerId(event.relatedPlayerId, matchAthlete.careerPlayerId) ||
      nameMatches(event.assist)
    ) : [];
    const eventBelongsToAthlete = event => matchAthlete && (
      eventHasPlayerId(event.playerId, matchAthlete.id) ||
      eventHasPlayerId(event.playerId, matchAthlete.careerPlayerId) ||
      nameMatches(event.scorer)
    );
    const goals = scorerEvents.length;
    const assists = assistEvents.length;
    const recordedShots = matchAthlete ? (s.events || []).filter(event => eventBelongsToAthlete(event) && (
      ['gol', 'save', 'post', 'miss'].includes(event.type) || (event.type === 'whistle' && /BLOQUEIO PROVIDENCIAL/i.test(event.text || ''))
    )).length : 0;
    const shots = matchAthlete ? Math.max(Number(matchAthlete.matchShots) || 0, recordedShots) : 0;
    const shotsOnTarget = matchAthlete ? (s.events || []).filter(event => eventBelongsToAthlete(event) && ['gol', 'save'].includes(event.type)).length : 0;
    const enteredMinute = matchAthlete ? Number(matchAthlete.enteredMinute) || 0 : 0;
    const playedMinutes = matchAthlete ? Math.max(0, Math.min(120, (Number(s.minute) || 90) - enteredMinute)) : 0;
    const liveCompId = finishingStateLeagueMatch
      ? stateLeagueMatchSession?.competitionId
      : finishingContinentalMatch
      ? continentalMatchSession?.competitionId
      : finishingCopaMatch
      ? 'bra-cup'
      : (curComp()?.id || state.compId);
    const liveCompName = finishingStateLeagueMatch
      ? stateLeagueMatchSession?.data?.name
      : finishingContinentalMatch
      ? continentalMatchSession?.compName
      : finishingCopaMatch
      ? 'Copa do Brasil'
      : (curComp()?.name || state.competition);
    playerPerformanceReport = window.AFM_PlayerEngine?.processMatchPerformance(state, {
      h: s.home,
      a: s.away,
      hg: s.hg,
      ag: s.ag,
      goalsFor: isUserHome ? s.hg : s.ag,
      goalsAgainst: isUserHome ? s.ag : s.hg,
      goals,
      assists,
      shots,
      shotsOnTarget,
      rating: Number(matchAthlete?.firstHalfRating) || undefined,
      playedMinutes,
      started: Boolean(matchAthlete?.wasStarter),
      competitionId: liveCompId,
      competitionName: liveCompName,
      eligibleForMatch: s.playerCareerAvailableForMatch !== false,
      status: s.playerCareerAvailableForMatch === false ? 'Não relacionado por condição física' : 'Reserva não utilizado',
      reason: s.playerCareerAvailableForMatch === false ? 'Você estava com condição abaixo de 50% e ficou fora dos relacionados.' : 'Você ficou no banco e não entrou nesta partida.'
    }, { showSummary: false });
    if(playerPerformanceReport) state.playerCareerState.lastProcessedLiveMatchId = s.matchId;
  }

  if(liveCanvasAnimId) cancelAnimationFrame(liveCanvasAnimId);
  $('#matchModalContainer')?.remove();
  liveMatchState = null;

  // Partidas estaduais não passam pelo finalizador da temporada nacional.
  if(finishingStateLeagueMatch){
    const session=stateLeagueMatchSession, data=session.data, [home,away]=session.fixture;
    const isHome=norm(home)===norm(state.club), gf=isHome?s.hg:s.ag, ga=isHome?s.ag:s.hg;
    const existing=(state.history||[]).some(h=>h.competitionId===session.competitionId&&Number(h.season)===Number(state.season)&&((norm(h.h)===norm(home)&&norm(h.a)===norm(away))||(norm(h.h)===norm(away)&&norm(h.a)===norm(home))));
    if(existing) toast('Resultado estadual já registrado; a partida não foi contabilizada novamente.');
    else {
      const homeTeam=data.teams.find(team=>norm(team.name)===norm(home)), awayTeam=data.teams.find(team=>norm(team.name)===norm(away));
      if(homeTeam&&awayTeam){
        for(const team of [homeTeam,awayTeam]) team.j=(Number(team.j)||0)+1;
        homeTeam.gp=(Number(homeTeam.gp)||0)+s.hg; homeTeam.gc=(Number(homeTeam.gc)||0)+s.ag;
        awayTeam.gp=(Number(awayTeam.gp)||0)+s.ag; awayTeam.gc=(Number(awayTeam.gc)||0)+s.hg;
        homeTeam.sg=homeTeam.gp-homeTeam.gc; awayTeam.sg=awayTeam.gp-awayTeam.gc;
        if(s.hg>s.ag){homeTeam.v=(Number(homeTeam.v)||0)+1;homeTeam.p=(Number(homeTeam.p)||0)+3;awayTeam.d=(Number(awayTeam.d)||0)+1;}
        else if(s.hg<s.ag){awayTeam.v=(Number(awayTeam.v)||0)+1;awayTeam.p=(Number(awayTeam.p)||0)+3;homeTeam.d=(Number(homeTeam.d)||0)+1;}
        else {homeTeam.e=(Number(homeTeam.e)||0)+1;awayTeam.e=(Number(awayTeam.e)||0)+1;homeTeam.p=(Number(homeTeam.p)||0)+1;awayTeam.p=(Number(awayTeam.p)||0)+1;}
        for(const team of [homeTeam,awayTeam]){team.pct=team.j?Math.round(team.p/(team.j*3)*100):0;team.form=Array.isArray(team.form)?team.form:[];team.form.push(team===homeTeam?(s.hg>s.ag?'V':s.hg<s.ag?'D':'E'):(s.ag>s.hg?'V':s.ag<s.hg?'D':'E'));team.form=team.form.slice(-5);}
      }
      const fixture=(data.fixtures||[]).find(f=>Number(f.roundIndex)===Number(session.roundIndex)&&norm(f.home)===norm(home)&&norm(f.away)===norm(away));
      if(fixture){fixture.result=[s.hg,s.ag];fixture.played=true;}
      (data.fixtures||[]).forEach(fix => {
        if(Number(fix.roundIndex) === Number(session.roundIndex) && !fix.played && !fix.result){
          const [hg, ag] = simulateScore(fix.home, fix.away);
          fix.result = [hg, ag];
          fix.played = true;
          const tH = data.teams.find(t=>norm(t.name)===norm(fix.home));
          const tA = data.teams.find(t=>norm(t.name)===norm(fix.away));
          if(tH && tA){
            tH.j = (Number(tH.j)||0)+1; tA.j = (Number(tA.j)||0)+1;
            tH.gp = (Number(tH.gp)||0)+hg; tH.gc = (Number(tH.gc)||0)+ag;
            tA.gp = (Number(tA.gp)||0)+ag; tA.gc = (Number(tA.gc)||0)+hg;
            tH.sg = tH.gp - tH.gc; tA.sg = tA.gp - tA.gc;
            if(hg > ag){ tH.v=(Number(tH.v)||0)+1; tH.p=(Number(tH.p)||0)+3; tA.d=(Number(tA.d)||0)+1; }
            else if(hg < ag){ tA.v=(Number(tA.v)||0)+1; tA.p=(Number(tA.p)||0)+3; tH.d=(Number(tH.d)||0)+1; }
            else { tH.e=(Number(tH.e)||0)+1; tA.e=(Number(tA.e)||0)+1; tH.p=(Number(tH.p)||0)+1; tA.p=(Number(tA.p)||0)+1; }
            for(const tm of [tH, tA]){
              tm.pct = tm.j ? Math.round(tm.p / (tm.j * 3) * 100) : 0;
              tm.form = Array.isArray(tm.form) ? tm.form : [];
              tm.form.push(tm === tH ? (hg > ag ? 'V' : hg < ag ? 'D' : 'E') : (ag > hg ? 'V' : ag < hg ? 'D' : 'E'));
              tm.form = tm.form.slice(-5);
            }

            // Registra artilharia e assistências dos outros confrontos da rodada estadual
            if(norm(fix.home) !== norm(state.club) && norm(fix.away) !== norm(state.club)){
              if(hg > 0){
                const hEv = simulateClubGoalEvents(fix.home, hg, session.competitionId);
                addPlayerMatchStats(session.competitionId, fix.home, hEv);
              }
              if(ag > 0){
                const aEv = simulateClubGoalEvents(fix.away, ag, session.competitionId);
                addPlayerMatchStats(session.competitionId, fix.away, aEv);
              }
            }
          }
        }
      });
      addPlayerMatchStats(session.competitionId,state.club,(s.events||[]).filter(event=>event?.type==='gol'));
      const oppClubLive = isHome ? away : home;
      const oppGoalsLive = isHome ? s.ag : s.hg;
      if(oppGoalsLive > 0){
        const oppEv = simulateClubGoalEvents(oppClubLive, oppGoalsLive, session.competitionId);
        addPlayerMatchStats(session.competitionId, oppClubLive, oppEv);
      }
      state.history=state.history||[];
      state.history.unshift({...userRes,round:session.roundIndex+1,season:Number(state.season),date:fixture?.isoDate||state.date,competitionId:session.competitionId,competitionName:data.name,isHome,won:gf>ga});
      state.history=state.history.slice(0,100);
      data.currentRound=Math.max(Number(data.currentRound)||1,session.roundIndex+2);
      state.estadualData[session.competitionId]=data;
      if(typeof syncCompetitionStatsComprehensive === 'function') syncCompetitionStatsComprehensive(session.competitionId);
    }
    advanceDateAfterMatch(state);
    restorePrimaryLeagueAfterStateMatch();
    if(window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.processRoundMatchStats === 'function'){
      window.AFM_MarketLupaAndAging.processRoundMatchStats(state, { h: userRes.h, a: userRes.a, hg: userRes.hg, ag: userRes.ag, gf, ga, won: gf > ga, events: userRes.events });
    }
    if(typeof window !== 'undefined' && window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.processRoundTurn === 'function'){
      window.AFM_LifeAndSharesPro.processRoundTurn(state);
    }
    if(typeof processFitness === 'function') processFitness();
    if(typeof processDevelopment === 'function') processDevelopment();
  } else if(finishingContinentalMatch){
    const session = continentalMatchSession;
    const { tournament, matchId, compName, competitionId } = session;
    const match = (tournament?.matches || []).find(m => m.id === matchId);
    if(match){
      const isHome = norm(match.home) === norm(state.club);
      const userGoals = isHome ? s.hg : s.ag;
      const oppGoals = isHome ? s.ag : s.hg;
      const won = userGoals > oppGoals;
      window.AFM_TOURNAMENT_ENGINE.recordResult(tournament, match.id, s.hg, s.ag);
      const events = (s.events || []).filter(e => e?.type === 'gol');
      addPlayerMatchStats(competitionId, state.club, events);
      const oppContClub = isHome ? match.away : match.home;
      if(oppGoals > 0 && oppContClub){
        const oppContEv = events.filter(e => norm(e.teamId) === norm(oppContClub));
        addPlayerMatchStats(competitionId, oppContClub, oppContEv.length ? oppContEv : simulateClubGoalEvents(oppContClub, oppGoals, competitionId));
      }
      const historyItem = {
        h: match.home, a: match.away, hg: s.hg, ag: s.ag, events,
        round: match.round, season: Number(state.season), date: match.date || state.date,
        competitionId, competitionName: compName, isHome, won
      };
      state.history = [historyItem, ...(state.history || [])].slice(0, 100);
      state.lastMatchSummary = { h: match.home, a: match.away, hg: s.hg, ag: s.ag, isHome, won };
      if(window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.processRoundMatchStats === 'function'){
        window.AFM_MarketLupaAndAging.processRoundMatchStats(state, { h: match.home, a: match.away, hg: s.hg, ag: s.ag, gf: userGoals, ga: oppGoals, won, events });
      }
      state.news = state.news || [];
      state.news.unshift(`🏆 ${compName}: ${match.home} ${s.hg} x ${s.ag} ${match.away} (Rodada ${match.round}).`);

      // Simula outros jogos da mesma data do torneio
      const otherDateMatches = (tournament.matches || []).filter(m => m.date === match.date && m.status === 'scheduled' && norm(m.home) !== norm(state.club) && norm(m.away) !== norm(state.club));
      for(const om of otherDateMatches){
        const [ohg, oag] = simulateScore(om.home, om.away);
        window.AFM_TOURNAMENT_ENGINE.recordResult(tournament, om.id, ohg, oag);
        if(ohg > 0) addPlayerMatchStats(competitionId, om.home, simulateClubGoalEvents(om.home, ohg, competitionId));
        if(oag > 0) addPlayerMatchStats(competitionId, om.away, simulateClubGoalEvents(om.away, oag, competitionId));
      }
      if(typeof syncCompetitionStatsComprehensive === 'function') syncCompetitionStatsComprehensive(competitionId);
    }
    advanceDateAfterMatch(state);
    restorePrimaryLeagueAfterContinentalMatch();
    if(typeof window !== 'undefined' && window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.processRoundTurn === 'function'){
      window.AFM_LifeAndSharesPro.processRoundTurn(state);
    }
    if(typeof processFitness === 'function') processFitness();
    if(typeof processDevelopment === 'function') processDevelopment();
  } else if(finishingCopaMatch){
    const session = copaMatchSession;
    const { fixture, phase, phaseName } = session;
    const isHome = norm(fixture.home) === norm(state.club);
    const userGoals = isHome ? s.hg : s.ag;
    const oppGoals = isHome ? s.ag : s.hg;
    const winner = s.winner || (s.hg === s.ag ? (Math.random() < 0.5 ? fixture.home : fixture.away) : (s.hg > s.ag ? fixture.home : fixture.away));
    fixture.score = [s.hg, s.ag];
    fixture.winner = winner;
    fixture.played = true;
    const events = (s.events || []).filter(e => e?.type === 'gol');
    addPlayerMatchStats('bra-cup', state.club, events);
    const oppCopaClub = isHome ? fixture.away : fixture.home;
    if(oppGoals > 0 && oppCopaClub){
      const oppCopaEv = events.filter(e => norm(e.teamId) === norm(oppCopaClub));
      addPlayerMatchStats('bra-cup', oppCopaClub, oppCopaEv.length ? oppCopaEv : simulateClubGoalEvents(oppCopaClub, oppGoals, 'bra-cup'));
    }
    if(typeof syncCompetitionStatsComprehensive === 'function') syncCompetitionStatsComprehensive('bra-cup');
    const result = { h: fixture.home, a: fixture.away, hg: s.hg, ag: s.ag, winner, events, round: phase.name, season: Number(state.season), date: state.date, competitionId: 'bra-cup', competitionName: 'Copa do Brasil' };
    state.history = [result, ...(state.history || [])].slice(0, 100);
    state.lastMatchSummary = { h: fixture.home, a: fixture.away, hg: s.hg, ag: s.ag, isHome, won: norm(winner) === norm(state.club) };
    if(window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.processRoundMatchStats === 'function'){
      window.AFM_MarketLupaAndAging.processRoundMatchStats(state, { h: fixture.home, a: fixture.away, hg: s.hg, ag: s.ag, gf: userGoals, ga: oppGoals, won: norm(winner) === norm(state.club), events });
    }
    state.news = state.news || [];
    state.news.unshift(`🏆 Copa do Brasil (${phase.name}): ${fixture.home} ${s.hg} x ${s.ag} ${fixture.away}. ${norm(winner) === norm(state.club) ? 'Classificado.' : 'Eliminado.'}`);
    if(norm(winner) !== norm(state.club)){
      const opp = isHome ? fixture.away : fixture.home;
      registrarEliminacaoMataMata(state, 'Copa do Brasil', phase.name, opp, userGoals, oppGoals);
    }
    advanceDateAfterMatch(state);
    restorePrimaryLeagueAfterCopaMatch();
    if(typeof window !== 'undefined' && window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.processRoundTurn === 'function'){
      window.AFM_LifeAndSharesPro.processRoundTurn(state);
    }
    if(typeof processFitness === 'function') processFitness();
    if(typeof processDevelopment === 'function') processDevelopment();
  } else finalizeRound(userRes, winners, isKO);
  save();
  render();

  // Relatório individual primeiro; ao continuar, abre as opções pós-jogo usuais.
  if(playerPerformanceReport && window.AFM_PlayerMode?.showPostMatchSummaryModal){
    window.AFM_PlayerMode.showPostMatchSummaryModal(playerPerformanceReport, null, () => {
      if(userRes) triggerPostMatchFlow(userRes);
      else { view = 'player_hub'; if(typeof window !== 'undefined') window.view = 'player_hub'; render(); }
    });
  } else if(userRes){
    triggerPostMatchFlow(userRes);
  } else {
    const isPl = (typeof window !== 'undefined' && window.isPlayerCareerActive?.(state)) || state?.gameMode === 'player';
    view = isPl ? 'player_hub' : 'central';
    if(typeof window !== 'undefined') window.view = view;
    render();
  }
}


let isSimulatingQuickRound = false;
function simulateQuickRound(){
  if(isSimulatingQuickRound) return;
  if(typeof repairSaveIfCorrupted === 'function' && repairSaveIfCorrupted(state)) save();
  const matchGate = canStartMatch();
  if(!matchGate.canStart && matchGate.status !== 'missed'){
    if(matchGate.status === 'season_finished'){
      showEndOfSeasonModal();
      return;
    }
    if(matchGate.status === 'other_competitions_pending'){
      openNextPendingCompetitionFixture(matchGate.nextFixture || getNextPendingClubFixture(state));
      return;
    }
    if(matchGate.status === 'future'){
      // Se o usuário clica em simular diretamente mas ainda faltavam dias, avança o calendário até a data do jogo
      state.date = matchGate.matchDate;
    } else if(matchGate.status === 'no_fixture' || matchGate.isBye){
      isSimulatingQuickRound = true;
      try {
        const fixtures = currentFixtures();
        if(!fixtures.length){
          const comp = curComp();
          const nextRound = (state.schedule || []).findIndex((roundGames, idx) => idx > state.round && Array.isArray(roundGames) && roundGames.some(g => Array.isArray(g) && g.length >= 2));
          if(nextRound >= 0){
            state.round = nextRound;
            state.date = getDateForRound(nextRound, state.season);
            state.news = Array.isArray(state.news) ? state.news : [];
            state.news.unshift(`📅 Rodada sem fixtures recuperada em ${comp?.name || 'competição'}; calendário sincronizado para a rodada ${nextRound + 1}.`);
            state.news = state.news.slice(0, 50);
            save(); render();
            toast(`📅 Calendário recuperado. Próxima rodada válida: ${nextRound + 1}.`);
            return;
          }
          showEndOfSeasonModal();
          return;
        }
        const comp = curComp(), isKO = comp.type === 'knockout';
        const winners = [];
        fixtures.forEach(([h,a]) => {
          if(norm(h) === norm(a)) return;
          const [hg,ag] = simulateScore(h,a);
          let winner = null;
          if(isKO){ winner = hg === ag ? (Math.random() < 0.5 ? h : a) : (hg > ag ? h : a); winners.push(winner); }
          applyResult(h,a,hg,ag);
        });
        finalizeRound(null, winners, isKO);
        save();
        render();
        toast('📅 Sua equipe está de folga nesta rodada. Os outros jogos foram simulados e o calendário avançou.');
      } finally {
        isSimulatingQuickRound = false;
      }
      return;
    } else if(matchGate.status === 'already_played'){
      state.round = Math.min((state.schedule?.length || 1) - 1, (state.round || 0) + 1);
      save(); render();
      toast('📅 Rodada já disputada. Avançando para a próxima rodada.');
      return;
    } else {
      toast(`⚠️ ${matchGate.reason}`);
      return;
    }
  }

  isSimulatingQuickRound = true;
  try {
    const activeMatch = typeof getActualCurrentMatch === 'function' ? getActualCurrentMatch(state) : null;
    if(activeMatch && activeMatch.type === 'estadual' && activeMatch.competitionId && Number.isInteger(activeMatch.roundIndex)){
      isSimulatingQuickRound = false;
      return simulateQuickStateLeagueRound(activeMatch.competitionId, activeMatch.roundIndex);
    }
    if(activeMatch && activeMatch.type === 'copa' && Number.isInteger(activeMatch.fixtureIndex)){
      isSimulatingQuickRound = false;
      return playCopaDoBrasilFixture(activeMatch.fixtureIndex, activeMatch.phaseName || copaCurrentPhase);
    }
    if(activeMatch && activeMatch.type === 'continental' && activeMatch.competitionId && activeMatch.matchId){
      isSimulatingQuickRound = false;
      return playContinentalFixture(activeMatch.competitionId, activeMatch.matchId);
    }
    if(state && state.isPreSeason && state.preSeasonDays > 0){
      state.isPreSeason = false;
      state.preSeasonDays = 0;
      state.date = getDateForRound(state.round || 0, state.season);
    }
    const fixtures = currentFixtures();
    if(state.round >= (state.schedule?.length || 1)){ showEndOfSeasonModal(); return; }
    if(!fixtures.length){
      const nextRound = (state.schedule || []).findIndex((games, index) => index > state.round && Array.isArray(games) && games.some(g => Array.isArray(g) && g.length >= 2));
      if(nextRound < 0){ showEndOfSeasonModal(); return; }
      state.round = nextRound;
      state.date = getDateForRound(nextRound, state.season);
      state.news = Array.isArray(state.news) ? state.news : [];
      state.news.unshift('Rodada sem fixtures recuperada. O calendário foi sincronizado com a próxima rodada válida.');
      state.news = state.news.slice(0, 50);
      save(); render();
      toast('Calendário recuperado. A próxima rodada tem jogos para simular.');
      return;
    }
    const comp=curComp(),isKO=comp.type==='knockout';
    let userRes=null,winners=[];
    fixtures.forEach(([h,a])=>{
      let [hg,ag]=simulateScore(h,a),winner=null,pens=null;
      if(isKO){
        if(hg===ag){
          let hp=rnd(3,6),ap=rnd(2,6);if(hp===ap)ap=hp===6?5:hp+1;
          pens=[hp,ap];winner=hp>ap?h:a;
        }else winner=hg>ag?h:a;
        winners.push(winner);
      }
      applyResult(h,a,hg,ag);
      if(norm(h)===norm(state.club)||norm(a)===norm(state.club)){
        const userGoals = norm(h) === norm(state.club) ? hg : ag;
        userRes={h,a,hg,ag,winner,pens,events:simulateUserGoalEvents(state.club,userGoals)};
      }
    });

    // Finaliza a rodada sincronizando tabela e pontuação de todos os clubes
    finalizeRound(userRes, winners, isKO);
    save();
    render();

    if(userRes){
      triggerPostMatchFlow(userRes);
    }
  } finally {
    isSimulatingQuickRound = false;
  }
}

// -------------------------------------------------------------
// CERIMÔNIA DE CAMPEÃO / LEVANTAMENTO DA TAÇA ESTILO FIFA
// -------------------------------------------------------------
function showChampionTrophyCeremonyModal(comp, onProceed){
  playCheerSound();
  playWhistleSound();

  let overlay = $('#trophyCeremonyContainer');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = 'trophyCeremonyContainer';
    document.body.appendChild(overlay);
  }

  const clubName = state.club || 'Clube';
  const managerName = state.manager || 'Treinador';
  const compName = (comp?.name || 'CAMPEONATO').toUpperCase();

  // Gera pedaços de confete dourados e coloridos no DOM
  const confettis = Array.from({length: 36}).map((_, i) => {
    const left = rnd(2, 98);
    const delay = (Math.random() * 2.2).toFixed(2);
    const dur = (rnd(22, 38) / 10).toFixed(2);
    const colors = ['#facc15', '#f59e0b', '#38bdf8', '#a855f7', '#22c55e', '#ef4444', '#ffffff'];
    const col = colors[i % colors.length];
    return `<div class="confetti-piece" style="left:${left}%;animation-delay:${delay}s;animation-duration:${dur}s;background:${col}"></div>`;
  }).join('');

  overlay.innerHTML = `
    <div class="trophy-ceremony-overlay">
      ${confettis}
      <div class="trophy-ceremony-card">
        <!-- PALCO DA CERIMÔNIA -->
        <div class="trophy-stage">
          <div class="champion-badge-halo">
            ${clubBadge(clubName, 88)}
          </div>

          <div class="trophy-cup-glow" title="Taça de Campeão Oficial">
            🏆
          </div>

          <div class="trophy-podium">
            ★ CAMPEÃO OFICIAL AFM ★
          </div>
        </div>

        <!-- TÍTULO ESTILO FIFA -->
        <div class="champion-sub-fifa">GLÓRIA ETERNA & CONQUISTA HISTÓRICA</div>
        <h1 class="champion-title-fifa">É CAMPEÃO!</h1>
        <div style="font-size:18px;font-weight:900;color:#facc15;letter-spacing:1px;margin-bottom:6px">
          ${esc(compName)}
        </div>

        <!-- ELENCO CELEBRANDO EM SILHUETA / EMOJIS -->
        <div class="champion-squad-celebration">
          <span>🙌</span> <span>🎉</span> <span>⭐</span> <span>🍾</span> <span>👑</span> <span>🔥</span> <span>🙌</span>
        </div>

        <div style="font-size:14px;color:rgba(255,255,255,0.85);max-width:540px;line-height:1.5;margin:8px 0 22px 0;font-weight:700">
          O <b>${esc(clubName)}</b> sob o comando tático do <b>Professor ${esc(managerName)}</b> ergue a taça mais cobiçada e grava seu nome na história do futebol! A torcida comemora em festa inesquecível!
        </div>

        <!-- BOTÃO DE CONTINUAR -->
        <button class="btn primary" id="btnClaimTrophyCeremony" style="font-size:15px;font-weight:900;padding:12px 36px;border-radius:12px;background:linear-gradient(135deg, #eab308, #ca8a04);color:#000;border:none;box-shadow:0 0 30px rgba(234,179,8,0.7);cursor:pointer;letter-spacing:0.5px">
          🏆 ERGUER A TAÇA E RECEBER A PREMIAÇÃO ➔
        </button>
      </div>
    </div>
  `;

  $('#btnClaimTrophyCeremony').onclick = () => {
    overlay.remove();
    if(typeof onProceed === 'function') onProceed();
  };
}

// -------------------------------------------------------------
// FIM DE TEMPORADA & MERCADO DE TÉCNICOS
// -------------------------------------------------------------
function showEndOfSeasonModal(){
  const pendingCompetitions = typeof getPendingClubCompetitions === 'function' ? getPendingClubCompetitions(state) : [];
  if(pendingCompetitions.length){
    const next = pendingCompetitions[0];
    toast(`⏳ A temporada continua aberta: termine ${next.name}${next.detail ? ` (${next.detail})` : ''}${next.date ? ` em ${formatDatePtBr(next.date)}` : ''} antes de virar o ano.`);
    view = 'calendario';
    render();
    return;
  }
  const pos = position();
  const trust = state.trust.board;
  const isSatisfied = trust >= 50;
  const comp = curComp();
  const prize = calculateSeasonPrizeMoney(pos, comp);
  if(!state.seasonPrizeClaimed || state.seasonPrizeClaimed !== state.season){ state.balance += prize; state.income += prize; state.seasonPrizeClaimed = state.season; } // prize guarded
  // income handled above
  const awards = calculateSeasonAwards();
  applyScoringAwardUpgrades(awards);
  if(window.AFM_ManagerEconomy && typeof window.AFM_ManagerEconomy.processAnnualShareDividends === 'function'){
    const annualProfit = (state.income || 0) - (state.expense || 0);
    if(annualProfit > 0 && (!state.seasonDividendsClaimed || state.seasonDividendsClaimed !== state.season)){
      const dividend = window.AFM_ManagerEconomy.processAnnualShareDividends(state, annualProfit);
      state.seasonDividendsClaimed = state.season;
      if(dividend > 0){
        state.news = Array.isArray(state.news) ? state.news : [];
        state.news.unshift(`💼 DIVIDENDOS DAS COTAS: Como sócio-cotista, você recebeu R$ ${dividend.toLocaleString('pt-BR')} em dividendos do clube pelo lucro da temporada!`);
      }
    }
  }
  const otherClubs = clubs.filter(c => norm(c.name) !== norm(state.club) && strength(c) >= strength(clubByName(state.club)) - 6).sort(() => Math.random() - .5).slice(0, 3);

  const contractDateStr = state.managerContractDate || `sex, 31 dez ${state.season + 1}`;
  const contractYear = parseInt((contractDateStr.match(/\d{4}/) || [state.season + 1])[0]);
  const yearsLeft = Math.max(0, contractYear - state.season);

  // Lógica de Acesso e Rebaixamento
  let promoInfo = null;
  const isEstadual = comp?.id?.startsWith('bra-est-');

  if(isEstadual){
    // Se não tem série superior garantida (Séries A, B ou C) e fica no G-2 do estadual -> Ganha vaga na Série D!
    const savedRosters = state.competitionTeams || window.COMPETITION_TEAMS || {};
    const hasSuperiorSeries = ['bra-a','bra-b','bra-c'].some(id => (savedRosters[id] || []).some(c => norm(c) === norm(state.club)));
    if(!hasSuperiorSeries && pos <= 2){
      promoInfo = {
        type: 'promote',
        toCompId: 'bra-d',
        title: '🎉 VAGA NA SÉRIE D DO BRASILEIRÃO CONQUISTADA!',
        desc: `Pelo grande desempenho no campeonato estadual (${pos}º colocado), o ${state.club} conquistou a vaga oficial na Série D nacional!`
      };
      state.nextSeasonCompId = 'bra-d';
    }
  } else if(comp?.id === 'bra-d'){
    const dGroups = typeof getSeriesDGroupStandings === 'function' ? getSeriesDGroupStandings() : null;
    const myGroup = dGroups ? Object.values(dGroups).find(group => group.some(t => norm(t.name) === norm(state.club))) : null;
    const myGroupPos = myGroup ? (myGroup.find(t => norm(t.name) === norm(state.club))?.groupPosition || 999) : 999;
    const groupChampions = Array.isArray(state.competitionPlayoffWinners?.['bra-d']) ? state.competitionPlayoffWinners['bra-d'] : [];
    const groupChampion = myGroupPos === 1 || groupChampions.some(name => norm(name) === norm(state.club));
    if(groupChampion){
      promoInfo = {
        type: 'promote',
        toCompId: 'bra-c',
        title: '🚀 ACESSO CONQUISTADO À SÉRIE C!',
        desc: `O ${state.club} venceu seu grupo de 24 clubes e conquistou uma das quatro vagas diretas de acesso à Série C.`
      };
      state.nextSeasonCompId = 'bra-c';
    }
  } else if(comp?.id === 'bra-c'){
    const persistedCFinalGroups = Array.isArray(state.competitionFinalGroups?.['bra-c']) ? state.competitionFinalGroups['bra-c'] : [];
    const cAccessByFinalGroup = persistedCFinalGroups.some(group => Array.isArray(group) && group.slice().sort((a,b) => (Number(b.p)||0)-(Number(a.p)||0) || (Number(b.sg)||0)-(Number(a.sg)||0)).slice(0,2).some(row => norm(typeof row === 'string' ? row : row?.name) === norm(state.club)));
    if(cAccessByFinalGroup || pos <= 4){
      promoInfo = {
        type: 'promote',
        toCompId: 'bra-b',
        title: '🚀 ACESSO CONQUISTADO À SÉRIE B!',
        desc: `O ${state.club} terminou entre os primeiros colocados e subiu para a Série B.`
      };
      state.nextSeasonCompId = 'bra-b';
    } else if(pos >= 17){
      promoInfo = {
        type: 'relegate',
        toCompId: 'bra-d',
        title: '📉 REBAIXAMENTO PARA A SÉRIE D',
        desc: `Campanha abaixo do esperado (${pos}º lugar). O clube disputará a Série D no próximo ano.`
      };
      state.nextSeasonCompId = 'bra-d';
    }
  } else if(comp?.id === 'bra-b'){
    const explicitBPlayoffWinners = Array.isArray(state.competitionPlayoffWinners?.['bra-b']) ? state.competitionPlayoffWinners['bra-b'] : [];
    const bPromotedAutomatically = pos <= 2;
    const bPromotedByPlayoff = explicitBPlayoffWinners.some(name => norm(name) === norm(state.club));
    if(bPromotedAutomatically || bPromotedByPlayoff){
      promoInfo = {
        type: 'promote',
        toCompId: 'bra-a',
        title: '👑 ACESSO À ELITE! SÉRIE A DO BRASILEIRÃO!',
        desc: bPromotedAutomatically
          ? `Histórico! O ${state.club} terminou no G-2 e conquistou o acesso direto à Série A!`
          : `O ${state.club} venceu o playoff do G-4 e conquistou o acesso à Série A!`
      };
      state.nextSeasonCompId = 'bra-a';
    } else if(pos >= 17){
      promoInfo = {
        type: 'relegate',
        toCompId: 'bra-c',
        title: '📉 REBAIXAMENTO PARA A SÉRIE C',
        desc: `Terminou no Z-4 (${pos}º lugar) e disputará a Série C na próxima temporada.`
      };
      state.nextSeasonCompId = 'bra-c';
    }
  } else if(comp?.id === 'bra-a'){
    if(pos >= 17){
      promoInfo = {
        type: 'relegate',
        toCompId: 'bra-b',
        title: '📉 REBAIXAMENTO PARA A SÉRIE B',
        desc: `Terminou no Z-4 da Série A (${pos}º lugar) e jogará a Série B no ano que vem.`
      };
      state.nextSeasonCompId = 'bra-b';
    }
  }

  // Qualificação Continental por Região
  let continentalPromo = null;
  const cContinent = comp?.continent || (comp?.country === 'Brasil' ? 'América do Sul' : 'Outro');
  if(cContinent === 'América do Sul' && comp?.id === 'bra-a'){
    if(pos <= 4){
      continentalPromo = { title: '🏆 VAGA NA FASE DE GRUPOS DA LIBERTADORES!', desc: `Classificação continental épica! Pelo ${pos}º lugar no Brasileirão, o ${state.club} disputará a Copa Libertadores!` };
    } else if(pos <= 6){
      continentalPromo = { title: '🔵 VAGA NA PRÉ-LIBERTADORES!', desc: `Pelo ${pos}º lugar na Série A, o ${state.club} disputará a fase preliminar da Copa Libertadores!` };
    } else if(pos <= 12){
      continentalPromo = { title: '🥈 VAGA NA COPA SUL-AMERICANA!', desc: `Vaga internacional garantida! O ${state.club} disputará a CONMEBOL Sul-Americana!` };
    }
  } else if(cContinent === 'Europa' && !comp?.id?.includes('cup')){
    if(pos <= 4){
      continentalPromo = { title: '🌟 VAGA NA UEFA CHAMPIONS LEAGUE!', desc: `G4 europeu conquistado (${pos}º lugar)! O clube disputará a fase de liga da UEFA Champions League!` };
    } else if(pos <= 6){
      continentalPromo = { title: '🥈 VAGA NA UEFA EUROPA LEAGUE!', desc: `Vaga europeia garantida! O clube disputará a UEFA Europa League (${pos}º lugar)!` };
    }
  } else if(cContinent === 'Ásia' && !comp?.id?.includes('cup')){
    if(pos <= 3){
      continentalPromo = { title: '🌟 VAGA NA AFC CHAMPIONS LEAGUE ELITE!', desc: `Top 3 conquistado (${pos}º lugar)! O clube disputará a AFC Champions League Elite!` };
    }
  }

  if(pos === 1){
    registerTrophyInMuseum(state, comp.name, state.season);
    state.news.unshift(`🏆 TÍTULO HISTÓRICO: O ${state.club} sagrou-se CAMPEÃO do ${comp.name} na Temporada ${state.season}!`);
  }

  const userTitlesInSeason = [];
  if(pos === 1 && comp?.name){ userTitlesInSeason.push(comp.name); }
  const copaStateModal = typeof getCopaDoBrasilState === 'function' ? getCopaDoBrasilState() : null;
  if(copaStateModal?.champion && norm(copaStateModal.champion) === norm(state.club)){ if(!userTitlesInSeason.includes('Copa do Brasil')) userTitlesInSeason.push('Copa do Brasil'); }
  for(const [tId, tourney] of Object.entries(state.tournaments || {})){
    if(Number(tourney?.season) === Number(state.season) && norm(tourney?.champion || tourney?.winner) === norm(state.club)){
      const tourneyName = compById(tId)?.name || tourney.name || tId;
      if(!userTitlesInSeason.includes(tourneyName)) userTitlesInSeason.push(tourneyName);
    }
  }
  const eliminations = (state.knockoutEliminations || []).filter(item => Number(item.season) === Number(state.season) && norm(item.club) === norm(state.club));
  const knockoutEliminationHtml = eliminations.length ? `<div style="background:rgba(239,68,68,.16);border:2px solid #ef4444;border-radius:12px;padding:12px 14px;margin-top:10px;text-align:left"><b style="display:block;color:#f87171;font-size:13px;text-transform:uppercase">Mata-Mata / Copas</b>${eliminations.map(elimination => `<div style="font-size:12px;color:#fca5a5;margin-top:4px;font-weight:700">Infelizmente você não passou do mata-mata — Eliminado na ${esc(elimination.round ? `Fase ${elimination.round}` : 'Fase eliminatória')} da ${esc(elimination.competitionName || elimination.competitionId || comp?.name || 'Competição')} para ${esc(elimination.opponent || 'Adversário')} (${esc(elimination.score || 'resultado definitivo')})</div>`).join('')}</div>` : '';
  const painelMinhasConquistasHtml = `
    <div class="card" style="margin-bottom:14px;background:linear-gradient(135deg,#18142e,#0f172a);border:1.5px solid #6366f1;border-radius:14px;padding:16px;box-shadow:0 0 20px rgba(99,102,241,0.2)">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px">
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:22px">🏆</span>
          <h3 style="margin:0;color:#facc15;font-size:15px;font-weight:900">Minhas Conquistas & Campanha na Temporada</h3>
        </div>
        <button class="btn" id="btnOpenWorldSaveChampionsModalModal" type="button" style="padding:6px 12px;font-size:11px;font-weight:900;background:rgba(56,189,248,0.15);border:1px solid #38bdf8;color:#38bdf8;border-radius:8px;cursor:pointer">
          🌍 Ver Campeões do Mundo do Save
        </button>
      </div>
      <div style="background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:10px 14px;margin-bottom:10px">
        <div style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:0.5px">Títulos Conquistados (${state.season})</div>
        ${userTitlesInSeason.length ? `
          <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:6px">
            ${userTitlesInSeason.map(t => `<span class="pill good" style="font-size:12px;font-weight:900;padding:4px 10px">🏆 ${esc(t)}</span>`).join('')}
          </div>
        ` : `
          <div style="font-size:12px;color:#cbd5e1;font-weight:700;margin-top:4px">Nenhum título conquistado nesta temporada.</div>
        `}
      </div>
      <div style="background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:10px 14px">
        <div style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:0.5px">Divisão & Desempenho na Tabela</div>
        <div style="font-size:13px;font-weight:800;color:#fff;margin-top:4px">
          ${esc(comp?.name || state.competition || 'Campeonato')}: <b>${pos}º colocado</b>
        </div>
        ${promoInfo ? `
          <div style="margin-top:6px;font-size:12px;font-weight:800;color:${promoInfo.type==='promote'?'#4ade80':'#f87171'}">
            ${promoInfo.title} — ${promoInfo.desc}
          </div>
        ` : `
          <div style="margin-top:4px;font-size:11px;color:#94a3b8">
            🛡️ Permanência na divisão garantida para a próxima temporada.
          </div>
        `}
      </div>
      ${knockoutEliminationHtml}
    </div>
  `;

  openCustomModal(
    `🏆 Encerramento da Temporada ${state.season}`,
    `
      <div style="text-align:center;margin-bottom:14px">
        <div class="muted">Seu clube finalizou a competição em <b>${pos}º lugar</b>.</div>
      </div>

      ${painelMinhasConquistasHtml}

      ${promoInfo ? `
        <div style="background:${promoInfo.type==='promote'?'rgba(34,197,94,0.18)':'rgba(239,68,68,0.18)'};border:2px solid ${promoInfo.type==='promote'?'#22c55e':'#ef4444'};border-radius:12px;padding:12px 16px;margin-bottom:14px;text-align:center">
          <div style="font-size:13px;font-weight:900;color:${promoInfo.type==='promote'?'#4ade80':'#f87171'}">${promoInfo.title}</div>
          <div style="font-size:12px;color:#fff;margin-top:4px">${promoInfo.desc}</div>
        </div>
      ` : ''}

      ${continentalPromo ? `
        <div style="background:rgba(56,189,248,0.18);border:2px solid #38bdf8;border-radius:12px;padding:12px 16px;margin-bottom:14px;text-align:center">
          <div style="font-size:13px;font-weight:900;color:#38bdf8">${continentalPromo.title}</div>
          <div style="font-size:12px;color:#fff;margin-top:4px">${continentalPromo.desc}</div>
        </div>
      ` : ''}

      <div style="background:rgba(34,197,94,0.15);border:1px solid #22c55e;border-radius:12px;padding:12px;margin-bottom:14px;text-align:center">
        <div style="font-size:12px;font-weight:800;color:#86efac;text-transform:uppercase">💰 Premiação Oficial da Competição</div>
        <div style="font-size:20px;font-weight:900;color:#22c55e;margin-top:2px">+${fmtMoney(prize)} creditados no caixa do clube!</div>
      </div>

      <div class="card" style="margin-bottom:14px;background:#141c26;padding:14px">
        <h4 style="margin:0 0 10px 0;color:#facc15">🏅 Premiações Individuais da Temporada</h4>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;font-size:12px;text-align:center">
          <div style="background:rgba(255,255,255,0.04);padding:8px;border-radius:8px">
            <div style="font-size:16px">👑</div>
            <b style="color:#fff">${esc(awards.bestPlayer.name)}</b>
            <div class="small muted">Craque do Ano (${awards.bestPlayer.ovr} OVR)</div>
          </div>
          <div style="background:rgba(255,255,255,0.04);padding:8px;border-radius:8px">
            <div style="font-size:16px">👟</div>
            <b style="color:#fff">${esc(awards.topScorer.name)}</b>
            <div class="small muted">Chuteira de Ouro (${awards.topScorer.goals} gols)</div>
          </div>
          <div style="background:rgba(255,255,255,0.04);padding:8px;border-radius:8px">
            <div style="font-size:16px">🎯</div>
            <b style="color:#fff">${esc(awards.assistLeader.name)}</b>
            <div class="small muted">Líder em assistências (${awards.assistLeader.assists})</div>
          </div>
          <div style="background:rgba(255,255,255,0.04);padding:8px;border-radius:8px">
            <div style="font-size:16px">🧤</div>
            <b style="color:#fff">${esc(awards.goldenGlove.name)}</b>
            <div class="small muted">Luva de Ouro (${awards.goldenGlove.ovr} OVR)</div>
          </div>
        </div>
      </div>

      <div class="grid g2">
        <div class="card">
          <h3>Avaliação da Diretoria</h3>
          <p>Confiança: <b>${state.trust.board}%</b> • Torcida: <b>${state.trust.fans}%</b></p>
          <p>${isSatisfied ? '✅ A diretoria está muito satisfeita e quer renovar seu contrato!' : '⚠️ Campanha abaixo do esperado, mas aceita permanência.'}</p>
          <button class="btn primary" id="renewContractBtn" style="width:100%;margin-top:10px;font-weight:800">📝 Renovar com ${esc(state.club)} (+15% salário)</button>

          <!-- VALIDADE DO CONTRATO ATUAL -->
          <div style="margin-top:12px;padding:10px 12px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.12);border-radius:8px">
            <div style="font-size:11px;font-weight:800;color:rgba(255,255,255,0.6);text-transform:uppercase;letter-spacing:0.5px">
              📄 Vínculo Atual com o Clube
            </div>
            <div style="font-size:14px;font-weight:900;color:#38bdf8;margin:3px 0">
              ${esc(contractDateStr)}
            </div>
            <div style="font-size:11px;color:${yearsLeft <= 0 ? '#ef4444' : '#22c55e'};line-height:1.4">
              ${yearsLeft <= 0
                ? '⚠️ <b>Seu contrato expira nesta virada de temporada!</b> Renove ou assuma outro clube para não ficar desempregado.'
                : `✅ <b>Vínculo ativo:</b> Você tem mais <b>${yearsLeft} ${yearsLeft === 1 ? 'temporada garantida' : 'temporadas garantidas'}</b> por contrato.`}
            </div>
          </div>
        </div>
        <div class="card">
          <h3>Propostas de Outros Clubes</h3>
          <div class="small muted" style="margin-bottom:8px">Clubes interessados no seu trabalho:</div>
          ${otherClubs.map(c => `
            <div style="display:flex;justify-content:space-between;align-items:center;padding:8px;background:var(--panel2);border-radius:8px;margin-bottom:6px">
              <div style="display:flex;align-items:center;gap:8px">
                ${clubBadge(c.name, 28)}
                <div><b>${esc(c.name)}</b><div class="small muted">${esc(c.competition)}</div></div>
              </div>
              <button class="btn success btnAcceptJob" data-club="${esc(c.name)}">Assumir</button>
            </div>
          `).join('')}
        </div>
      </div>
      <div style="margin-top:20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
        <button class="btn" id="btnOpenBallonDorTop" style="padding:14px 22px;font-size:14px;font-weight:900;background:linear-gradient(135deg,#eab308,#ca8a04);color:#000;border:none;border-radius:12px;cursor:pointer;display:flex;align-items:center;gap:8px">
          <span>🏆 GALA DA BOLA DE OURO & SELEÇÃO DO ANO</span> <span>🌟</span>
        </button>
        <button class="btn primary" id="closeEndSeasonBtn" style="padding:16px 28px;font-size:15px;font-weight:900;background:linear-gradient(135deg, #10b981, #059669);color:#fff;border:none;border-radius:12px;box-shadow:0 8px 25px rgba(16,185,129,0.45);cursor:pointer;display:flex;align-items:center;gap:8px">
          <span>🚀 VIRAR O ANO & INICIAR TEMPORADA ${state.season + 1}</span> <span>➔</span>
        </button>
      </div>
    `,
    () => {
      advanceSeasonYear();
    }
  );

  const bGala = $('#btnOpenBallonDorTop');
  if(bGala) bGala.onclick = () => window.AFM30 && window.AFM30.openBallonDorGalaModal(state);

  const renew = $('#renewContractBtn');
  if(renew) renew.onclick = () => {
    state.managerSalary = Math.round(state.managerSalary * 1.15);
    const renewalBonus = state.managerSalary * 2;
    state.managerMoney += renewalBonus;
    if(state.managerPersonal) state.managerPersonal.personalBalance = (Number(state.managerPersonal.personalBalance) || 0) + renewalBonus;
    state.trust.board = clamp(state.trust.board + 10, 0, 100);
    const newYear = Math.max(state.season + 2, contractYear + 1);
    state.managerContractDate = `qui, 31 dez ${newYear}`;
    toast(`Contrato renovado até ${state.managerContractDate}! (+15% salário)`);
    closeCustomModal();
    advanceSeasonYear();
  };

  $$('.btnAcceptJob').forEach(btn => {
    btn.onclick = () => {
      const newClub = btn.dataset.club;
      if(window.AFM_WorldSimulation && typeof window.AFM_WorldSimulation.canCoachAcceptClubWithLicense === 'function'){
        const check = window.AFM_WorldSimulation.canCoachAcceptClubWithLicense(state, newClub);
        if(!check.allowed){
          alert(`🚫 Proposta recusada por falta de escolaridade técnica!\n\nPara assumir o ${newClub}, é exigida a Licença: ${check.requiredLicenseName}.\n\nVocê possui: ${check.currentLicenseName}.\nAdquira novas licenças no menu Carreira.`);
          return;
        }
      }
      closeCustomModal();
      changeUserClub(newClub);
    };
  });

  const closeBtn = $('#closeEndSeasonBtn');
  const btnWorldSaveModal = $('#btnOpenWorldSaveChampionsModalModal'); if(btnWorldSaveModal) btnWorldSaveModal.onclick = openWorldSaveChampionsModal;
  if(closeBtn) closeBtn.onclick = () => { try { closeCustomModal(); advanceSeasonYear(); } catch(err) { console.error('[AFM closeEndSeasonBtn Error]', err); advanceSeasonYear(); } };



}

function executeSeasonTransitions(finishedCompId = null, finishedRanking = null, requestedDestinationCompId = null, sourceNationalDivision = null, finalSeasonSnapshot = null){
  const divisionIds = ['bra-a','bra-b','bra-c','bra-d'];
  const stateCompIds = ['bra-est-df','bra-est-sp','bra-est-rj','bra-est-mg','bra-est-rs','bra-est-pr','bra-est-sc','bra-est-ba','bra-est-ce','bra-est-go','bra-est-pe'];
  // Every seasonal movement belongs exclusively to the active career. Clone the
  // persisted save rosters (or the immutable base catalog for older saves) and
  // never write them back to window.COMPETITION_TEAMS/teamMap.
  const tMap = clone(state.competitionTeams && typeof state.competitionTeams === 'object'
    ? state.competitionTeams
    : (BASE_COMPETITION_TEAMS || window.COMPETITION_TEAMS || {}));
  const uniqueNames = names => [...new Map((Array.isArray(names) ? names : []).filter(name => typeof name === 'string' && name.trim()).map(name => [norm(name), name])).values()];
  const myClubName = String(state.club || '').trim();
  const myNorm = norm(myClubName);
  const lists = Object.fromEntries(divisionIds.map(id => [id, uniqueNames(tMap[id]).slice(0, id === 'bra-d' ? Math.max(1, Number(compById('bra-d')?.teams) || 96) : 20)]));
  // Keep a snapshot of every state-league roster; national movements cannot rewrite it.
  const preservedStateRosters = Object.fromEntries(stateCompIds.map(id => [id, uniqueNames(tMap[id])]));
  // CRITICAL SYSTEM: division movement must use saved seasonal standings, not
  // historical BASE_COMPETITION_TEAMS. Group/playoff promotions require real
  // persisted qualifiers/winners; absence of these results must not invent them.
  const integrityService = window.AFM_COMPETITION_INTEGRITY;
  let criticalPipelineHandled = false;
  if(integrityService && finalSeasonSnapshot){
    criticalPipelineHandled = true;
    const snapshot = finalSeasonSnapshot;
    const plan = integrityService.simulateBrazilSeason
      ? integrityService.simulateBrazilSeason(lists, Number(snapshot.season), divisionIds.includes(finishedCompId) ? finishedCompId : null, divisionIds.includes(finishedCompId) ? finishedRanking : null, window.AFM_TOURNAMENT_ENGINE, {}, {
          requestedDestinationCompId: divisionIds.includes(requestedDestinationCompId) ? requestedDestinationCompId : null,
          userClub: state.club,
          sourceCompId: finishedCompId,
          stateRosters: tMap
        })
      : { valid: false, issues: [{ code: 'season-pipeline-unavailable' }], rosters: lists };
    if(plan.valid && integrityService.audit(plan.rosters).valid){
      for(const id of divisionIds) lists[id] = plan.rosters[id];
      Object.entries(plan.stateRosterUpdates || {}).forEach(([id, roster]) => { tMap[id] = roster; });
      if(requestedDestinationCompId && divisionIds.includes(requestedDestinationCompId)) state.compId = requestedDestinationCompId;
      const activeDivision = divisionIds.includes(requestedDestinationCompId) ? requestedDestinationCompId
        : divisionIds.find(id => lists[id].some(name => norm(name) === norm(state.club))) || state.compId;
      if(divisionIds.includes(activeDivision)){
        state.compId = activeDivision;
        const activeComp = compById(activeDivision);
        if(activeComp){state.competition=activeComp.name;state.currentLeague=activeComp.name;}
      }
      state.competitionIntegrity = { season: Number(snapshot.season), valid: true, checkedAt: new Date().toISOString(), movements: plan.movers };
      state.nationalCompetitionStandings = plan.standings;
      state.competitionFinalGroups = plan.finalGroups;
      state.competitionGroupStandings = plan.groupStandings;
      state.competitionPlayoffWinners = plan.playoffWinners;
      state.competitionHistory = state.competitionHistory || [];
      const historyItem = state.competitionHistory.find(item => Number(item.season) === Number(snapshot.season) && item.competitionId === snapshot.competitionId);
      if(historyItem){
        historyItem.nationalStandings = plan.standings;
        historyItem.finalGroups = plan.finalGroups;
        historyItem.groupStandings = plan.groupStandings;
        historyItem.playoffWinners = plan.playoffWinners;
        historyItem.nationalMovements = plan.movers;
      }
      // Qualification registry is save data, keyed by destination season.
      // Missing league tables leave competitions pending; historical 2026 lists
      // are never silently recycled as qualified teams.
      state.continentalQualifications = state.continentalQualifications || {};
      const leagueTables = { ...(state.internationalLeagueStandings?.[Number(snapshot.season)] || {}), ...plan.standings };
      // Complete world standings from the competitions/participants already in
      // the save. This simulates matches and stores resulting tables; it does
      // not infer qualifications from static array order or historic metadata.
      const qualificationLeagueIds = ['arg-1','uru-1','chi-1','col-1','par-1','ecu-1','per-1','bol-1','ven-1',
        'eng-1','esp-1','ita-1','ger-1','fra-1','por-1','ned-1','bel-1','tur-1','sco-1','aut-1','sui-1','gre-1','cro-1','ser-1','cze-1','den-1','nor-1','swe-1',
        'ksa-1','jpn-1','kor-1','chn-1','qat-1','uae-1','irn-1','ind-1','aus-1','tha-1'];
      for(const leagueId of qualificationLeagueIds){
        const comp = compById(leagueId);
        if(!comp || (Array.isArray(leagueTables[leagueId]) && leagueTables[leagueId].length >= (Number(comp.teams)||1))) continue;
        const participants = Array.isArray(tMap[leagueId]) && tMap[leagueId].length
          ? [...tMap[leagueId]]
          : (typeof eligibleClubNames === 'function' ? eligibleClubNames(comp) : []);
        if(participants.length < (Number(comp.teams)||1)) continue;
        const simulated = integrityService.simulateTable?.(participants, Number(snapshot.season), leagueId, window.AFM_TOURNAMENT_ENGINE, {}, `${snapshot.season}|${leagueId}`);
        if(simulated?.complete && simulated.standings.length === participants.length) leagueTables[leagueId] = simulated.standings;
      }
      state.internationalLeagueStandings = state.internationalLeagueStandings || {};
      state.internationalLeagueStandings[Number(snapshot.season)] = leagueTables;
      const cupWinners = { ...(state.cupWinnersBySeason?.[Number(snapshot.season)] || {}), ...(snapshot.cupWinners || {}) };
      const champions = { ...(state.continentalChampionsBySeason?.[Number(snapshot.season)] || {}) };
      Object.entries(state.tournaments || {}).forEach(([id, tournament]) => {
        if(Number(tournament?.season) !== Number(snapshot.season)) return;
        if(tournament.champion) champions[id] = tournament.champion;
        const played = (tournament.matches || []).filter(match => match.status === 'played' && match.winner);
        if(played.length && tournament.phase === 'final') champions[id] = played[played.length - 1].winner;
      });
      const qualificationPlan = integrityService.buildContinentalQualifications?.(Number(snapshot.season), leagueTables, cupWinners, champions, state.worldClubRanking?.[Number(snapshot.season)] || []);
      if(qualificationPlan){
        state.continentalQualifications[Number(snapshot.season) + 1] = qualificationPlan;
        state.continentalQualificationHistory = state.continentalQualificationHistory || [];
        state.continentalQualificationHistory.unshift({ fromSeason:Number(snapshot.season), toSeason:Number(snapshot.season)+1, competitions:qualificationPlan });
        state.continentalQualificationHistory = state.continentalQualificationHistory.slice(0, 20);
      }
      if(plan.movers.length){
        state.news = Array.isArray(state.news) ? state.news : [];
        state.news.unshift(`🏟️ PIRÂMIDE NACIONAL: ${plan.movers.length} movimentos de divisão processados para a temporada ${Number(snapshot.season) + 1}.`);
        state.news = state.news.slice(0, 50);
      }
    } else {
      // Never apply a partial movement that would silently drop a club.
      state.competitionIntegrity = { season: Number(snapshot.season), valid: false, checkedAt: new Date().toISOString(), issues: plan.issues };
      state.news = Array.isArray(state.news) ? state.news : [];
      state.news.unshift('⚠️ INTEGRIDADE CRÍTICA: movimentações bloqueadas porque o resultado não preservaria a capacidade oficial. Os rosters foram mantidos para evitar perda de clubes.');
      state.news = state.news.slice(0, 50);
      // Roll back any tentative destination: a blocked reclassification must
      // not leave compId and roster membership pointing at different leagues.
      if(divisionIds.includes(finishedCompId)) state.compId = finishedCompId;
      else if(sourceNationalDivision && lists[sourceNationalDivision]?.some(name => norm(name) === myNorm)) state.compId = finishedCompId;
    }
  }
  if(criticalPipelineHandled){
    // Never run the legacy base-roster filler after evaluating this season.
    for(const id of divisionIds) tMap[id] = uniqueNames(lists[id]);
    const expectedStateId = state?.customClubStateCompId || (['brasilia','aruc','gama','ceilandia','sobradinho','samambaia','paranoa','capital-df','real brasilia','brasiliense'].includes(myNorm) ? 'bra-est-df' : null);
    for(const id of stateCompIds) tMap[id] = uniqueNames([...(preservedStateRosters[id] || []), ...uniqueNames(tMap[id]), ...(id === expectedStateId && myClubName ? [myClubName] : [])]);
    state.competitionTeams = clone(tMap);
    state.news = Array.isArray(state.news) ? state.news : [];
    state.news = state.news.slice(0, 50);
    return;
  }
  const originalNationalKeys = new Set(divisionIds.flatMap(id => uniqueNames(tMap[id]).map(norm)));
  const capacities = {
    'bra-a': 20,
    'bra-b': 20,
    'bra-c': 20,
    'bra-d': Math.max(1, Number(compById('bra-d')?.teams) || 96)
  };
  // Capture todos os nomes nacionais originais antes do truncamento por capacidade;
  // um clube descartado por excesso não pode voltar pelo pool de preenchimento.
  const destination = divisionIds.includes(requestedDestinationCompId) ? requestedDestinationCompId : null;
  let source = divisionIds.includes(sourceNationalDivision) ? sourceNationalDivision : null;
  if(!source && divisionIds.includes(finishedCompId)) source = finishedCompId;
  if(!source && divisionIds.includes(state.compId)) source = state.compId;
  if(!source && myNorm) source = divisionIds.find(id => lists[id].some(name => norm(name) === myNorm)) || null;
  const previousNationalMemberships = divisionIds.filter(id => lists[id].some(name => norm(name) === myNorm));

  const previousTargetIndex = destination ? lists[destination].findIndex(name => norm(name) === myNorm) : -1;
  let displacedFromDestination = null;
  if(destination && destination !== source && myNorm){
    for(const id of divisionIds) lists[id] = lists[id].filter(name => norm(name) !== myNorm);
    const target = lists[destination];
    if(previousTargetIndex < 0 && target.length >= capacities[destination]) displacedFromDestination = target.pop() || null;
    target.splice(Math.min(previousTargetIndex >= 0 ? previousTargetIndex : target.length, target.length), 0, myClubName);
    state.compId = destination;
    // O clube que cede a vaga no destino ocupa a vaga aberta na divisão de origem.
    // Isso preserva o tamanho dos elencos sem perder um clube do mapa nacional.
    if(source && source !== destination && displacedFromDestination){
      const sourceList = lists[source];
      if(!sourceList.some(name => norm(name) === norm(displacedFromDestination))){
        if(sourceList.length >= capacities[source]) sourceList.pop();
        sourceList.push(displacedFromDestination);
      }
    }
    // CRITICAL INVARIANT: national division swaps must never alter state-league rosters.
    // The promoted club remains registered in its estadual after moving between A-D.
  } else if(source && myNorm){
    // Sem um destino explícito, o fim de uma copa/estadual não é promoção nem rebaixamento.
    for(const id of divisionIds){
      if(id !== source) lists[id] = lists[id].filter(name => norm(name) !== myNorm);
    }
    if(!lists[source].some(name => norm(name) === myNorm)){
      let displaced = null;
      if(lists[source].length >= capacities[source]) displaced = lists[source].pop() || null;
      lists[source].push(myClubName);
      const oldDivision = previousNationalMemberships.find(id => id !== source);
      if(displaced && oldDivision && lists[oldDivision].length < capacities[oldDivision] && !lists[oldDivision].some(name => norm(name) === norm(displaced))){
        lists[oldDivision].push(displaced);
      }
    }
  }

  // Remove sobreposições entre as divisões mantendo a primeira inscrição válida (A → D).
  const globallyAssigned = new Set();
  for(const id of divisionIds){
    lists[id] = uniqueNames(lists[id]).filter(name => {
      const key = norm(name);
      if(globallyAssigned.has(key)) return false;
      globallyAssigned.add(key);
      return true;
    });
  }

  // Só preenche vagas com clubes sem divisão nacional cadastrada; não inventa classificações.
  // Preenche primeiro com clubes do catálogo-base da própria divisão, sem mover quem já está noutra Série.
  for(const id of divisionIds){
    for(const candidate of uniqueNames(BASE_COMPETITION_TEAMS?.[id])){
      if(lists[id].length >= capacities[id]) break;
      const key = norm(candidate);
      if(!key || globallyAssigned.has(key)) continue;
      lists[id].push(candidate);
      globallyAssigned.add(key);
    }
  }
  const candidatePool = [];
  const candidateKeys = new Set();
  const addCandidates = names => {
    for(const name of Array.isArray(names) ? names : []){
      if(typeof name !== 'string' || !name.trim()) continue;
      const key = norm(name);
      if(key && !originalNationalKeys.has(key) && !candidateKeys.has(key)){
        candidateKeys.add(key);
        candidatePool.push(name);
      }
    }
  };
  for(const [compId, names] of Object.entries(tMap)) if(!divisionIds.includes(compId)) addCandidates(names);
  addCandidates(['Santos','Sport','América-MG','Goiás','Coritiba','Ceará','Novorizontino','Mirassol','Operário-PR','Vila Nova','Ponte Preta','Avaí','CRB','Amazonas','Chapecoense','Botafogo-SP','Paysandu','Ituano','Brusque','Guarani','Retrô','Anápolis','Maringá','Itabaiana','Brasiliense','Capital-DF','Gama','Ceilândia','Treze','Iguatu','Manaus','Nova Iguaçu','Altos','Porto Velho','Princesa do Solimões','Águia de Marabá','Santa Cruz','América-RN','Inter de Limeira','Água Santa']);
  for(const id of divisionIds){
    for(const candidate of candidatePool){
      if(lists[id].length >= capacities[id]) break;
      const key = norm(candidate);
      if(!globallyAssigned.has(key)){
        lists[id].push(candidate);
        globallyAssigned.add(key);
      }
    }
  }

  // Restore all state registrations after national promotion/relegation and roster repair.
  const expectedStateId = ['brasilia','aruc','gama','ceilandia','sobradinho','samambaia','paranoa','capital-df','real brasilia','brasiliense'].includes(myNorm) ? 'bra-est-df' : null;
  for(const id of stateCompIds) tMap[id] = uniqueNames([...(preservedStateRosters[id] || []), ...uniqueNames(tMap[id]), ...(id === expectedStateId && myClubName ? [myClubName] : [])]);

  for(const id of divisionIds) tMap[id] = lists[id];
  state.competitionTeams = clone(tMap);
  state.news = Array.isArray(state.news) ? state.news : [];
  if(destination && destination !== source){
    state.news.unshift(`🔁 VIRADA DE DIVISÃO: ${myClubName} disputará ${compById(destination)?.name || destination} na temporada ${state.season}. As outras divisões não foram reclassificadas sem tabelas simuladas.`);
    state.news = state.news.slice(0, 50);
  }
}



function advanceSeasonYear(){
  try {
  const pendingCompetitions = typeof getPendingClubCompetitions === 'function' ? getPendingClubCompetitions(state) : [];
  if(pendingCompetitions.length){
    const next = pendingCompetitions[0];
    toast(`🚫 VIRADA DO ANO BLOQUEADA: ainda falta disputar ${next.name}${next.detail ? ` (${next.detail})` : ''}${next.date ? ` em ${formatDatePtBr(next.date)}` : ''}. Conclua todas as competições da temporada.`);
    view = 'calendario';
    render();
    return false;
  }
  // 1. Registra Snapshot Histórico no Hall da Fama da Carreira
  const finishedYear = state.season;
  if(window.AFM_LifeAndSharesPro?.recordSeasonCareerSnapshot){
    window.AFM_LifeAndSharesPro.recordSeasonCareerSnapshot(state, finishedYear);
  }
  const compFinished = curComp();
  const rankingTable = ranking();
  const finishedPosition = position();
  const finishedTeamCount = Math.max(1, state.teams?.length || 1);
  const prize = (typeof calculateSeasonPrizeMoney === 'function' ? calculateSeasonPrizeMoney(finishedPosition, compFinished) : 0) || 0;
  simulateRemainingWorldTournaments(finishedYear);
  // CRITICAL SYSTEM: capture final competition state before season reset.
  // Promotions and qualification are derived from this immutable snapshot,
  // never from newly reset standings or historical club metadata.
  const finalSeasonSnapshot = {
    season: Number(finishedYear),
    competitionId: compFinished?.id || state.compId,
    competitionName: compFinished?.name || state.competition || 'Campeonato',
    ranking: JSON.parse(JSON.stringify(rankingTable || [])),
    cupWinners: { 'bra-cup': getCopaDoBrasilState()?.champion || null },
    groupStandings: JSON.parse(JSON.stringify(state.competitionFinalGroups || {})),
    playoffWinners: JSON.parse(JSON.stringify(state.competitionPlayoffWinners || {}))
  };
  state.competitionHistory = Array.isArray(state.competitionHistory) ? state.competitionHistory : [];
  state.competitionHistory = state.competitionHistory.filter(item => Number(item.season) !== Number(finishedYear) || item.competitionId !== finalSeasonSnapshot.competitionId);
  state.competitionHistory.unshift(finalSeasonSnapshot);
  state.competitionHistory = state.competitionHistory.slice(0, 200);
  // Arquivo anual do universo desta carreira, usando somente resultados e
  // participantes persistidos no save ativo.
  const yearCompetitions = new Map();
  const addYearCompetition = (id, name, champion) => {
    if(!champion || !String(champion).trim()) return;
    const competitionId = String(id || name || 'competition');
    yearCompetitions.set(`${Number(finishedYear)}|${competitionId}`, { id:competitionId, name:name || competitionId, champion:String(champion) });
  };
  addYearCompetition(compFinished?.id || state.compId, compFinished?.name || state.competition || 'Campeonato', rankingTable?.[0]?.name);
  const copaData = getCopaDoBrasilState();
  addYearCompetition('bra-cup', 'Copa do Brasil', copaData?.champion);
  for(const [id, champion] of Object.entries(state.continentalChampionsBySeason?.[Number(finishedYear)] || {})){
    addYearCompetition(id, compById(id)?.name || id, champion);
  }
  for(const [id, champion] of Object.entries(state.cupWinnersBySeason?.[Number(finishedYear)] || {})){
    addYearCompetition(id, compById(id)?.name || (id === 'bra-cup' ? 'Copa do Brasil' : id), champion);
  }
  for(const [competitionId, tournament] of Object.entries(state.tournaments || {})){
    if(Number(tournament?.season) !== Number(finishedYear)) continue;
    const matches = Array.isArray(tournament.matches) ? tournament.matches : [];
    const completed = matches.length > 0 && matches.every(match => ['played','complete','finished'].includes(String(match.status || '').toLowerCase()));
    if(completed){
      const finalMatch = matches.slice().reverse().find(match => match.winner || match.result);
      const champion = tournament.champion || tournament.winner || (tournament.phase === 'final' ? finalMatch?.winner : null);
      addYearCompetition(competitionId, compById(competitionId)?.name || tournament.name || competitionId, champion);
    }
  }
  const addChampionFromTable = (id, rows, name) => {
    if(!Array.isArray(rows) || !rows.length || !rows.some(row => Number(row?.j ?? row?.played ?? 0) > 0)) return;
    const sorted = rows.slice().sort((a,b)=>(Number(b?.p ?? b?.points)||0)-(Number(a?.p ?? a?.points)||0)||((Number(b?.gp)||0)-(Number(b?.gc)||0))-((Number(a?.gp)||0)-(Number(a?.gc)||0)));
    const required = id === 'bra-d' ? 4 : (Number(compById(id)?.teams) || 1);
    if(sorted.length < required) return;
    addYearCompetition(id, name || compById(id)?.name || id, sorted[0]?.name);
  };
  for(const id of ['bra-a','bra-b','bra-c','bra-d']){
    const rows = id === state.compId ? state.teams : state.nationalCompetitionStandings?.[id];
    addChampionFromTable(id, rows, compById(id)?.name || id);
  }
  for(const [id, rows] of Object.entries(state.internationalLeagueStandings?.[Number(finishedYear)] || {})){
    addChampionFromTable(id, rows, compById(id)?.name || id);
  }
  if(state.competitionPlayoffWinners?.['bra-d']){
    const dWinners = state.competitionPlayoffWinners['bra-d'];
    const dChamp = Array.isArray(dWinners) ? (dWinners[0] || 'Brasiliense') : dWinners;
    addYearCompetition('bra-d', compById('bra-d')?.name || 'Campeonato Brasileiro Série D', dChamp);
  }
  if(state.estadualData){
    for(const [cId, est] of Object.entries(state.estadualData)){
      if(!est) continue;
      const sortedEst = (est.teams || []).slice().sort((a,b)=>(Number(b.p)||0)-(Number(a.p)||0)||((Number(b.gp)||0)-(Number(b.gc)||0))-((Number(a.gp)||0)-(Number(a.gc)||0)));
      if(sortedEst.length && sortedEst[0]?.j > 0){
        addYearCompetition(cId, est.name || compById(cId)?.name || 'Campeonato Estadual', sortedEst[0]?.name);
      }
    }
  }
  addYearCompetition('bra-cup', 'Copa do Brasil', copaData?.champion);
  const achievements = [];
  if(Number(finishedPosition) === 1) achievements.push(`Campeão de ${compFinished?.name || state.competition || 'Campeonato'}`);
  if(Number(finishedPosition) === 2) achievements.push(`Vice-Campeão de ${compFinished?.name || state.competition || 'Campeonato'}`);
  const clubChampionships = [...yearCompetitions.values()].filter(item => norm(item.champion) === norm(state.club));
  for(const item of clubChampionships){
    const achievement = `Título: ${item.name}`;
    if(!achievements.includes(achievement)) achievements.push(achievement);
    registerTrophyInMuseum(state, item.name, finishedYear);
  }
  if(state.nextSeasonCompId && state.nextSeasonCompId !== state.compId){
    const label = window.AFM_TitlesAndHistoryService ? window.AFM_TitlesAndHistoryService.getDivisionMovementLabel(state.compId, state.nextSeasonCompId) : (['bra-a','bra-b','bra-c','bra-d'].indexOf(state.nextSeasonCompId) < ['bra-a','bra-b','bra-c','bra-d'].indexOf(state.compId) || !['bra-a','bra-b','bra-c','bra-d'].includes(state.compId) ? 'Acesso' : 'Rebaixamento');
    achievements.push(`${label} para ${compById(state.nextSeasonCompId)?.name || state.nextSeasonCompId}`);
    if(window.AFM_ManagerEconomy && typeof window.AFM_ManagerEconomy.onDivisionChangeUpdateSharePrice === 'function'){
      window.AFM_ManagerEconomy.onDivisionChangeUpdateSharePrice(state, label === 'Acesso', label === 'Rebaixamento');
    }
  }
  const yearEliminations = (state.knockoutEliminations || []).filter(item => Number(item.season) === Number(finishedYear) && norm(item.club) === norm(state.club)).map(item => ({ competitionId:item.competitionId, competitionName:item.competitionName, round:item.round, opponent:item.opponent, score:item.score, date:item.date }));
  if(yearEliminations.length) achievements.push(...yearEliminations.map(item => `Eliminação: ${item.competitionName || item.competitionId} (${item.score || 'placar não registrado'} contra ${item.opponent || 'adversário'})`));
  const yearlyRecord = { season:Number(finishedYear), userClub:state.club, competitions:[...yearCompetitions.values()], achievements, eliminations:yearEliminations, titlesWon:clubChampionships.map(item => item.name), prizeMoney:Number(prize) || 0, savedAt:new Date().toISOString() };
  state.worldChampionHistory = Array.isArray(state.worldChampionHistory) ? state.worldChampionHistory : [];
  state.worldChampionHistory = state.worldChampionHistory.filter(item => Number(item.season) !== Number(finishedYear));
  state.worldChampionHistory.unshift(yearlyRecord);
  state.worldChampionHistory = state.worldChampionHistory.slice(0, 100);
  state.campeoesDoMundoSave = state.worldChampionHistory;
  state.historicoCarreira = state.worldChampionHistory;
  state.seasonHistory = state.seasonHistory || [];
  state.seasonHistory.unshift({
    season: finishedYear,
    compName: compFinished?.name || 'Campeonato',
    champion: rankingTable[0]?.name || state.club,
    runnerUp: rankingTable[1]?.name || 'Vice-Campeão',
    userPosition: position(),
    userClub: state.club,
    titlesWon: [...(state.titles || [])],
    balance: state.balance,
    income: Number(state.income) || 0,
    expense: Number(state.expense) || 0,
    financePeriodStartedDate: state.financePeriodStartedDate || null,
    bankDebt: totalBankDebt(),
    stadiumDebt: Math.max(0, Number(state.stadiumRingData?.debt?.remaining) || 0)
  });
  state.seasonHistory = state.seasonHistory.slice(0, 20);

  // Preserve caixa and dívidas; the new season starts with clean accounting totals.
  state.income = 0;
  state.expense = 0;
  state.financingInflow = 0;
  state.debtPrincipalPaid = 0;

  state.season++;
  const expiredSponsorContracts = expireSeasonSponsorContracts(state, state.season);
  state.round = 0;
  state.competitionStats = {};
  state.estadualData = null; // Reinicia dados do estadual para a nova temporada
  (state.bankLoans || []).forEach(loan => {
    if(loan.remainingDebt > 0 && loan.remainingInstallments > 0) loan.nextDueRound = 2;
  });
  state.date = `${state.season}-01-01`;
  state.currentDate = state.date;
  state.currentDateFormatted = formatDatePtBr(state.date);
  startSeasonTransferWindow(state);
  state.seasonPrizeClaimed = null;
  state.seasonConcluded = false;
  expireStadiumEventConfirmation();

  // Captura origem e destino antes de alterar o save. Só um destino explícito vindo
  // das regras de acesso/rebaixamento pode mudar a divisão nacional do clube.
  const nationalDivisionIds = ['bra-a','bra-b','bra-c','bra-d'];
  const finishedCompId = compFinished?.id || state.compId;
  const divisionMapForTransition = state.competitionTeams || BASE_COMPETITION_TEAMS || window.COMPETITION_TEAMS || {};
  const sourceNationalDivision = nationalDivisionIds.includes(finishedCompId) ? finishedCompId
    : (nationalDivisionIds.includes(state.compId) ? state.compId
      : nationalDivisionIds.find(id => (divisionMapForTransition[id] || []).some(name => norm(name) === norm(state.club))) || null);
  const requestedDestinationCompId = nationalDivisionIds.includes(state.nextSeasonCompId) ? state.nextSeasonCompId : null;
  if(requestedDestinationCompId) state.compId = requestedDestinationCompId;
  delete state.nextSeasonCompId;
  executeSeasonTransitions(finishedCompId, rankingTable, requestedDestinationCompId, sourceNationalDivision, finalSeasonSnapshot);
  if(window.AFM_RealWorldLeagues && typeof window.AFM_RealWorldLeagues.processEndOfSeasonPromotionsAndRelegations === 'function'){
    window.AFM_RealWorldLeagues.processEndOfSeasonPromotionsAndRelegations(state);
  }
  const comp = curComp();
  if(comp){
    state.competition = comp.name;
    state.currentLeague = comp.name;
  }
  refreshAnnualSponsorValues(finishedPosition, finishedTeamCount, comp?.id);
  state.financePeriodStartedDate = state.date;
  state.news.unshift(`🤝 PATROCÍNIOS REAJUSTADOS: contratos e novas propostas atualizados para ${comp?.name || 'a nova divisão'}, considerando a posição ${finishedPosition}ª de ${finishedTeamCount} na temporada anterior.`);
  state.news.unshift(`🎆 Feliz Ano Novo! Início da temporada ${state.season}! O ${state.club} disputará o ${comp?.name || 'Campeonato'} com pré-temporada aberta por 4 dias.`);
  state.news = state.news.slice(0, 50);

  const cc = competitionClubs(comp, state.club);
  state.teams = cc.map(c => ({name:c.name, strength:strength(c), j:0, v:0, e:0, d:0, gp:0, gc:0, sg:0, p:0, form:[]}));
  state.schedule = buildSchedule(comp, cc.map(c=>c.name));
  state.sponsorOffers = generateSponsorOffers(state.balance);
  expiredSponsorContracts.forEach(expired => {
    if(!state.sponsorOffers.some(offer => offer.renewalFor === expired.renewalFor)){
      state.sponsorOffers.unshift({ ...expired, renewal: true });
    }
  });
  state.sponsorOffers = uniqueAvailableSponsorOffers(state.sponsorOffers, state.sponsors);
  const isPlayerCareerRollover = Boolean(
    state.gameMode === 'player' ||
    state.isPlayerMode === true ||
    (typeof window !== 'undefined' && window.isPlayerCareerActive?.(state))
  );

  if(isPlayerCareerRollover && window.AFM_PlayerEngine?.processEndOfSeasonAwards){
    try { window.AFM_PlayerEngine.processEndOfSeasonAwards(state, finishedYear); } catch(_){}
  }

  (state.youthAcademy || []).forEach(p => {
    p.age = clamp((Number(p.age) || 16) + 1, 15, 18);
  });
  if(Number(state.lastSquadAgingSeason) !== Number(state.season)){
    state.lastSquadAgingSeason = Number(state.season);
    (state.squad || []).forEach(p => {
      if(!p) return;
      const isControlled = Boolean(
        p.isControlled ||
        p.isControlledAthlete ||
        (state.controlledPlayerId != null && String(p.id) === String(state.controlledPlayerId))
      );
      p.stamina = 100;
      p.goals = 0;
      p.assists = 0;
      p.yellowCards = 0;
      p.redCard = false;
      if(isControlled) return;
      p.age = (Number(p.age) || 24) + 1;
      if(p.age >= 35 && Math.random() < 0.35){
        p.fc = Math.max(45, (p.fc || playerOverall(p)) - 1);
      }
    });
  }

  if(isPlayerCareerRollover && window.AFM_PlayerEngine?.rolloverPlayerSeason){
    try { window.AFM_PlayerEngine.rolloverPlayerSeason(state, finishedYear); } catch(e){ recordAFMError('player-season-rollover', e); }
    restorePlayerCareerSquad(state);
  }

  if(Number(state.lastRegensSeason) !== Number(state.season)){
    state.lastRegensSeason = Number(state.season);
    generateWorldRegens();
  }
  if(window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.processAgingDeclineAndGeneticRegens === 'function'){
    window.AFM_MarketLupaAndAging.processAgingDeclineAndGeneticRegens(state);
  }

  closeCustomModal(); save(); render(); return true; } catch(err) { console.error('[AFM advanceSeasonYear Error]', err); try { state.season = (Number(state.season) || 2027) + 1; state.round = 0; state.date = `${state.season}-01-01`; state.currentDate = state.date; state.currentDateFormatted = formatDatePtBr(state.date); startSeasonTransferWindow(state); state.seasonPrizeClaimed = null; state.seasonConcluded = false; closeCustomModal(); save(); render(); toast('🚀 Temporada ' + state.season + ' iniciada com sucesso!'); } catch(fallbackErr) { console.error('[AFM Fallback Error]', fallbackErr); } return false; }

}

function generateWorldRegens(){
  state.worldRegens = state.worldRegens || [];
  const firsts = ['Enzo', 'Cauã', 'Matheus', 'Arthur', 'Bryan', 'Davi', 'Gustavo', 'Luan', 'Murilo', 'Rayan', 'Estêvão', 'Endrick', 'Lamine', 'Arda', 'Kauã', 'Vinícius', 'Gabriel', 'Kaio'];
  const lasts = ['Alves', 'Pereira', 'Ribeiro', 'Carvalho', 'Gomes', 'Martins', 'Barbosa', 'Monteiro', 'Moreira', 'Nascimento', 'Teixeira', 'Cardoso', 'Silveira', 'Moraes', 'Dantas'];
  const count = rnd(18, 28);
  for(let i=0; i<count; i++){
    const name = `${firsts[rnd(0, firsts.length - 1)]} ${lasts[rnd(0, lasts.length - 1)]}`;
    const pos = ['GK', 'CB', 'LB', 'RB', 'DM', 'CM', 'RW', 'LW', 'ST'][rnd(0, 8)];
    const ovr = rnd(62, 74);
    const pot = rnd(80, 94);
    state.worldRegens.push({
      name,
      pos,
      age: rnd(16, 18),
      fc: ovr,
      potential: pot,
      club: 'Livre no Mercado',
      salary: Math.round(ovr * 450)
    });
  }
}

function changeUserClub(newClubName){
  const club = clubByName(newClubName) || {name: newClubName, country: 'Brasil', atk: 68, mid: 68, def: 68, budget: 6};
  if(window.AFM_ManagerEconomy && typeof window.AFM_ManagerEconomy.liquidateSharesOnClubExit === 'function'){
    const payout = window.AFM_ManagerEconomy.liquidateSharesOnClubExit(state);
    if(payout > 0){
      state.news = Array.isArray(state.news) ? state.news : [];
      state.news.unshift(`💼 LIQUIDAÇÃO DE COTAS: Suas cotas no clube anterior foram vendidas e renderam R$ ${payout.toLocaleString('pt-BR')} ao seu saldo pessoal!`);
    }
  }
  state.club = club.name;
  state.managerContractDate = `sex, 31 dez ${state.season + 2}`;
  const managerSalaryBonus = state.gameMode === 'manager' ? clamp(Number(state.managerCareerBonuses?.salaryPct) || 0, 0, 10) : 0;
  state.managerSalary = Math.round(((club.budget || 5) * 8000 + 15000) * (1 + managerSalaryBonus / 100));
  state.squad = playersForClub(club.name, state.worldGenerated);
  state.infrastructure = defaultInfrastructure(club);
  state.youthAcademy = generateInitialYouthAcademy(1, club.name);
  state.balance = Math.max(500000, (club.budget || 5) * 1e6);
  state.news.unshift(`Você assumiu o comando técnico do ${club.name} para a temporada ${state.season}! Vínculo assinado até ${state.managerContractDate}.`);
  state.managerFinanceHistory = state.managerFinanceHistory || [];
  state.managerFinanceHistory.unshift({
    date: state.date,
    desc: `Luvas de assinatura com o ${club.name}`,
    amount: state.managerSalary * 2
  });
  const signBonus = state.managerSalary * 2;
  state.managerMoney = (Number(state.managerMoney) || 0) + signBonus;
  if(state.career && typeof state.career === 'object'){
    state.career.cash = (Number(state.career.cash) || 0) + signBonus;
    state.career.personalCash = state.career.cash;
  }
  if(state.managerPersonal) state.managerPersonal.personalBalance = (Number(state.managerPersonal.personalBalance) || 0) + signBonus;
  if(window.AFMCareerFix?.calculateCareerEconomy) window.AFMCareerFix.calculateCareerEconomy(state);
  advanceSeasonYear();
  toast(`Você agora é o técnico do ${club.name}!`);
}

function ranking(){
  return [...state.teams].sort((a,b)=>
    b.p - a.p ||
    (b.v || 0) - (a.v || 0) ||
    b.sg - a.sg ||
    b.gp - a.gp ||
    a.name.localeCompare(b.name, 'pt-BR')
  );
}
function position(){return Math.max(1,ranking().findIndex(t=>t.name===state.club)+1)}
window.ranking = ranking;
window.position = position;

// -------------------------------------------------------------
// MODAIS POPUP CUSTOMIZADOS COM BOTÃO X
// -------------------------------------------------------------
function openCustomModal(title, bodyHtml, onConfirm, confirmText='Confirmar', showActions=false, maxWidth=null, onClose=null){
  closeCustomModal(false);
  window.__afmCustomModalOnClose = onClose;
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay active';
  overlay.id = 'appCustomModal';
  overlay.style.cssText = 'position:fixed;inset:0;background:#060a0fdf;backdrop-filter:blur(12px);z-index:999999;display:flex;align-items:center;justify-content:center;padding:16px;pointer-events:auto;';
  const modalClasses = `${maxWidth ? 'modal-wide' : ''}${title === '⇄ Negociação de Empréstimo de Jogador' ? ' loan-negotiation-modal' : ''}`.trim();
  const widthStyle = maxWidth ? `style="max-width:${maxWidth};width:96%;pointer-events:auto;"` : 'style="pointer-events:auto;"';
  overlay.innerHTML = `
    <div class="modal ${modalClasses}" ${widthStyle}>
      <div class="modal-header" style="pointer-events:auto;">
        <h3 style="margin:0">${esc(title)}</h3>
        <button class="modal-close-btn" id="modalCloseXBtn" style="pointer-events:auto;cursor:pointer;">✕</button>
      </div>
      <div style="pointer-events:auto;">${bodyHtml}</div>
      ${showActions ? `
        <div class="actions" style="margin-top:20px;justify-content:flex-end;pointer-events:auto;">
          <button class="btn" id="modalCancelAction" style="pointer-events:auto;cursor:pointer;">Cancelar</button>
          <button class="btn primary" id="modalConfirmAction" style="pointer-events:auto;cursor:pointer;">${esc(confirmText)}</button>
        </div>
      ` : ''}
    </div>
  `;
  document.body.appendChild(overlay);

  // Delegação central de eventos no overlay para blindar cliques em qualquer circunstância
  overlay.addEventListener('click', (e) => {
    if(e.target === overlay) {
      closeCustomModal();
      return;
    }
    const closeBtn = e.target.closest('#modalCloseXBtn, .modal-close-btn, [data-modal-close]');
    if(closeBtn){
      e.preventDefault();
      e.stopPropagation();
      closeCustomModal();
      return;
    }
    const cancelBtn = e.target.closest('#modalCancelAction, [data-modal-cancel]');
    if(cancelBtn){
      e.preventDefault();
      e.stopPropagation();
      closeCustomModal();
      return;
    }
    const confBtn = e.target.closest('#modalConfirmAction, [data-modal-confirm]');
    if(confBtn){
      e.preventDefault();
      e.stopPropagation();
      window.__afmCustomModalOnClose = null;
      try {
        if(typeof onConfirm === 'function') onConfirm();
      } catch(err){
        console.error('Erro no onConfirm do custom modal:', err);
      } finally {
        closeCustomModal(false);
      }
      return;
    }
  });

  // Handlers diretos para compatibilidade com listeners legados
  const closeX = overlay.querySelector('#modalCloseXBtn');
  if(closeX) closeX.onclick = (e) => { e.preventDefault(); e.stopPropagation(); closeCustomModal(); };
  const cancelBtn = overlay.querySelector('#modalCancelAction');
  if(cancelBtn) cancelBtn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); closeCustomModal(); };
  const confBtn = overlay.querySelector('#modalConfirmAction');
  if(confBtn) confBtn.onclick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    window.__afmCustomModalOnClose = null;
    try {
      if(typeof onConfirm === 'function') onConfirm();
    } catch(err){
      console.error('Erro no onConfirm do custom modal:', err);
    } finally {
      closeCustomModal(false);
    }
  };
}

function closeCustomModal(triggerOnClose = true){
  const cb = window.__afmCustomModalOnClose;
  window.__afmCustomModalOnClose = null;
  const m = $('#appCustomModal') || document.getElementById('appCustomModal');
  if(m) m.remove();
  document.querySelectorAll('#appCustomModal').forEach(el => el.remove());
  if(triggerOnClose && typeof cb === 'function'){
    try { cb(); } catch(err){ console.warn('Error in custom modal onClose:', err); }
  }
}
window.closeCustomModal = closeCustomModal;

function closeActiveModal(triggerOnClose = true){
  if(typeof closeCustomModal === 'function') closeCustomModal(triggerOnClose);
  const m = document.getElementById('appCustomModal');
  if(m) m.remove();
  const backdrops = document.querySelectorAll('.modal-overlay, .modal-backdrop');
  backdrops.forEach(b => {
    try { b.remove(); } catch(e) {}
  });
}
window.closeActiveModal = closeActiveModal;

