function upgradeFacility(key){
  if (window.__afmFacilityLock) return;
  window.__afmFacilityLock = true;
  setTimeout(() => { window.__afmFacilityLock = false; }, 350);

  const f=state.infrastructure[key],d=FACILITIES[key];
  if(!f||!d)return;
  if(f.level>=d.max){toast('Estrutura no nível máximo.');return}
  const cost=facilityCost(key);
  if(state.balance<cost){toast('Caixa insuficiente para a obra.');return}
  const previousMarketingWeekly = Math.max(MARKETING_MINIMUM_WEEKLY, Number(state.marketingWeekly) || 36000);
  state.balance-=cost;
  state.expense+=cost;
  f.level++;
  if(state.facilities) state.facilities[key] = f.level;
  if(key==='stadium'){
    state.stadiumRingData = state.stadiumRingData || { ring: 1, maxRings: 6, sides: { norte: false, sul: false, leste: false, oeste: false }, rings: {}, purchasedSectors: [] };
    state.stadiumRingData.maxUnlockedRing = Math.min(6, Math.max(state.stadiumRingData.maxUnlockedRing || 1, f.level));
    state.stadiumRingData.rings = state.stadiumRingData.rings || {};
    state.stadiumRingData.purchasedSectors = Array.isArray(state.stadiumRingData.purchasedSectors) ? state.stadiumRingData.purchasedSectors : [];
    const unlockedRing = Math.min(6, f.level);
    state.stadiumRingData.rings[unlockedRing] = state.stadiumRingData.rings[unlockedRing] || { norte: false, sul: false, leste: false, oeste: false };
    const currentRing = state.stadiumRingData.ring || 1;
    if(currentRing < unlockedRing && ['norte', 'sul', 'leste', 'oeste'].every(side => state.stadiumRingData.rings[currentRing]?.[side])){
      state.stadiumRingData.ring = currentRing + 1;
      state.stadiumRingData.sides = state.stadiumRingData.rings[state.stadiumRingData.ring];
    }
    state.news.unshift(`🏟️ ESTÁDIO EVOLUÍDO PARA NÍVEL ${f.level}/8! O ${unlockedRing}º anel foi liberado para obras por setor. A capacidade não muda até a conclusão das obras.`);
  }
  if(key==='parking') f.spots = parkingSpots(f.level);
  if(key==='marketing'){
    state.marketingWeekly = Math.round(previousMarketingWeekly * MARKETING_UPGRADE_MINIMUM_GROWTH);
    state.marketingMonthly = state.marketingWeekly * 4;
    state.news.unshift(`📢 Aporte semanal de marketing reajustado em 20% após o upgrade: ${fmtMoney(state.marketingWeekly)}/semana.`);
  }
  if(key==='training') state.news.unshift(`⚽ CENTRO DE TREINAMENTO NÍVEL ${f.level}: elenco ampliado para ${squadCapacity(f.level)} vagas e bônus de treino elevado para +${trainingBonusPct(f.level)}% no desenvolvimento dos atletas!`);
  if(key==='museum'||key==='stadium') state.trust.fans=clamp(state.trust.fans+4,0,100);
  if(key==='museum'){
    state.museumData = state.museumData || { level: 1 };
    state.museumData.level = f.level;
  }
  if(key==='press') state.trust.board=clamp(state.trust.board+1,0,100);
  if(key==='academy') boostYouthAcademyOnUpgrade(f.level);
  if(key==='bank') state.news.unshift(`🏦 Banco & Financiamento evoluído para o nível ${f.level}! Limite de crédito ampliado e taxas de juros reduzidas.`);
  state.news.unshift(`${d.name} foi ampliado para o nível ${f.level}, por ${fmtMoney(cost)}.`);
  save();render();toast(`${d.name}: nível ${f.level} alcançado!`);
}
if(typeof window !== 'undefined') window.upgradeFacility = upgradeFacility;

// -------------------------------------------------------------
// SISTEMA BANCÁRIO & EMPRÉSTIMOS FINANCEIROS DO CLUBE
// -------------------------------------------------------------
function totalBankDebt(){
  if(!state || !Array.isArray(state.bankLoans)) return 0;
  return state.bankLoans.reduce((acc, l) => acc + (Number(l.remainingDebt) || 0), 0);
}

function ensureBankCreditHistory(){
  if(!state) return { onTimePayments: 0, latePayments: 0, completedLoans: 0 };
  if(!state.bankCreditHistory || typeof state.bankCreditHistory !== 'object'){
    const legacyPaid = (state.bankLoans || []).reduce((sum, loan) => sum + Math.max(0, Number(loan.paidInstallments) || 0), 0);
    state.bankCreditHistory = {
      onTimePayments: legacyPaid,
      latePayments: (state.bankLoans || []).filter(loan => loan.overdue).length,
      completedLoans: 0
    };
  }
  const history = state.bankCreditHistory;
  history.onTimePayments = Math.max(0, Math.floor(Number(history.onTimePayments) || 0));
  history.latePayments = Math.max(0, Math.floor(Number(history.latePayments) || 0));
  history.completedLoans = Math.max(0, Math.floor(Number(history.completedLoans) || 0));
  return history;
}

function recordBankCreditPayment(type){
  const history = ensureBankCreditHistory();
  if(type === 'late') history.latePayments++;
  else if(type === 'completed') history.completedLoans++;
  else history.onTimePayments++;
}

function bankCreditAssessment(){
  if(!state) return { score: 0, rating: 'Sem avaliação', maxLimit: 0, availableCredit: 0, monthlySurplus: 0, liquidityMonths: 0 };
  const projection = monthlyFinancialProjection();
  const monthlyRevenue = Math.max(0, Number(projection.monthlyRevenue) || 0);
  const monthlyExpenses = Math.max(0, Number(projection.monthlyExpenses) || 0);
  const monthlySurplus = Number(projection.monthlyBalance) || 0;
  const monthlyBase = Math.max(50000, monthlyExpenses);
  const cash = Math.max(0, Number(state.balance) || 0);
  const debt = totalBankDebt();
  const liquidityMonths = cash / monthlyBase;
  const liquidityScore = clamp(liquidityMonths / 2, 0, 1) * 25;
  const cashFlowRatio = monthlySurplus / monthlyBase;
  const cashFlowScore = clamp((cashFlowRatio + 0.25) / 0.75, 0, 1) * 25;

  const history = ensureBankCreditHistory();
  const paymentCount = history.onTimePayments + history.latePayments;
  const paymentScore = paymentCount === 0
    ? 12
    : clamp(history.onTimePayments / paymentCount, 0, 1) * 16 + Math.min(4, history.completedLoans * 2);
  const debtToRevenue = debt / Math.max(1, monthlyRevenue * 12);
  const debtScore = clamp(1 - debtToRevenue, 0, 1) * 10;
  const fame = clamp(Number(teamFameScore()) || 0, 0, 100);
  const notorietyScore = fame * 0.2;
  const score = Math.round(clamp(liquidityScore + cashFlowScore + paymentScore + debtScore + notorietyScore, 0, 100));

  const rating = score >= 85 ? 'Excelente' : score >= 70 ? 'Muito bom' : score >= 55 ? 'Bom' : score >= 40 ? 'Regular' : 'Baixo';
  const scoreBasedLimit = 500000 + Math.pow(score / 100, 2) * 34500000;
  const affordabilityLimit = Math.max(500000, (Math.max(0, monthlySurplus) * 18) + (cash * 0.35));
  const maxLimit = Math.round(Math.min(scoreBasedLimit, affordabilityLimit) / 100000) * 100000;
  return {
    score,
    rating,
    maxLimit,
    affordabilityLimit,
    availableCredit: Math.max(0, maxLimit - debt),
    monthlySurplus,
    liquidityMonths,
    fame,
    monthlyRevenue,
    monthlyExpenses
  };
}

function bankAvailableCredit(){
  if(!state) return 0;
  const assessment = bankCreditAssessment();
  const bankLevel = clamp(Number(state.infrastructure?.bank?.level) || 1, 1, 8);
  const institutionBonus = 1 + ((bankLevel - 1) * 0.025);
  const adjustedLimit = Math.min(assessment.maxLimit * institutionBonus, assessment.affordabilityLimit);
  return Math.max(0, Math.round((adjustedLimit - totalBankDebt()) / 100000) * 100000);
}

function calcBankInterestRate(amount, installments){
  const lvl = Number(state.infrastructure?.bank?.level) || 1;
  let rate = 2.0;
  if(amount > 15000000) rate += 3.5;
  else if(amount > 8000000) rate += 2.4;
  else if(amount > 3000000) rate += 1.5;
  else if(amount > 1000000) rate += 0.8;

  if(installments >= 36) rate += 1.8;
  else if(installments >= 24) rate += 1.1;
  else if(installments >= 12) rate += 0.5;

  rate = Math.max(1.4, rate - ((lvl - 1) * 0.2));
  return Math.round(rate * 10) / 10;
}

function calcBankInstallment(amount, installments, monthlyRate){
  // Cada parcela vence a cada duas rodadas; o calendário tem quatro rodadas por mês.
  const totalInterest = amount * (monthlyRate / 100) * (installments / 2);
  const totalDebt = amount + totalInterest;
  return Math.round(totalDebt / installments);
}

function processBankLoansOnRound(){
  if(!state || !Array.isArray(state.bankLoans) || state.bankLoans.length === 0) return;
  state.bankLoans.forEach((loan) => {
    if(loan.remainingInstallments <= 0 || loan.remainingDebt <= 0) return;
    if((state.round || 0) >= (loan.nextDueRound || 0)){
      const instVal = Math.round(loan.installmentValue || (loan.remainingDebt / Math.max(1, loan.remainingInstallments)));
      const alreadyChargedThisRound = Number(loan.lastPenaltyRound) === Number(state.round || 0);
      // O débito automático só tenta a parcela no vencimento inicial. Se falhar,
      // a dívida fica em atraso e exige regularização manual com os juros acumulados.
      if(state.bankAutoDebitEnabled && !loan.overdue && state.balance >= instVal){
        const wasOverdue = !!loan.overdue;
        const amountDue = instVal + Math.max(0, Number(loan.penalty) || 0);
        state.balance -= amountDue;
        const breakdown = bankLoanPaymentBreakdown(loan, amountDue);
        loan.remainingPrincipal = breakdown.remainingPrincipal;
        state.debtPrincipalPaid = (state.debtPrincipalPaid || 0) + breakdown.principalPaid;
        state.expense = (state.expense || 0) + breakdown.interestPaid;
        if(!wasOverdue) recordBankCreditPayment('on-time');
        loan.paidInstallments = (loan.paidInstallments || 0) + 1;
        loan.remainingInstallments = Math.max(0, (loan.remainingInstallments || 1) - 1);
        loan.remainingDebt = Math.max(0, loan.remainingDebt - breakdown.amount);
        loan.nextDueRound = (state.round || 0) + 2;
        loan.overdue = false;
        loan.penalty = 0;
        loan.lastPenaltyRound = null;
        if(loan.remainingDebt <= 0 || loan.remainingInstallments <= 0) recordBankCreditPayment('completed');
        state.news.unshift(`🏦 Banco & Finanças: Débito automático de ${fmtMoney(amountDue)} realizado (${loan.paidInstallments}/${loan.totalInstallments}).`);
      } else {
        if(!loan.overdue) recordBankCreditPayment('late');
        loan.overdue = true;
        if(!alreadyChargedThisRound){
          const penaltyFee = Math.max(1, Math.round(instVal * 0.02));
          loan.penalty = (Number(loan.penalty) || 0) + penaltyFee;
          loan.remainingDebt += penaltyFee;
          loan.lastPenaltyRound = Number(state.round) || 0;
          state.news.unshift(`🚨 ALERTA BANCÁRIO: parcela de ${fmtMoney(instVal)} vencida${state.bankAutoDebitEnabled ? ' por saldo insuficiente' : ' (débito automático desativado)'}. Juros de atraso: +${fmtMoney(penaltyFee)}.`);
        }
      }
    }
  });
  state.bankLoans = state.bankLoans.filter(l => l.remainingDebt > 0 && l.remainingInstallments > 0);
  const severeOverdue = state.bankLoans.some(l => l.overdue && ((Number(state.round) || 0) - (Number(l.nextDueRound) || 0)) >= 4);
  state.transferBan = Boolean(severeOverdue);
}

