function triggerAFMSystemEnhancements(){
  if(!state || typeof document === 'undefined') return; try { window.state = state; window.GameState = state; if(typeof window.AFM_InstantCareerHook === 'function') window.AFM_InstantCareerHook(); if(typeof window.__AFM_RUN_INSTANT_HOOKS === 'function') window.__AFM_RUN_INSTANT_HOOKS(); } catch(e){}
  try {
    if(typeof window.syncCoachSalaryWithLicenses === 'function'){
      window.syncCoachSalaryWithLicenses(state);
    }
    if(window.AFM_CalendarFix && typeof window.AFM_CalendarFix.syncDateInDOM === 'function'){
      window.AFM_CalendarFix.syncDateInDOM(state);
    }
    if(window.AFM_TrophiesTvPayroll){
      if(typeof window.AFM_TrophiesTvPayroll.refreshMuseumTrophiesDOM === 'function') window.AFM_TrophiesTvPayroll.refreshMuseumTrophiesDOM(state);
      if(typeof window.AFM_TrophiesTvPayroll.injectTvBroadcastSectionInOffice === 'function') window.AFM_TrophiesTvPayroll.injectTvBroadcastSectionInOffice(state);
      if(typeof window.AFM_TrophiesTvPayroll.syncCoachSalaryAndSquadSlotsInDOM === 'function') window.AFM_TrophiesTvPayroll.syncCoachSalaryAndSquadSlotsInDOM(state);
    }
    if(window.AFM_WorldSimulation){
      if(typeof window.AFM_WorldSimulation.injectPrestigeAndRankingButtonInCareerCard === 'function') window.AFM_WorldSimulation.injectPrestigeAndRankingButtonInCareerCard(state);
      if(typeof window.AFM_WorldSimulation.ensureUserClubInCopaDoBrasilAndHighlight === 'function') window.AFM_WorldSimulation.ensureUserClubInCopaDoBrasilAndHighlight(state);
    }
    if(window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.injectLupaButtonsInMarketDOM === 'function'){
      window.AFM_MarketLupaAndAging.injectLupaButtonsInMarketDOM(state);
    }
    if(window.AFM_LineupPhotos && typeof window.AFM_LineupPhotos.scanAndHydratePitchAndBenchPhotos === 'function'){
      window.AFM_LineupPhotos.scanAndHydratePitchAndBenchPhotos();
    }
  } catch(e) {
    console.warn('[AFM System Enhancements]', e);
  }
}

function processCoachSalaryOnFirstOfMonth(gameState = state){
  if(!gameState) return false;
  if((typeof window.isPlayerCareerActive === 'function' && window.isPlayerCareerActive(gameState)) || gameState.gameMode === 'player' || gameState.isPlayerMode){
    return false;
  }
  const date = String(gameState?.date || '');
  if(date.length !== 10 || date[4] !== '-' || date[7] !== '-' || date.slice(8) !== '01') return false;
  // Dia 1 de abertura de uma nova carreira (01/01/2026 sem jogos) não desconta salário mensal antecipado do caixa inicial!
  if(date === '2026-01-01' && Number(gameState.season || 2026) === 2026 && (Number(gameState.round) || 0) === 0 && !(gameState.history || []).length){
    return false;
  }
  const payroll = window.AFM_LifeAndSharesPro;
  if(!payroll || typeof payroll.payMonthlyCoachSalary !== 'function') return false;
  const result = payroll.payMonthlyCoachSalary(gameState);
  if(!result?.paid) return false;
  save();
  return true;
}

function render() {
  if(typeof state !== 'undefined' && !state && typeof window !== 'undefined' && window.state) { state = window.state; }
  try { if (typeof state !== 'undefined' && state) { window.state = state; window.GameState = state; } if (typeof render === 'function') { window.render = render; } } catch(e) {}

  if (window.__afmIsRendering) return;
  window.__afmIsRendering = true;

  const app=$('#app');
  if(!app) {
    window.__afmIsRendering = false;
    return;
  }

  // Blindagem contra sobrescrita durante criação de atleta (Hipótese 6)
  if (app.querySelector && (app.querySelector('.afm-player-creator-wrapper') || (typeof setupViewMode !== 'undefined' && setupViewMode === 'create_player') || (typeof window !== 'undefined' && window.setupViewMode === 'create_player'))) {
    window.__afmIsRendering = false;
    return;
  }

  try {
    if(!state){
      renderSetup(app);
      return;
    }
    if (typeof window.migrateAndSanitizeSaveState === 'function') {
      state = window.migrateAndSanitizeSaveState(state);
    }
    try { if(typeof repairSaveIfCorrupted === 'function' && repairSaveIfCorrupted(state)) save(); } catch(e){}
    try { processLoanContractReturns(state); } catch(e){ recordAFMError('loan-contract-expiration', e); }
    try { processCoachSalaryOnFirstOfMonth(state); } catch(e){ recordAFMError('coach-monthly-payday', e); }
    const restoreScroll = app.dataset?.renderedView === view;
    const windowScroll = window.scrollY;
    const mainScroll = app.querySelector('.main')?.scrollTop || 0;
    const nestedScroll = [...app.querySelectorAll('.tablewrap, .tactics-bench-wrapper > div[style*="overflow-y:auto"]')].map(el => el.scrollTop);
    const restore = () => requestAnimationFrame(() => {
      if(app.dataset) app.dataset.renderedView = view;
      if(!restoreScroll){ if(typeof window.scrollTo === 'function') window.scrollTo(0, 0); return; }
      if(typeof window.scrollTo === 'function') window.scrollTo(0, windowScroll);
      const main = app.querySelector('.main');
      if(main) main.scrollTop = mainScroll;
      app.querySelectorAll('.tablewrap, .tactics-bench-wrapper > div[style*="overflow-y:auto"]').forEach((el, i) => { el.scrollTop = nestedScroll[i] || 0; });
    });
    const isPlayerMode = typeof window.isPlayerCareerActive === 'function' ? window.isPlayerCareerActive(state) : Boolean(state?.gameMode === 'player' || state?.playerCareerState || state?.controlledPlayerId);
    const currentMode = isPlayerMode ? 'player' : 'manager';
    const mainEl = app.querySelector('.main');
    const sideNav = app.querySelector('.nav');
    if(mainEl && sideNav && app.querySelector('.app') && app.dataset?.renderedGameMode === currentMode){
      try {
        const nextHtml = page();
        mainEl.innerHTML = nextHtml;

        // Mantém a navegação lateral e a ribbon sincronizadas com labels, notificações e abas adaptativas
        const drawerItems = getDrawerNavItems();
        const currentNavSignature = [...sideNav.querySelectorAll('[data-view]')].map(b => `${b.dataset.view}:${b.innerHTML}`).join('|');
        const nextNavSignature = drawerItems.map(([id, l]) => `${id}:${l}`).join('|');
        if(currentNavSignature !== nextNavSignature){
          sideNav.innerHTML = drawerItems.map(([id, l]) => `<button class="btn ${view===id?'active':''}" data-view="${id}">${l}</button>`).join('');
        } else {
          sideNav.querySelectorAll('[data-view]').forEach(b => {
            b.classList.toggle('active', b.dataset.view === view);
          });
        }

        // Sincroniza a fita adaptativa do topo (Top 4 Atalhos)
        const ribbon = app.querySelector('.sm-task-ribbon');
        if(ribbon && typeof getAdaptiveRibbonTabs === 'function'){
          const ribbonTabs = getAdaptiveRibbonTabs(isPlayerMode, view, state);
          const currentRibbonSignature = [...ribbon.querySelectorAll('.sm-ribbon-pill[data-view]:not(.sm-ribbon-cal)')].map(b => `${b.dataset.view}:${b.innerHTML}`).join('|');
          const nextRibbonSignature = ribbonTabs.map(t => `${t.id}:${t.label}`).join('|');
          if(currentRibbonSignature !== nextRibbonSignature){
            const tagText = isPlayerMode ? 'ATLETA' : 'Tarefas';
            const tickerMsg = isPlayerMode
              ? (state?.playerCareerState?.athleteName ? `Craque: ${state.playerCareerState.athleteName} · Foque na evolução` : 'Foco total na temporada')
              : (state?.club ? `Clube: ${state.club} · Temporada em andamento` : 'Temporada em andamento');
            ribbon.innerHTML = `
              <span class="sm-ribbon-tag" style="${isPlayerMode ? 'background:linear-gradient(135deg,#10b981,#059669);color:#000;font-weight:900;' : ''}">${tagText}</span>
              ${ribbonTabs.map(t => `
                <button type="button" class="sm-ribbon-pill ${view===t.id?'active':''}" data-view="${t.id}">${t.label}</button>
              `).join('')}
              <div class="sm-ribbon-ticker">
                <span>⚽ ${tickerMsg}</span>
              </div>
              <button type="button" class="sm-ribbon-pill sm-ribbon-cal ${view==='calendario'?'active':''}" data-view="calendario" title="Calendário de Jogos">
                🗓️ Calendário
              </button>
            `;
          } else {
            ribbon.querySelectorAll('.sm-ribbon-pill[data-view]').forEach(b => {
              b.classList.toggle('active', b.dataset.view === view);
            });
          }
        }

        if(isPlayerMode) {
          const pState = state.playerCareerState;
          const athlete = (typeof getControlledPlayer === 'function') ? getControlledPlayer(state) : (state?.squad?.find(p => p.id === state.controlledPlayerId || p.isControlled));
          const pBank = Number(pState?.personalBank ?? athlete?.cash ?? pState?.lifestyle?.cash ?? 0);
          const patrimony = typeof window.AFM_Lifestyle?.getPlayerTotalPatrimony === 'function'
            ? window.AFM_Lifestyle.getPlayerTotalPatrimony(pState || athlete)
            : (pBank + (Number(pState?.lifestyle?.investments?.cdbBalance) || 0));

          const dPatrimonyEl = app.querySelector('#drawerPatrimonyVal');
          if (dPatrimonyEl) dPatrimonyEl.textContent = `R$ ${patrimony.toLocaleString('pt-BR')}`;

          const dCashEl = app.querySelector('#drawerPersonalCashVal');
          if (dCashEl) dCashEl.textContent = `R$ ${pBank.toLocaleString('pt-BR')}`;
        } else {
          const balEl = app.querySelector('.club-card b:last-of-type') || app.querySelector('.club-card b');
          if(balEl) {
            balEl.textContent = fmtMoney(state.balance);
          }
        }
        const strengthValEl = app.querySelector('.sm-badge-strength .sm-res-val');
        if(strengthValEl) {
          if(isPlayerMode){
            const pState = state.playerCareerState;
            const athlete = (typeof getControlledPlayer === 'function') ? getControlledPlayer(state) : (state?.squad?.find(p => p.id === state.controlledPlayerId || p.isControlled));
            const aOvr = Number(athlete?.ovr || athlete?.overall || pState?.athleteOvr || 35);
            strengthValEl.textContent = `${aOvr} OVR`;
            const badgeStr = app.querySelector('.sm-badge-strength');
            if(badgeStr) badgeStr.title = `Overall do Atleta: ${aOvr}`;
          } else {
            const tOvr = (typeof overallSquad === 'function') ? overallSquad() : 70;
            strengthValEl.textContent = `${tOvr} OVR`;
            const badgeStr = app.querySelector('.sm-badge-strength');
            if(badgeStr) badgeStr.title = `Força Geral do Time (Overall: ${tOvr})`;
          }
        }
        const prestigeValEl = app.querySelector('.sm-badge-prestige .sm-res-val');
        if(prestigeValEl) {
          if(isPlayerMode){
            const pState = state.playerCareerState;
            const pts = Number(pState?.availablePoints ?? pState?.skillPoints ?? 0);
            prestigeValEl.textContent = `${pts} pts`;
            const badgePres = app.querySelector('.sm-badge-prestige');
            if(badgePres) badgePres.title = `Pontos de Atributos Livres: ${pts} pts`;
          } else {
            const cPres = state?.managerPersonal?.prestigeScore || state?.coachPrestige || 5;
            prestigeValEl.textContent = `${cPres} pts`;
            const badgePres = app.querySelector('.sm-badge-prestige');
            if(badgePres) badgePres.title = `Prestígio do Treinador: ${cPres} pts`;
          }
        }
        const cashValEl = app.querySelector('.sm-badge-cash .sm-res-val');
        if(cashValEl) {
          if(isPlayerMode){
            const pState = state.playerCareerState;
            const athlete = (typeof getControlledPlayer === 'function') ? getControlledPlayer(state) : (state?.squad?.find(p => p.id === state.controlledPlayerId || p.isControlled));
            const pBank = Number(pState?.personalBank ?? athlete?.cash ?? pState?.lifestyle?.cash ?? 0);
            const patrimony = typeof window.AFM_Lifestyle?.getPlayerTotalPatrimony === 'function'
              ? window.AFM_Lifestyle.getPlayerTotalPatrimony(pState || athlete)
              : (pBank + (Number(pState?.lifestyle?.investments?.cdbBalance) || 0));

            cashValEl.textContent = `R$ ${(pBank >= 1000000 ? (pBank/1000000).toFixed(1) + 'M' : (pBank >= 1000 ? Math.round(pBank/1000) + 'K' : pBank))}`;
            const badgeCash = app.querySelector('.sm-badge-cash');
            if(badgeCash) badgeCash.title = `Conta Pessoal: R$ ${pBank.toLocaleString('pt-BR')} · Patrimônio: R$ ${patrimony.toLocaleString('pt-BR')}`;
          } else {
            cashValEl.textContent = fmtCompactMoney(state.balance);
            const badgeCash = app.querySelector('.sm-badge-cash');
            if(badgeCash) badgeCash.title = `Saldo em Caixa: ${fmtMoney(state.balance)}`;
          }
        }

        const gate = (typeof canStartMatch === 'function') ? canStartMatch() : { ok: false };
        const btnContLabel = app.querySelector('.sm-continue-label');
        if(btnContLabel) btnContLabel.textContent = gate.ok ? 'JOGAR' : 'CONTINUAR';
        const btnContTime = app.querySelector('.sm-continue-time');
        if(btnContTime) btnContTime.textContent = gate.ok ? '🔥 Dia de Jogo!' : `${formatDatePtBr(state.date)}`;

        // Atualiza data e janela de transferências no topo em tempo real
        const dateEl = document.getElementById('topBarCurrentDate') || app.querySelector('.top-right span:first-child');
        if(dateEl) dateEl.innerHTML = `📅 ${formatDatePtBr(state.date)}`;
        const winBadgeEl = app.querySelector('.window-badge');
        if(winBadgeEl) {
          const winInfo = getTransferWindowInfo(state.date);
          winBadgeEl.className = `window-badge ${winInfo.open?'window-open':'window-closed'}`;
          winBadgeEl.textContent = `${winInfo.open?'🟢':'🔴'} ${winInfo.text}`;
        }

        bind();
        triggerAFMSystemEnhancements();
        restore();
        return;
      } catch(err){
        recordAFMError('render-page', err);
        console.error('Falha ao renderizar a tela ' + view + ':', err);
        const safeMessage = esc(err?.message || 'Erro inesperado ao montar a tela.');
        const isPlayerMode = typeof window.isPlayerCareerActive === 'function' ? window.isPlayerCareerActive(state) : Boolean(state?.gameMode === 'player' || state?.playerCareerState);
        const homeView = isPlayerMode ? 'player_hub' : 'central';
        const homeLabel = isPlayerMode ? 'Voltar ao Hub do Atleta' : 'Voltar à Central';
        try {
          mainEl.innerHTML = `<section class="card" role="alert" style="margin:20px;padding:20px;border:1px solid #ef4444;background:#1b1020;color:#fff">
            <h2 style="margin-top:0">Não foi possível abrir esta tela</h2>
            <p>O jogo encontrou um erro ao renderizar <b>${esc(view)}</b>.</p>
            <pre style="white-space:pre-wrap;overflow-wrap:anywhere;color:#fecaca">${safeMessage}</pre>
            <button type="button" class="btn primary" id="btnRetryRenderPage">Tentar abrir novamente</button>
            <button type="button" class="btn" id="btnReturnCentralAfterRenderError">${homeLabel}</button>
          </section>`;
          $('#btnRetryRenderPage')?.addEventListener('click', render);
          $('#btnReturnCentralAfterRenderError')?.addEventListener('click', () => { view = homeView; render(); });
        } catch(fallbackError){
          recordAFMError('render-error-ui', fallbackError);
          mainEl.textContent = 'Erro ao renderizar a tela: ' + safeMessage;
        }
        sideNav.querySelectorAll('[data-view]').forEach(b => {
          b.classList.toggle('active', b.dataset.view === view);
        });
        restore();
        return;
      }
    }
    app.innerHTML=shell(page());
    if(app.dataset) app.dataset.renderedGameMode = currentMode;
    bind();
    triggerAFMSystemEnhancements();
    restore();
  } catch(err){
    recordAFMError('render-shell', err);
    console.error('Falha ao renderizar o aplicativo:', err);
    try {
      renderSetup(app);
    } catch(setupErr) {
      app.innerHTML = `<div style="padding:40px;text-align:center;color:#fff;font-family:system-ui">
        <h2>⚽ AFM MANAGER 2027</h2>
        <p style="color:#94a3b8">Recuperando inicialização do simulador...</p>
        <button class="btn primary" onclick="location.reload();" style="padding:10px 20px;margin-top:10px">Recarregar Página</button>
      </div>`;
    }
  } finally {
    window.__afmIsRendering = false;
    const loader = document.getElementById('afmLoadingScreen');
    if(loader){
      loader.style.transition = 'opacity 0.2s ease';
      loader.style.opacity = '0';
      loader.style.pointerEvents = 'none';
      setTimeout(() => { if(loader && loader.parentNode) loader.remove(); }, 200);
    }
  }
}


function closeMatchActionModal(){
  const m = document.getElementById('appMatchActionModal');
  if(m) m.remove();
}
window.closeMatchActionModal = closeMatchActionModal;

function handleExitGameAction(){
  openCustomModal(
    'Sair para o Menu Principal',
    '<div style="text-align:center;padding:10px 0;">' +
      '<div style="font-size:36px;margin-bottom:8px">💾</div>' +
      '<p style="font-size:14px;color:#fff;font-weight:700;margin:0 0 6px 0;">Deseja sair para o Menu Inicial?</p>' +
      '<p style="font-size:12px;color:rgba(255,255,255,0.7);margin:0;">Seu jogo será <b>salvo automaticamente</b> na sua conta antes de sair.</p>' +
    '</div>',
    ()=>{
      try {
        if (typeof window.toggleAFMMobileDrawer === 'function') window.toggleAFMMobileDrawer(false);
        const owner = state?.userOwner || (typeof getActiveAccount === 'function' ? getActiveAccount()?.username : null) || 'aquino';
        if (typeof save === 'function') save({ force: true, manual: true });
        if (typeof setActiveAccount === 'function') {
          setActiveAccount(owner && localStorage.getItem('afm_remember_login_v1') !== 'false' ? owner : null);
        }
        if (typeof closeMatchActionModal === 'function') closeMatchActionModal();
        const pModal = document.getElementById('appMatchPreviewModal');
        if (pModal) pModal.remove();
        const pressModal = document.getElementById('appPressConferenceModal');
        if (pressModal) pressModal.remove();
        const customModal = document.getElementById('appCustomModal');
        if (customModal) customModal.remove();

        // Limpa estado ativo, pausa auto-saves e libera trava de modo da sessão antes do menu
        if (window.AFM_SETUP_GUARD && typeof window.AFM_SETUP_GUARD.enterSetupCleanly === 'function') {
          window.AFM_SETUP_GUARD.enterSetupCleanly();
        }
        state = null;
        window.state = null;
        window.GameState = null;
        setupViewMode = 'select';

        const appEl = document.querySelector('#app');
        if (appEl && typeof renderSetup === 'function') {
          try { renderSetup(appEl); } catch(errSetup) { console.error('Erro ao renderizar setup após sair:', errSetup); }
        } else if (typeof render === 'function') {
          render();
        }

        if (typeof toast === 'function') toast('💾 Jogo salvo automaticamente! Escolha uma campanha salva ou inicie uma nova carreira.');
      } catch(exitErr) {
        console.error('Erro ao sair para o menu:', exitErr);
        state = null;
        window.state = null;
        window.GameState = null;
        setupViewMode = 'select';
        if (typeof render === 'function') render();
      }
    },
    'Sim, Salvar e Sair',
    true
  );
}
window.handleExitGameAction = handleExitGameAction;



function openMatchActionModal(){
  if(!state) return;
  closeMatchActionModal();

  const matchGate = (typeof canStartMatch === 'function') ? canStartMatch(null, state) : { canStart: false };
  if(matchGate.status === 'season_finished'){
    if(typeof showEndOfSeasonModal === 'function') showEndOfSeasonModal();
    return;
  }
  if(matchGate.status === 'other_competitions_pending'){
    if(typeof openNextPendingCompetitionFixture === 'function'){
      openNextPendingCompetitionFixture(matchGate.nextFixture || (typeof getNextPendingClubFixture === 'function' ? getNextPendingClubFixture(state) : null));
      return;
    }
  }

  const activeMatch = (typeof getActualCurrentMatch === 'function') ? getActualCurrentMatch(state) : null;
  const f = activeMatch ? activeMatch.fixture : (typeof userFixture === 'function' ? userFixture() : null);
  const oppFallback = state.teams?.find(t => norm(t.name) !== norm(state.club))?.name || (norm(state.club)==='brasilia'?'Gama':'Brasília');
  const opp = activeMatch ? activeMatch.opponent : (f ? (norm(f[0])===norm(state.club) ? f[1] : f[0]) : oppFallback);
  const isHome = activeMatch ? activeMatch.isHome : (f ? norm(f[0])===norm(state.club) : true);
  const home = isHome ? state.club : opp;
  const away = isHome ? opp : state.club;
  const comp = typeof curComp === 'function' ? curComp() : null;
  const displayCompName = activeMatch?.competitionName || comp?.name || state.competition || 'Campeonato';
  const displayRoundLabel = activeMatch?.roundLabel || ('Rodada ' + ((state.round || 0) + 1));
  const our = typeof overallSquad === 'function' ? overallSquad() : 70;
  const oppStr = opp && typeof teamStrengthByName === 'function' ? teamStrengthByName(opp) : 65;
  const matchDate = activeMatch ? activeMatch.date : (typeof getDateForRound === 'function' ? getDateForRound(state.round || 0, state.season || 2026) : state.date);
  const isMatchDay = state.date === matchDate || Boolean(matchGate.canStart);

  const clubObj = (typeof clubByName === 'function' ? clubByName(state.club) : null) || { stadium: 'Estádio Principal' };
  const oppObj = opp && typeof clubByName === 'function' ? clubByName(opp) : null;
  const stadiumName = isHome ? (clubObj.stadium || 'Estádio Principal') : (oppObj?.stadium || 'Estádio Adversário');
  const weather = (typeof getMatchWeather === 'function') ? getMatchWeather(state.date, state.round || 0) : { icon: '☀️', condition: 'Tempo Aberto', temp: 24, impact: 'Gramado Perfeito', drain: 1.0 };
  const h2h = (typeof getHeadToHeadRecord === 'function') ? getHeadToHeadRecord(state.club, opp) : { winsA: 0, draws: 0, winsB: 0, total: 0 };
  const caldeirao = (typeof getCaldeiraoData === 'function') ? getCaldeiraoData() : { caldeiraoPercent: 15 };

  // Standings / Position
  let myPos = 1;
  let totalInTable = 20;
  if(Array.isArray(state.teams) && state.teams.length > 0){
    const sorted = state.teams.slice().sort((a,b) => b.p - a.p || b.sg - a.sg || b.gp - a.gp);
    myPos = (sorted.findIndex(t => norm(t.name) === norm(state.club)) + 1) || 1;
    totalInTable = state.teams.length;
  } else if(typeof position === 'function'){
    myPos = position() || 1;
  }

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay active afm-match-action-modal-overlay';
  overlay.id = 'appMatchActionModal';
  overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;pointer-events:auto;z-index:999999;';

  overlay.innerHTML = `
    <div class="modal afm-match-action-modal" style="max-width:660px;width:95%;padding:22px;background:#0d1117;border:1px solid rgba(168,85,247,0.4);border-radius:20px;box-shadow:0 16px 50px rgba(0,0,0,0.9);position:relative;">
      <!-- Header do Modal -->
      <div style="display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,0.08);padding-bottom:12px;margin-bottom:12px;">
        <div style="display:flex;align-items:center;gap:10px;">
          <span style="font-size:24px">🏆</span>
          <div>
            <div style="font-size:16px;font-weight:900;color:#fff;text-transform:uppercase;letter-spacing:0.5px;">${esc(displayCompName)}</div>
            <div style="font-size:11px;color:rgba(255,255,255,0.6);">${esc(displayRoundLabel)} · Data do Jogo: ${formatDatePtBr(matchDate)}</div>
          </div>
        </div>
        <button type="button" class="modal-close-btn" id="btnMatchModalClose" title="Fechar" style="background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);color:#fff;font-size:16px;width:32px;height:32px;border-radius:8px;cursor:pointer;display:flex;align-items:center;justify-content:center;">✕</button>
      </div>

      <!-- Barra de Clima e Gramado -->
      <div style="display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:8px 12px;margin-bottom:12px;font-size:11px;">
        <div style="display:flex;align-items:center;gap:6px;">
          <span style="font-size:15px">${weather.icon}</span>
          <span style="color:#e2e8f0;font-weight:700;">Clima: ${esc(weather.condition)} (${weather.temp}°C)</span>
        </div>
        <span style="color:${weather.drain > 1.1 ? '#f87171' : '#94a3b8'};font-size:10px;font-weight:700;">${esc(weather.impact)}</span>
      </div>

      <!-- Pitch do Confronto Estilo Soccer Manager 2027 -->
      <div class="sm-hero-match-pitch" style="padding:16px;margin:0 0 12px 0;border-radius:14px;background:linear-gradient(135deg,rgba(16,185,129,0.08),rgba(124,58,237,0.08));border:1px solid rgba(255,255,255,0.1);">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;">
          <div style="display:flex;align-items:center;gap:12px;flex:1;min-width:240px;justify-content:center;">
            <!-- Mandante -->
            <div style="display:flex;flex-direction:column;align-items:center;gap:6px;width:95px;text-align:center;">
              ${typeof clubBadge === 'function' ? clubBadge(home, 50) : ''}
              <div style="font-size:12px;font-weight:900;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:95px;">
                ${esc(home)}
              </div>
            </div>

            <!-- Overall Mandante -->
            <div class="sm-ovr-circle" style="border-color:${isHome ? '#a855f7' : '#38bdf8'};color:#fff;width:38px;height:38px;font-size:15px;display:flex;align-items:center;justify-content:center;border-radius:50%;border:2px solid;font-weight:900;background:rgba(0,0,0,0.4);" title="Força do Mandante">
              ${isHome ? our : oppStr}
            </div>

            <div style="font-size:18px;font-weight:900;color:rgba(255,255,255,0.4);">-</div>

            <!-- Overall Visitante -->
            <div class="sm-ovr-circle" style="border-color:${!isHome ? '#a855f7' : '#38bdf8'};color:#fff;width:38px;height:38px;font-size:15px;display:flex;align-items:center;justify-content:center;border-radius:50%;border:2px solid;font-weight:900;background:rgba(0,0,0,0.4);" title="Força do Visitante">
              ${!isHome ? our : oppStr}
            </div>

            <!-- Visitante -->
            <div style="display:flex;flex-direction:column;align-items:center;gap:6px;width:95px;text-align:center;">
              ${typeof clubBadge === 'function' ? clubBadge(away, 50) : ''}
              <div style="font-size:12px;font-weight:900;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:95px;">
                ${esc(away)}
              </div>
            </div>
          </div>

          <!-- Botão Lateral: Meu Time & Tática (Unificado) -->
          <div style="display:flex;align-items:center;justify-content:center;">
            <button type="button" class="btn" id="btnMatchModalTactics" title="Abrir Meu Time & Tática" style="padding:8px 16px;font-size:12px;font-weight:900;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);border-radius:10px;color:#fff;cursor:pointer;white-space:nowrap;display:flex;align-items:center;gap:7px;transition:all 0.2s ease;">
              <span>📋</span> Meu Time & Tática
            </button>
          </div>
        </div>

        <!-- Metadados da Partida -->
        <div style="display:flex;align-items:center;justify-content:space-between;margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,0.08);font-size:11px;color:rgba(255,255,255,0.7);flex-wrap:wrap;gap:6px;">
          <span class="pill" style="font-size:10px;font-weight:800;background:rgba(16,185,129,0.2);color:#34d399;border:1px solid rgba(16,185,129,0.4);">
            🏆 ${esc(displayCompName)}
          </span>
          <span>📅 ${formatDatePtBr(matchDate)}</span>
          <span>⏰ 15:00 Pontapé de saída</span>
          <span>🏟️ ${esc(stadiumName)}</span>
        </div>
      </div>

      <!-- Histórico Direto -->
      <div style="${h2h.hide ? 'display:none;' : ''}background:#141122;border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:7px 12px;text-align:center;font-size:11px;color:rgba(255,255,255,0.7);margin-bottom:10px;">
        ⚔️ Histórico Direto: <b style="color:#22c55e">${h2h.winsA}V</b> · <b style="color:#94a3b8">${h2h.draws}E</b> · <b style="color:#ef4444">${h2h.winsB}D</b> <span class="muted">(${h2h.total} jogos)</span>
      </div>

      <!-- Caldeirão & Tabela -->
      <div style="display:flex;justify-content:space-around;gap:8px;font-size:11px;color:rgba(255,255,255,0.6);text-align:center;margin:8px 0 12px 0;">
        <div>🔥 <b>CALDEIRÃO (+${caldeirao.caldeiraoPercent}%)</b></div>
        <div>📊 <b>NA TABELA:</b> ${myPos}º de ${totalInTable}</div>
      </div>

      <!-- Escalação e Mentalidade Rápida -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px;">
        <div style="background:#161324;border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:8px 12px;">
          <div style="font-size:9px;font-weight:800;color:rgba(255,255,255,0.4);">ESCALAÇÃO</div>
          <div style="font-size:13px;font-weight:900;color:#fff;margin-top:2px;">${esc(state.formation || '4-3-3')} &gt;</div>
        </div>
        <div style="background:#161324;border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:8px 12px;">
          <div style="font-size:9px;font-weight:800;color:rgba(255,255,255,0.4);">MENTALIDADE</div>
          <select id="matchModalMental" style="background:transparent;border:none;color:#fff;font-size:12px;font-weight:900;width:100%;cursor:pointer;">
            ${['Retranca','Defensiva','Equilibrada','Ofensiva','Pressão total'].map(x=>`<option value="${x}" ${state.mentality===x?'selected':''}>${x}</option>`).join('')}
          </select>
        </div>
      </div>

      <!-- Banner de Dia de Jogo -->
      <div style="background:${isMatchDay ? 'rgba(34,197,94,0.15)' : 'rgba(56,189,248,0.15)'};border:1px solid ${isMatchDay ? '#22c55e' : '#38bdf8'};border-radius:10px;padding:8px 12px;display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">
        <span style="font-size:11px;color:${isMatchDay ? '#86efac' : '#bae6fd'};font-weight:900;">
          ${isMatchDay ? ('🔥 HOJE É DIA DE JOGO: ' + esc(displayCompName).toUpperCase() + '!') : ('📅 CONFRONTO CONFIRMADO: ' + esc(displayCompName).toUpperCase() + '!')}
        </span>
        <span style="font-size:11px;color:${isMatchDay ? '#22c55e' : '#38bdf8'};font-weight:800;">${formatDatePtBr(state.date)}</span>
      </div>

      <!-- OS 3 BOTÕES DE AÇÃO: JOGAR AO VIVO, SIMULAR, PRÉVIA -->
      <div style="display:grid;grid-template-columns:2fr 1.2fr 1fr;gap:8px;">
        <button type="button" class="btn primary" id="btnMatchModalPlayLive" style="padding:14px 10px;font-size:14px;font-weight:900;letter-spacing:0.5px;background:linear-gradient(135deg, #7c3aed, #9333ea);border:none;border-radius:12px;box-shadow:0 6px 18px rgba(124,58,237,0.4);color:#fff;cursor:pointer;">
          ▶ JOGAR AO VIVO
        </button>
        <button type="button" class="btn" id="btnMatchModalSimulate" style="padding:14px 6px;font-size:12px;font-weight:800;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.15);border-radius:12px;color:#fff;cursor:pointer;">
          ⚡ SIMULAR
        </button>
        <button type="button" class="btn" id="btnMatchModalPreview" style="padding:14px 6px;font-size:12px;font-weight:800;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.15);border-radius:12px;color:#fff;cursor:pointer;">
          📋 PRÉVIA
        </button>
      </div>
    </div>
  `;

  document.body.appendChild(overlay);

  // Bind dos eventos do modal
  overlay.onclick = (e) => {
    if(e.target === overlay) closeMatchActionModal();
  };
  const bClose = overlay.querySelector('#btnMatchModalClose');
  if(bClose) bClose.onclick = closeMatchActionModal;

  const bSquad = overlay.querySelector('#btnMatchModalSquad');
  if(bSquad) bSquad.onclick = () => {
    closeMatchActionModal();
    view = 'elenco';
    render();
  };

  const bTactics = overlay.querySelector('#btnMatchModalTactics');
  if(bTactics) bTactics.onclick = () => {
    closeMatchActionModal();
    view = 'meutime';
    render();
  };

  const selMental = overlay.querySelector('#matchModalMental');
  if(selMental) selMental.onchange = () => {
    state.mentality = selMental.value;
    if(typeof save === 'function') save();
    if(typeof toast === 'function') toast('Mentalidade tática atualizada.');
  };

  const bLive = overlay.querySelector('#btnMatchModalPlayLive');
  if(bLive) bLive.onclick = () => {
    closeMatchActionModal();
    if(typeof startLiveMatch === 'function') startLiveMatch();
  };

  const bSim = overlay.querySelector('#btnMatchModalSimulate');
  if(bSim) bSim.onclick = () => {
    closeMatchActionModal();
    if(typeof simulateQuickRound === 'function') simulateQuickRound();
  };

  const bPrev = overlay.querySelector('#btnMatchModalPreview');
  if(bPrev) bPrev.onclick = () => {
    closeMatchActionModal();
    window.__afmOpenedFromMatchActionModal = true;
    if(typeof openMatchPreviewModal === 'function'){
      openMatchPreviewModal(home, away, displayCompName, matchDate, {
        returnToMatchActionModal: true,
        onClose: () => {
          if(typeof openMatchActionModal === 'function') openMatchActionModal();
        }
      });
    } else if(typeof openClubInfoModal === 'function'){
      openClubInfoModal(opp);
    }
  };
}
window.openMatchActionModal = openMatchActionModal;

