function continentalFixtureId(competitionId, fixture){
  const compact = value => norm(value).replace(/[^a-z0-9]/g, '');
  return `${competitionId}-${state.season}-${fixture.round}-${fixture.group}-${compact(fixture.home)}-${compact(fixture.away)}`;
}

function getContinentalTournament(competitionId){
  if(!['lib','sud','ucl','uel','uecl','afc-el','afc2','cwc'].includes(competitionId) || !window.AFM_TOURNAMENT_ENGINE) return null;
  state.tournaments = state.tournaments || {};
  const current = state.tournaments[competitionId];
  if(current?.season === Number(state.season)){
    if(Array.isArray(current.matches)){
      current.matches.forEach(m => {
        if(m.date && typeof ensureMidweekDate === 'function') m.date = ensureMidweekDate(m.date, state.season);
      });
    }
    return current;
  }
  const priorQualification = state.continentalQualifications?.[Number(state.season)]?.[competitionId];
  // Fixed participants are only a bootstrap template for 2026. Future editions
  // must be backed by the prior season's persisted qualification record.
  if(Number(state.season) !== 2026 && (!priorQualification || priorQualification.status !== 'qualified')) return null;
  let groups = priorQualification?.groups || (Number(state.season) === 2026 ? window.AFM_CONTINENTAL_2026?.groups?.[competitionId] : null) || null;
  if(!groups){
    const catalogParticipants = (Array.isArray(state?.competitionTeams?.[competitionId]) && state.competitionTeams[competitionId].length)
      ? state.competitionTeams[competitionId]
      : (Array.isArray(window.COMPETITION_TEAMS?.[competitionId]) && window.COMPETITION_TEAMS[competitionId].length)
        ? window.COMPETITION_TEAMS[competitionId]
        : (typeof BASE_COMPETITION_TEAMS !== 'undefined' && Array.isArray(BASE_COMPETITION_TEAMS?.[competitionId]))
          ? BASE_COMPETITION_TEAMS[competitionId]
          : [];
    const participants = (Array.isArray(priorQualification?.participants) && priorQualification.participants.length)
      ? priorQualification.participants
      : (Number(state.season) === 2026 ? catalogParticipants : []);
    const comp = compById(competitionId);
    if(!participants.length || (Number(state.season) !== 2026 && priorQualification?.status !== 'qualified')) return null;
    groups = {};
    if(['ucl','uel','uecl','afc-el'].includes(competitionId)){
      groups.LEAGUE = participants;
    } else {
      const groupCount = ['cwc','afc2','lib','sud'].includes(competitionId) ? (competitionId === 'cwc' ? 4 : 8) : Math.ceil(participants.length / 4);
      const groupSize = 4;
      for(let index = 0; index < participants.length; index++){
        const group = String.fromCharCode(65 + (Math.floor(index / groupSize) % groupCount));
        (groups[group] ||= []).push(participants[index]);
      }
    }
  }
  let fixtures;
  if(['ucl','uel','uecl','afc-el'].includes(competitionId) && Array.isArray(groups.LEAGUE)){
    const configuredRounds = Number(compById(competitionId)?.rounds) || 8;
    fixtures = window.AFM_TOURNAMENT_ENGINE.roundRobinFixtures({ id:competitionId, season:Number(state.season), teamNames:groups.LEAGUE, startDate:`${state.season}-03-04`, homeAway:false })
      .filter(fixture => fixture.round <= configuredRounds);
  } else {
    fixtures = window.AFM_TOURNAMENT_ENGINE.groupFixtures({ id:competitionId, season:Number(state.season), groups, startDate:`${state.season}-03-04` });
  }
  if(Array.isArray(fixtures)){
    fixtures.forEach(f => {
      if(f.date && typeof ensureMidweekDate === 'function') f.date = ensureMidweekDate(f.date, state.season);
    });
  }
  state.tournaments[competitionId] = window.AFM_TOURNAMENT_ENGINE.createGroupTournament({
    id: competitionId, season: Number(state.season), groups, fixtures
  });
  return state.tournaments[competitionId];
}

function playContinentalFixture(competitionId, matchId){
  const tournament = getContinentalTournament(competitionId);
  const match = tournament?.matches.find(item => item.id === matchId);
  if(!match || match.status !== 'scheduled') return;
  const mDate = match.date || ensureMidweekDate(match.date, state.season);
  if(state.date < mDate){
    state.date = mDate;
    state.currentDate = mDate;
    state.currentDateFormatted = formatDatePtBr(mDate);
  }
  if(norm(match.home) !== norm(state.club) && norm(match.away) !== norm(state.club)) return;
  const dateFixtures = tournament.matches.filter(item => item.date === match.date && item.status === 'scheduled');
  let userResult = null;
  for(const fixture of dateFixtures){
    const [homeGoals, awayGoals] = simulateScore(fixture.home, fixture.away);
    window.AFM_TOURNAMENT_ENGINE.recordResult(tournament, fixture.id, homeGoals, awayGoals);
    if(norm(fixture.home) === norm(state.club) || norm(fixture.away) === norm(state.club)){
      const isHomeCont = norm(fixture.home) === norm(state.club);
      const uGoals = isHomeCont ? homeGoals : awayGoals;
      const oGoals = isHomeCont ? awayGoals : homeGoals;
      const oClub = isHomeCont ? fixture.away : fixture.home;
      const events = simulateUserGoalEvents(state.club, uGoals);
      addPlayerMatchStats(competitionId, state.club, events);
      if(oGoals > 0) addPlayerMatchStats(competitionId, oClub, simulateClubGoalEvents(oClub, oGoals, competitionId));
      const compLabel = compById(competitionId)?.name || (competitionId === 'lib' ? 'Copa Libertadores' : competitionId === 'sud' ? 'Copa Sul-Americana' : competitionId);
      userResult = { h: fixture.home, a: fixture.away, hg: homeGoals, ag: awayGoals, events, round: fixture.round, season: Number(state.season), date: state.date, competitionId, competitionName: compLabel };
    } else {
      if(homeGoals > 0) addPlayerMatchStats(competitionId, fixture.home, simulateClubGoalEvents(fixture.home, homeGoals, competitionId));
      if(awayGoals > 0) addPlayerMatchStats(competitionId, fixture.away, simulateClubGoalEvents(fixture.away, awayGoals, competitionId));
    }
  }
  if(typeof syncCompetitionStatsComprehensive === 'function') syncCompetitionStatsComprehensive(competitionId);
  if(userResult){
    state.history = [userResult, ...(state.history || [])].slice(0, 100);
    if(window.AFM_MarketLupaAndAging && typeof window.AFM_MarketLupaAndAging.processRoundMatchStats === 'function'){
      window.AFM_MarketLupaAndAging.processRoundMatchStats(state, { h: userResult.h, a: userResult.a, hg: userResult.hg, ag: userResult.ag, gf: (norm(userResult.h) === norm(state.club) ? userResult.hg : userResult.ag), ga: (norm(userResult.h) === norm(state.club) ? userResult.ag : userResult.hg), won: state.lastMatchSummary?.won, events: userResult.events });
    }
    state.lastMatchSummary = { h:userResult.h, a:userResult.a, hg:userResult.hg, ag:userResult.ag, isHome:norm(userResult.h)===norm(state.club), won:(norm(userResult.h)===norm(state.club)?userResult.hg>userResult.ag:userResult.ag>userResult.hg) };
    const payroll = typeof payrollPerRound === 'function' ? payrollPerRound() : 0;
    const facilitiesExp = typeof facilitiesExpensesPerRound === 'function' ? facilitiesExpensesPerRound(state) : 0;
    state.balance -= (payroll + facilitiesExp);
    state.expense = (state.expense || 0) + (payroll + facilitiesExp);
  }
  state.news = state.news || [];
  const compLabel = compById(match.competitionId)?.name || (match.competitionId === 'lib' ? 'Libertadores' : match.competitionId === 'sud' ? 'Sul-Americana' : match.competitionId);
  state.news.unshift(`🏆 ${compLabel}: rodada ${match.round} concluída; classificação atualizada.`);
  advanceDateAfterMatch(state);
  if(typeof window !== 'undefined' && window.AFM_LifeAndSharesPro && typeof window.AFM_LifeAndSharesPro.processRoundTurn === 'function'){
    window.AFM_LifeAndSharesPro.processRoundTurn(state);
  }
  if(typeof processFitness === 'function') processFitness();
  if(typeof processDevelopment === 'function') processDevelopment();
  save();
  toast('Partidas continentais da data simuladas; classificação salva.');
  render();
  if(userResult){
    triggerPostMatchFlow(userResult);
  } else {
    view = 'central';
    render();
  }
}

function processContinentalFixturesBefore(date){
  if(!Number.isFinite(Number(state?.season))) return;
  const userClubNorm = norm(state?.club);
  for(const competitionId of ['lib','sud','ucl','uel','uecl','afc-el','afc2','cwc']){
    const tournament = getContinentalTournament(competitionId);
    for(const match of tournament?.matches || []){
      if(match.status !== 'scheduled' || match.date >= date) continue;
      // NUNCA auto-simular jogos do clube do usuário em segundo plano!
      if(userClubNorm && (norm(match.home) === userClubNorm || norm(match.away) === userClubNorm)) continue;
      const [homeGoals, awayGoals] = simulateScore(match.home, match.away);
      window.AFM_TOURNAMENT_ENGINE.recordResult(tournament, match.id, homeGoals, awayGoals);
    }
  }
}

// -------------------------------------------------------------
// ABA CALENDÁRIO COM DATAS OFICIAIS E JANELAS DE TRANSFERÊNCIA
// -------------------------------------------------------------
// CENTRAL DO CALENDÁRIO OFICIAL & MODAL DE PRÉVIA / SÚMULA
// -------------------------------------------------------------
window.AFM_CALENDAR_HUB = {
  // 1. CÁLCULO PRECISO DAS JANELAS OFICIAIS DE TRANSFERÊNCIA (CBF / FIFA)
  // Verão: 01/Jan a 31/Mar (90 dias ou 91 em ano bissexto)
  // Inverno: 10/Jul a 02/Set (55 dias corridos inclusive)
  getTransferWindowStatus(dateStr) {
    const st = (typeof state !== 'undefined' && state) ? state : ((typeof window !== 'undefined' && window.state) ? window.state : null);
    if(st?.freeTransferWindow) {
      return {
        open: true,
        text: 'Janela Aberta (Modo Livre)',
        detail: 'Contratações e vendas liberadas em todas as datas',
        badgeClass: 'window-open',
        windowName: 'Modo Livre',
        currentDay: 1,
        totalDays: 1,
        daysRemaining: 999
      };
    }

    const curDateStr = dateStr || st?.date || st?.currentDate || '2026-01-01';
    const parts = String(curDateStr).split('-').map(Number);
    const year = parts[0] || 2026;
    const month = parts[1] || 1;
    const day = parts[2] || 1;
    const curTime = new Date(year, month - 1, day).getTime();

    // Janela 1: Verão (01/Jan a 31/Mar)
    const summerStart = new Date(year, 0, 1).getTime();
    const summerEnd = new Date(year, 2, 31).getTime();
    const summerTotalDays = Math.round((summerEnd - summerStart) / 86400000) + 1;

    // Janela 2: Inverno (10/Jul a 02/Set)
    const winterStart = new Date(year, 6, 10).getTime();
    const winterEnd = new Date(year, 8, 2).getTime();
    const winterTotalDays = Math.round((winterEnd - winterStart) / 86400000) + 1;

    if(curTime >= summerStart && curTime <= summerEnd) {
      const currentDay = Math.round((curTime - summerStart) / 86400000) + 1;
      const daysRemaining = Math.max(0, summerTotalDays - currentDay);
      return {
        open: true,
        text: `Janela Aberta (Dia ${currentDay} de ${summerTotalDays})`,
        detail: `${daysRemaining} dias restantes`,
        badgeClass: 'window-open',
        windowName: 'Janela de Verão',
        currentDay,
        totalDays: summerTotalDays,
        daysRemaining
      };
    }

    if(curTime >= winterStart && curTime <= winterEnd) {
      const currentDay = Math.round((curTime - winterStart) / 86400000) + 1;
      const daysRemaining = Math.max(0, winterTotalDays - currentDay);
      return {
        open: true,
        text: `Janela Aberta (Dia ${currentDay} de ${winterTotalDays})`,
        detail: `${daysRemaining} dias restantes`,
        badgeClass: 'window-open',
        windowName: 'Janela de Inverno',
        currentDay,
        totalDays: winterTotalDays,
        daysRemaining
      };
    }

    // Janela Fechada
    let nextOpenDate = '';
    let daysToNext = 0;
    if(curTime < winterStart && curTime > summerEnd) {
      nextOpenDate = `10/07/${year}`;
      daysToNext = Math.round((winterStart - curTime) / 86400000);
    } else {
      const nextSummerStart = new Date(year + 1, 0, 1).getTime();
      nextOpenDate = `01/01/${year + 1}`;
      daysToNext = Math.round((nextSummerStart - curTime) / 86400000);
    }

    return {
      open: false,
      text: `Janela Fechada (Reabre em ${nextOpenDate})`,
      detail: `Reabre em ${daysToNext} dias`,
      badgeClass: 'window-closed',
      windowName: 'Janela Fechada',
      currentDay: 0,
      totalDays: 0,
      daysRemaining: 0,
      nextOpenDate
    };
  },

  // 2. DETECTOR DE CLÁSSICOS & RIVALIDADES HISTÓRICAS
  isDerbyMatch(clubA, clubB) {
    if(!clubA || !clubB) return false;
    const nA = (typeof norm === 'function' ? norm(clubA) : String(clubA).toLowerCase().trim());
    const nB = (typeof norm === 'function' ? norm(clubB) : String(clubB).toLowerCase().trim());
    if(nA === nB) return false;

    const derbyPairs = [
      // DF (Candango)
      ['gama', 'brasiliense'], ['gama', 'ceilandia'], ['brasiliense', 'ceilandia'],
      ['gama', 'brasilia'], ['brasiliense', 'capital-df'], ['brasilia', 'brasiliense'],
      ['ceilandia', 'capital-df'], ['paranoa', 'samambaia'], ['real brasilia', 'capital-df'],
      ['gama', 'real brasilia'], ['brasiliense', 'real brasilia'],
      // SP
      ['corinthians', 'palmeiras'], ['sao paulo', 'corinthians'], ['palmeiras', 'sao paulo'],
      ['santos', 'corinthians'], ['palmeiras', 'santos'], ['sao paulo', 'santos'],
      ['guarani', 'ponte preta'], ['juventus', 'portuguesa'],
      // RJ
      ['flamengo', 'fluminense'], ['flamengo', 'vasco'], ['fluminense', 'vasco'],
      ['botafogo', 'flamengo'], ['botafogo', 'fluminense'], ['botafogo', 'vasco'],
      ['bangu', 'america-rj'],
      // MG
      ['atletico-mg', 'cruzeiro'], ['america-mg', 'atletico-mg'], ['america-mg', 'cruzeiro'],
      // RS
      ['gremio', 'internacional'], ['juventude', 'caxias'], ['brasil de pelotas', 'pelotas'],
      // PR
      ['coritiba', 'athletico-pr'], ['coritiba', 'parana'], ['athletico-pr', 'parana'],
      // BA
      ['bahia', 'vitoria'],
      // SC
      ['avai', 'figueirense'], ['chapecoense', 'criciuma'], ['joinville', 'avai'],
      // CE
      ['ceara', 'fortaleza'], ['ferroviario', 'ceara'], ['ferroviario', 'fortaleza'],
      // PE
      ['sport', 'santa cruz'], ['nautico', 'sport'], ['nautico', 'santa cruz'],
      // GO
      ['goias', 'vila nova'], ['atletico-go', 'goias'], ['atletico-go', 'vila nova'],
      // PA
      ['remo', 'paysandu'],
      // AL
      ['crb', 'csa'],
      // RN
      ['abc', 'america-rn']
    ];

    return derbyPairs.some(([c1, c2]) => (nA.includes(c1) && nB.includes(c2)) || (nA.includes(c2) && nB.includes(c1)));
  },

  // 3. ESCUDO VETORIAL FALLBACK ANTI-404
  buildCrestFallbackUri(abbr, name) {
    const letters = (abbr || (name ? name.replace(/[^a-zA-Z]/g, '').slice(0, 3) : 'AFM')).toUpperCase() || 'AFM';
    const bg = '#1e293b';
    const fg = '#38bdf8';
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64"><polygon points="32,4 58,16 58,44 32,60 6,44 6,16" fill="${bg}" stroke="${fg}" stroke-width="2"/><text x="32" y="38" text-anchor="middle" font-size="14" font-weight="900" font-family="system-ui, sans-serif" fill="${fg}">${letters}</text></svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
  },

  // 4. RESUMO ESTATÍSTICO DA TEMPORADA
  computeSeasonSummary(calendarMatches, myClub, gameState) {
    const clubKey = name => (typeof norm === 'function' ? norm(name) : String(name || '').toLowerCase().trim());
    const mClubKey = clubKey(myClub);

    let played = 0;
    let wins = 0;
    let draws = 0;
    let losses = 0;
    let derbiesTotal = 0;
    let derbiesPlayed = 0;
    let derbiesWins = 0;
    let derbiesDraws = 0;
    let derbiesLosses = 0;

    const streakMatches = [];

    (calendarMatches || []).forEach(match => {
      const isDerby = window.AFM_CALENDAR_HUB.isDerbyMatch(match.home, match.away);
      if(isDerby) derbiesTotal++;

      const res = (typeof resolveCalendarMatchResult === 'function')
        ? resolveCalendarMatchResult(match, gameState)
        : (Array.isArray(match.result) && match.result.length >= 2 ? match.result : null);

      if(Array.isArray(res) && res.length >= 2) {
        played++;
        const isHome = clubKey(match.home) === mClubKey;
        const myGoals = isHome ? Number(res[0]) || 0 : Number(res[1]) || 0;
        const oppGoals = isHome ? Number(res[1]) || 0 : Number(res[0]) || 0;

        let resultType = 'E';
        if(myGoals > oppGoals) {
          wins++;
          resultType = 'V';
          if(isDerby) derbiesWins++;
        } else if(myGoals < oppGoals) {
          losses++;
          resultType = 'D';
          if(isDerby) derbiesLosses++;
        } else {
          draws++;
          if(isDerby) derbiesDraws++;
        }

        if(isDerby) derbiesPlayed++;
        streakMatches.push({ date: match.date, resultType });
      }
    });

    const total = (calendarMatches || []).length;
    const points = wins * 3 + draws;
    const winRate = played > 0 ? Math.round((points / (played * 3)) * 100) : 0;

    streakMatches.sort((a,b) => b.date.localeCompare(a.date));
    let streakText = '—';
    let streakSub = 'Aguardando início';
    if(streakMatches.length > 0) {
      const lastRes = streakMatches[0].resultType;
      let count = 0;
      for(const m of streakMatches) {
        if(m.resultType === lastRes) count++;
        else break;
      }
      if(lastRes === 'V') {
        streakText = `🔥 ${count}V seguidas`;
        streakSub = 'Fase vitoriosa';
      } else if(lastRes === 'D') {
        streakText = `⚠️ ${count}D seguidas`;
        streakSub = 'Alerta de rendimento';
      } else {
        streakText = `⚖️ ${count}E seguidos`;
        streakSub = 'Sequência de empates';
      }
    }

    const derbiesRecord = derbiesPlayed > 0
      ? `${derbiesWins}V · ${derbiesDraws}E · ${derbiesLosses}D`
      : 'Nenhum clássico jogado';

    return {
      played,
      total,
      wins,
      draws,
      losses,
      points,
      winRate,
      streakText,
      streakSub,
      derbiesTotal,
      derbiesPlayed,
      derbiesRecord
    };
  }
};

