window.openMatchPreviewModal = function(home, away, compName, matchDate, options = {}) {
  document.getElementById('afmMatchPreviewModal')?.remove();

  const myClub = state?.club || '';
  const myClubNorm = (typeof norm === 'function' ? norm(myClub) : String(myClub).toLowerCase().trim());
  const isHome = (typeof norm === 'function' ? norm(home) : String(home).toLowerCase().trim()) === myClubNorm;
  const opp = isHome ? away : home;
  const hStrength = typeof teamStrengthByName === 'function' ? teamStrengthByName(home) : 60;
  const aStrength = typeof teamStrengthByName === 'function' ? teamStrengthByName(away) : 60;

  const homeAdv = 3;
  const netHomeRating = hStrength + homeAdv;
  const netAwayRating = aStrength;
  const diff = netHomeRating - netAwayRating;
  let pHome = Math.round(42 + diff * 2.2);
  let pDraw = Math.round(28 - Math.abs(diff) * 0.8);
  pHome = Math.max(15, Math.min(80, pHome));
  pDraw = Math.max(12, Math.min(35, pDraw));
  let pAway = 100 - (pHome + pDraw);
  if(pAway < 10) { pAway = 10; pDraw = 100 - pHome - pAway; }

  const history = Array.isArray(state?.history) ? state.history : [];
  const h2h = history.filter(h => {
    const hh = (typeof norm === 'function' ? norm(h.h) : String(h.h).toLowerCase().trim());
    const ha = (typeof norm === 'function' ? norm(h.a) : String(h.a).toLowerCase().trim());
    const hNorm = (typeof norm === 'function' ? norm(home) : String(home).toLowerCase().trim());
    const aNorm = (typeof norm === 'function' ? norm(away) : String(away).toLowerCase().trim());
    return (hh === hNorm && ha === aNorm) || (hh === aNorm && ha === hNorm);
  });

  const isDerby = window.AFM_CALENDAR_HUB ? window.AFM_CALENDAR_HUB.isDerbyMatch(home, away) : false;

  const overlay = document.createElement('div');
  overlay.id = 'afmMatchPreviewModal';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.85);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;backdrop-filter:blur(6px);animation:fadeIn 0.2s ease;';

  overlay.innerHTML = `
    <div style="background:#0f172a;border:1px solid rgba(255,255,255,0.15);border-radius:14px;max-width:540px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 25px 50px -12px rgba(0,0,0,0.7);padding:22px;position:relative;color:#f8fafc">
      <button type="button" id="btnCloseMatchPreviewModal" style="position:absolute;top:16px;right:16px;background:rgba(255,255,255,0.08);border:none;color:#94a3b8;width:32px;height:32px;border-radius:50%;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.15s">✕</button>

      <div style="text-align:center;margin-bottom:16px">
        <span class="pill" style="font-size:10px;font-weight:900;background:#1e293b;color:#38bdf8;padding:2px 8px;border-radius:12px">🏆 ${esc(compName || 'Confronto Oficial')}</span>
        ${isDerby ? '<span class="pill" style="margin-left:6px;font-size:10px;font-weight:900;background:rgba(239,68,68,0.25);color:#f87171;border:1px solid rgba(239,68,68,0.4)">🔥 CLÁSSICO REGIONAL</span>' : ''}
        <div class="small muted" style="margin-top:6px;font-size:11px">${matchDate ? 'Data: ' + formatDatePtBr(matchDate) : 'Temporada Oficial'}</div>
      </div>

      <div style="display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;background:rgba(255,255,255,0.03);padding:18px 12px;border-radius:12px;border:1px solid rgba(255,255,255,0.07)">
        <div style="text-align:center">
          <div style="display:flex;justify-content:center;margin-bottom:8px">${clubBadge(home, 48)}</div>
          <div style="font-weight:900;font-size:14px;color:#fff">${esc(home)}</div>
          <div class="small muted" style="font-size:11px">Força: <b style="color:#38bdf8">${hStrength}</b></div>
          <span class="pill" style="font-size:9px;margin-top:4px">🏠 Mandante</span>
        </div>
        <div style="text-align:center">
          <div style="font-size:20px;font-weight:900;color:#64748b">VS</div>
        </div>
        <div style="text-align:center">
          <div style="display:flex;justify-content:center;margin-bottom:8px">${clubBadge(away, 48)}</div>
          <div style="font-weight:900;font-size:14px;color:#fff">${esc(away)}</div>
          <div class="small muted" style="font-size:11px">Força: <b style="color:#38bdf8">${aStrength}</b></div>
          <span class="pill" style="font-size:9px;margin-top:4px">✈️ Visitante</span>
        </div>
      </div>

      <div style="margin-top:18px">
        <div style="font-size:11px;font-weight:800;text-transform:uppercase;color:#94a3b8;margin-bottom:6px;display:flex;justify-content:space-between">
          <span>Probabilidade do Confronto</span>
          <span>Vitória Casa / Empate / Fora</span>
        </div>
        <div style="display:flex;height:12px;border-radius:6px;overflow:hidden;background:#334155;margin-bottom:6px">
          <div style="width:${pHome}%;background:#38bdf8" title="${home}: ${pHome}%"></div>
          <div style="width:${pDraw}%;background:#94a3b8" title="Empate: ${pDraw}%"></div>
          <div style="width:${pAway}%;background:#f43f5e" title="${away}: ${pAway}%"></div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:11px;font-weight:700">
          <span style="color:#38bdf8">${pHome}% (${esc(home)})</span>
          <span style="color:#94a3b8">${pDraw}% (Empate)</span>
          <span style="color:#f43f5e">${pAway}% (${esc(away)})</span>
        </div>
      </div>

      <div style="margin-top:18px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.05);padding:12px;border-radius:10px">
        <div style="font-size:11px;font-weight:800;color:#cbd5e1;margin-bottom:6px">📜 Histórico Recente no Save (${h2h.length} confrontos)</div>
        ${h2h.length === 0 ? '<div class="small muted" style="font-size:11px">Nenhum confronto anterior registrado nesta carreira entre estas equipes.</div>' : `
          <div style="display:flex;flex-direction:column;gap:4px">
            ${h2h.slice(-3).map(h => {
              const hScore = h.hg !== undefined ? h.hg : h.homeGoals;
              const aScore = h.ag !== undefined ? h.ag : h.awayGoals;
              return `<div style="display:flex;justify-content:space-between;font-size:11px;padding:3px 6px;border-radius:4px;background:rgba(255,255,255,0.03)">
                <span>${esc(h.h)} vs ${esc(h.a)} (${esc(h.competitionId || 'Liga')})</span>
                <b>${hScore} x ${aScore}</b>
              </div>`;
            }).join('')}
          </div>
        `}
      </div>

      <div style="margin-top:20px;text-align:center">
        <button type="button" id="btnConfirmClosePreviewModal" class="btn primary" style="width:100%;padding:10px;font-weight:800;border-radius:8px">Entendido / Fechar</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const close = () => {
    overlay.remove();
    if(options.onClose) options.onClose();
  };
  overlay.querySelector('#btnCloseMatchPreviewModal').onclick = close;
  overlay.querySelector('#btnConfirmClosePreviewModal').onclick = close;
  overlay.onclick = (e) => { if(e.target === overlay) close(); };
};

window.openMatchSummaryModal = function(info) {
  document.getElementById('afmMatchSummaryModal')?.remove();

  const home = info.home;
  const away = info.away;
  const scoreH = info.scoreH;
  const scoreA = info.scoreA;
  const compName = info.compName;
  const dateStr = info.dateStr;
  const roundStr = info.roundStr;

  const myClub = state?.club || '';
  const myClubNorm = (typeof norm === 'function' ? norm(myClub) : String(myClub).toLowerCase().trim());
  const isHome = (typeof norm === 'function' ? norm(home) : String(home).toLowerCase().trim()) === myClubNorm;

  const userGoals = isHome ? scoreH : scoreA;
  const oppGoals = isHome ? scoreA : scoreH;
  let outcomeText = '🟡 EMPATE';
  let outcomeColor = '#eab308';
  if(userGoals > oppGoals) { outcomeText = '🟢 VITÓRIA'; outcomeColor = '#22c55e'; }
  else if(userGoals < oppGoals) { outcomeText = '🔴 DERROTA'; outcomeColor = '#ef4444'; }

  const isPlayer = typeof isPlayerCareerActive === 'function' ? isPlayerCareerActive(state) : false;
  let playerPerf = null;
  if(isPlayer && state.player && Array.isArray(state.player.matchRatingHistory)) {
    playerPerf = state.player.matchRatingHistory.find(m => m.date === dateStr || m.opponent === (isHome ? away : home));
  }

  const overlay = document.createElement('div');
  overlay.id = 'afmMatchSummaryModal';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.85);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;backdrop-filter:blur(6px);animation:fadeIn 0.2s ease;';

  overlay.innerHTML = `
    <div style="background:#0f172a;border:1px solid rgba(255,255,255,0.15);border-radius:14px;max-width:500px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 25px 50px -12px rgba(0,0,0,0.7);padding:22px;position:relative;color:#f8fafc">
      <button type="button" id="btnCloseMatchSummaryModal" style="position:absolute;top:16px;right:16px;background:rgba(255,255,255,0.08);border:none;color:#94a3b8;width:32px;height:32px;border-radius:50%;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center">✕</button>

      <div style="text-align:center;margin-bottom:16px">
        <span class="pill" style="font-size:10px;font-weight:900;background:#1e293b;color:#38bdf8;padding:2px 8px;border-radius:12px">🏆 ${esc(compName || 'Partida Oficial')}</span>
        <div class="small muted" style="margin-top:6px;font-size:11px">${roundStr ? esc(roundStr) + ' • ' : ''}${dateStr ? formatDatePtBr(dateStr) : ''}</div>
        <div style="margin-top:8px;font-size:14px;font-weight:900;color:${outcomeColor}">${outcomeText}</div>
      </div>

      <div style="display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;background:rgba(255,255,255,0.03);padding:20px 12px;border-radius:12px;border:1px solid rgba(255,255,255,0.07)">
        <div style="text-align:center">
          <div style="display:flex;justify-content:center;margin-bottom:8px">${clubBadge(home, 48)}</div>
          <div style="font-weight:900;font-size:14px;color:#fff">${esc(home)}</div>
        </div>
        <div style="text-align:center">
          <div style="font-size:32px;font-weight:900;color:#fff;letter-spacing:4px">${scoreH} x ${scoreA}</div>
          <span class="pill good" style="font-size:10px;margin-top:4px">Encerrado</span>
        </div>
        <div style="text-align:center">
          <div style="display:flex;justify-content:center;margin-bottom:8px">${clubBadge(away, 48)}</div>
          <div style="font-weight:900;font-size:14px;color:#fff">${esc(away)}</div>
        </div>
      </div>

      ${playerPerf ? `
        <div style="margin-top:16px;background:rgba(56,189,248,0.05);border:1px solid rgba(56,189,248,0.2);padding:14px;border-radius:10px">
          <div style="font-size:11px;font-weight:800;color:#38bdf8;margin-bottom:8px">⭐ Sua Atuação Individual (Carreira Jogador)</div>
          <div style="display:grid;grid-template-columns:repeat(4, 1fr);gap:8px;text-align:center">
            <div style="background:rgba(255,255,255,0.03);padding:6px;border-radius:6px">
              <div class="small muted" style="font-size:9px">NOTA</div>
              <div style="font-size:14px;font-weight:900;color:#facc15">${playerPerf.rating || playerPerf.note || '—'}</div>
            </div>
            <div style="background:rgba(255,255,255,0.03);padding:6px;border-radius:6px">
              <div class="small muted" style="font-size:9px">MINUTOS</div>
              <div style="font-size:14px;font-weight:900;color:#fff">${playerPerf.minutes || 90}'</div>
            </div>
            <div style="background:rgba(255,255,255,0.03);padding:6px;border-radius:6px">
              <div class="small muted" style="font-size:9px">GOLS</div>
              <div style="font-size:14px;font-weight:900;color:#4ade80">${playerPerf.goals || 0}</div>
            </div>
            <div style="background:rgba(255,255,255,0.03);padding:6px;border-radius:6px">
              <div class="small muted" style="font-size:9px">ASSIST.</div>
              <div style="font-size:14px;font-weight:900;color:#38bdf8">${playerPerf.assists || 0}</div>
            </div>
          </div>
        </div>
      ` : ''}

      <div style="margin-top:20px;text-align:center">
        <button type="button" id="btnConfirmCloseSummaryModal" class="btn primary" style="width:100%;padding:10px;font-weight:800;border-radius:8px">Fechar Súmula</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const close = () => overlay.remove();
  overlay.querySelector('#btnCloseMatchSummaryModal').onclick = close;
  overlay.querySelector('#btnConfirmCloseSummaryModal').onclick = close;
  overlay.onclick = (e) => { if(e.target === overlay) close(); };
};

// -------------------------------------------------------------
// RESOLUÇÃO DE CONFLITOS DE JOGOS NO MESMO DIA & FILTROS UNIFICADOS
// -------------------------------------------------------------
function resolveSameDayFixtureConflicts(fixtures, userClubName) {
  if (!Array.isArray(fixtures) || !userClubName) return fixtures || [];
  const normFn = (typeof norm === 'function') ? norm : (str => String(str || '').trim().toLowerCase());
  const target = normFn(userClubName);
  const usedDates = new Set();

  // Ordena cronologicamente antes de validar datas
  fixtures.sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')));

  for (const fx of fixtures) {
    const isUserMatch = normFn(fx.home) === target || normFn(fx.away) === target;
    if (!isUserMatch || !fx.date) continue;

    let curDateStr = String(fx.date).slice(0, 10);
    let guard = 0;
    while (usedDates.has(curDateStr) && guard < 14) {
      const [y, m, d] = curDateStr.split('-').map(Number);
      const dt = new Date(y, m - 1, d + 1, 12, 0, 0);
      const ny = dt.getFullYear();
      const nm = String(dt.getMonth() + 1).padStart(2, '0');
      const nd = String(dt.getDate()).padStart(2, '0');
      curDateStr = `${ny}-${nm}-${nd}`;
      guard++;
    }
    fx.date = curDateStr;
    usedDates.add(curDateStr);
  }
  return fixtures;
}

function applyCalendarFiltersAndSearch() {
  const filter = window.activeCalFilter || window.calendarFilter || 'ALL';
  const query = String(window.activeCalSearch || window.__calSearchQuery || '').trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  if (typeof document === 'undefined') return;
  document.querySelectorAll('.calendar-view .calendar-card').forEach((card) => {
    const opp = String(card.getAttribute('data-opponent') || '').toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const cardText = String(card.textContent || '').toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

    const isDerby = Boolean(card.querySelector('.calendar-derby-badge') || cardText.includes('clássico') || cardText.includes('classico'));
    const isHome = cardText.includes('em casa');
    const isAway = cardText.includes('fora');
    const isPlayed = card.classList.contains('played') || card.getAttribute('data-played') === '1';

    let matchFilter = true;
    if (filter === 'UPCOMING') matchFilter = !isPlayed;
    else if (filter === 'PLAYED') matchFilter = isPlayed;
    else if (filter === 'DERBY') matchFilter = isDerby;
    else if (filter === 'HOME') matchFilter = isHome;
    else if (filter === 'AWAY') matchFilter = isAway;
    else if (filter === 'MYCLUB' || filter === 'ALL') matchFilter = true;
    else {
      const compAttr = String(card.getAttribute('data-comp-id') || cardText).toLowerCase();
      matchFilter = compAttr.includes(filter.toLowerCase());
    }

    const matchSearch = !query || opp.includes(query) || cardText.includes(query);
    card.style.display = (matchFilter && matchSearch) ? '' : 'none';
  });
}

if(typeof window !== 'undefined'){
  window.resolveSameDayFixtureConflicts = resolveSameDayFixtureConflicts;
  window.applyCalendarFiltersAndSearch = applyCalendarFiltersAndSearch;
}

// -------------------------------------------------------------
// ABA CALENDÁRIO COM DATAS OFICIAIS E JANELAS DE TRANSFERÊNCIA
// -------------------------------------------------------------
function calendarPage(){
  if (state && state.gameMode !== 'player') {
    if (typeof ensureManagerCalendarHydrated === 'function') ensureManagerCalendarHydrated(state);
  }
  const ctx = (typeof resolveModeContext === 'function') ? resolveModeContext(state) : { isManager: true, isPlayer: false, clubName: state?.club || '' };
  const comp = curComp(), schedule = state.schedule || [], myClub = ctx.clubName || state.club;
  const calendarClubKey = name => ({'red bull bragantino':'bragantino'}[norm(name)] || norm(name));
  const winInfo = (window.AFM_CALENDAR_HUB && typeof window.AFM_CALENDAR_HUB.getTransferWindowStatus === 'function')
    ? window.AFM_CALENDAR_HUB.getTransferWindowStatus(state.date)
    : getTransferWindowInfo(state.date);
  const extraMatches = [];
  const copa = getCopaDoBrasilState();
  processCopaDoBrasilCalendar(state.date);
  if(isClubRegisteredInCopaDoBrasil(state, myClub)) Object.entries(copa.phases || {}).forEach(([phaseName,phase])=>(phase.fixtures||[]).forEach((fixture,fixtureIndex)=>{
    if(calendarClubKey(fixture.home)!==calendarClubKey(myClub)&&calendarClubKey(fixture.away)!==calendarClubKey(myClub))return;
    const cDate = ensureMidweekDate(fixture.isoDate || phase.isoDate, state.season);
    const savedCupResult = (state.history || []).find(h => h.competitionId === 'bra-cup' && Number(h.season) === Number(state.season) && ((calendarClubKey(h.h)===calendarClubKey(fixture.home)&&calendarClubKey(h.a)===calendarClubKey(fixture.away))||(calendarClubKey(h.h)===calendarClubKey(fixture.away)&&calendarClubKey(h.a)===calendarClubKey(fixture.home))));
    const result = fixture.score || (savedCupResult ? (calendarClubKey(savedCupResult.h)===calendarClubKey(fixture.home) ? [savedCupResult.hg,savedCupResult.ag] : [savedCupResult.ag,savedCupResult.hg]) : null);
    extraMatches.push({competitionId:'bra-cup',name:'Copa do Brasil',home:fixture.home,away:fixture.away,isHome:calendarClubKey(fixture.home)===calendarClubKey(myClub),round:phaseName,date:cDate,result,current:cDate===state.date,matchIndex:fixtureIndex,phaseName});
  }));
  for(const id of ['lib','sud','ucl','uel','uecl','afc-el','afc2','cwc']){
    const tournament=getContinentalTournament(id);
    if(!tournament||Number(tournament.season)!==Number(state.season))continue;
    const participants=new Set(Object.values(tournament.groups||{}).flat().map(calendarClubKey));
    if(!participants.has(calendarClubKey(myClub)))continue;
    extraMatches.push(...(tournament.matches||[]).filter(f=>participants.has(calendarClubKey(f.home))&&participants.has(calendarClubKey(f.away))&&(calendarClubKey(f.home)===calendarClubKey(myClub)||calendarClubKey(f.away)===calendarClubKey(myClub))).map(f=>{
      const matchDate = ensureMidweekDate(f.date,state.season);
      const historyMatch = (state.history||[]).find(h =>
        h.competitionId === id &&
        Number(h.season) === Number(state.season) &&
        (Number(h.round) === Number(f.round) || h.date === matchDate || h.date === f.date) &&
        ((calendarClubKey(h.h) === calendarClubKey(f.home) && calendarClubKey(h.a) === calendarClubKey(f.away)) ||
         (calendarClubKey(h.h) === calendarClubKey(f.away) && calendarClubKey(h.a) === calendarClubKey(f.home)))
      );
      const result = f.result || (historyMatch ? [Number(historyMatch.hg)||0, Number(historyMatch.ag)||0] : null);
      return {
        ...f,
        competitionId: id,
        round: `Fase de Grupos • Rodada ${f.round}`,
        date: matchDate,
        matchId: f.id,
        result,
        historyMatch,
        isHome: calendarClubKey(f.home)===calendarClubKey(myClub),
        name: ({lib:'Copa Libertadores',sud:'Copa Sul-Americana',ucl:'UEFA Champions League',uel:'UEFA Europa League',uecl:'UEFA Conference League','afc-el':'AFC Champions League Elite',afc2:'AFC Champions League Two',cwc:'Mundial de Clubes FIFA'})[id]||id
      };
    }));
  }
  const cupLabels={'bra-cup':'🏅 Copa do Brasil',lib:'🏆 Libertadores',sud:'🥈 Sul-Americana',ucl:'UEFA Champions League',uel:'UEFA Europa League',uecl:'UEFA Conference League','afc-el':'AFC Champions League Elite',afc2:'AFC Champions League Two',cwc:'Mundial de Clubes FIFA'};
  const cupFilters=Object.keys(cupLabels).filter(id=>extraMatches.some(match=>match.competitionId===id)).map(id=>[id,cupLabels[id]]);

  const memberships=getSavedSeasonMemberships(myClub);
  const stateCompId=memberships.stateId;
  const stateComp=stateCompId?compById(stateCompId):null;
  const stateRoster=stateCompId?(state.competitionTeams?.[stateCompId]||window.COMPETITION_TEAMS?.[stateCompId]||[]):[];
  const hasStateMembership=Boolean(stateCompId&&stateComp&&stateCompId.startsWith('bra-est-')&&(memberships.stateId===stateCompId||stateRoster.some(name=>calendarClubKey(typeof name==='string'?name:name?.name)===calendarClubKey(myClub))||norm(myClub)==='brasilia'));
  const leagueTab={id:'COMP',name:comp.name,label:`🏆 ${comp.name}`,matches:schedule.flatMap((games,rIndex)=>{
    const fixture=games.find(game=>Array.isArray(game)&&game.some(name=>calendarClubKey(name)===calendarClubKey(myClub)));
    if(!fixture)return [];
    const [home,away]=fixture,isHome=calendarClubKey(home)===calendarClubKey(myClub),date=getDateForRound(rIndex,state.season),opponentKey=calendarClubKey(isHome?away:home);
    const historyMatch=(state.history||[]).find(h=>Number(h.round)===rIndex+1&&(!h.competitionId||h.competitionId===comp.id||h.competitionId==='COMP')&&(!h.season||Number(h.season)===Number(state.season))&&((calendarClubKey(h.h)===calendarClubKey(myClub)&&calendarClubKey(h.a)===opponentKey)||(calendarClubKey(h.a)===calendarClubKey(myClub)&&calendarClubKey(h.h)===opponentKey)));
    const dRoster = (state.compId === 'bra-d' && Array.isArray(state.teams) && state.teams.length >= 96)
      ? state.teams.map(t => t.name)
      : (state.competitionTeams?.['bra-d'] || window.COMPETITION_TEAMS?.['bra-d'] || []);
    let groupIndex = comp.id === 'bra-d' ? Math.floor(dRoster.findIndex(name => norm(name) === norm(myClub)) / 24) : -1;
    if(comp.id === 'bra-d' && groupIndex < 0) groupIndex = 0;
    const groupName = groupIndex >= 0 ? String.fromCharCode(65 + groupIndex) : '';
    const result = historyMatch ? (calendarClubKey(historyMatch.h) === calendarClubKey(home) ? [Number(historyMatch.hg)||0, Number(historyMatch.ag)||0] : [Number(historyMatch.ag)||0, Number(historyMatch.hg)||0]) : null;
    return [{competitionId:'COMP',name:comp.name,home,away,isHome,date,round:comp.id==='bra-d'?`Grupo ${groupName} - Rodada ${rIndex+1}`:`Rodada ${rIndex+1}`,current:rIndex===state.round,past:date<state.date,historyMatch,result,matchIndex:rIndex}];
  })};
  const competitionTabs=[leagueTab];
  if(hasStateMembership && stateCompId !== comp.id){
    const data=getStateCompData(stateCompId), played=(state.history||[]).filter(h=>h.competitionId===stateCompId&&Number(h.season)===Number(state.season)), stateMatches=[];
    (data.fixtures||[]).forEach((row,fixtureIndex)=>{
      if(calendarClubKey(row.home)!==calendarClubKey(myClub)&&calendarClubKey(row.away)!==calendarClubKey(myClub))return;
      const {home,away}=row,roundIndex=Number(row.roundIndex)||0,isHome=calendarClubKey(home)===calendarClubKey(myClub);
      const saved=played.find(h=>Number(h.round)===roundIndex+1&&((calendarClubKey(h.h)===calendarClubKey(home)&&calendarClubKey(h.a)===calendarClubKey(away))||(calendarClubKey(h.h)===calendarClubKey(away)&&calendarClubKey(h.a)===calendarClubKey(home))));
      const date=row?.isoDate||getDateForRound(roundIndex,state.season);
      const historyMatch=saved?{...saved,hg:calendarClubKey(saved.h)===calendarClubKey(home)?saved.hg:saved.ag,ag:calendarClubKey(saved.h)===calendarClubKey(home)?saved.ag:saved.hg}:(row.result?{hg:row.result[0],ag:row.result[1]}:null);
      const result = (Array.isArray(row.result) && row.result.length >= 2) ? [Number(row.result[0])||0, Number(row.result[1])||0] : (historyMatch ? [Number(historyMatch.hg)||0, Number(historyMatch.ag)||0] : null);
      stateMatches.push({competitionId:stateCompId,name:stateComp.name,home,away,isHome,date,round:`Rodada ${roundIndex+1}`,current:date===state.date,past:row.played===true||Boolean(row.result)||Boolean(saved),historyMatch,result,stateFixture:row,matchIndex:roundIndex,fixtureIndex});
    });
    competitionTabs.push({id:stateCompId,name:stateComp.name,label:`🏟️ ${stateComp.name}`,matches:stateMatches});
  }
  for(const [id,label] of cupFilters){const matches=extraMatches.filter(m=>m.competitionId===id);if(matches.length)competitionTabs.push({id,name:matches[0].name,label,matches});}

  const allMatches = competitionTabs.flatMap(tab=>tab.matches);
  if (typeof window.resolveSameDayFixtureConflicts === 'function') {
    window.resolveSameDayFixtureConflicts(allMatches, myClub);
  }

  // Ordem cronológica oficial da temporada para determinar estritamente a próxima partida jogável
  const chronologicalMatches = allMatches.slice().sort((a,b)=>a.date.localeCompare(b.date)||(a.competitionId==='COMP'?-1:1));
  const nextUnplayedMatch = chronologicalMatches.find(m => {
    const res = resolveCalendarMatchResult(m, state);
    return !(Array.isArray(res) && res.length >= 2);
  });

  const summary = (window.AFM_CALENDAR_HUB && typeof window.AFM_CALENDAR_HUB.computeSeasonSummary === 'function')
    ? window.AFM_CALENDAR_HUB.computeSeasonSummary(allMatches, myClub, state)
    : { played: 0, total: allMatches.length, wins: 0, draws: 0, losses: 0, points: 0, winRate: 0, streakText: '—', streakSub: 'Aguardando início', derbiesTotal: 0, derbiesPlayed: 0, derbiesRecord: '—' };

  const upcomingCount = allMatches.filter(m => { const r = resolveCalendarMatchResult(m, state); return !(Array.isArray(r) && r.length >= 2); }).length;
  const playedCount = allMatches.length - upcomingCount;
  const derbyCount = allMatches.filter(m => window.AFM_CALENDAR_HUB && window.AFM_CALENDAR_HUB.isDerbyMatch(m.home, m.away)).length;
  const myClubMatches = allMatches.filter(m => (typeof norm === 'function' && (norm(m.home) === norm(myClub) || norm(m.away) === norm(myClub))));

  const activeCalendarFilter = competitionTabs.some(tab=>tab.id===calendarFilter) || ['ALL','UPCOMING','PLAYED','DERBY','HOME','AWAY','MYCLUB'].includes(calendarFilter) ? calendarFilter : 'ALL';

  const calendarMatches = allMatches.filter(match => {
    const res = resolveCalendarMatchResult(match, state);
    const isDone = Array.isArray(res) && res.length >= 2;
    if(activeCalendarFilter === 'ALL') return true;
    if(activeCalendarFilter === 'MYCLUB') return (typeof norm === 'function' && (norm(match.home) === norm(myClub) || norm(match.away) === norm(myClub)));
    if(activeCalendarFilter === 'UPCOMING') return !isDone;
    if(activeCalendarFilter === 'PLAYED') return isDone;
    if(activeCalendarFilter === 'DERBY') return window.AFM_CALENDAR_HUB && window.AFM_CALENDAR_HUB.isDerbyMatch(match.home, match.away);
    if(activeCalendarFilter === 'HOME') return match.isHome;
    if(activeCalendarFilter === 'AWAY') return !match.isHome;
    return match.competitionId === activeCalendarFilter;
  }).sort((a,b)=>a.date.localeCompare(b.date)||(a.competitionId==='COMP'?-1:1));

  return `
    <div class="hero">
      <div>
        <h1>Calendário Oficial de Jogos & Janelas de Transferência</h1>
        <div class="muted">Datas dos confrontos, mandos de campo, torneios da temporada ${state.season} e janelas de contratação</div>
      </div>
      <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">
        <span class="window-badge ${winInfo.open?'window-open':'window-closed'}" title="${esc(winInfo.detail || '')}">${winInfo.open?'🟢':'🔴'} ${esc(winInfo.text)}</span>
        <span class="pill">${esc(comp.name)}</span>
      </div>
    </div>

    <!-- CARDS DAS DUAS JANELAS OFICIAIS -->
    <div class="grid g2 afm-calendar-windows" style="margin-top:14px">
      <div class="card afm-window-card" style="border-left:4px solid var(--neon)">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <h3 style="margin:0">☀️ Janela de Verão (Início de Ano)</h3>
          <span class="pill ${isTransferWindowOpen(state.season+'-02-01')?'good':''}">01/Jan a 31/Mar</span>
        </div>
        <p class="small muted afm-window-desc" style="margin:6px 0 0 0">Período oficial de montagem do elenco (90 dias). Permite contratações definitivas, empréstimos e vendas.</p>
      </div>
      <div class="card afm-window-card" style="border-left:4px solid var(--cyan)">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <h3 style="margin:0">❄️ Janela de Inverno (Meio de Ano)</h3>
          <span class="pill ${isTransferWindowOpen(state.season+'-08-01')?'good':''}">10/Jul a 02/Set</span>
        </div>
        <p class="small muted afm-window-desc" style="margin:6px 0 0 0">Período de reforços e ajustes do elenco (55 dias) para o segundo semestre e retas finais dos campeonatos.</p>
      </div>
    </div>

    <!-- PAINEL SUPERIOR DE ESTATÍSTICAS DA TEMPORADA -->
    <div class="card" style="margin-top:14px;padding:12px 16px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:10px;display:grid;grid-template-columns:repeat(auto-fit, minmax(130px, 1fr));gap:12px;align-items:center">
      <div>
        <div class="small muted" style="font-size:10px;text-transform:uppercase;letter-spacing:0.5px">Jogos Disputados</div>
        <div style="font-size:18px;font-weight:900;color:#fff">${summary.played} / ${summary.total}</div>
        <div class="small muted" style="font-size:10px">${summary.wins}V · ${summary.draws}E · ${summary.losses}D</div>
      </div>
      <div>
        <div class="small muted" style="font-size:10px;text-transform:uppercase;letter-spacing:0.5px">Aproveitamento</div>
        <div style="font-size:18px;font-weight:900;color:${summary.winRate >= 50 ? '#4ade80' : summary.winRate >= 35 ? '#facc15' : '#f87171'}">${summary.winRate}%</div>
        <div class="small muted" style="font-size:10px">${summary.points} pts somados</div>
      </div>
      <div>
        <div class="small muted" style="font-size:10px;text-transform:uppercase;letter-spacing:0.5px">Sequência Atual</div>
        <div style="font-size:16px;font-weight:900;color:#38bdf8">${summary.streakText}</div>
        <div class="small muted" style="font-size:10px">${summary.streakSub}</div>
      </div>
      <div>
        <div class="small muted" style="font-size:10px;text-transform:uppercase;letter-spacing:0.5px">Clássicos na Temporada</div>
        <div style="font-size:16px;font-weight:900;color:#f97316">🔥 ${summary.derbiesPlayed} / ${summary.derbiesTotal}</div>
        <div class="small muted" style="font-size:10px">${summary.derbiesRecord}</div>
      </div>
    </div>

    <!-- BARRA DE FILTROS & BUSCA DE ADVERSÁRIO -->
    <div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;flex-wrap:wrap;gap:10px">
      <div class="filters" style="margin-top:0">
        <button type="button" class="btn ${activeCalendarFilter==='ALL'?'primary':''}" data-cal-filter="ALL">📅 Todos (${allMatches.length})</button>
        <button type="button" class="btn ${activeCalendarFilter==='MYCLUB'?'primary':''}" data-cal-filter="MYCLUB">⭐ Apenas Meu Clube (${myClubMatches.length})</button>
        <button type="button" class="btn ${activeCalendarFilter==='UPCOMING'?'primary':''}" data-cal-filter="UPCOMING">⏳ Próximos (${upcomingCount})</button>
        <button type="button" class="btn ${activeCalendarFilter==='PLAYED'?'primary':''}" data-cal-filter="PLAYED">✅ Disputados (${playedCount})</button>
        ${derbyCount > 0 ? `<button type="button" class="btn ${activeCalendarFilter==='DERBY'?'primary':''}" data-cal-filter="DERBY">🔥 Clássicos (${derbyCount})</button>` : ''}
        ${competitionTabs.map(tab=>`<button type="button" class="btn ${activeCalendarFilter===tab.id?'primary':''}" data-cal-filter="${tab.id}">${tab.label}</button>`).join('')}
        <button type="button" class="btn ${activeCalendarFilter==='HOME'?'primary':''}" data-cal-filter="HOME">🏠 Em Casa</button>
        <button type="button" class="btn ${activeCalendarFilter==='AWAY'?'primary':''}" data-cal-filter="AWAY">✈️ Fora</button>
      </div>
      <div>
        <input type="text" id="calSearchOpponentInput" placeholder="🔍 Filtrar adversário..." value="${esc(window.activeCalSearch || window.__calSearchQuery || '')}" class="input" style="max-width:220px;padding:5px 10px;font-size:11px;border-radius:6px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.15);color:#fff">
      </div>
    </div>

    <!-- LISTA DE PARTIDAS DO CALENDÁRIO COM BLOQUEIO CRONOLÓGICO -->
    <div class="calendar-view" style="margin-top:10px">
      ${calendarMatches.map((match, matchIdx) => {
        const opponent = match.isHome ? match.away : match.home;
        const date = new Date(`${match.date}T12:00:00`);
        const dayNames = ['DOM','SEG','TER','QUA','QUI','SEX','SÁB'];
        const dayBadge = dayNames[date.getDay()] || 'JOGO';
        const isMidweek = date.getDay() === 3;
        const dateFormatted = date.toLocaleDateString('pt-BR', {day:'2-digit', month:'long'});

        const resScore = resolveCalendarMatchResult(match, state);
        const isCompleted = Array.isArray(resScore) && resScore.length >= 2;
        const isDerby = window.AFM_CALENDAR_HUB && window.AFM_CALENDAR_HUB.isDerbyMatch(match.home, match.away);

        // Bloqueio rigoroso: Apenas a primeira partida não-jogada do calendário é jogável agora
        const isNextPlayable = Boolean(nextUnplayedMatch && (
          match === nextUnplayedMatch ||
          (match.competitionId === nextUnplayedMatch.competitionId && match.date === nextUnplayedMatch.date && match.matchIndex === nextUnplayedMatch.matchIndex)
        ));

        const previewBtn = `<button type="button" class="btn btnCalPreviewNow" data-home="${esc(match.home)}" data-away="${esc(match.away)}" data-comp="${esc(match.name)}" data-date="${esc(match.date)}" style="padding:4px 8px;font-size:11px;font-weight:800;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.15);border-radius:6px;cursor:pointer" title="Ver Prévia & Histórico do Adversário">📋 Prévia</button>`;

        let status = '';
        if(isCompleted){
          const myClubKey = calendarClubKey(myClub);
          const isHomeClub = calendarClubKey(match.home) === myClubKey;
          const userGoals = isHomeClub ? resScore[0] : resScore[1];
          const oppGoals = isHomeClub ? resScore[1] : resScore[0];
          let resBadge = '<span class="pill" style="font-size:10px;font-weight:900;background:#475569;color:#cbd5e1;padding:1px 5px">E</span>';
          if(userGoals > oppGoals) resBadge = '<span class="pill" style="font-size:10px;font-weight:900;background:#15803d;color:#fff;padding:1px 5px">V</span>';
          else if(userGoals < oppGoals) resBadge = '<span class="pill" style="font-size:10px;font-weight:900;background:#b91c1c;color:#fff;padding:1px 5px">D</span>';

          const summaryBtn = `<button type="button" class="btn btnCalSummaryNow" data-home="${esc(match.home)}" data-away="${esc(match.away)}" data-score-h="${resScore[0]}" data-score-a="${resScore[1]}" data-comp="${esc(match.name)}" data-date="${esc(match.date)}" data-round="${esc(match.round||'')}" style="padding:4px 8px;font-size:11px;font-weight:800;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.18);border-radius:6px;cursor:pointer" title="Ver Súmula Oficial">📊 Súmula</button>`;

          status = `<div style="display:flex;align-items:center;gap:6px;justify-content:flex-end">
            ${resBadge}
            <span class="pill good" style="font-size:11px;font-weight:900">${resScore[0]} x ${resScore[1]}</span>
            ${summaryBtn}
            ${previewBtn}
          </div>`;
        } else if(isNextPlayable){
          // Partida ativa para disputar agora
          let playButtons = '';
          if(match.competitionId==='COMP'){
            playButtons = `<button type="button" class="btn primary btnCalPlayNow" data-round="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 9px;font-size:11px;font-weight:900;background:linear-gradient(135deg,#7c3aed,#9333ea);border:none;border-radius:6px;cursor:pointer">▶ Jogar</button><button type="button" class="btn btnCalSimNow" data-round="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 8px;font-size:11px;font-weight:800;background:#1e1b4b;border:1px solid #6366f1;color:#a5b4fc;border-radius:6px;cursor:pointer">⚡ Simular</button>`;
          } else if(match.competitionId.startsWith('bra-est-')){
            playButtons = `<button type="button" class="btn primary btnCalStatePlay" data-state-comp="${match.competitionId}" data-round="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 9px;font-size:11px;font-weight:900;background:linear-gradient(135deg,#7c3aed,#9333ea);border:none;border-radius:6px;cursor:pointer">▶ Jogar</button><button type="button" class="btn btnCalStateSim" data-state-comp="${match.competitionId}" data-round="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 8px;font-size:11px;font-weight:800;background:#1e1b4b;border:1px solid #6366f1;color:#a5b4fc;border-radius:6px;cursor:pointer">⚡ Simular</button>`;
          } else if(match.competitionId==='bra-cup'){
            playButtons = `<button type="button" class="btn primary btnCalCopaPlay" data-phase="${esc(match.phaseName)}" data-index="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 9px;font-size:11px;font-weight:900;background:linear-gradient(135deg,#7c3aed,#9333ea);border:none;border-radius:6px;cursor:pointer">▶ Jogar</button><button type="button" class="btn btnCalCopaSim" data-phase="${esc(match.phaseName)}" data-index="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 8px;font-size:11px;font-weight:800;background:#1e1b4b;border:1px solid #6366f1;color:#a5b4fc;border-radius:6px;cursor:pointer">⚡ Simular</button>`;
          } else if(match.matchId){
            playButtons = `<button type="button" class="btn primary btnCalTournamentPlay" data-tournament="${esc(match.competitionId)}" data-match="${esc(match.matchId)}" data-date="${esc(match.date)}" style="padding:4px 9px;font-size:11px;font-weight:900;background:linear-gradient(135deg,#7c3aed,#9333ea);border:none;border-radius:6px;cursor:pointer">▶ Jogar</button><button type="button" class="btn btnCalTournamentSim" data-tournament="${esc(match.competitionId)}" data-match="${esc(match.matchId)}" data-date="${esc(match.date)}" style="padding:4px 8px;font-size:11px;font-weight:800;background:#1e1b4b;border:1px solid #6366f1;color:#a5b4fc;border-radius:6px;cursor:pointer">⚡ Simular</button>`;
          } else {
            playButtons = `<button type="button" class="btn primary btnCalPlayNow" data-round="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 9px;font-size:11px;font-weight:900;background:linear-gradient(135deg,#7c3aed,#9333ea);border:none;border-radius:6px;cursor:pointer">▶ Jogar</button><button type="button" class="btn btnCalSimNow" data-round="${match.matchIndex}" data-date="${esc(match.date)}" style="padding:4px 8px;font-size:11px;font-weight:800;background:#1e1b4b;border:1px solid #6366f1;color:#a5b4fc;border-radius:6px;cursor:pointer">⚡ Simular</button>`;
          }
          status = `<div style="display:flex;align-items:center;gap:5px;justify-content:flex-end">${playButtons}${previewBtn}</div>`;
        } else {
          // Partida futura: bloqueada contra saltos arbitrários
          status = `<div style="display:flex;align-items:center;gap:6px;justify-content:flex-end">
            <span class="pill" style="font-size:10px;font-weight:700;background:rgba(255,255,255,0.05);color:#94a3b8;border:1px dashed rgba(255,255,255,0.15)">🔒 Aguardando Rodada</span>
            ${previewBtn}
          </div>`;
        }

        // Divisores de marcos da temporada (Janela FIFA ou Playoffs)
        let milestoneDivider = '';
        if(matchIdx > 0){
          const prevMatch = calendarMatches[matchIdx - 1];
          const prevMonth = parseInt(String(prevMatch.date).split('-')[1], 10);
          const curMonth = parseInt(String(match.date).split('-')[1], 10);
          if(curMonth !== prevMonth && [3, 6, 9, 10, 11].includes(curMonth)){
            milestoneDivider = `<div class="calendar-milestone-divider" style="margin:8px 0;padding:6px 12px;background:linear-gradient(90deg,rgba(59,130,246,0.15),transparent);border-left:3px solid #3b82f6;border-radius:6px;font-size:11px;font-weight:700;color:#93c5fd;display:flex;align-items:center;gap:8px"><span>✈️ JANELA FIFA / CONVOCAÇÃO DA SELEÇÃO</span><span class="small muted" style="font-weight:normal">Pausa para amistosos e eliminatórias</span></div>`;
          }
        }

        const cardClass = `calendar-card ${isNextPlayable ? 'current' : ''} ${isCompleted ? 'played' : ''}`;
        const cardBorder = isDerby ? 'border-left: 4px solid #ef4444 !important;' : (isNextPlayable ? 'border-left: 4px solid var(--neon) !important;' : '');

        return `
          ${milestoneDivider}
          <div class="${cardClass}" data-opponent="${esc(opponent)}" data-comp-id="${esc(match.competitionId)}" data-played="${isCompleted ? '1' : '0'}" style="${cardBorder}">
            <div>
              <div style="display:flex;align-items:center;gap:6px;white-space:nowrap">
                <span class="pill" style="font-size:9px;font-weight:900;padding:1px 5px;background:${isMidweek?'rgba(56,189,248,0.25);color:#38bdf8':'rgba(34,197,94,0.25);color:#4ade80'}">${dayBadge}</span>
                <b>${dateFormatted}</b>
              </div>
              <div class="small muted" style="margin-top:3px">${esc(match.round||'')}</div>
            </div>
            <div>
              <span class="pill" style="font-size:11px">${match.isHome?'🏠 EM CASA':'✈️ FORA'}</span>
            </div>
            <div style="display:flex;align-items:center;gap:12px;min-width:0">
              ${clubBadge(opponent,32)}
              <div style="min-width:0">
                <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                  <b>vs ${esc(opponent)}</b>${isDerby ? `<span class="calendar-derby-badge">🔥 CLÁSSICO (+50% XP)</span>` : ''}
                </div>
                <div class="small muted" style="margin-top:2px">
                  Força estimada ${teamStrengthByName(opponent)}${isDerby ? ' · <span style="color:#f87171;font-weight:700">Rivalidade Regional</span>' : ''}
                </div>
              </div>
            </div>
            <div>
              <span class="pill" style="font-size:11px;background:#1e293b;color:#93c5fd">🏆 ${esc(match.name)}</span>
            </div>
            <div style="text-align:right">
              ${status}
            </div>
          </div>
        `;
      }).join('')}
    </div>
  `;
}
function myTeamPage(){
  if (state?.gameMode !== 'player') {
    if (typeof ensureManagerSquadHydrated === 'function') ensureManagerSquadHydrated(state);
  }
  ensureTacticsState(state);
  // Normalize partially migrated/legacy saves before the tactical renderer touches arrays.
  normalizeSquadState(state);
  state.squad = Array.isArray(state.squad) ? state.squad.filter(Boolean) : [];
  state.lineup = Array.isArray(state.lineup) ? state.lineup : [];
  state.formation = FORMATIONS[state.formation] ? state.formation : '4-3-3';
  state.setPieces = state.setPieces && typeof state.setPieces === 'object' ? state.setPieces : {};
  state.setPieceTakers = state.setPieceTakers && typeof state.setPieceTakers === 'object' ? state.setPieceTakers : {};
  state.captains = Array.isArray(state.captains) ? state.captains : [];
  const curTac = state.tactics;
  const tacMetrics = calculateTacticalMetrics(state.formation, curTac);
  const formMeta = FORMATION_META[state.formation] || FORMATION_META['4-3-3'] || {
    name: state.formation, lines: [1, 4, 3, 3], width: 70, behindBall: 5, aheadBall: 5,
    centralCover: 75, flankCover: 75, pressCapacity: 75, transitionCapacity: 75, vulnerabilities: []
  };
  const slots = formationSlots();
  const sec = lineupSector();
  const bench = state.squad.filter(p => p && !(state.lineup||[]).includes(playerKey(p))).sort((a,b)=>playerOverall(b)-playerOverall(a));

  const startingPlayers = (slots || []).map((slot, idx) => {
    const pk = state.lineup?.[idx];
    return pk ? state.squad.find(q => q && playerKey(q) === pk) || null : null;
  });
  const validStarters = startingPlayers.filter(Boolean);
  const hasEmptySlot = startingPlayers.some(p => !p);
  // Todos os seletores de bolas paradas consomem jogadores reais, nunca slots vazios.
  const setPieceCandidates = (validStarters.length ? validStarters : state.squad).filter(p => p && typeof p === 'object' && (p.name || p.id || p.marketKey));
  const overallTitulares = validStarters.length > 0
    ? Math.round(validStarters.reduce((acc, p) => acc + playerOverall(p), 0) / validStarters.length)
    : 59;

  const top11 = state.squad.filter(Boolean).slice().sort((a,b)=>playerOverall(b)-playerOverall(a)).slice(0, 11);
  const overallBest11 = top11.length > 0
    ? Math.round(top11.reduce((acc, p) => acc + playerOverall(p), 0) / top11.length)
    : 60;

  return `
    <div class="hero">
      <div>
        <h1>Meu time & Tática</h1>
        <div class="muted">Clique no titular e no reserva para substituir (ou vice-versa). A posição ideal acende em <b style="color:var(--neon)">VERDE</b> e adaptações em <b style="color:var(--warn)">AMARELO</b>.</div>
      </div>
    </div>

    <!-- Painel de Bolas Paradas e Capitães (AFM30) -->
    <div class="tactics-setpieces-panel" style="background:#130f26;border:1px solid rgba(139,92,246,0.3);border-radius:12px;padding:10px 16px;margin:8px 0 12px 0;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
      <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap">
        <div>
          <span style="font-size:11px;font-weight:900;color:#facc15">🎯 PÊNALTIS:</span>
          <select id="selPenaltyTaker" class="btn" style="padding:4px 8px;font-size:11px;background:#1e1838;color:#fff;border-radius:6px;border:1px solid rgba(255,255,255,0.15)">
            ${validStarters.map(p=>`<option value="${playerKey(p)}" ${(state.setPieces?.penalty||state.setPieceTakers?.penalties)===playerKey(p)?'selected':''}>${esc(p.name || 'Jogador')} (${p.ovr ?? playerOverall(p)})</option>`).join('')}
          </select>
        </div>
        <div>
          <span style="font-size:11px;font-weight:900;color:#38bdf8">⚡ FALTAS:</span>
          <select id="selFreekickTaker" class="btn" style="padding:4px 8px;font-size:11px;background:#1e1838;color:#fff;border-radius:6px;border:1px solid rgba(255,255,255,0.15)">
            ${validStarters.map(p=>`<option value="${playerKey(p)}" ${(state.setPieces?.freekick||state.setPieceTakers?.freekicks)===playerKey(p)?'selected':''}>${esc(p.name || 'Jogador')} (${p.ovr ?? playerOverall(p)})</option>`).join('')}
          </select>
        </div>
        <div>
          <span style="font-size:11px;font-weight:900;color:#eab308">👑 CAPITÃO:</span>
          <select id="selCaptain" class="btn" style="padding:4px 8px;font-size:11px;background:#1e1838;color:#fff;border-radius:6px;border:1px solid rgba(255,255,255,0.15)">
            ${validStarters.map(p=>`<option value="${esc(p.name || playerKey(p))}" ${state.captains?.[0]===p.name?'selected':''}>${esc(p.name || 'Jogador')} (${p.pos || '-'})</option>`).join('')}
          </select>
        </div>
      </div>
      <div style="font-size:11px;font-weight:900;color:#22c55e;display:flex;align-items:center;gap:6px">
        <span>⚡ Sinergia Tática:</span> <span style="background:rgba(34,197,94,0.15);padding:3px 8px;border-radius:6px;border:1px solid #22c55e">+3 OVR Ativo</span>
      </div>
    </div>

    ${hasEmptySlot ? `
      <!-- Alerta de Escalação Incompleta com Ação Direta -->
      <div id="lineupWarningBanner" style="background:linear-gradient(135deg,rgba(239,68,68,0.18),rgba(153,27,27,0.28));border:1px solid #ef4444;border-radius:10px;padding:10px 16px;margin:8px 0;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
        <div style="display:flex;align-items:center;gap:8px;color:#fca5a5;font-size:12px;font-weight:700">
          <span style="font-size:16px">⚠️</span>
          <span>Atenção: Há posições vagas no time titular! O elenco do clube está disponível.</span>
        </div>
        <button id="btnFixLineupImmediate" class="btn" style="background:#22c55e;color:#000;font-weight:900;padding:6px 14px;border-radius:6px;border:none;font-size:11px;cursor:pointer;box-shadow:0 2px 8px rgba(34,197,94,0.35)">
          ⚡ Auto-Preencher 11 Titulares
        </button>
      </div>
    ` : ''}

    <!-- Barra de Ações e Atalhos Táticos -->
    <div class="tactics-actions-bar" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin:8px 0 10px 0">
      <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">
        <button class="btn btnOpenSquadReportsModal" id="btnOpenSquadReportsMyTeam" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;background:linear-gradient(135deg,#059669,#10b981);color:#fff;border:none;box-shadow:0 2px 8px rgba(16,185,129,0.35);cursor:pointer;display:inline-flex;align-items:center;gap:6px" title="Ver perspetiva geral, lesões, suspensões, moral, contratos e juventude">
          📊 Relatórios do Elenco
        </button>
        <button class="btn btnOpenTrainingModal" id="btnOpenTrainingFromMyTeam" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;background:#18142b;color:#10b981;border:1px solid rgba(16,185,129,0.4);cursor:pointer;display:inline-flex;align-items:center;gap:6px" title="Abrir painel de exercícios e sessão de treinamento">
          🏋️ Treino & CT
        </button>
        <button class="btn btnOpenAccordion" data-target="accordionHierarchy" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;background:#18142b;color:#facc15;border:1px solid rgba(234,179,8,0.3)">
          👔 Mentoria & Vestiário
        </button>
        <button class="btn btnOpenAccordion" data-target="accordionTactics" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;background:#18142b;color:#a78bfa;border:1px solid rgba(139,92,246,0.3)">
          ⚙️ Tática Coletiva (Build-Up)
        </button>
        <button class="btn btnOpenAccordion" data-target="accordionRoles" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;background:#18142b;color:#38bdf8;border:1px solid rgba(56,189,248,0.3)">
          👥 Funções dos 11 (Roles)
        </button>
        <button class="btn btnOpenAccordion" data-target="accordionSetpieces" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;background:#18142b;color:#4ade80;border:1px solid rgba(34,197,94,0.3)">
          🎯 Bolas Paradas
        </button>
      </div>

      <div style="display:flex;gap:8px">
        <button class="btn" id="btnAssistantSuggestedSwaps" style="background:linear-gradient(135deg,#8b5cf6,#6d28d9);color:#fff;font-weight:900;padding:7px 14px;border-radius:8px;border:none;font-size:12px;cursor:pointer" title="O Auxiliar Técnico analisa cansaço, lesões e suspensões para indicar as melhores trocas">
          🤝 TROCAS SUGERIDAS
        </button>
        <button class="btn" id="btnAILineup" style="background:#ffffff;color:#0f172a;font-weight:900;padding:7px 14px;border-radius:8px;border:none;font-size:12px;cursor:pointer">
          ⭐ DEIXAR A IA ESCALAR
        </button>
        <button class="btn" id="btnSaveLineup" style="background:#22c55e;color:#000;font-weight:900;padding:7px 18px;border-radius:8px;border:none;font-size:12px;cursor:pointer;box-shadow:0 3px 10px rgba(34,197,94,0.35)">
          💾 SALVAR ESCALAÇÃO
        </button>
      </div>
    </div>

    <!-- Card de FORÇA Compacto e Moderno (Menor e sem ocupar espaço excessivo) -->
    <div class="card tactics-strength-card" style="background:#ffffff;color:#0f172a;border-radius:12px;padding:8px 18px;box-shadow:0 4px 14px rgba(0,0,0,0.15);margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
      <!-- Lado Esquerdo: FORÇA, Estrelas e Médias -->
      <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
        <div style="display:flex;align-items:center;gap:8px">
          <h2 style="margin:0;font-size:16px;font-weight:900;letter-spacing:0.8px;color:#0f172a;text-transform:uppercase">FORÇA</h2>
          <div style="display:flex;align-items:center;gap:2px;font-size:16px">
            ${renderStarRating(overallTitulares)}
          </div>
        </div>
        <div style="font-size:11px;color:#64748b;background:#f1f5f9;padding:3px 10px;border-radius:6px">
          Média dos titulares: <b style="color:#0f172a">${overallTitulares}</b> · 11 melhores: <b style="color:#0f172a">${overallBest11}</b>
        </div>
      </div>

      <!-- Lado Direito: Formação e Setores ATA, MEI, DEF compactos e alinhados -->
      <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
        <div style="display:flex;align-items:center;gap:6px">
          <span style="font-size:11px;font-weight:900;color:#64748b;letter-spacing:0.5px">FORMAÇÃO:</span>
          <select id="formation" class="btn" style="padding:4px 10px;font-weight:900;font-size:12px;border-radius:8px;background:#0f172a;color:#fff;border:1px solid #334155;cursor:pointer">
            ${Object.keys(FORMATIONS).map(x=>`<option ${state.formation===x?'selected':''}>${x}</option>`).join('')}
          </select>
        </div>
        <div style="width:1px;height:20px;background:#cbd5e1"></div>
        <div style="display:flex;align-items:center;gap:6px">
          <span style="font-size:10px;font-weight:800;color:#64748b;letter-spacing:0.5px">ATA</span>
          <b style="font-size:18px;font-weight:900;color:#0f172a">${sec.atk}</b>
        </div>
        <div style="width:1px;height:18px;background:#e2e8f0"></div>
        <div style="display:flex;align-items:center;gap:6px">
          <span style="font-size:10px;font-weight:800;color:#64748b;letter-spacing:0.5px">MEI</span>
          <b style="font-size:18px;font-weight:900;color:#0f172a">${sec.mid}</b>
        </div>
        <div style="width:1px;height:18px;background:#e2e8f0"></div>
        <div style="display:flex;align-items:center;gap:6px">
          <span style="font-size:10px;font-weight:800;color:#64748b;letter-spacing:0.5px">DEF</span>
          <b style="font-size:18px;font-weight:900;color:#0f172a">${sec.def}</b>
        </div>
      </div>
    </div>

    <!-- ESTRUTURA RÍGIDA DE 2 COLUNAS (.tactics-modal-container) -->
    <div class="tactics-modal-container" id="myTeamTacticsContainer" style="margin-bottom: 18px">
      <!-- COLUNA 1: GRAMADO VERTICAL OFICIAL -->
      <div class="tactics-pitch-wrapper" id="myTeamPitchWrapper">
        ${renderVerticalTacticsPitch(startingPlayers, state.formation || '4-3-3', { isHalftime: false, selectedStarterKey: tacticalSelectedKey })}
      </div>

      <!-- COLUNA 2: BANCO DE RESERVAS LATERAL ORGANIZADO -->
      <div class="tactics-bench-wrapper" id="myTeamBenchWrapper">
        <div style="font-size:12px;font-weight:900;color:#94a3b8;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0">
          <span>BANCO DE RESERVAS</span>
          <span style="color:#22c55e;font-size:11px;font-weight:800">${bench.length} disponíveis</span>
        </div>
        <div style="flex:1;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding-right:2px">
          ${bench.slice(0, 30).map(p => {
            const pOvr = playerOverall(p);
            return `
              <div class="bench-player-row" data-bench-key="${esc(playerKey(p))}" data-player-pos="${esc(p.pos)}" title="Clique para selecionar e trocar">
                ${playerPhoto(p, 36)}
                <div style="flex:1;min-width:0;margin-left:8px">
                  <div style="display:flex;justify-content:space-between;align-items:center;gap:4px">
                    <b style="font-size:12px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(p.name)}</b>
                    ${(typeof renderPendingTransferTag === 'function') ? renderPendingTransferTag(p, true) : ''}
                    <span class="rating-pill ${ratingClass(pOvr)}">${pOvr}</span>
                  </div>
                  <div style="display:flex;justify-content:space-between;align-items:center;margin-top:2px;font-size:10px">
                    <span style="color:#c084fc;font-weight:800">
                      ${esc(p.pos || '-')}
                      ${p.injury ? `<span class="pill bad" style="font-size:8px;padding:0 3px">🚑 ${p.injuryMatches}j</span>` : ''}
                      ${p.suspended > 0 ? `<span class="pill bad" style="font-size:8px;padding:0 3px">🟥 ${p.suspended}j</span>` : ''}
                    </span>
                    <span style="color:#94a3b8">Físico ${Math.round(p.fitness ?? 100)}%</span>
                  </div>
                </div>
              </div>
            `;
          }).join('')}
        </div>
        <div style="margin-top:8px;background:#101726;padding:8px 10px;border-radius:8px;font-size:10px;color:rgba(255,255,255,0.7);flex-shrink:0;line-height:1.3">
          💡 <b>Dica:</b> Clique no titular e no reserva (ou vice-versa) para trocar. Slots indicam 🟢 <b>VERDE (★ IDEAL)</b>, 🟡 <b>AMARELO (ADAPTADA)</b> e 🔴 <b>VERMELHO (INCOMPATÍVEL)</b>!
        </div>
      </div>
    </div>

    <!-- 1. ACORDEÃO: TÁTICA AVANÇADA & ESTILO COLETIVO (FECHADO POR PADRÃO) -->
    <details class="tactical-accordion" id="accordionTactics" ${(state?.tacticsAccordionOpen || tacticalActiveTab === 'open') ? 'open' : ''}>
      <summary>
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-size:16px">⚙️</span>
          <span style="font-size:13px;color:#fff;text-transform:uppercase">Tática Avançada & Estilo Coletivo (Build-Up & Sliders)</span>
          <span class="pill" style="font-size:10px;background:rgba(124,58,237,0.3);color:#38bdf8;border:1px solid #38bdf8">ENGINE FC 27</span>
        </div>
        <span class="pill" style="font-size:10px;background:rgba(255,255,255,0.08);color:#94a3b8">▶ Clique para Abrir / Fechar</span>
      </summary>
      <div class="tactical-accordion-body">
        <!-- Cabeçalho & Presets A, B, C -->
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:18px">
          <div>
            <div style="font-size:11px;color:rgba(255,255,255,0.5)">
              Formação tática, estilo coletivo e táticas de reserva
            </div>
          </div>
          <!-- Seletor de Táticas de Reserva (A, B, C) -->
          <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">
            <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.4);text-transform:uppercase">TÁTICAS:</span>
            ${['A','B','C'].map(pk => {
              const isAct = curTac.activePreset === pk;
              const pObj = curTac.presets?.[pk] || {};
              const pLabel = pk === 'A' ? '⚡ Tática A (Equilibrada)' : pk === 'B' ? '🛡️ Tática B (Defensiva)' : '⚔️ Tática C (Ofensiva)';
              return `
                <button class="btn btnSelectTacticalPreset ${isAct ? 'primary' : ''}" data-preset-key="${pk}" style="font-size:11px;font-weight:900;padding:6px 12px;border-radius:8px;${isAct ? 'background:linear-gradient(135deg,#7c3aed,#9333ea);color:#fff;box-shadow:0 0 12px rgba(124,58,237,0.5)' : 'background:#18142b;color:rgba(255,255,255,0.7);border:1px solid rgba(255,255,255,0.1)'}">
                  ${pLabel} <span style="font-size:9px;opacity:0.8">(${pObj.formation || '4-2-3-1'})</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>

        <!-- Análise Estrutural da Formação Ativa -->
        <div style="background:#151228;border:1px solid rgba(255,255,255,0.06);border-radius:14px;padding:14px;margin-bottom:18px">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
            <div>
              <b style="color:#fff;font-size:13px">${esc(formMeta.name || state.formation)}</b>
              <div style="font-size:11px;color:rgba(255,255,255,0.5);margin-top:2px">
                Linhas: ${(formMeta.lines||[1,4,3,3]).join('-')} · Atrás da bola: <b>${formMeta.behindBall||6}</b> · À frente: <b>${formMeta.aheadBall||4}</b>
              </div>
            </div>
            <div style="display:flex;gap:14px;align-items:center">
              <div style="text-align:center">
                <div style="font-size:9px;color:rgba(255,255,255,0.5);font-weight:800">COB. CENTRAL</div>
                <div id="tacMetricCentralCover" style="font-size:12px;font-weight:900;color:#a855f7;transition:all 0.2s ease">${tacMetrics.centralCover}%</div>
              </div>
              <div style="text-align:center">
                <div style="font-size:9px;color:rgba(255,255,255,0.5);font-weight:800">COB. LATERAL</div>
                <div id="tacMetricFlankCover" style="font-size:12px;font-weight:900;color:#38bdf8;transition:all 0.2s ease">${tacMetrics.flankCover}%</div>
              </div>
              <div style="text-align:center">
                <div style="font-size:9px;color:rgba(255,255,255,0.5);font-weight:800">PRESSÃO</div>
                <div id="tacMetricPressCapacity" style="font-size:12px;font-weight:900;color:#22c55e;transition:all 0.2s ease">${tacMetrics.pressCapacity}%</div>
              </div>
              <div style="text-align:center">
                <div style="font-size:9px;color:rgba(255,255,255,0.5);font-weight:800">TRANSIÇÃO</div>
                <div id="tacMetricTransitionCapacity" style="font-size:12px;font-weight:900;color:#facc15;transition:all 0.2s ease">${tacMetrics.transitionCapacity}%</div>
              </div>
            </div>
          </div>
          ${formMeta.vulnerabilities && formMeta.vulnerabilities.length > 0 ? `
            <div style="font-size:10px;color:#f87171;margin-top:8px;background:rgba(239,68,68,0.08);padding:6px 10px;border-radius:6px;border:1px solid rgba(239,68,68,0.2)">
              ⚠️ <b>Atenção Estrutural:</b> ${formMeta.vulnerabilities.join(' · ')}
            </div>
          ` : ''}
        </div>

        <!-- Grade de Configurações Táticas Coletivas (Estilos + Sliders) -->
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px">
          <!-- Bloco 1: Estilos Globais -->
          <div style="background:#16122b;border:1px solid rgba(255,255,255,0.06);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:14px">
            <div>
              <label style="font-size:11px;font-weight:900;color:rgba(255,255,255,0.7);display:block;margin-bottom:6px">
                ⚡ CONSTRUÇÃO DE JOGO (BUILD-UP)
              </label>
              <select id="tacBuildUpStyle" class="btn" style="width:100%;background:#1d1838;color:#fff;border:1px solid rgba(255,255,255,0.15);font-size:12px;padding:8px">
                ${[
                  ['Balanced', 'Equilibrada (Construção Mista)'],
                  ['Short Passing', 'Passes Curtos (Retenção & Posse Paciente)'],
                  ['Fast Build-Up', 'Construção Rápida (Aceleração Vertical)'],
                  ['Direct', 'Jogo Direto (Bolas Longas & Ligação Direta)'],
                  ['Possession', 'Posse de Bola (Circulação & Linhas Altas)'],
                  ['Counter Attack', 'Contra-Ataque (Recuperação & Transição Veloz)']
                ].map(([v, l]) => `<option value="${v}" ${curTac.buildUpStyle===v?'selected':''}>${l}</option>`).join('')}
              </select>
            </div>
            <div>
              <label style="font-size:11px;font-weight:900;color:rgba(255,255,255,0.7);display:block;margin-bottom:6px">
                🛡️ POSTURA DEFENSIVA (APPROACH)
              </label>
              <select id="tacDefensiveApproach" class="btn" style="width:100%;background:#1d1838;color:#fff;border:1px solid rgba(255,255,255,0.15);font-size:12px;padding:8px">
                ${[
                  ['Balanced', 'Equilibrada (Linhas Médias)'],
                  ['Low Block', 'Bloco Baixo (Retranca & Espaço Fechado)'],
                  ['Mid Block', 'Bloco Médio (Compactação Central)'],
                  ['High', 'Linha Alta (Pressão Constante no Ataque)'],
                  ['Aggressive', 'Marcação Agressiva (Duelos Físicos & Bote)'],
                  ['Press After Loss', 'Pressão Pós-Perda (Morde Imediatamente)']
                ].map(([v, l]) => `<option value="${v}" ${curTac.defensiveApproach===v?'selected':''}>${l}</option>`).join('')}
              </select>
            </div>
          </div>

          <!-- Bloco 2: Sliders Táticos Numéricos -->
          <div style="background:#16122b;border:1px solid rgba(255,255,255,0.06);border-radius:14px;padding:16px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
            <div>
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.6)">ALTURA DA LINHA</span>
                <b id="tacLineHeightVal" style="font-size:11px;color:#a855f7">${curTac.lineHeight||60}</b>
              </div>
              <input type="range" id="tacLineHeight" min="20" max="95" value="${curTac.lineHeight||60}" style="width:100%;accent-color:#a855f7">
            </div>
            <div>
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.6)">INTENSIDADE PRESSÃO</span>
                <b id="tacPressIntensityVal" style="font-size:11px;color:#ef4444">${curTac.pressIntensity||65}</b>
              </div>
              <input type="range" id="tacPressIntensity" min="20" max="95" value="${curTac.pressIntensity||65}" style="width:100%;accent-color:#ef4444">
            </div>
            <div>
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.6)">LARGURA ATAQUE</span>
                <b id="tacAttackingWidthVal" style="font-size:11px;color:#38bdf8">${curTac.attackingWidth||60}</b>
              </div>
              <input type="range" id="tacAttackingWidth" min="20" max="95" value="${curTac.attackingWidth||60}" style="width:100%;accent-color:#38bdf8">
            </div>
            <div>
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.6)">LARGURA DEFESA</span>
                <b id="tacDefensiveWidthVal" style="font-size:11px;color:#3b82f6">${curTac.defensiveWidth||50}</b>
              </div>
              <input type="range" id="tacDefensiveWidth" min="20" max="95" value="${curTac.defensiveWidth||50}" style="width:100%;accent-color:#3b82f6">
            </div>
            <div>
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.6)">RITMO (TEMPO)</span>
                <b id="tacTempoVal" style="font-size:11px;color:#facc15">${curTac.tempo||55}</b>
              </div>
              <input type="range" id="tacTempo" min="20" max="95" value="${curTac.tempo||55}" style="width:100%;accent-color:#facc15">
            </div>
            <div>
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                <span style="font-size:10px;font-weight:900;color:rgba(255,255,255,0.6)">VERTICALIDADE (PASSES)</span>
                <b id="tacDirectnessVal" style="font-size:11px;color:#22c55e">${curTac.directness||50}</b>
              </div>
              <input type="range" id="tacDirectness" min="20" max="95" value="${curTac.directness||50}" style="width:100%;accent-color:#22c55e">
            </div>
          </div>
        </div>
      </div>
    </details>

    <!-- 2. ACORDEÃO: FUNÇÕES DOS 11 TITULARES (ROLES & FOCUS - FECHADO POR PADRÃO) -->
    <details class="tactical-accordion" id="accordionRoles">
      <summary>
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-size:16px">👥</span>
          <span style="font-size:13px;color:#fff;text-transform:uppercase">Funções dos 11 Titulares (Roles & Focus Individuais)</span>
          <span class="pill" style="font-size:10px;background:rgba(56,189,248,0.2);color:#38bdf8">11 Titulares</span>
        </div>
        <span class="pill" style="font-size:10px;background:rgba(255,255,255,0.08);color:#94a3b8">▶ Clique para Abrir / Fechar</span>
      </summary>
      <div class="tactical-accordion-body">
        <div style="display:flex;flex-direction:column;gap:8px">
          ${slots.map((s, idx) => {
            const p = lineupPlayer(idx);
            const pk = p ? playerKey(p) : `slot_${idx}`;
            const pRoles = TACTICAL_ROLES[s.r] || TACTICAL_ROLES[p?.pos] || TACTICAL_ROLES['CM'] || [];
            const savedRole = curTac.playerRoles?.[pk]?.roleId || curTac.playerRoles?.[p?.name]?.roleId || pRoles[0]?.id;
            const curRoleDef = pRoles.find(r => r.id === savedRole) || pRoles[0] || {};
            const curFocus = curTac.playerRoles?.[pk]?.focus || curRoleDef.focus || 'Balanced';

            // Gerar badges de impacto
            const b = curRoleDef.behavior || {};
            const tagBadges = [];
            if(b.depthRuns > 1.2) tagBadges.push('<span class="pill" style="font-size:9px;background:rgba(239,68,68,0.15);color:#f87171">🏃 Profundidade</span>');
            if(b.buildUpDrop > 1.2) tagBadges.push('<span class="pill" style="font-size:9px;background:rgba(56,189,248,0.15);color:#38bdf8">🔄 Recua p/ Apoio</span>');
            if(b.halfSpaceOcc) tagBadges.push('<span class="pill" style="font-size:9px;background:rgba(168,85,247,0.15);color:#c084fc">⚡ Half-Space</span>');
            if(b.boxPresence > 1.2) tagBadges.push('<span class="pill" style="font-size:9px;background:rgba(245,158,11,0.15);color:#fbbf24">🎯 Infiltração</span>');
            if(b.coverDefense > 1.2) tagBadges.push('<span class="pill" style="font-size:9px;background:rgba(34,197,94,0.15);color:#4ade80">🛡️ Protege Zaga</span>');
            if(b.creativePassing > 1.2) tagBadges.push('<span class="pill" style="font-size:9px;background:rgba(99,102,241,0.15);color:#818cf8">🪄 Criativo</span>');

            return `
              <div style="background:#161226;border:1px solid rgba(255,255,255,0.06);border-radius:12px;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px">

                <!-- Jogador & Posição -->
                <div style="display:flex;align-items:center;gap:12px;min-width:200px">
                  <span class="pill" style="font-size:11px;font-weight:900;background:#241d3d;color:#c084fc;padding:4px 8px;border-radius:6px">
                    ${s.r}
                  </span>
                  <div>
                    <b style="color:#fff;font-size:13px">${p ? esc(p.name) : 'Vazio'}</b>
                    <div style="font-size:10px;color:rgba(255,255,255,0.5)">
                      ${p ? `${p.pos} · OVR ${playerOverall(p)} · Físico ${Math.round(p.fitness??100)}%` : 'Sem atleta'}
                    </div>
                  </div>
                </div>

                <!-- Seletor de Função (Role) -->
                <div style="display:flex;align-items:center;gap:8px">
                  <span style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.5)">FUNÇÃO:</span>
                  <select class="btn selPlayerRole" data-slot-idx="${idx}" data-player-key="${esc(pk)}" style="background:#1d1838;color:#fff;border:1px solid rgba(255,255,255,0.15);font-size:11px;padding:5px 8px;border-radius:6px">
                    ${pRoles.map(r => `<option value="${r.id}" ${r.id===curRoleDef.id?'selected':''}>${r.name}</option>`).join('')}
                  </select>
                </div>

                <!-- Seletor de Foco (Focus) -->
                <div style="display:flex;align-items:center;gap:8px">
                  <span style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.5)">FOCO:</span>
                  <select class="btn selPlayerFocus" data-slot-idx="${idx}" data-player-key="${esc(pk)}" style="background:#1d1838;color:#fff;border:1px solid rgba(255,255,255,0.15);font-size:11px;padding:5px 8px;border-radius:6px">
                    ${['Defend','Balanced','Attack','Build-Up'].map(fc => `<option value="${fc}" ${fc===curFocus?'selected':''}>${fc}</option>`).join('')}
                  </select>
                </div>

                <!-- Badges de Impacto Comportamental -->
                <div style="display:flex;gap:4px;flex-wrap:wrap;min-width:140px;justify-content:flex-end">
                  ${tagBadges.join('') || '<span class="muted" style="font-size:10px">Equilibrado</span>'}
                </div>

              </div>
            `;
          }).join('')}
        </div>
      </div>
    </details>

    <!-- 3. ACORDEÃO: BOLAS PARADAS & POSTURA DEFENSIVA (FECHADO POR PADRÃO) -->
    <details class="tactical-accordion" id="accordionSetpieces">
      <summary>
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-size:16px">🎯</span>
          <span style="font-size:13px;color:#fff;text-transform:uppercase">Bolas Paradas, Marcação & Bloco Defensivo</span>
          <span class="pill" style="font-size:10px;background:rgba(34,197,94,0.2);color:#4ade80">Cobranças & Pressão</span>
        </div>
        <span class="pill" style="font-size:10px;background:rgba(255,255,255,0.08);color:#94a3b8">▶ Clique para Abrir / Fechar</span>
      </summary>
      <div class="tactical-accordion-body">
        <div class="grid g2">
          <!-- Bolas Paradas -->
          <div style="background:#16122b;border:1px solid rgba(255,255,255,0.06);border-radius:14px;padding:16px">
            <h3 style="margin:0 0 12px 0;font-size:14px;font-weight:900;color:#fff;text-transform:uppercase">
              🎯 Cobradores Oficiais
            </h3>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
              <div>
                <label style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.6);margin-bottom:4px;display:block">
                  ©️ Capitão da Equipe
                </label>
                <select id="setPieceCaptain" class="btn" style="width:100%;background:#18142b;color:#fff;border:1px solid rgba(255,255,255,0.12);font-size:11px">
                  ${setPieceCandidates.map(p=>`<option value="${playerKey(p)}" ${(state.setPieces?.captain===playerKey(p))?'selected':''}>${esc(p.name || 'Jogador')} (${p.pos||'-'} · ${playerOverall(p)})</option>`).join('')}
                </select>
              </div>

              <div>
                <label style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.6);margin-bottom:4px;display:block">
                  ⚽ Pênaltis
                </label>
                <select id="setPiecePenalty" class="btn" style="width:100%;background:#18142b;color:#fff;border:1px solid rgba(255,255,255,0.12);font-size:11px">
                  ${setPieceCandidates.map(p=>`<option value="${playerKey(p)}" ${(state.setPieces?.penalty===playerKey(p))?'selected':''}>${esc(p.name || 'Jogador')} (${p.pos||'-'} · ${playerOverall(p)})</option>`).join('')}
                </select>
              </div>

              <div>
                <label style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.6);margin-bottom:4px;display:block">
                  🎯 Faltas Diretas
                </label>
                <select id="setPieceFreekick" class="btn" style="width:100%;background:#18142b;color:#fff;border:1px solid rgba(255,255,255,0.12);font-size:11px">
                  ${setPieceCandidates.map(p=>`<option value="${playerKey(p)}" ${(state.setPieces?.freekick===playerKey(p))?'selected':''}>${esc(p.name || 'Jogador')} (${p.pos||'-'} · ${playerOverall(p)})</option>`).join('')}
                </select>
              </div>

              <div>
                <label style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.6);margin-bottom:4px;display:block">
                  🚩 Escanteios
                </label>
                <select id="setPieceCorner" class="btn" style="width:100%;background:#18142b;color:#fff;border:1px solid rgba(255,255,255,0.12);font-size:11px">
                  ${setPieceCandidates.map(p=>`<option value="${playerKey(p)}" ${(state.setPieces?.corner===playerKey(p))?'selected':''}>${esc(p.name || 'Jogador')} (${p.pos||'-'} · ${playerOverall(p)})</option>`).join('')}
                </select>
              </div>
            </div>
          </div>

          <!-- Marcação & Bloco -->
          <div style="background:#16122b;border:1px solid rgba(255,255,255,0.06);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:12px">
            <div>
              <label style="font-size:10px;font-weight:800;color:#c084fc;margin-bottom:6px;display:block">
                🛡️ Altura do Bloco Defensivo
              </label>
              <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px">
                <button class="btn btn-defensive-block ${state.defensiveBlock==='baixo'?'active':''}" data-block="baixo" style="padding:8px 4px;font-size:11px;font-weight:900;border-radius:8px;${state.defensiveBlock==='baixo'?'background:#2563eb;color:#fff':''}">
                  🚌 Baixo
                </button>
                <button class="btn btn-defensive-block ${(!state.defensiveBlock||state.defensiveBlock==='medio')?'active':''}" data-block="medio" style="padding:8px 4px;font-size:11px;font-weight:900;border-radius:8px;${(!state.defensiveBlock||state.defensiveBlock==='medio')?'background:#7c3aed;color:#fff':''}">
                  ⚖️ Médio
                </button>
                <button class="btn btn-defensive-block ${state.defensiveBlock==='alto'?'active':''}" data-block="alto" style="padding:8px 4px;font-size:11px;font-weight:900;border-radius:8px;${state.defensiveBlock==='alto'?'background:#ea580c;color:#fff':''}">
                  🚀 Alto
                </button>
              </div>
            </div>

            <div>
              <label style="font-size:10px;font-weight:800;color:#ef4444;margin-bottom:6px;display:block">
                ⚔️ Intensidade de Marcação
              </label>
              <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px">
                <button class="btn btn-marking-intensity ${state.markingIntensity==='leve'?'active':''}" data-intensity="leve" style="padding:8px 4px;font-size:11px;font-weight:800;border-radius:8px;${state.markingIntensity==='leve'?'background:#059669;color:#fff':''}">Prudente</button>
                <button class="btn btn-marking-intensity ${(!state.markingIntensity||state.markingIntensity==='equilibrada')?'active':''}" data-intensity="equilibrada" style="padding:8px 4px;font-size:11px;font-weight:800;border-radius:8px;${(!state.markingIntensity||state.markingIntensity==='equilibrada')?'background:#7c3aed;color:#fff':''}">Padrão</button>
                <button class="btn btn-marking-intensity ${state.markingIntensity==='agressiva'?'active':''}" data-intensity="agressiva" style="padding:8px 4px;font-size:11px;font-weight:800;border-radius:8px;${state.markingIntensity==='agressiva'?'background:#dc2626;color:#fff':''}">Agressiva</button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </details>

    <!-- 4. ACORDEÃO: HIERARQUIA DO VESTIÁRIO & MENTORIA (FECHADO POR PADRÃO) -->
    ${(()=>{
      const hier = getSquadHierarchy(state.squad);
      const squad = state.squad || [];
      const activeMentorKey = state.activeMentorship?.mentorKey;
      const activeMenteeKey = state.activeMentorship?.menteeKey;

      // Encontrar melhor professor (veterano 29+ com maior OVR)
      const bestMentorCandidate = squad.filter(p => (p.age||25) >= 29).sort((a,b)=>playerOverall(b)-playerOverall(a))[0] || squad.filter(p => (p.age||25) >= 26).sort((a,b)=>playerOverall(b)-playerOverall(a))[0];
      // Encontrar melhor jovem (sub-22 com maior potencial)
      const bestMenteeCandidate = squad.filter(p => (p.age||25) <= 22).sort((a,b)=>(b.potential||playerOverall(b)+8)-(a.potential||playerOverall(a)+8))[0] || squad.filter(p => (p.age||25) <= 24).sort((a,b)=>(b.potential||playerOverall(b)+8)-(a.potential||playerOverall(a)+8))[0];

      const currentMentor = squad.find(p => playerKey(p) === activeMentorKey) || bestMentorCandidate;
      const currentMentee = squad.find(p => playerKey(p) === activeMenteeKey) || bestMenteeCandidate;

      return `
        <details class="tactical-accordion" id="accordionHierarchy">
          <summary>
            <div style="display:flex;align-items:center;gap:10px">
              <span style="font-size:16px">👔</span>
              <span style="font-size:13px;color:#fff;text-transform:uppercase">Hierarquia do Vestiário & Mentoria de Jovens</span>
              <span class="pill" style="font-size:10px;background:rgba(234,179,8,0.2);color:#facc15">+15% XP de Treino</span>
            </div>
            <span class="pill" style="font-size:10px;background:rgba(255,255,255,0.08);color:#94a3b8">▶ Clique para Abrir / Fechar</span>
          </summary>
          <div class="tactical-accordion-body">

            <!-- DESTAQUE CLARO: O PROFESSOR E O JOVEM APRENDIZ -->
            <div style="background:radial-gradient(circle at 50% 30%, #1e1838, #0f0c1d);border:2px solid #eab308;border-radius:14px;padding:16px;margin-bottom:16px;box-shadow:0 0 20px rgba(234,179,8,0.2)">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px">
                <span style="font-size:11px;font-weight:900;color:#facc15;letter-spacing:1px;text-transform:uppercase">
                  🎓 PROGRAMA DE MENTORIA TÁTICA (VETERANO ➔ JOVEM)
                </span>
                <span class="pill" style="background:rgba(234,179,8,0.25);color:#facc15;font-size:10px;font-weight:900;border:1px solid #eab308">
                  ${state.activeMentorship ? '✨ MENTORIA ATIVA' : '💡 PARCERIA SUGERIDA'}
                </span>
              </div>

              <!-- CARDS LADO A LADO DO PROFESSOR E DO JOVEM -->
              <div style="display:grid;grid-template-columns:1fr auto 1fr;gap:14px;align-items:center">

                <!-- PROFESSOR (MENTOR) -->
                <div style="background:#16122c;border:1px solid rgba(255,255,255,0.1);border-radius:12px;padding:12px;display:flex;align-items:center;gap:12px">
                  ${playerPhoto(currentMentor?.name, 48)}
                  <div style="flex:1;min-width:0">
                    <span class="pill" style="font-size:9px;font-weight:900;background:rgba(56,189,248,0.2);color:#38bdf8;padding:2px 6px">
                      PROFESSOR (MENTOR)
                    </span>
                    <b style="display:block;font-size:14px;color:#fff;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
                      ${esc(currentMentor?.name || 'Veterano')}
                    </b>
                    <div style="font-size:10px;color:#94a3b8">
                      ${currentMentor?.pos || 'CM'} · ${currentMentor?.age || 32} anos · <b style="color:#22c55e">OVR ${playerOverall(currentMentor)}</b>
                    </div>
                  </div>
                </div>

                <!-- CONEXÃO CENTRAL -->
                <div style="text-align:center;padding:0 4px">
                  <div style="font-size:22px;color:#facc15">➔ ⚡ ➔</div>
                  <span style="font-size:9px;font-weight:900;color:#a3e635;text-transform:uppercase;white-space:nowrap">Ensinando</span>
                </div>

                <!-- JOVEM APRENDIZ (PUPILO) -->
                <div style="background:#16122c;border:1px solid rgba(255,255,255,0.1);border-radius:12px;padding:12px;display:flex;align-items:center;gap:12px">
                  ${playerPhoto(currentMentee?.name, 48)}
                  <div style="flex:1;min-width:0">
                    <span class="pill" style="font-size:9px;font-weight:900;background:rgba(168,85,247,0.2);color:#c084fc;padding:2px 6px">
                      JOVEM ALUNO (APRENDIZ)
                    </span>
                    <b style="display:block;font-size:14px;color:#fff;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
                      ${esc(currentMentee?.name || 'Promessa')}
                    </b>
                    <div style="font-size:10px;color:#94a3b8">
                      ${currentMentee?.pos || 'ST'} · ${currentMentee?.age || 19} anos · <b style="color:#a855f7">POT ${currentMentee?.potential || (playerOverall(currentMentee)+8)}</b>
                    </div>
                  </div>
                </div>

              </div>

              <!-- CONTROLES PARA DEFINIR / TROCAR MENTORIA -->
              <div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,0.08);flex-wrap:wrap;gap:8px">
                <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">
                  <div>
                    <label style="font-size:10px;color:rgba(255,255,255,0.6);display:block;margin-bottom:2px">Trocar Professor (29+ anos):</label>
                    <select id="selMentorVeteran" class="btn" style="padding:4px 8px;font-size:11px;background:#18142b;color:#fff;border-radius:6px">
                      ${squad.filter(p => (p.age||25)>=28).map(p => `<option value="${playerKey(p)}" ${(currentMentor && playerKey(currentMentor)===playerKey(p))?'selected':''}>${esc(p.name)} (${p.pos} · ${p.age}a · OVR ${playerOverall(p)})</option>`).join('')}
                    </select>
                  </div>
                  <div>
                    <label style="font-size:10px;color:rgba(255,255,255,0.6);display:block;margin-bottom:2px">Trocar Aluno (Sub-22):</label>
                    <select id="selMenteeYoung" class="btn" style="padding:4px 8px;font-size:11px;background:#18142b;color:#fff;border-radius:6px">
                      ${squad.filter(p => (p.age||25)<=22).map(p => `<option value="${playerKey(p)}" ${(currentMentee && playerKey(currentMentee)===playerKey(p))?'selected':''}>${esc(p.name)} (${p.pos} · ${p.age}a · POT ${p.potential||playerOverall(p)+8})</option>`).join('')}
                    </select>
                  </div>
                </div>

                <button class="btn primary" id="btnAssignMentorship" style="background:#eab308;color:#000;font-weight:900;padding:7px 16px;border-radius:8px;font-size:11px">
                  ✓ Fixar Mentoria
                </button>
              </div>

              ${state.activeMentorship ? `
                <div style="margin-top:10px;font-size:10px;color:#a3e635;background:rgba(163,230,53,0.1);border:1px solid rgba(163,230,53,0.25);padding:6px 10px;border-radius:6px">
                  ✨ <b>Mentoria Ativa:</b> ${esc(state.activeMentorship.mentorName || 'Veterano')} está ensinando ${esc(state.activeMentorship.menteeName || 'Jovem')}. O jovem recebe +15% de desenvolvimento semanal!
                </div>
              ` : ''}
            </div>

            <!-- CHIPS DE CAPITÃO E LÍDERES -->
            <div style="display:grid;grid-template-columns:1fr 2fr;gap:12px">
              <div style="background:#161226;border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px 14px;display:flex;align-items:center;gap:10px">
                <span style="font-size:22px">👑</span>
                <div>
                  <span style="font-size:9px;font-weight:900;color:#fbbf24;text-transform:uppercase">Capitão Principal</span>
                  <b style="display:block;font-size:13px;color:#fff">${esc(hier.captain?.name || 'Não definido')}</b>
                  <div style="font-size:10px;color:#94a3b8">${hier.captain?.pos || ''} · ${hier.captain?.age || 28} anos · OVR ${hier.captain ? playerOverall(hier.captain) : '-'}</div>
                </div>
              </div>

              <div style="background:#161226;border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px 14px">
                <span style="font-size:9px;font-weight:900;color:#38bdf8;text-transform:uppercase;display:block;margin-bottom:4px">
                  🛡️ Líderes Influentes do Elenco
                </span>
                <div style="display:flex;gap:6px;flex-wrap:wrap">
                  ${(hier.leaders || []).map(p => `
                    <span class="pill" style="background:#1f1938;color:#fff;font-size:10px;padding:4px 8px;border-radius:6px;border:1px solid rgba(255,255,255,0.1)">
                      <b>${esc(p.name)}</b> (${p.pos} · ${p.age}a · OVR ${playerOverall(p)})
                    </span>
                  `).join('') || '<span class="muted small">Sem veteranos influentes</span>'}
                </div>
              </div>
            </div>

          </div>
        </details>
      `;
    })()}
  `;
}

// -------------------------------------------------------------
// ELENCO (SEM AS COLUNAS PES E EA FC)
// -------------------------------------------------------------
function squadPage(){
  if (state?.gameMode !== 'player') {
    if (typeof ensureManagerSquadHydrated === 'function') ensureManagerSquadHydrated(state);
  }
  normalizeSquadState(state);
  let ps=state.squad.filter(Boolean).slice();
  if(squadFilter === 'GK') ps = ps.filter(p=>p.pos==='GK');
  else if(squadFilter === 'DEF') ps = ps.filter(p=>['CB','RB','LB'].includes(p.pos));
  else if(squadFilter === 'MID') ps = ps.filter(p=>['DM','CM','AM'].includes(p.pos));
  else if(squadFilter === 'ATK') ps = ps.filter(p=>['RW','LW','ST','CF'].includes(p.pos));
  else if(squadFilter === 'TRANSFER') ps = ps.filter(p=>isPlayerTransferListed(p));
  else if(squadFilter === 'LOAN') ps = ps.filter(p=>isPlayerLoanListed(p));

  // O indicador de jogadores caros representa o elenco inteiro e não deve
  // mudar apenas porque o usuário selecionou um filtro de posição.
  const expensiveList = state.squad.filter(p => p && isExpensiveForTier(p));
  const expensiveCount = expensiveList.length;

  if(squadViewMode === 'salaries'){
    const clubObj = typeof clubByName === 'function' ? clubByName(state.club) : null;
    const snap = getSquadContractsSnapshot(state, clubObj);
    const loanPlayers = snap.players.filter(player => player?.isLoan);
    const loanedOut = Array.isArray(state.loanedOut) ? state.loanedOut : [];
    const totalLoans = loanPlayers.length + loanedOut.length;

    const contractTabs = `
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">
        <button class="btn contract-view-tab" data-tab="squad" style="${salaryViewTab==='squad'?'background:#7c3aed;color:#fff;border:0':''}">💰 Salários do Elenco</button>
        <button class="btn contract-view-tab" data-tab="loans" style="${salaryViewTab==='loans'?'background:#7c3aed;color:#fff;border:0':''}">🤝 Empréstimos (${totalLoans})</button>
      </div>`;

    if(salaryViewTab === 'loans'){
      const nIn = loanPlayers.length;
      const inText = nIn === 0
        ? 'Nenhum jogador emprestado ao seu clube.'
        : nIn === 1
          ? '1 jogador emprestado ao seu clube. Ao vencer o prazo, o atleta retorna automaticamente ao clube de origem.'
          : `${nIn} jogadores emprestados ao seu clube. Ao vencer o prazo, os atletas retornam automaticamente ao clube de origem.`;

      const nOut = loanedOut.length;
      const outText = nOut === 0
        ? 'Nenhum atleta do seu elenco está emprestado a outros clubes no momento.'
        : nOut === 1
          ? '1 atleta do seu elenco está cedido por empréstimo.'
          : `${nOut} atletas do seu elenco estão cedidos por empréstimo a outras equipes.`;

      return `
        <div class="hero">
          <div><h1>Contratos & Salários</h1><div class="muted">Acompanhe os contratos temporários e a data de retorno dos jogadores emprestados</div></div>
          <button class="btn" id="btnToggleSquadView" style="background:#7c3aed;color:#fff;border:none">👥 Visualização de Elenco</button>
        </div>
        ${contractTabs}

        <!-- 1. EMPRÉSTIMOS RECEBIDOS -->
        <div class="card" style="margin-top:14px;padding:24px;background:#120f20;border:1px solid rgba(139,92,246,0.3);border-radius:18px">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px">
            <h2 style="margin:0;font-size:20px;color:#fff;text-transform:uppercase">📥 EMPRÉSTIMOS RECEBIDOS (${nIn})</h2>
          </div>
          <div class="muted" style="margin-bottom:16px">${inText}</div>
          ${loanPlayers.length ? `<div class="tablewrap"><table><thead><tr><th>JOGADOR</th><th>CLUBE DE ORIGEM</th><th>FIM DO EMPRÉSTIMO</th><th>TEMPO RESTANTE</th><th>OPÇÃO DE COMPRA</th><th>AÇÃO</th></tr></thead><tbody>
            ${loanPlayers.map(player => {
              const remainingDays = getLoanRemainingDays(player, state.date);
              const remainingMonths = Math.ceil(remainingDays / 30.4375);
              const optionActive = Number(player.loanBuyOptionPrice) > 0 && (!player.loanBuyOptionEndDate || state.date <= player.loanBuyOptionEndDate);
              return `<tr class="salary-loan-item" data-player-key="${esc(playerKey(player))}">
                <td><b>${esc(player.name)}</b> ${(typeof renderPendingTransferTag === 'function') ? renderPendingTransferTag(player) : ''}<div class="small muted">${esc(player.pos || '-')} · ${playerOverall(player)} OVR</div></td>
                <td>${clubBadge(player.loanFrom, 18)} ${esc(player.loanFrom || 'Clube de origem')}</td>
                <td>${player.loanEndDate ? formatDatePtBr(player.loanEndDate) : 'A definir'}</td>
                <td><b style="color:${remainingDays <= 30 ? '#f59e0b' : '#38bdf8'}">${remainingDays} dias</b><div class="small muted">aprox. ${remainingMonths} mês(es)</div></td>
                <td>${optionActive ? `<b style="color:#22c55e">${fmtMoney(player.loanBuyOptionPrice)}</b><div class="small muted">até ${formatDatePtBr(player.loanBuyOptionEndDate || player.loanEndDate)}</div>` : '<span class="muted">Sem cláusula fixada</span>'}</td>
                <td><button class="btn btnManageSalaryLoan" data-key="${esc(playerKey(player))}" style="padding:6px 10px;font-size:11px">Gerenciar contrato</button></td>
              </tr>`;
            }).join('')}
          </tbody></table></div>` : `<div class="empty" style="padding:24px;text-align:center">${inText}</div>`}
        </div>

        <!-- 2. EMPRÉSTIMOS CONCEDIDOS (CEDIDOS A OUTROS CLUBES) -->
        <div class="card" style="margin-top:16px;padding:24px;background:#120f20;border:1px solid rgba(255,255,255,0.08);border-radius:18px">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px">
            <h2 style="margin:0;font-size:20px;color:#fff;text-transform:uppercase">📤 EMPRÉSTIMOS CONCEDIDOS (${nOut})</h2>
          </div>
          <div class="muted" style="margin-bottom:16px">${outText}</div>
          ${loanedOut.length ? `<div class="tablewrap"><table><thead><tr><th>JOGADOR</th><th>DESTINO</th><th>POS</th><th>NOTA</th><th>SALÁRIO</th><th>AÇÃO</th></tr></thead><tbody>
            ${loanedOut.map((p, idx) => `
              <tr>
                <td><b>${esc(p.name)}</b></td>
                <td><div class="club-cell">${clubBadge(p.loanTo, 18)} ${esc(p.loanTo||'-')}</div></td>
                <td><span class="pill" style="font-size:11px">${esc(p.pos||'-')}</span></td>
                <td><span class="rating-pill ${ratingClass(playerOverall(p))}">${playerOverall(p)}</span></td>
                <td><span style="color:#38bdf8;font-weight:700">${fmtMoney(p.wage || playerSalary(p))}/mês</span></td>
                <td>
                  <button class="btn btnRecallLoanedPlayer" data-idx="${idx}" style="padding:5px 12px;font-size:11px">
                    Requisitar Retorno
                  </button>
                </td>
              </tr>
            `).join('')}
          </tbody></table></div>` : `<div class="empty" style="padding:24px;text-align:center">${outText}</div>`}
        </div>
      `;
    }

    // Sub-aba: Salários do Elenco
    const maxWage = Math.max(1, ...snap.players.map(p => p._monthlyWage), 10000);

    // Filtros rápidos
    let list = [...snap.players];
    const filterBy = window.contractsFilterBy || 'all';
    if(filterBy === 'expensive') list = list.filter(p => p._expensive);
    else if(filterBy === 'expiring') list = list.filter(p => p._expiringSoon);

    // Ordenação segura
    const sortBy = window.contractsSortBy || salarySort || 'salary';
    list.sort((a, b) => {
      if(sortBy === 'overall') return (Number(b.overall || b.ovr || 0) - Number(a.overall || a.ovr || 0));
      if(sortBy === 'contract') return (a._contractYear - b._contractYear) || (b._monthlyWage - a._monthlyWage);
      return b._monthlyWage - a._monthlyWage;
    });

    return `
      <div class="hero">
        <div>
          <h1>Contratos & Salários</h1>
          <div class="muted">Gestão financeira do elenco, tetos salariais e tempo de contrato dos atletas</div>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button class="btn" id="btnToggleSquadView" style="background:#7c3aed;color:#fff;border:none">
            👥 Visualização de Elenco
          </button>
        </div>
      </div>
      ${contractTabs}

      <div class="card" style="margin-top:14px;padding:24px;background:#120f20;border:1px solid rgba(139,92,246,0.3);border-radius:18px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px">
          <div>
            <h2 style="margin:0;font-size:24px;font-weight:900;letter-spacing:0.5px;color:#fff;text-transform:uppercase">SALÁRIOS DO ELENCO</h2>
            <div style="margin-top:6px;font-size:14px;color:rgba(255,255,255,0.7)">
              ${snap.totalCount} jogadores · Limite ${snap.maxSquadLimit} vagas · <span style="color:#fbbf24;font-weight:800">${snap.expensiveCount} caros para o nível</span>
            </div>
          </div>
          <button class="btn" id="btnToggleSquadViewLink" style="background:transparent;border:none;color:#c084fc;font-weight:700;font-size:15px;cursor:pointer;padding:4px 8px">
            Elenco
          </button>
        </div>

        <!-- 4 CARDS DE RESUMO FINANCEIRO COMPACTOS -->
        <div class="grid g4" style="margin-top:16px;gap:10px">
          <div style="background:rgba(255,255,255,0.03);padding:12px 14px;border-radius:12px;border:1px solid rgba(255,255,255,0.06)">
            <div class="small muted" style="font-size:11px">💰 Folha Mensal Total</div>
            <b style="color:#22c55e;font-size:16px;display:block;margin-top:2px">R$ ${snap.totalMonthlyPayroll.toLocaleString('pt-BR')}/mês</b>
            <div class="small muted" style="font-size:10px;margin-top:2px">Salários somados do plantel</div>
          </div>
          <div style="background:rgba(255,255,255,0.03);padding:12px 14px;border-radius:12px;border:1px solid rgba(255,255,255,0.06)">
            <div class="small muted" style="font-size:11px">📅 Projeção Anual (12x)</div>
            <b style="color:#38bdf8;font-size:16px;display:block;margin-top:2px">R$ ${snap.totalAnnualPayroll.toLocaleString('pt-BR')}/ano</b>
            <div class="small muted" style="font-size:10px;margin-top:2px">Custo anual projetado</div>
          </div>
          <div style="background:rgba(255,255,255,0.03);padding:12px 14px;border-radius:12px;border:1px solid rgba(255,255,255,0.06)">
            <div class="small muted" style="font-size:11px">🎯 Teto Salarial do Nível</div>
            <b style="color:#fbbf24;font-size:16px;display:block;margin-top:2px">~R$ ${snap.recommendedTierCap.toLocaleString('pt-BR')}/mês</b>
            <div class="small muted" style="font-size:10px;margin-top:2px">Recomendado p/ divisão</div>
          </div>
          <div style="background:rgba(255,255,255,0.03);padding:12px 14px;border-radius:12px;border:1px solid ${snap.expiringCount > 0 ? 'rgba(239,68,68,0.25)' : 'rgba(255,255,255,0.06)'}">
            <div class="small muted" style="font-size:11px">⏳ Contratos Vencendo</div>
            <b style="color:${snap.expiringCount > 0 ? '#ef4444' : '#4ade80'};font-size:16px;display:block;margin-top:2px">${snap.expiringCount} atleta(s) em ${state.season || 2026}</b>
            <div class="small muted" style="font-size:10px;margin-top:2px">${snap.expiringCount > 0 ? 'Atenção para renovações' : 'Contratos sob controle'}</div>
          </div>
        </div>

        <!-- FILTROS RÁPIDOS E ORDENAÇÃO -->
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-top:18px">
          <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <span style="font-size:12px;color:rgba(255,255,255,0.5)">Filtrar:</span>
            <button class="btn salary-filter-btn ${(window.contractsFilterBy || 'all') === 'all' ? 'active' : ''}" data-filter="all" style="padding:4px 12px;font-size:11px;font-weight:800;border-radius:16px;${(window.contractsFilterBy || 'all') === 'all' ? 'background:#7c3aed;color:#fff;border:none' : 'background:rgba(255,255,255,0.06);color:#ccc;border:1px solid rgba(255,255,255,0.1)'}">Todos (${snap.totalCount})</button>
            <button class="btn salary-filter-btn ${window.contractsFilterBy === 'expensive' ? 'active' : ''}" data-filter="expensive" style="padding:4px 12px;font-size:11px;font-weight:800;border-radius:16px;${window.contractsFilterBy === 'expensive' ? 'background:#f59e0b;color:#000;border:none' : 'background:rgba(255,255,255,0.06);color:#ccc;border:1px solid rgba(255,255,255,0.1)'}">Caros p/ o nível (${snap.expensiveCount})</button>
            <button class="btn salary-filter-btn ${window.contractsFilterBy === 'expiring' ? 'active' : ''}" data-filter="expiring" style="padding:4px 12px;font-size:11px;font-weight:800;border-radius:16px;${window.contractsFilterBy === 'expiring' ? 'background:#ef4444;color:#fff;border:none' : 'background:rgba(255,255,255,0.06);color:#ccc;border:1px solid rgba(255,255,255,0.1)'}">Vencendo em ${state.season || 2026} (${snap.expiringCount})</button>
          </div>

          <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:12px;color:rgba(255,255,255,0.5)">Ordem:</span>
            <button class="btn salary-sort-btn ${sortBy === 'salary' ? 'active' : ''}" data-sort="salary" style="padding:4px 12px;font-size:11px;font-weight:800;border-radius:16px;${sortBy === 'salary' ? 'background:#fff;color:#000;border:none' : ''}">SALÁRIO</button>
            <button class="btn salary-sort-btn ${sortBy === 'overall' ? 'active' : ''}" data-sort="overall" style="padding:4px 12px;font-size:11px;font-weight:800;border-radius:16px;${sortBy === 'overall' ? 'background:#fff;color:#000;border:none' : ''}">OVERALL</button>
            <button class="btn salary-sort-btn ${sortBy === 'contract' ? 'active' : ''}" data-sort="contract" style="padding:4px 12px;font-size:11px;font-weight:800;border-radius:16px;${sortBy === 'contract' ? 'background:#fff;color:#000;border:none' : ''}">CONTRATO</button>
          </div>
        </div>

        <div class="salary-list" style="margin-top:20px;display:flex;flex-direction:column;gap:12px">
          ${list.length === 0
            ? `<div class="empty" style="padding:24px;text-align:center;color:#94a3b8">Nenhum atleta encontrado para o filtro selecionado.</div>`
            : list.map(p => {
                const wage = p._monthlyWage;
                const ovr = playerOverall(p);
                const until = p.isLoan && p.loanEndDate ? formatDatePtBr(p.loanEndDate) : p._contractYear;
                const isExp = p._expensive;
                const barPct = clamp(Math.round((wage / maxWage) * 100), 8, 100);
                const pKey = playerKey(p);

                return `
                  <div class="salary-item-clickable"
                       data-player-id="${esc(p.id ?? '')}"
                       data-player-key="${esc(pKey)}"
                       role="button"
                       tabindex="0"
                       style="cursor:pointer;padding:12px 14px;border-radius:12px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.05);transition:all 0.2s">
                    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px">
                      <div style="display:flex;align-items:center;gap:12px;min-width:0;flex:1">
                        <span class="pill" style="font-size:11px;font-weight:800;background:rgba(255,255,255,0.08);color:rgba(255,255,255,0.85);min-width:36px;text-align:center;flex-shrink:0">
                          ${esc(p.pos || '-')}
                        </span>
                        <div style="min-width:0;flex:1">
                          <div style="font-size:15px;font-weight:800;color:#fff;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
                            <span>${esc(p.name)}</span>
                            ${(typeof renderPendingTransferTag === 'function') ? renderPendingTransferTag(p, true) : ''}
                            ${isExp ? `<span class="badge-expensive" style="background:rgba(245,158,11,0.18);color:#fbbf24;border:1px solid rgba(245,158,11,0.4);border-radius:4px;padding:1px 6px;font-size:10px;font-weight:900;letter-spacing:0.5px">CARO P/ O NÍVEL</span>` : ''}
                            ${p._expiringSoon ? `<span class="pill" style="font-size:10px;padding:1px 6px;background:rgba(239,68,68,0.18);border:1px solid rgba(239,68,68,0.45);color:#fca5a5;font-weight:800">VENCE ESTE ANO</span>` : ''}
                            ${p.isLoan ? `<span style="background:rgba(245,158,11,0.18);color:#fbbf24;border:1px solid rgba(245,158,11,0.4);border-radius:4px;padding:1px 6px;font-size:10px;font-weight:900;letter-spacing:0.5px">EMPRESTADO</span>` : ''}
                          </div>
                          <div style="font-size:12px;color:rgba(255,255,255,0.55);margin-top:3px">
                            ${ovr} OVR · ${p.age || 22} anos · até ${until}
                          </div>
                        </div>
                      </div>

                      <div style="text-align:right;flex-shrink:0">
                        <div style="font-size:17px;font-weight:900;color:#fff;letter-spacing:0.4px">
                          R$ ${wage.toLocaleString('pt-BR')}
                        </div>
                        <div style="font-size:11px;color:${p.isLoan ? '#fbbf24' : '#a855f7'};font-weight:700">
                          ${p.isLoan ? 'Negociar c/ detentor ➔' : 'Clique p/ renovar ➔'}
                        </div>
                      </div>
                    </div>

                    <div style="margin-top:10px;width:100%;height:4px;background:rgba(255,255,255,0.06);border-radius:4px;overflow:hidden">
                      <div style="height:100%;width:${barPct}%;background:${isExp ? 'linear-gradient(90deg, #f59e0b, #fbbf24)' : 'linear-gradient(90deg, #7c3aed, #a855f7)'};border-radius:4px"></div>
                    </div>
                  </div>
                `;
              }).join('')}
        </div>
      </div>
    `;
  }

  // A ordenação atua somente sobre a lista filtrada e não altera o elenco salvo.
  const ctx = (typeof resolveModeContext === 'function') ? resolveModeContext(state) : { isManager: true, isPlayer: false, clubName: state?.club || '' };
  const posOrderMap = { GK: 1, CB: 2, RB: 3, LB: 4, DM: 5, CM: 6, AM: 7, RW: 8, LW: 9, ST: 10, CF: 11 };
  const squadSorters = {
    position: (a, b) => (posOrderMap[a.pos] || 99) - (posOrderMap[b.pos] || 99),
    overall: (a, b) => (Number(playerOverall(b)) || 0) - (Number(playerOverall(a)) || 0),
    age: (a, b) => {
      const ageA = Number(a.age), ageB = Number(b.age);
      return (Number.isFinite(ageA) && ageA > 0 ? ageA : Infinity) - (Number.isFinite(ageB) && ageB > 0 ? ageB : Infinity);
    },
    morale: (a, b) => (Number(b.morale ?? 100) || 0) - (Number(a.morale ?? 100) || 0),
    fitness: (a, b) => (Number(b.fitness ?? 100) || 0) - (Number(a.fitness ?? 100) || 0),
    salary: (a, b) => (Number(playerSalary(b)) || 0) - (Number(playerSalary(a)) || 0),
    value: (a, b) => (Number(calcValueMi(b)) || 0) - (Number(calcValueMi(a)) || 0)
  };
  const compareSquadPlayers = squadSorters[squadRosterSort] || squadSorters.overall;
  ps.sort((a, b) => compareSquadPlayers(a, b) || String(a.name || '').localeCompare(String(b.name || ''), 'pt-BR'));

  return `
    <!-- Card de Resumo do Elenco (Dark Neon) -->
    <div class="card" style="margin-bottom:14px;padding:16px;background:linear-gradient(135deg,#131024 0%,#0d0a1a 100%);border:1px solid rgba(139,92,246,0.25);border-radius:14px">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
        <div style="display:flex;align-items:center;gap:12px">
          ${typeof clubBadge === 'function' ? clubBadge(ctx.clubName, 36) : ''}
          <div>
            <div style="font-size:11px;font-weight:800;color:#a855f7;text-transform:uppercase;letter-spacing:1px">RESUMO DO ELENCO • ${ctx.isManager ? 'GESTÃO DO TREINADOR' : 'CONSULTA DO ATLETA'}</div>
            <div style="font-size:18px;font-weight:900;color:#fff">${typeof esc === 'function' ? esc(ctx.clubName) : ctx.clubName} <span class="muted" style="font-size:13px;font-weight:600">(${ps.length} atletas)</span></div>
          </div>
        </div>
        <div style="display:flex;gap:16px;align-items:center;flex-wrap:wrap">
          <div style="text-align:center">
            <div style="font-size:10px;color:rgba(255,255,255,0.5)">MÉDIA OVR</div>
            <div style="font-size:18px;font-weight:900;color:#22c55e">${ps.length ? Math.round(ps.reduce((acc,p)=>acc+playerOverall(p),0)/ps.length) : 0}</div>
          </div>
          <div style="text-align:center">
            <div style="font-size:10px;color:rgba(255,255,255,0.5)">MÉDIA IDADE</div>
            <div style="font-size:18px;font-weight:900;color:#38bdf8">${ps.length ? (ps.reduce((acc,p)=>acc+(Number(p.age)||24),0)/ps.length).toFixed(1) : '24.0'} anos</div>
          </div>
          ${ctx.isManager ? `
            <div style="text-align:center">
              <div style="font-size:10px;color:rgba(255,255,255,0.5)">FOLHA MENSAL</div>
              <div style="font-size:18px;font-weight:900;color:#facc15">${fmtMoney(typeof totalMonthlyPayroll === 'function' ? totalMonthlyPayroll() : ps.reduce((acc,p)=>acc+playerSalary(p),0))}/mês</div>
            </div>
          ` : ''}
          <div style="text-align:center">
            <div style="font-size:10px;color:rgba(255,255,255,0.5)">DEPARTAMENTO MÉDICO</div>
            <div style="font-size:14px;font-weight:900;color:${ps.filter(p=>p.injured||(p.injury&&p.injury.games>0)).length>0?'#ef4444':'#22c55e'}">${ps.filter(p=>p.injured||(p.injury&&p.injury.games>0)).length>0 ? `🚨 ${ps.filter(p=>p.injured||(p.injury&&p.injury.games>0)).length} lesionado(s)` : '✅ Nenhum lesionado'}</div>
          </div>
        </div>
      </div>
    </div>

    <div class="hero">
      <div>
        <h1>Elenco do Clube</h1>
        <div class="muted">${ps.length} jogadores no plantel · Limite de ${squadCapacity()} vagas (${Math.max(0, squadCapacity()-ps.length)} disponíveis) • Folha: ${fmtMoney(totalMonthlyPayroll())}/mês • Estrutura & Staff: ${fmtMoney(totalFacilitiesMonthlyExpense())}/mês</div>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn btnOpenSquadReportsModal" id="btnOpenSquadReports" style="background:linear-gradient(135deg,#059669,#10b981);color:#fff;border:none;font-weight:900;box-shadow:0 2px 8px rgba(16,185,129,0.35);display:inline-flex;align-items:center;gap:6px" title="Ver perspetiva geral, lesões, suspensões, moral, contratos e juventude">
          📊 Relatórios & Perspetiva Geral
        </button>
        <button class="btn btnOpenTrainingModal" id="btnOpenTrainingFromSquad" style="background:linear-gradient(135deg,#0d9488,#14b8a6);color:#fff;border:none;font-weight:900;box-shadow:0 2px 8px rgba(13,148,136,0.35);display:inline-flex;align-items:center;gap:6px" title="Abrir painel de exercícios e sessão de treinamento">
          🏋️ Sessão de Treino
        </button>
        <button class="btn" id="btnGoToSalariesView" style="background:linear-gradient(135deg,#7c3aed,#a855f7);color:#fff;border:none;font-weight:700">
          💰 Salários (${expensiveCount} caros)
        </button>
        <button class="btn" id="btnOpenCompareModalSquad" style="background:linear-gradient(135deg,#0284c7,#0369a1);color:#fff;border:none;font-weight:700">
          ⚖️ Comparar Atletas
        </button>
        <button class="btn" id="btnOpenYouthFromSquad" style="background:linear-gradient(135deg,#059669,#10b981);color:#fff;border:none">
          🌱 Categorias de Base (${(state.youthAcademy||[]).length})
        </button>
        <button class="btn primary" id="btnSearchAllDb">🔍 Consultar Banco</button>
      </div>
    </div>

    <div class="filters" style="margin-top:14px">
      <button class="btn ${squadFilter==='ALL'?'primary':''}" data-squad-filter="ALL">Todos (${state.squad.length})</button>
      <button class="btn ${squadFilter==='GK'?'primary':''}" data-squad-filter="GK">Goleiros</button>
      <button class="btn ${squadFilter==='DEF'?'primary':''}" data-squad-filter="DEF">Defensores</button>
      <button class="btn ${squadFilter==='MID'?'primary':''}" data-squad-filter="MID">Meio-Campo</button>
      <button class="btn ${squadFilter==='ATK'?'primary':''}" data-squad-filter="ATK">Atacantes</button>
      <button class="btn ${squadFilter==='TRANSFER'?'primary':''}" data-squad-filter="TRANSFER" style="${squadFilter==='TRANSFER'?'background:rgba(249,115,22,0.9);color:#fff;border:none':''}">🏷️ À Venda (${state.squad.filter(p=>isPlayerTransferListed(p)).length})</button>
      <button class="btn ${squadFilter==='LOAN'?'primary':''}" data-squad-filter="LOAN" style="${squadFilter==='LOAN'?'background:rgba(14,165,233,0.9);color:#fff;border:none':''}">🤝 Empréstimo (${state.squad.filter(p=>isPlayerLoanListed(p)).length})</button>
    </div>
    <div class="squad-sort-toolbar" style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:0 0 12px;padding:10px 12px;background:rgba(15,23,42,.72);border:1px solid var(--line,#263244);border-radius:10px">
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;flex:1;min-width:280px">
        <label for="squadRosterSort" style="color:var(--muted,#94a3b8);font-size:12px;font-weight:800;white-space:nowrap">ORDENAR ELENCO</label>
        <select id="squadRosterSort" aria-label="Organizar elenco" style="min-width:180px;padding:7px 10px;border:1px solid var(--line,#263244);border-radius:8px;background:#111827;color:#e2e8f0;font-size:12px">
          <option value="position" ${squadRosterSort==='position'?'selected':''}>Por Posição (GOL, ZAG, MEI, ATA)</option>
          <option value="overall" ${squadRosterSort==='overall'?'selected':''}>Maior overall</option>
          <option value="morale" ${squadRosterSort==='morale'?'selected':''}>Maior moral</option>
          <option value="fitness" ${squadRosterSort==='fitness'?'selected':''}>Melhor forma física</option>
          <option value="age" ${squadRosterSort==='age'?'selected':''}>Mais jovens</option>
          <option value="salary" ${squadRosterSort==='salary'?'selected':''}>Maior salário</option>
          <option value="value" ${squadRosterSort==='value'?'selected':''}>Maior valor de mercado</option>
        </select>
        <input id="squadSearchInput" type="text" placeholder="🔍 Buscar atleta por nome ou posição..." style="flex:1;min-width:200px;padding:7px 12px;border:1px solid var(--line,#263244);border-radius:8px;background:#111827;color:#e2e8f0;font-size:12px">
      </div>
      <button id="btnAutoNumberSquad" class="btn" style="background:#1e1838;color:#38bdf8;border:1px solid rgba(56,189,248,0.4);font-size:11px;font-weight:900;padding:7px 12px;border-radius:8px;cursor:pointer" title="Numerar automaticamente os jogadores de 1 a 25">
        🔢 Numerar Elenco (1-25)
      </button>
    </div>

    <div class="card" style="margin-top:10px">
      <div class="tablewrap">
        <table>
          <thead>
            <tr>
              <th>Foto</th>
              <th style="width:42px;text-align:center" title="Número da Camisa">Nº</th>
              <th>Jogador</th>
              <th>Pos</th>
              <th>Idade</th>
              <th>Overall</th>
              <th>Potencial</th>
              <th>Salário / Mês</th>
              <th>Contrato</th>
              <th>Físico</th>
              <th>Valor de Mercado</th>
              <th>Ação</th>
            </tr>
          </thead>
          <tbody id="squadTableBody">
            ${ps.map(p=>`
              <tr>
                <td style="width:46px;text-align:center;cursor:pointer" class="btn-lupa-details" data-key="${esc(playerKey(p))}" onclick="if(window.AFM_MarketLupaAndAging)window.AFM_MarketLupaAndAging.openPlayerDetails(this)" title="Ver ficha técnica de ${esc(p.name)}">${playerPhoto(p, 36)}</td>
                <td style="width:42px;text-align:center"><button class="btn btn-sm btn-subtle" onclick="openSquadShirtNumbersModal('${esc(typeof playerKey === 'function' ? playerKey(p) : p.name)}')" title="Alterar camisa de ${esc(p.name)}" style="padding:2px 7px;font-size:12px;font-weight:900;border-radius:6px;min-width:32px;color:#38bdf8;border:1px solid rgba(56,189,248,0.3)">#${p.number || '-'}</button></td>
                <td>
                  <b style="cursor:pointer" class="btn-lupa-details" data-key="${esc(playerKey(p))}" onclick="if(window.AFM_MarketLupaAndAging)window.AFM_MarketLupaAndAging.openPlayerDetails(this)" title="Ver ficha técnica de ${esc(p.name)}">${esc(p.name)}</b>
                  ${(typeof renderPendingTransferTag === 'function') ? renderPendingTransferTag(p) : ''}
                  ${p.injury ? `<span class="pill bad" style="font-size:9px;padding:1px 5px" title="${esc(p.injury)} (${p.injuryMatches} jogos)">🚑 ${p.injuryMatches}j</span>` : ''}
                  ${p.suspended > 0 ? `<span class="pill bad" style="font-size:9px;padding:1px 5px" title="Suspenso por cartões">🟥 ${p.suspended}j</span>` : (p.yellowCards > 0 ? `<span class="pill" style="font-size:9px;padding:1px 5px;background:rgba(234,179,8,0.2);color:#facc15" title="${p.yellowCards} cartão amarelo">🟨 ${p.yellowCards}</span>` : '')}
                  ${(p.morale || 75) >= 90 ? `<span class="pill good" style="font-size:9px;padding:1px 4px" title="Moral em alta">⭐</span>` : ((p.morale || 75) <= 50 ? `<span class="pill bad" style="font-size:9px;padding:1px 4px" title="Moral baixa">⚠️</span>` : '')}
                  ${p.isLoan ? '<span class="pill" style="font-size:10px">Emprestado</span>':''}
                  ${isPlayerTransferListed(p) ? `<span class="pill open-transfer-modal" data-key="${esc(playerKey(p))}" style="cursor:pointer;font-size:9px;font-weight:900;padding:2px 7px;border-radius:4px;background:rgba(249,115,22,0.25);border:1px solid rgba(249,115,22,0.7);color:#fb923c" title="Atleta à venda (clique para gerenciar ofertas ou retirar da lista)">🏷️ À VENDA</span>` : ''}
                  ${isPlayerLoanListed(p) ? `<span class="pill open-transfer-modal" data-key="${esc(playerKey(p))}" style="cursor:pointer;font-size:9px;font-weight:900;padding:2px 7px;border-radius:4px;background:rgba(14,165,233,0.25);border:1px solid rgba(14,165,233,0.7);color:#38bdf8" title="Atleta para empréstimo (clique para gerenciar ofertas ou retirar da lista)">🤝 EMPRÉSTIMO</span>` : ''}
                </td>
                <td>
                  <button type="button" class="btn btn-sm btn-subtle btnChangePlayerPosSquad" onclick="openPlayerChangePositionModal('${esc(typeof playerKey === 'function' ? playerKey(p) : p.name)}')" title="Alterar posição de ${esc(p.name)}" style="padding:2px 7px;font-size:11px;font-weight:900;border-radius:6px;min-width:38px;color:#c084fc;background:#1e1838;border:1px solid rgba(192,132,252,0.3);cursor:pointer;display:inline-flex;align-items:center;gap:3px">
                    <span>${esc(p.pos||'-')}</span>
                    <span style="font-size:9px;opacity:0.7">✏️</span>
                  </button>
                </td>
                <td>${p.age||'-'} anos</td>
                <td><span class="rating-pill ${ratingClass(playerOverall(p))}">${playerOverall(p)}</span></td>
                <td><div style="display:flex;align-items:center;gap:6px"><b class="good">${p.potential||playerOverall(p)}</b> ${window.AFM_SquadAssistant ? window.AFM_SquadAssistant.renderThreeLayerStarsHTML(p) : ''}</div></td>
                <td style="color:#22c55e;font-weight:700">R$ ${playerSalary(p).toLocaleString('pt-BR')}</td>
                <td><span class="pill" style="font-size:11px">até ${playerContractUntil(p)}</span></td>
                <td>
                  <div style="display:flex;align-items:center;gap:6px">
                    <span>${Math.round(p.fitness??100)}%</span>
                    <div class="bar" style="width:40px;height:5px"><span style="width:${p.fitness??100}%;background:${p.fitness>85?'var(--neon)':p.fitness>70?'var(--warn)':'var(--bad)'}"></span></div>
                  </div>
                </td>
                <td>${fmtMi(calcValueMi(p))}</td>
                <td>
              <div style="display:flex;gap:5px;flex-wrap:wrap;align-items:center">
                <button type="button" class="btn btn-lupa-details btn-lupa-squad" data-key="${esc(playerKey(p))}" onclick="if(window.AFM_MarketLupaAndAging)window.AFM_MarketLupaAndAging.openPlayerDetails(this)" title="Ver ficha técnica e atributos reais de ${esc(p.name)}" style="background:#3b1d7a;color:#fff;border:1px solid #a78bfa;border-radius:8px;padding:4px 8px;cursor:pointer;font-size:12px;line-height:1;display:inline-flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(124,58,237,0.3);flex-shrink:0;">🔍</button>
                ${ctx.isManager ? (p.isLoan ? `<button class="btn btnManageLoanRow" data-key="${esc(playerKey(p))}" style="padding:4px 8px;font-size:11px">🤝 Negociar c/ detentor</button>` : `
                  <button class="btn btnRenewContractRow" data-key="${esc(playerKey(p))}" style="padding:4px 8px;font-size:11px">📝 Renovar contrato</button>
                  <button class="btn open-transfer-modal ${(p.pendingTransfer||p.isSold)?'warn':isPlayerTransferListed(p)?'warn':isPlayerLoanListed(p)?'primary':''}" data-key="${esc(playerKey(p))}" style="padding:4px 8px;font-size:11px">${(p.pendingTransfer||p.isSold) ? (p.pendingTransfer?.type==='loan_out'?'🤝 Empréstimo Agendado':'🏷️ Venda Agendada (Janela)') : isPlayerTransferListed(p)?'🏷️ Gerenciar Venda':isPlayerLoanListed(p)?'🤝 Gerenciar Empréstimo':'📄 Propostas / Vender'}</button>
                `) : (Boolean(p.isControlled || (ctx.playerName && typeof norm === 'function' && norm(p.name) === norm(ctx.playerName))) ? `
                  <span class="pill" style="font-size:10px;background:#7c3aed;color:#fff;font-weight:900">VOCÊ</span>
                ` : `
                  <span class="pill" style="font-size:10px;background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.6)">👥 Companheiro</span>
                `)}
              </div>
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

// -------------------------------------------------------------
// MERCADO (COM FILTROS DE REGIÃO, PAÍS, COMPETIÇÃO E CLUBE)
