function showGlobalDatabaseModal(){
  openCustomModal(
    '🔍 Consulta Global de Jogadores no Banco',
    `
      <div class="filters">
        <input id="dbSearchInput" placeholder="Digite o nome do jogador ou clube..." style="flex:1">
      </div>
      <div class="tablewrap" id="dbSearchResults" style="max-height:460px;margin-top:10px"></div>
    `,
    null,
    'Fechar',
    false
  );

  function renderSearch(){
    const q = norm($('#dbSearchInput')?.value || '');
    const pool = livePlayers.length > 0 ? livePlayers : (state.worldGenerated || []);
    const filtered = pool.filter(p => !q || norm(p.name + ' ' + p.club).includes(q)).slice(0, 80);
    const box = $('#dbSearchResults');
    if(!box) return;
    box.innerHTML = `
      <table>
        <thead><tr><th>Jogador</th><th>Clube</th><th>Pos</th><th>Overall</th><th>Idade</th></tr></thead>
        <tbody>
          ${filtered.map(p => `
            <tr>
              <td><b>${esc(p.name)}</b></td>
              <td><div class="club-cell">${clubBadge(p.club, 18)} ${esc(p.club||'-')}</div></td>
              <td><span class="pill" style="font-size:11px">${esc(p.pos||'-')}</span></td>
              <td><span class="rating-pill ${ratingClass(playerOverall(p))}">${playerOverall(p)}</span></td>
              <td>${p.age||'-'} anos</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;
  }

  $('#dbSearchInput').oninput = renderSearch;
  renderSearch();
}

function exportSave(){
  const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`AFM-save-${state.club.replace(/[^a-z0-9]+/gi,'_')}-${state.season}.json`;
  a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),1500);
}

function importSave(ev){
  const f=ev.target.files?.[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{
    try{
      const parsed=JSON.parse(r.result);
      const raw=(parsed&&typeof parsed==='object'&&parsed.data&&parsed.data.club)?parsed.data:parsed;
      if(!raw||!raw.club||(!raw.teams&&!raw.squad)) throw Error('Save inválido');
      const targetSlot=Math.max(1,Math.min(3,Number(state?.userSlot||raw.userSlot||1)));
      let nextState=(window.AFM_SETUP_GUARD&&typeof window.AFM_SETUP_GUARD.sanitizeLoadedSave==='function')
        ?window.AFM_SETUP_GUARD.sanitizeLoadedSave(raw,targetSlot)
        :clone(raw);
      nextState.userSlot=targetSlot;
      if(typeof window.migrateAndSanitizeSaveState==='function'){
        nextState=window.migrateAndSanitizeSaveState(nextState);
      }
      state=migrate(nextState);
      if(typeof window!=='undefined') window.state=state;
      const isPl=(typeof window.isPlayerCareerActive==='function'&&window.isPlayerCareerActive(state))||state.gameMode==='player';
      state.gameMode=isPl?'player':'manager';
      state.mode=state.gameMode;
      state.isPlayerMode=isPl;
      if(isPl&&!state.retiredPlayerCareer){
        state.coachName='Treinador da IA';
        state.manager='Treinador da IA';
        restorePlayerCareerSquad(state);
      }
      if(window.AFM_SAVE_VERIFIER) window.AFM_SAVE_VERIFIER.lockSlotMode(targetSlot,state.gameMode,{club:state.club});
      view=isPl?'player_hub':'central';
      state.view=view;
      if(typeof window!=='undefined'){ window.view=view; window.state=state; }
      save({allowModeReplace:true,manual:true,force:true});
      render();
      toast(`Save importado com sucesso (${isPl?'Modo Jogador':'Modo Treinador'})!`);
    }catch{
      alert('Arquivo de save inválido.');
    }
  };
  r.readAsText(f);
}

window.TACTICAL_DEBUG = false;

window.runTacticalEngineTests = function(numMatches = 100){
  console.log(`[AFM FC27 Match Engine] Iniciando bateria de testes com ${numMatches} partidas...`);
  const results = {
    matches: numMatches,
    totalGoals: 0,
    homeWins: 0,
    awayWins: 0,
    draws: 0,
    totalXGHome: 0,
    totalXGAway: 0,
    totalPossessionHome: 0,
    totalPossessionAway: 0,
    cleanSheets: 0,
    anomalies: []
  };

  const testFormations = Object.keys(FORMATIONS);
  for(let i = 0; i < numMatches; i++){
    const hForm = testFormations[i % testFormations.length];
    const aForm = testFormations[(i + 3) % testFormations.length];
    const hStr = 70 + (i % 15);
    const aStr = 68 + ((i + 5) % 15);

    const dynamics = calculateTacticalMatchDynamics('Time Casa', 'Time Fora', hStr, aStr, false, false, {
      formation: hForm,
      tactics: { lineHeight: 60, attackingWidth: 60, defensiveWidth: 50, pressIntensity: 65, buildUpStyle: 'Balanced', defensiveApproach: 'Balanced' }
    }, {
      formation: aForm,
      tactics: { lineHeight: 50, attackingWidth: 50, defensiveWidth: 50, pressIntensity: 55, buildUpStyle: 'Balanced', defensiveApproach: 'Mid Block' }
    });

    const score = simulateScore('Time Casa', 'Time Fora', hStr, aStr, false, false);
    const hG = score[0];
    const aG = score[1];

    if(hG < 0 || aG < 0 || isNaN(hG) || isNaN(aG)){
      results.anomalies.push({ match: i, error: 'Placar negativo ou NaN', score });
    }
    if(hG > 12 || aG > 12){
      results.anomalies.push({ match: i, error: 'Placar com anomalia irreal (>12 gols)', score });
    }

    results.totalGoals += (hG + aG);
    if(hG > aG) results.homeWins++;
    else if(aG > hG) results.awayWins++;
    else results.draws++;

    if(hG === 0 || aG === 0) results.cleanSheets++;
    results.totalXGHome += dynamics.homeXG;
    results.totalXGAway += dynamics.awayXG;
    results.totalPossessionHome += dynamics.homePossession;
    results.totalPossessionAway += dynamics.awayPossession;
  }

  const avgGoals = (results.totalGoals / numMatches).toFixed(2);
  const avgXGHome = (results.totalXGHome / numMatches).toFixed(2);
  const avgXGAway = (results.totalXGAway / numMatches).toFixed(2);
  const avgPossH = (results.totalPossessionHome / numMatches).toFixed(1);
  const avgPossA = (results.totalPossessionAway / numMatches).toFixed(1);
  const winRateH = ((results.homeWins / numMatches) * 100).toFixed(1);
  const winRateA = ((results.awayWins / numMatches) * 100).toFixed(1);
  const drawRate = ((results.draws / numMatches) * 100).toFixed(1);

  console.table({
    'Partidas Simuladas': numMatches,
    'Média de Gols / Partida': avgGoals,
    'Média xG Casa': avgXGHome,
    'Média xG Fora': avgXGAway,
    'Posse Média Casa': `${avgPossH}%`,
    'Posse Média Fora': `${avgPossA}%`,
    'Vitórias Mandante': `${winRateH}%`,
    'Empates': `${drawRate}%`,
    'Vitórias Visitante': `${winRateA}%`,
    'Anomalias / Bugs': results.anomalies.length
  });

  if(results.anomalies.length > 0){
    console.error('Anomalias detectadas:', results.anomalies);
  } else {
    console.log('✅ Todos os testes da Match Engine FC 27 passaram com sucesso (distribuição causal realista, sem placares absurdos)!');
  }

  return {
    passed: results.anomalies.length === 0,
    avgGoals,
    avgXGHome,
    avgXGAway,
    avgPossH,
    avgPossA,
    winRateH,
    drawRate,
    winRateA,
    anomalies: results.anomalies
  };
};

